[Definition 73 of arXiv:2607.18104, '2607.18104'] We define the extended disagreement process $(\xi^{\modi}_t)_{t \geq 0}$ as a Markov process on the state space
\begin{equation}
\{ \one , \onep , \Aup , \Bup , \zerop, \zero \}^{\Z} .
\end{equation}
For all edges $e=\{ x,x+1\}$ with $x\in \Z$, assign a rate $1+q$ Poisson clock. Whenever a clock rings at time $t$, we sample a Uniform-$[0, 1]$-random variable $U$ independently of all previous samples. First, consider $x\in \mathcal{I}^{\rho}_{N}\big(\theta,1+\theta\big)$. We distinguish two cases:
\begin{itemize}
\item[(1)] Assume that $U\leq (1+q)^{-1}$. If $\{ \xi^{\modi}_{t_-}(x), \xi^{\modi}_{t_-}(x+1) \}  \neq \{\Aup,\Bup\}$, then sort the endpoints in $\xi^{\modi}_t$ with respect to  \eqref{def:ExtendedPartialOrder} in increasing order. If $\{ \xi^{\modi}_{t_-}(x), \xi^{\modi}_{t_-}(x+1) \}  = \{\Aup,\Bup\}$, then set $\xi^{\modi}_t(x+1)=\onep$ and $\xi^{\modi}_t(x)=\zerop$. Moreover, for all $y=x \mod N$ with $y \neq x$, we distinguish the following four sub-cases:
\begin{itemize}
    \item[(1a)] If $\xi^{\modi}_{t_-}(y) \in \{\one,\onep\}$ and $\xi^{\modi}_{t_-}(y+1) \in \{\zero,\zerop\}$, set $(\xi^{\modi}_{t}(y),\xi^{\modi}_{t}(y+1))=(\Aup,\Bup)$,
    \item[(1b)] If $\xi^{\modi}_{t_-}(y) \in \{\one,\onep\}$ and $\xi^{\modi}_{t_-}(y+1) = \Aup$, then swap the endpoints.
    \item[(1c)] If $\xi^{\modi}_{t_-}(y) =\Bup$ and $\xi^{\modi}_{t_-}(y+1) = \Aup$, then set $(\xi^{\modi}_{t}(y),\xi^{\modi}_{t}(y+1))=(\zerop,\onep)$,  
    \item[(1d)] If $\xi^{\modi}_{t_-}(y) =\Bup$ and $\xi^{\modi}_{t_-}(y+1) \in \{\zero,\zerop\}$, then swap the endpoints. 
\end{itemize}
In all other cases, leave the configuration unchanged. 
\item[(2)] Assume that  $U> (1+q)^{-1}$. If $\{ \xi^{\modi}_{t_-}(x), \xi^{\modi}_{t_-}(x+1) \}  \neq \{\Aup,\Bup\}$, then sort the endpoints in $\xi^{\modi}_t$ with respect to  \eqref{def:ExtendedPartialOrder} in decreasing order. If $\{ \xi^{\modi}_{t_-}(x), \xi^{\modi}_{t_-}(x+1) \}  = \{\Aup,\Bup\}$, then set $\xi^{\modi}_t(x)=\onep$ and $\xi^{\modi}_t(x+1)=\zerop$. Moreover, for all $y=x \mod N$ with $y \neq x$, we distinguish the following four sub-cases:
\begin{itemize}
    \item[(2a)] If $\xi^{\modi}_{t_-}(y) \in \{\zero,\zerop\}$ and $\xi^{\modi}_{t_-}(y+1) \in \{\one,\onep\}$, set $(\xi^{\modi}_{t}(y),\xi^{\modi}_{t}(y+1))=(\Bup,\Aup)$,
    \item[(2b)] If $\xi^{\modi}_{t_-}(y) = \Aup$ and $\xi^{\modi}_{t_-}(y+1) \in \{\one,\onep\}$, then swap the endpoints.
    \item[(2c)] If $\xi^{\modi}_{t_-}(y) =\Aup$ and $\xi^{\modi}_{t_-}(y+1) = \Bup$, then set $(\xi^{\modi}_{t}(y),\xi^{\modi}_{t}(y+1))=(\onep,\zerop)$,  
    \item[(2d)] If $\xi^{\modi}_{t_-}(y)\in \{\zero,\zerop\}$ and $\xi^{\modi}_{t_-}(y+1)=\Bup$, then swap the endpoints. 
\end{itemize}
In all other cases, leave the configuration unchanged. 
\end{itemize}
Now assume that $x\notin \mathcal{I}^{\rho}_{N}\big(\theta,1+\theta\big)$. Depending on the outcome of the random variable $U$, we proceed with an update of the edge $\{x,x+1\}$ as follows:
\begin{itemize}
\item[(3)] Assume that $U\leq (1+q)^{-1}$. We distinguish the following four sub-cases:
\begin{itemize}
    \item[(3a)] If $\xi^{\modi}_{t_-}(x) \in \{\one,\onep\}$ and $\xi^{\modi}_{t_-}(x+1) \in \{\zero,\zerop\}$, set $(\xi^{\modi}_{t}(x),\xi^{\modi}_{t}(x+1))=(\Bup,\Aup)$,
    \item[(3b)] If $\xi^{\modi}_{t_-}(x) \in \{\one,\onep\}$ and $\xi^{\modi}_{t_-}(x+1) = \Bup$, then swap the endpoints.
    \item[(3c)] If $\xi^{\modi}_{t_-}(x) =\Aup$ and $\xi^{\modi}_{t_-}(x+1) = \Bup$, then set $(\xi^{\modi}_{t}(x),\xi^{\modi}_{t}(x+1))=(\zerop,\onep)$,  
    \item[(3d)] If $\xi^{\modi}_{t_-}(x) =\Aup$ and $\xi^{\modi}_{t_-}(x+1) \in \{\zero,\zerop\}$, then swap the endpoints. 
\end{itemize}
In all other cases, leave the configuration unchanged. 
\item[(4)] Assume that  $U> (1+q)^{-1}$. We distinguish the following four sub-cases:
\begin{itemize}
    \item[(4a)] If $\xi^{\modi}_{t_-}(x) \in \{\zero,\zerop\}$ and $\xi^{\modi}_{t_-}(x+1) \in \{\one,\onep\}$, set $(\xi^{\modi}_{t}(x),\xi^{\modi}_{t

[Theorem thm:band_main of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For $d=1$ and $\alpha > 1$, consider the random band matrix $H_N$ defined in Definition (defmodel of the paper) with profile function $f$. Assume $f$ satisfies the comparison conditions in Definition (ass:ft of the paper) with respect to the $\alpha$-stable density $f_{\alpha}$ in Definition (def:alpha_profile of the paper). Let $R_{N;k}$ denote the $k$-point correlation measure of $H_N$, and let $(T_{s_N})_* R_{N;k}$ be its rescaling through the map $T_{s_N}(x_i) = 2 + s_N x_i$. Then, the following scaling limits hold as $N \to \infty$:
    \begin{enumerate}
        \item[(i)] \textbf{(Supercritical regime)} When  $W \gg N^{1-\frac{1}{3\alpha}}$, with $s_N=N^{-2/3}$ the rescaled $k$-point correlation   measure
        \begin{equation}
       (T_{s_N})_*R_{N;k}(dx_1, \ldots, dx_k)
        \end{equation}
        converges vaguely to those of the GOE/GUE  Airy point  process.

        \item[(ii)] \textbf{(Critical regime)} When  $W \sim \gamma N^{1-\frac{1}{3\alpha}}$ with some   constant $\gamma > 0$, with  $s_N = W^{-\frac{2\alpha}{3\alpha-1}}$ the rescaled $k$-point correlation measure
        \begin{equation}
            (T_{s_N})_*R_{N;k}(dx_1, \ldots, dx_k)
        \end{equation}
        converges vaguely  to $R^{\mathrm{(Crit)}}_{k}(\gamma;d y_1,\ldots,d y_k)$ defined in Definition (def:Rcrit of the paper).

        \item[(iii)] \textbf{(Subcritical regime)} When  $(\log N)^{1/\alpha} \ll W \ll N^{1-\frac{1}{3\alpha}}$, let $s_N = W^{-\frac{2\alpha}{3\alpha-1}}$ and $\gamma_N = N W^{-\frac{3\alpha}{3\alpha-1}}$. As $N \to \infty$, for any $k \ge 1$, the rescaled $k$-point correlation measures satisfy the  factorization property:
        \begin{equation}
            \gamma_N^{-k}  (T_{s_N})_* R_{N;k}(dx_1, \dots, dx_k) \rightarrow \prod_{j=1}^k R^{\mathrm{(Sub)}}_1(dy_j).
        \end{equation}
        Here $R^{\mathrm{(Sub)}}_1(dy_j)$ is given in Definition (def:Rsub of the paper).
    \end{enumerate}

