[Theorem T: main diffusive of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Assume that $\mathbf{P}\{ f_{+},f_{-} \in \mathcal{S} \} = 1$,  (equation E: decay one of the paper) holds, and $\sigma \neq 0$.  Fix a $\theta \in \mathbb{R}$ and let $p^{(N)} = 1/2 + \theta N^{-1}$.  For each $N \in \mathbb{N}$, let $\{X^{(N,n)}\}$ be a solution of the RDE 
	\begin{equation*}
		X^{(N,n)} \overset{d}{=} \Phi^{(N)} ( X^{(N,n-1)}_{1}, X^{(N,n-1)}_{2} ),
	\end{equation*}
where $(X^{(N,n-1)}_{1},X^{(N,n-1)}_{2})$ are i.i.d.\ copies of $X^{(N,n-1)}$ and $\Phi^{(N)}$ is given by (equation E: main forcing of the paper) with bias parameter $p = p^{(N)}$.  


	Assume that there is a function $F_{\text{in}}$ such that, at the initial time $n = 0$, the following limit holds:
		\begin{align*}
			\lim_{N \to +\infty} \mathbb{P} \{ N^{-1/2} X^{(N,0)} \leq x\} = F_{\text{in}}(x) \quad \text{for almost every} \, \, x \in \mathbb{R}.
		\end{align*}
	If $\{F_{N}\}$ is the sequence of rescaled CDF's defined in $\mathbb{R} \times [0,+\infty)$ by
		\begin{align*}
			F_{N}(x,t) = \mathbb{P} \{ N^{-1/2} X^{(N, [ N t ] )} \leq x \},
		\end{align*}
	then $F_{N} \to F$ locally uniformly in $\mathbb{R} \times (0,+\infty)$ as $N \to +\infty$, where $F$ is the unique bounded discontinuous viscosity solution of the initial value problem
				\begin{align} 
					\left\{ \begin{array}{r l}
						\partial_{t} F - \sigma | \partial_{x} F |^{2} + 2 \theta F ( 1 - F ) = 0 & \text{in} \, \, \mathbb{R} \times (0,+\infty), \\
						F(x,0) = F_{\text{in}}(x).
					\end{array} \right.
				\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] For $\kappa > 0$ and $\theta \geq 1$, define
\[
T_{\theta,\kappa}
:= \left\{
\sigma \in GL(d,\mathbb{R})
\;\middle|\;
\|\sigma\| \ge \kappa,\;
\|\sigma\|\,\|\sigma^{-1}\| \leq \theta
\right\},
\]
where $\|\cdot\|$ denotes the standard operator norm induced by the Euclidean norm on $\mathbb{R}^d$ and $GL(d,\mathbb{R})$ is the space of invertible $d \times d$ matrices.

[Theorem thm:optimal of arXiv:2412.00279, 'Optimal local storage policy based on stochastic intensities and its large scale behavior'] For any causal policy $\mathcal{C}(t)$, its stationary hit rate $h_{\mathcal{C}}$ satisfies:
  \begin{equation*}
    h_{\mathcal{C}}= \E{\lambda_{\mathcal{C}}(0)} \leqslant \E{\lambda_{\mathcal{C}^*}(0)} = 
    h_{\mathcal{C}^*}.
  \end{equation*}
  In addition, the hit probability:
  \begin{equation*}
    H_{\mathcal{C}} := {\rm P}^0_\Phi\left( \Psi_{\mathcal{C}}(\{0\}) = 1 \right)
  \end{equation*}
  is also maximized by the policy $\mathcal{C}^*$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma le:change-patial-int of arXiv:2411.12192, 'Sample path properties and small ball probabilities for stochastic fractional diffusion eq'] Let $(Y,\mathcal Y,\mu)$ be a measurable  space with $\mu:\mathcal Y\to[0,\infty]$. Let $f$ be a complex-valued function defined on
   $\mathbb{R}\times Y$ and $\delta\in(0,\infty)$ be a constant.   Suppose that,  for  $x\in(x_0-\delta,x_0+\delta)$,
  \begin{enumerate}[(i)]
    \item $u(x)=\displaystyle \int_{Y}f(x,y)\mu(\ensuremath{ \mathrm{d}}  y)$ with $\displaystyle\int_{Y}|f(x,y)|\mu(\ensuremath{ \mathrm{d}}  y)<\infty$;
    \medskip

    \item for fixed $y$, $\displaystyle \frac{\partial}{\partial x}f(x,y)$ exists and is a continuous function of $x$;
    \medskip

    \item $v(x)=\displaystyle\int_{Y}\frac{\partial}{\partial x}f(x,y) \mu(\ensuremath{ \mathrm{d}}  y)$ is continuous at $x=x_0$;
    \medskip

    \item $\displaystyle\int_{Y}\int_{-\delta}^{\delta}\left|\frac{\partial}{\partial x}f(x_0+z,y) \right|\ensuremath{ \mathrm{d}}  z\mu(\ensuremath{ \mathrm{d}}  y)<\infty$;
  \end{enumerate}
  then we have \[u'(x_0)=v(x_0).\]

