body:
[Theorem cor022404-26 of arXiv:2606.07353, 'The Gaussian structure of a perturbed KPZ'] Under the assumption (equation V00 of the paper), {$\nu_V$ is absolutely continuous with respect to $\nu$, i.e.,}  there exists a unique $\bar
  F_V\in D(\nu)$ such that
   \begin{equation}

    {\mathcal P}_{t }^V\bar F_V =\bar F_V,\quad t\ge0.
  \end{equation}
  The following are true: 

  \begin{itemize}
  \item[(i)]
 The relative entropy of $\nu_V$ w.r.t. the white noise measure $\nu$ is finite:
  \begin{equation}

{\mathbf{H}}_{V}(\nu_V\big|\nu )=\int_{\mathrm{H}}\bar F_V\log \bar F_V d\nu<+\infty.
\end{equation}

\item[(ii)] Starting from an arbitrary density, the convergence to the invariant measure is in the total variation sense: 
   \begin{equation}

    \lim_{t\to+\infty} \|{\mathcal P}_{t}^VF-\bar
    F_V\|_{L^1(\nu)}=0,\quad \mbox{for all}\,F\in D(\nu).
  \end{equation}

  \item[(iii)] $\bar F_V$ belongs to $L^p(\nu)$ for small
    perturbations: there exists a universal constant $C>0$ such that
  \[  \mbox{if $p\in(1,+\infty)$ and $ \|V\|_{L^2(\mathbb{T})}< Cp^{-1}$, 
  then $\bar F_V\in L^p(\nu)$.}
  \]
  \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 (Ergodicity for $\hat{J}\in[0,+\infty)$) of arXiv:2605.29608, '2605.29608'] Let $(Y_{k})_{k\in\mathbb{Z}^{+}}$ and $\mu_{N}$ be defined as in Theorem \ref{thm: transitionmatrix}. If the coupling constant $\hat{J}\in [0,+\infty)$, then for any initial configuration $Y_{1}\in\Omega$ and any real-valued function $g$ on $\Omega$, we have
	\begin{align*}	
		\lim_{M\rightarrow+\infty}\frac{1}{M}\sum_{k=1}^{M}g(Y_{k})=E_{\mu_{N}}[g], \qquad \mathbb{P}\text{-a.s.}.
	\end{align*}

[Theorem 18 (Robust pre-response phase boundary) of arXiv:2608.26877, 'When Is the Sharp Covariance Envelope Tight? Feature-Only Geometry for Volume-Sampled Leas'] Let $d\ge1$, $m\ge d+2$, and $d<s<m$.  Suppose that
$A\in\R^{m\times d}$ has orthonormal columns and no coloop, namely
\begin{equation}
  \ell_i<1\qquad\text{for every }i\in[m].

\end{equation}
Use ordinary unrescaled indexed size-$s$ volume sampling followed by
selected unweighted least squares on positive-volume subsets.  For every
$\theta\in\R^d$ and $L^*>0$, with the definitions above,
$\nu_A\ge0$ and
\begin{equation}
  \boxed{
  \alpha_s-\mathsf T_{\mathrm{spec}}^{\mathrm{RU}}(A,s)
  \ge \beta_s\gamma_s\nu_A.}

\end{equation}
Moreover, the feature margin exactly classifies strictness versus tightness
of the universal spectral envelope:
\begin{equation}
  \boxed{
  \nu_A>0
  \quad\Longleftrightarrow\quad
  \mathsf T_{\mathrm{spec}}^{\mathrm{RU}}(A,s)<\alpha_s,}

\end{equation}
\begin{equation}
  \boxed{
  \nu_A=0
  \quad\Longleftrightarrow\quad
  \mathsf T_{\mathrm{spec}}^{\mathrm{RU}}(A,s)=\alpha_s.}

\end{equation}
If $\nu_A=0$, there exists one residual direction
$z_*\in\mathcal Z_A$ such that, simultaneously for every
$s'\in\{d+1,\ldots,m-1\}$,
\begin{equation}
  \frac{\lambda_{\max}(\overline M_{s'}^{A,z_*})}{L^*}
  =\frac{m-s'}{m-d}.

\end{equation}
The right-hand side of \eqref{eq:robust-pre-response-slack} is a guaranteed
lower bound on the spectral slack.  The exact statement is the phase
classification in \eqref{eq:robust-pre-response-strict}--
\eqref{eq:robust-pre-response-tight}, not an equality formula for the
positive slack magnitude. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 24 of arXiv:2511.22156, ''] Let $B=B(x,r)$, there exist constants $C_7,C_8,C_9>0$, such that   
\begin{equation}
P^x(\tau_B\leq t)\leq C_7\exp(-C_8(\frac{r^{\beta}}{t})^{\frac{1}{\beta-1}}),\qquad C_9t>r>1.
\end{equation}

\begin{proof}
Let $\tau=\tau_B$. Notice that $\tau\leq t+(\tau-t){1}_{\{\tau>t\}}$. By \eqref{e:6.7}, 
\begin{equation*}
\begin{aligned}
C_5^{-1}r^\beta\leq E^x[\tau]&\leq t+E^x[{1}_{\{\tau>t\}}E^{W_t}[\tau]]\\
&\leq t+C_5 P^x(\tau>t)r^{\beta},\qquad r>1.        
\end{aligned}
\end{equation*}
Thus 
\[
C_5^{-1}r^\beta\leq t+C_5 P^x(\tau>t)r^{\beta},\qquad r>1,
\]

which gives 
\begin{equation}
P^x(\tau\leq t)\leq c_1+c_2r^{-\beta}t,\qquad r>1,
\end{equation}
for $c_1\in (0,1),\ c_2>0$. Let $n\geq 1$, $b=\frac{r}{n}$ and $s_0=0,\ s_{i+1}=\inf\{t>s_i:|W_t-W_{s_i}|=b\},\ \xi_i=s_i-s_{i-1},\ i\geq1$. By \eqref{e:6.13} and strong markov property,
\[
P^x(\xi_{i+1}\leq t|\mathcal{F}_{s_i})\leq c_1+c_2r^{-\beta}t,\qquad b>1.
\]
Then by \cite[Lemma 3.14. p32]{barlow2006diffusions}, 
\begin{equation}
\log P^x(\tau\leq t)\leq c_3(r^{-\beta}n^{1+\beta}t)^{\frac{1}{2}}-c_4n,\qquad r>n,
\end{equation}
where $c_4,c_3>0$. If $r^{\beta}>2c_3c_4^{-1}t>r$, then take $n=(c_4r^{\beta}/(2c_3t))^{\frac{1}{\beta-1}}\in (1,r)$, and by \eqref{e:6.14}
\begin{equation*}
P^x(\tau\leq t)\leq c_5 \exp(-c_6(\frac{r^{\beta}}{t})^{\frac{1}{\beta-1}}).
\end{equation*}
While if $2c_3c_4^{-1}t\geq r^{\beta}$, then we obtain the same bound, on adjusting the constant $c_5$. 
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 of arXiv:2511.01456, 'Zero distribution of multiplicative Hermite and Laguerre polynomials'] Recall that $m_k(\gamma)$ is the $k$-th moment of $\nu_{\beta, \gamma}$. Then,
\begin{equation}
\begin{aligned}
&m_k'(\gamma)
=
 -  \frac 1 {1 +  \beta}
\sum_{j=1}^{k} j m_j(\gamma)
\widehat B_{k-j} \left(m_1(\gamma),\ldots, m_{k-j}(\gamma); -\frac 1 {1 + \beta}\right),
\quad k\in \N,\ \gamma\geq 0,
\\
&m_{0}(\gamma) =  1 \quad (\text{for all } \gamma\geq 0), \qquad m_{k}(0) = 1 \quad (\text{for all } k\in  \mathbb N).
\end{aligned}
\end{equation}

