[Proposition prop:annealed 0 of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $f\in\mathbb{R}$, $u\in(0,1)$, $q\in(0,1)$, and $\zeta\in\mathrm{Prefix}_2(u,q)$. Recall $\mathcal{P}\mathrm{arisi}$ from (equation def:Par of the paper).
		Define the \emph{prefix free energy} 
		\begin{equation*}
			\mathcal{P}(u;q):=\inf_{\zeta'\in\mathrm{Prefix}_2(u,q)}\mathcal{P}\mathrm{arisi}(\zeta')
		\end{equation*}
		and the \emph{complexity functional at level $f$}
		\begin{equation}
			\mathcal{C}_f(u;q)
			\;:=\;
			u\,\bigl(\mathcal{P}(u;q)-f\bigr).
		\end{equation}

		We assume:
		\begin{enumerate}
			\item[\emph{(i)}]
			\emph{(Tail optimality.)} The infimum $\mathcal{P}(u;q)$ is attained at $\zeta$.
			\item[\emph{(ii)}]
			\emph{(Stationarity.)} $(u,q)$ is a critical point of $\mathcal{C}_f$.
		\end{enumerate}

		Let $\varepsilon\in(0,1)$ and let $\mathcal{N}_\varepsilon(f,\zeta,q)$ be the number of critical
		points of $F_{\mathrm{TAP},\zeta}$ in $\mathrm{SUSY}_1(\zeta,\varepsilon)$ with
		$\frac{1}{N}F_{\mathrm{TAP},\zeta}(\mathbf{m})\in(f-\varepsilon,f+\varepsilon)$.  Then
		\[
		\lim_{\varepsilon\to 0}\lim_{N\to\infty}
		\frac{1}{N}\log\mathbb{E}\bigl[\mathcal{N}_\varepsilon(f,\zeta,q)\bigr]
		\;=\;
		\mathcal{C}_f(u;q)
		\;=\;
		\zeta(\{0\})\,\bigl(\mathcal{P}\mathrm{arisi}(\zeta)-f\bigr).
		\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Em:MC:l of arXiv:2604.16206, 'Extrapolation of max--stable random fields with Fr\'echet marginals'] Let $\mathbf{X}=(X_1,\ldots,X_n)$ be a  $n$-variate max-stable random vector    with $H_\alpha$--distributed marginals  and tail dependence function $l_\mathbf{X}.$ For any $\mathbf{w}^{(1)},\mathbf{w}^{(2)}\in\mathbb{R}_+^n$ it holds
\begin{eqnarray}
    \rho_\mathbf{X}(\mathbf{w}^{(1)},\mathbf{w}^{(2)})&=  \frac{1}{1+l_\mathbf{X}\left((\mathbf{w}^{(1)})^\alpha\right)}+\frac{1}{1+l_\mathbf{X}\left((\mathbf{w}^{(2)})^\alpha\right)} \\
    &- \frac{2}{1+l_\mathbf{X}\left((\mathbf{w}^{(1)}\vee \mathbf{w}^{(2)})^\alpha\right)} \nonumber  .
\end{eqnarray}

[Proposition 8 (Failure of smoothness at an atom) of arXiv:2608.06565, 'Smoothness of the survival probability in models with a random environment: the annuity an'] Let $K=1$, $\sigma>0$, $\alpha>0$, let the measure $F$ have an atom at a point
$-b<0$ of weight $\varkappa:=F(\{-b\})>0$ and no other atoms in some punctured
neighbourhood of $-b$, and let $\Phi(0+)>0$. Then $\Phi\in C^1(0,\infty)$, the
second derivative has one-sided limits at $b$, and
\begin{equation}

    \Phi''(b^+)-\Phi''(b^-)=-\frac{2\alpha\,\varkappa\,\Phi(0+)}{\sigma^2b^2}
    \;<\;0 ,
\end{equation}
in particular $\Phi\notin C^2(0,\infty)$. The condition $\Phi(0+)>0$ holds,
for instance, for $c>0$.

[Lem Theorem:ProductRule of arXiv:2411.13765, 'Schr\"odinger Bridge Problem for Jump Diffusions'] Let $L$ be the jump-diffusion operator defined in (equation ReferenceGenerator of the paper), $h$ be a non-negative function of class $C^{1,2}$ on $[0,T]\times\mathbb{R}^n$, and $\mathcal A_h$ be as in (equation definition_A_h of the paper). Define, for every $(t,x)\in \mathcal A_h$, 
\begin{equation}
\begin{aligned} b^h(t,x):=b(t,x)& +\sigma\sigma^T\nabla
 \log h(t,x)+ \\
 & \int_{|z|\leq 1} \frac{h(t,x+\gamma(t,x,z))-h(t,x)}{h(t,x)}\gamma(t,x,z)\nu(dz),
\end{aligned}
\end{equation}
and
\begin{equation}
 \nu^h(t,x;dz) :=  \frac{h(t,x+\gamma(t,x,z))}{h(t,x)}\nu(dz).
\end{equation}
Then for every $f\in C^{1,2}(\mathbb{R}^+\times \mathbb{R}^n)$, at $(t,x)\in \mathcal A_h$, \begin{equation*}
    L(hf)(t,x)=\left (h\tilde{L}f+fLh\right ) (t,x),
\end{equation*}
where $\tilde{L}$ is the operator defined in (equation ReferenceGenerator of the paper) with $b$ replaced by $b^h$, and $\nu$ replaced by $\nu^h$. 
Equivalently, writing $\tilde{{\mathfrak L}}:=\frac{\partial}{\partial t}+\tilde{L}$, at $(t,x)\in \mathcal A_h$, 
\begin{equation}
    {\mathfrak L}(hf) (t,x) =\left(h\tilde{{\mathfrak L}}f+f{\mathfrak L} h\right)(t,x).
\end{equation}
In particular, if $h$ is harmonic, then $$\tilde{{\mathfrak L}}f=\frac{1}{h}{\mathfrak L}(hf)={\mathfrak L}^hf\text{ and }L^hf=\tilde{L}f\text{ on }\mathcal A_h.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:good_approximation of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] Suppose that we have the setup above where $\mathcal {L}$ is the outermost loop of $\Gamma_\mathbf{D}$ that surrounds~$0$. Suppose that $\metapprox{\epsilon}{\cdot}{\cdot}{\Gamma}$ is an approximate ${\rm CLE}_{\kappa'}${} metric for each $\epsilon \in {(0,1]}$ with respect to the same constants $c_{\mathrm{s}} \ge 0$, $c_{\mathrm{p}}(N) > 0$. We say that $(\metapprox{\epsilon}{\cdot}{\cdot}{\Gamma})_{\epsilon \in {(0,1]}}$ is a \emph{good approximation scheme} if there exists a constant $\mathbf{a}_{\epsilon} > 0$ for each $\epsilon \in {(0,1]}$ and a constant $a_0 > 0$ such that
\begin{equation}
 \lim_{\epsilon \searrow 0} \frac{\mathbf{a}_{\epsilon}}{\epsilon^{a_0}\median{\epsilon}} = 0
\end{equation}
and for each $r>0$ we have
\begin{equation}
 \lim_{\epsilon \searrow 0} \mathbf{P}\left[ \sup_{V \in \metregions} \sup_{\substack{\dpath[\overline{V}](x,y) < \epsilon ,\\ \dpath(x, \Upsilon_\Gamma \setminus \overline{V}) \ge r}} \metapproxres{\epsilon}{V}{x}{y}{\Gamma} \le \mathbf{a}_{\epsilon} \right] = 1 .
\end{equation}

[Theorem 30 of arXiv:2607.28614, 'Tampered Memory Elephant Random Walk on one-dimensional integer lattice'] Let $\theta^*$ be an equilibrium point for the mean field function $h$, that is, $\theta^* \in \{\theta: \, h(\theta)=0\}$, where $h$ is as in \eqref{Eq: recursion_general_SA}. Let $\theta_n$, $\Delta M_n$, and $r_n$ be as in \eqref{Eq: recursion_general_SA}, and $\theta_n \longrightarrow \theta^*, \text{ a.s.}$ as $n \to \infty$. 
Further, assume that 
\begin{equation}

{h(\theta)= \left(\theta -\theta^*\right) Dh(\theta^*)+ o(\lvert \lvert \theta -\theta^*\rvert \rvert^{1+\epsilon}) \text{ as } \theta \rightarrow \theta^*, \text{ for some } \epsilon>0.}
\end{equation}
Let $0< \rho^* < 1/2$. Furthermore, assume that 
\begin{equation}

\sum_{m=1}^n \E \left[\Delta M_m \left(\Delta M_m\right)^\top \mid \FF_{m-1}\right]= \OO(n), \text{ a.s. or in } L_1,
\end{equation}
and 
\begin{equation}

\sum_{k=1}^n r_k= o\left(n^{1-\rho^*-\delta_0}\right)
\text{ a.s. for some } \delta_0>0.
\end{equation}
Then there exists a random variable $L$, such that, 
\begin{equation}

n^{\rho^*}\left(\theta_n-\theta^*\right)\rightarrow L, \text{ a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:lipptx33 of arXiv:2411.10235, '\textbf{Smooth transport map via diffusion process}'] Let $\delta_1,\delta_2\in [0,1)$, $\lambda_1\geq 0$ and $l\in \mathcal{H}_1^{\delta_1,\lambda_1}(\mathbb{R}^d)$, $h\in \mathcal{H}_1^{\delta_2}(\mathbb{R}^d)$, $z\in \mathbb{R}^d$. For $t\in [0,1)$ and $\theta_1,\theta_2\in \mathbb{R}^d$, in the case $\beta\geq 1$ we have 
    \begin{align*}
        \|&\int (l(y)-l(z))h(y)(p^{t,\theta_1}(y)-p^{t,\theta_2}(y))d\lambda^d(y)\|\\
        & \leq C \sum_{i=1}^2\left(\|\theta_1-\theta_2\|^{\delta_1}\log(\|\theta_1-\theta_2\|^{-1})^{-\lambda_1}\Biggl(\int\|h(y)\|^2p^{t,\theta_i}(y) \right)^{1/2}+\|\theta_1-\theta_2\|^{\delta_2}\left(\int\|l(y)-l(z)\|^2p^{t,\theta_i}(y) \right)^{1/2}\Biggl).
    \end{align*}
    and in the case $\beta<1$, $l(y)-l(z)=y-t\theta_1$, $h(y)=H(y,\theta_2)$ we have
    \begin{align*}
        &\|\int (y-t\theta_1)H(y,\theta_2)(p^{t,\theta_1}(y)-p^{t,\theta_2}(y))d\lambda^d(y)\|\\
         \leq &C\|\theta_1-\theta_2\|\left(\|\int H(y,\theta_2)dp^{t,\theta_2}(y) \|+\|\int \left(y-t\theta_1 \right)dp^{t,\theta_2}(y)\|\right)\\
        & +C\frac{\|\theta_1-\theta_2\|^{\beta}}{\log(\|\theta_1-\theta_2\|^{-1})^{\theta}}\left(\int\|y-t\theta_2\|^2dp^{t,\theta_2}(y) \right)^{1/2}\left(\int\|H(y,\theta_2)\|^2p^{t,\theta_1}(y) \right)^{1/2}.
    \end{align*}

