[Prop intro-prop-1 of arXiv:2608.30518, 'Grow-up rates of inhomogeneous semilinear heat equations in the critical dimension'] Let $N\ge 3$ and $\lambda=\lambda^{*}$. Assume that (equation katei-f of the paper), $u_0\in C^{0}(\overline{B_1})$ and $\varphi_0\le u_0\le u^{*}$ in $B_1$. 
Then, (equation eq-intro-1 of the paper) admits a unique global solution $u$ such that $u\to u^*$ in $L^2(B_1)\cap C^2_{\mathrm{loc}}(\overline{B_1}\setminus \{0\})$ as $t\to \infty$. Furthermore, $u^{*}\in H^{1}_{0,\mathrm{rad}}(B_1)$ and $u$ satisfy
\begin{enumerate}
\item[(i)] $u^{*}\in C^{2}(\overline{B_1})$ and thus
$u\to u^{*}$ in $C^{2}(B_1)$ as $t\to\infty$ when $N\le 9$;
\item[(ii)] $u^{*}\not \in L^{\infty}(B_1)$ and
thus $\lVert u\rVert_{L^{\infty}(B_1)}\to\infty$ as $t\to\infty$ when $N\ge 10$ and $f\le f_H$ in $B_1$;
\item[(iii)] $u^{*}\in C^{2}(\overline{B_1})$ and
thus $u\to u^{*}$ in $C^{2}(B_1)$ as $t\to\infty$ when $N\ge 10$, $f\ge f_H$ in $B_1$
and $f\not \equiv f_H$,
\end{enumerate}
where $H$ and $f_h$ are those in (equation defH of the paper) and (equation deffh of the paper), respectively, (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 33 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Assume \eqref{H1} and \eqref{eq:liminf}. Then there exists constant $c>0$ such that for any $n$ sufficiently large, $h_*+\frac{n}{(\log n)^{1+\frac{\varepsilon}{8}}}\le  s \le h^*$ and $1\le k\le q_n(s)$, we have
    \begin{equation}
    \p_n\left(X_{s-{\frac{n}{(\log n)^{1+\frac{\varepsilon}{8}}}}}\le \dfrac{k}{(\log n)^{\frac{\varepsilon}{6}}}+(\log n)^{1+\frac{\varepsilon}{2}}\,\Big|\, X_s=k\right)\ge 1-c(\log n)^{-\frac{13}{24}\varepsilon}.
    \end{equation}

