[Thm 2 of arXiv:2609.02327, 'On the counting function of square-full numbers'] We assume the strong Riemann hypothesis. For any $x\geqslant x_0$, where $x_0$ is sufficiently large, there are effective complex constant $c_{\{\gamma /6 \}}$ such that the asymptotic formula
			\begin{equation}
				\sum_{n\leqslant x} f_2(n)= \frac {\zeta (\frac {3}{2})}{\zeta (3)} x^{\frac {1}{2}} + \frac {\zeta (\frac {2}{3})}{\zeta (2)}  x^{\frac {1}{3}}+	
				\sum_{\substack{\rho=\frac{1}{12}+i\frac{\gamma}{6},\\|\gamma |< c_1 x^{\frac {1}{2}},\\\zeta(6\rho)=0}}c_{\frac{\gamma}{6}} \ x^{\frac{1}{12}+i\frac{\gamma}{6}}
				+O_{\epsilon} \left( x^{10 \epsilon} \right)
			\end{equation}
			holds. We also have
			\begin{equation}
				\sum_{n\leqslant x} f_2(n)= \frac {\zeta (\frac {3}{2})}{\zeta (3)} x^{\frac {1}{2}} + \frac {\zeta (\frac {2}{3})}{\zeta (2)}  x^{\frac {1}{3}}+	
				\sum_{\substack{\rho=\frac{1}{12}+i\frac{\gamma}{6},\\|\gamma |< c_2 x^{\frac {5}{12}},\\\zeta(6\rho)=0}}c_{\frac{\gamma}{6}} \ x^{\frac{1}{12}+i\frac{\gamma}{6}}
				+O_{\epsilon} \left( x^{\frac {1}{12} + 10 \epsilon} \right).
			\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2511.09280, 'Random Walk conditioned to stay above a non-flat floor: curvature effects'] For any \(1\leq k\leq n/2\), \(a> 0\),
    \begin{equation*}
        P(S_k \geq a \given S_0=0 =S_n, S\geq 0)
        \leq
        \frac{4}{\sqrt{\pi}}\Bigl(\frac{a}{\sqrt{\beta k}} + \frac{\sqrt{\beta k}}{ a}\Bigr)e^{-a^2/2\beta k}.
    \end{equation*}

