body:
[Prop 13 (Randomized measure-valued weak solution) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] Let $(\mu_t,I_t,Z_t)_{t\in[0,T]}$ be a limit point of $(\mu^n_t,I^n_t,Z^n_t)_{t\in[0,T]}$. Then, $\mu=(\mu_t)_{t\in[0,T]}$ is a stochastic process taking values in $\mathcal{M}_{\leq 1}(\R^+)$ with $\mu_0=P_0\circ \theta_{a_0}^{-1}$ and it satisfies
\begin{equation}
\di \langle\mu_t,\phi\rangle	=\langle\mu_{t},\tfrac{{1}}{2}\sigma_{A}(t,\cdot)^{2}\partial_{xx}\phi\rangle\dt+\langle\mu_{t}, (b_{A}(t,\cdot)-A^\prime_{t})\partial_{x}\phi\rangle\dt + \di Z^{\phi}_t,
\end{equation}
for all $t\in[0,T]$ and all $\phi \in C^{2}_b(\R)$, almost surely, with 
\begin{equation}
\E\biggl[\int_0^t H_s \di Z_t^{ \phi}\biggr]
= \lim_{\delta \downarrow 0}  \E\biggl[\int_0^t H_s \bigl( \tfrac{1}{2} \partial_x \phi(0) - \phi(0) \gamma(s, C_s) \bigr)\langle \mu_s, \sigma_A(s, \cdot)^2 \psi_\delta  \rangle \ds \biggr],
\end{equation}
for all $t\in[0,T]$, all $\phi\in C_b^2(\R)$, and
all bounded continuous processes $H$ adapted to the filtration \eqref{eq:limit_filtration} generated by $(\mu,I)$, where
\begin{equation}
A_t = a_0 + \alpha\int_{t-\bar{d}}^t \varrho(t-s) I_{s} \ds,\quad C_t = \int_{t-\bar{d}}^t \varrho(t-s) (I_{s} - I_{s-\bar{d
}})\ds,\quad I_t= 1- \mu_t(\R^+).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2606.24599, '\bf Perron--Frobenius theorem for a general tree-valued growth-fragmentation-isolation pro'] Let $g: [0, \infty)\to\mathbb{R}$ be a continuous function, $C \in \R$,  and $c \in \R_+$. Assume the following estimate for all $0\leq s\leq t$
        \begin{equation}
        g(t) - g(s) \leq \int_s^t(-cg(r)+C)\,dr.
        \end{equation}
        Then for any $t\geq 0$ 
        \begin{equation}
        g(t) \leq \frac{C}{c} + \left[ g(0) - \frac{C}{c} \right]_+ e^{-ct},
        \end{equation}
        where $[ \cdot ]_+ := \max(0, \cdot)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

