[Def weighted stable nodal family of arXiv:2609.04023, 'Characterizing Contractions and Weighted Blowdowns'] \begin{enumerate}
    \item Define input data to be a tuple $(g,\mathscr{A}):=(g,a_1,\dots,a_n)$ consisting of an integer $g\ge 0$ and the {\em weight data} $(a_1,\dots,a_n)\in \mathbb{Q}^n$ satisfying $0<a_j\leq 1$ for $j=1,\ldots,n$ and $2g-2+a_1+a_2+\dots +a_n>0$.
    \item A family of nodal curves with marked points $(C,s_1,\ldots,s_n)\xrightarrow{\pi}B$ is stable of type $(g,\mathscr{A})$ if
    \begin{itemize}
        \item the sections $s_1,\ldots,s_n$ lie in the smooth locus of $\pi$,
        \item for any $\{i_1,\dots, i_r\}\subseteq [n]$ such that $\bigcap_{j=1}^{r}s_{i_j}(B)\neq\emptyset$, we have $a_{i_1}+\dots +a_{i_r}\leq 1$ and,
        \item $K_{\pi}+a_1s_1+a_2s_2+\dots +a_ns_n$ is $\pi$-ample.
    \end{itemize}
\end{enumerate}

[Lemma 23 of arXiv:2609.00245, 'Higher-order Gaussian bounds for maximally subelliptic boundary value problems'] For every \(\alpha\), there exists \(C_\alpha\geq 1\) such that, for every \((\xi,\delta)\in \CompactZero\times (0,\delta_0]\) and every \(\left( -\opL, \xi, \delta \right)\)-heat function \(u:(-1/2,1/2)\rightarrow \DomainLinfty\), the following statements hold.
    \begin{enumerate}[(i)]
        \item  
        If \((\xi,\delta)\in \SSetOne\), set \(U(t,x):=u(t,\Phi_{\xi,\delta}(x))\). Then,
            \begin{equation*}
                \sup_{\substack{t\in (-3/8,3/8) \\ y\in \Cuben{3/8}}}
                \left| \left( V^{\xi,\delta,1}\right)^{\alpha} U(t,y)  \right|
                \leq C_\alpha \LtNorm{U}[(-7/16,7/16)\times \Cuben{7/16}].
            \end{equation*}
        \item 
        If \((\xi,\delta)\in \SSetTwo\), set \(U(t,x):=u(t,\Psi_{\xi,\delta}(x))\). Then,
            \begin{equation*}
                \sup_{\substack{t\in (-3/8,3/8) \\ y\in \Cubengeq{3/8}}}
                \left| \left( V^{\xi,\delta,2}\right)^{\alpha} U(t,y)  \right|
                \leq C_\alpha \LtNorm{U}[(-7/16,7/16)\times \Cubengeq{7/16}].
            \end{equation*}
    \end{enumerate}

