[Theorem 2 of arXiv:2606.06231, 'Sensitivity of SDE Solutions to Perturbations of the Diffusion and Drift'] Under Assumptions  \ref{assump:main_assumptions_1}, \ref{assump:h_assump1}, \ref{assump:main_assumptions_2},  and \ref{assump:sigma_invert}, suppose also that:
\begin{enumerate}
\item  The SDE \eqref{eq:Y} for $Y_t$ is time-homogeneous.
\item $Y_0$ is distributed as $\mu^*_Y$, which is an invariant distribution for  \eqref{eq:Y}.
\item There exists $\sigma_{\mathrm{Lip}_1}\in (0,\infty)$ such that every $1$-Lipschitz function $h:\mathbb{R}^d\to\mathbb{R}$  is $\sigma_{\mathrm{Lip}_1}$-sub-Gaussian   with respect to $\mu_{X}^*$.
\end{enumerate}
If $F-G$ is bounded then we have the following bound on the $1$-Wasserstein distance:
\begin{align}
W_1(\mu_Y^*,\mu_{X}^*)\leq& \frac{  (1+1/\epsilon)^{1/2}}{K_{\kappa,\epsilon}^{1/2}} \|\sigma-\eta\|_{F,\infty}\\
&+(2C_*)^{1/2}  \sigma_{\mathrm{Lip}_1}\|\sigma^{-1}\|_{2,\infty} 
\left(  \|F-G\|_\infty^2+\frac{\kappa^2(1+1/\epsilon)\|\sigma-\eta\|_{F,\infty}^2}{K_{\kappa,\epsilon}}\right)^{1/2}\notag\,.
\end{align}
\begin{comment} Without boundedness of $F-G$ one still has
\begin{align}
W_1(\mu_Y^*,\mu_{X}^*)\leq&\frac{  (1+1/\epsilon)^{1/2}}{K_{\kappa,\epsilon}^{1/2}} \|\sigma-\eta\|_{F,\infty} \\
&+C_*^{1/2}  \sigma_{\mathrm{Lip}_1}\liminf_{T\to\infty}
\left(  \frac{1}{T} \int_0^T\mathbb{E}\left[ \left\|\sigma^{-1}(\tilde{X}_t)\left(F(\tilde{X}_t)-G(\tilde{X}_t)+\kappa(\tilde{X}_t-Y_t)\right)\right\|^2\right]dt\right)^{1/2}\,.\notag
\end{align}
\end{comment} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 23 (Doob's $L^p$ slack is an exact three-term residual) of arXiv:2608.20337, 'Information on trajectories:\\ martingales and random times'] Let $(M_t)_{t=0}^T$ be a nonnegative \emph{sub}martingale with deterministic $M_0>0$ and $M^\ast:=\sup_{t\le T}M_t$, let $p>1$ and $q=p/(p-1)$ with $\E[M_T^p]<\infty$, and let $U$ be as in~\eqref{eq:doob-bellman}.
\begin{enumerate}[label=(\roman*),leftmargin=2em]
\item $U(M_t,M^\ast_t)$ is a supermartingale and the \emph{optional-stopping deficit}
  \begin{equation}
    \delta_{\mathrm B}\;:=\;U(M_0,M_0)-\E\bigl[U(M_T,M^\ast_T)\bigr]
    \;=\;q\,\E\bigl[(M^\ast)^{p-1}M_T\bigr]-\E\bigl[(M^\ast)^{p}\bigr]-\frac{M_0^{p}}{p-1}
  \end{equation}
  is nonnegative: it is the Bregman record sum of Proposition~\ref{prop:ay-certificate}(iii), plus the nonnegative drift term of the submartingale form.
\item With the \emph{H\"older deficit}
  $\delta_{\mathrm H}:=\E[(M^\ast)^p]^{(p-1)/p}\,\E[M_T^p]^{1/p}-\E[(M^\ast)^{p-1}M_T]\ \ge 0$,
  \begin{equation}
    \bigl\|M^\ast\bigr\|_p\;=\;q\,\bigl\|M_T\bigr\|_p\;-\;\cR,
    \qquad
    \cR\;=\;\frac{q\,\delta_{\mathrm H}+\delta_{\mathrm B}+M_0^{p}/(p-1)}
               {\E[(M^\ast)^p]^{(p-1)/p}}\;\ge\;0 .
  \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 7 (Uniform two-convexity) of arXiv:2608.25971, 'Positive \texorpdfstring{$\tau$}{tau}-bi-Ricci curvature and Mean curvature flow with surg'] There is $\beta=\beta(n,\alpha_0)>0$ such that every hypersurface in
$\CC_{\tau,\kappa}(R,\alpha)$ satisfies
\begin{equation}
 \lambda_1+\lambda_2\geq\beta H.
\end{equation}
One may take
\begin{equation}
 \beta=\frac{2\alpha_0}{2(n-2)+n\alpha_0}.
\end{equation}
Consequently,
\begin{equation*}
 -H\leq\lambda_1\leq\cdots\leq\lambda_n\leq H,
 \qquad \frac1nH^2\leq|A|^2\leq nH^2,
\end{equation*}
$\lambda_i\geq\beta H/2$ for $i\geq2$, and
\begin{equation}
 |H\nabla_i h_{kl}-(\nabla_iH)h_{kl}|^2
 \geq\frac{\beta^2}{8}H^2|\nabla H|^2.
\end{equation}

