[Lemma 22 of arXiv:2603.00353, 'Aldous-type Spectral Gaps in Unitary Groups'] For every $k,d\in\Z_{\ge1}$, 
    \begin{enumerate}
        \item  $$\sum_{\sigma\in\sym(k)}\wg_{k,d}(\sigma)=\frac{1}{k!\cdot\ms{d}{k}}=\frac{1}{d(d+1)(d+2)\cdots(d+k-1)}.$$
        \item  $$\sum_{\sigma\in\sym(k)}\sign(\sigma)\cdot\wg_{k,d}(\sigma)=
        \begin{cases}
            \frac{1}{k!\cdot\binom{d}{k}}=\frac{1}{d(d-1)(d-2)\cdots(d-k+1)} & d\ge k\\
            0 & d<k.
        \end{cases}
        $$
    \end{enumerate}

