[Lemma 22 (Reduction to simple integrals) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Let $z_0 \in \R^2$ and $(a,b) \in \R^2$ such that $b > 0$ and $(a,b) \neq z_0$. Then, for $\e > 0$ small enough, $g^{z_0}(a,b)$ can be written as $g^{z_0}(a,b) = I_1^{z_0}(a,b) + I_2^{z_0}(a,b)$, where
\begin{equation}
I_1^{z_0}(a,b) = \frac{1}{2i\pi}\int_{-\e - i\infty}^{-\e + i\infty}
\phi^{z_0}(x)\frac{\gamma(x, Y^+(x), Z^+(x))}{\partial_y\gamma_+(x, Y^+(x))} e^{-ax - bY^+(x)}
\, dx
\end{equation}

and
\begin{equation}
I_2^{z_0}(a,b) = \frac{1}{2i\pi}\int_{-\e - i\infty}^{-\e + i\infty}
\frac{e^{(a_0 - a)x} \left(
e^{(b_0 - b)Y^+(x)}\fc_{b_0>0} 
+ e^{b_0Z^+(x) - bY^+(x)}\fc_{b_0 < 0}
\right)}{\partial_y\gamma_+(x, Y^+(x))} \, dx \quad \textnormal{if } b > b_0.
\end{equation}

Furthermore, the following expressions hold for $I_2^{z_0}(a,b)$ if $b_0 > 0$:
\begin{equation}
I_2^{z_0}(a,b) = \frac{1}{2i\pi}\int_{-\e - i\infty}^{-\e + i\infty}
\frac{e^{(a_0 - a)X^+(y) + (b_0 - b)y}}{\partial_x\gamma_+(X^+(y), y)} \, dy \quad \textnormal{if } a > a_0
\end{equation}
\begin{equation}
I_2^{z_0}(a,b) = \frac{-1}{2i\pi}\int_{-\e - i\infty}^{-\e + i\infty}
\frac{e^{(a_0 - a)X^-(y) + (b_0 - b)y}}{\partial_x\gamma_+(X^-(y), y)} \, dy \quad \textnormal{if } a < a_0.
\end{equation}

[Thm 1 of arXiv:2609.03188, 'Some generalizations of Oort's conjecture'] Assume that $p\geq5$. Each of the following loci contains an open dense subscheme $U$ such that $\operatorname{Aut}(A_x,\vph_x)=\{\pm1\}$ for every $x\in U(\overline{\F}_p)$:
\begin{enumerate}[(i)]
\item for even $g$, the supersingular Ekedahl--Oort stratum attached to $w\in\SAdm(\mu)$ such that $\supp_\sigma(w)$ is a maximal proper $\tau$-stable subset of $\tS$;
\item for $g\geq3$, the intersection of $\mathscr S_g$ with the Ekedahl--Oort stratum attached to $w\in\SAdm(\mu)$ such that $\supp_\sigma(w)=\tS$ and $w$ is of positive Coxeter type;
\item for $g\geq4$, the locus in $\mathscr S_g$ where the $a$-number is at least $2$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:Lie-weighted-formula of arXiv:2609.02710, 'Asymptotic Mean Value Laplacian\\ on equiregular sub-Riemannian manifolds'] Let $W\in C^\infty(G)$ and $\mu_W=e^W\mu$, where $\mu$ is left Haar
measure, and write $A_h^{\mu_W}$ for (equation eq:AMV-def of the paper) formed with
$\mu_W$. Then, for every $f\in C_c^\infty(G)$, locally uniformly in $x$,
\begin{equation}
\begin{split}
  A_h^{\mu_W}f(x)\longrightarrow\frac1{\widehat V}\Bigg[&
    \frac12\sum_{i,j=1}^kM_{ij}X_iX_jf(x)\\
  &+\sum_{i,j=1}^kM_{ij}
    \left(X_jW(x)-\frac12\Tr(\ad_{X_j})\right)X_if(x)
  \Bigg].
\end{split}
\end{equation}

[Definition 1 of arXiv:2606.06757, 'Path-Dependent Ergodic Optimal Control \\ and Backward Stochastic Differential Equations'] {\rm (i)} $\K\!:=\!\big\{K\!: \R_+\!\to\!\R_+~\text{non-increasing}, \text{c\`adl\`ag},\ \int_0^\infty\!K(t)\,dt=1 \big\}$ is the set of \textnormal{kernels}; \\

\vspace{-8pt}

\noindent {\rm (ii)} The uniform Kernel $K^0:=\mathbf{1}_{[0,1)}$, the exponential kernel $K^{\rm exp}:=e^{-\cdot}$ and the rescaled kernel $K_\rho:=\rho K(\rho\cdot)$ are elements of $\K$, for all $K\in\K$, $\rho>0$; \\

\vspace{-8pt}

\noindent {\rm (iii)} For $\Lambda \in {\rm{UC}}$ and $K \in \K$, we define the two \textnormal{ergodic values} of $\Lambda$ by:
    \begin{equation*}
    \begin{array}{ccc}
        \displaystyle \lambda_*(K)\coloneqq \liminf_{\rho\downarrow 0} - \int_0^\infty \Lambda(t) \,dK_{\rho}(t)& \text{and} & \displaystyle \lambda^*(K)\coloneqq \limsup_{\rho\downarrow 0} - \int_0^\infty \Lambda(t) \, dK_{\rho}(t) \,.
    \end{array}
    \end{equation*}
If in addition $\Lambda\in{\rm UC}\cap{\rm AC}$, then $\Lambda$ has linear growth and we have by integration by parts:
\begin{equation*}
\begin{array}{ccc}
    \displaystyle \lambda_*(K)\coloneqq \liminf_{\rho\downarrow 0}\int_0^\infty K_{\rho}(t)\Lambda'(t)\,dt & \text{and} & \displaystyle \lambda^*(K)\coloneqq \limsup_{\rho\downarrow 0}\int_0^\infty K_{\rho}(t) \Lambda'(t)\,dt \,,
\end{array}
\end{equation*}
as $\lim_{T\to\infty}TK(T)=0$ due to the non-increase and the integrability of $K$ at $\infty$.

[Corollary 11 (Compatible initial potential) of arXiv:2609.01589, 'Uniform stability of expanding simple waves for Euler--Poisson--Boltzmann: a singular comp'] Let $n_0=n^a(t_0)+r_0$ with $r_0\in H^s$, $\norm{r_0}_{H^s}$ sufficiently
small, and $n_0>0$.  Then there is a unique
$\phi_0=\phi^a(t_0)+\psi_0$ satisfying the Poisson equation and the prescribed
far fields.  Moreover,
\begin{equation}
  \norm{\psi_0}_{\cG^s_\eps}
  \le C\left(\norm{r_0}_{H^s}
  +\norm{\cR_\phi^a(t_0)}_{H^s}\right). 
\end{equation}
Thus $r_0$ and $v_0$ are the freely chosen perturbative data; $\psi_0$ is a
constraint variable. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition eq:u'-less-v of arXiv:2604.20094, 'Persistence and local extinction for superprocesses in random environments'] Let $f\in C_c^+({\mathbb R}^d)$. Then $0\leqslant u(\lambda)\leqslant \lambda v$, and there is a random function $\partial_\lambda u: \overline{{\mathbb R}}_+\times \overline{{\mathbb R}}_+ \times {\mathbb R}^d\times \Omega\to {\mathbb R}$ such that
     \begin{equation}
    	0\leqslant \partial_\lambda u(\lambda) \leqslant v ~\mbox{ and }~   u(\lambda)= \int_0^\lambda \partial_\lambda u(\tau) \mathrm{d} \tau.
    \end{equation}
    Moreover, $\partial_\lambda u(\lambda)$ solves equation (equation eq:Eq-Du of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2608.07239, 'Unified framework for asymptotically uniform iterative construction of generalised random '] Consider the iterative oriented graph process on $V$, $\d$, $\d'$, and $X$. Let $x_{\max}$ be the maximum out- or in-degree in $(V,X)$, and let
		\begin{align}
			d_{\max}&:=\max\{d_1,\ldots,d_n,d_1',\ldots,d_{n}'\},
			\\\Delta&:=d_{\max}(d_{\max}+x_{\max}).
		\end{align}
		Consider the asymptotics as $m\to\infty$, and assume that $\Delta=O(m^{\sfrac12}/(\log m)^2)$. Then the probability of rejection is $O(\Delta/m)$. In particular, for $m$ large enough, there exists an oriented graph with out- and in-degree sequences $\d$ and $\d'$ and with no arcs from $X$. Furthermore, any such graph is sampled with probability $(1+O(\mathscr{E}))\mathscr{P}$, where $\mathscr{E}:=\mathscr{E}(m,\Delta)$ and $$\mathscr{P}:=\exp(\lambda_{\d,\d'}+\tfrac12\lambda_{\d,\d'}^2+\tfrac12\lambda_{\d}\lambda_{\d'}+\mu_{\d,\d'}^{X})\frac1{m!}\prod_{i=1}^{n}d_i!d_i'!,$$ which is asymptotically uniform. The total number of such graphs is thus $(1+O(\mathscr{E}))\mathscr{P}^{-1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[OPEN PROBLEM - not a proved fact. Stated in arXiv:2607.02406, 'On the range of competing random walks' (conjecture environment).] If $X^1,\dots,X^N$ are in the domain of attraction of a $\beta$-stable process $U$ with scale function $b(n)$ and that $d/\beta<1$, then 
 \begin{equation*}
 \frac{1}{b(n)}\R_n^k\distribution\lambda\left(\left\{x\in\RR, \tau_x^k\le 1\wedge\min_{j\ne k}\tau_x^j\right\}\right),
 \end{equation*}
 where $U^1,\dots,U^N$ are $i.i.d.$ copies of $U$ and where $\tau_x^\ell\eqdef\inf\{t>0, U_t^\ell=x\}$.

 Furthermore, joint convergence in $k\in[\![N]\!]$ also holds. (Verbatim from the paper's TeX; symbols are the source paper's. Stated as open/conjectural; no resolution of it was found in the paper's own text by the rules of problem_index.py - a paper may still prove special cases of a conjecture it states.)

[Definition 57 (H\"older spaces of regularity $\alpha\in(0,1)$) of arXiv:2605.14630, '2605.14630'] For $0 < \alpha < 1$, the space $\cC^\alpha(\Lambda)$ consists in all functions 
$f:\Lambda\to\R$ such that 
\begin{equation}

 \norm{f}_{\cC^\alpha} 
 = \sup_{x\in\Lambda} \abs{f(x)}
 +\sup_{\substack{x,y\in\Lambda \\x\neq y}}
 \frac{\abs{f(x)-f(y)}}{\norm{x-y}^\alpha} < \infty\;.
\end{equation}

