[Prop 72 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $n\in \N$, $n$ odd.
Then the following holds.
\begin{enumerate}
\item For every $j\in \{0,\dots, \lfloor n/2\rfloor-1\}$,
\begin{displaymath}
\dfrac{1}{2^{n-1}}
\sum_{k=0}^{\lfloor n/2\rfloor}
(-1)^{j+k}
\dfrac{n! (2(n-1-k-j))!}{(n-2k)! k! (n-1-k-j)! j!}
= 0.
\end{displaymath}
\item In the case $j = \lfloor n/2\rfloor$,
\begin{displaymath}
\dfrac{1}{2^{n-1}}
\sum_{k=0}^{\lfloor n/2\rfloor}
(-1)^{j+k}
\dfrac{n! (2(n-1-k-j))!}{(n-2k)! k! (n-1-k-j)! j!}
= 1.
\end{displaymath}
\end{enumerate}

