[Proposition prop:2ptfncrestt of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Under the assumptions of Proposition~(prop:mgfref of the paper),  also let $\pi_{\hash} V_0 = \sigma_\hash \lambda^{(\emptyset)}_{0, \hash} \varphi^{(1)}_\hash$ for both $\hash \in \{{\sf o},{\sf x}\}$.  Then
\begin{align}
	\lambda^{(\emptyset)}_{0, {\sf o}} \lambda^{(\emptyset)}_{0, {\sf x}}	\frac{\E_{C^{(\vec{\textbf{a}})}} [ \varphi_{\sf o}^{(1)} \varphi_{\sf x}^{(1)} e^{-V_{0,\varnothing} (\Lambda, \varphi)  }  ] } {\E_{C^{(\vec{\textbf{a}})}} [ e^{-V_{0,\varnothing} (\Lambda, \varphi) }  ]}
		& = 
		\frac{\int_{\R^n} Z_{N,{\sf ox}} ( y \one ) e^{-\frac{1}{2}  t_N^{-1} L^{dN}  |y|^2  } {\rm d} y }{\int_{\R^n} Z_{N,\varnothing}  ( y \one ) e^{-\frac{1}{2} t_N^{-1} L^{dN} |y|^2  } {\rm d} y }  .
\end{align}
If $\textbf{a}^{(\emptyset)}=0$,  then the identity holds with $t_N^{-1} = 0$.

