    \centering
    \includegraphics[width=8cm]{Random_3_with_localization.png}
    \caption{Localization of multiple radial SLE($\kappa$)} 

\end{figure}

[Definition 36 of arXiv:2601.16377, '2601.16377'] Let $\boldsymbol{\chi}_{\N}^{(1)}$ and $\boldsymbol{\chi}_{\N}^{(2)}$ be two families (indexed by a large parameter $\N$) of discrete random $K$-dimensional real vectors. We say that the distribution of $\boldsymbol{\chi}_{\N}^{(1)}$ is asymptotically equal to the distribution of $\boldsymbol{\chi}_{\N}^{(2)}$ if
\begin{equation}

 \lim_{\N\rightarrow\infty} \sup_{f \in \textnormal{Lip}_1} \big|\E[f(\boldsymbol{\chi}_{\N}^{(1)})]-\E[f(\boldsymbol{\chi}_{\N}^{(2)})]\big| =0,
\end{equation}
where $\textnormal{Lip}_1$ is the set $1$-Lipschitz functions real-valued functions on $\amsmathbb{R}^K$ that are upper-bounded by $1$. If \eqref{eq_asymptotic_equivalence} holds, we write $\chi_{\N}^{(1)} \stackrel{\textnormal{d}}{\sim} \chi_{\N}^{(2)}$.

[Lemma 8 (Log-concavity) of arXiv:2608.30174, 'Exact counting of spherical metrics with one conical singularity on rectangular tori'] On every open interval $I\subset\mathbb{R}$ where $\Delta_q(E)\in (-2,2)$,
\begin{equation}
 \frac{\dd^2}{\dd E^2}\log\bigl(4-\Delta_q(E)^2\bigr)<0.
\end{equation}

