body:
[Theorem Thm:SLLN of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Suppose that $\{X_k\}_{k\geq 1}$ is a d-dimensional $\alpha$-mixing stationary sequence on a regular sublinear expectation space $(\Omega,\mathcal{H},\hat{\mathbb{E}})$ for some $\alpha>0$ with $\hat{\mathbb{E}}[|X_1|^{2}]<\infty$. Let
   $\Gamma_*$ be defined as in (equation eq:Gamma* of the paper).
     Then 
     \begin{equation*}
         \lim_{n\to\infty}dist\left(\frac{1}{n}\sum_{k=1}^nX_k,\Gamma_*\right)=0, \ \text{$\hat{\mathbb{E}}$-q.s.,}
     \end{equation*}
     where $dist(x,\Gamma_*):=\inf_{y\in \Gamma_*}|x-y|$. In particular, this implies that all limit points of the sequence $\{\frac{1}{n}\sum_{k=1}^nX_k\}_{n=1}^\infty$ are contained within the set  $\Gamma_*$, $\hat\mathbb{E}$-q.s. For the case when 
 $d=1$,
     \begin{equation*}
       -\hat{\mathbb E}[-X_1] \le \inf_{x\in \Gamma_*}x\leq \liminf_{n\to\infty}\frac{1}{n}\sum_{k=1}^nX_k\leq \limsup_{n\to\infty}\frac{1}{n}\sum_{k=1}^nX_k\leq \sup_{x\in \Gamma_*}x\leq\hat{\mathbb E}[X_1], \ \text{$\hat\mathbb{E}$-q.s.} 
     \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2605.23461, 'An almost sure invariance principle for the Takagi--van der Waerden class functions'] Suppose that \eqref{Assump2:A_n_to_infinite} and \eqref{Assump2:last_term} hold. Then, for $\mu$-a.e.~$x$,
  \begin{equation}
    A_{m(h)}^{-1/2+\delta/8}\sum_{k=k_0(x,h)+1}^{m(h)} |a_k| \to 0\quad \text{as $h\downarrow 0$}.
  \end{equation}

