[Lemma 11 of arXiv:2603.29473, '$\chi^2$--cut-off phenomenon for Galerkin projections of Fokker--Planck equations with mon'] Let $f \in \mathcal{C}(\R_+)$ and $g \in \mathcal{C}(\R_+)$. Let $u \in \mathcal{C}^2(\R_+)$ be a solution to
	\begin{equation}
		-u'' + f u' = g u\quad \textrm{ in }\quad \R_+
	\end{equation}
	with boundary condition $(u(0),u'(0)) = X_0\in \R^2$.
	For all $t\geq 0$
	denote $X(t):= (u(t),u'(t))$ and define the radial component $r$ and angular component $Y$ such that $X(t) = r(t) Y(t)$ with $Y(t): = (\cos(\theta(t)), \sin(\theta(t)))$. Then $r \in \mathcal{C}^1(\R^+)$ and satisfies the non-homogeneous ODE
	\begin{equation} 
		r'(t) = r(t) A(t) Y(t) \cdot Y(t), \quad \text{where} \quad A(t) =
		\begin{bmatrix}
			0     & 1    \\
			-g(t) & f(t)
		\end{bmatrix},
	\end{equation}
	where $\cdot$ denotes the usual inner product in $\mathbb{R}^2$.
	Furthermore, $\theta \in \mathcal{C}^1(\R_+)$ satisfies the ODE
	\begin{equation} 
		\theta'(t) = -1 - (g(t)-1) \cos^2(\theta(t)) + \frac{f(t)}{2} \sin(2\theta(t)).
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:moment_cumulant_formula of arXiv:2608.28169, 'characteristic polynomial of self-normalized random matrices'] {PeccatiTaqqu2011}}]
    Let $(Z_k)_{k \geqslant 1}$ be a family of random variables. Then it holds for any positive integers $k_1,\ldots,k_{\ell}$ that
    \begin{equation}

        {\mathbb E} \left[\prod_{r=1}^\ell Z_{k_r} \right] = \sum_{\pi \in \mathcal{P}_\ell} \prod_{B \in \pi} \kappa_B(Z_{k_1}, \dots, Z_{k_\ell}) \,,
    \end{equation}
    where $\mathcal{P}_{\ell}$ denotes the set of all partitions of $\{1,\ldots,\ell\}$ and where for $B=\{r_1,\ldots,r_s\}\subseteq\{1,\ldots,\ell\}$,
    \begin{equation*}
        \kappa_B(Z_{k_1}, \dots, Z_{k_\ell}) := \kappa_s(Z_{k_{r_1}}, \dots, Z_{k_{r_s}})
    \end{equation*}
    denotes the $s$-th joint cumulant of 
    $Z_{k_{r_1}}, \dots, Z_{k_{r_s}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma aindistr of arXiv:2606.30475, 'Ancestries in random $d$-DAGs'] For $2\leq i\leq n$ and $j\in[n+1-i]$, we have
 \begin{equation}
  \mathbb{P}(a_i(n)=j) = \bigg(\frac{i-1}{n-j}\bigg)^d \cdot \prod_{k=1}^{j-1} \left[1-\bigg(\frac{i-1}{n-k}\bigg)^d\,\right].
 \end{equation}

[Lemma 15 of arXiv:2606.15432, 'A Concavity Theorem for the Parisi PDE'] For all $(s,x)\in [0,1]\times \R$,
\begin{equation}
\paraop_s
v^\gamma(s,x)
=
(\partial_x\Psi^\gamma)^2.

\end{equation}
Therefore, for all $0\leq \rho\leq r\leq 1$,
\begin{equation}
P_{\rho,r}^\gamma[v^\gamma(r,\cdot)](x)
=
1-\int_r^1 w_{\rho,\sigma}^\gamma(x)\,d\sigma.

\end{equation}

