body:
[Definition def:var-sol of arXiv:2608.21805, 'Logarithmic derivatives of variational and singular stochastic partial differential equati'] An $H$-valued continuous $\mathcal{F}_t$-adapted process $X = \{X(t)\}_{t \in [0,T]}$ is a
\emph{variational solution} (or \emph{analytically strong solution}) of~(equation eq:SPDE of the paper) if:
\begin{enumerate}[(i)]
  \item $X \in L^p(0,T; V) \cap C([0,T]; H)$ $\mathbb{P}$-a.s.;
  \item $\mathcal{A}(\cdot, X(\cdot)) \in L^{p'}(0,T; V^*)$ $\mathbb{P}$-a.s., where $p' = p/(p-1)$;
  \item $\mathcal{B}(\cdot, X(\cdot)) \in L^2(0,T; L_2(U, H))$ $\mathbb{P}$-a.s.;
  \item for all $t \in [0,T]$ and all $\varphi \in V$, the following identity holds $\mathbb{P}$-a.s.:
  \begin{multline}
    \ip{X(t)}{\varphi}_H + \int_0^t \dual{\mathcal{A}(s, X(s))}{\varphi}\,\mathrm{d}s \\
    = \ip{x}{\varphi}_H + \int_0^t \ip{\mathcal{B}(s, X(s))\,\mathrm{d}W(s)}{\varphi}_H,
  \end{multline}
  where the last integral is the It\^o stochastic integral taking values in $\mathbb{R}$ via the pairing $\ip{\mathcal{B}(s,X(s))\,\mathrm{d}W(s)}{\varphi}_H = \sum_{k=1}^\infty \ip{\mathcal{B}(s,X(s))f_k}{\varphi}_H\,\mathrm{d}B^k_s$.
\end{enumerate}

