[Theorem thm:qsl-rw2mc of arXiv:2509.10225, 'Phase Transitions for Elephant Random Walks \\ with Two memory Channels'] {We have the following quadratic strong laws for the fluctuations around the almost sure limit.
\begin{enumerate}
\item[a)] For $p \in \left(0, \frac{11}{16}\right)\cup\left(\frac{113+\sqrt{97}}{128}, 1\right)$,
\begin{align}
    \lim_{n \to \infty} \frac{1}{\log n}\sum_{k=1}^n\left(\frac{S_k}{k}-\Lambda_p\right)^2 
    {= \Sigma^{(1)}_p},
\end{align}
where $\Sigma^{(1)}_p$ is given by (equation eq:sigma1 of the paper).\\
\item[b)] For $p \in \left\{\frac{11}{16}, \frac{113+\sqrt{97}}{128}\right\}$,
\begin{align}
    \lim_{n \to \infty}  \frac{1}{\log\log n}\sum_{k=1}^n\left(\frac{1}{\log k}\right)^2\left(\frac{S_k}{k}-\Lambda_p\right)^2 
    {= \Sigma^{(2)}_p},
\end{align}
where $\Sigma^{(2)}_p$ is given by (equation eq:sigma2 of the paper).
\end{enumerate}} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def: fantastic_vertex of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] We say $v \in \mathbb{T}^d_m$ is $\mathbf{fantastic}$ if the planted particle $w_0^o$ visits at least $\phi(s)$ number of vertices in $B_v$, where
    \begin{align}
        \phi(s) = \begin{cases}
            \, \frac{c_1 s}{2}, &\textup{if $d \ge 3$ or $(d = 2$ and $\alpha > 2)$,} \\[0.2em]
            \, \frac{c_1 s}{2 \log \log s}, &\textup{if $d = 2$ and $\alpha = 2$,} \\[0.2em]
            \, \frac{c_1 s}{2 \log s}, &\textup{if $d = 2$ and $\alpha < 2$,}
        \end{cases} \quad
        s = \begin{cases}
        \, r^2, &\textup{if } \alpha > 2, \\[0.2em]
        \, \frac{r^2}{\log r}, &\textup{if } \alpha = 2, \\[0.2em]
        \, r^\alpha, &\textup{if } \alpha < 2,
    \end{cases} 
    \end{align}
    and $c_1$ is the same constant in Lemma~(lemma: range_estimates_main_text of the paper). Let $\mathrm{Fant}$ denote the set of all $\mathrm{fantastic}$ vertices.

[Lemma lem  : Topology/GMT/Gradient of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] Let $D \in \RegPD[\mu]$, and $\gamma: \intervalleff0T \rightarrow X$ be a Lipschitz path.

	\begin{enumerate}[(i)]
	\item For almost every $t\in\intervalleff0T$,
	\begin{equation}

		\MD\gamma(t) = (\Pgrad D)_{\gamma(t)}\mathopen{}\mathclose\bgroup\originalleft( \gamma'(t) \aftergroup\egroup\originalright).
		\end{equation}

	\item For all $0\le t_1 \le t_2 \le T$,
	\begin{equation}

		D\p{ \restriction\gamma{\intervalleff{t_1}{t_2} } } =  \int_{t_1}^{t_2} (\Pgrad D)_{\gamma(t)}\mathopen{}\mathclose\bgroup\originalleft( \gamma'(t) \aftergroup\egroup\originalright) \mathrm{d} t.
	\end{equation}
	\end{enumerate}

