body:
[Proposition 24 (Interior identification and local integrability of the limiting drift) of arXiv:2605.23529, 'Generalized Bessel-Dunkl diffusions'] Let
    \begin{equation*}
        \left(
            X,M,\bigl(A^\alpha\bigr)_{\alpha\in R_+}
        \right)
    \end{equation*}
    be a generalized weak limit obtained in Proposition~\ref{prop:deg:skorokhod}. Then, for every $\alpha\in R_+$, there exists a continuous increasing process $\Lambda^\alpha$ on $[0,\zeta)$, with $\Lambda^\alpha(0)=0$, such that, almost surely, for every $t<\zeta$,
    \begin{equation}

        A^\alpha(t) = \int_0^t \frac{k_\alpha(s,X(s))}{\langle X(s),\alpha\rangle} \mathbf 1_{\{\langle X(s),\alpha\rangle>0\}}\,ds + \Lambda^\alpha(t).
    \end{equation}
    Moreover, the Stieltjes measure $d\Lambda^\alpha$ is supported on the wall $\{\langle X,\alpha\rangle=0\}$, in the sense that, almost surely, for every $t<\zeta$,
    \begin{equation}

        \int_0^t \mathbf 1_{\{\langle X(s),\alpha\rangle>0\}} \,d\Lambda^\alpha(s) = 0.
    \end{equation}
    Equivalently, on $[0,\zeta)$,
    \begin{equation}

        dA^\alpha(t) = \frac{k_\alpha(t,X(t))}{\langle X(t),\alpha\rangle} \mathbf 1_{\{\langle X(t),\alpha\rangle>0\}}\,dt + d\Lambda^\alpha(t).
    \end{equation}
    Furthermore, for every $T,r>0$, define
    \begin{equation}

        \chi_r := T\wedge\inf\{t\in[0,\zeta):\ |X(t)|\ge r\},
    \end{equation}
    with the convention $\inf\varnothing=\infty$. Then, for every $\alpha\in R_+$,
    \begin{equation}

        \E \int_0^{\chi_r} \frac{k_\alpha(s,X(s))}{\langle X(s),\alpha\rangle} \mathbf 1_{\{\langle X(s),\alpha\rangle>0\}}\,ds \le C_{\alpha,r,T},
    \end{equation}
    where $C_{\alpha,r,T}$ is the constant from Proposition~\ref{prop:deg:localized-compactness}\textup{(ii)}. Consequently, almost surely,
    \begin{equation}

        \int_0^t \frac{k_\alpha(s,X(s))}{\langle X(s),\alpha\rangle}\mathbf 1_{\{\langle X(s),\alpha\rangle>0\}}\,ds < \infty
    \end{equation}
    for every $t<\zeta$.

