[Lem decoration-moments of arXiv:2607.21428, 'Subcritical percolation and network archaeology on random recursive tree substrate network'] Conditional on \(\mathcal{F}_n\), the variables
		\((\widetilde X_u:u\in\mathcal{B}_n^{\operatorname{root}})\) are independent.  Moreover, they are
		conditionally independent of the internal root-blob genealogy.  On the event
		of Lemma~(lem:singly-attached-decorations of the paper), put
		\[
		X_u:=|D_u|,\qquad u\in\mathcal{B}_n^{\operatorname{root}},
		\]
		where \(D_u\) includes the skeleton vertex \(u\).  Off this event set
		\(X_u=1\) for definiteness; this convention only affects an \(o(1)\) event.
		Then
		\begin{equation}

			\mathbb P\left(
			X_u=\widetilde X_u\text{ for all }u\in\mathcal{B}_n^{\operatorname{root}}
			\right)\to1.
		\end{equation}
		Moreover, for every \(\zeta>0\), there exists a finite deterministic
		\(C_\zeta>1\) such that the \(\mathcal{F}_n\)-measurable event
		\[
		E_n^{\mathrm{mom}}(C_\zeta)
		:=
		\left\{
		1\leqslant \mathbb E[\widetilde X_u\mid\mathcal{F}_n]\leqslant C_\zeta
		\text{ and }
		\mathbb E[\widetilde X_u^2\mid\mathcal{F}_n]\leqslant C_\zeta
		\text{ for all }u\in\mathcal{B}_n^{\operatorname{root}}
		\right\}
		\]
		satisfies
		\begin{equation}

			\limsup_{n\to\infty}
			\mathbb P\left(E_n^{\mathrm{mom}}(C_\zeta)^c\right)
			\leqslant\zeta .
		\end{equation}
		In addition,
		\begin{equation}

			\max_{u\in\mathcal{B}_n^{\operatorname{root}}} X_u=o_{\mathbb P}(|\mathcal{B}_n^{\operatorname{root}}|).
		\end{equation}

[Lemma 33 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] Let us recall the processes $\wtilde{M}_m$ and $\wtilde{M}$ defined in \eqref{eqn-martingale} and \eqref{eqn-martingale-1}, respectively. Then, for fixed $\psi \in L^2(\bO)$ and $0\le s\leq t \le T$
				\begin{align}
					\lim_{m\to\infty} \wtilde{\E}\big[(\wtilde{M}_m(t) -\wtilde{M}_m(s),\psi)h(\wtilde{u}_{m}|_{[0,s]})\big] = \wtilde{\E}\big[(\wtilde{M}(t) -\wtilde{M}(s),\psi)h(\wtilde{u}|_{[0,s]})\big].
				\end{align}

[Proposition 49 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] For every $t\geq0$ and every $q=(q_s)_{s\in\sS}\in\mcl Q_2^\sS$, writing $q^\lambda:=\sum_{s\in\sS}\lambda_s q_s$,
we have
\begin{align}

    u(t,q^\lambda)\leq f(t,q)\leq \sum_{s\in\sS}\lambda_s u(t,q_s).
\end{align}
In particular, we have $f(t,0)=u(t,0)$.

