[Definition def: renormalized cost fcn of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] Let $T>0$. The \emph{renormalized cost function} is the map given, for every $u \in \mathbb H$, by
\begin{equation}
\mathbb F_T^{\Xi^\partial_T(\varphi_-,\varphi_+)}(u):= \mathbb E \left[ \Phi^{\varphi_-,\varphi_+}_T(u) + \mathcal C_T(u) \right],	
\end{equation}
where
\begin{equation}
\Phi_T^{\varphi_-,\varphi_+}(u) = 	\sum_{i=1}^9 R_i + \sum_{i=1}^4\Upsilon_{i,T}.
\end{equation}
The \emph{renormalized variational problem} is given by
\begin{equation}
\inf_{u \in \mathbb H} 	\mathbb F_T^{\Xi^\partial_T(\varphi_-,\varphi_+)}(u)
\end{equation}

[Lemma eq:exp-moment-XY of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:one-coordinate-Lindeberg}
Fix \(m\ge2\).  Let \(X,Y\) be real random variables satisfying
\[
 \mathbb E X^r=\mathbb E Y^r,
 \qquad r=1,\ldots,m,
\]
and
\begin{equation}
 \mathbb E e^{\left\lvertX\right\rvert/K}+\mathbb E e^{\left\lvertY\right\rvert/K}\le4.
\end{equation}
Let \(F:\mathbb R\to(0,\infty)\) be \(C^{m+1}\), fix constants \(C_1,\ldots,C_{m+1}<\infty\), and set
\begin{equation}
 a_0=a_0(K,m,C_1):=\min\{1,(2KC_1)^{-1}\},
\end{equation}
with the convention \(a_0=1\) if \(C_1=0\).  Suppose that, for some \(0<a\le a_0\),
\begin{equation}
 \abs{F^{(r)}(t)}\le C_r a^rF(t),
 \qquad t\in\mathbb R,\quad r=1,\ldots,m+1.
\end{equation}
Then
\begin{equation}
 \left\lvert\log\mathbb E F(X)-\log\mathbb E F(Y)\right\rvert\le C a^{m+1},
\end{equation}
where \(C\) depends only on \(m,K,C_1,\ldots,C_{m+1}\).

