body:
[Lem L:1.1 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Assume that $X$ satisfies (AC), (H1a), and (H1b), and additionally that $({\mathcal{E}},{\mathcal{F}})$ is transient. 

Let $B\subset E$ be a nearly Borel set of finite $0$-order capacity. Then there exists a unique  finite, positive measure $\nu_B$ with $\mathrm{supp}[\nu_B]\subset \overline{B}$ such that 
\begin{equation}
    \mathbb{P}^x[\sigma_B<\infty]=\int_E u(x,y)\nu_B(\mathrm{d} y),\quad \forall x\in  E,
\end{equation}
where $u(x,y)$ denotes the potential kernel of $X$.
In particular,
\begin{equation}
{\mathbb{P}}^x\left[\sigma_B\le t\right] \ge \emph{Cap}_{(0)}(B)\inf_{y\in \overline B}\int_0^t  p(s, x, y)\mathrm{d} s,\quad \forall t>0,x\in E.
\end{equation}

[Theorem mt1 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] Let $(\ell_N:N\ge 1)$ be the sequence such that $\ell_N = N^{4/5}$ in
dimension $1$, $\ell^3_N \log \ell_N = N^2$ in
dimension $2$, and $\ell_N = N^{4/3d}$ in dimension $d\ge 3$.  Assume
that $\lim_{N\uparrow\infty}K_N=\infty$ and
$\sup_{N\ge 1} K^2_N / \ell^d_N < \infty$.  Then, there exists a
constant ${\mathfrak c}({\boldsymbol u}^N)$, depending only on ${\boldsymbol u}^N$ and uniformly
bounded in $N$, such that
\begin{equation*}
\frac{d}{dt}\, H_N(f^N_t) \;\leq\; 
{\mathfrak c}({\boldsymbol u}^N)\,\, K^2_N
\, \big\{ H_N(f^N_t) \,+\, (N/\ell_N)^d \, \big\}
\end{equation*}
for all $t\ge 0$, $N\ge 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop strip PT formula of arXiv:2609.03152, 'Experiments with membranes, maps and sheaves'] We have
    \begin{equation}

		\PTarg{}{X}{Z}{\Gm_q}{\mathsf{T}'} = \Exp \left(-\sum_{1 \leq m < n \leq N+1} \frac{[\kappa q_{v_m}]}{[q_{v_n}] \, [\kappa^{1/2}q] \, [\kappa^{1/2}q^{-1}]} \prod_{i=m}^{n-1} Q_i \right)
	\end{equation}
    where we use the notation $[q]\coloneqq q^{1/2} - q^{-1/2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn Pure Partition Functions of arXiv:2506.01306, 'Asymptotic of Coulomb gas integral, Temperley-Lieb type algebras and pure partition functi'] The functions $\mathcal{Z}_\alpha: \mathfrak{X}_n \rightarrow \mathbb{R}^+$, indexed by link patterns $\alpha \in \mathrm{LP}(n,m)$, are called \emph{pure partition functions}. They are a collection of positive solutions to the null vector equation, subject to boundary conditions specified by their asymptotic behavior, which is determined by the link pattern $\alpha$
\begin{itemize}
    \item[\textnormal{(ASY)}] \textbf{Asymptotics:} For all $\alpha \in \mathrm{LP}_n$, $j \in \{1, \ldots, n\}$, and $\xi \in (\theta_{j-1}, \theta_{j+2})$, the following limit exists:
    \[
    \lim_{\theta_j, \theta_{j+1} \rightarrow \xi} \frac{\mathcal{Z}_\alpha\left(\theta_1, \ldots, \theta_n\right)}{(\theta_{j+1} - \theta_j)^{\frac{6 - \kappa}{\kappa}}}
    =
    \begin{cases}
        0, & \text{if } \{j, j+1\} \notin \alpha, \\
        \mathcal{Z}_{\hat{\alpha}}\left(\theta_1, \ldots, \theta_{j-1}, \theta_{j+2}, \ldots, \theta_n\right), & \text{if } \{j, j+1\} \in \alpha,
    \end{cases}
    \]
\end{itemize}
where $\hat{\alpha} = \alpha / \{j, j+1\} \in \mathrm{LP}(n-2,m-1)$ denotes the link pattern obtained from $\alpha$ by removing the link $\{j, j+1\}$ and relabeling the remaining indices as $1, 2, \ldots, n-2$.

[Proposition decC of arXiv:2608.30747, 'Compact homogeneous complex manifolds'] As a manifold, any C-space as in (equation gprime of the paper) admits the following decomposition: 
\begin{equation*}
M=G/K=\widetilde{G}/\widetilde{H}\times \underline{G}/\underline{K}\times\overline{G}, 
\end{equation*}
where $\widetilde{G}/\widetilde{H}$ is a flag manifold, $\underline{G}/\underline{K}=\underline{G}_f/\underline{K}\times T^z$ is a strict C-space and $\overline{G}$ is a compact semisimple Lie group. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 25 (\cite{LecturesonPP}, Theorem~12.7) of arXiv:2510.26216, 'A functional Breuer-Major theorem with Poisson noise'] Suppose $f_i \in L^1\left(\mathbb{R}^{a_i}\right)$ for $i \in\{1, \ldots, \ell\}$. If
        \begin{equation*}
            \int_{\mathbb{R}^{|\sigma|}}\left(\otimes_{i=1}^\ell|f_{i}|\right)_\sigma dx<\infty, \quad \forall\sigma \in \Pi(\vec{a}),
        \end{equation*}
    then we have
        \begin{equation*}
            \mathbf{E} \bigg[\prod_{i=1}^{\ell} I_{a_i}\left(f_i\right) \bigg] = \sum_{\sigma \in \Pi_{\geq 2} (\vec{a})} \int_{\mathbb{R}^{|\sigma|}} \left( \otimes_{i=1}^\ell  f_{i}\right)_\sigma dx.
        \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm_var_est of arXiv:2608.08529, 'Maximum Spanning Trees of Random Geometric Graphs With Independent Edge Weights'] Let~\(\epsilon_1,\epsilon_2\) be as in~((f_eq of the paper)) and suppose that~\(nr_n^2p_n \geq M\log{n}\) for some constant~\(M > 0.\) Also suppose that the ccdf scaling condition~((dilpax of the paper)) in Theorem~(thm_mst_max of the paper)\((b)\) holds for some constant~\(s > 3\) strictly. There is a constant~\(\gamma> 0\) such that for any~\(M > \gamma,\)~\(L = L(n) >0\) and~\(2 < s_1 < s,\) the variance~\[var(\tau_n) \leq  \gamma n (\sigma^2_{loc} + \sigma^2_{wt}),\] where
\begin{equation}
\sigma^2_{loc} :=  (nr_n^2p_n)^2 \left(L^2 + n^{4}r_n^2p_n F_c(L) + n^2F_c^{1-2/s_1}(L)\right) + n^{6}e^{-\gamma^{-1}nr_n^2p_n}
\end{equation} is the scaled contribution due to randomness in the vertex locations and \[\sigma^2_{wt} := H^2(nr_n^2p_n)\] is the scaled contribution due to randomness in edge states and weights. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 18 of arXiv:2606.03534, 'Construction and simulation of a path-valued model of dendrite development'] Define the processes
    \begin{align*}
        A_t = \int a \, d\mu_t \,, \quad I_t = \int 1-a \, d\mu_t \,,
    \end{align*}
    which count the number of active and inactive branches respectively. 
    Then $A_t$ is equal to the number of dendrite tips and $I_t$ is equal to the number of branch points.

[Lemma 24 of arXiv:2606.01832, 'MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding'] In the orange region, for $m\ge1$, it holds that
    \begin{align} 
       \frac{\partial}{\partial y}\hat{P}_{a,y,\theta}(z)   
    =\frac{-\theta z}{a+1}\hat{P}_{a,\theta y,\theta}(z),~~~~y\in A_m,
    \end{align}
    and
    \begin{align}
    \hat{P}_{a,\frac{-a}{\theta^{m}},\theta}(z)=\lim_{y\nearrow\frac{-a}{\theta^{m}}}\hat{P}_{a,y,\theta}(z).
\end{align}

