body:
[Thm theorem local bounded of arXiv:2504.19942, 'The edge-averaging process on graphs \\ with random initial opinions'] Suppose that the initial opinions $\{f_0(v)\}_{v \in V}$ are i.i.d.\ and take values in $[-1,1]$. Fix $o\in V$. Then for every $t\ge 0$   and $\varepsilon <1$, we have 
   \begin{equation}
    \mathbb P \big( |f_t(o)-\mu |\ge \varepsilon  \big) \le 3 \exp \Big( -\frac{\varepsilon ^2 \sqrt{t_*}}{12} \Big)\,,
\end{equation}
where  $t_*:=\min(t,|V|^2)$ (so $t_*=t$ if $V$ is infinite). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 16 of arXiv:2607.11756, 'Full replica symmetry breaking in the Sherrington--Kirkpatrick model'] If
\begin{equation}
 2\int_0^tq(s)\dd s=tq(t),
\end{equation}
then
\begin{equation}
 q(t)<t\theta^2.
\end{equation}

[Definition kpoint of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] For $k\in \Bbb N$, define the \textit{$k$-point motion} to be the continuous-time Markov process $\mathbf R=(R^1,\ldots,R^k)$ on $\Bbb Z^k$ with transition probabilities  given, for every $t\ge0$ and $\mathbf x = (x_1,\ldots,x_k), \mathbf y=(y_1,\ldots,y_k)\in \mathbb{Z}^k$, by
    \begin{equation}\mathsf p^{(k)}_t(\mathbf x, \mathbf y)\coloneqq \Bbb E \bigg[ \prod_{j=1}^k K_t (x_j,y_j)\bigg]\; \text{.}
    \end{equation} 
     Let $\ensuremath{\mathcal L}^{(k)} (\mathbf x,\mathbf y):= \frac{{\rm d}}{{\rm d} t}\big|_{t=0}\, \mathsf p^{(k)}_t(\mathbf x,\mathbf y) $, $\mathbf x, \mathbf y \in \mathbb{Z}^k$, denote the corresponding generator, while
    $\mathbf P_\mathbf x^{(k)}$ and $\mathbf E_\mathbf x^{(k)}$ stand for the path law and corresponding expectation when starting from $\mathbf x\in \mathbb{Z}^k$.

[Lemma 4 of arXiv:2605.07411, '\bf {A note on the equivalence of super-Poincar\'e inequality}'] Assume that the  SPI  \eqref{e1-1} holds.
Then the following conclusions are true.
\begin{itemize}
\item [(1)] Suppose that the weak Poincar\'e inequality \eqref{l3-5-1a} is true,
then $\mu$ satisfies the WLSI \eqref{e1-3}
with the rate function $\beta_{{\rm WL}}:\R_+ \to \R_+$ defined by \eqref{l3-5-2a}.
\medskip
\item [(2)] Furthermore, if we assume \eqref{l3-5-2} is true, then the SLSI \eqref{e1-2} holds
with rate function $\beta_{{\rm SL}}(s)$ defined by \eqref{l3-5-3}.
\end{itemize}

