[Lemma LEM:Error0 of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] Under the orthogonal decomposition $h(x)=h^\perp(x)+\langle Q^{\eta_L}_{x_0}, \Re h\rangle \gamma(x)$ in (equation eqn: decomp of the paper), we have that on the set $S_{Q,x_0}\cap \mathcal{K}^L_\delta$ in Proposition (PROP:REDUC of the paper)
\begin{align}
\|h \|_{L^2(\mathbb{T}_{L^2})} &\le (1+\delta_1) \|h^\perp \|_{L^2(\mathbb{T}_{L^2})} \\
|\jb{Q^{\eta_L}_{x_0},  \Re h }|& \le \delta_2  \|h^\perp \|_{L^2(\mathbb{T}_{L^2})} \\
\| h\|_{L^\infty(\mathbb{T}_{L^2}) } &\le \|h^\perp \|_{L^\infty(\mathbb{T}_{L^2})}+\delta_3 \| h^\perp\|_{L^2(\mathbb{T}_{L^2}) } \\
\|h^\perp \|_{L^2(\mathbb{T}_{L^2})} &\le \delta_4 L^{\frac 32} 
\end{align}

\noindent
for arbitrary small constants $\delta_1, \delta_2, \delta_3, \delta_4>0$.

\begin{proof}
From the condition $S_{Q,x_0}\cap \mathcal{K}^L_\delta$, we can obtain
\begin{align}
|\jb{Q^{\eta_L}_{x_0}, \Re h }| \le \frac{2}{L^\frac 32} \|h \|_{L^2}^2 \le 2 \delta \| h\|_{L^2}.

\end{align}

\noindent
This, together with Young's inequality, implies that 
\begin{align}
|h(x)|^2 &\le (1+\varepsilon)|h^\perp(x)|^2+(1+\varepsilon^{-1})|\jb{Q^{\eta_L}_{x_0}, \Re h }|^2 \gamma^2(x) \notag \\
&\le (1+\varepsilon)|h^\perp(x)|^2+2 \varepsilon^{-1} \delta^2 \|h \|_{L^2}^2 \gamma^2(x)

\end{align}

\noindent
for some small constant $\varepsilon>0$.
By integrating and choosing $0<\delta \ll \varepsilon$ sufficiently small, we have
\begin{align}
\int_{\mathbb{T}_{L^2}} |h|^2 \, \mathrm{d}x \le \frac{1+\varepsilon}{1-\overline \delta } \int_{\mathbb{T}_{L^2}} |h^\perp|^2 \, \mathrm{d}x

\end{align}

\noindent
for some small constant $\overline \delta>0$. This implies (equation hperpL20 of the paper). Furthermore, from (equation SJW1 of the paper) and (equation SJW2 of the paper), we obtain (equation hperpL21 of the paper). 

From $h(x)=h^\perp(x)+\langle Q^{\eta_L}_{x_0}, \Re h\rangle \gamma(x)$, $\|\gamma \|_{L^\infty}=O(1)$, and (equation hperpL21 of the paper), we have
\begin{align*}
\| h\|_{L^\infty} \le \| h^\perp \|_{L^\infty}+ \| \gamma\|_{L^\infty} |\langle Q^{\eta_L}_{x_0}, \Re h\rangle | \le \| h^\perp\|_{L^\infty}+\delta \|h^\perp \|_{L^2}
\end{align*}

\noindent
for some small $\delta>0$. This implies (equation hperpLinf of the paper).

From $\|h \|_{L^2}\le \delta L^\frac 32$ on the set $\mathcal{K}^L_\delta $, $\| \gamma\|_{L^\infty}=O(1)$, and (equation hperpL21 of the paper), we have 
\begin{align*}
\| h^\perp\|_{L^2} \le \|h \|_{L^2}+ \| \gamma\|_{L^\infty} |\langle Q^{\eta_L}_{x_0}, \Re h\rangle | \le  \delta L^\frac 32+ \zeta \| h^\perp\|_{L^2}
\end{align*}

\noindent
for some small $\zeta>0$. By choosing $\zeta>0$ sufficiently small, we obtain (equation hperpL2 of the paper).

\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem CNFormula of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] For any $\lambda,\mu\in \mathbb{C}$, one has 
\begin{equation}
C_{N}(\lambda,\mu)=\mu\sum_{j=0}^{N-1}\big(\int_{0}^{1}\frac{x_{t}^{j}}{j!}dy_{t}\big)\lambda^{j}.
\end{equation}

