[Theorem thm:main of arXiv:2509.02074, 'On the Kolmogorov-Feller weak law of large numbers for the Fr\'{e}chet mean on non-compact'] Suppose that Condition (C) holds. If either of the following conditions is satisfied, then $\mu_{n} \overset{\mathbb{P}}{\to} \mu$ as $n$ tends to infinity.
\begin{enumerate}
  \item[(i)] For some $\mu_0 \in M$, it holds that $\sum_{i=1}^{n} \mathbb{P}(d(X_i, \mu_0) > n) \underset{n \to \infty}{\to} 0$ and $n^{-2}\sum_{i=1}^{n}\mathbb{E}[d^2\{\overline{X_{n,i}}(\mu_0), \mu_0\}] \underset{n \to \infty}{\to} 0$;

  \item[(ii)] The $X_i$'s are identically distributed and for some $\mu_0 \in M$, $n\mathbb{P}(d(X_1, \mu_0) > n) \underset{n \to \infty}{\to} 0$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 (Gordin decomposition) of arXiv:2607.04943, '\textbf{Approximation of Random Differential Equations Driven by Physical Brownian Motion '] Let $(Y_n)_{n\in\mathbb{Z}}$ be a strictly stationary sequence, $\mathcal{G}_n:=\sigma(Y_k:k\leq n)$. Assume that
		\begin{equation}
			\E Y_0=0,\quad\E |Y_0|^2<\infty, \quad\sum_{k=0}^{\infty} \|\E(Y_{n+k}|\mathcal{G}_n)\|_2<\infty. 
		\end{equation}
		Then there exist a strictly stationary random sequence $(d_n)_n$ adapted to $(\mathcal{G}_n)_n$ and a strictly stationary random sequence $(Z_n)_n$, such that
		\begin{equation*}
			Y_n=d_{n}+Z_n-Z_{n+1},\quad n\in\mathbb{Z}.
		\end{equation*} 
		Besides, $(d_n)$ is a martingale difference sequence, that is,
		\begin{equation*}
			\E(d_{n+1}|\mathcal{G}_n)=0,\quad n\in\mathbb{Z}.
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:fik-is-mostly-intuitionistic of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] {balbiani_natural_2024}}]  \leavevmode
  (1) $\textbf{FIK}$ enjoys DP.
  (2) $\textbf{FIK} + \varphi \lor \neg \varphi = \textbf{K}$.\\
  (3) $\textbf{FIK} \nvdash \textsf{Dual}_\Box$ and $\textbf{FIK} \nvdash \textsf{Dual}_\Diamond$.
  \begin{proof}
    (1) It is easily proven by a semantical argument, similarly to Proposition (prop:ik-enjoys-dp of the paper).
    (2) As $\textbf{WK} \vdash \Box \varphi \to \neg \Diamond \neg \varphi$,
    it suffices to show that $\textbf{FIK} + \varphi \lor \neg \varphi \vdash \neg \Diamond \neg \varphi \to \Box \varphi$ (see Proposition (prop:ik-plus-em-is-k of the paper)).
    The following derivation proves it:
    \begin{center}
      \scalebox{0.75}{
        \AxiomC{$ $}
        \UnaryInfC{$\bot \to \Box \varphi$}
        \UnaryInfC{$(\Diamond \neg \varphi \to \bot) \to (\Diamond \neg \varphi \to \Box \varphi)$}

        \AxiomC{$ $}
        \UnaryInfC{$\neg \varphi \lor \varphi$}
        \RightLabel{\scriptsize{$\textsf{M}_\Box$, $\textsf{N}_\Box$}}
        \UnaryInfC{$\Box(\neg \varphi \lor \varphi)$}

        \AxiomC{$ $}
        \RightLabel{\scriptsize{$\textsf{wCD}$}}
        \UnaryInfC{$\Box(\neg \varphi \lor \varphi) \to ((\Diamond \neg \varphi \to \Box \varphi) \to \Box \varphi)$}

        \RightLabel{\scriptsize{MP}}
        \BinaryInfC{$(\Diamond \neg \varphi \to \Box \varphi) \to \Box \varphi$}

        \RightLabel{\scriptsize{Syll.}}
        \BinaryInfC{$(\Diamond \neg \varphi \to \bot) \to \Box \varphi$}
        \UnaryInfC{$\neg \Diamond \neg \varphi \to \Box \varphi$}
        \DisplayProof
      }
    \end{center}
    (3) Follows from Proposition (prop:ik-non-duality of the paper) and $\textbf{FIK} \subsetneq \textbf{IK}$.
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:hidden-parameter of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] The \emph{hidden purification parameter} is
\begin{equation}
x_k := a_3\,\rho_\star^{2k} = \frac{c_3^2}{c_2^2}\left(\frac{\lambda_3}{\lambda_2}\right)^{2k}.
\end{equation}

[Defn def:reflection-positivity of arXiv:2609.01499, 'On the rigidity of sloped height functions in $d\ge 3$ \\ and non-crossing surfaces'] We say a measure is vertex reflection positive if the following holds. For every $\tau$ that is a reflection across a coordinate line of the torus, and every function $f$ measurable with respect to the configuration on one side of the line,
    \begin{align*}
        \nu_{\Lambda}^{\text{per}}(f \cdot \tau f) \ge 0\,.
    \end{align*}

[Lem strip to rectangle of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Let $\beta>\beta_c$. For every $h>0$ sufficiently large, there exist $\delta,c_2>0$ such that, for every $L$ large enough,
\begin{equation}
\Psi^{0,h}_{\mathcal R(L,\delta L),\beta}[\partial^{{\rm bot}} \mathcal R(L, \delta L) \longleftrightarrow\partial^{{\rm top}} \mathcal R(L, \delta L)] \geq 1 - e^{-c_2 L^{d-1}}. 
\end{equation}

[Proposition prop:necessary-rigid of arXiv:2510.18392, 'Hyperuniformity of random measures, transport and rigidity'] Assume the spectral density $    \mathsf s$ satisfies for some $ c,p,\varepsilon >0$:\begin{itemize}
\item $    \mathsf s$ has finitely many zeros $ u_{ 1},\dots ,u_{ m}\in \mathbb{R}^{ d}$ and they have finite order, i.e. 
\begin{align*}
 \int_{B(u_{ i},\varepsilon )}\frac{ \|u-u_{ i}\|^{ p}}{   \mathsf s(u)}du<\infty 
\end{align*}
\item $    \mathsf s$ does not vanish too fast at $ \infty $: for $ u \notin \bigcup _{ i}B(u_{ i},\varepsilon )$, $ 
    \mathsf s(u)\geqslant c(1 + \|u\|)^{ -p} $.
\end{itemize}
Then $ \mathsf{M}$ is not maximally rigid on $ B_{ R}$ for $ R>0$, and for $ k\in \mathbb{N}$, $ \mathsf{M}$ is not linearly $ k$-rigid if  (equation eq:simple-condition-k-rigidity of the paper) does not hold. (Proof in the paper; no proof environment follows the statement in the TeX.)

