[Proposition 3 (Regularity of the coefficient fields) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] Suppose Assumptions~\ref{assump:mdp}, \ref{assump:stable_kernels}, and \ref{assump:stepsizes} hold. Then, for every $n\ge0$, $\theta_n^\mrm U,\theta_n^\mrm N\in\Theta$. Moreover, the coefficient fields are also Lipschitz with
\begin{equation}
        [\theta_n^{\mrm U}]_{\rho}
        \le L_{0,\rho} + \frac{2\alpha_{\mrm U} L_{\kappa,\rho}}{1-\gamma}
        \log\crbk{\frac{n+n_0^{\mrm U}}{n_0^{\mrm U}}},

\end{equation}
and
\begin{equation}
        [\theta_n^{\mrm N}]_{\rho}
        \le
        L_{0,\rho}+
        \frac{2\alpha_{\mrm N} L_{\kappa,\rho}}{1-\gamma} \crbk{\frac{1}{c_\wedge}+\frac{1}{c_\wedge^2}}
        \log\crbk{\frac{n+n_0^{\mrm N}}{n_0^{\mrm N}}}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition defi:sol of arXiv:2511.12692, 'A stochastic flow approach to De Giorgi--Nash--Moser estimates for SPDE\lowercase{s} with '] Let Assumptions (ass:quasilinear of the paper) and (ass:quasilinear_data of the paper) be satisfied,
 $\sigma$ be a stopping time and 
$
U:(0,\sigma)\times \Omega\to W^{1,q}(\mathbb{T}^d)
$
be progressively measurable. 
\begin{enumerate}[{\rm(1)}]
\item We say that $(U,\sigma)$ is a \emph{local $(p,\kappa,q)$-solution} to (equation eq:SPDE_quasi of the paper) if there exists a sequence of stopping times $(\sigma_j)_{j\geq 1}$ for which $\sigma_j \to\sigma$ a.s. and for all $j\ge 1$
\begin{align}

U\in L^p(0,\sigma_j,w_{\kappa};W^{1,q}(\mathbb{T}^d))\cap C([0,\sigma_j];B^{1-2\frac{1+\kappa}{p}}_{q,p}(\mathbb{T}^d)), \qquad \text{a.s.,}
\end{align}
and
\begin{align}

U(t) - U_0 =\int_0^t \nabla \cdot (A(\cdot,U)\cdot \nabla U)\,\mathrm{d} s 
+\sum_{n\geq 1} \int_0^t (B_n \cdot\nabla) U\,\mathrm{d} w^n_s,\qquad t\in [0,\sigma_j].
\end{align}
\item We call a local $(p,\kappa,q)$-solution $(U,\sigma)$ to (equation eq:SPDE_quasi of the paper) \emph{unique} if for any other local $(p,\kappa,q)$-solution $(V,\tau)$ to (equation eq:SPDE_quasi of the paper) it holds a.s.\ $U=V$ on $[0,\sigma\wedge \tau )$.
\item We call a local $(p,\kappa,q)$-solution $(U,\sigma)$ to (equation eq:SPDE_quasi of the paper) \emph{maximal} if for any other local $(p,\kappa,q)$-solution $(V,\tau)$ to (equation eq:SPDE_quasi of the paper) it holds $\tau\leq \sigma$ a.s.\ and $U=V$ on $[0,\sigma\wedge \tau )$.
\item We call a local $(p,\kappa,q)$-solution $(U,\sigma)$ to (equation eq:SPDE_quasi of the paper) \emph{global} if  a.s.\ $\sigma=\infty$. In this case, we simply write $U$ instead of $(U,\sigma)$.
\end{enumerate}

[Proposition prop: bdry UV stable of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] There exists $c,C>0$ such that for every $T \in (0,\infty]$ and every $f \in C^\infty(\mathbb T^2)$,
\begin{equation}
	\exp(-C-c\|f\|_{H^{-1/2+\kappa_0'}_z}^2 ) \leq \mathcal Z^0_T(f) \leq \exp(C+c\|f\|_{H^{-1/2+\kappa_0'}_z}^2). 
\end{equation}

[Ppn 211 (quenched second moment bounds for $\vY$ and $\vY^\frozen$) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] For all $0\le s<t\le1$ we have
    \[
    \sum_{\sigma\in\{\RomII,\RomIII,\Ising\}}
    \frac{\bE[(Y^\sigma(t)-Y^\sigma(s))^2]}{(t-s)}
    \le L^{O(1)} \bigg\{
    (\MAX_N)^2+ \frac{(\SMAX_N)^2\BUCKETS}{N\delta}
