[Lemma 23 (Fourier estimate) of arXiv:2608.06576, 'The Resultant Distribution Method: Universality for $p$-adic Random Matrices and Polynomia'] Let $\xi$ be an $\epsilon$-balanced $\F_p$-valued random variable.
Then, for every $a\in\F_p^\times$,
\begin{equation}

\left|\E e_p(a\xi)\right|\leq
\exp\left(-\frac{\epsilon}{p^2}\right).
\end{equation}

[Lemma WPD-NHS-AA of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] For any $N \in \left\{ {0,1, \cdots ,10} \right\}$ and $t \in \mathop  \cap \limits_{j = 0}^{q} \left[ {0,{\mathfrak{t}_j}} \right] \cap \left[ {{t_k},{t_{k + 1}}} \right)$, there exists a real number $\alpha \in \left( {\frac{\beta }{{b}},\beta } \right)$ such that the backward flow ${{\tilde \Phi }_k}\left( {t,x} \right)$ and the Lagrangian flow ${{\tilde X}_t}$ satisfy
\begin{equation}
{\left\| {\nabla {{\tilde \Phi }_k}} \right\|_N} + {\left\| {{{\left( {\nabla {{\tilde \Phi }_k}} \right)}^{ - 1}}} \right\|_N}  \lesssim \lambda _q^N \lambda _{q + 1}^{ - \alpha }   ,
\end{equation}
\begin{equation}
{\left\| {D{{\tilde X}_k}} \right\|_N} \lesssim  \max \left\{ {1,\lambda _q^N \lambda _{q + 1}^{ - \alpha }} \right\}  ,
\end{equation}
\begin{equation}
{\left\| {{{\bar D}_{t,\Gamma }}\nabla {{\tilde \Phi }_k}} \right\|_N} + {\left\| {{{\bar D}_{t,\Gamma }}{{\left( {\nabla {{\tilde \Phi }_k}} \right)}^{ - 1}}} \right\|_N} \lesssim \delta _q^{\frac{1}{2}}\lambda _q^{N + 1}   ,
\end{equation}
\begin{equation}
{\left\| {{\partial _{tt}}{{\tilde \Phi }_k}} \right\|_N} \lesssim \delta _q^{\frac{1}{2}}\lambda _q^{N + 1}  ,
\end{equation}
and
\begin{equation}
{\left\| {{\partial _{tt}}{{\left( {\nabla {{\tilde \Phi }_k}} \right)}^{ - 1}}} \right\|_N} \lesssim \delta _q^{\frac{1}{2}} \lambda _q^{N + 3}   ,
\end{equation}
where ${{\bar D}_{t,\Gamma }} \triangleq {\partial _t} + {{\bar v}_{q,\Gamma }} \cdot \nabla $ is the material derivative corresponding to ${{\bar v}_{q,\Gamma }}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 (Poisson point process) of arXiv:2604.11434, 'Maxima of stationary systems of randomly time-changed L\'evy particles'] Let $(\mathcal{X}_{}, \mathcal{C}, \mu)$ be a measure space satisfying $\{x\}\in \mathcal{C}$ for all $x\in \mathcal{X}$ and $\mu(\mathcal{X})=\infty$.
  A random collection $\{U^{(i)}\}_{i\in\NN}
  $ of points in $\mathcal{X}$ is called Poisson point process having intensity measure $\mu$ if for every $m\in\NN$ and corresponding disjoint sets $C_1,\ldots,C_m \in \mathcal{C}$ and non-negative (including $+\infty$) integers $r_1,\ldots,r_m $ it holds that
  \begin{align*}
    \PP
    \left[
    \sum_{i\in\NN}
    \ind\{U^{(i)}\in C_j\}
           \
    =
    \
    r_j
    \qquad\text{for all}\
    j\in \{1,\ldots,m\}
    \right]
    \ = \
    \prod_{j=1}^m
    p(\mu(C_j),r_j)
    \,,
  \end{align*}
  where
  \begin{align*}
    p(\lambda,k)
    \ = \
    \begin{cases}
      \frac{\lambda^k \exp(-\lambda)}{k!}
      &\qquad\text{if}\qquad \lambda <\infty\quad \text{and}\quad  k<\infty\,,\\
      1
      &\qquad\text{if}\qquad \lambda =\infty\quad \text{and}\quad  k=\infty
      \qquad\text{or}\qquad \lambda =0 \quad \text{and}\quad  k=0\,,
      \\
      0&\qquad\text{elsewhere}.
    \end{cases}
  \end{align*}

