[Proposition 9 (Uniform Ginibre power bound) of arXiv:2608.20998, 'Free-Probability Kernels for Zero-Rollout Hyperparameter Selection in Reservoir Computing'] Let
\[
A_n
=
(1-\alpha)I_n
+
\alpha\frac{\sigma_r}{\sqrt n}G_r^{(n)}
\]
and assume $\sigma_r<1$. For any
$1<R<\sigma_r^{-1}$, set
$q_R:=1-\alpha+\alpha\sigma_rR<1$.
Almost surely, there are finite random constants $C_R$ and $N_R$ such
that, for all $n\geq N_R$ and $m\geq0$,
\begin{equation}
\lVert A_n^m\rVert
\leq
C_Rq_R^m.

\end{equation}
Consequently, for bounded input histories,
\begin{equation}
x_t^{(\infty)}
:=
\alpha\sum_{k=0}^{\infty}
A_n^kW_{\rm in}^{(n)}u_{t-1-k}

\end{equation}
is well defined for all sufficiently large $n$, and
\begin{equation}
\limsup_{n\to\infty}
\frac1{\sqrt n}
\left\|
x_t^{(\infty)}-x_t^{(L)}
\right\|
\leq
\frac{\alpha C_R\sigma_{\rm in}U}
{\sqrt{d_{\rm in}}(1-q_R)}
q_R^{L+1}

\end{equation}
almost surely.

[Theorem 4 (\cite{S11}) of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] For any $\alpha\geq 1$ and $\delta>0$, $L_G^{\alpha+\delta}(\Omega_T)\subset L_{\mathcal{E}}^{\alpha}(\Omega_T)$. More precisely, for any $1<\gamma<\beta:=(\alpha+\delta)/\alpha$ and $\gamma\leq 2$, we have
	\begin{displaymath}
		\|\xi\|_{\alpha,\mathcal{E}}^{\alpha}\leq \gamma^*\left\{\|\xi\|_{L_G^{\alpha+\delta}}^{\alpha}+14^{1/\gamma}
		C_{\beta/\gamma}\|\xi\|_{L_G^{\alpha+\delta}}^{(\alpha+\delta)/\gamma}\right\},\quad \forall \xi\in L_{ip}(\Omega_T),
	\end{displaymath}
	where $C_{\beta/\gamma}=\sum_{i=1}^\infty i^{-\beta/\gamma}$ and $\gamma^*=\gamma/(\gamma-1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:double-well of arXiv:2411.01364, 'Global Dynamics of Granular Media Equations via Stochastic Order'] Consider the following one-dimensional McKean-Vlasov SDE,
\begin{equation}
\mathop{}\!\mathrm{d} X_t=-\left[X_t(X_t-1)(X_t+1)+\theta\left(X_t-\mathbf E [X_t]\right)\right]\mathop{}\!\mathrm{d} t+\sigma(X_t)\mathop{}\!\mathrm{d} B_t.
\end{equation}
If the parameter $\theta$ and the Lipschitz function $\sigma\colon\mathbb R\to\mathbb R$ satisfy
\begin{equation}
    \theta\geq\frac{27(9+\sqrt{17})}{128},\quad 0<\inf_{x\in\mathbb R}\sigma^2(x)\leq \sup_{x\in\mathbb R}\sigma^2(x)<\frac{51\sqrt{17}-107}{256},
\end{equation}
and let $r=\frac{9-\sqrt{17}}{8}$, then
\begin{enumerate}[label=\textnormal{(\roman*)}]
\item There are exactly three invariant measures, $\nu_{-1}, \nu_0, \nu_1\in\mathcal P_{\8}(\mathbb R)$ with $\nu_{-1}<_{\mathrm{st}}\nu_0<_{\mathrm{st}}\nu_1$;
\item For all bounded sets $B\subset\mathcal P_2(\mathbb R)$, $\mathcal W_2(P_t^*B,[\nu_{-1},\nu_1])\to0$ as $t\to\8$;
\item There are a decreasing connecting orbit from $\nu_0$ to $\nu_{-1}$ and an increasing connecting orbit from $\nu_0$ to $\nu_1$;
\item There hold $\nu_{-1}\in B(\delta_{-1},r)$, $\nu_1\in B(\delta_1,r)$, and
\[
\mathcal W_2(P_t^*\mu,\nu_{-1})\to0\ \text{ as $t\to\8$ for all $\mu\in\bigcup_{a\leq0}B(\delta_{-1+a},r)$},
\]
\[
\mathcal W_2(P_t^*\mu,\nu_1)\to0\ \text{ as $t\to\8$ for all $\mu\in\bigcup_{a\geq0}B(\delta_{1+a},r)$}.
\]
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

