[Theorem thm:moderate.dev.FPP of arXiv:2411.02046, 'Speed of Convergence and Moderate Deviations of FPP on Random Geometric Graphs'] Consider first-passage percolation as in Theorem~(thm:speed.FPP of the paper), under the same assumptions as in that theorem. There exist finite constants~$\upvarphi > 0$ and~$C > 0$ such that, for~$x \in \R^d$ with~$\|x\|$ large enough,
	\begin{equation}
		\frac{\|x\|}{ \upvarphi} \leq  \E\left[ T(x) \right]   \leq \frac{\|x\|}{ \upvarphi} + C \sqrt{\|x\|} \log\big(\|x\|\big)
	\end{equation}
	and
    \begin{equation} 
    \operatorname{Var} T(x) \le C\|x\| \log \big(\|x\|\big).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem complete-to-residue of arXiv:2608.26876, 'Local Bousfield classes via homological support'] Let $\cat B \in \Spc^h(\cat T^c)$ be such that $\cat P\coloneqq\pi(\cat B)\in \Spc(\cat T^c)$ is weakly visible. The localization $\cat T\to \LKBT$ induces a canonical functor
	\begin{equation}
		(\cat T_{\cat P})_{\cat P}^\wedge \to \LKBT.
	\end{equation}
	This is an equivalence if and only if
	\begin{equation}
		\cat P \in \Supp(t) \Longrightarrow \cat B \in \Supphnaive(t)
	\end{equation}
	for all $t\in \cat T$.

[Lemma corotLIL0 of arXiv:2607.28167, 'Temporal properties of the stochastic fractional heat equation with rough dependence in sp'] Choose and fix   $x\in \mathbb R$.   Then,
        \begin{itemize}
        \item[(a).] (Khinchin's LIL)
        \begin{equation}
        \begin{split}
        \lim_{r \to 0}  \sup_{ 0<t<r}  \frac{|v(t, x)|}{t^{\widetilde{H}/2}\sqrt{2 \log\log(1/t)}}=  \widetilde\kappa, \ \ \ \text{a.s.},
        \end{split}
                 \end{equation}
where $\widetilde{H}=\frac{\alpha+2H-2}{\alpha}$ and $  \widetilde\kappa$ is given by  (equation eq con kappa1 of the paper).
            \item[(b).]  (Chung's LIL)
       \begin{equation}
\begin{split}
\liminf_{\varepsilon \to 0}\sup_{0\le r\le \varepsilon}\frac{|v(r, x)|}{(\varepsilon / \log\log(1/\varepsilon))^{\widetilde{H}/2}}
= \left( \frac{ \Gamma(2\widetilde{H})}{ \Gamma(\widetilde{H})} \right)^{\frac12}
\lambda_{\widetilde{H}}^{\widetilde{H}/2}, \quad \text{a.s.}
\end{split}
\end{equation}
        where $\widetilde{H}=\frac{\alpha+2H-2}{\alpha}$ and $\lambda_H$ is the small ball constant of a  fBm with index $\frac{\widetilde{H}}{2}$
        (see, e.g., [LS01*]).
      \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2605.13518, 'The inertial It\^{o} drift and its applications to particle collision'] Assume Hypothesis \ref{hyp}, and for every $\a \in\,[0,+\infty]$, denote by  $x^\alpha$  the unique solution of the problem
\begin{equation}

\begin{array}{l}
\ds{dx^\alpha(t)=(\gamma^{-1}b)(x^\alpha(t))+f_\alpha(x^\alpha(t))\,dt+(\gamma^{-1}\sigma)(x^\alpha(t))\, B\,dw(t),}	\end{array}
	\end{equation}
where $f_\alpha:\mathbb{R}^d\to\mathbb{R}^d$ is the vector field \begin{equation}
\begin{array}{l}
\ds{	[f_\alpha(x)]_{i}=\partial_l\,\gamma^{-1}_{i,j}(x)	[\alpha N_\alpha(x)]_{l,j}+\partial_l\,(\gamma^{-1}_{i,j}\sigma_{j,k})(x)A^{-1}_{k,h}[L_\alpha(x)]_{l,h},}
\end{array}
\end{equation}
and  $N_\alpha \in\,\mathbb{R}^{d\times d}$ and $L_\alpha\in\,\mathbb{R}^{d\times n}$ are the matrices 
\begin{equation}

L_{\alpha}(x):=\frac 1\alpha \int_0^\infty e^{-\frac 1\alpha \gamma(x)t}\sigma(x)Me^{-A^\star t}\,dt,	
\end{equation}
and
\begin{equation}

N_\alpha(x):=\int _0^\infty e^{-\gamma(x) t}\,[L_{\alpha}(x)\, \sigma^\star(x)+\sigma(x) L^\star_{\alpha}(x)]\,e^{-\gamma^\star(x)t}\,dt,	
\end{equation}
with
\begin{equation}

M:=\int_0^{+\infty} e^{-A s}BB^\star e^{-As}\,ds.	
\end{equation}
Then, if
\[\lim_{\epsilon\to 0}\frac{\mu(\epsilon)}{\epsilon}=\alpha,\]
for every $\eta>0$ and $T>0$ we have
\begin{equation}

\lim_{\e\to 0}\mathbb{P}\left(	\sup_{t \in\,[0,T]}|x_{\epsilon}(t)-x^\alpha(t)|>\eta\right)=0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 (Composition law) of arXiv:2609.03881, 'Eulerian insertion operators and an Eulerian form of the Pieri rule'] For independent indeterminates \(z\) and \(v\),
\begin{equation*}
 \G(z)\G(v)=\G(z+v-\delta zv).
\end{equation*}

[Proposition prop.L2FluxErr of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] We have the following estimates for the two-scale expansion $\widetilde{G}_\lambda$:
		\begin{enumerate}
			\item [gu2025relaxation] There exists a finite positive constant $C(d, c_{-},c_{+})$ such that 
			\begin{equation*}
				\norm{\widetilde{G}_\lambda-\overline{G}_\lambda}^2_{L^2}\leqslant C3^{2m}\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}.
			\end{equation*}
			\item [gu2025relaxation] There exists an exponent $\alpha(d,c_{-},c_{+}, \mathbf{r}) > 0$ and a finite positive constant $C(d,c_{-},c_{+}, \mathbf{r},\rho)$ such that the following estimate holds for any $V\in L^2$:
			\begin{equation*}
				\left|\expec{V,-\mathcal{L}\widetilde{G}_\lambda+{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}\right|\leqslant C\left\langle V,-{\overbracket[1pt][-1pt]{\mathcal{L}}} V \right\rangle^{\frac{1}{2}}\left(3^{-\alpha m}\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}^{\frac{1}{2}}+3^m \expec{-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}^{\frac{1}{2}}\right).
			\end{equation*}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Local well-posedness) of arXiv:2608.27054, 'GLOBAL WELL-POSEDNESS FOR THE 2D STOCHASTIC HYPOVISCOUS NAVIER-STOKES EQUATIONS'] Let $\gam \in (\frac 12, 1]$, $s\in [\gam, 2\gam)$ and suppose that Assumption \ref{ass:X0X1_g} holds. Furthermore, assume that $p,q\in (2,\infty)$ satisfy
        \begin{equation*}
        \max\{|s-1|, 3\gam-s-1\}<\frac dq < 4\gam-s-1\quad \text{ and }\quad \frac{2}{p}+\frac{d}{q\gam}\leq 4-\frac{s+1}{\gam}.
    \end{equation*}
    Moreover, set $\kappa:=-1 + \frac{p}{2}\big(4-\gam^{-1}(\frac{d}{q}+s+1)\big)$. Then for all $u_0 \in L^0_{\mc{F}_0}(\Om; \BB_{q,p}^{\frac{d}{q}+1-2\gam}(\T^d;\RRd))$ there exists a unique maximal solution $(u,\sigma)$ to \eqref{eq:abstract_eq} satisfying $\sigma>0$ a.s. and
    \begin{align*}
        u&\in H^{\theta,p}_{\loc}([0,\sigma),w_{\kappa}; \Hs^{-s+2\gam(1-\theta),q}(\T^d; \RRd)) \,\,\text{a.s. for all }\theta\in [0,\tfrac 12),\\
        u&\in C([0, \sigma); \BB_{q,p}^{\frac{d}{q}+1-2\gam}(\T^d; \RRd))\,\, \text{ a.s.}
    \end{align*}
    The solution $(u,\sigma)$ instantaneously regularises in time and space:
\begin{align*}
u&\in L^r_\loc((0,\sigma);\Hs^{\gam,\zeta}(\T^d;\RRd))
\quad\text{a.s.}, &&r,\zeta\in(2,\infty),\\
u&\in C^{\theta-\eps}_\loc((0,\sigma);
\Hs^{-\gam+2\gam(1-\theta),\zeta}(\T^d;\RRd))
\quad\text{a.s.}, &&
\theta\in(0,\tfrac 12),\ \eps\in(0,\theta),\ \zeta\in(2,\infty).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma3 of arXiv:2411.01731, '$L^2$-Wasserstein contraction of modified Euler schemes for SDEs with high diffusivity and'] Assume   (equation EY* of the paper) and
 suppose further that  there exist constants $ \lambda_b^\star, C_b^\star>0$ such that for any $\delta\in[0,1] $ and $x\in\mathds R^d,$
\begin{align}
\<\pi^{(\delta)}(x),b^{(\delta)}(\pi^{(\delta)}(x))\>\le   C_b^\star- \lambda_b^\star|\pi^{(\delta)}(x)|^2.
\end{align}
 Then, for any $p>0$,
 there exists a constant  $  C^*(p)>0$ such that for all $\delta\in (0,\delta_\star]$ and $n\ge0,$
\begin{equation}
\mathbb E\big(|X^{\delta}_{n\delta}|^{p}\big|\mathscr F_0\big)\le  C^*(p)(1+   d^{\frac p2}) +  \text{\rm{e}}^{-\frac{p\lambda_b^\star  n\delta}{4(3+\lfloor p\rfloor)} }|X^\delta_0|^p,
\end{equation}
in which $\delta_\star:=\big( \lambda_b^\star/(2\psi^2_2(1))\big)^{\frac{1}{1-2\theta}}\wedge(1/\lambda_b^\star)\wedge 1$ with $\psi_2(\cdot)$ being introduced in (equation EY* of the paper).
Consequently,  for each fixed $\delta\in(0,\delta_\star],$  $(X_{n\delta}^{\delta})_{n\ge0}$ possesses an   IPM  $\pi^{(\delta)}_\infty$  satisfying
\begin{align}
\pi_\8^{(\delta)}(|\cdot|^p)\le  C^*(p)(1+   d^{\frac p2}).
\end{align}

