[Lemma 28 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Fix $r>0$ and an even number $n=2N$. 
For $\bs{\alpha}, \bs{\beta}\in\LX_n$, we write $\bs{x}=\ee^{\ii\bs{\alpha}}$ and $\bs{y}=\ee^{\ii\bs{\beta}-r}$.  
We denote by $\Pcro{1}$ the law of annulus $\SLE_4(\LZcro{1})$ in $(\A_r; x_1, y_1)$. 
Suppose $\gamma^1$ is the annulus Loewner chain whose law is the same as tilting $\Pcro{1}$ by the local martingale
\begin{align}
M_t(\LZcro{1}; \LZann{n})=\ee^{\frac{n-1}{4}t}
	\prod_{j=2}^{n}
	\left(\mathfrak{\covmap}_t'(\alpha_j)
	\mathfrak{\covmap}_t'(\beta_j+\ii r)\right)^{\frac14}
	\frac{\LZann{n}\left(r-t;\zeta_t,\mathfrak{\covmap}_t(\alpha_2),
		\ldots,\mathfrak{\covmap}_t(\alpha_n),
		\Re\mathfrak{\covmap}_t(\bs{\beta}+\ii r)\right)}
	{\LZcro{1}\left(r-t;\zeta_t,
		\Re\mathfrak{\covmap}_t(\beta_1+\ii r)\right)},
\end{align}
where $t<T$ and $T$ is the life-time of $\gamma^1$, i.e. the minimum between $r$ and swallowing time of points $\{x_2, x_n\}$.
\begin{itemize}
\item The driving function $\zeta:[0,r)\to \R$ for $\gamma^1$ satisfies the SDE system
\begin{equation}
	\begin{cases}
		\displaystyle \ud \zeta_t = 2 \ud B_t + 4 \partial_{\alpha_1} \log \LZann{n}(r-t; \zeta_t, U_t^2,\ldots, U_t^n,V_t^1,\ldots, V_t^n) \ud t, \qquad \zeta_0=\alpha_1, \\
		\displaystyle \ud U_t^j = H_1(r-t; U_t^j-\zeta_t)\ud t, \qquad U_0^j=\alpha_j,\quad 2\le j\le n,\\
		\displaystyle \ud V_t^j = H_3(r-t; V_t^j-\zeta_t)\ud t, \qquad V_0^j=\beta_j,\quad 1\le j\le n,
	\end{cases}
\end{equation}
where $\{B_t\}_{t\ge 0}$ is a standard Brownian motion.
\item The Dirichlet GFF $\Gamma$ in annulus $\A_r$ can be coupled with $\gamma^1$ so that $\gamma^1$ is a  level line of $\Gamma+\varphiann{n}$ starting from $x_1$.
\end{itemize}

