body:
[Lemma 165 (Euler completion under a trace clock) of arXiv:2608.04993, '2608.04993'] Let
$\varnothing\ne\cP\subset\mathfrak S_{\Lambda,0}^{0,T}(H)$, and let
\[
 b:[0,T]\times\mathbb R^m\to\mathbb R^m,
 \qquad
 \sigma:[0,T]\times\mathbb R^m\to\mathcal L(H,\mathbb R^m)
\]
be deterministic and continuous.  Suppose that, for constants $L,K<\infty$,
\begin{align}
 &|b(t,z)-b(t,z')|
  +\|\sigma(t,z)-\sigma(t,z')\|_{\rm op}
  \le L|z-z'|,
 \\
 &|b(t,z)|+\|\sigma(t,z)\|_{\rm op}
  \le K(1+|z|).

\end{align}
For every deterministic $(s,y)$, every $q\ge2$, and every sequence of
partitions $\pi_n$ of $[s,T]$ with $|\pi_n|\to0$, the raw maps
$Y^{\pi_n;s,y}$ from \eqref{eq:raw-Euler-starting-pair} converge in
$\mathbb S_{\cP}^q$ to a limit $Y^{s,y}$ independent of the partitions.
If
\begin{equation}
 H_u^{\pi;s,y}
 :=\one_{(s,T]}(u)\,
 \sigma\bigl(\ell_\pi(u),Y_{\ell_\pi(u)}^{\pi;s,y}\bigr),
\end{equation}
then these integrands converge in $\mathbb H_{\cP}^q$ to the unique element
$\Sigma^{s,y}$ satisfying
\begin{equation}
 j_P\Sigma^{s,y}
 =\one_{(s,T]}\sigma(\cdot,\pi_PY^{s,y})
 \quad\text{in }\mathbb H^q(P),
 \qquad P\in\cP.
\end{equation}
The pair $(Y^{s,y},\Sigma^{s,y})$ solves
\begin{equation}
 Y_t^{s,y}
 =y+\int_s^{t\vee s}b(u,Y_u^{s,y})\,\dd u+I_t(\Sigma^{s,y})
 \quad\text{in }\mathbb S_{\cP}^q,
\end{equation}
and is the unique pair with the modelwise prescription
\eqref{eq:Euler-limit-modelwise-integrand}.  Under each $P\in\cP$ its
projection is the unique classical strong It\^o solution.

Moreover,
\begin{equation}
 Y^{s,y}\in
 \mathbb L_{\cP}^q\bigl(C([0,T];\mathbb R^m)\bigr),
\end{equation}
and, for every $R<\infty$, there are constants depending only on the displayed
parameters such that
\begin{align}
 \sup_{\substack{s\in[0,T]\\|y|\le R}}
 \|Y^{s,y}\|_{\mathbb S_{\cP}^q}
 &\le C_{q,R},
 \\
 \|Y^{s,y}-Y^{r,z}\|_{\mathbb S_{\cP}^q}
 &\le C_{q,R}\bigl(|s-r|^{1/2}+|y-z|\bigr),
 \qquad s,r\in[0,T],\quad |y|,|z|\le R.

\end{align}
The conclusions in
\eqref{eq:Euler-section-regular-completion}--\eqref{eq:Euler-section-parameter-increment}
also hold for every $1\le q<2$.  In that range, define
$(Y^{s,y},\Sigma^{s,y})$ as the image of the exponent-two pair under the
canonical contractions of
\Cref{cor:common-integral-exponent-compatibility}.  Then
\eqref{eq:common-integral-exponent-compatibility} gives
\eqref{eq:Euler-common-solution-pair} in $\mathbb S_{\cP}^q$, and
Lyapunov's inequality gives the stated bounds.  These lower-exponent pairs are
the limits of the same elementary Euler sequence and are therefore compatible
across all exponents.

