[Lemma lem:dgt4-path-survival of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] Let $T>0$, $\kappa>0$, and $n_R\coloneqq\lfloor R^2T\rfloor$, and suppose that for every
	$\varepsilon\in(0,1)$, as $R\to\infty$,
	\begin{equation}
		\max_{\lceil\varepsilon n_R\rceil\leq m\leq n_R}\left\{\left|\frac{m\mathbb{P}(J(0)>\mathbb{E} u_{m-1}(0))}{G(0,0)\kappa}-1\right|+m\mathbb{P}\bigl(\{u_m(0)=0\}\mathbin{\triangle}\{J(0)>\mathbb{E} u_{m-1}(0)\}\bigr)\right\}\longrightarrow0\, .
	\end{equation}
	Then
	\begin{equation}
		R^{-2}\sum_{j=0}^{n_R-1}\mathbf E_0\left|\mathbb{P}(S_{n_R,j}(X)=1\mid X)-\left(1-\frac{j}{R^2T}\right)^\kappa\right|\longrightarrow0\, .
	\end{equation}
	Moreover, there is $C<\infty$ so that for each $\delta\in(0,T)$ there are $\varepsilon_R(\delta)\geq0$ with
	$\varepsilon_R(\delta)\to0$ as $R\to\infty$ and, uniformly over $0\leq i,j\leq n_R-\delta R^2$ and all
	deterministic nearest-neighbor paths $X=(X_0,\ldots,X_i)$ and $Y=(Y_0,\ldots,Y_j)$,
	\begin{equation}
		\bigl|\Cov(S_{n_R,i}(X),S_{n_R,j}(Y)\mid X,Y)\bigr|\leq\frac{C}{\delta R^2}\sum_{r=0}^i\sum_{h=0}^j\mathbf{1}_{\{X_r=Y_h\}}+\varepsilon_R(\delta)\, .
	\end{equation}

