[Theorem Reg-est-Jaco-2 of arXiv:2512.17727, 'Stochastic transport equation with L\'evy noise'] { Let us assume that   $\alpha\in[1,2)$  and
 $\beta  \in (0, 1)  $ be such that (equation eqn-beta+alpha half of the paper) holds. Let   $L = (L_t)_{t\geq 0}$ be a L\'evy  process with L\'evy triplet $(0,0,\nu)$ satisfying Hypothesis (hyp-nondeg2 of the paper).}
     Assume that $b\in C_{\mathrm{b}}^{\beta}(\mathbb{R}^d,\mathbb{R}^d)$ and there exists
     {$p \in (\alpha,2]$} such that $\operatorname{div} b \in L^{p}( \mathbb{R}^{d})$.\\ Then for any $\delta \in [0,\frac{p-1}{p}\alpha)$ and $r>0$,
     \begin{align*}
     J\phi\in L^p(0,T;W_r^{\delta,p}), \;\; \mathbb{P}\mbox{-a.s.}
     \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 24 of arXiv:2511.05386, 'CLT for $\beta$-ensembles with Freud weights, application to the KLS conjecture in Schatte'] Let $p>1$.
\begin{enumerate}
    \item  There exist $X_1\geq 1$ and $c_1>0$
    such that, for any $N \geq 1$, $\alpha \in [0,1]$ and $\abs{x} \geq X_1$, 
    \begin{equation*}
        p_N^\alpha(x) \leq e^{-c_1 N V_{\alpha}(x)}.
    \end{equation*}
    \item  For any $\varepsilon >0$, there exist $C,c_2>0$ such that, for any $N \geq 1$ and $\alpha \in [0,1]$,
    \begin{equation*}
    \P_\alpha ( \exists k \in \llbracket1,N\rrbracket, \abs{\lambda_k} \geq 1+\varepsilon )
    \leq Ce^{-c_2 N}.
    \end{equation*}
\end{enumerate}

[Corollary corollary2 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Let $(u_{n})_{n \in \mathbb{N}}$ be any admissible ordering of $\mathcal{I}$ and let $\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C2 of the paper). Then, for every fixed $t \in \mathbb{R}$, we have that, for $i \geq 2$ and $u \in \mathcal{I}$ such that $u_{i} \preceq u$ and $|u|-|u_{i}|\leq h$,
\begin{align}
\mathbb{E}[\varphi_{u}^{(h+k+|u_{i}| -|u|)}(t-S(u)) \mid \mathcal{G}_{i-1}^{(h)} ] \stackrel{a.s.}{=}  \varphi_{u}^{(h+|u_{i}| -|u|)}(t-S(u)), \quad  \text{for} \quad k=0,1.
\end{align}

