    \begin{align}
          \biggl\lvert\, \bbP\biggl(\coker\bigl(\bM_{p,\beta},\zeta_{p,\beta}\bigr)    \cong \frac{\bbF_{p}[x]}{\beta(x)\bbF_{p}[x]}\biggr) - \frac{1}{q^2}\Bigl( 1 - \frac{1}{q^2}\Bigr)^2 \prod_{i\geq 1}\Bigl(1 - \frac{1}{q^{2i+1}} \Bigr)   \,  \biggr\rvert \leq \frac{6}{q^n}. 
