[Lemma lm:B-cK of arXiv:2507.08757, 'Strong existence and uniqueness of the tilt-indexed Busemann process in the planar corner '] Fix ${\widehat B}\in\widehat{\mathcal{K}}$. 
Suppose $s\in(0,1]$ satisfies 
	\begin{align}
	\mathbb{P}\bigl( \forall u,v\in\mathbb{Z}^2:{\boldsymbol{\pi}}^{{\widehat B},u,s}\curlywedgeuparrow {\boldsymbol{\pi}}^{{\widehat B},v,s}\hspace{0.7pt}\bigr) =1.
	\end{align}
Then $A^s$, defined by (equation B-def of the paper), is a shift-covariant recovering cocycle. For any $u\in\mathbb{Z}^2$ and $\{x,y\}\subset u+\mathbb{Z}^2_+$, $A^s(x,y)$ is $\mathcal{F}^{+}_u$-measurable, up to events of zero $\mathbb{P}$-measure.

[Definition 31 of arXiv:2512.07202, 'Hitting Probabilities for Hypoelliptic Differential Equations Driven by Fractional Brownia'] For each $l\geqslant 1$, we define the \textit{Taylor approximation function} \( F_l : \mathfrak{g}^{(l)} \times \mathbb{R}^N \to \mathbb{R}^N \) of order \( l \) associated with the RDE \eqref{density1} by
\begin{equation}
F_l(u,x) := \sum_{\alpha \in \mathcal{A}_1(l)} V_{(\alpha)}(x) \cdot (\exp u)^\alpha, \quad (u,x) \in \mathfrak{g}^{(l)} \times \mathbb{R}^N,
\end{equation}
where the exponential function is defined on \( T^{(l)} \) by \eqref{(2.6)} and \( (\exp u)^\alpha \) is the coefficient of \( \exp u \) with respect to the tensor basis element \( e_{(\alpha)} \). We  say that \( u \in \mathfrak{g}^{(l)} \) \emph{joins \( x \) to \( y \) in the sense of Taylor approximation} if \( y = x + F_l(u,x) \).

[Prop RW/RI to independent RI coupling of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] Let $\delta > 0$. Assume that $R \in [1, \frac{N}{1+\delta}]$ and $\boldsymbol{F} \subset \mathbb{T}_N$ (resp.\ $F \subset Q(0,N)$) is $(1+\delta)R$-well separated. Then for every $u>0$, $\rho \in (0,1)$, there exists a probability measure $\widetilde{\mathsf{P}}$ (resp.\ $\widetilde{\mathbb{P}}$) extending $\mathsf{P}$ (resp.\ $\mathbb{P}$) and carrying independent random interlacements $\left(\mathcal{I}^{(x),u(1\pm\rho)}\right)_{x\in F}$ with the same law as $\mathcal{I}^{u(1\pm\rho)}$, such that
    \begin{multline}

        \widetilde{\mathsf{P}}\Big(\mathcal{I}^{(x), u(1-\rho)} \cap Q_R(x) \subset X[0, uN^d] \cap Q_R(\boldsymbol{x}) \subset \mathcal{I}^{(x), u(1+\rho)} \cap Q_R(x) \text{\quad for all } x \in F \Big) \\
        \geq 1-C|F|R^{2d}\lceil uR^{d-2}\rceil \exp\Big(-c\rho\sqrt{uR^{d-2}}\Big), 
    \end{multline}
    resp.
    \begin{multline}

        \widetilde{\mathbb{P}}\Big(\mathcal{I}^{(x), u(1-\rho)} \cap Q_R(x) \subset \mathcal{I}^u \cap Q_R(\boldsymbol{x}) \subset \mathcal{I}^{(x), u(1+\rho)} \cap Q_R(x) \text{\quad for all } x \in F \Big) \geq \\
        1-C|F|R^{2d}\exp\big(-c\rho^2 uR^{d-2}\big)
    \end{multline}
    for some constants $c,C \in (0, \infty)$ depending only on $\delta$ and $d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 of arXiv:2605.27818, 'Exponential decay of mass for inertial coalescing particles with Hamiltonian noise'] Let $W\in C^1(\T)$, with $W>0$ on $\T$. Suppose $h\in C^3(\T)$ is a
non-trivial real-valued periodic solution of
\begin{equation}h''(x)+W(x)\,h(x)=0,\ \ \ \ \ x\in\T.
\end{equation}
Then $h$ satisfies conditions (H1), (H2) and (H3). 

On the other hand, assume that $h\in C^3(\T)$ is non-trivial and satisfy conditions (H1), (H2) and (H3). If we define
$W:\T\to\R$ by
\begin{equation}W(x):=\begin{cases}\,-h''(x)/h(x)&\text{if }h(x)\neq 0,\\[2pt]\,-h'''(x)/h'(x)&\text{if }h(x)=0,\end{cases}
\end{equation}
then $W\in C^1(\T)$, $W\geq 0$ on $\T$, and $h$ is a solution of equation \eqref{fine19}.

[Proposition kbasicfn of arXiv:2609.01990, 'Jacquet-Zagier treatment of the beyond endoscopy trace formula for \(\GL_2\)'] The basic function $\phi_{s_B,q}^k$ corresponding to the $k$-th symmetric power representation $\sigma_k$ of $\text{GL}_2(\mathbb{C})$ is given by
    \begin{equation}
        \phi_{s_B,q}^{k} = \sum_{m=0}^{\infty} \left( \sum_{r=0}^{\lfloor km/2 \rfloor} \mathfrak{c}(k,m,r) q^r T_{k,q}^{m,r} \right) q^{-m(s_B+\frac{k}{2})} 
    \end{equation} 
    with $T_{k,q}^{m,r}$ being the characteristic function of the set
    \[
    \left\{ X \in \text{M}_2(q^r \mathbb{Z}_q) \: : \: |\det X|_q = q^{-km} \right\}
    \]

