[Lemma l:conv of arXiv:2604.03979, 'Stationary Distributions in Monotone Markov Models: Theory and Applications'] There exists an $x^* \in \mathsf{X}$ such that

    \begin{equation}
         d(T_t \, \bar x, x^*) \to 0
         \quad \text{as} \quad
         t \to \infty.
    \end{equation}

[Definition def:XYgeneralpercsite of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Let us fix an integer $L \in \ensuremath{\mathbb{N}}$, a percolation configuration $r \in \{0,1\}^{\Lambda_L}$, and define four models of height functions:
\begin{itemize}
    \item Given an inverse temperature $\beta \geq 0$, we define 
    \begin{equation} 
    \mu_{\Lambda_L , \beta,r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} (\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L,\beta,r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} } \prod_{x \sim y} I_{\left(\varphi(x) - \varphi(y)\right)} \left( r_x r_y \beta \right) .
\end{equation}
We denote by $\mathrm{Var}_{L , \beta , r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}$ the variance with respect to the measure $\mu_{\Lambda_L , \beta, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}$.
    \item Given an inverse temperature $\beta \geq 0$, we define
\begin{equation*}
    \mu_{\Lambda_L , \beta,r}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}} (\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L,\beta,r}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}} } \exp \left( - \frac{1}{2\beta} \sum_{x \sim y} \frac{\left( \varphi(x) - \varphi(y) \right)^2}{r_x r_y} \right).
\end{equation*}
We denote by $\mathrm{Var}_{L , \beta , r}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}}$ the variance with respect to the measure $\mu_{\Lambda_L , \beta, r}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}}$.
    \item Given an integer $n \geq 2$ and two inverse temperatures $\beta_1 , \beta_2 \geq 0$, we define
\begin{equation} 
    \mu_{\Lambda_L , n, \beta_1, \beta_2, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} (\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L , n, \beta_1, \beta_2, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} }  \prod_{x \sim y}  \left[ I_{\left(\varphi(x) - \varphi(y)\right)} \left( r_x \beta_1 \right) I_{\left(\varphi(x) - \varphi(y)\right)} \left( r_y \beta_1 \right) \left(I_{\left(\varphi(x) - \varphi(y)\right)} \left(  n \beta_2 \right)\right)^{n-2} \right]. 
\end{equation}
We denote by $\mathrm{Var}_{L , n, \beta_1, \beta_2, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}$ the variance with respect to the measure $\mu_{\Lambda_L , n, \beta_1, \beta_2, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}$.
\item Given two inverse temperatures $\beta_1 , \beta_2 \geq 0$, we define
   \begin{equation} 
        \mu_{\Lambda_L, \beta_1 , \beta_2 ,r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}/\mathrm{GFF}}(\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L, \beta_1 , \beta_2 }^{\ensuremath{\mathbb{Z}}-\mathrm{XY}/\mathrm{GFF}}} \prod_{x \sim y}  I_{\left(\varphi(x) - \varphi(y)\right)} \left(r_x  \beta_1 \right)  I_{\left(\varphi(x) - \varphi(y)\right)} \left(r_y  \beta_1 \right)  \exp \left( - \frac{\left( \varphi(x) - \varphi(y) \right)^2}{2\beta_2} \right).
    \end{equation}
    We denote by $\mathrm{Var}_{L , \beta_1 , \beta_2 , r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY/GFF}}$ the variance with respect to the measure $\mu_{\Lambda_L , \beta_1 , \beta_2, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY/GFF}}$.
\end{itemize}

[Theorem 7 of arXiv:2606.15178, 'The distribution of the de Moivre experiment'] The moment of order $r$ of the bi$^{s}$nomial distribution, denoted by $M(r)$, has a polynomial form generated by the partial Bell polynomials:
	\begin{equation}
		M(r)=\sum_{k=1}^{r} (n)_k B_{r,k}\Big(\sum_{l=1}^{s}l p^l q^{s-l},\sum_{l=1}^{s}l^2 p^l q^{s-l},\ldots,\sum_{l=1}^{s}l^{r-k+1} p^l q^{s-l}\Big), \quad \text{ for } p\neq q,
	\end{equation} 
	and
	\begin{equation}
		M(r)=\sum_{k=1}^{r} (n)_k p^{ks} B_{r,k}\Big(\sum_{l=1}^{s}l ,\sum_{l=1}^{s}l^2,\ldots,\sum_{l=1}^{s}l^{r-k+1} \Big),\quad \text{ for } p= q,
	\end{equation}
	where $ (n)_k $ is the falling factorial, $ (n)_k=n(n-1)\cdots(n-k+1). $

[Lemma 4 of arXiv:2607.04759, 'Limit theorems for strongly and intermediately supercritical branching processes in Markov'] For any $n\in\N$ and $s\in[0,1)$,
	\begin{equation}
		q^{-1}_n(s)=\frac{e^{-S_n}}{1-s}+\sum_{k=0}^{n-1}\eta(k+1)\,e^{-S_k},
	\end{equation}
	In particular, for any $n\in\N$,
	\begin{equation}
		q^{-1}_n=e^{-S_n}+\sum_{k=0}^{n-1}\eta(k+1)\,e^{-S_k}.
	\end{equation}
	If assume in addition Condition \ref{Con2}, then the random variable $\eta(k)$ satisfies, for any $k\in\N$,
	\begin{equation}
		0<\eta(k)<\eta,
	\end{equation}
where $\displaystyle\eta:=\max_{i\in\X}\eta_i$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma unimodal-subseq of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let $L^{\ast }$ and $T^{\ast }=(L^{\ast })^{-1}$ be
as in Lemma~(subseq-MV of the paper), and define 
\begin{equation}
w^{\ast }(u)=w(T^{\ast }(u))=T^{\ast }(u)(1-T^{\ast }(u)).  
\end{equation}
Then:

\begin{enumerate}
\item $w^{\ast }$ is continuous on $[0,1]$, satisfies $w^{\ast }(0)=w^{\ast
}(1)=0$, and is strictly positive on $(0,1)$;

\item there exists a unique $u_{0}\in (0,1)$ such that $T^{\ast }(u_{0})=
\tfrac{1}{2}$ and 
\begin{equation}
w^{\ast }\text{ is strictly increasing on }[0,u_{0}],\quad w^{\ast }\text{
is strictly decreasing on }[u_{0},1].  
\end{equation}
In particular, $w^{\ast }$ is strictly unimodal on $[0,1]$ with a single
peak at $u_{0}$.
\end{enumerate}

[Lemma Lemma bound the intensities of arXiv:2411.09260, 'The Hydrodynamic Limit of Hawkes Processes on Adaptive Stochastic Networks'] There exists a constant $c_T$ (the constant is independent of $n$ and $j$) such that for all $t\leq T$, all $j\in I_n$,
\begin{align}
n^{-1} \sum_{k\in I_n} \sum_{\alpha,\beta \in \Gamma \; : \; \alpha\neq \beta} \big( \grave{f}^k_{\alpha\mapsto\beta}(t) + \breve{f}^k_{\alpha\mapsto\beta}(t) \big) &\leq c_T \big(  \delta^n_t +  \varphi^{n}_t + \eta^n_t \big)  \\
n^{-2} \sum_{j,k\in I_n} \sum_{a,b \in \Gamma_E \; : \; a\neq b } \big( \grave{l}^{jk}_{a \mapsto b}(t) + \breve{l}^{jk}_{a \mapsto b}(t)  \big) &\leq c_T \big( \delta^n_t + \varphi^{n}_t \big) \\
n^{-1} \sum_{j\in I_n} \big\| G^j_t - \hat{G}^j_t \big\|  \leq & c_T\eta^n_t + c_T \big( \delta^n_t + \varphi^{n}_t \big).
\end{align}

