[Defn of arXiv:2411.09988, 'A Study in Markov Chains, Loop-Erased Random Walk and Loop Soups'] Write a path $\omega$ of length $n$ as a finite sequence of points
    \begin{equation}
        \omega = [\omega_0, \ldots, \omega_n]
    \end{equation}
    with $\omega_j \in \overline{A}$. We call a path a \textit{self-avoiding walk} (SAW) of length $n$ if all of the vertices $\{\omega_0, \ldots, \omega_n\}$ are distinct.

[Proposition prop:NS of arXiv:2411.06838, 'Generalized Wasserstein Barycenters'] A sequence $(\gamma_n)_{n\in \mathbb{N}} \subset \mathcal{P}_2^{sw}(Z)$ and a measure $\gamma \in \mathcal{P}_2^{sw}(Z)$ satisfy
\begin{itemize}
	\item[\rm{(i)}] $\gamma_n \rightharpoonup \gamma$ narrowly in $\mathcal{P}(Z)$;
	\item[\rm{(ii)}] $\displaystyle \lim_{n\to \infty} \int_Z |x|^2\, {\rm d}\gamma_n(x,y) \to \int_Z |x|^2\, {\rm d} \gamma(x,y)$;
	\item[\rm{(iii)}] $\displaystyle \sup_{n \in \mathbb{N}} \int_Z |y|^2\, {\rm d}\gamma_n(x,y) < +\infty$, 
\end{itemize}	
if and only if
\[
	\gamma_n \to \gamma\quad  \text{in}\quad \mathcal{P}_2^{sw}(Z).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Main Theorem Statement of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] Fix a $k \in \mathbb{N}$ and let $\{a_j\}_{j=1}^n, \{b_j\}_{j=1}^{n-1}$ be the tridiagonal entry (processes) as in (equation eq:tridiagonalmatrix of the paper), from the $n\times n$ tridiagonalized GOE process. Define 
\begin{equation*}
E_n(t):=\left(a_1(t),\dots, a_k(t), \frac{1}{\sqrt{n}}(b_1(t)^2-n),\dots ,\frac{1}{\sqrt{n}}(b_k(t)^2-n)\right).
\end{equation*} 
Then, $E_n(t)$ converges weakly in $C[0,\infty)$ to a vector process $E(t)=(A_1(t),\dots,A_k(t),B_1(t),\dots,B_k(t))$ as $n\to\infty$, where
\begin{equation*}
    \frac{1}{\sqrt{2}}E(t) \sim \mathbf{OU}_{2k}(1,3,\dots,2k-1,2,4,\dots,2k).
\end{equation*} 
More explicitly, the components $A_j(t) \in C[0,\infty)$ and $B_j(t) \in C[0,\infty)$ are jointly-independent centered Ornstein--Uhlenbeck processes with covariances given as $\mathrm{Cov}(A_j(t),A_j(s))=2e^{-(2j-1)|t-s|}$ and $\mathrm{Cov}(B_j(t),B_j(s))=2e^{-2j|t-s|}$, for $j=1,\dots,k$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma e_t of arXiv:2608.29507, 'Denoising as Projection: Constrained Optimization with Gradient-Guided Diffusion'] Define 
    \begin{align*}
        e_t:= \frac{\eta L^2}{2(1-\eta\mu c)} \|v_t\|^2,
    \end{align*}
    where $v_t$ is defined as in (equation eq:def-u-v of the paper), then under the conditions specified in Theorem (theorem: convergence-guided-diffusion of the paper) and for $\widetilde{\eta}$ defined as in (equation eq:subspace-dynamics of the paper), we have that 
    \begin{align*}
        e_{t-1} \le  (1-\widetilde{\eta} \mu c)e_t -  \frac{\widetilde{\eta} L^2}{2}\|v_t\|^2
    \end{align*}
    \begin{proof} For $\|v_t\| = 0$ the statement is trivial. For $\|v_t\|>0$ we have
        \begin{align*}
            &e_{t-1} \le  (1-\widetilde{\eta} \mu c)e_t -  \frac{\widetilde{\eta} L^2}{2}\|v_t\|^2\\
            \stackrel{\textup{Lemma (lemma:guided-diffusion-u-v of the paper)}}{\Longleftrightarrow}\quad& \frac{\eta L^2}{2(1-\eta\mu c)} \frac{\sigma_{t-1}^2}{\sigma_t^2} \le (1-\widetilde{\eta} \mu c)\frac{\eta L^2}{2(1-\eta\mu c)} -  \frac{\widetilde{\eta} L^2}{2}\\
            \Longleftrightarrow\quad & \frac{\sigma_{t-1}^2}{\sigma_t^2}\le (1-\widetilde{\eta} \mu c) - \frac{\widetilde{\eta} (1-\eta\mu c)}{\eta}\\
            \Longleftrightarrow\quad & (1-\epsilon)^2=\frac{\sigma_{t-1}^2}{\sigma_t^2}\le (1-\widetilde{\eta} \mu c) - \epsilon (1-\eta\mu c) = 1-\epsilon\eta\mu c -\epsilon + \epsilon\eta\mu c = 1-\epsilon,
        \end{align*}
        given that $\epsilon \in (0,1)$, it completes the proof.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 29 (Universal polynomial inequality) of arXiv:2605.11451, '2605.11451'] Let $0<s<1$ and $s^2\le r\le s$. Then
\begin{equation}
 (1+s^2)(1+r)(1+r^3)\le2(1+r^2s)^2.
\end{equation}

[Lemma Vprimeqjqk of arXiv:2608.30212, 'A Painlev\'e equation for the H\"ormander-Bernhardsson constant'] For $c\in J_{k,0}$ and $j\le k$,
\begin{align}
\mathcal{L}_c[Q_{k,c}'Q_{j,c}] = \mathcal{L}_c[V_c'Q_{k,c} Q_{j,c}]
\end{align}

[Definition Thick quantum disk of arXiv:2510.05850, 'Three-point connectivity constant for $q$-state Potts spin clusters'] For $W \ge \frac{\gamma^2}{2}$, we define the measure $\mathcal{M}_2^{\rm disk}(W)$ as follows. Write $\beta=\gamma+\frac{2-W}{\gamma}$ and let $(B_t)_{t \ge 0}$ be a standard Brownian motion conditioned on $B_{2t}-(Q-\beta)t<0$ for all $t>0$, and $(\widetilde B_t)_{t \ge 0}$ be its independent copy. Let
    \begin{equation*}
        Y_t=
        \begin{cases}
            B_{2t}-(Q-\beta) t, & \mbox{ for }\,t \ge 0, \\
            \widetilde B_{-2t}+(Q-\beta)t, & \mbox{ for }\,t<0,
        \end{cases}
    \end{equation*}
    and set $h_1(z)=Y_{\mathrm{Re} z}$ for each $z \in \mathcal{S}$. Let $h_2$ be a random generalized function with the same law as $h_\mathcal{S}^2$ defined above and independent from $h_1$.
    Sample $\mathbf{c} \in \mathbb{R}$ independently from the measure $\frac{\gamma}{2} e^{(\beta-Q)c} \mathop{}\!\mathrm{d} c$, and set $\phi(z)=h_1(z)+h_2(z)+\mathbf{c}$. The infinite measure $\mathcal{M}_2^{\rm disk}(W)$ is defined as the law of $(\mathcal{S},\phi,-\infty,+\infty)/{\sim_\gamma}$.

[Proposition 12 of arXiv:2609.03961, 'On the exponential sum over squarefree integers'] Let $N\ge2$, let $2\le Q\le N^{1/2}/64$, and suppose that
\eqref{eq:minor-approx} holds.  Then
\begin{equation}
  |S(\alpha)|\ll\frac NQL^5,
\end{equation}
where the implied constant is absolute.

[Proposition 22 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] Under the above settings, the Feller process $\Xi$ admits a unique invariant probability measure $\mu=\delta_0\times\leb(\T)$. Moreover, for any $V:\R_+\times\T\rightarrow[0,\infty)$ that is continuous,
            \begin{equation*}
               \lim_{t\rightarrow\infty} d_V(P_t^*\delta_x,\mu)=0, \quad \forall\, x\in\X.
            \end{equation*}

