[Proposition prop:converge_to_max of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Let $\bigl(f_n\bigr)_{n \in \mathbb{N}}$ be a sequence of \rm{(}possibly random\rm{)} functions $f_n:\mathbb{N} \to \mathbb{R}$. Then,   
    \begin{enumerate} [label=(\roman*), font=\normalfont]
        \item  If there exists $\theta \in \mathbb{R}$ such that, for each fixed $\xi \in [0,1]$, with probability one,
    \begin{equation} 
    \liminf_{n \to \infty} \frac{f_n(1 + \lfloor \xi n\rfloor)}{n} \ge \theta \xi,
    \end{equation}
    then, for fixed real numbers $0 \le x< y \le 1$ and integers $k \ge t$, the following holds almost surely:
    \begin{equation} 
    \liminf_{n \to \infty} \frac{1}{n} \max_{\ell \in \llbracket 1 + \lfloor xn \rfloor,  \lfloor yn \rfloor + k + 1\rrbracket }\bigl[f_n(\ell) + G\bigl((-n - 1 + \ell,-n),(k,t))\bigr)\bigr] \ge \sup_{\xi \in [x,y]}[\theta \xi + \rho_{c}(1 - \xi)],
    \end{equation}
     where the function $ \rho_{c}:[0,1] \to \mathbb{R}$ is defined in (equation eq:mu_k_def of the paper). 
    \item  If, for some $\theta \ge 0$, the following holds almost surely:
    \begin{equation} 
    \limsup_{n \to \infty} \frac{1}{n} \max_{\ell \in \llbracket 1,n \rrbracket }[f_n(\ell) - \theta \ell] = 0,
    \end{equation}
    then for all real numbers $0 \le x < y \le 1$ and integers $k \ge t$, the following holds almost surely:
    \begin{equation} 
    \limsup_{n \to \infty} \frac{1}{n} \max_{\ell \in \llbracket 1 + \lfloor xn \rfloor, \lfloor yn \rfloor + k + 1 \rrbracket }\bigl[f_n(\ell) + G\bigl((-n - 1 + \ell,-n ),(k,t))\bigr)\bigr] \le \sup_{\xi \in [x,y]}[\theta \xi + \rho_{c}(1 - \xi)].
    \end{equation}
    \item  Assume $c \le 1$ or $\theta \neq \frac{qc}{1-qc}$ and the sequence $f_n$ satisfies both conditions (equation eq:liminf_ge of the paper) and  (equation eq:limsup_le of the paper) almost surely. Define the new function $f_n':\mathbb{Z}_{\ge -n} \to \mathbb{R}$ by $f_n'(\ell) = f_n(\ell + n + 1)$. Then, for each $k \ge t$ and $\varepsilon > 0$, there exists a random $N = N(k,t,\varepsilon) \in \mathbb{Z}$ such that for all $n \in \mathbb{Z}_{\ge N}$, all maximizers of $\ell \mapsto f_n'(\ell) + G\bigl((\ell,-n),(k,t)\bigr)$ over $\ell \in \llbracket -n,k\rrbracket$ lie in the set 
    \begin{equation} 
    \Bigl[\bigl(-X_c(\theta) - \varepsilon)n, (-X_c(\theta)- \varepsilon)n\bigr)\Bigr],
    \end{equation}
    where the function $X$ is defined in (equation eq:K_func of the paper).  In particular, for all $n \in \mathbb{Z}_{\ge N}$,
    \begin{equation} 
    Z_{f_n',-n}(k,t) \in  \Bigl[\bigl(-X_c(\theta)  - \varepsilon)n, (-X_c(\theta) + \varepsilon)n\bigr)\Bigr].
    \end{equation}
    \end{enumerate}

