[Lemma 7 (Properties of concave functions) of arXiv:2605.28766, 'Convex order and faster transmission in first contact percolation'] Let $I$ be some index set and let $\varphi_i\colon\R^k\to\R\cup\{-\infty\}$ be concave for every $i\in I$. Then,
    \begin{enumerate}
        \item $\inf_{i\in I} \varphi_i$ is concave.

        \item If $\sharp I<\infty$, then $\sum_{i\in I} \varphi_i$ is concave.
    \end{enumerate}
    The same is true if we replace concave with increasing and concave.

[Lemma 34 of arXiv:2608.27307, '2608.27307'] Let $h$ be a real random variable with moments of all orders, and let $F:\R\to\C$ be a smooth function. For every fixed integer $\ell\geq1$,
        \begin{align}
                \bb E[hF(h)] =\sum_{k=0}^{\ell}\frac{\kappa_{k+1}(h)}{k!}\bb E F^{(k)}(h)+\calR_{\ell+1}. \nonumber
        \end{align}
        For any $K>0$, the remainder term satisfies
        \begin{align}
                \abs{\calR_{\ell+1}} & \leq O(1)(\bb E\sup_{|t|\leq|h|}|F^{(\ell+1)}(t)|^2\bb E[|h|^{2\ell+4}1_{\{|h|>K\}}])^{1/2} +O(1)\bb E|h|^{\ell+2}\sup_{|t|\leq K}|F^{(\ell+1)}(t)|. \nonumber
        \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] The transition density $p^D$ satisfies
		\begin{align}
			\lim_{D\ni x\to z}p^D(t,x,y)=0,
		\end{align}
		for all $y\in D$ and for all regular points $z\in \partial D$ for $X$.

		If $D$ is regular, then for all $u\in \BB_b(D)$ we have $ P^D_tu\in C_0(D)$, $t>0$.

