[Lem martingale_ineq of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] Let $p\geq 2$. 
	For a real-valued $\mathscr{P}\otimes\mathscr{Z}$-measurable function $g$, there is a constant $K$, depending only on $p$, such that 
	\begin{align*}
		E \displaystyle \sup_{t\in[0,T]}\Big|\int_{0}^{t}&\int_Z g_s(z) \tilde n_p(ds,dz)\Big|^{p}
		\leq  K E\int_{0}^{T}\int_Z |g_t(z)|^p \nu(dz) dt<\infty.
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:diagram of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] A \emph{diagram} $\Gamma$ is a ribbon graph satisfying the following two conditions:
\begin{itemize}
    \item[(i)] Every unmarked vertex has degree at least 3;
    \item[(ii)] Every marked vertex has degree at least 2.
\end{itemize}

Let $E(\partial \Sigma), V(\partial\Sigma)$ be the edge and vertex set of $\partial \Sigma$. For the diagram, we will frequently use   the following notation:
\begin{itemize}
    \item  {\bf Edge set}: let \(E(\Gamma)\) denote the set of all edges of \(\Gamma\), with \(E_{\mathrm{int}}(\Gamma)=E(\Gamma)\setminus E(\partial\Sigma)\) and \(E_{\mathrm{b}}(\Gamma)= E(\partial\Sigma)\) denoting the sets of interior and boundary edges, respectively;
    \item {\bf Vertex   set}: let \(V(\Gamma)\), \(V_{\mathrm{int}}(\Gamma)=V(\Gamma)\setminus V(\partial\Sigma)\) and \(V_{\mathrm{b}}(\Gamma)=V(\partial\Sigma)\) denote the sets of all, interior, and boundary vertices, respectively;
    \item  {\bf Boundary  set}: for each \(j \in [s]\), let \(\partial D_j \subset E(\Gamma)\) denote the set of edges forming the boundary of face \(j\).
     \item  {\bf Diagram  set}: let $\mathscr{D}_{s;\beta}$ be the set of all $s$-cell diagrams (on orientable surfaces when $\beta=2$) and  \(\mathscr{D}_{s;\beta}^* \subset \mathscr{D}_{s;\beta}\) be the subset of connected diagrams.
\end{itemize}

[Dfntn 2 (gradient and divergence operators) of arXiv:2608.31054, 'Revisiting Picard's proof of the Picard--Weber--Weck selection theorem'] Let $\Omega\subseteq \R^d$ be open. We define the differential operators
\begin{align*}
    \grad_c&: C_c^\infty(\Omega)\subseteq L^2(\Omega)\rightarrow L^2(\Omega)^d,\quad v\mapsto (\partial_1 v,\ldots,\partial_d v)^\top,\\ 
    \div_c&: C_c^\infty(\Omega)^d\subseteq L^2(\Omega)^d\rightarrow L^2(\Omega),\quad (v_1,\ldots,v_d)^\top\mapsto \sum_{k = 1}^d \partial_k v_k,\\
    \Grad_c&: C_c^\infty(\Omega)^d\subseteq L^2(\Omega)^d\rightarrow L^2(\Omega)^{d\times d},\quad (v_1,\ldots,v_d)^\top\mapsto (\partial_j v_i)_{1\leq i,j\leq d},\\
    \Div_c&: C_c^\infty(\Omega)^{d\times d}\subseteq L^2(\Omega)^{d\times d}\rightarrow L^2(\Omega)^{d},\quad (v_{ij})_{1\leq i,j\leq d}\mapsto (\sum_{j = 1}^d \partial_j v_{ij})_{1\leq i\leq d}.
\end{align*}
We set
\begin{align*}
    \gradcirc := \overline{\grad_c},\qquad  \divcirc := \overline{\div_c},\qquad \Gradcirc := \overline{\Grad_c},\qquad  \Divcirc := \overline{\Div_c},
\end{align*}
and
\begin{align*}
    \grad := -(\divcirc)^\ast,\quad \div := -(\gradcirc)^\ast,\quad \Grad := -(\Divcirc)^\ast,\quad \Div := -(\Gradcirc)^\ast.
\end{align*}

[Cor vssm =ssm for trees of arXiv:2603.17858, 'Decay of correlations and zeros for the hard-core model'] Let $\lambda>0$.
    For any rooted tree $(T,v)$ and any $r=(r_u)\in [0,\lambda]^{S^*_T(v,n)}$ we have 
    \begin{eqnarray}
        {F}_{T,n}({\Vec{0}})\leq {F}_{T,n}(r_u) \leq {F}_{T,n}({\Vec{\lambda}}) & \text{ if $n$ is even, and} 
        \\
        {F}_{T,n}({\Vec{\lambda}})\leq {F}_{T,n}(r_u) \leq {F}_{T,n}({\Vec{0}})  &\text{ if $n$ is odd.}
    \end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

