[Theorem 3 of arXiv:2608.29878, 'Discontinuous phase transitions \\ in the one-dimensional \\ pair and triplet creation pro'] Let $x^k\in \RR$ and $x_\vep^k\in\vep\ZZ$, $\,k=1,\dots
  K$ satisfy
  \begin{equation}
    x^k_\vep\to x^k\hbox{ and
    }\vep^{-1}|x^k_\vep-x^{k'}_\vep|\to\infty\hbox{ as
    }\vep\to0\hbox{ for any }k\neq k'. 
  \end{equation}
  If $u$ is the solution of mean-field PDE  \eqref{rdpde}, and $t>0$ then  
  \begin{align}
    \lim_{\vep\to 0}P(\xi^\vep_t(x_\vep^k+\vep y_i)=\eta_{i,k},
&\ \ i=0,\dots,L,\, k=1,\dots K)
\nonumber\\ 
& =\prod_{k=1}^K\langle 1\{\xi(y_i)=\eta_{i,k}, i=0,\dots,L\}\rangle_{u(t,x^k)}.

  \end{align}
for any  $\eta\in \{0,1\}^{\{0,\dots,L\}\times \{1,\dots K\}}$, $y_0,\dots,y_L\in\ZZ$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:gen-smooth-evaluation of arXiv:2605.26652, 'Pathological Large Deviations of the KMP Process in Dimension $d\ge 2$'] For any twice-differentiable test function $\varphi\in C^2(\mathbb T^d)$, there exist constants $\epsilon_{N,\varphi,H,K}$, vanishing as $N\to\infty$, such that, $\mathbb{Q}^{N,K}$-almost surely, for all $0\le t\le T$,
\begin{equation}
\left|\mathcal L^{N,H,K}_t\langle \varphi, \pi_N(\xi^N_t)\rangle-\frac12\langle \Delta\varphi,\pi_N(\xi^N_t)\rangle-\mathfrak D_{t,\varphi}^{N,K}(\xi^N_t)\right|\le \epsilon_{N,\varphi,H,K}.
\end{equation} 
Moreover, the $\mathbb{Q}^{N,K}$-martingale
\[
M^{N,\varphi}_t:=\langle \varphi, \pi_N(\xi^N_t)\rangle-\langle \varphi, \pi_N(\xi^N_0)\rangle-\int_0^t\mathcal L^{N,H,K}_s\langle \varphi, \pi_N(\xi^N_s)\rangle ds
\]
has predictable quadratic variation at most
\begin{equation}

[M^{N,\varphi}]_t\le \frac{C_{\varphi,H,K}}{N^d}\int_0^t\|\xi^N_s\|_{L^2_N}^2 ds.
\end{equation}

