[Theorem 3 of arXiv:2603.25452, 'New approach to optimal control of delayed stochastic Volterra integral equations'] \textbf{(Representation Theorem for advanced BSVIEs)}\\
	Assume that the generator $\phi: [0, T]^2\times\mathbb{R}\times\mathbb{R}\to \mathbb{R}$ such that $\phi(.,s.,.)$ is $(\mathcal{F}_s)_{s\geq 0}$-adapted. Suppose that there is the couple of process $(p(t), q(t, .))$ solution of  the backward stochastic Volterra integral equation (BSVIE) 
\begin{eqnarray*}
	p(t) = \Phi(t) + \int_t^T \phi(t, s, p(s+\delta), q(t, s))ds 
		- \int_t^T q(t, s)dB(s), \quad t \in [0, T].	
\end{eqnarray*}  
Then, for all $0\leq t<s\leq T$, we have 
\begin{eqnarray}
q(t, s) = \mathbb{E}\left[ D_s p(t) \mid \mathcal{F}_s \right].
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 (Exact distribution) of arXiv:2605.08629, 'Moderate deviations for the Maki--Thompson rumour model'] For $j = 1,\ldots,n$,
    \begin{equation}
        \mathbb{P}(V_n = j) = \frac{(n-1)!}{(n-j)!} \frac{d_j}{n^{2j}},
    \end{equation}
    where the sequence $\{d_j\}_{j\ge 1}$ is defined recursively by $d_1=1$ and for $j\ge 2$,
    \begin{equation}
        d_j = \frac{j^{2j}}{(j-1)!} - \sum_{i=1}^{j-1} \frac{j^{2(j-i)}}{(j-i)!} d_i.
    \end{equation}
    Consequently, for $k = 0,\ldots,n-1$,
    \begin{equation}
        \mathbb{P}(X_n = k) = \frac{(n-1)!}{k!} \frac{d_{n-k}}{n^{2(n-k)}}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem upperbdeg of arXiv:2606.18722, 'Very large cliques in a scale-free random graph'] Given any $x\geq 4$ we have that
    \[\mathbb{P}_u\left(\text{deg}(u,t)\geq \left(\frac{t}{b(u)}\right)^{1-p/2}x\right)\leq \exp\left(-C_3\frac{x^2}{b(u)}\right),\]
    for some constant $C_3=C_3(p)>0$ which depends solely on $p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lm 44 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let us denote, by $\Theta_i$, the polynomials from \eqref{eq:pre phi contour virtual} so that for a fixed integer $N$
\begin{equation}
   \Theta_i(x) := \phi_{[N-i+1,N]}(\virst_i,x) = \oint_{\gamma} \frac{\dd z}{2\pi\ii} \frac{1}{z^i} \left(\frac{1}{1-z}\right)^x = \binom{x+i-2}{x-1},
\end{equation}
where the contour surrounds $z=0$ while omitting all other singularities of the integrand. Then the following holds for all $1\leq i,j\leq N$:
\begin{equation}

    \sum_{x=1}^\infty \sum_{y=1}^\infty \Theta_i(x) Q_{1,1}(x,y) \Theta_j(y) =  Q_{i+1,j+1}(1,1).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:usefuldecomp of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $l,m,n \in \mathbb{N}\cup \{0\}$ with $l > n \geq 0$ and $m \geq 1$. Let $P \in \mathcal{L}(\pi)$ and $Q_i \in \mathcal{I}(\pi) \cap \mathcal{L}$ for $i \in \llbracket 0,m-1 \rrbracket$ be a sequence of isometric involution transition matrices. Define $R_n$ as in (equation eq:Rndef of the paper). 
	\begin{itemize}
		\item For $E \in \mathcal{E}$, we have
		\begin{align*}
			D^\pi_{KL}(R_n \| E) 
			&= \sum_{j=n}^{l-1} D^\pi_{KL}(R_j \| R_{j+1}) + D^\pi_{KL}(R_{l} \| E).
		\end{align*}

		\item For $E \in \mathcal{E}$, we have
		\begin{align*}
			\left\lVertR_n - E\right\rVert_F^2 
			&= \sum_{j=n}^{l-1} \norm{R_j - R_{j+1}}_F^2 + \norm{R_{l} - E}_F^2.
		\end{align*}

		\item  We have
		\begin{align*}
			R_\infty(Q_0,\ldots,Q_{m-1},P) = R_\infty(Q_0,\ldots,Q_{m-1},R_l).
		\end{align*}

		\item(Projection is trace-preserving)
		\begin{align*}
			\mathrm{Tr}(R_n) = \mathrm{Tr}(P).
		\end{align*}
	\end{itemize}

