[Thm 1 of arXiv:2506.08782, 'First to reach $n$ game\thanks{This version corrects a few minor typos which were in the p'] Let  $E_{n,p}=\E Z_{n,p}$ and $z=pq$. Then 
\begin{align}
   E_{n,p} =n\mu \,\sum_{j=0}^{n-1} C_j z^j
\end{align}
where $C_j=\frac{(2j)!}{j!(j+1)!}$ are {\em Catalan numbers}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 254 of arXiv:2601.16377, '2601.16377'] A connectoid $\boldsymbol{\Theta}$ is realizable if and only it is the matrix full of $1$s, or the conditions (1) and (2) below are simultaneously satisfied.
\begin{itemize}
\item[(1)] For any $g,h,k \in [H]$, having $\theta_{g,h} = 1$ implies $\theta_{g,k} = \theta_{h,k}$. In particular, the relation $\theta_{g,h} = 1$ defines an equivalence relation on $[H]$, and we denote $O_h$ the equivalence class of $h$.
\item[(2)] For each $h \in [H]$, the set of subsets $\mathfrak{C}_h := \big\{C_h \cap C_g \,\,|\,\,g \in C_h \setminus O_h \big\}$ has cardinality $1$ or $2$. If it has two distinct elements $C_{h}',C_h''$, then $C_h' \cap C_h''$ is the equivalence class containing $h$.
\end{itemize}
In this case, denoting $\mathfrak{C}_h^+ = \mathfrak{C}_h$ if the latter set has cardinality $2$, and $\mathfrak{C}_h^+ = \mathfrak{C}_h \sqcup \{O_h\}$ otherwise, and $\mathfrak{C}^+ = \bigcup_{h = 1}^H \mathfrak{C}_h^+$, we have
\begin{equation}
\boldsymbol{\Theta} = \frac{1}{2} \sum_{C \in \mathfrak{C}^+} \textnormal{\textbf{1}}_{C \times C}.
\end{equation}

[Lemma 30 (Basic properties of the vectorfields) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The follow results hold.

\begin{enumerate}
\item The vectorfield $\Lgeo$ is geodesic and $\gfour$-null, i.e., with 
$\Dfour$ denoting the Levi-Civita connection of $\gfour$, we have:
 \begin{align} 
 \gfour(\Lgeo,\Lgeo) & = 0, 
	&  
\Dfour_{\Lgeo}\Lgeo & = 0.
\end{align}
The rescaled vectorfield $\Lunit$ is also $\gfour$-null:
\begin{align} 
\gfour(\Lunit,\Lunit) 
& = 0,
\end{align}
and it satisfies the following identity,
where $\upmu$ is the inverse foliation density defined in \eqref{E:MUDEF}:
\begin{align} 
	\Dfour_{\Lunit} \Lunit
	& = \frac{(\Lunit \upmu)}{\upmu} \Lunit.
\end{align}\item $\Lunit$ is $\gfour$-orthogonal to the characteristics $\nullhyparg{u}$, 
that is, for any vectorfield $\Singletan$ tangent to $\nullhyparg{u}$,
	we have:
	\begin{align} 
		\gfour(\Lunit,\Singletan)
		& = 0.
	\end{align}\item The following identities hold:
\begin{align}
\Lunit u & = 0, & \Lunit t = \Lunit^0 & = 1, & \muX u & = 1, & \muX t = \muX^0 &= 0,  \\
\gfour(X,X) & = 1, & \gfour(\muX,\muX) & = \upmu^2, & \gfour(\Lunit,X) & = -1, & \gfour(\Lunit,\muX) &= -\upmu. 
\end{align}\item The vectorfield $\olduLunit$ is $\gfour$-null and transverse to $\nullhyparg{u}$. In particular, we have:
	\begin{align}
		\gfour(\olduLunit,\olduLunit) = 0, & & \gfour(\Lunit,\olduLunit) = -2. 
	\end{align}


\item The material vectorfield $\Transport$ is future directed, $\gfour$-orthogonal to $\Sigma_t$ (and hence also to $\ell_{t,u}$), 
and it is of $\gfour$-unit size: 
\begin{align} 
\gfour(\Transport,\Transport) 
& = -1.
\end{align}
Moreover, we have:
\begin{align} 
\Transport & = \Lunit + X, 
\end{align}
and relative to the Cartesian coordinates, we have:
\begin{align}
\Transport_{\alpha}
& = 
-
\updelta_\alpha^0, 
\end{align}
where $\updelta_{\alpha}^{\beta}$ is the Kronecker delta. 
\item Finally, the following identities hold for $i=1,2,3$ and $A=2,3$:
\begin{subequations}
\begin{align}
	\Xsmall^i  & = - \Lsmall^i + v^i, 

		\\
	\Yvfsmall{A}^i
	& = 
			-\Speed^{-2} \Xsmall^A
			X^i
			=
			-\Speed^{-2} 
			(- \Lsmall^A + v^A)
			(-\Lunit^i + v^i).

\end{align}
\end{subequations} 

\end{enumerate}

