body:
[Proposition 10 (Newton inversion) of arXiv:2608.29585, '2608.29585'] Every sequence $f_r\in L$ has a unique expansion
\eqref{eq:abstract-newton-expansion}.  Its coefficients satisfy
\begin{equation}
 h_k=
 \frac{f_k-\sum_{j=0}^{k-1}p_j(x_k)h_j}{p_k(x_k)}
\end{equation}
and
\begin{equation}
 h_k=\sum_{j=0}^{k}\frac{f_j}{D_{k,j}},
 \qquad
 D_{k,j}=\prod_{\substack{0\le i\le k\\i\ne j}}(x_j-x_i).
\end{equation}
For $k\ge1$, put
\begin{equation}
 \Delta_k(f)=\det
 \begin{pmatrix}
 1&x_0&\cdots&x_0^{k-1}&f_0\\
 1&x_1&\cdots&x_1^{k-1}&f_1\\
 \vdots&\vdots&&\vdots&\vdots\\
 1&x_k&\cdots&x_k^{k-1}&f_k
 \end{pmatrix},
 \qquad \Delta_0(f)=f_0,
\end{equation}
and
\begin{equation}
 V_k=\prod_{0\le i<j\le k}(x_j-x_i),
 \qquad V_0=1.
\end{equation}
Then
\begin{equation}
 h_k=\frac{\Delta_k(f)}{V_k}.
\end{equation}

