[Corollary prop:exponential-decay of arXiv:2505.02685, 'On the Spectral Expansion of Monotone Subsets of the Hypercube'] Let $f \in L^2(V)$. Then the function $t \mapsto \mathcal{E}^-(P_t f)$ satisfies, for all $t \ge 0$, 
    \begin{equation}

        \odv*{\mathcal{E}^-(P_t f)}{t} \le -2\lambda^-(G)\cdot \mathcal{E}^-(P_t f) \,.
    \end{equation}
    Furthermore, $\lambda^-(G)$ is the largest constant for which
    (equation eq:directed-spectral-gap-decay of the paper) holds for all $f, t$.

[Proposition prop:compact:supp:sink of arXiv:2412.09235, 'A semiconcavity approach to stability of entropic plans and exponential convergence of Sin'] Assume that $\rho$ has compact support and that $\nu$ satisfies (eq:TI of the paper).
    \begin{enumerate}[label=(\roman*)] 
        \item If $\nabla_2^2c(x,y)=\Sigma$, then Sinkhorn's algorithm converges and for $\varepsilon\leq \sqrt{\tau}\,\norm{g}_{\mathrm{L}^\infty(\rho)}$   the rate is 
        \begin{equation}
        1-\frac{\varepsilon^2}{\varepsilon^2+\tau \|g\|_{\mathrm{L}^\infty(\rho)}^2}\,,
        \end{equation}
         where $g(x)\coloneqq \nabla_2 c(x,y)-\Sigma y$. 
        \item If $\nu$ is  compactly supported, then Sinkhorn's algorithm converges and for $\varepsilon$ small enough (as in (equation eps:small:compact:both of the paper)) the rate is
        \begin{equation*}
1-\frac{\varepsilon^2}{\varepsilon^2+\tau\varepsilon\,(H(c)-h(c))+\tau\norm{\nabla_2 c}_{\mathrm{L}^\infty(\rho\times\nu)}^2}\,,
\end{equation*}
where $h(c),\,H(c)$ are defined such that $h(c)\preceq \nabla_2^2c(x,y)\preceq H(c)$ on $\supp(\rho)\times\supp(\nu)$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

