[Thm RB of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] For $\mu > -\frac12$, define the fourth-order differential operator 
\begin{align} 
  {\mathfrak D}_{\mu}^{{\mathbb R} \rtimes {\mathbb B}} u: = \,& -\frac14 (1-\|{\bm y}\|^2) \Delta_{{\bm x}}^2 + {\langle} {\bm x},\nabla_{\bm x}{\rangle} \Delta_{\bm x} - ({\langle} {\bm x},\nabla_{\bm x}{\rangle} 
   + {\langle} {\bm y},\nabla_{\bm y}{\rangle}) ^2  \\
   & + \Delta_{\bm x} + \Delta_{\bm y} 
   +  (2\mu + d_1+d_2 -1) \left( \frac12 \Delta_{\bm x}- {\langle} {\bm x},\nabla_{\bm x}{\rangle} - {\langle} {\bm y},\nabla_{\bm y}{\rangle} \right). \notag
\end{align}
Then ${\mathcal V}_n({\mathbb R}^{d_1}  \rtimes {\mathbb B}^{d_2}, \bm W_{\mu}^{{\mathbb R} \rtimes {\mathbb B}})$ is an eigenspace 
of $ {\mathfrak D}_{\mu}^{{\mathbb R} \rtimes {\mathbb B}}$ for each $n \in {\mathbb N}_0$. More precisely, 
\begin{align} 
  {\mathfrak D}_{\mu}^{{\mathbb R} \rtimes {\mathbb B}} u =  - n (n+ 2\mu + d_1+d_2 - 1) u, \qquad 
         \forall u \in {\mathcal V}_n\big({\mathbb R}^{d_1}  \rtimes {\mathbb B}^{d_2}, \bm W_{\mu}^{{\mathbb R} \rtimes {\mathbb B}}\big).
\end{align}

