[Theorem 2 (Convergence in probability) of arXiv:2605.15718, 'Mean-field derivation of a two-dimensional signal-dependent parabolic-elliptic Keller-Sege'] Let $T >0$. Under the assumptions \ref{ass_ks} it holds: \\
$\forall \eta \in (0,1) : \forall \beta \in (0, \frac{1}{4} ) :\forall \gamma >0 : \exists C>0 : \forall N \in \N, \text{ with } N \geq 2 : $
\begin{align*}
\sup_{t \in [0,T]} \pr \bigg( \Big\{ \max_{1 \leq i \leq N}  \left| X^\varepsilon_{N,i} - \hat{X}_{i} \right|(t) \geq \varepsilon^\eta\Big\} \bigg) \leq  C \varepsilon^\gamma ,
\end{align*}
where $\varepsilon = N^{-\beta}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2607.08129, '2607.08129'] For $0\le s\le t\le1$,
\begin{align}
 \E[W_n(t)-W_n(s)]
 &\longrightarrow
 \int_0^1\Prob(s<xG\le t)\dd x
 =c_\theta(t-s).

\end{align}
For $0\le s,t\le1$,
\begin{align}
 &\frac1{n\log n}
 \sum_{\sqrt n<p\le n}(\log p)^2
 \Cov\Big(
 \1_{\{x_{n,p}G_{n,p}\le s\}},
 \1_{\{x_{n,p}G_{n,p}\le t\}}
 \Big)
\longrightarrow C_\theta(s,t).
\end{align}

[Theorem 12 of arXiv:2605.29608, '2605.29608'] Consider the 1D Ising model with coupling constant $\hat{J}\in[0,+\infty)$. Let $(Y_{k})_{k\in\mathbb{Z}^{+}}$ and $\mu_{N}$ be defined as in Theorem \ref{thm: transitionmatrix}. Then for $N=o(\sqrt{M})$ (i.e., $N/\sqrt{M} \to 0$ as $M\to+\infty$),
\begin{align*}
	\lim_{N,M\rightarrow+\infty}E^{\mathbb{P}_{\mu_{N}}}[\Vert\mathbb{K}\Vert^{2}_{1}]=0,
\end{align*}
which implies
\begin{align*}
	\lim_{N,M\rightarrow+\infty}E^{\mathbb{P}_{\mu_{N}}}[\rho(\mathbb{K})]=0.
\end{align*}

