[Proposition 13 of arXiv:2609.04143, 'The Geometry of Real Anisotropic Bohnenblust--Hille Constants'] Let $\mathbf q=(q_1,\ldots,q_m)$ be a Bohnenblust--Hille exponent and put $p=\min_i q_i$. For every integer $r\ge0$, set
\[
\mathbf q^{[r]}=(q_1,\ldots,q_m,\underbrace{2,\ldots,2}_{r\text{ times}}).
\]
Then
\begin{equation}
2^{r(1/p-1/2)}C_{\mathbf q}^{(m)} \le
C_{\mathbf q^{[r]}}^{(m+r)} \le A_p^{-r}C_{\mathbf q}^{(m)}.
\end{equation}
If $p\le p_{\mathrm H}$, then
\begin{equation}
C_{\mathbf q^{[r]}}^{(m+r)} =2^{r(1/p-1/2)}C_{\mathbf q}^{(m)}.
\end{equation}

[Defi 26 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] We define the following classes of prefixes:
    \begin{equation}
        \begin{aligned}
        \mathcal A_{\rmleft}&=\bigcup_{1<M\leq K}\left\{x\in [k]_0^M: x[M]>\ileft^{(t)} ,\, x[t]\leq \ileft^{(t)},\, \forall 1<t<M

        \right\} \\
        &\quad\quad\quad\quad\bigcup \quad
        \left\{x\in [k]_0^K: x[t]\leq \ileft^{(t)},\, \forall 1<t\leq K\right\},\\
        \mathcal A_{\rmright}&=\bigcup_{1<M<K}\left\{x\in [k]_0^M: x[M]<\iright^{(t)} ,\, x[t]\geq \iright^{(t)},\, \forall 1<t<M

        \right\} \\
        &\quad\quad\quad\quad\bigcup \quad
        \left\{x\in [k]_0^M: x[t]\geq \iright^{(t)},\, \forall 1<t\leq K\right\}.
    \end{aligned}
    \end{equation}
    Moreover, we define
    \begin{equation}
        \begin{aligned}
        \widetilde {\mathcal A}_{\rmleft}&=
        \Big\{x\in \mathcal A_{\rmleft}:|\{t:x[t]< \ileft^{(t)}\}|<\frac{\mathsf{C}}{\log(1/\chi)}\log N\Big\},
        \\
        \widetilde{\mathcal A}_{\rmright}&=
        \Big\{x\in \mathcal A_{\rmright}^{(t)}:|\{t:x[t]> \iright^{(t)}\}|<\frac{\mathsf{C}}{\log(1/\chi)}\log N\Big\}.
    \end{aligned}
    \end{equation}

[Proposition 6 of arXiv:2603.28170, 'Stabilization time of finite configurations with a second class particle in discrete TASEP'] For $p>1/2$, we have that
\begin{equation}
\lim_{n\to\infty}\frac{\E(M)}n=0.
\end{equation}

