body:
[Prop Prop_SliceDerivativeOfUniversalDiracOperator of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] For every $({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Dir}\times\mathbf{Ram}$ the following hold:
  \begin{enumerate}
  \item

    For every $\dot{\mathbf{p}}_\mathrm{BG} = (\dot g;\dot \gamma^\mathrm{BG},\dot\nabla^\mathrm{BG};0) \in H_{\mathrm{BG};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}$
    \begin{equation*}
      \nabla_{\dot{\mathbf{p}}_\mathrm{BG}}^\mathbf{Sl} {\mathbf{D}}({\mathbf{p}},{\mathfrak l};\phi)
      =
      - \frac12 \sum_{i,j=1}^d \dot g(e_i,e_j) \gamma(e_i)\nabla_{e_j} \phi
      + \frac14\gamma\paren[\big]{(\nabla^*\dot g)^\sharp + \nabla(\tr_g\dot g)}\phi.
    \end{equation*}
  \item

    For every $\dot{\mathbf{p}}_\mathscr{G} = (0;[\xi,\gamma],-\nabla\xi;0) \in V_{\mathscr{G};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}$
    \begin{equation*}
      \nabla_{\dot{\mathbf{p}}_\mathscr{G}}^\mathbf{Sl} {\mathbf{D}}({\mathbf{p}},{\mathfrak l};\phi)
      =
      \sum_{i=1}^d \paren[\big]{
        [\xi,\gamma(e_i)] \nabla_{e_i} \phi
        - \gamma(e_i) (\nabla_{e_i}\xi) \phi
      }.
    \end{equation*}
  \item

    For every $\dot{\mathbf{p}}_\nabla = (0;0,\dot\nabla;0) \in V_{\nabla;{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}$
    \begin{equation*}
      \nabla_{\dot{\mathbf{p}}_\nabla}^\mathbf{Sl} {\mathbf{D}}({\mathbf{p}},{\mathfrak l};\phi)
      =
      \sum_{i=1}^d \gamma(e_i) \dot\nabla_{e_i}\phi.
    \end{equation*}    
  \end{enumerate}
  Moreover, $\nabla^\mathbf{Sl} \mathbf{res} = 0$.

