body:
[Proposition pr:cons-M of arXiv:2412.01489, 'One- and two-particle spectral gap identities for the symmetric inclusion process and rela'] Define, for all integers $k\ge 2$, 	the following \textquotedblleft restricted\textquotedblright\ annihilation operator $\hat{\mathfrak a}_k : \mathbb{R}^{\Omega_{k-1}}\to \mathbb{R}^{\Omega_k}$ as
	\begin{equation}
		\hat{\mathfrak a}_k g(\eta)\coloneqq \sum_{x\in V} \eta_x\,g(\eta-\delta_x)\; \text{,}\;\;\qquad g\in \mathbb{R}^{\Omega_{k-1}}\; \text{,}\;\;\eta\in \Omega_k\; \text{.} 
	\end{equation}
	Then, we have \begin{equation}
		M_{\hat\alpha,k}\,\hat{\mathfrak a}_k = \hat{\mathfrak a}_k\, M_{\hat\alpha,k-1}\; \text{.}
		\end{equation}

