[Definition def: def of good external field configuration event for cle singularity of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] Recall the definitions of  $\mathsf{a}_i(\tau),\mathsf{b}_i(\tau),\mathsf{c}_i(\tau), \mathsf{d}_i(\tau), \mathcal{F}_i(\tau)$ from Proposition~(prop: adding external field fluctuation of the paper). Recall that we have chosen $\kappa=10^{-5}.$ We define the event $\mathcal{A}_i\subset\mathbb{R}^{\Lambda_N}\otimes\{0,1\}^n$ to be the collection of pairs $(h,\tau)$ such that $$|\mathsf{a}_i(\tau)-\mathsf{b}_i(\tau)-\mathsf{c}_i(\tau)-\mathsf{d}_i(\tau)|\le ({\epsilon} M^{\frac{7}{8}})^{2.7}\mbox{  and  }|\mathsf{a}_i(\tau)|\le ({\epsilon} M^{\frac{7}{8}})^{0.9}$$ and let $\mathcal{A}=\cap_{i=1}^n\mathcal{A}_i$.  In addition, we define the following events \begin{equation*}
    \begin{aligned}
        \mathcal{B}&=\{(h,\tau):\sum_{i=1}^{n}(\frac{\mathsf{b}_i^2}{2}-\mathsf{b}_i)\ge c_7{\epsilon}^2M^{\frac{7}{4}}|\tau| +\sum_{i=1}^n\frac{{\mathbb{E}}\big(\mathsf{b}_i^2\mid \mathcal{F}_{i-1}\big)}{4} \},\\
    \mathcal{A}^*&=\{(h,\tau):|\sum_{i=1}^{n}(\mathsf{a}_i^2-\mathsf{b}_i^2)|\le 1\},
    \\
    \mathcal{C}&=\{(h,\tau):|\sum_{i=1}^{n}\mathsf{c}_i|\le 1\},~~~~
    \mathcal{D}=\Big\{(h,\tau):|\sum_{i=1}^{n}\mathsf{d}_i|\le \sqrt{\iota^{-2\kappa}\cdot \sum_{i=1}^{n}\sigma_i^2}\Big\}.
    \end{aligned}
\end{equation*}

[Lemma lem:distinguishedtight of arXiv:2506.02611, '\textbf{The tight length spectrum of large-genus random hyperbolic surfaces with many cusp'] The mapping (equation eq:forgethomotopy of the paper) gives rise to an injection
    \begin{align*}
        \bigsqcup_{\Gamma'\in \mathcal{C}^{\Gamma}_{g,n+p}/ \lambda_{g,n,p}^{-1}(\mathrm{Stab}_{g,n}(\Gamma))} \hat{\mathcal{M}}^{\mathrm{tight}}_{g,n,p}(\mathbf{L},\mathbf{K})^{[\Gamma']_{g,n+p}} \longrightarrow \mathcal{M}^{\mathrm{tight}}_{g,n,p}(\mathbf{L},\mathbf{K})^{[\Gamma]_{g,n}}
    \end{align*}
    with image of full Weil-Petersson measure.

[Lemma of arXiv:2507.19554, 'Full extremal process in four-dimensional membrane model'] For $i=1,...,K^4$, let $z_i$ be as in (prop:aux of the paper) and $z_i' \in V_{N}^{K, \delta, i}$ be measurable with respect to $\{h_x^f: x \in V_N^{K, i}\}$ such that $\lv z_i - z_i'\rv = o(N/K)$ as $N,K \rightarrow \infty$. Then for any $A \subset [0,1]^4$ open and non-empty 
    \begin{equation}
        \lim_{K\rightarrow \infty}\lim\sup_{N\rightarrow \infty} d\lp \max\{h_{z_i}^f + h_{z_i}^c: B^{K, i}\subset A\}, \max\{h_{z_i}^f + h_{z_i'}^c: B^{K, i}\subset A\}\rp = 0.
    \end{equation}
    where $d$ is the Levy metric for $\mbR$-valued random variables. (Proof in the paper; no proof environment follows the statement in the TeX.)

