[Theorem 9 of arXiv:2604.10705, '#1'] Let $F \in \mathscr{C}^{0,1}_l([0,T],\mathbb{R}^d)$, be differentiable in the direction of a Lipschitz and boundedness-preserving $\gamma$. Then $F \in \mathscr{C}^{1,1}_l([0,T],\mathbb{R}^d)$, and
\begin{align}
DF(t,x_{\wedge t}) &= D^\gamma F(t,x_{\wedge t})-\langle \nabla F(t,x_{\wedge t^-}), \gamma(t,x_{\wedge t})\rangle, \,\,\text{for a.e. $t \in [0,T]$}.
\end{align}
Thus, 
\begin{align}
    F(t+h,x_{\wedge t})-F(t,x_{\wedge t}) = \int_0^h DF(t+s, x_{\wedge t})\,\mathrm{d}s.
\end{align}
\noindent (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Theorem 7.1 of arXiv:2609.03411, 'Adjacent vertex distinguishing total chromatic number of graph products'] {\em Let $G$ and $H$ be two total colorable connected graphs. Let $k_{1}$ and $k_{2}$ be the vertex covering
numbers of $G$ and $H$, respectively. If either 
\begin{center}
    $\Delta(H) \leq \Delta(G)$ and $k_{1}+1 < k_{2}$ or $\Delta(G) \leq \Delta(H)$ and
$k_{2}+1 < k_{1}$ 
\end{center}
then $G \stackMath\mathbin{\stackinset{c}{0ex}{c}{0ex}{\ast}{\bigcirc}} H$ satisfies AVDTCC.}

