[Lemma lem:codiff-finite of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Let $X = I(f_1)$, $Y = I(f_2)$ be jointly S$\alpha$S with
$\alpha \in (1,2]$ and $f_1, f_2 \in L^\alpha(E,m)$. Then:
\begin{enumerate}[label=(\roman*)]
\item \textbf{Finiteness and bound.}
  \begin{equation}

  0 \leq \tau(X,Y) \leq 2\min\!\bigl(\|X\|_\alpha^\alpha,
  \|Y\|_\alpha^\alpha\bigr) < \infty.
  \end{equation}
\item \textbf{Symmetry.} $\tau(X,Y) = \tau(Y,X)$.
\item \textbf{Independence.} $X \perp Y \Rightarrow \tau(X,Y) = 0$.
\item \textbf{Gaussian case.} For $\alpha = 2$:
  $\tau(X,Y) = \mathrm{Cov}(X,Y)$.
\item \textbf{Integral formula.}
  \begin{equation}

  \tau(X,Y)
  = \int_E\!\bigl[|f_1|^\alpha + |f_2|^\alpha
    - |f_1 - f_2|^\alpha\bigr]\,dm.
  \end{equation}
\end{enumerate}

[Lemma lem:L2_convergence_drift of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] For any $T\ge r$, as $n\to\infty$, the following convergence holds almost surely,
	\begin{align*}
		\sup_{r\le x\le T} \left| \left(X^n(x)-\int_r^x b_n(X^n(u),u)\ensuremath{\mathrm{d}} u\right) - \left(X(x)-\int_r^x b(X(u),u)\ensuremath{\mathrm{d}} u\right) \right| \to 0.
	\end{align*}

[Proposition jo112 of arXiv:2411.18374, 'Drawdowns of diffusions'] For  $\alpha>\beta>0$
\begin{align}

&
\nonumber
{\bf P}_0\left(D^-_{H_\alpha}\leq \delta\,|\,  D^-_{H_\beta}= \rho\right)
=\begin{cases}
\displaystyle{\exp\left(-\int_\beta^\alpha\frac{dS(z)}{S(z)-S(z-\delta)}\right)},& \delta\geq\rho,\\
0,& \delta<\rho\\
