\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma induction-statement of arXiv:2607.22480, 'Distinguishability threshold for random geometric graphs'] Assume that $H\in \mathcal{E}$. Then for every $0\leq s\leq n-1$,
{\relscale{0.95}\begin{align*}
\mathbb{P}\Big[G(n,d,p)\big|_{[s+1,n]}\!=\!H_s\wedge \mathcal{F} \Big|\mathcal{G}_s\Big]
\leq \!\!\!\!\!\!\prod_{s<i<j\leq n}\!\!\!\!\!\Phi_{sij}
\exp\!\Big(Z_s + &\frac{\kappa_{\triangle}N_{\triangle}(H_s)}{\sqrt{d}}
+\frac{\kappa_\square N_{\square}(H_s)}{d}+\frac{\kappa_{\diamond} N_{\diamond}(H_s)}{d}
+ \widetilde O\Big((n\!-\!s)R_{n, d, p}\Big)\!\Big),
\end{align*}}
where $\kappa_\triangle=\frac{a^3}{p^3(1-p)^3}, \kappa_\square=\frac{a^4}{p^4(1-p)^4}-\frac{2a^6}{p^5(1-p)^5}$, and $\kappa_{\diamond}=\frac{a^5}{p^5(1-p)^5}\Big(z_p-\frac{a(1-2p)}{p(1-p)}\Big)$,
\[
\Phi_{sij}=
\begin{cases}
\Phi\Big(-z_p+\sqrt d\,\langle \pi_s(\boldsymbol{v}_i),\pi_s(\boldsymbol{v}_j)\rangle\Big),& ij\in E(H),\\[2mm]
\Phi\Big(z_p-\sqrt d\,\langle \pi_s(\boldsymbol{v}_i),\pi_s(\boldsymbol{v}_j)\rangle\Big),& ij\notin E(H),
\end{cases}
\]
and
$Z_s=\sum_{\substack{s<i< j\leq n\\s<r<n}}\lambda_{ij}\lambda_{ir}\lambda_{jr}(z_p-\lambda_{ij})\langle \pi_s(\boldsymbol{v}_i), \pi_s(\boldsymbol{v}_j)\rangle .$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2604.00742, 'Delayed Logistic equation as a limit\\ of long memory Markov chains'] For each $m,q \in \N_{0}$ and $T>0$, it almost surely holds that
	\begin{equation*}
		|\xi_{0}^{N}(m+q)-\xi_{0}^{N}(m)| \;\leq\; q H(T)\,,
	\end{equation*}
		where
	\begin{equation}
		H^{N}(T) \;:=\; \sup_{{s} \in [0,T]}\left\{ Y^{N}({s})+ Y^{N}({s})Z^{N}({s})\right\}.
	\end{equation}

