[Theorem 2 of arXiv:2506.15044, '2506.15044'] Let $\mathbb{B}$ be given by \eqref{B}, $\mathcal{D}$ be a class of processes, and $X,Y\in \mathcal{D}^\mathbb{B}$. Suppose that $(T_n,X^{(n)})$ is an FCS for $X\in \mathcal{D}^\mathbb{B}$  (resp. a CS for $X$), and that $(S_n)$ is an increasing sequence of stopping times with $S_n\uparrow T$ and $\bigcup\limits_{n=1}^{{+\infty}}\llbracket{0,S_n}\rrbracket\supseteq \mathbb{B}$.
\begin{itemize}
  \item[$(1)$] $X=Y$ if and only if $XI_{\mathbb{B}\llbracket{0,S_n}\rrbracket}=YI_{\mathbb{B}\llbracket{0,S_n}\rrbracket}$ for each $n\in \mathbf{N}^+$.
  \item[$(2)$] $X=X^{(k)}=X^{(l)}$ on $\mathbb{B}\llbracket{0,T_k}\rrbracket$ for any $k,\;l\in \mathbf{N}^+$ with $k\leq l$, i.e.,
      \begin{equation}
      XI_{\mathbb{B}\llbracket{0,T_k}\rrbracket}=X^{(k)}I_{\mathbb{B}\llbracket{0,T_k}\rrbracket}
      =X^{(l)}I_{\mathbb{B}\llbracket{0,T_k}\rrbracket}.
      \end{equation}
      Specially, $X^{(k)}I_{\llbracket{0}\rrbracket}=XI_{\llbracket{0}\rrbracket}$.
  \item[$(3)$] $(\tau_n,X^{(n)})$ is an FCS for $X\in \mathcal{D}^\mathbb{B}$ (resp. a CS for $X$), where $\tau_n=T_n\wedge S_n$ for each $n\in \mathbf{N}^+$.
  \item[$(4)$] Suppose that $\mathcal{D}$ satisfies the linearity: $aU+bV\in \mathcal{D}$ holds for all $U,V\in \mathcal{D}$ and all $a,b\in \mathbf{R}$.
      Then $aX+bY\in \mathcal{D}^\mathbb{B}$ holds for all $a,b\in \mathbf{R}$.
  \item[$(5)$] $X$ can be expressed as
      \begin{equation}
      X=\left(X_0I_{\llbracket{0}\rrbracket}+\sum\limits_{n=1}^{{+\infty}}X^{(n)}I_{\rrbracket{T_{n-1},T_n}
      \rrbracket}\right)\mathfrak{I}_\mathbb{B},\quad T_0=0.
      \end{equation}
      Furthermore, if $(S_n,\widetilde{X}^{(n)})$ is also an FCS for $X\in \mathcal{D}^\mathbb{B}$ (resp. a CS for $X$), then $X=\widetilde{X}$ where $\widetilde{X}$ is given by
      \begin{equation*}
      \widetilde{X}=\left(X_0I_{\llbracket{0}\rrbracket}+\sum\limits_{n=1}^{{+\infty}}\widetilde{X}^{(n)}I_{\rrbracket{S_{n-1},S_n}
      \rrbracket}\right)\mathfrak{I}_\mathbb{B},\quad S_0=0.
      \end{equation*}
      In this case, we say the expression of \eqref{x-expression} is independent of the choice of the FCS $(T_n,X^{(n)})$ for $X\in \mathcal{D}^\mathbb{B}$ (resp. the CS $(T_n,X^{(n)})$ for $X$).
      \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:vm of arXiv:2607.04002, 'Collisions of random walks in unimodular random graphs: applications to the random geometr'] For each $G \in \{ \mathcal G_\mathrm{SGil},\mathcal G_\mathrm{Del}, \mathcal G_\mathrm{Gab} \}$, the following holds:
\begin{enumerate}
    \item for~$d=2$, we have~$\mathscr I_e(G) = \{\mu_0,\mu_1\}$ almost surely;
    \item for~$d \ge 3$, we have~$\mathscr I_e(G) =  \{\mu_\alpha: \alpha \in [0,1]\}$ almost surely.
\end{enumerate}
For the long-range percolation cluster~$\mathcal C_\infty$, with the same assumptions as Theorem~(thm:long_range_cluster of the paper), the following holds:
\begin{enumerate}
    \item for~$d=1$ with~$s=2$, and for~$d=2$ with~$s \ge 4$, we have~$\mathscr I_e(\mathcal C_\infty) = \{ \mu_0, \mu_1 \}$ almost surely;
    \item for~$d = 1$ with~$s \in (1,2)$, and for~$d \ge 2$ with~$s \in (d, d+2)$, we have~$\mathscr I_e(\mathcal C_\infty) =  \{\mu_\alpha: \alpha \in [0,1]\}$ almost surely.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition explicit.V of arXiv:2607.10708, 'A class of Markov processes with resetting and applications to cybersecurity'] Under Assumption~(ass_ex of the paper), with  $\alpha = 1/\theta$ and $\eta(A) = c/A$, the value function is equal to 

\begin{equation}
    V = \frac{ \alpha \beta (2 \alpha^2 + A_*^2 +2 \alpha A_* - \beta^2)}{2 (\alpha + \beta)(\alpha + A_* - \beta)} + \frac{c}{A_*}

\end{equation}
    where

\begin{equation}
      A_* =\frac{\alpha ^2 \beta ^2+4 c^2 \left(\alpha ^2-\beta ^2\right)^2-4 \alpha  \beta  c \left(\alpha ^2-\beta ^2\right)-4 c \rho_1 \left(\alpha ^2-\beta ^2\right)+\rho_1^2-\alpha  \beta  \rho_1}{6 c (\alpha +\beta ) \rho_1}

\end{equation}
    where
    \begin{align*}
      \rho_1^3 =&-\alpha ^3 \beta ^3+8 c^3 \left(\alpha ^2-\beta ^2\right)^3+6 \alpha  \beta  c^2 (\alpha +\beta )^2 \left(7 \alpha ^2+4 \alpha  \beta -2 \beta ^2\right)\\
      &+6 \alpha ^2 \beta ^2 c (\alpha -\beta ) (\alpha +\beta )
      +6 \sqrt{3} \sqrt{\alpha ^3 \beta  c^2 (\alpha +\beta )^2 \rho_2}\\
      \rho_2 =& -\alpha ^3 \beta ^3+8 c^3 \left(\alpha ^2-\beta ^2\right)^3+3 \alpha  \beta  c^2 (\alpha +\beta )^2 (\alpha +2 \beta ) (5 \alpha -2 \beta )\\
      &+6 \alpha ^2 \beta ^2 c (\alpha -\beta ) (\alpha +\beta ).
    \end{align*}

