[Lemma lem: more refined R_3 estimate of arXiv:2603.10738, 'Pairwise Negative Correlation for Uniform Spanning\\ Subgraphs of the Complete Graph'] For $R_3$, we have the following asymptotic behaviour
	\begin{align}
		R_3
		&=\sqrt{2\pi}\,n^{\,n+\frac{3k-5}{2}}
		\Bigg\{
		\frac{9k\,\chi_k}{2^{\frac{3k+2}{2}}\Gamma\!\left(\frac{3k+2}{2}\right)}
		\,+\frac{3(3k-1)\big(\tilde{\chi}_k+k\chi_k-3(k-1)\chi_{k-1}\big)}{2^{\frac{3k+1}{2}}\Gamma\!\left(\frac{3k+1}{2}\right)}\,n^{-\frac12}\nonumber
		\\
		&\qquad+\frac{1}{2^{\frac{3k}{2}}\Gamma\!\left(\frac{3k}{2}\right)}
		\Bigg(
		3(3k-2)\hat{\chi}_k+(3k-1)(3k-2)\tilde{\chi}_k-3(3k-4)(3k-2)\tilde{\chi}_{k-1}\nonumber\\\nonumber
		&\qquad\qquad
		-3(k-1)(3k-4)(3k-2)\chi_{k-1}
		+\frac{3}{2}(k-2)(3k-4)(3k-2)\chi_{k-2}
		\\&\qquad\qquad+\frac14(18k^3-9k^2+34k+37)\chi_k
		\Bigg)\,n^{-1}
	    \,+O\!\left(n^{-\frac32}\right)
		\Bigg\}.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2606.31528, 'Well-posedness and stationary distribution of free stochastic differential equations'] \cite[Theorem 3.1]{karginFreeStochasticDifferential2011}
Suppose that $\alpha, \beta^i,$ and $\gamma^i$ $(i=1,2,\ldots,l)$ are locally operator Lipschitz. Then there exist a sufficient small $T_0>0$ and a family of operators $U_t$ defined for
all $t \in [ 0, T_0),$ such that $U_t$ is a unique solution to \eqref{eq:fSDE} for $t < T_0.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma recursion of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Let parameters $\gamma$, $\theta$, $\zeta$, and $\eta$ be chosen according to (equation def: epsilon_gamma_zeta of the paper)-(equation def: theta_eta of the paper), and fix $\delta \in (0, 1/2)$. 
Then, there exists a positive constant $\beta_0$ such that $\beta_1 \ge \beta_0$ implies that
\begin{align}
    a_k \le \exp\left(- \beta_1 c^{k+1} m_k^{\zeta(2d\zeta - s)} \right)
\end{align}
holds for any $k \in \{0, ..., k_0\}$, where $c$ is a positive constant depending only on $\zeta, \delta, d, s$.

