body:
[Lemma lem: facts of T(z) of arXiv:2603.10738, 'Pairwise Negative Correlation for Uniform Spanning\\ Subgraphs of the Complete Graph'] The formal power series $T(z)\coloneq \sum_{n\;\geqslant\;1} n^{n-1}\frac{z^n}{n!}$ has the following properties:
	\begin{enumerate}
		\item[(1)] It is well-known (see, e.g., equation~(44), p.~127 of [FS2009]) that $T(z)$ satisfies 
		\begin{equation}
		T(z)=ze^{T(z)}\,.
		\end{equation}


		\item[(2)] The derivative of $T(z)$ satisfies(see, e.g., formula~(2.7) in the proof of Lemma~2.1 of [Stark2011])
		\begin{equation}
		T'(z)=\frac{T(z)}{z\big[1-T(z)\big]}\,.
		\end{equation}

		\item[(3)] For an integer $k\in[1,n]$, we have\footnote{Here and in the sequel, we use $\big[z^n\big]f(z)\coloneq f_n$ to denote the coefficient of $z^n$ in the formal power series $f(z)=\sum_{n\;\geqslant\;0}f_nz^n$.}  (see, e.g., Proposition~1 of [FGKP1995])
		\begin{equation}
		\big[z^n\big]T^k(z)=\frac{kn^{n-k-1}}{(n-k)!}.
		\end{equation}

		\item[(4)] For an integer $k\in[1,n]$, we have (see, e.g.,  formula~(2.13) in Lemma~2.3 of [Stark2011]) 
		\begin{equation}
		\big[z^n\big]\frac{T^k(z)}{1-T(z)}=\frac{n^{n-k}}{(n-k)!}\,.
		\end{equation}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:subdivision of arXiv:2609.01672, '\textbf{All-Minors Matrix-Tree Theory for Superport Networks:\\ Completed Quotient-Inciden'] For every \(X\subseteq V\), put \(R_X:=V\setminus X\),
\(S_X:=S_c(G)-R_X\), and \(S_{X,C}:=S_c(G)-S(C)-R_X\). Then
\begin{align}
\det L_c[X,X]
={}&m(S_X,|X|)\notag\\
&+\sum_{\substack{C\in\mathcal C(G)\\V(C)\subseteq X}}
 (-2)^{p(C)}c(C)\notag\\
&\qquad\times m(S_{X,C},|X|-|C|).

\end{align}

