[Proposition 1 ({Hinrichs--Kolb--Wachtel \cite{HKW2020}}) of arXiv:2608.17927, 'Near-unit-root persistence of symmetric stable \\ autoregressive sequences'] Symmetric $\alpha$-stable innovations satisfy the hypotheses of \cite[Theorem~1]{HKW2020}. Specifically, $\EE[\log{(1+|\xi_{1}|)}] < \infty$, $\EE[(\xi_{1}^{+})^{\delta}] < \infty$ for every $0 < \delta < \alpha$, and $\PP(\xi_{1} > 0)\PP(\xi_{1} < 0) > 0$. Then the following holds:
\begin{enumerate}[label=\textup{(\roman*)}]
\item The limit
\begin{equation}

\Lambda(a,\alpha) \deq
-\lim_{n \to \infty}\,\frac{1}{n}\log{Q_{n}(x;a,\alpha,\sigma)}
\end{equation}
exists in $(0,\infty)$ and is the same for every fixed starting point $x > 0$.
\item Writing $\pi$ for the stationary law of \eqref{eq:ar1},
\begin{equation}

-\lim_{n \to \infty}\,\frac{1}{n} \log{\PP_{\pi}(X_{0} > 0,X_{1} > 0,\ldots,X_{n} > 0)}
= \Lambda(a,\alpha).
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:vax of arXiv:2411.05369, 'Stochastic games of parental vaccination decision making and bounded rationality'] If $\bar{I}(t)\xrightarrow[]{t\to\infty} I_0$, then $x(t)$ has an almost sure logistic stable equilibrium at $0$ and $1$ under the following conditions:
\begin{enumerate}
    \item If $\omega+\kappa\frac{\sigma_2^2-\sigma_3^2}{2}>\max(I_0-\delta,\delta)$, then $x(t)\xrightarrow[]{t\to\infty} 0$ logistically almost surely, and
    \item If $\omega+\kappa\frac{\sigma_2^2-\sigma_3^2}{2}<\min(I_0-\delta,\delta)$, then $x(t)\xrightarrow[]{t\to\infty} 1$ logistically almost surely, and also, $I(t)\xrightarrow[]{t\to\infty} 0$ and $S(t)\xrightarrow[]{t\to\infty} 0$ $a.s.$ whether $R_0^s$ is more or less than one.
\end{enumerate}

