[Lemma 25 of arXiv:2608.25772, 'Propagation of Chaos and Gaussian Fluctuations for Mean-field Coupled Maps'] For any $\varphi\in H^3(\T)$, we have
    \begin{equation}
        \Vert\varphi\circ F_{\bar{\rho}_t}\Vert_{H^3}\leq C\Vert\varphi\Vert_{H^3},
    \end{equation}
    where the constant $C>0$ depends on $F,\Delta$ and $\| h\|_{C^3}$.

[Theorem 4 of arXiv:2607.28004, 'Folding representations of reflected diffusions'] Consider functions $b:I \to \R$ measurable, and $\sigma:I \to (0,\infty)$ satisfying the assumptions of Lemma~\ref{lem:ODE_nu}. Further, suppose that the function $\zeta$ of \eqref{eq:zeta_halfline} is bounded on $I$. Then, \begin{enumerate}[label = (\roman*),noitemsep]
        \item  the unique global solution $(f,\nu)$, with $f:I \to I$ belonging to  $W^{2,1}(I)$ and $\nu \in (0,\infty)$, to the equation \eqref{eq:nonlinear_ODE_nu}, is given by
        \begin{equation} 
           f(y) = g^{-1}\bigg(\frac{y}{\nu}\bigg) \quad \text{for } y \in I, \qquad   \nu = \bigg(\int_0^1 \frac{1}{\sigma(u)}du\bigg)^{-1},
        \end{equation}
         where $g$ is the function in \eqref{eq:g};

        \item  the SDE \eqref{eq:X_SDE_nu},
        with $\nu$ given by \eqref{eq:nu}, with  
        \begin{equation} 
          \alpha(x) = \nu\sign\big(x-\Even(x)\big)\,\zeta\Big(f\big(|x-\Even(x)|\big)\Big),  \qquad \text{for a.e.~}  x \in \R,
        \end{equation}
        and with $\zeta$ as in \eqref{eq:zeta_halfline},
        has a pathwise unique, strong solution for every initial value $X_0 \in \R$;
        \item the process $Y = f(|X-\Even(X)|)$ satisfies the RSDE \eqref{eq:RSDE} with initial condition $Y_0 = f(|X_0-\Even(X_0)|)$, finite variation process
        \begin{equation}  \Phi = \frac{1}{\nu}\sum_{n \in \Z}\big(\sigma(0)L^{2n}(X) - \sigma(1)L^{2n+1}(X)\big),
        \end{equation} and Brownian Motion $W = \int_0^\cdot \mathrm{sign}(X_t-\Even(X_t))dB_t$. 
    \end{enumerate}

