[Theorem 37 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Suppose $\mu$ satisfies Assumption \ref{as:mu_tail} for some $\alpha > 0$.  There exists a constant $C = C(\mu) >0$ such that for any $\delta > 0$, if $\beta \leq C (n/\log n)^{1/\alpha}$ and $n$ is sufficiently large, then 
    \begin{equation}
        \widehat \P \Big( C_1(\delta)^{-1} n^{1/2}\leq \diam(\cT^\omega_{n,                \beta})\leq C_1(\delta) n^{1/2} \Big) \geq 1-\delta,
    \end{equation}
    where $C_1(\delta)>0$ is a constant depending only on $\delta$. On the other hand, if $\beta \geq n^{1/\alpha + 1/3} \log n$ and $n$ is sufficiently large, then
    \begin{equation}
        \widehat \P \Big( C_2(\delta)^{-1} n^{1/3}\leq \diam(\cT^\omega_{n, \beta})\leq C_2(\delta) n^{1/3}   \Big) \geq 1-\delta,
    \end{equation}
    where $C_2(\delta)>0$ is a constant depending only on $\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma L:Gronwall of arXiv:2412.03521, 'On ergodic properties of stochastic PDEs'] Let $g(\cdot)$ be a nonnegative and monotone function on $[0,\infty)$ that
  decreases to $0$ as $t\to\infty$, and such that $g(0)<\infty$. Let $k(\cdot)$
  be a nonnegative and integrable function on $[0,\infty)$ and define
  \begin{align}
    h(t) \coloneqq \int_t^{\infty} k (s) \ensuremath{\mathrm{d}} s.
  \end{align}
  Then, we have:

  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\roman*)}]
    \setlength\itemsep{.1in}

    \item For any nonnegative integer $n$ and $t\ge 0$, it
      holds that
      \begin{align}
        \int_0^t g \left(\frac{t - s}{2^n}\right) k(s) \ensuremath{\mathrm{d}} s
        \le g(0) h \left(\frac{t}{2^{n + 1}}\right) + h(0) g \left(\frac{t}{2^{n + 1}}\right).
      \end{align}
      In particular, when $g = h$ as defined in (equation E:def-gnr-H of the paper), the above
      inequality~(equation E:g*h of the paper) reduces to
      \begin{align}
        \int_0^t h \left(\frac{t - s}{2^n}\right) k(s) \ensuremath{\mathrm{d}} s
        \le 2 h(0) h \left(\frac{t}{2^{n + 1}}\right).
      \end{align}

    \item For any nonnegative integer $n$ and $t\ge 0$, it
      holds that
      \begin{align}
        \int_{[0, t]^{n}_<}
            & \ensuremath{\mathrm{d}} u_n \cdots \ensuremath{\mathrm{d}} u_1\:  g \left(t - u_n \right) \prod_{i = 1}^n k(u_{i} - u_{i - 1} ) \nonumber \\
        \le & \left( 2^{n} - 1\right) g(0) h(0)^{n-1} h \left(\frac{t}{2^{n}}\right) + h(0)^n g \left(\frac{t}{2^{n}}\right),
      \end{align}
      where $[0, t]_<^{n} \coloneqq \left\{(s_1,\dots, s_n) \in [0,t]^n; 0 <
      s_1< \dots < s_n <t\right\}$ and we have used the convention that $u_0
      \equiv 0$.

    \item Let $f$ be a function on $[0,\infty)$ such that
      \begin{align*}
        f(t) \le g(t) + \beta \int_{0}^t f(t - s) k(s) \ensuremath{\mathrm{d}} s, \quad \text{for all $t\ge 0$ with $\beta>0$}.
      \end{align*}
      Then, whenever $\beta < [2 h(0)]^{-1}$, the following convergence is true,
      \begin{align}
        \lim_{t\to \infty} f(t) = 0.
      \end{align}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition defn:PHlamzeta of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] The state space is $\Omega_H = 2^{V(H)}$. For any $y \in \Omega$, we set
\[P_{H,\lambda,\zeta} y = P^u_{H,\lambda,\zeta} y\] 
where $u \in V(H)$ is chosen uniformly at random, and
\[
P_{H,\lambda,\zeta}^u y = \begin{cases}
y \cup \{u\} &\text{w.p. $\frac{\lambda (1 - \zeta)^{d(v)}}{1 + \lambda (1 - \zeta)^{d(v)}}$, and}\\
y \setminus \{u\} &\text{w.p. $\frac{1}{1 + \lambda (1 - \zeta)^{d(v)}}$}
\end{cases}
\]
where $d(v)=d_y(v)$ denotes the degree of $v$ in the subgraph of $H$ induced by $y\cup \{v\}$.

