		\begin{equation}

			\forall \mathfrak{p} \in (0,1), \qquad \xi \cdot {\overbracket[1pt][-1pt]{\mathbf{a}}}^{(k)}_m(\mathfrak{p}) \xi =  \frac{k!}{(1-\mathfrak{p})^k} \sum_{\substack{|F|=k\\ F\subseteq E_d({\scaleobj{1}{\square}}_m)}} \mathbb{E}_{\mathfrak{p}}\left[D_F \mathscr{E}_{m,\xi}(\mathbf{a}) \right].
		\end{equation}

