\begin{align}
	\mathbb E\left[N^w_n(u)^m\right]
	=O\bigl(n^{\lfloor\frac{m}{2}\rfloor}\bigr).
\end{align}

[Lemma lem:collision of arXiv:2608.23638, 'Replicable Conformal Prediction'] For fixed $a,b\in\mathbb R$ and
$u\sim\operatorname{Unif}[0,\beta)$,
\begin{equation}
\mathbb{P}_u\{\operatorname{rd}_u(a)\ne\operatorname{rd}_u(b)\}
=\frac{\min\{|a-b|,\beta\}}{\beta}.
\end{equation}

[Cor ineq of arXiv:2412.03450, 'On intermediate levels of nested occupancy scheme in random environment generated by stick'] Suppose (equation eq:estim of the paper). Then, for $t\geq 0$ and positive integer $j$ satisfying (equation ineq:condition of the paper),
\begin{equation}
|V_j(t)-\rho_j t^{\alpha j}|\leq 
2D C^{j-1} j\frac{(\Gamma(\alpha+1))^{j-1}\Gamma(\beta+1)}{\Gamma(\alpha (j-1)+\beta+1)} t^{\alpha(j-1) + \beta}
\end{equation}
and
\begin{equation}
V_j(t) \leq 5 \rho_j t^{\alpha j}, \quad t \geq 0.
\end{equation}

