[Proposition 4 of arXiv:2604.10820, 'A Strict Gap Between Relaxed and Partition-Constrained\\ Spectral Compression in a Six-Sta'] The number of partitions into three nonempty cells of a six-element state space is the Stirling number of the second kind
\begin{equation*}
S(6,3)=90.
\end{equation*}

[Lemma of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] Consider any $r_1, \ldots, r_k \in \alpha \times \alpha$ such that ${\textsc{Supp}}(r_1, \ldots, r_k) = \alpha$. Then, for any $\beta \subsetneq \alpha$ and all $\mathbf{t}$, we have 
    \begin{align*}
         \Phi_{\beta}^{(r_1, \ldots, r_k)}(\mathbf{t}) = 0.
    \end{align*}

[Corollary 9 (Expected excess risk bound for kTULA) of arXiv:2605.24937, '2605.24937'] Assume \hyperref[ass:PJG]{\textup{(A1)}}--\hyperref[ass:LSI]{\textup{(A6)}}, and let $\lambda\in(0,\lambda_{\max}^{\mathrm{kTULA}}]$. Let $(\widehat X_n)_{n\ge0}$ be the \eqref{eq:kTULA} iterates. Fix $\mu:=\Law(\widehat X_0)$ such that $R_0:=R_2(\mu\|\pi_\beta)<\infty$.
Then there exist constants $C_0,C_1,C_2,C_3>0$, independent of $N$ and $\lambda$, such that for all $N\in\mathbb N$,
\begin{equation}
\E\!\bigl[u(\widehat X_N)\bigr]-\inf_{\theta\in\R^d}u(\theta)
\;\le\;
C_1\,e^{-C_0N\lambda}
+
C_2\,\lambda\,\sqrt{(N\lambda)\vee\log N}
+
C_3\frac{\log \beta}{\beta}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 17 of arXiv:2604.01701, '\bf Chung-type laws of the iterated logarithm for $m$-fold weighted integrated fractional '] Let $  X(t)$ be a continuous, centered, self-similar Gaussian process of index $\tau>0$.
Suppose that $1< q\le\infty$ and
\begin{equation}-\log \pr\Big(\sup_{0\le t\le 1} \left|  X(t)\right|<\epsilon\Big)\le c_0\epsilon^{-1/\tau}+o(\epsilon^{-1/\tau}).   
\end{equation} 
 Assume that  $\int_0^t|w(s)|s^{\tau}ds<\infty$, and $\Delta$ is a sub-interval of $(0,\infty)$. Suppose that $\Delta$ is bounded   when $q<\infty$.
 Then   
\begin{equation}-\log \pr\left( \left\|I\big(wX\big)\right\|_{L^q(\Delta)}<\epsilon\right)\le C\|w\mathbbm{I}_{\Delta}\|_{r,\tau+1,q}^{1/(\tau+1)}\cdot \epsilon^{-1/(\tau+1)}+o\big(\epsilon^{-1/(\tau+1)}\big),
\end{equation}
where $\frac{1}{r}=\tau+1+\frac{1}{q}$ and the constant $C>0$ does not depend on $w$.   Moreover,  we assume that $w$ is almost everywhere continuous on $\Delta$ when $q=\infty$, and $\Delta$ is bounded when $1<q<\infty$. Then
\begin{equation}\log \pr\left( \left\|I\big(wX\big)-wI(X)\right\|_{L^q(\Delta)}<\epsilon\right)=o\big(\epsilon^{-1/(\tau+1)}\big) \text{ as }  \epsilon\to 0,
\end{equation}
if $\|w\mathbbm{I}_{\Delta}\|_{r,\tau+1,q}<\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2605.11801, 'A non-local singular non-linear Fokker-Planck PDE'] Let $f\in \shc^{\g}$ for some $\gamma \in \R$. Then for any $\theta\geq 0$ there exists a constant $c$ such that
    \begin{equation}
    \|P_tf\|_{\shc^{2\theta+\g}}\leq c t^{-\theta} \|f\|_{\shc^\g},        
    \end{equation}
    for all $t>0$. 
  Moreover for $f\in\shc^{2\theta+\g}$ and for all $\theta \in (0,1)$ we have
    \begin{equation}
        \|P_tf-f\|_{\shc^\g}\leq ct^{\theta} \|f\|_{\shc^{2\theta+\g}}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm of arXiv:2411.13419, 'Forest Fire Model on $\Z_{+}$ with Delays'] Let $c\le 1$. Assume that either 
\begin{itemize}
    \item[(a)] $\Delta_x\le c/x$ \ for all large $x$, or
    \item[(b)] for some $C>0$ we have $|\Delta_x|\le C$ for all~$x$,  $\sum_x Var(\Delta_x)<\infty$, $\left|\sum_x \left[\mathbb{E}\Delta_x-\frac{c}x\right]\right|<\infty$.
\end{itemize}
Then the infinite fire does not occur a.s. i.e., $\mathbb{P}(n_k<\infty\text{ for all }k )=1$.
\\[2mm]
Conversely, if $c>1$, and either 
\begin{itemize}
    \item[(c)] $\Delta_x> c/x$ \ for all large $x$, or
    \item[(d)] $\mathbb{E} \Delta_x=\frac {c+o(1)}x$  and $\displaystyle \mathbb{P}\left(\lim_{x\to\infty}\, |\Delta_x|\sqrt{x}=0\right)=1$.
\end{itemize}
Then the infinite fire occurs a.s.

