[Cor 53 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $\eta>0$, $k\geq 0$, $j\geq 1$, $l\geq 0$, with $j+2l\leq 2k+1$.
Let $b\in2\lambda\N$ with $b\geq v + 2\lambda$.
Then
\begin{multline*}
\E\Big[\big\Vert
\ell_{0,b}^{2k+1-j-2l}V_{A_{0,b}}^{l}
\,:\Phi_{D\setminus A_{0,b}}^{j} :
\ind_{\{z\in A_{0,b}\text{~or~}\ell_{0,b}(z)=b\}}
\big\Vert_{H^{-\eta}(\C)}^{2}
\Big]
\leq
\\
C_{j,l}(1\vee\diam(D)^{j/4})
b^{4k+2-2j - 4l}
\\
\times
\int_{D^{2}}
e^{-(b-v-2\lambda)^{2}/(2\log(2)/\pi + 2 G_{D}(z,w))}
\Big(
1\vee\log\Big(\dfrac{2(1\vee\diam(D))}{\vert w-z\vert}\Big)^{j+2l}
\Big)
\LK_{\eta}(\vert w-z\vert)
\,d^{2}z\,d^{2}w,
\end{multline*}
where $C_{j,l}>0$ is a constant depending only on $j$ and $l$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2512.10761, 'Special times for the point set process of the Brownian Net'] For any deterministic $t\in\R$:
     \begin{enumerate}[label=(\alph*)]
         \item Almost surely, for any point in $\R\times\{t\}$ either there is no incoming path at that point or there is an incoming pair $(l,r)\in (\mathcal{W}^l,\mathcal{W}^r)$ at that point and both cases occur.
         \item Let $S^t:=\{x\in\R:\text{There exists an incoming pair $(l,r)$ at $(x,t)$}\}$ and let $\mathcal{F}_t$ be the sigma algebra generated by $\{\left(\pi(s)\right)_{s\in[\sigma_\pi,t]}:\pi\in\mathcal{N},\sigma_\pi\leq t\}.$ Then almost surely for any $x\in S^t$ the process $D^{l,r}_t:=\frac{r_t-l_t}{\sqrt{2}}$ with $(l,r)$ being an incoming pair at $(x,t)$ has the following conditional distribution:
         \begin{equation*}
             \pr[D^{l,r}_{t+s}\in dy\bigm|\mathcal{F}_t]=P_s(0,y)dy,
         \end{equation*}
         where $P_s(0,y)$ is given by (\ref{transition density}).
     \end{enumerate}

[Lemma 12 of arXiv:2604.26898, '\bf Stochastic Scaling Limits and Synchronization \\by Noise in Deep Transformer Models'] For the remainder $\mathcal{R}_\ell^i$ defined in Lemma \ref{lem:norm_res}, there exists a constant $\mathsf c > 0$ such that for all $\ell \in \{1,  \dots, L\}$ and $i \in \{1, \dots, N\}$ and all $m \in \mathbb N$:
    \begin{equ}
        \E\left[|\mathcal{R}_\ell^i|^2\right] \leq \mathsf c\dt^3.
    \end{equ}

