body:
[Lem 8 of arXiv:2606.14917, 'The Ornstein--Uhlenbeck process on $\scr P_2$ \\with a volatility operator'] There exists a family of Hilbert spaces ${(H_\mu)}_{\mu\in \P_2}$ such that:
	\begin{itemize}[leftmargin=*]
	\item[]a) $T_\mu\hookrightarrow H_\mu$ is densely, continuously embedded for $\mu\in\P_2$ and the embedding $T_\mu\hookrightarrow H_\mu$ is a Hilbert-Schmidt operator for $\Lam$-a.e.~$\mu\in \P_2$.
	\item[]b)  $\P_2\ni \mu\mapsto{\la\eta(\mu,\cdot),\xi(\mu,\cdot )\ra}_{H_\mu}\in\RR$ is $\Lam$-integrable for $\eta,\xi\in \int_{\P_2}^\oplus T_\bullet \d\Lam$ and 
	\begin{equation}
		\int_{\P_2}{\la\eta(\mu,\cdot),\xi(\mu,\cdot )\ra}_{H_\mu}\Lam(\d\mu)=\int_{T_\lam} \big\la A^{-1}J\eta(f,\cdot ),J\xi(f,\cdot )\big\ra_{T_\lam}G(\d f).
	\end{equation}
	\end{itemize}

