[Thm 9 of arXiv:2604.26499, 'Spectrum of Random Matrices with Exploding Moments'] \cite[Theorem 9]{weaver1985centrosymmetric}
 \begin{enumerate}[label=(\alph*)]

     \item  If $M=\left(\begin{array}{ll}A & B \\ C & D\end{array}\right)$ is an $N \times N$ centrosymmetric matrix with $N=2s$ and $A, B, C$, and $D \text{ are } s\times$ s matrices, then $M$ is orthogonally similar to
     \begin{align*}
         Q^T M Q=\left(\begin{array}{cc}
    A+J C & 0 \\
    0 & A-J C
\end{array}\right),
     \end{align*}
     where 
     \begin{align*}
         Q  =  \sqrt{\frac{1}{2}}\left(\begin{array}{ll}\mathbb{I} & -J \\ J & \mathbb{I}\end{array}\right).
     \end{align*}

     \item If $M=\left(\begin{array}{lll}A & x & B \\ y & q & yJ \\ C & Jx & D\end{array}\right)$ is an $N \times N$ centrosymmetric matrix with $N=2s+1$, and $A, B, C, D$  are  $s \times s$ matrices, $x$ is $s \times 1$ matrix, $y$ is $1 \times s$ matrix, and $q$ is a scalar, then $M$ is orthogonally similar to
     \begin{align*}
         Q^{T} M Q=\left(\begin{array}{ccc}
			A+J C & \sqrt{2} x & 0 \\
			\sqrt{2} y & q & 0 \\
			0 & 0 & A-J C
		\end{array}\right),
     \end{align*}
		where
  \begin{align*}
      Q  =  \sqrt{\frac{1}{2}}\left(\begin{array}{lll} \mathbb{I} & 0 & -J \\ 0 & \sqrt{2} & 0\\ J & 0 & \mathbb{I}\end{array}\right).
  \end{align*}
 \end{enumerate}
 Here $\mathbb{I}$ is the identity matrix and $J$ is the counter-identity matrix. In both cases $Q^TQ=\mathbb{I}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[OPEN PROBLEM - not a proved fact. Stated in arXiv:2506.13587, 'Non-exchangeable mean-field theory for adaptive weights: propagation of dissociatedness and graphon sampling l' (conj environment).] Adopt the setting of Theorem~(thm:empirical_data_stability), but for $k \in \mathbb{N}$, assume the $N_k$-particle system $\bm{\mathcal{Y}}^{(k)}(t) = ((\bm{X}^{(k)}_{i}(t))_{i \in [N_k]}, (\bm{W}^{(k)}_{i,j}(t))_{i,j \in [N_k]})$ evolves according to the SDE system (eqn:decay_SDEs) with $\epsilon = 1$. 
Let $\overline{\mathcal{Y}}(t) = (\overline{\mathsf{X}}(t), \overline{\mathsf{W}}(t))$ denote the structural limit solution to the McKean-Vlasov SDEs (eqn:main_McKean_Vlasov) in the sense of Proposition~(prop:well_posedness_McKean_Vlasov) (corresponding to the particular dynamics (eqn:decay_SDEs)).
Moreover, assume
\begin{equation*}
\begin{aligned}
& \lim_{k \to \infty} \mathbb{E} \Big[ \gamma_{W_1,\square}\big( \bm{\mathcal{Y}}^{(k)}(0), \overline{\mathcal{Y}}(0) \big) \Big] = 0.
\end{aligned}
\end{equation*}
Then, ``the convergence at $t \to \infty$ takes place in the stronger sense'', namely,
\begin{equation*}
\begin{aligned}
& \lim_{t \to \infty}
\limsup_{k \to \infty}
\E \Big[ \delta_{W_1,\square}\big( \bm{\mathcal{Y}}^{(k)}(t), \overline{\mathcal{Y}}(t) \big) \Big]= 0.
\end{aligned}
\end{equation*} (Verbatim from the paper's TeX; symbols are the source paper's. Stated as open/conjectural; no resolution of it was found in the paper's own text by the rules of problem_index.py - a paper may still prove special cases of a conjecture it states.)

[Thm {Conidis~\cite[Theorem 3.9 of arXiv:2609.00884, 'The weakness of typicality'] {conidisClassifyingModeltheoreticProperties2008}}]\label[theorem]{thm:amt-escape}
For every $\Delta^0_2$ function $f : \omega \to \omega$, there is a computable atomic theory~$T$
such that every atomic model~$\mathcal{M}$ of~$T$ computes a function $g : \omega \to \omega$ not dominated by~$f$. (Proof in the paper; no proof environment follows the statement in the TeX.)

