[Definition {\cite{MR773445}} of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] A characteristic function $f$ is said to be \textit{geometrically infinitely divisible} if for every $p\in(0,1)$ there exists a characteristic function $g_p$ such that
    \begin{align}
        f(\xi)=\frac{p\,g_p(\xi)}{1-(1-p)g_p(\xi)}.
    \end{align}

[Proposition 22 of arXiv:2609.03954, 'Galois representations ramified at one prime via relative deformation theory'] For every $j\ge j_0$ there exist continuous representations
\[
 \tau_j:G_{\{p\}}\longrightarrow\GG(\Z/p^j\Z)
\]
and
\[
 \varrho_{j+R}:G_{\{p\}}
 \longrightarrow\GG(\Z/p^{j+R}\Z)
\]
such that
\begin{enumerate}[label=\textup{(\arabic*)}]
\item $\varrho_{j+R}\pmod{p^j}=\tau_j$;
\item $\tau_{j+1}\pmod{p^j}=\tau_j$;
\item $\varrho_{j+R}\pmod{p^R}=\rho_R$;
\item $\tau_{j_0}=\rho_{2A}^*\pmod{p^{j_0}}$.
\end{enumerate}

[Proposition prop:Converse of arXiv:2509.04155, 'An Approach to Sub-Gaussian Heat Kernel Estimates via Analysis on Metric Spaces'] Let $1 \leq p \leq q$, $(\mathcal{F}_p,\Gamma_p,\Psi)$ be a $p$-energy structure and $\nu$ be a Borel measure on $X$. Assume that the pair $x_0 \in X$ and $R_0 \in (0,\diam(X))$ satisfies the following condition. There are constants $L_0,\sigma \geq 1$ such that, whenever $x \in X$ and $r > 0$ with
    \begin{equation*}
        B(x,r) \cap B(x_0,R_0) \neq \emptyset \text{ and } 0 < r \leq R_0,
    \end{equation*}
    it holds for every $f \in \mathcal{F}_p$,
    \begin{equation}
    \left(\int_{B(x,r)} \abs{\tilde{f} - f_{B(x,r)}}^{q} \, d\nu \right)^{\frac{1}{q}} \leq L_0 \left(\int_{B(x,\sigma r)} d\Gamma_p\Span{f} \right)^{\frac{1}{p}}.
    \end{equation}
    Then there is a constant $C \geq 1$ such that
    \begin{equation}
        \nu(B(x_0,R_0))^{\frac{1}{q}} \leq C L_0 \left( \frac{\mu(B(x_0,R_0))}{\Psi(x_0,R_0)} \right)^{\frac{1}{p}}.
    \end{equation}
    This result is quantitative in the sense that $C$ depends only on the constants in (eq:UCap of the paper), (equation eq:muDoubling of the paper), (equation eq:RadDiam of the paper), the constants associated to $\Psi$ in (equation eq:Psi of the paper), $\sigma,\, p$ and $q$.

