[Prp 40 of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] Under the above setting, where $\{X_l\}_{l \in \Z}$ is given by \eqref{fGn def}, the following holds for every $k \in \N_0$ and $r \in [1,\infty]$.
\begin{enumerate}[\normalfont(1)]
    \item When $m = 2$, 
    \begin{align}
        \norm{\rho_{F_n}^{} - \rho_{\cN}^{}}_{W^{k,r}(\R)} \propto
        \begin{cases}
            n^{-\frac{1}{2}} &\quad  \text{if \  $H \in (0,\frac{2}{3})$},\\
            n^{-\frac{1}{2}}(\log n)^2 &\quad \text{if \  $H = \frac{2}{3}$},\\
            n^{-\frac{9}{2}+ 6H} &\quad \text{if \  $H \in (\frac{2}{3}, \frac{3}{4})$}.
        \end{cases}
    \end{align}
    \item When $m = 3$, 
    \begin{align}
        \norm{\rho_{F_n}^{} - \rho_{\cN}^{}}_{W^{k,r}(\R)} \propto
        \begin{cases}
            n^{-1} &\quad  \text{if \  $H \in (0, \frac{3}{4})$},\\
            n^{-1}(\log n)^3 &\quad \text{if \  $H = \frac{3}{4}$},\\
            n^{-10+12H} &\quad \text{if \  $H \in (\frac{3}{4}, \frac{5}{6})$}.
        \end{cases}
    \end{align}
    \item When $m = 4$, 
    \begin{align}
        \norm{\rho_{F_n}^{} - \rho_{\cN}^{}}_{W^{k,r}(\R)} \propto
        \begin{cases}
            n^{-\frac{1}{2}} &\quad  \text{if \  $H \in (0,\frac{5}{6})$},\\
            n^{-\frac{1}{2}}(\log n)^2 &\quad \text{if \  $H = \frac{5}{6}$},\\
            n^{-\frac{21}{2} + 12H} &\quad \text{if \  $H \in (\frac{5}{6}, \frac{7}{8})$}.
        \end{cases}
    \end{align}
    \item When $m \geq 5$ is an odd integer,
    \begin{align}
        \norm{\rho_{F_n}^{} - \rho_{\cN}^{}}_{W^{k,r}(\R)} \propto
        \begin{cases}
            n^{-1} &\quad  \text{if \  $H \in (0,\frac{3}{4})$},\\
            n^{-1}(\log n) &\quad \text{if \  $H = \frac{3}{4}$},\\
            n^{4H-4} &\quad \text{if \  $H \in (\frac{3}{4}, 1-\frac{1}{2m-2})$},\\
            n^{4H-4}(\log n)^2 &\quad \text{if \  $H = 1-\frac{1}{2m-2}$},\\
            n^{2 -4m + 4mH} &\quad \text{if \  $H \in (1-\frac{1}{2m-2}, 1-\frac{1}{2m})$}.
        \end{cases}
    \end{align} 
    \item When $m \geq 6$ is an even integer, 
    \begin{align}
        \norm{\rho_{F_n}^{} - \rho_{\cN}^{}}_{W^{k,r}(\R)} \propto
        \begin{cases}
            n^{-\frac{1}{2}} &\quad  \text{if \  $H \in (0,\frac{7}{8}]$},\\
            n^{4H-4} &\quad \text{if \  $H \in [\frac{7}{8}, \frac{6m-11}{6m-8}]$},\\
            n^{\frac{3}{2} - 3m + 3mH} &\quad \text{if \  $H \in [\frac{6m-11}{6m-8}, 1-\frac{1}{2m})$}.
        \end{cases}
    \end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

