[Lemma lem: 445 of arXiv:2607.05848, 'Mesoscopic eigenvalue statistics for correlated random matrices'] We define the matrix $V=(V_{ij})$ by setting
\begin{equation}
	V_{ij}\equiv V_{ij}(z,w) \coloneqq \sum_{b} \big( \mathcal{B}_{z,w}^{-1}\mathcal{C}_{M,\widetilde{M}}\mathcal{S}[E^{jb}] \big)_{ib}.
\end{equation}
Then,
\begin{multline}
	\frac{\mathrm{i}}{\pi}\int_{\Omega_{0}}\frac{\partial\tilde{f}}{\partial\bar{z}}
	\Tr\mathcal{B}_{z}^{-1}[RM] \mathrm{d}^{2}z \\
	=
	\frac{2\lambda\phi(\lambda)}{\pi^{2}}
	\int_{\Omega_{0}}\int_{\Omega_{0}'}\frac{\partial\tilde{f}(z)}{\partial\bar{z}}\frac{\partial\tilde{f}(w)}{\partial\bar{w}}
	\partial_{w}\Tr (M'M^{-1}V) \mathrm{d}^{2}w \mathrm{d}^{2}z
	+ O_{\prec}\big( (1+|\lambda|)N^{-\epsilon_{0}/4} \big).
\end{multline}
Moreover,
\begin{equation}
	\int_{\Omega_{0}}\frac{\partial\tilde{f}}{\partial\bar{z}}
	\Tr\mathcal{B}_{z}^{-1}[Q^{(k)}M] \mathrm{d}^{2}z
	= O_{\prec}\Big( (1+|\lambda|)^{2}\eta_{0}^{1/2} + (N\eta_{0})^{-1/2} \Big), \quad k\in\{1,\dots,L-1\},
\end{equation}
and
\begin{equation}
	\int_{\Omega_{0}}\frac{\partial\tilde{f}}{\partial\bar{z}}
	\Tr\mathcal{B}_{z}^{-1}[\mathcal{E}^{(L)}M] \mathrm{d}^{2}z = O_{\prec}(\eta_{0}).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 49 (Critical split completion) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] The completion of \(\mathscr G_{\mathrm{fin}}(H)\) for the coordinate
quasi-gauge
\begin{equation}
 \|(x,A,Q)\|_{\mathrm{crit}}
 :=\|x\|_H+\|A\|_{1,\infty}+\|Q\|_1

\end{equation}
is canonically
\begin{equation}
 \mathscr G_{\mathrm{crit}}(H)
 =H\times\mathcal S^0_{1,\infty}(H)_{\mathrm{skew}}
       \times\mathcal S_1(H)_{\mathrm{sa}}.

\end{equation}
The product \eqref{cc:eq-critical-split-product} and inverse
\[
 (x,A,Q)^{-1}=(-x,-A,-Q)
\]
extend continuously and make this space a separable complete topological
group.  More precisely, there are an exponent
\(0<\vartheta\leq1\) and an equivalent quasi-norm
\(\|\cdot\|_{1,\infty,*}\) on
\(\mathcal S^0_{1,\infty}(H)\) such that
\[
 \|S+T\|_{1,\infty,*}^{\vartheta}
 \leq \|S\|_{1,\infty,*}^{\vartheta}
      +\|T\|_{1,\infty,*}^{\vartheta}.
\]
Consequently
\begin{align}
 d_{\mathrm{crit}}(g,h)
 :={}&\|x_g-x_h\|_H^{\vartheta}
 +\|A_g-A_h\|_{1,\infty,*}^{\vartheta}
 +\|Q_g-Q_h\|_1^{\vartheta}

\end{align}
is a compatible complete metric.  In particular,
\(\mathscr G_{\mathrm{crit}}(H)\) is Polish; no Banach-space assertion is
being made for its weak-ideal coordinate.

The physical sector
\begin{equation}
 \mathscr G^+_{\mathrm{crit}}(H)
 :=\{(x,A,Q)\in\mathscr G_{\mathrm{crit}}(H):Q\succeq0\}

\end{equation}
is a closed submonoid.  For every bounded \(L:H\to H'\),
\[
 L_{\#}(x,A,Q):=(Lx,LAL^*,LQL^*)
\]
is a continuous homomorphism, and the homogeneous dilations
\[
 \delta_a(x,A,Q):=(ax,a^2A,a^2Q),\qquad a\in\mathbb R,
\]
are continuous.

