[Proposition 39 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] [\textbf{Proposition 12 in \cite{Minh2024:FisherRaoGaussian}}]

Let $\nu = \Ncal(0,C_{\nu}) \in \Gauss(\Hcal,\mu_{*})$ be fixed but arbitrary, with $C_{\nu} = C_{*}^{1/2}(I-S_{\nu})C_{*}^{1/2}$.

	Let $\mu_i = \Ncal(0,C_i)$, $C_i = C_{*}^{1/2}(I-S_i)C_{*}^{1/2}$,  $S_i \in \SymHS(\Hcal)_{< I}$,
	$i=1,2$.

	Then 
	\begin{align}

		&\left\| \log\left\{{\frac{d\mu_1}{d\mu_{*}}(x)}\right\}- \log\left\{{\frac{d\mu_2}{d\mu_{*}}(x)}\right\}\right\|^2_{\Lcal^2(\Hcal,\nu)}
		\nonumber
		\\
		&\leq \frac{1}{2}\left(||I-S_{\nu}||^2 + ||S_{\nu}||_{\HS}^2+ [||S_1||_{\HS} + ||S_2||_{\HS} + ||S_1S_2||_{\HS}]^2\right)
		\nonumber
		\\
		& \quad \times ||(I-S_1)^{-1}||^2||(I-S_2)^{-1}||^2||S_1-S_2||^2_{\HS}. 

	\end{align}
	\begin{comment}
	\begin{align}
		&\left\| \log\left\{{\frac{d\mu}{d\mu_{*}}(x)}\right\}- \log\left\{{\frac{d\nu}{d\mu_{*}}(x)}\right\}\right\|^2_{\Lcal^2(\Hcal,\mu_{*})}=
		\frac{1}{2}||S(I-S)^{-1}-T(I-T)^{-1}||^2_{\HS}
		\nonumber
		\\
		& \quad \quad \quad \quad \quad \quad + \frac{1}{4}(\log\dettwo[(I-S)^{-1}] - \log\dettwo[(I-T)^{-1}])^2.

	\end{align}
	Furthermore,
	\begin{align}

		&\left\| \log\left\{{\frac{d\mu}{d\mu_{*}}(x)}\right\}- \log\left\{{\frac{d\nu}{d\mu_{*}}(x)}\right\}\right\|^2_{\Lcal^2(\Hcal,\mu_{*})}

		\\
		&\leq \left(\frac{1}{2} + \frac{1}{4}[||S||_{\HS} + ||T||_{\HS} + ||ST||_{\HS}]^2\right)||(I-S)^{-1}||^2||(I-T)^{-1}||^2||S-T||^2_{\HS}.
		\nonumber
	\end{align}
	\end{comment}

\begin{proposition}

Let $\Xcal$ be a Polish space and $\Bsc(\Xcal)$ its Borel $\sigma$-algebra.

Let
$\mu, \nu \in \Pcal(\Xcal)$ be such that $\nu << \mu$. Then
\begin{align}
\KL(\nu||\mu) \leq \left\|\log\left(\frac{d\nu}{d\mu}\right) \right\|_{\Lcal^2(\Hcal,\nu)}.
\end{align}
Consequently,
\begin{align}
\left\|\log\left(\frac{d\nu}{d\mu}\right) \right\|_{\Lcal^2(\Hcal,\nu)} = 0 \equivalent \KL(\nu||\mu ) = 0 \equivalent \nu = \mu.
\end{align}
In particular, let $\{\mu_k\}_{k \in \Nbb} \in \Pcal(\Xcal)$ be such that $\mu_k \sim \mu$ $\forall k \in \Nbb$. Then
\begin{align}
\lim_{k \approach \infty}\left\|\log\left(\frac{d\mu_k}{d\mu}\right) \right\|_{\Lcal^2(\Hcal,\mu)} = 0 \imply \lim_{k \approach \infty}\KL(\mu||\mu_k) = 0.
\end{align}

