[Theorem thm:qRacah_ensemble_and_tilings of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] {borodin-gr2009q} and [dimitrov2019log]}]

	Fix $T,S,N$. In the zones (equation eq:hexagon_zone_1 of the paper) and (equation eq:hexagon_zone_2 of the paper), the distribution of $X(t)$ (equation eq:nonintersecting_path_ensemble_X_t_defn of the paper) under the $q$-Racah measure ((def:qRacah_tilings of the paper)) is given by the $N$-particle $q$-Racah OPE on $\{0,1,\ldots,M\}$. In the zones (equation eq:hexagon_zone_3 of the paper) and (equation eq:hexagon_zone_4 of the paper), the distribution of the shifted configuration
	\begin{equation}

		X(t)+T-t-S=(x_1(t)+T-t-S<x_2(t)+T-t-S<\ldots<x_N(t)+T-t-S)
	\end{equation}
	is given by the $N$-particle $q$-Racah OPE on $\{0,1,\ldots,M\}$. In all cases, the parameters $M, \alpha,\beta,\gamma,\delta$ are given by the corresponding formulas in (equation eq:hexagon_zone_1 of the paper)--(equation eq:hexagon_zone_4 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 62 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $\left(X, \mathbb{P}_x,x\in E\right)$ be a right process associated to the resolvent $\mathcal{U}$ on the Lusin measurable space $(E,\mathcal{B})$. 
    Further, let $m$ be a $\sigma$-finite measure on $E$, and $\tau$ be a natural topology on $E$.
    Furthermore, suppose that
    \begin{equation*}
        \mathbb{P}_m\left([0,\infty)\ni t\mapsto X(t)\in E \mbox{ is } \tau\mbox{-continuous} \right)=1.
    \end{equation*}
    Then there exists a set $E_0\subset E$ such that $E\setminus E_0$ is $m$-inessential and
    \begin{equation}
        \mathbb{P}_x\left([0,\infty)\ni t\mapsto X(t)\in E_0 \mbox{ is } \tau\mbox{-continuous} \right)=1 \quad \mbox{for all } x\in E_0.
    \end{equation}
    Consequently, one can consider the restriction $\widetilde{X}$ of $X$ from $E$ to $E_0$, so that $\widetilde{X}$ is a right process with a.s. $\tau$-continuous paths in $E_0$; in particular, $\tau$ is a natural topology on $E_0$.
    Furthermore, the above assertion remains true if instead of "$\tau$-continuous" we use "$\tau$-right-continuous" or "$\tau$-c\`adl\`ag".

[Lemma lem:ergodic_characterization of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] $B$ is 
		\begin{itemize}
			\item ergodic if
			\begin{equation*}
				\lim_{r\to +\infty}\frac{1}{\Vol{\mathsf{B}_{r}}}\int_{\mathsf{B}_{r}}\@ifnextchar[{\@withe}{\@withoute}{f(B)\overline{g(\theta_{t}B)}}\, \mathrm{d}t=\@ifnextchar[{\@withe}{\@withoute}{f(B)}\overline{\@ifnextchar[{\@withe}{\@withoute}{g(B)}},
			\end{equation*}
			\item weakly-mixing if
			\begin{equation*}
				\lim_{r\to +\infty}\frac{1}{\Vol{\mathsf{B}_{r}}}\int_{\mathsf{B}_{r}}\left|\,\@ifnextchar[{\@withe}{\@withoute}{f(B)\overline{g(\theta_{t}B)}}-\@ifnextchar[{\@withe}{\@withoute}{f(B)}\overline{\@ifnextchar[{\@withe}{\@withoute}{g(B)}}\,\right|^{2}\, \mathrm{d}s=0,
			\end{equation*}
			\item strong-mixing if
			\begin{equation*}
				\lim_{\|t\|\to +\infty}\@ifnextchar[{\@withe}{\@withoute}{f(B)\overline{g(\theta_{t}B)}}=\@ifnextchar[{\@withe}{\@withoute}{f(B)}\overline{\@ifnextchar[{\@withe}{\@withoute}{g(B)}}
			\end{equation*}
		\end{itemize}
		for any $f,g$ of the forms 
		\begin{equation}
			f(B)=\exp{i\sum_{j=1}^{n}a_{j}B_{t_{j}}}, \quad g(B)=\exp{i\sum_{j=1}^{n}b_{j}B_{t_{j}}}
		\end{equation} 
		with $a_{j}, b_{j} \in \mathbb{R}$ and $ t_{j} \in \mathbb{R}^{d}$.

[Thm 7 of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Let $\Theta \subseteq \mathbb{R}^d \times \mathbb{S}_+^d \times \mathcal{L}$ be closed, convex, and satisfy Assumptions~\ref{B} and~\ref{J}. Moreover, let the cost function $\ell$ satisfy Assumption~\ref{L}. Then for every $\overline{\mathbb{F}}$-stopping time $\overline{\tau}$ taking values in $[t,1]$ and all $(b,c,v)\in\mathbb{R}^d\times\mathbb{R}^{d^2}\times\mathbb{R}^{\mathbb{N}}$, we have
\begin{equation}
\lambda(t,x)=\inf_{\overline{\mathbb{P}}\in\overline{\mathfrak{P}}_{\Theta}^{t,x,b,c,v}}\mathbb{E}^{\overline{\mathbb{P}}}
\Bigl[\int_{t}^{\overline{\tau}} \overline{\ell}(s,\overline{X}_s,\overline{b}_s,\overline{c}_s,\overline{v}_s)\,\mathrm{d}s+\lambda(\overline{\tau},\overline{X}_{\overline{\tau}})\Bigr].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition no_BAD_steps of arXiv:2603.05491, '\textbf{Local limits of uniform triangulations with boundaries in high genus}'] For any $k \ge 1$ and any $\varepsilon > 0$, there exist $A,a > 0$ such that, for $n$ large enough and for any peeling algorithm $\mathcal{A}$, we have
    \begin{align*}
        \mathbb{P}\bigg(\mathbf{GOOD}^{\mathcal{A}}_{n}(A,a,k) \bigg) \ge 1-\varepsilon. 
    \end{align*}

