[Proposition 7 of arXiv:2608.27093, 'Soliton Solutions to the Curvature Flow on the 2-dimensional De Sitter Space and Applicati'] Given a solution $(\alpha(s), \tau(s), \eta(s))$ of the system \eqref{c4e1} on some interval $I$  with fixed $a>0$,  and initial conditions $(\alpha(0),\tau(0),\eta(0))$ satisfying \eqref{e_i2}, there exists a smooth  spacelike curve or timelike curve  $X: I \rightarrow \mathbb{S}_{1}^{2}$, parametrized by arc length $s$,   such that its tangent and normal unit vetor fields $T$ and $N$  satisfy
	\begin{equation}
		\alpha(s)=\langle X(s),e\rangle,\hspace{.5 cm}\tau(s)=\langle T(s),e\rangle \hspace{.5 cm} \text{\rm e} \hspace{.5 cm} \eta(s)=\langle N(s),e\rangle, 
	\end{equation} 
	where $e=(-1,0,0)$  (respectively $e=(-1,1,0)$ and $e=(0,0,1)$).

[Lem 1.1 of arXiv:2412.00708, 'Stochastic PDE approach to fluctuating interfaces'] We have
\begin{align}  
b_K^N(\eta,\varphi) & = \frac{N^2}{2N^d} \sum_{p,q\in{\mathbb{T}}_N^d: |p-q|=1} 
c_{p,q}(\eta)(\eta_p-\eta_q) 
\left(\varphi\left(\tfrac{q}N\right)  - \varphi\left(\tfrac{p}N\right) \right), \\

\Gamma_K^N(\eta,\varphi) & = \frac{N^2}{2N^{2d}} \sum_{p,q\in{\mathbb{T}}_N^d: |p-q|=1} 
c_{p,q}(\eta) (\eta_p-\eta_q)^2
 \left(\varphi\left(\tfrac{q}N\right)  - \varphi\left(\tfrac{p}N\right) \right)^2.
\end{align}
In particular, when $c_{p,q}\equiv 1$ called simple Kawasaki dynamics
or simple exclusion process,
one can rewrite (equation eq:b of the paper) as
\begin{align}  
b_K^N(\eta,\varphi) & = \frac1{N^d} \sum_{p\in{\mathbb{T}}_N^d} \eta_p \, \Delta^N
\varphi\left(\tfrac{p}N\right)   \equiv \langle\rho^N,\Delta^N\varphi\rangle,
\intertext{where}  \notag
\Delta^N\varphi\left(\tfrac{p}N\right) &= N^2 \sum_{q\in {\mathbb{T}}_N^d:|q-p|=1}
\left(\varphi\left(\tfrac{q}N\right)  - \varphi\left(\tfrac{p}N\right) \right).
\end{align}

