    \begin{align*}
    g^\beta(t) - g^\beta(s) &= \lim_{x\rightarrow-\infty}\left[v^{\beta}(t,x) - v^{\beta}(s,x)\right] \\
    &= \lim_{x\rightarrow -\infty}\left[\P\left(X_t > x, \sigma^{\beta} > t\right) - \P\left(X_s > x, \sigma^{\beta} > s\right)\right] \\
    &= \P\left(\sigma^{\beta} > t \right) - \P\left(\sigma^{\beta} > s\right).
