[Thm Thomeo of arXiv:2605.07920, 'Primitive Sequences for Probability Measures on Compact Intervals'] Equip $\pazocal{P}_{[a,b]}$ with the weak topology and $\pazocal{S}^{\mathrm{adm}}_{[a,b]}$ with the subspace topology inherited from the product topology on $\prod_{n = 0}^\infty [0, (b-a)^n/n!]$. Then the primitive sequence map $S$ is a homeomorphism between $\pazocal{P}_{[a,b]}$ and $\pazocal{S}^{\mathrm{adm}}_{[a,b]}$; in particular, for $\mu_k, \mu \in \pazocal{P}_{[a,b]}$ with $k \geq 1$, 
    \begin{equation*}
        \mu_k \rightsquigarrow \mu \quad \Longleftrightarrow \quad \varepsilon_n(\mu_k) \to \varepsilon_n(\mu), \quad n \geq 0.
    \end{equation*}

[Lemma 19 of arXiv:2512.05466, 'Stochastic Flows and Marked Stable Processes'] The following statements hold almost surely, for all $(a,r),(a',r')\in (0,\infty)\times \bR$ and $(b,x)\in \bR_+\times (r,\infty)$: 
\begin{enumerate}[(i)]
\item  We have $(b,x)\in \cT_{(a,r)}$ if and only if $(a,r)$ is an ancestor of $(b,x)$ for both $\cB$ and $\cR$. In particular, there is the identity
\begin{equation}
    \cT_{(a,r)}=\{(b,x)\in \bR_+\times (r,\infty)\,:\, a=\cB^*_{-x,-r}(b)=\cR^*_{-x,-r}(b)\}.
\end{equation} 

\item   If $(b,x)\in \cT_{(a,r)}$, then the points  $(\cR^*_{-x,-y}(b),y)$ and $(\cB^*_{-x,-y}(b),y)$ for $y\in (r,x)$ also belong to $\cT_{(a,r)}$.
\item  $\cT_{(a,r)}$ is bounded.
    \item Either $\cT_{(a,r)}$ and $\cT_{(a',r')}$ are disjoint or one is included in the other.

\end{enumerate}

