[Lemma tricky of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] Let $E,F\subseteq \mathbb R^3$ be non-empty Borel sets. Let $\mu$ be a finite measure on $F$, and $\nu(y,\cdot)$ be a finite measure on $E$ for each $y\in F$. 
    Suppose $p(x,y)$, $s(y)$ and $r(z)$ are non-negative bounded Borel functions on $E\times F,\,F,\,E$, respectively, such that the following equality holds for all $x\in E$,
    \begin{equation}
        r(x)=\int _F p(x,y)\left (\int _E r(z)\nu(y,dz)\right )\mu(dy)+\int _F p(x,y)s(y)\mu(dy).
    \end{equation}
    Moreover, suppose there exists a constant $0\le a <1$ such that for all $x\in E$,
    \begin{equation}
        \int_F p(x,y)\nu(y,E)\mu(dy)\leq a,
    \end{equation}
    then for all $x\in E$,
    \begin{equation*}
        \int p(x,y)s(y)\mu(dy)\geq \dfrac{1-a}{1+(K(p)-1)a}r(x).
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma le:4arm_good_fl of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] Fix $p \in (0,1)$. Let~$h$ be a GFF on~$\mathbf{D}$ with boundary values so that its flow line $\eta$ is an ${\rm SLE}_{\kappa}${} from $-i$ to $i$. Let $X^0_{0,1},X^0_{0,\epsilon}$ be as defined in~(equation eq:fl_annulus of the paper). Let $I_\epsilon$ be the event that there exist two strands $\eta_{w_1;\mathrm{in}}$, $\eta_{w_3;\mathrm{in}}$ of $X^0_{0,1}$ and a strand $\eta_{w_2;\mathrm{out}}$ of $X^0_{0,\epsilon}$ so that the following hold.
\begin{itemize}
 \item The continuations of $\eta_{w_i;\mathrm{in}}$, $i=1,3$, exit $A(0,\epsilon/4,3/4)$ on the inner boundary and without merging, and the continuation of $\eta_{w_2;\mathrm{out}}$ exits $A(0,\epsilon/4,3/4)$ on the outer boundary.
 \item Let $\widetilde{I}_\epsilon$ be the event that
 \begin{itemize}
  \item $\eta$ merges consecutively into $\eta_{w_1;\mathrm{in}}$, $\eta_{w_2;\mathrm{out}}$, $\eta_{w_3;\mathrm{in}}$ before hitting $B(i,1/8)$ and without crossing $A(0,1/4,3/4)$ (resp.\ $A(0,\epsilon/4,3\epsilon/4)$) inbetween,
  \item the event $\mathcal {E}_4$ in Proposition~(pr:alternating_crossing_simple of the paper) occurs for $\eta$.
 \end{itemize}
 The conditional probability of $\widetilde{I}_\epsilon$ given $\eta_{w_1;\mathrm{in}}$, $\eta_{w_2;\mathrm{out}}$, $\eta_{w_3;\mathrm{in}}$, $X^0_{0,1},X^0_{0,\epsilon}$, and the values of $h$ on $X^0_{0,1},X^0_{0,\epsilon}$ is at least $p$.
\end{itemize}
Then
\[\mathbf{P}[I_\epsilon]=O(\epsilon^{\alpha_{4,\kappa}+o(1)}).\]

[Proposition 14 of arXiv:2607.22438, 'A deterministic scalar reduction for the phase transition in two interacting urns'] Let $s_0\in(0,1)$ be the unique solution of
\begin{equation}
 2s_0\operatorname{arctanh}(s_0)=1.
\end{equation}
Then
\begin{equation}
 \lim_{\alpha\downarrow1}\frac{p_\alpha}{\alpha-1}
 =\frac{1-s_0^2}{2s_0^2}.
\end{equation}

