body:
[Thm dynamicLinearStatisticsCLT of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Let $0\le\mathsf{s}<\mathsf{d}/2$, $\beta>0$, and $T>0$.  Let $(\mu^t)_{0\le t\le T}$ be a mean-field trajectory and $(f_N^t)_{0\le t\le T}$ the corresponding particle laws.  Assume the following.
\begin{enumerate}[(i)]
\item The particle system and mean-field equation are well posed in a class for which the time-dependent It\^o formulas used below are valid; the Brownian motions are independent of the initial configuration; $f_N^0={\mathbb{Q}}_{N,\beta}(\mu^0)$; and the estimate (equation eq:MFEdiffusiveGronwall of the paper) holds.  Moreover,
\begin{align}
\sup_{0\le t\le T}
\pa*{\|\mu^t\|_{L^\infty}+\mathcal A^t+\mathcal B^t}
<\infty.
\end{align}
If $\mathsf{s}=0$, assume in addition that
\begin{align}
\inf_{0\le t\le T} I_{\mu^t}>-\infty.
\end{align}
\item There are constants $0<c_{\beta,T}\le C_{\beta,T}<\infty$ and $C_{2\beta,T}<\infty$ such that
\begin{align}
&\inf_{N\ge1}\inf_{0\le t\le T}{\mathsf{K}}_{N,\beta}(\mu^t)\ge c_{\beta,T},
\qquad
\sup_{N\ge1}\sup_{0\le t\le T}{\mathsf{K}}_{N,\beta}(\mu^t)\le C_{\beta,T},\\
&\sup_{N\ge1}\sup_{0\le t\le T}{\mathsf{K}}_{N,2\beta}(\mu^t)\le C_{2\beta,T},
\end{align}
and $\mu^0$ satisfies the hypotheses of (prop:linearEmpiricalFluctuationCLT of the paper).
\item There is a real linear test space $\mathscr D_T\subset C_b^2({\mathbb{R}}^\mathsf{d})$ such that, for every $t\in[0,T]$ and $\phi\in\mathscr D_T$, the terminal-value problem
\begin{align}
-\partial_r f^r=\mathcal L_{\beta,\mu^r}f^r,
\qquad 0\le r\le t,
\qquad f^t=\phi,
\end{align}
has a unique real-valued classical solution, denoted by $f^r=\mathsf{U}^{r,t}\phi$, for which $f$, $\nabla f$, $\nabla^{\otimes2}f$, and $\partial_r f$ are jointly continuous and
\begin{align}
\sup_{0\le r\le t}
\pa*{
\|f^r\|_{L^\infty}
+\|\nabla f^r\|_{L^\infty}
+\|\nabla^{\otimes2}f^r\|_{L^\infty}
+\|\partial_r f^r\|_{L^\infty}}
<\infty.
\end{align}
The bound in (equation eq:dynamicAdjointRegularity of the paper) is uniform over each fixed finite family of terminal pairs $(t,\phi)$.
\end{enumerate}
Fix $k\ge1$, times $t_1,\ldots,t_k\in[0,T]$, and tests $\phi_1,\ldots,\phi_k\in\mathscr D_T$.  Then
\begin{align}
\pa*{S_N^{t_1}(\phi_1),\ldots,S_N^{t_k}(\phi_k)}
\Longrightarrow (G_1,\ldots,G_k),
\end{align}
where the vector on the right is centered Gaussian with covariance
\begin{align}
{\mathbb{E}}[G_aG_b]
={}&\Sigma_{\beta,\mu^0}\pa*{\mathsf{U}^{0,t_a}\phi_a,\mathsf{U}^{0,t_b}\phi_b}\\
&+\frac2\beta\int_0^{t_a\wedge t_b}
\int_{{\mathbb{R}}^\mathsf{d}}\nabla\mathsf{U}^{r,t_a}\phi_a\cdot
\nabla\mathsf{U}^{r,t_b}\phi_b\,\mathop{}\!\mathrm d\mu^r\,\mathop{}\!\mathrm d r.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 (Compressibility yields best \(N\)-term approximation) of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] Let $S>\frac{1}{2}$ and let $X \in \mathcal{H}^2_{T}(\mathbb{R}^{d})$ be $S$-compressible with compressibility constant $C_X$. Then, for every $N \in \mathbb{N}_{+}$, we have
\begin{equation}
    \inf_{\substack{\beta_1,\ldots,\beta_N\in\mathbb R^d\\
\mathfrak{m}^{(1)},\ldots,\mathfrak{m}^{(N)}\in \mathfrak{C}}}
\left\|
X-\sum_{n=1}^{N}\beta_n \mathfrak m^{(n)}
\right\|_{\mathcal{H}_T^2}
\lesssim_X
N^{-(S-\frac12)}.
\end{equation}

[Lemma 16 (Weighted core balls) of arXiv:2607.13183, '2607.13183'] Let $k=\lfloor\eps^{-1}\rfloor$.  There are absolute constants
$C_{\rm ball},C_{\rm near}<\infty$ such that, with high probability,
\begin{equation}
        \sum_{z\in V(\Core)}\nu(z)B_E(z,k+2)
        \le C_{\rm ball} k,
\end{equation}
and
\begin{equation}
        \sum_{z,w\in V(\Core)}\nu(z)\nu(w)
        \one_{\{\dist_{\Core}(z,w)\le k\}}
        \le \frac{C_{\rm near}}{\eps^3n}=o(1).
\end{equation}

[Theorem thm:lowerboundpt of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Under the same assumptions as in (thm:flowpoincare of the paper), it holds that for any observation period $T > 0$, and the initial condition $x_0 \in \mathcal{F}^\perp$, 
\begin{align} 
    \frac{1}{T}\int_t^{t + T} \lVertP_s x_0\rVert_{\mathcal{H}}^2 \,\mathrm{d} s \le e^{- 2\nu t} \lVertx_0\rVert_{\mathcal{H}}^2\,,
\end{align}
with the convergence rate: 
\begin{equation} 
    \nu = \frac{\gamma}{\gamma^2 C_0(T) + C_1(T)}\,,
\end{equation}
where $C_0(T)$ and $C_1(T)$ are the flow Poincar\'e constants in (thm:flowpoincare of the paper). 
Moreover, the convergence rate estimate (equation eq:ratel2 of the paper) is maximized at 
\begin{align} 
    \gamma_{\rm max} = \sqrt{C_1(T)/C_0(T)} \quad \text{with rate}\quad \nu_{\max} = \frac{1}{2\sqrt{C_0(T) C_1(T)}}\,.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem main-1 of arXiv:2609.02769, 'Divergence-Free Approximation in Sobolev and Lebesgue Spaces on general unbounded domains '] Let $\Omega=\mathbb{R}^d$ and $\boldsymbol{y}\in\mathbb{V}\cap\mathbb{L}^p_{\sigma}$. Then, there exists a sequence $\{\boldsymbol{y}_n\}_{n\geq1}$ in $\mathbb{C}_{0,\sigma}^{\infty}(\Omega)$ such that 
		\begin{align}
			\|\boldsymbol{y}_n-\boldsymbol{y}\|_{\mathbb{V}}+\|\boldsymbol{y}_n-\boldsymbol{y}\|_{\mathbb{L}^p_{\sigma}}\to 0\ \text{ as }\ n\to\infty. 
		\end{align}
		Equivalently, $\mathbb{C}_{0,\sigma}^{\infty}(\Omega)$ is dense in $\mathbb{V}\cap\mathbb{L}^p_{\sigma}$ for
		the norm $\|\cdot\|_{\mathbb{V}}+\|\cdot\|_{\mathbb{L}^p_{\sigma}}$.

