[Lemma uniformEY of arXiv:2412.09850, 'Averaging principles for time-inhomogeneous multi-scale SDEs via nonautonomous Poisson equ'] Suppose that Assumption {\rm(A1 of the paper)} holds. Then there is a constant $C>0$ such that
\begin{itemize}
\item[{\rm (i)}] for $t \ge s$, $x\in\mathbb{R}^{n}$ and $y\in\mathbb{R}^{m}$,
\begin{equation}
\mathbb{E}|Y_{t}^{s,x,y} |^{4} \le e^{-4\gamma\int^{t}_s \alpha(u)\,du}|y|^4+C(1+|x|^4);
\end{equation}
\item[{\rm (ii)}]   for $t \ge s$, $x_1,x_2\in\mathbb{R}^{n}$ and $y_1,y_2\in\mathbb{R}^{m}$,
\begin{equation}
\mathbb{E}|Y_t^{s,x_1,y_1}-Y_t^{s,x_2,y_2}|^{4}\le e^{-4\gamma\int^t_s \alpha(u)\,du }|y_1-y_2|^{4}+C|x_1-x_2|^{4}, 
\end{equation}\end{itemize}
where $\gamma\in(0,1)$ is the constant in (equation A12 of the paper).

