[Corollary c4.17 of arXiv:2603.14447, '\Large \bf Backward doubly stochastic differential equations with and without reflection u'] \sl
		Assume that
		the conditions \(\textbf{(A2)}\), \(\textbf{(G1)}\), \(\textbf{(S2)}\) and \(\textbf{(G2)}\) hold with \(\lambda(t)=0\) for all \(t\in [0,T]\).   For any \((t,y,z)\in[0,T]\times\mathbb{R}\times\mathbb{R}^d\), we have
		\begin{align*}
			S^1_t\leqslant S^2_t,\quad\ 	\xi^1\leqslant \xi^2,\quad\ 
			f^1(t,y,z)\leqslant f^2(t,y,z), \quad\  \hbox{a.s.}
		\end{align*}
		Moreover, assume that  $f^2$ satisfies \(\textbf{(F3')}\).
		Then for any \(t\in [0,T]\), $Y_t^1\leqslant Y_t^2,  \mathbb{P} $-a.s., where $(Y^1,Z^1,K^1)\in S_\mathbb{F}^{\infty}([0,T];\mathbb{R})\times L_\mathbb{F}^2([0,T];\mathbb{R}^d)\times A_\mathbb{F}^{2}([0,T];\mathbb{R}_+)$ is a bounded solution of reflected BDSDE (equation r1 of the paper) with parameters $(\xi^1,f^1,g)$ and obstacle $S^1$,
		$(Y^2,Z^2,K^2)\in S_\mathbb{F}^{\infty}([0,T];\mathbb{R})\times L_\mathbb{F}^2([0,T];\mathbb{R}^d)\times A_\mathbb{F}^{2}([0,T];\mathbb{R}_+)$ is a maximal solution of reflected BDSDE (equation r1 of the paper) with parameters $(\xi^2,f^2,g)$ and obstacle $S^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 42 (Martin Boundary and harmonic functions for general $q$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] If $x^* = +\infty$, then Theorem~\ref{thm5} applies. Assume now that $x^* \in (0, \M)$. 
Then, the Martin boundary $\Gamma$ is given by
\begin{equation}
\Gamma = \left[\{e^{i\alpha}\}_{\alpha \in [\alpha^*_+,\alpha^*_-] \cap \mathcal M} \cup \{ue^{i\tilde\alpha_b}\}_{u\in[1,2]}\right]/\mathcal{R}_1 \;\sim\; \mathbb{S}^1
\end{equation}
where $\mathcal{R}_1$ is the equivalence relation given by $e^{i\alpha^*_-}\,\mathcal{R}_1\,e^{i\alpha^*_+}$, $e^{i\pi}\,\mathcal{R}_1\,2e^{i\tilde\alpha_b}$, and $[x\mathcal{R}_1y \Longleftrightarrow x=y]$ for the other points (see Figure~\ref{fig:martingeneral}).
Furthermore, the minimal Martin boundary, denoted by $\Gamma_{min}$, is given by
\begin{equation}
\Gamma_{min} = \left[\{e^{i\alpha}\}_{\alpha \in [\alpha^*_+,\alpha^*_-] \cap \mathcal M}\right] /\mathcal{R}_2 \;\sim\; [0,1]
\end{equation}
where $\mathcal{R}_2$ is the equivalence relation given by $e^{i\alpha^*_-}\,\mathcal{R}_2\,e^{i\alpha^*_+}$ and $[x\mathcal{R}_2y \Longleftrightarrow x=y]$ for the other points (see again Figure~\ref{fig:martingeneral}). Moreover, for each positive harmonic function $h$ (with respect to the process), there exists a unique Radon measure $\nu$ on $[\alpha^*_+, \alpha^*_-)\cap \mathcal M$ such that
\begin{equation}
    \forall z \in \R^2, \quad h(z) = \int_{[\alpha^*_+, \alpha^*_-)\cap \mathcal M} \frac{h_\alpha(z)}{h_\alpha(0)} \, d\nu(\alpha) 
\end{equation}
where the conventions $\frac{h_{\alpha^*_+}(z_0)}{h_{\alpha^*_+}(0)} = \frac{f_*(z_0)}{f_*(0)}$ and $\frac{h_{\pi}(z_0)}{h_{\pi}(0)} = \frac{f_\pi(z_0)}{f_\pi(0)}$ are used, since 
$$\underset{\alpha \to \alpha^*_+\atop \alpha \in \mathcal M}{\lim} \frac{h_\alpha(z_0)}{h_\alpha(0)} \left(= \underset{\alpha \to \alpha^*_-\atop \alpha \in \mathcal M}{\lim} \frac{h_\alpha(z_0)}{h_\alpha(0)}\right) = \frac{f_*(z_0)}{f_*(0)}\quad \textnormal{and}\quad \frac{h_\alpha(z_0)}{h_\alpha(0)} \underset{\alpha \to \pi \atop \alpha \in \mathcal M}{\longrightarrow} \frac{f_\pi(z_0)}{f_\pi(0)}.$$
Finally, the case $x^* \in (\m, 0)$ is symmetric. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop contour_partfn of arXiv:2411.07809, 'Pirogov--Sinai Theory Beyond Lattices'] Let $\Lambda$ be a finite induced subgraph of $G$. Then
  \begin{equation*}
    Z^{\textsf{e}}_{\Lambda} = \lambda_{\textsf{e}}^{|V_\textsf{e} \cap \Lambda|}\sum_{\substack{\Gamma \subseteq \overline{\mathcal C}(\Lambda) \\ \text{compatible} \\ \text{matched} \\\text{external}\ \textsf{e}}} \prod_{\gamma \in \Gamma} w_\gamma.
\end{equation*}
The same holds with odd replacing even.

[Defn of arXiv:2609.00884, 'The weakness of typicality'] \ 
\begin{itemize}
    \item[(1)] A \emph{Turing ideal} $\mathcal{M}$ is a non-empty collection of sets which is downward-closed under Turing reducibility ($\forall X \in \mathcal{M}~ \forall Y \leq_T X,\ Y \in \mathcal{M}$) and closed under the effective join ($\forall X, Y \in \mathcal{M}, X \oplus Y \in \mathcal{M}$).
    \item[(2)] A problem~$\mathsf{P}$ \emph{holds} in a Turing ideal~$\mathcal{M}$ (written $\mathcal{M} \vDash \mathsf{P}$) if for every~$\mathsf{P}$-instance~$X \in \mathcal{M}$, there is a $\mathsf{P}$-solution~$Y \in \mathcal{M}$.
    \item[(3)] A problem~$\mathsf{P}$ is \emph{$\omega$-reducible} to $\mathsf{Q}$ (written $\mathsf{P} \leq_\omega \mathsf{Q}$) if for every Turing ideal~$\mathcal{M}$, if $\mathcal{M} \vDash \mathsf{Q}$ then $\mathcal{M} \vDash \mathsf{P}$.
\end{itemize}

[Thm 23 of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Let $\mu_0,\mu_1\in\mathcal{P}(\mathbb{R}^d)$ have finite second moments and let $\ell$ (defined in \eqref{definel}) satisfy Assumptions~\ref{L} and~\ref{uL}. Then 
\begin{equation*}
MBB(\mu_0,\mu_1)=\sup_{\lambda_1\in C_b(\mathbb{R}^d)}\Bigl\{ \int_{\mathbb{R}^d}\lambda_0^{\lambda _1}(x)\,\mu_0(\mathrm{d}x)-\int_{\mathbb{R}^d}\lambda_1(x)\,\mu_1(\mathrm{d}x) \Bigr\},
\end{equation*}
where
\begin{equation*}
\lambda_{0}^{\lambda_1}(x)=\inf_{\mathbb{P}\in\mathfrak{P}_{\Theta}(\delta_x)}\mathbb{E}^{\mathbb{P}}\biggl[\int_0^1 \ell(t,X_t,c_t^{\mathbb{P}})\,\mathrm{d}t+\lambda_1(X_1)\biggr].
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:form_of_drift of arXiv:2412.04005, '$\SLE_{\kappa}(\rho)$ processes in the light cone regime on\\ Liouville quantum gravity'] {dms2014mating}}$]
Let 
\begin{align*}
\alpha = \frac{\rho + 4}{\gamma} - Q = \frac{\rho + 2}{\gamma} - \frac{\gamma}{2}.
\end{align*}
Let $\widehat{B}_{2t}^{j,\epsilon,\widetilde{\epsilon},r} = \alpha t - \widehat{X}_{t}^{j,\epsilon,\widetilde{\epsilon},r}$ for $t \geq 0$. Given $\widetilde{\mathcal {F}}_{\tau_{j}^{r,\epsilon,\overline{\epsilon}}}$, the process $\widehat{B}^{j,\epsilon,\overline{\epsilon},r}$ is a standard Brownian motion with $\widehat{B}_{0}^{j,\epsilon,\overline{\epsilon},r} = -r$.

[Conjecture ProbContSharp of arXiv:2504.18739, 'discrete analogues of second-order Riesz transforms'] For $j\neq k$,
\begin{align} 
    &\|2\mathbf{R}^{(jk)}\|_{L^p\to L^p} =(p^*-1), \\
    &\|\mathbf{R}^{(jj)}-\mathbf{R}^{(kk)}\|_{L^p\to L^p}= (p^*-1).
\end{align} 
When $j=k$, 
\begin{equation}
    \|\mathbf{R}^{(jj)}\|_{L^p\to L^p}=\gamma(p).
\end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Proposition prop:geom of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] Let $d\ge 1$.
Suppose that Assumptions~(ass:Omega of the paper) and~(ass:J of the paper)
hold, but without requiring that $h^{(\mu)},J^{(\mu)}$ satisfy
(equation eq:Q_d-1 of the paper).
Then the set $\overline \Omega$ is strictly convex, and every $\mu \in \overline \Omega$ obeys $\abs \mu^2 \le M/K_{\mathrm{IR}}$.
For each $\mu \in \overline\Omega$, we have
\begin{equation} 
    \sum_{y\in {\mathbb Z^d}} J ^{(\mu)}(y) \le 1
    \quad \text{with equality if and only if $\mu\in\partial\Omega$.}
\end{equation}
For each nonzero $ x \in {\mathbb R^d}$,
there is a unique vector ${\mu_{\hat x}} \in \partial \Omega$, depending only on the direction $\hat x = x / \abs x$ of $x$, such that
\begin{equation}

\mu_{\hat x}\cdot x = \max_{\mu \in \overline\Omega }\, \mu\cdot x.
\end{equation}
The vector $\eta_{\hat x} \in {\mathbb R^d}$ with components
\begin{equation} 
\eta_{{\hat x},j}
= \sum_{y\in {\mathbb Z^d}} y_j J(y) e^{{\mu_{\hat x}} \cdot y}
\end{equation}
satisfies $\eta_{\hat x} = |\eta_{\hat x}|\hat x$.
Also,
with the matrix $\Lambda_{\hat x}$ defined by
$\Lambda_{\hat x, j l } = \sum_{y\in {\mathbb Z^d}} y_j y_l J(y) e^{{\mu_{\hat x}} \cdot y}$,
we have
\begin{equation} 
 \mu_{\hat x} \cdot x  \asymp m_S  \abs x ,
	\qquad
|\eta_{\hat x}| \asymp m_S ,
	\qquad
k \cdot \Lambda_{\hat x} k \asymp \abs k^2
	\quad (k\in {\mathbb R^d}) ,
\end{equation}
with constants depending only on $d,M,K_{\mathrm{IR}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm t.main of arXiv:2507.16056, 'Conditional GMC within the stochastic heat flow'] With $s<t$, $\theta\in\mathbb{R}$, and $\mathbb{E}\xi_1^2:=a$,
\begin{align}

	\mathcal{G}\big[ M^{\theta}_{[s,t]}, Y_{\star\,[s,t]}^{\theta}, \xi \big]
	\text{ is equal in law to }
	M^{\theta+a}_{[s,t]}\ .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

