[Lemma 41 (Frostman's Lemma) of arXiv:2512.07202, 'Hitting Probabilities for Hypoelliptic Differential Equations Driven by Fractional Brownia'] Let \( U \) be a compact metric space and fix \( 0 \leqslant \alpha < \infty \), \( 0 < \delta \leqslant \infty \). Then there exists a Radon measure \( \mu \) on \( U \) such that \( \mu(U) = \lambda^\delta_\alpha(U) \) and
\begin{equation}
\mu(E) \leqslant d(E)^\alpha \quad \text{for all } E \subseteq U \text{ with } d(E) < \delta.
\end{equation}
In particular, if \( \mathcal{H}_\alpha(U) > 0 \), then there exist \( \delta > 0 \) and a Radon measure \( \mu \) satisfying \eqref{cononmu} with \( \mu(U) > 0 \). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Eq G Ext Gamma decomp of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] For every $\theta\in[0,2\pi)$,
\begin{eqnarray}

G_{\operatorname{Ext}(\Gamma)}(e^{i\theta},\infty)
&=&
\dfrac{1}{2\pi}
\log R^{+}(\Gamma)^{-1}
\\
\nonumber
&&+
\int_{0}^{2\pi}
G_{\operatorname{Ext}(\Gamma)}(R^{+}(\Gamma)e^{i\alpha},\infty)
P_{\mathbb{C}\setminus(R^{+}(\Gamma)\overline{\mathbb{D}})}
(e^{i\theta},R^{+}(\Gamma)e^{i\alpha})
(R^{+}(\Gamma)d\alpha).
\end{eqnarray}
In particular,
\begin{multline}

1
=
\dfrac{1}{2\pi}
(\log R^{+}(\Gamma)^{-1})
\operatorname{ED}(\Gamma,\partial\mathbb{D})^{-1}
\\
+
\int_{0}^{2\pi}
d\theta
\int_{0}^{2\pi}
(R^{+}(\Gamma)d\alpha)
\int_{\Gamma}
G_{\operatorname{Ext}(\Gamma)}(R^{+}(\Gamma)e^{i\alpha},\infty)
P_{\mathbb{C}\setminus(R^{+}(\Gamma)\overline{\mathbb{D}})}
(e^{i\theta},R^{+}(\Gamma)e^{i\alpha})
H_{\mathcal{A}_\Gamma}(dz,e^{i\theta}).
\end{multline}

[Thm ch5-t30 of arXiv:2410.23995, 'Sample path properties of parabolic SPDEs with non constant coefficients'] We assume that $({\bf H_\Lambda})$, $({\bf \bar{H}_\Gamma})$, $({\bf H_L})$ and $({\bf H_I})$ hold.
Let $(u(t, x), \, (t,x)\in[0,T]\times D)$ be the solution of (equation 5.1 of the paper) given in Theorem (ch5-t2 of the paper). Then
for every $p\in[2,\infty[$, $\gamma_1\in \left]0,\frac{1-\eta}{2}\right [$ and $\gamma_2\in\, ]0,1-\eta[$, there exists a constant $C>0$ such that for all $s,t\in[0,T]$, $x,y\in D$,
\begin{equation}

 E\left(|u(t,x) - u(s,y)|^p\right) \le C\left(|t-s|^{\gamma_1 p} + |x-y|^{\gamma_2 p}\right) + |I_0(t,x)-I_0(s,y)|^p.
\end{equation}
As a consequence, for $\gamma_1 \in \left]0,\frac{1-\eta}{2}\right [$ and $\gamma_2\in\, ]0,1-\eta[$, there is a version of $(u(t, x) - I_0(t, x), \, (t, x) \in [0, T] \times D)$ with  locally H\"older continuous sample paths with exponents $(\gamma_1, \gamma_2)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to [-1,1]$, and $1\leq q\leq p\leq 2$,
\begin{equation}
    \frac{\left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p}}{\big[1+\frac{q}{2k(2-q)} \ln^{+}(\left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p}/\left\|\left|\grad^k f\right|\right\|_{\Leb^q}^{2})\big]^{kp/2}} \geq C^{\text{\rm\ref{thm:high-order-Lp-Lq-energy-Boolean}}}(p,q)^k \Wop^{\geq k}(f),
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-Lp-Lq-energy-Boolean}}}(p,q) = \left(M(p)^{-\frac{2}{p}}+\frac{pq}{4\upe(2-q)}\right)^{-\frac{p}{2}}  \gtrsim 2-q$, where $M(p) := p \, 2^{-\frac{p}{2}} \max_{x\geq 0} \frac{1-\upe^{-x}}{x^{p/2}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

