body:
[Corollary eq:growing-L-pressure of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[corollary]{cor:growing-cutoff-regimes}
In the setting of (thm:growing-point-cutoff of the paper), suppose
\[
 r_N=L_N\sqrt{\frac{\log N}{N}},
 \qquad L_N\longrightarrow\infty,
 \qquad r_N\le1.
\]
Then the cutoff is Haar-full.  Pressure universality holds if
\begin{equation}
 L_N=o\left(
 \frac{N^{(p-2)/(2(p-1))}}{\sqrt{\log N}}
 \right),
\end{equation}
and the expectation-ratio conclusion holds if
\begin{equation}
 L_N=o\left(
 \frac{
 N^{\frac{p-2}{2(p-1)}
 -\frac1{(m-1)(p-1)}}}
 {\sqrt{\log N}}
 \right).
\end{equation}
The latter permits a growing \(L_N\) precisely when
\((m-1)(p-2)>2\).

Equivalently, for \(r_N=N^{-a}\), the cutoff is Haar-full and pressure
universal whenever
\begin{equation}
 \frac1{2(p-1)}<a<\frac12.
\end{equation}
It is Haar-full and satisfies the ratio conclusion whenever
\begin{equation}
 \frac{m+1}{2(m-1)(p-1)}<a<\frac12.
\end{equation}

[Corollary 10 (Solutions for $0\neq\theta \in \mathbb C \backslash \mathbb{R}$) of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Let $c^2 < 4ab$, i.e.\ $\theta$ defined in~\eqref{def:theta} satisfies $\theta= i|\theta| = i \sqrt{4ab-c^2}$. Then~\eqref{eq:lemsollangevin} admits the solution
\begin{subequations}
\begin{align}
    \begin{split} 
       q_t &= \Bigl[ \cos\Bigl(t\mfrac{|\theta|}{2}\Bigr)+ \frac{c}{|\theta|}\sin\Bigl(t\mfrac{|\theta|}{2}\Bigr)  \Bigr] e^{-\frac{c}{2}t}q_0 + \frac{2a}{|\theta|} \sin\Bigl(t\mfrac{|\theta|}{2}\Bigr)e^{-\frac{c}{2}t}p_0 \\ 
       & \qquad - \mfrac{2a}{|\theta|} \int_0^t \sin\Bigl((t-s)\mfrac{|\theta|}{2}\Bigr)e^{-\frac{c}{2}(t-s)}  \nabla V(q_s,\tilde q_s) ds   +  \frac{2a\tilde c}{|\theta|} \int_0^t \sin\Bigl((t-s)\mfrac{|\theta|}{2}\Bigr)e^{-\frac{c}{2}(t-s)}  dB_s,
    \end{split}\\
    \begin{split}
    p_t &=  - \frac{2b}{|\theta|}  \sin\Bigl(t\mfrac{|\theta|}{2}\Bigr)e^{-\frac{c}{2}t}q_0 + \Bigl[\cos\Bigl(t\mfrac{|\theta|}{2}\Bigr) - \frac{c}{|\theta|}\sin\Bigl(t \mfrac{|\theta|}{2}\Bigr)\Bigr]e^{-\frac{c}{2}t}p_0 \\
    & \qquad - \int_0^t \Bigl[ \cos\Bigl((t-s)\frac{|\theta|}{2}\Bigr) - \frac{c}{|\theta|} \sin\Bigl((t-s)\frac{|\theta|}{2}\Bigr) \Bigr] \nabla V(q_s,\tilde q_s) e^{-\frac{c}{2}(t-s)} ds \\
    &\qquad+ \  \tilde c \int_0^t \left( \cos\Bigl((t-s)\mfrac{|\theta|}{2}\Bigr) - \frac{c}{|\theta|} \sin\Bigl((t-s)\mfrac{|\theta|}{2}\Bigr) \right) e^{-\frac{c}{2}(t-s)} dB_s.
    \end{split}
\end{align}
\end{subequations}

