[Definition def: approx amplitude of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] Let $\sigma \in \{\emptyset,-,+\}$ and $\varphi_-^{0,\sigma},\varphi_+^{0,\sigma} \in S'(\mathbb T^2)$. The regularized $\varphi^4_3$ amplitude on $M^\sigma$ is the map
\begin{equation}
	\mathcal A_T^\sigma:C^\infty(M^\sigma)\times S'(\mathbb T^2)\times S'(\mathbb T^2) \rightarrow \mathbb R
\end{equation}
defined by
\begin{equation}
	\mathcal A_T^\sigma(f \mid \varphi_-^\sigma,\varphi_+^\sigma):= \mathcal A^{\rm free, \sigma}(f \mid \varphi_-^{0,\sigma},\varphi_+^{0,\sigma}) \mathcal E_{T}^\sigma(\varphi_-^\sigma,\varphi_+^\sigma)  
	 \mathcal Z^\sigma_T(f \mid \varphi^\sigma_-,\varphi^\sigma_+). 
\end{equation}

[Theorem 9 of arXiv:2604.00474, 'Trap behaviors for Brownian motions'] The solution $u \in C((0, \infty), D) \times \bar{D}_L$ to \eqref{probXbar} has the representation
\begin{align}
\mathbf{E}_x\left[ f(\bar{X}_t) \right] = & \mathbf{E}_x\left[f(X^+ \circ \bar{V}^{-1}_t) \exp \left( - (c/\sigma)\, \gamma^+ \circ \bar{V}^{-1}_t \right) \right], \quad t>0,\; x \in \overline{D}

\end{align}
where $\bar{V}^{-1}_t$ is the inverse to 
\begin{align}
\bar{V}_t = t + H \circ (\eta/\sigma) \gamma^+_t, \quad t\geq 0.
\end{align}

[Lemma l3.3 of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] For any $t_1,t_2\in[0,T]$ and $p \geq 2$,
\begin{equation}
	\mathbb{E}|X_{t_1}^{\varepsilon,h^\varepsilon}-X_{t_2}^{\varepsilon,h^\varepsilon}|^p \lesssim_{x,y,p,M,T}|t_1-t_2|^{\frac{p}{2}}+|t_{1}-t_{2}|^{\frac{p(q-2)}{2q}}.
\end{equation}

