[Definition Horizontal perimeter of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] For a measurable set $\Omega\subset \mathbb{G}$, its \emph{horizontal perimeter} is defined by
\begin{align*}
    \operatorname{Per}_{\mathcal H}(\Omega)=\sup\left\{\int_{\Omega}\sum_{i=1}^{d} X_i \rho_i: \|\sum_{i=1}^d \rho^2_i\|_\infty\leqslant 1, \rho_i\in C_c^\infty(\mathbb G)\right\},
\end{align*}
where $\{X_1, \ldots, X_{d}\}$ is an orthonormal frame in $V_1$. A measurable set $\Omega\subset \mathbb{G}$ is called a \emph{Caccioppoli set} if $\operatorname{Per}_{\mathcal H}(\Omega)<\infty$.

[Lemma guided-diffusion-u-v of arXiv:2608.29507, 'Denoising as Projection: Constrained Optimization with Gradient-Guided Diffusion'] Define
    \begin{align}
        u_t:= Ax_t, \qquad v_t := A^{\perp} x_t
    \end{align}
    then (equation eq:guided-diffusion of the paper) with Assumption (assump:linear of the paper) would give the following update
    \begin{align*}
        v_{t-1} &= \frac{\sigma_{t-1}}{\sigma_t} v_t\\
        u_{t-1} &= u_t - (1-\frac{\sigma_{t-1}}{\sigma_t})(I + \sigma_t^2\Sigma^{-1})^{-1}(\sigma_t^2 \Sigma^{-1} u_t + \eta_t A \nabla f(x_t)) 
    \end{align*}
    \begin{proof}
        From Lemma (lemma:pi-t of the paper), $\widehat\pi_t(x) = A^\top (I + \sigma_t^2 \Sigma^{-1})^{-1}Ax$, hence
        \begin{align*}
            v_{t-1} &= A^{\perp} x_{t-1} = A^{\perp}\left(\frac{\sigma_{t-1}}{\sigma_t} x_t + \left(1- \frac{\sigma_{t-1}}{\sigma_t}\right)\widehat\pi_t(x_t -\eta_t \nabla f(x_t))\right)\\
            &= A^{\perp}\left(\frac{\sigma_{t-1}}{\sigma_t} x_t + \left(1- \frac{\sigma_{t-1}}{\sigma_t}\right)A^\top (I + \sigma_t^2 \Sigma^{-1})^{-1}A(x_t -\eta_t \nabla f(x_t))\right)\\
            &= \frac{\sigma_{t-1}}{\sigma_t}A^{\perp} x_t =\frac{\sigma_{t-1}}{\sigma_t} v_t\\
            u_{t-1} &= A x_{t-1} = A\left(\frac{\sigma_{t-1}}{\sigma_t} x_t + \left(1- \frac{\sigma_{t-1}}{\sigma_t}\right)\widehat\pi_t(x_t -\eta_t \nabla f(x_t))\right)\\
            &= A\left(\frac{\sigma_{t-1}}{\sigma_t} x_t + \left(1- \frac{\sigma_{t-1}}{\sigma_t}\right)A^\top (I + \sigma_t^2 \Sigma^{-1})^{-1}A(x_t -\eta_t \nabla f(x_t))\right)\\
            &= \frac{\sigma_{t-1}}{\sigma_t} u_t + \left(1- \frac{\sigma_{t-1}}{\sigma_t}\right)(I + \sigma_t^2 \Sigma^{-1})^{-1} (u_t - \eta_tA\nabla f(x_t))\\
            & = u_t + \left(1- \frac{\sigma_{t-1}}{\sigma_t}\right)\left(-u_t + (I + \sigma_t^2 \Sigma^{-1})^{-1} (u_t - \eta_tA\nabla f(x_t))\right)\\
            & = u_t + \left(1- \frac{\sigma_{t-1}}{\sigma_t}\right)(I + \sigma_t^2\Sigma^{-1})^{-1} (-\sigma_t^2\Sigma^{-1}u_t -\eta_t A\nabla f(x_t) )
        \end{align*}
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Deff 4 (Extended Carre du Champ operator) of arXiv:2604.20435, 'Stochastic Extinction with Relaxed Boundedness Conditions'] Let $A\subset M$ be an open invariant set. Define $\mathcal D^{ext}_2(A)$ be set of all continuous $f : A \to \R$ such that there exist continuous functions $\Lom f : A \to \R$ and $\Gamma f : A \to [0, \infty)$ such that $M^f_t(x)$ \begin{equation}
	M^f_t(x) := f(X^x_t) - f(x) - \int_0^t \Lom f(X^x_s) ds
\end{equation}
is a cadlag square integrable martingale and the stochastic process 
\begin{equation}
	(M^f_t(x))^2 - \int_0^t \Gamma f(X^x_s) ds
\end{equation}
is a martingale for
	all $x \in A$.

[Lemma 62 (cf. {\cite[Lemma 3.2) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] {Mak24}}] 
    Suppose $ \log n \ll np \ll \sqrt{n}$ and let $\epsilon = \epsilon(n) > 0$ be such that $\sqrt{\log n/ np} \ll \epsilon < 1/2$. There exists some universal constant $C > 0$ such that for any $K > 0$ the following holds with probability at least $1 - O(n^{-K})$: 
    \begin{enumerate}[(i)]
        \item for all $u,v \in V$
            \begin{equation} 
                \effR{G_{n,p}}{u}{v} \leq \frac{2(1 + C \epsilon)}{np};
            \end{equation}
        \item and for all edges $e = (u,v)$ and $f$ with $|e \cap f| = 1$
            \begin{equation} 
                \effR{G_{n,p} / f}{u}{v} \leq \frac{3(1+C \epsilon)}{2np}.
            \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition p:easycheeger of arXiv:2510.00748, '\bf On irreducible central limit theorems'] Let $G=(V,\mathcal{E})$ be a finite graph respecting Convention (conv;simple of the paper) with $|V|=N$ and let $\mu_k$ be the $k$-th smallest eigenvalue of the normalized Laplacian ${\ensuremath{\mathcal L}} $, for $k=2,\ldots,N$.
Then,
\begin{equation}
    \mu_k \le 2 \, \varphi_k(G)\,.
\end{equation}

