[Proposition 60 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] For every partition $\lambda$ and every $w\in S_n$,
\begin{equation}
 \Nrm_{x,z}\bigl(\overline H_{w,\lambda}(x,z)\bigr)\in\RV.
\end{equation}
If $\operatorname{char}(\kk)=0$ and the packet is nonzero, it admits a
smooth integral projective realization.

[Proposition 19 of arXiv:2609.03248, 'Connections between colored restricted $b$-ary and ordinary partitions'] Let $\rho\geq 1$ and $b\geq 2$ be integers. Then
\begin{enumerate}
\item[(a)] the numbers $C_b^\rho(n)$ of $\rho$-color $b$-ary partitions 
of $n$, and 
\item[(b)] the numbers $Y_n$ of compositions of $n$ into $\rho$ parts
\end{enumerate}
are connected by the recurrence relation
\begin{equation}
C_b^\rho(bn+j)=\sum_{k=0}^n Y_{bk+j}C_b^\rho(n-k) \qquad (j=0, 1,\ldots b-1).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: BK for Ising weak four arm of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] For any integers $0<M_1<M_2$, let $\mathtt{Con_2}(M_1,M_2)$ be the event that there exist two plus crossings in the annulus $\Lambda_{M_2}\setminus\Lambda_{M_1}$ such that their plus spin clusters, restricted to $\Lambda_{M_2}\setminus\Lambda_{M_1}$, are disjoint. Then there exists a constant $c_8>0$ such that for any integers $M_2>M_1>0$ and any boundary conditions $\xi,\nu$ on $\partial\Lambda_{M_2}$ and $\partial\Lambda_{M_1+1}$, respectively, we have
\begin{equation}
\mu_{\Lambda_{M_2}\setminus\Lambda_{M_1}}^{\nu,\xi}(\mathtt{Con_2}(M_1,M_2))\le c_8\Big(\frac{M_2}{M_1}\Big)^{-\frac{1}{4}}.
\end{equation}

[Lemma 17 (Levi form and weak pseudoconvexity) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] On $\Omega_N$,
\begin{equation}
 (\partial_j\bar\partial_k\Phi_{N,\beta})_{j,k}=\frac\beta2I_N.
\end{equation}
Moreover, $|Z|^2+|\Delta_N(Z)|^{-2}$ is a smooth strictly plurisubharmonic exhaustion of $\Omega_N$.
In particular, $\Omega_N$ is weakly pseudoconvex.

[Theorem PT7 of arXiv:2509.20657, 'Scaling limit for Brownian motions \\ on the $l$-level Sierpinski gaskets: \\ The fractal '] For any $t_0>0$, there exist constants $C$ and $\gamma>0$ such that
\[\left|p^{l}_{\tau^lt}(x,y)-p^{l}_{\tau^lt}(x',y')\right|\leq Ct^{-(1+3d/4)}\left(|x-x'|\vee|y-y'|\vee l^{-1}\right)^{\gamma},\]
for all $x,x',y,y' \in \mathrm{SG}(l)$, $t\in [4l^{-2},t_0]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi iota of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] For $J\in \mathbb{R}^{\mathcal E}_a$ we define $\iota J\in \mathcal{M}(\mathbb{R}^n;\mathbb{R}^n)$ by 
    \begin{align*}
        \iota J=\frac12\sum_{(x,y)\in\mathcal E}J(x,y)\frac{y-x}{|y-x|}\mathcal{H}^1|_{[x,y]}. 
    \end{align*}

