On $U_T=U\times(0,T]$ let $Lu=-a^{ij}(x,t)u_{x_ix_j}+b^i(x,t)u_{x_i}+c(x,t)u$ with real coefficients, $a^{ij}=a^{ji}$. The operator $\partial_t+L$ is uniformly parabolic if there is $\theta>0$ with $a^{ij}(x,t)\xi_i\xi_j\ge\theta|\xi|^2$ for all $(x,t)\in U_T$, $\xi\in\mathbb R^n$ (the heat operator is $a^{ij}=\delta^{ij}$, $b=0$, $c=0$). $C^2_1(U_T)$ denotes functions $u$ with $u,Du,D^2u,u_t$ continuous in $U_T$. A function $u\in C^2_1(U_T)$ is a subsolution if $u_t+Lu\le0$ in $U_T$ and a supersolution if $u_t+Lu\ge0$. Sign conventions matter: with this $L$, maximum principles need $c\equiv0$ or $c\ge0$ (see the pitfall on the zeroth-order term).
a^{ij} = a^{ji}
a^{ij} xi_i xi_j >= theta |xi|^2 with theta > 0 on U_T

[Lemma L:lmm_tu of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Let $0<s<t$, and $a,b,c \in \mathbb{R}$ satisfy the property that $-1 <a <0$, $b > c
    \geq -2$ and $a + b + c > -4$. Furthermore, suppose that $t - s \ll s$. Denote
  by
  \begin{align*}
    I  \coloneqq & \int_{s}^{t} \ensuremath{\mathrm{d} } \theta_2 \int_{s}^{\theta_2} \ensuremath{\mathrm{d} } \theta_1  \int_0^s \ensuremath{\mathrm{d} } r_2 \int_{0 \vee (r_2 - \theta_2 + \theta_1)}^{r_2} \ensuremath{\mathrm{d} } r_1 \: (r_2-r_1)^{a}  (\theta_1 - r_1)^{b}  (\theta_2 - r_2)^{c} \shortintertext{and}
    I' \coloneqq & \int_{s}^{t} \ensuremath{\mathrm{d} } \theta_2 \int_{s}^{t} \ensuremath{\mathrm{d} } \theta_1  \int_0^s \ensuremath{\mathrm{d} } r_2 \int_{0}^{(r_2 - \theta_2 + \theta_1) \wedge r_2} \ensuremath{\mathrm{d} } r_1 \: (r_2-r_1)^{a}  (\theta_1 - r_1)^{c} (\theta_2 - r_2)^{b}.
  \end{align*}
  Then, the following inequalities hold.
  \begin{align*}
    I \lesssim (t-s)^{(a + b + c + 4)\wedge 2} \quad  \text{and} \quad
    I' \lesssim \begin{dcases}
                  (t-s)^{(a + b + c + 4)\wedge 2}, & a + b + c \neq -2, \\
                  (t-s)^2 (1 + |\log (t-s)|),      & a + b + c = -2.
                \end{dcases}
  \end{align*}

[Proposition 5 of arXiv:2607.20714, 'High Minima of Gaussian Processes: Overshoots and Minimizer Locations'] Suppose that $\sigma_*^2>0$, and let $T$ be any measurable selection from
$\argmin_{t\in K}X(t)$.  Then $M\in\mathbb D^{1,2}$ and
\begin{equation}
 DM=R_T:=R(T,\cdot)\qquad\text{almost surely}.

\end{equation}
The random element $R_T\in\cH$ is independent of the chosen minimizer
selection.  Moreover, if $f:\mathbb R\to\mathbb R$ is locally absolutely
continuous and $f'\in L^\infty(\mathbb R)$, then
$f(M)\in\mathbb D^{1,2}$ and, for every $h\in\cH$,
\begin{equation}
 \Ee\bigl\{W(h)f(M)\bigr\}
 =\Ee\bigl\{f'(M)h(T)\bigr\}.

\end{equation}
Here $f'$ may be chosen arbitrarily on its Lebesgue-null set of
non-differentiability.

[Proposition saddle relations of arXiv:2608.27771, 'A normal form for the Thin Flat Surfaces category'] Relations 11 and 12 shown in Figure (Fig:Relations11-12 of the paper)  hold in the $\mathbf{TFS}$ category involving the saddles $S_1$ and $S_2$ and the permutation P:  
\begin{center}
\includegraphics[width=0.8\textwidth]{Normal/Relations11-12.pdf}
    \captionof{figure}{Relations 11 and 12:  $S_1 \circ P = S_2 = P\circ S_1$, and
        $S_2 \circ P = S_1 = P\circ S_2$. }
\end{center}

[Lemma 14 of arXiv:2609.01826, 'An extension theory for fully fractional Schr\"odinger equations with memory'] Let \(a>-1\) and \(t\neq 0\). Then we define the boundary kernel 
\[
P_{a}(z,t) := -i\,z^{-a}\,\partial_z S_{-a}(z,0,t)
=
\frac{2^{a-1}\operatorname{sgn}(t)}{\Gamma\!\left(\frac{1-a}{2}\right)}
\,z^{1-a}\,|t|^{\frac{a-3}{2}}
\,e^{-i\,\operatorname{sgn}(t)\,\frac{(1-a)\pi}{4}}
\,e^{i\frac{z^2}{4t}}.
\]

[Lemma WPD-NHS-HUD-BB of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] For any $N \in \left\{ {0,1, \cdots ,10} \right\} $ and $t \in \mathop  \cap \limits_{j = 0}^{q} \left[ {0,{\mathfrak{t}_j}} \right] \cap \left[ {{t_k},{t_{k + 1}}} \right)$, the stream function ${\mathfrak{S}_\xi }\left( \cdot \right)$ defined by (equation IUHYU-DJ of the paper) admits
\begin{equation}
{\left\| {{\mathfrak{S}_\xi }\left( {{\lambda _{q + 1}}{{\tilde \Phi }_k}} \right)} \right\|_N} \lesssim \delta _q^{\frac{1}{2}} \lambda _{q + 1}^N  ,
\end{equation}
\begin{equation}
{\left\| {{{\bar D}_{t,\Gamma }}{\mathfrak{S}_\xi }\left( {{\lambda _{q + 1}}{{\tilde \Phi }_k}} \right)} \right\|_N} \lesssim  \delta _q^{\frac{1}{2}}\lambda _{q + 1}^{N + 1}  ,
\end{equation}
and
\begin{equation}
{\left\| {{\partial _{tt}}{\mathfrak{S}_\xi } \left( {{\lambda _{q + 1}}{{\tilde \Phi }_k}} \right)} \right\|_N} \lesssim  \delta _q^{\frac{1}{2}}\lambda _q^{N + 1}\lambda _{q + 1}^2   .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 29 of arXiv:2608.29086, '2608.29086'] [Rational molecules $RAT(Mol)$]
Given $m \in Obj(Mol)$. $m$ is called a \textit{rational molecule} if 
\begin{equation*}
\exists \lambda \in INT(Mol) \cap MOL(M_0) \text{ s.t. } Part(\lambda,m) \neq \emptyset
\end{equation*} 
(Figure \ref{figure3} (a)). $\lambda$ is called an \textit{integral closure} of $m$. $Cl(m)$ denotes the collection of all integral closure of $m$, i.e,
\begin{equation*} 
Cl(m):=\{\lambda \in INT(Mol) \cap MOL(M_0)\ |\ Part(\lambda,m) \neq \emptyset \}.
\end{equation*} 
$RAT(Mol)$ denotes the collection of all rational molecules, i.e., 
\begin{equation*} 
RAT(Mol):=\{m \in Obj(Mol) \ |\ Cl(m) \neq \emptyset\}.
\end{equation*}
The collection $RAT(Loop)$ of rational loops and the collection $RAT(Reg)$ of rational regions are also defined in the same way (Figure \ref{figure3} (b)).

[Prop quotient L2 formula of arXiv:2604.23890, 'The Cutoff Profile for Random Transpositions on Repeated Cards in the Full Range of Parame'] Let \(G\) be a finite group and \(H\leq G\) be a subgroup. Let
\(\mu_1,\mu_2:G\to\mathbb{C}\) be two class functions which are probability measures on \(G\).
For each irreducible representation \(\rho\) of \(G\), let
\(a_\rho^{(1)},a_\rho^{(2)}\in\mathbb{C}\) be the scalars such that
\begin{equation}
\sum_{g\in G}\mu_i(g)\rho(g)=a_\rho^{(i)}I_{d_\rho},
\qquad i=1,2.
\end{equation}
Denote by \(\sim_H\backslash\mu_1,\sim_H\backslash\mu_2\) the probability measures on
the left coset space \(H\backslash G\) induced by \(\mu_1,\mu_2\), respectively. Then, we have
\begin{equation}
D_{L^2}(\sim_H\backslash\mu_1,\sim_H\backslash\mu_2)^2
=
\frac{|H|}{|G|}
\sum_{\rho}
d_\rho\,\dim(V_\rho^H)\,
\left|a_\rho^{(1)}-a_\rho^{(2)}\right|^2.
\end{equation}
Here, \(D_{L^2}\) denotes the \(L^2\)-distance between measures on the quotient space
\(H\backslash G\), while on the right-hand side, we sum over all nontrivial irreducible representations $\rho$ of $G$.

[Lemma lem:one_extension of arXiv:2605.26048, 'Classification of the eternal solutions and multiple coalescing shocks in the KPZ fixed po'] Let $\widetilde \varphi$ be any function $\mathfrak{X}\rightarrow [-\infty,\infty)$.   Define the function $ \varphi:\mathfrak{X} \to [-\infty,\infty]$ by 
    \begin{equation} 
    \varphi(\xi) := \limsup_{\eta \to \xi}\widetilde \varphi(\eta) =  \lim_{\varepsilon \downarrow 0} \sup_{0 \le |\eta - \xi| \le \varepsilon} \widetilde \varphi(\eta),
    \end{equation}
    where we have added the second equality to clarify that we allow $\eta = \xi$ in the supremum. 
    Then, $\varphi \in \operatorname{USC}(\mathfrak{X})$, and $W\star  \varphi = W\star \widetilde \varphi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Definition of mixing of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] A sublinear expectation system $(\Omega, \mathcal{H}, (U_t)_{t\in \mathbb T}, \hat{\mathbb{E}})$ ($\mathbb T=\mathbb N, \mathbb Z, \mathbb R_+, \mathbb R$) is called mixing if for any $X\in \mathcal{H}^{d_1},Y \in \mathcal{H}^{d_2}$ and $\phi \in C_{lip}(\mathbb{R}^{d_1+d_2})$, we have
		\begin{equation}

			\lim_{t\rightarrow \infty}\hat{\mathbb{E}}[\phi(X,U_tY)]=\hat{\mathbb{E}}[\hat{\mathbb{E}}[\phi(x,Y)]|_{x=X}].
		\end{equation}

[Theorem thm4.3 of arXiv:2606.01944, 'Propagation of Chaos for Mean-field Mean Reflected Backward Stochastic Differential Equati'] For any $1\leq i\leq N$, set 
\begin{align*}
\hat{Y}^i:=Y^i-\bar{Y}^i, \ \hat{K}:=K^{(N)}-K,\ \hat{Z}^i:=Z^i-\bar{Z}^i e_i,
\end{align*}
where $(e_1,\cdots,e_N)$ is the canonical basis in $\mathbb{R}^N$.

\begin{itemize}
\item[1.] If $h\in C^{1,2}_b([0,T]\times\mathbb{R})$ and $\sup_{t\in[0,T]}\mathsf{E}[|\bar{Z}^1_t|^4]<\infty$, then there exists a constant $C$ independent of $N$, such that
\begin{align*}
\mathsf{E}\left[\sup_{t\in[0,T]}|\hat{Y}^i_t|^2\right]\leq CN^{-1}, \ \mathsf{E}\left[\sup_{t\in[0,T]}|\hat{K}_t|^2\right]\leq CN^{-1/2}, \ \mathsf{E}\left[\int_0^T|\hat{Z}^i_t|^2dt\right]\leq CN^{-1/2}.
\end{align*}

\item[2.] If $\xi$ is $p$-integrable, $\mathsf{E}[\int_0^T |f(t,0,0)|^pdt]<\infty$ and $\sup_{t\in[0,T]}\mathsf{E}[|\bar{Z}^1_t|^p]<\infty$ for some $p>4$, then there exists a constant $C$ independent of $N$, such that
\begin{align*}
\mathsf{E}\left[\sup_{t\in[0,T]}|\hat{Y}^i_t|^2\right]\leq CN^{-1/2}, \ \mathsf{E}\left[\sup_{t\in[r,T]}|\hat{K}_t|^2\right]\leq CN^{-1/4}, \ \mathsf{E}\left[\int_0^T|\hat{Z}^i_t|^2dt\right]\leq CN^{-1/4}.
\end{align*}

\end{itemize}

