[Proposition prop:profile-wellposedness-comp of arXiv:2609.00698, 'Kinetic Wedge Layers and Diffusive Limit of Neutron Transport in Polygonal Domains'] Under (equation eq:strict-convexity of the paper) and Assumption~(ass:primitive-data-comp of the paper), and with the parameters of Section~(subsec:parameters-data of the paper), the lifting normalization of Section~(subsec:harmonic-lifts-comp of the paper) and the cutoffs, extensions and length scales of Section~(sec:matching-realization of the paper) fixed, the following are uniquely defined:
\begin{enumerate}[label=\textup{(\roman*)}]
\item the interior and decaying side profiles $\{\rho_k,U_k,\mathcal U_{j,k}:0\le k\le N\}$ generated by (equation eq:microscopic-recursion-comp of the paper)--(equation eq:side-profile-recursion-comp of the paper), with $\rho_k$, $k\ge1$, as in Definition~(def:finite-part-solution-comp of the paper).
\item the construction expansion truncated at $\widetilde{T}$ and the matching subexpansion truncated at $T$, as in (equation eq:two-ledgers-comp of the paper).
\item every corrector $D_{m,\alpha,b}$, $(\alpha,b)\in\mathfrak J_m^{\rm mat}$, as the unique bounded mild solution of (equation eq:defect-wedge-problem of the paper).
\item after the fixed linear assembly choices above, the regularized base $U_{\mathrm{base}}^{\varepsilon,[N]}$ and the composite $U_{\mathrm{app}}^{\varepsilon,[N]}(\delta)$.
\end{enumerate}
Moreover, for the uniform integer $L_{\ln}=N+1$ defined above,
\begin{align}
 \abs{\mathcal D_m^\varepsilon(Y,v)}
 \le C(1+\abs{\ln\varepsilon})^{L_{\ln}}\left\langleR\right\rangle^{-\beta}.

\end{align}
Every coefficient depends continuously and linearly on $g_{j,0},g_{j,1},g_{j,2}$.

[Lemma 3step of arXiv:2608.09589, 'On stochastic stability of systems\\ driven by red noise\thanks{The authors gratefully ack'] For $\delta_2$ and $C_2$ as in Lemma (foster-lyapunov of the paper),
\begin{equation}
    \mathbb{E}[V(\bar{X}_{n+1},\bar{Y}_{n+1})\mid\mathcal{F}_n']\leq \delta_2 V(\bar{X}_{n},\bar{Y}_{n})+C_2.
    \end{equation}
    Furthermore, $C_{3}>0$ and $\delta_3$ as in Lemma (foster-lyapunov of the paper), on the event
$\{|X_n|+B|Y_n|+|\bar{X}_{n}|+B|\bar{Y}_{n}|>2C_3\}$
\begin{equation}

    \begin{aligned}
      &\mathbb{E}_n[V(X_{n+1},Y_{n+1})+V(\bar{X}_{n+1},\bar{Y}_{n+1})\mid\mathcal{F}_{n}']\\
      \leq~&\delta_3 [V(X_{n},Y_{n}) +V(\bar{X}_{n},\bar{Y}_{n})].
    \end{aligned}    
\end{equation}

[Definition 11 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] $\Phi$ is said to be \textit{uniformly Ces\`aro eventually continuous with respect to a family $\mathfrak{F}\subset\mathcal{A}$ at $x\in\X$} if 
		\begin{equation*}
			\limsup\limits_{x'\rightarrow x}\limsup\limits_{t\rightarrow\infty}\sup_{f\in\mathfrak{F}}|Q_tf(x')-Q_tf(x)|=0.
		\end{equation*}

