[Lemma 12 (A relative determinant inequality) of arXiv:2608.20101, '\bfseries Largest bulk gap of the complex Ginibre ensemble'] Let \(A,C\) be positive trace-class contractions on a Hilbert space, assume
\(0\le A\le C\) and \(\|C\|<1\), and put \(D=C-A\).  Then
\begin{equation}
 0\le \log\frac{\det(I-A)}{\det(I-C)}
 \le \|(I-C)^{-1}\|\,\Tr D.
\end{equation}

[Proposition eq:bd_It of arXiv:2411.09482, 'Anomalous Regularization in Kazantsev-Kraichnan Model'] Take $s\in (0,d/2)$ and $\alpha\in (0,1)$. Then we have, as $|n|\to\infty$,
\begin{align}
    \mathcal{I}_{tra}(n) = c_{tra}|n|^{-2s+2-2\alpha}  +O(|n|^{-2s}),
\end{align}
where\footnote{The constant $c_{tra}$ comes exactly from [galeati2024anomalous], as one can check using $\Gamma(z+1)=z\Gamma(z)$; mind that, unlike in [galeati2024anomalous], here the integral $\mathcal{I}_{tra}(n)$ is not multiplied by $(2\pi)^{-d/2}$.}
\begin{align*}
    c_{tra}= -(d-1)(s+\alpha-1)(d+2-2s-2\alpha)C_{d,s,\alpha}
\end{align*}
and
\begin{align}
    C_{d,s,\alpha} = -\frac{\pi^{d/2}\Gamma(s+\alpha-1)\Gamma\left(\frac{d-2s+2}{2}\right)\Gamma(-\alpha)}{4\Gamma(s)\Gamma\left(\frac{d+2+2\alpha}{2}\right)\Gamma\left(\frac{d+4-2s-2\alpha}{2}\right)}>0.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:multCol of arXiv:2508.03577, 'Phase Transitions in a Particle Model\\ for the Self-Adaptive Response to Cancer Dynamics'] \begin{enumerate}
    \item(PAI off, $\lambda_m=0$)
    Let $(A_t)_{t\ge 0}$ be the evolution of the model according to Definition (def:mutlCol of the paper). Let $\tau$ be the first time a column is equal to $\1=(1,\ldots,1)$. Denote $b=\tfrac{pM}{qN}$ and assume that this remains constant. We then have that for $\varepsilon_M\to 0$ sufficiently slowly\footnote{here, $\varepsilon_M>\log^{-1/2}(M)$ is sufficient}
    \begin{equation}
        \lim_{\mycom{M\to\infty}{b={pM}/\left(qN\right)}}\mathbb{P}\rk{\abs{\tau-\frac{M\log(M)}{q}}\le \varepsilon_M M\log(M)\mid A_0\equiv 0}=1\, .
    \end{equation}
    Furthermore, as $M\to\infty $ and $b=\tfrac{pM}{qN}$ constant, we have that
    \begin{equation}
        \mathbb{E}_\pi\ek{\#\gk{\text{columns }c\text{ with }c\equiv 1}}\sim N\frac{\Gamma(b+1)}{ (M/q)^{b}}\, ,
    \end{equation}
    where $\pi$ is the stationary distribution (on the space of matrices). Furthermore, after time $\tau(1+\varepsilon)$, the number of columns equal to 1 agrees with the stationary distribution. This implies that the model has a cut-off phenomenon on the $\log$-scale.
    \item(PAI on) Introduce now the new parameter $\widetilde{q}=q+\lambda_m$. Denote $\widetilde{b}=\tfrac{{p}M}{\widetilde{q}N}$ and assume that it remains constant. We then have that under the same conditions on $\varepsilon_M$ as before
    \begin{equation}
         \lim_{\mycom{M\to\infty}{\widetilde{b}={pM}/\left(qN\right)}}\mathbb{P}\rk{\abs{\tau-\frac{M\log(M)}{\widetilde{q}}}\le \varepsilon_M M\log(M)\mid A_0\equiv 0}=1\, ,
    \end{equation}
    as well as
    \begin{equation}
        \mathbb{E}_\pi\ek{\#\gk{\text{columns }c\text{ with }c\equiv 1}}\sim N\frac{\Gamma\rk{\widetilde{b}+1}}{ (M/\widetilde{q})^{\widetilde{b}}}\, .
    \end{equation}
    Hence, PAI can be achieved by a change of parameters.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

