body:
[Lemma lem:restarted-diffusion-differentiation of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Assume Assumption~(ass:reference-diffusion of the paper).  For deterministic
$0\leq t<r\leq T$ and $x\in\mathbb R^d$, let $\mathscr J^{t,x}$ be the unique
$\mathbb R^{d\times d}$-valued solution of
\begin{equation}
 \,\mathrm d\mathscr J_{t,\tau}^{t,x}
 =D_xb(\tau,X_\tau^{t,x})\mathscr J_{t,\tau}^{t,x}\,\mathrm d\tau
  +\sum_\ell D_x\sigma_{\cdot\ell}(\tau,X_\tau^{t,x})
       \mathscr J_{t,\tau}^{t,x}\,\mathrm d W_\tau^\ell,
 \qquad \mathscr J_{t,t}^{t,x}=I_d.

\end{equation}
It satisfies
$\mathbb E\sup_{t\leq\tau\leq r}|\mathscr J_{t,\tau}^{t,x}|^4
\leq C\exp(C|x|)$.
For the coordinate vectors $e_k$, put
$\delta_{h,k}X^{t,x}:=(X^{t,x+he_k}-X^{t,x})/h$.  These difference quotients satisfy
\begin{equation*}
 \lim_{h\to0}\mathbb E\sup_{t\leq\tau\leq r}
 \left|\delta_{h,k}X_\tau^{t,x}
       -\mathscr J_{t,\tau}^{t,x}e_k\right|^2=0.
\end{equation*}
Consequently, if $I=(r_0,r_1)$ and the scalar fields
$F\in C_c^\infty(I\times\mathbb R^d)$, $\eta\in C_c^\infty(\mathbb R^d)$, then
\begin{equation*}
 u(t,x)=\mathbb E\left[\eta(X_{r_1}^{t,x})
          +\int_t^{r_1}F(\tau,X_\tau^{t,x})\,\mathrm d\tau\right]
\end{equation*}
has, for every $t\in I$, the local weak spatial gradient
\begin{equation*}
 D_xu(t,x)=\mathbb E\left[
   (\mathscr J_{t,r_1}^{t,x})^\top D_x\eta(X_{r_1}^{t,x})
   +\int_t^{r_1}(\mathscr J_{t,\tau}^{t,x})^\top
       D_xF(\tau,X_\tau^{t,x})\,\mathrm d\tau\right].
\end{equation*}

[Thm 8 of arXiv:2512.10199, 'Explicit correlation functions for the six-vertex model in the free-fermion regime'] The partition function $Z^{\gen}_n$ has the explicit formula
    \begin{equation*}
        Z^{\gen}_n = \sum_{\theta \in \{0,1\}^2 } C_\theta \det(K_\theta)
    \end{equation*}
    where $C_\theta = \frac{1}{2}(-1)^{(\theta_1 + n + 1)(\theta_2 + n + 1)}$, and $K_\theta$ is defined in Equation \eqref{eq:Kdef}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor cor_santaloMeasureSpecific of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] Let the setup be the same as in Lemma~(lem_santaloMeasure of the paper). If $\Gamma = \eta\zeta$ for some $\eta,\zeta\in U$ then
    \begin{align*}
        \nu_G(\mkern 1.5mu\overline{\mkern-1.5mu\eta\zeta\mkern-1.5mu}\mkern 1.5mu) = d(\eta,\zeta)
    \end{align*}

