[Lemma 9 ({Nakano and Takei \cite[Lemma 3.1) of arXiv:2605.23461, 'An almost sure invariance principle for the Takagi--van der Waerden class functions'] {NakanoTakeiTakagifunctions}}]
  For any $\{a_k\}_{k\ge 1}$ and any integers $n>m\ge 1$, we have
  \begin{equation}
    \frac{1}{K(p)}\cdot (A_n-A_m) \le E\bigl[(S_m-S_n)^2\bigr] \le K(p)\cdot (A_n-A_m).
  \end{equation}
  Here $K(p)$ is the constant defined by \eqref{eq:Kp_definition}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm.zador of arXiv:2505.15283, 'Quantization of Probability Distributions via Divide-and-Conquer: Convergence and Error Pr'] Suppose ${\mathbb{E}}[|X|^{1+\delta}]<\infty$ for some $\delta>0$ and assume that the distribution of $X$, denoted by $\mu$, is absolutely continuous with respect to Lebesgue measure with density $f$. 
    Then 
    \begin{equation*}
        \lim_{n\to \infty} n \inf_{\substack{\nu \in {\mathcal{M}} \\ \#(\mathrm{supp}\,(\nu)) =n }} W_{1}(\mu,\nu) = \frac{1}{4} 
        \left(
            \int \sqrt{f} \mathrm{d} x 
        \right)^2,
    \end{equation*}
    where the infimum is over all probability measures with $n$ distinct Dirac measures. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Minors of delta matrix bis of arXiv:2609.04072, 'Oort's conjecture for split unitary Shimura varieties'] Let $s_0< s_1\in \mathbb{Z}_{\geq 0}$. For any $s\in\llbracket s_0,s_1-1\rrbracket$ and any $\alpha\in \mathcal B_s$, let $r(\alpha)\in\mathbb{Z}$ and let $\tilde{P}_\alpha\in \mathcal F$. Suppose that the $\tilde{P}_\alpha$ are affine in all variables of level $l\geq s_1-s_0$.

    Let $(\delta_{i,l}^j)_{(i,j,l)\in \llbracket1,g\rrbracket^2\times \llbracket0,N-1\rrbracket}$ be a family of elements of $\overline{\mathbb{F}}_p$, and define a $(g'+1)\times g$-matrix $A_2(\underline{X})\in \operatorname{Mat}_{(g'+1)\times g}(\mathcal F)$ as:

	\begin{equation}A_2(\underline{X}):=
		\begin{pmatrix}

			\sum\limits_{l=0}^{N-1}\sum\limits_{i=1}^g\delta_{i,l}^1 X_{i,l}-\sum\limits_{s=s_0}^{s_1-1}\sum\limits_{\alpha\in \mathcal B_s} \tilde{P}_\alpha X_{1,s_1-s}^{p^{r(\alpha)}} & \dots & \sum\limits_{l=0}^{N-1}\sum\limits_{i=1}^g\delta_{i,l}^g X_{i,l} -\sum\limits_{s=s_0}^{s_1-1}\sum\limits_{\alpha\in \mathcal B_s} \tilde{P}_\alpha X_{g,s_1-s}^{p^{r(\alpha)}} \\
			X_{1,0}^{p^{r_1}} & \dots & X_{g,0}^{p^{r_1}}\\
			\dots & \dots & \dots
			\\
			X_{1,0}^{p^{r_{g'}}}& \dots &X_{g,0}^{p^{r_{g'}}}
		\end{pmatrix}.
	\end{equation}
Then, if one of the following conditions holds, the matrix $A_2(\underline{X})$ admits a non-zero $(g'+1)$-minor:
\begin{enumerate}
    \item There exists $r\in \mathbb{Z}\setminus\{0\}$ such that $\sum\limits_{\alpha\in \mathcal B_{s_0}, r(\alpha)=r}\tilde{P}_\alpha\neq 0$.
	\item The matrix $(\delta_{i,s_1-s_0}^j)_{(i,j)\in\llbracket1,g\rrbracket}$ is not diagonal.


\end{enumerate}

