[Lemma lem:higher_queue of arXiv:2607.13748, 'Load Balancing with Individually Heterogeneous Servers'] For any $h\in \mathbb{R}^{\infty}$ and $y\in \mathbb{D}_{\mathbb{R}}^{\infty}[0,\infty)$, the following system of equations 
     \begin{align}
         x_1(t) &= x_2(t) = 0,\\
         x_i(t) & = h_i + y_i(t) - \mu_{\min}\int_0^t x_i(s)ds + \mu_{\min}\int_0^t x_{i+1}(s)ds, \mbox{ for all }i\geq 3
     \end{align}
     has a unique solution $x\in \mathbb{D}_{\mathbb{R}}^{\infty}[0,\infty)$ and there exists a well-defined mapping $f:\mathbb{R}^\infty\times \mathbb{D}_{\mathbb{R}}^{\infty}[0,\infty)\to \mathbb{D}_{\mathbb{R}}^{\infty}[0,\infty)$. Furthermore, $f$ is a continuous mapping and $x=f(h,y)$ is continuous if $y$ is continuous. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 23 of arXiv:2609.03512, ''] Let $g(G)=3$ and $r(G)\in \{2,3,4,5\}$. Then $\gamma(G)=\gamma_t(G)=2$ if and only if $G$ belongs to one of the following classes:
\begin{enumerate}

\item $G\in\mathcal{M}(K_3)$, with $m_i\geq2$ for at least one $i\in[3]$;
\item $G\in\mathcal{M}\bigl(B_2,B_4,B_5\bigr)$;
\item $G\in\mathcal{M}\bigl(B_1,K_4\bigr)$, with $m_i\geq 2$ for at least one index $i$ corresponding to a dominating vertex $v_i$ of the base graph.
\item $G\in\mathcal{M}\bigl(D_2,D_5,D_6,D_8,D_9,D_{11},D_{12},D_{13},D_{14},D_{16},D_{17},D_{19}\bigr)$;
\item $G\in\mathcal{M}\bigl(D_{10},D_{15},D_{18},D_{20},D_{21},D_{22},D_{24}\bigr)$, with $m_i\geq 2$ for at least one index $i$ corresponding to a dominating vertex $v_i$ of the base graph.

\end{enumerate}

[Corollary 46 of arXiv:2508.04938, 'Perfect t-embeddings of doubly periodic Aztec diamonds'] Let~$w=w_{\ell x'+i',2y'+j'}$ and~$b=b_{\ell x+i,2y+j}$ be non-boundary vertices in the reduced Aztec diamond. 

The Coulomb gauge functions~$\mathcal F^\bullet$ and~$\mathcal F^\circ$ defined in Proposition~\ref{prop:FG} are given by
\begin{equation*}
 \mathcal F^\bullet(b)=
\frac{1}{2\pi\i}\int_{\tilde \Gamma}\left(f(z)Q(z,w)
  \prod_{m=1}^{2i}\phi_m(z)\right)_{j+1}(z-1)^{\ell N}\frac{w^{x-N}}{z^{y}}\frac{\d z}{z},
\end{equation*}
and
\begin{equation}
\mathcal F^\circ(w)
=\frac{1}{2\pi\i}\int_{\tilde \Gamma}\left(\left(\prod_{m=1}^{2i'+1}\phi_m(z)\right)^{-1}Q(z,w)
  g(z)
  \right)_{j'+1} \frac{z^{y'}}{(z-1)^{\ell N}w^{x'-N}}\d z,
\end{equation}
where 
\begin{equation}
f(z)=\sqrt{a+\i}\left(-\frac{\i\alpha_1}{z-1}
\begin{pmatrix}
1 & -\alpha_1^{-1}
\end{pmatrix}
-\frac{\beta_\ell a}{z-1}
\begin{pmatrix}
1 & \beta_\ell^{-1}
\end{pmatrix}
\right)
=\frac{\sqrt{a+\i}\left(\i-a\right)}{z-1}
\begin{pmatrix}
\i\sqrt{\alpha_1\beta_\ell} & 1
\end{pmatrix}
\end{equation}
and
\begin{equation}
g(z)=\sqrt{a-\i}\left(\frac{\i}{\sqrt{\alpha_1\beta_\ell}}\frac{1}{z}
\begin{pmatrix}
 1 \\
 0
\end{pmatrix}
+
\begin{pmatrix}
  0 \\
  1
\end{pmatrix}
\right)
\end{equation}

