    \node[node] (2) at (-0.5,-0.29) {};
    \node[node] (3) at (0.5,-0.29) {}; 
    \draw[edge] (1) to (2) ; 
    \draw[edge] (3) to (1) 
}, x, y) - t_{W}(
\tikz[motif]{
 \node[node] (1) at (0,0.58) {};
    \node[node] (2) at (-0.5,-0.29) {};
    \node[node] (3) at (0.5,-0.29) {}; 
    \draw[edge] (1) to (2) ; 
    \draw[edge] (3) to (1) 
}, y, x) = d^{\uparrow}_W(y)-d^{\uparrow}_W(x) , 
\end{align} 
where $d^{\uparrow}_W$ is the out-degree function defined in (equation eq:directeddegree of the paper). Hence, $t_{W}(
\tikz[motif]{
