body:
[Lem LDP-relating-X1-X of arXiv:2510.26123, 'Directed distances in bipolar-oriented triangulations:\\ exact exponents and scaling limit'] Let ${\operatorname{XDP}} = \operatorname{LDP}$. Define the KMSW encoding walk $\mathcal Z  :\mathbbm Z\to\mathbbm Z^2$, the infinite directed triangulations $M_{0,\infty} \overset{d}{=} M_{1,\infty}$, and their associated Busemann functions $\mathcal X$ and $\mathcal X^1$ as at the beginning of Section~(sec-recursive of the paper).

    \begin{itemize}
        \item If $\mathcal Z(1)-\mathcal Z(0)=(1,-1)$, then 
            \begin{equation} 
            \Big(\mathcal X(-1)\,,\,\mathcal X(1)\Big)=\mathopen{}\mathclose\bgroup\originalleft(\mathcal X^1(-2) - \max\{\mathcal X^1(-1),1\}\,,\,  - \max\{\mathcal X^1(-1),1\}\aftergroup\egroup\originalright). 
            \end{equation}
        \item If $\mathcal Z(1)-\mathcal Z(0)=(-1,0)$, then 
           \begin{equation} 
           \Big(\mathcal X(-1)\,,\,\mathcal X(1)\Big)=\mathopen{}\mathclose\bgroup\originalleft( - \mathcal X^1(1)-1\,,\,-1\aftergroup\egroup\originalright).
           \end{equation}
        \item If $\mathcal Z(1)-\mathcal Z(0)=(0,1)$, then 
           \begin{equation}  
           \Big(\mathcal X(-1)\,,\,\mathcal X(1)\Big)=\mathopen{}\mathclose\bgroup\originalleft(\mathcal X^1(-1) \,,\, \mathcal X^1(2) \aftergroup\egroup\originalright).
           \end{equation}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

