[Proposition prop:convergence of the roots of arXiv:2606.28031, 'Insurance risk models in a heterogeneous time-dependent population: scaling limits and rui'] Assume:
\begin{enumerate}
\item[{\em (1)}] {the Cram\'er condition (equation cram of the paper) applies};
\item[{\em (2)}] for $\alpha\geqslant 0$, the limit $\ell_\alpha := \lim_{t\to \infty} k_\alpha(t)/t$ exists almost surely;
\item[{\em (3)}] there is a unique $\alpha_*\in(0,\overline{\alpha})$ such that $\ell_{\alpha_*}=0$.
\end{enumerate}
Let $\alpha(t)=\sup{{\left\{\alpha\geqslant 0: k_\alpha(t)=0\right\}}}$ denote the largest root of $\alpha\mapsto k_\alpha(t)$. Then
\[
\lim_{t\to \infty} \alpha(t) = \alpha_* \quad \text{almost surely.}\]
In addition, we have $\alpha_0\leqslant \alpha_*$, where $\alpha_0$ is the rough decay rate introduced in Proposition~(prop:estimation ruin probability for the collective model of the paper).

[Lemma 2 (Schatten ideal, interpolation, and tensor regrouping) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Let $U,V,U',V'$ be Hilbert spaces.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.2em]
 \item If $T\in\cL(U,V)\cap\Sch_2(U,V)$ and $2\le r<\infty$, then
 \begin{equation}
  \norm{T}_{\Sch_r}
  \le \norm{T}_{\rm op}^{1-2/r}\norm{T}_{\Sch_2}^{2/r}.
 \end{equation}
 \item If $A\in\cL(V,V')$, $B\in\cL(U',U)$, and $T\in\Sch_r(U,V)$, then
 \begin{equation}
  \norm{ATB}_{\Sch_r(U',V')}
  \le \norm{A}_{\rm op}\norm{T}_{\Sch_r(U,V)}\norm{B}_{\rm op}.
 \end{equation}
 \item The canonical regroupings of Hilbert tensor products, for instance
 $((\cA\otimes_2\cB)\otimes_2\cC)\simeq\cA\otimes_2\cB\otimes_2\cC$, are unitary.  Consequently Hilbert--Schmidt norms are unchanged by a mere reorientation of tensor legs.  Multiplication by unimodular factors on any frequency leg is also unitary and hence preserves every Schatten norm.
\end{enumerate}

[Lemma lem:aftercancellation of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] Define $\ell \coloneqq  \lceil |\alpha| / 2 \rceil$
    For every $\beta \subseteq \alpha$ and any $\mathbf{t}$, we have
    \begin{align*}
        \sum_{\beta \subseteq \alpha} (-1)^{|\alpha \setminus \beta|}  \hspace{.1cm}\varphi_{\beta}(\mathbf{t}) = e^{-\frac{\widehat{\sigma}^2}{2} \|\mathbf{t}\|^2 } \left( \widehat{\Lambda}_\alpha(  \mathbf{X}_{\text{R}} , \mathbf{t}) + \widehat{R}_\alpha( \mathbf{X}_{\text{R}} , \mathbf{t}) \right).
    \end{align*}
    with \begin{align*}
        \widehat{\Lambda}_\alpha(  \mathbf{X}_{\text{R}} , \mathbf{t})  \coloneqq  \frac{(-1)^\ell}{2^\ell \ell!}  \sum_{ \substack{ r_1, \ldots r_k \in \alpha \times \alpha \\ {\textsc{Supp}}(r_1, \ldots, r_k ) = \alpha }} \Phi_{\alpha}^{(r_1, \ldots, r_k)}(\mathbf{t}) \text{ and } \widehat{R}_\alpha( \mathbf{X}_{\text{R}} , \mathbf{t}) \coloneqq\sum_{\beta \subseteq \alpha} (-1)^{|\alpha \setminus \beta|}\sum_{k=\ell + 1}^\infty \frac{(-1)^k}{2^k k!} (\mathbf{t}^\top \! (\boldsymbol{\Sigma}_\beta - \widehat{\sigma}^2\mathbf{I}) \ \mathbf{t})^k
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

