[Lemma 4 of arXiv:2605.28801, 'Microscopic Weak Selection Principle for the Logistic Branching Brownian Motion with selec'] For any $K \in \mathbb{N}$, the measure $(\mu^{K}_t)_{t\geq 0}$ defined in \eqref{eq: defemp0} satisfies the following stochastic differential equation
	\begin{equation}
		\begin{split}
			\big< \phi, \mu^{K}_t\big>  =&  \big< \phi, \mu^{K}_0\big>
			+\int_{0}^{t}\int_{\mathbb{R}}  \Big(\partial_t\phi(s, x) +\frac{1}{2} \partial_{xx}\phi(s, x ) \Big) \mu^{K}_s(dx)ds\\
			&+\int_0^t \int_{\mathbb{R}}\phi(s,x)\Big(1-2\int_x^\infty\mu^{K}_s(dy)+2c_K\Big)\mu^{K}_s(dx)ds +L^{K,\phi}_t 
		\end{split},
	\end{equation}
	for all bounded functions $\phi(t,x) \in C^{1,2}_b(\mathbb{R}_+\times\mathbb{R})$. Here, $(L^{K,\phi}_t )_{t\geq 0}$ is a c\`adl\`ag martingale defined by 
	\begin{align*}
		L^{K,\phi}_t : = B^{K,\phi}_t + M^{K,\phi}_t  - D^{K,\phi}_t,
	\end{align*} 
	where $(B^{K,\phi}_t )_{t\geq 0}$, $(D^{K,\phi}_t )_{t\geq 0}$ and $(M^{K,\phi}_t)_{t\geq 0}$ are square-integrable martingales given by 
	\begin{equation}
		\begin{split}
			&B^{K,\phi}_t  = \int_0^t\int_{\mathbb{R}} \phi(s,x)\nu^b(ds,dx) - \int_0^t \frac{1}{m_K}\sum_{u \in \mathcal{N}^K_s}\phi(s,X^K_u(s))ds \, ;\\
			& D^{K,\phi}_t  = \int_0^t\int_{\mathbb{R}} \phi(s,x)\nu^d(ds,dx) - \int_0^t  \frac{2c_K}{m_K}  \sum_{u \in \mathcal{N}^K_w} \phi(w,X^K_u(w))\Bigg(\sum_{v \in \mathcal{N}^K_w}\mathbb{1}_{\{X^K_u(w)\leq X^K_v(w)\}}-1\Bigg)dw \, \text{; and}\\
			& M^{K,\phi}_t  = \frac{1}{m_K}\sum_{u\in\mathbb{T}^K: \tau^b_u \leq t }\int_{0}^{t} \mathbb{1}_{\{\tau^{b}_u\leq s< \tau^{d}_u\}}\partial_x\phi(s, X^K_u(s)) dX^K_u(s), 
		\end{split}
	\end{equation}
	respectively. Furthermore, $L^{K,\phi} $ has  predictable quadratic variation 
	\[
	\begin{split}
		\big<L^{K,\phi} \big>_t & = \int_0^t  \frac{2c_K}{m^2_K}  \sum_{u \in \mathcal{N}^K_w} \phi^2(w,X^K_u(w))\Bigg(\sum_{v \in \mathcal{N}^K_w}\mathbb{1}_{\{X^K_u(w)\leq X^K_v(w)\}}-1\Bigg)dw \\&- \int_0^t \frac{1}{m_K^2}\sum_{u \in \mathcal{N}^K_s}\phi^2(s,X^K_u(s))ds - \frac{1}{m_K^2}\sum_{u\in\mathbb{T}^K: \tau^b_u \leq t}\int_{0}^{t} \mathbb{1}_{\{\tau^{b}_u\leq s <\tau^{d}_u\}}(\partial_x\phi(s, X^K_u(s)))^2 ds
	\end{split},\]
	and converges to $0$ when $K$ goes to infinity in $L^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

