        \mathcal{E}_k(t):= \mathrm{Span}(\{M(t)^{j_1}e_{j_2+2}\}_{0 \leq j_1 \leq k, 0 \leq j_2 \leq k-1}).
    \end{equation}

[Thm 1 ({\cite{BollobasRiordan,EggemannNoble,SubgraphsPAM}}) of arXiv:2605.28776, 'Limiting distributions of triangle counts in linear preferential attachment models'] Let $m\ge2$ be a fixed integer and $\delta> -m$ be a fixed real number. Let $T_n$ be the number of triangles in $\pam(m,\delta)$. Then
\begin{align*}
 \E T_n\cong \begin{cases}
 \log n & \text{ if } \delta>0\\
 (\log n)^3 & \text{ if } \delta=0\\
 n^{|\delta|/(2m+\delta)}\log n & \text{ if } \delta\in(-m,0).
 \end{cases}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: leading coef of arXiv:2603.10738, 'Pairwise Negative Correlation for Uniform Spanning\\ Subgraphs of the Complete Graph'] We have the following identities for $k\;\geqslant\;1$:
	\begin{equation}
	\sum_{r=0}^{k-1}\frac{(-1)^r}{2^rr!(k-r-1)!}=\frac{1}{2^{k-1}(k-1)!}\,,
	\end{equation}
	    \begin{equation}
	\sum_{r=0}^{k-1}\frac{(-1)^rr}{2^rr!(k-r-1)!}=-\frac{1}{2^{k-1}(k-2)!}\mathbf{1}_{\{k\;\geqslant\; 2\}}\,,
	\end{equation}
	\begin{equation}
	\sum_{r=0}^{k-1}\frac{(-1)^rr^2}{2^rr!(k-r-1)!}=\frac{k-3}{2^{k-1}(k-2)!}\mathbf{1}_{\{k\;\geqslant\; 2\}}\,,
	\end{equation}
	and
	\begin{equation}
	\sum_{r=0}^{k-1}\frac{(-1)^rr^3}{2^rr!(k-r-1)!}=\frac{-k^2+8k-13}{2^{k-1}(k-2)!}\mathbf{1}_{\{k\;\geqslant\; 2\}}.
	\end{equation}

