[Definition 204 of arXiv:2601.16377, '2601.16377'] We introduce four linear operators
\begin{equation*}
\begin{split}
\mathcal{K}_h \,\,:\,\, \mathscr{O}(\amsmathbb{M}_h \setminus \amsmathbb{A}_h^{\mathfrak{m}}) \longrightarrow \mathscr{H}^{[H + 1]}, & \qquad \mathcal{K}\,\, :\,\, \prod_{h = 1}^{H} \mathscr{O}(\amsmathbb{M}_h \setminus \amsmathbb{A}_h^{\mathfrak{m}}) \longrightarrow \mathscr{H}^{[H + 1]}, \\
\mathcal{U}_{h}\,\,:\,\, \mathscr{H}^{[1]} \longrightarrow \mathscr{O}(\amsmathbb{M}_h \setminus \amsmathbb{A}_h^{\mathfrak{m}}), & \qquad \mathcal{P}\,\, :\,\, \mathscr{H}^{[1]} \longrightarrow \amsmathbb{C}_{H - 1}[z],
\end{split}
\end{equation*}
defined by the formulae ($z$ is outside the integration contours)
\begin{equation*}

\begin{split}
\mathcal{K}_h[f](z) & = \frac{1}{\sigma(z)} \oint_{\gamma_h} \frac{\dd \zeta}{2\ii\pi} \,\frac{\sigma(\zeta)}{\zeta - z}\,\frac{f(\zeta)}{\theta_{h,h} \sqrt{(\zeta - \alpha_h)(\zeta - \beta_h)}}, \\
\mathcal{K}[\boldsymbol{f}](z) & = \sum_{h = 1}^H \mathcal{K}_h[f_h], \\
\mathcal{U}_h[f](z) & = \bigg(\sum_{\substack{g = 1 \\ g \neq h}}^H (\theta_{h,h} - \theta_{h,g})f_g(z)\bigg) \sqrt{(z - \alpha_h)(z - \beta_h)}, \\
\mathcal{P}[f](z) & = \Res_{\zeta = \infty}\left[ \frac{\sigma(\zeta)}{z - \zeta}\,f(\zeta)\right].
\end{split}
\end{equation*}

[Lemma lem:LSI:orthogonal of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Let $\nu \in {\mathcal{M}_{\kappa, d}}$ satisfy \begin{equation}

     \int_{(\ensuremath{\mathbb{R}}^d)^{1 + \kappa}} \Big(\big|\nabla_{\mathbf{x}} \log \nu(\mathbf{x})\big|^2 \Big) \nu(d\mathbf{x}) < \infty.
 \end{equation}
    Fix $n \in \ensuremath{\mathbb{N}}$ with $n \geq 3$. The following properties hold for $u \in V_{n-2}$: 
    \begin{enumerate}
        \item For all $A \subset \{-n, \ldots, u+1\}$ and $f:(\ensuremath{\mathbb{R}}^d)^A \rightarrow \ensuremath{\mathbb{R}}^d$ such that \begin{equation}

\int_{(\ensuremath{\mathbb{R}}^d)^{V_n}} |f(x_A)|^2 \psi^n_\nu(d\mathbf{x}^{(n)}) < \infty,
\end{equation}
we have
\begin{equation}
    \int_{(\ensuremath{\mathbb{R}}^d)^{V_n}} f(x_A) \cdot \nabla_{x_u} \log \nu(x_{u+2}|x_{u+1}, x_u) \psi^n_\nu(d\mathbf{x}^{(n)}) = 0.

\end{equation}
\item  For all $B \subset \{u-1, \ldots, n\}$ and $f:(\ensuremath{\mathbb{R}}^d)^B \rightarrow \ensuremath{\mathbb{R}}^d$ such that \begin{equation*}
\int_{(\ensuremath{\mathbb{R}}^d)^{V_n}} |f(x_B)|^2 \psi^n_\nu(d\mathbf{x}^{(n)}) < \infty,
\end{equation*}we have
\begin{equation*}
    \int_{(\ensuremath{\mathbb{R}}^d)^{V_n}} f(x_B) \cdot \nabla_{x_v} \log \nu(x_{u-2}|x_{u-1}, x_u) \psi^n_\nu(d\mathbf{x}^{(n)}) = 0.
\end{equation*}
    \end{enumerate}

