[Theorem 51 (Percolation mean-field bound) of arXiv:2512.00213, 'On strong sharp phase transition in the random connection model'] Let $\delta>0$. Suppose that $n\in\N$ satisfies \eqref{c:main}. Then 
\begin{align}
    \|\theta(t)\|_r \geq \left(\frac{\bar\theta(t_T)}{\delta}
+\frac{\I\{\bar\theta(t_T)=0\}}{2t\Delta_n(t)}\right)(t-t_T),
\end{align}
for all $t\in[t_T, t_T + \delta]$ and $r\in[1,\infty]$.

[Lemma 8 of arXiv:2604.10051, 'Ergodicity of the voter model with dynamic anti-voter bonds'] Fix an arbitrary $k \in \N$, a graph~$G$ and a function~$Q$ satisfying~\eqref{Q_def_adoption_rw}. Then, the voter model with dynamic anti-voter bonds $(\eta_t,\zeta_t)_{t \ge 0}$ with adoption rate~$Q$ and environment parameters~$p$ and~$\mathsf v$, and the Markov chain~$(\mathbf Y_t,\mathbf i_t,A_t,B_t)_{t \ge 0}$ with matrix rate~$Q_\mathrm{crw}(p,\mathsf v,k,Q)$ are dual with respect to the function~$D = D_k:\Omega \times \mathcal S_k \to \R$ defined as
$$D(\eta,\zeta,\mathbf x,\mathbf i,A,B) = \varphi_\mathrm{site}(\eta,\mathbf x, \mathbf i)  \cdot \varphi_\mathrm{edge}(\zeta,A,B),$$
    where
    \begin{equation}
        \begin{aligned}
        & \varphi_\mathrm{site}(\eta,\mathbf x, \mathbf i) = \mathds{1}\{ \eta(x_1) = \mathsf i_1, \dots, \eta(x_k) = \mathsf i_k \} \; \text{ and} \\[2mm]
        & \varphi_\mathrm{edge}(\zeta,A,B) = p^{-|A|}(1-p)^{-|B|} \cdot \mathds{1}\{\zeta \equiv 1 \text{ on } A,\; \zeta \equiv -1 \text{ on } B\},
        \end{aligned}
    \end{equation}
    that is, for any~$(\eta,\zeta,\mathbf{x},\mathbf i,A,B) \in \Omega \times \mathcal S_k$ we have that
    \begin{equation}
        E_{\eta,\zeta}[D(\eta_t,\zeta_t,\mathbf{x},\mathbf{i},A,B)] = E_{\mathbf{x},\mathbf{i},A,B}[D(\eta,\zeta,\mathbf Y_t, \mathbf i_t,A_t,B_t)].
    \end{equation}

