body:
[Lemma 2 of arXiv:2608.05514, 'It\^{o}'s formula for L\'evy-It\^{o} processes taking values in the dual of nuclear space'] Let $M$ be a cylindrical martingale-valued measure on $\R_{+} \times \mathcal{R}$. There exists two  cylindrical martingale-valued measures $M^{c}$ and $M^{d}$ on $\R_{+} \times \mathcal{R}$ with the following properties:
\begin{enumerate}
\item $M(t,A)=M^{c}(t,A)+M^{d}(t,A)$ $\forall t\geq 0$, $A \in \mathcal{R}$.  
\item For every $A \in \mathcal{R}$ and $\phi \in \Phi$, $(M^{c}(t,A)(\phi): t \geq 0)$ has continuous paths and $(M^{d}(t,A)(\phi): t \geq 0)$ has purely discontinuous paths. 
\item For every $A \in \mathcal{R}$ and $\phi \in \Phi$, the square integrable martingales $(M^{c}(t,A)(\phi): t \geq 0)$ and $(M^{d}(t,A)(\phi): t \geq 0)$ are orthogonal.   
\end{enumerate}

[Conjecture of arXiv:2507.18080, 'An upper bound for the lower tail of the mass of balls under the Critical $2d$ stochastic '] There exists a non-random function $b(\varepsilon)>0$ with $b(\varepsilon)\to \infty$ as $\varepsilon\to 0$ such that  for any $\psi\in C_c({\mathbb{R}}^2)$\begin{align*}
\int_{{\mathbb{R}}^2}\frac{1}{b(\varepsilon)}\left(\log \mathscr{Z}^\vartheta_t(1,B_\varepsilon(x))-E[\log \mathscr{Z}^\vartheta_t(1,B_\varepsilon(x))]\right)\psi(x)\text{\rm d} x
\end{align*}
converges weakly to a nontrivial random variable $\mathfrak{h}_t(\psi)$. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Theorem thm:clt-rw2mc of arXiv:2509.10225, 'Phase Transitions for Elephant Random Walks \\ with Two memory Channels'] The fluctuations of the walk around the almost sure limit exhibit the following central limit behavior based on the value of $p$. 
\begin{enumerate}
\item[a)] For $p \in \left(0, \frac{11}{16}\right)\cup\left(\frac{113+\sqrt{97}}{128}, 1\right)$,
\begin{align}
    \sqrt{n}\left(\frac{{S}_n}{{n}} - \Lambda_p\right) \stackrel{d}{\to} N\left(0,\Sigma^{(1)}_p\right),
\end{align}
where
\begin{align}
   \Sigma^{(1)}_p = &{\begin{cases}{\frac{2}{11-16p}}, &{p \in \left(0, \frac{11}{16}\right)}, \\[.1cm] \Sigma^{(1)}_{\alpha, \beta, p}, &{p \in \left(\frac{113+\sqrt{97}}{128}, 1\right)},\end{cases}}
\end{align}
with $\alpha, \beta$ given by (equation eq:al-be of the paper) and the random variable $\Sigma^{(1)}_{\alpha, \beta, p}$ given by (equation eq:sig1 of the paper).
\item[b)] For $p \in \left\{\frac{11}{16}, \frac{113+\sqrt{97}}{128}\right\}$,
\begin{align}
    \sqrt{\frac{n}{\log n}}\left(\frac{{S}_n}{{n}} - \Lambda_p\right) \stackrel{d}{\to} N\left(0,\Sigma^{(2)}_p\right),
\end{align}
where
\begin{align}
   \Sigma^{(2)}_p = &{\begin{cases}{\frac{2}{3}}, &{p = \frac{11}{16}}, \\[.1cm] \Sigma^{(2)}_{\alpha, \beta, p}, &{p = \frac{113+\sqrt{97}}{128}}.\end{cases}}
