[Dfn 4 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $(X,d^X)$ be a metric space. For a function $f:X\to\R$, a non-empty subset
  $A\subseteq X$ and a real number $\kappa\in (0,1]$, we define $\|f\|_A,$ $\|f\|_{\Lip^{\kappa}(A)}\in [0,\infty],$ and $\|f\|_{\BL^{\kappa}(A)}\in [0,\infty]$ 
  as follows.
  \begin{equation*}
    \|f\|_A:=\sup_{a\in A}|f(a)|,\qquad \|f\|_{\Lip^{\kappa}(A)}:=\sup_{\substack{x,y\in A\\x\neq y}}\frac{|f(x)-f(y)|}{d^X(x,y)^{\kappa}},
  \end{equation*}
  and
  \begin{equation*}
    \|f\|_{\BL^{\kappa}(A)}:=\|f\|_A+\|f\|_{\Lip^{\kappa}(A)}.
  \end{equation*} 
  If $A$ is a singleton, we set $\|f\|_{\Lip^{\kappa}(A)}=0$. 
  The quantity $\|f\|_{\Lip^{\kappa}(A)}$ is the $\kappa$-H\"older constant of $f|_A$, 
  and we call $\|\cdot\|_{\BL^{\kappa}(A)}$ the $\BL^{\kappa}(A)$ norm 
  or simply the $\BL^{\kappa}$ norm if $A$ is clear from the context.
Also, we denote the set of functions with a finite $\BL^{\kappa}(A)$ norm by
$\BL^{\kappa}(A)$. Namely,
  \begin{equation*}
  \BL^{\kappa}(A):=\{f:X\to\R:\|f\|_{\BL^{\kappa}(A)}<\infty\}.
\end{equation*}

[Prop 2 (Taylor expansion of the compact solution) of arXiv:2608.30374, 'Compact and Infinite-Order Error Analysis\\ for Null-Space SVD Estimation'] For \(k\geq1\), write
\begin{equation}
    c_k:=\V{\eta}^T\V{\eta}_k,
    \qquad
    \V{\eta}_k^\perp
      :=(I_m-\V{\eta}\V{\eta}^T)\V{\eta}_k.

\end{equation}
With empty sums interpreted as zero, the Taylor coefficients are determined
sequentially, for every \(k\geq1\), by
\begin{align}
    \lambda_k
      &=\V{\eta}^T A_1\V{\eta}_{k-1}
        +\V{\eta}^T A_2\V{\eta}_{k-2}
        -\sum_{j=1}^{k-1}\lambda_j
             \V{\eta}^T\V{\eta}_{k-j},
      \\
    \V{\eta}_k^{\perp}
      &=G\left(
          -A_1\V{\eta}_{k-1}
          -A_2\V{\eta}_{k-2}
          +\sum_{j=1}^{k-1}\lambda_j\V{\eta}_{k-j}
        \right),
      \\
    c_k
      &=-\frac12\sum_{j=1}^{k-1}
          \V{\eta}_j^T\V{\eta}_{k-j},
      \\
    \V{\eta}_k
      &=\V{\eta}_k^{\perp}+c_k\V{\eta}.

\end{align}
The order-\(K\) Taylor approximation to the error is
\begin{equation}
    \V{\epsilon}^{[K]}(\sigma)
       =\sum_{k=1}^{K}\sigma^k\V{\eta}_k.

\end{equation}

[Lem 20 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$, $0 \leq s \leq t \leq T$, $n \in \mathbb{N}_+$ and $A_n$ be an arbitrary subset of $\mathbb{Z}^{2}$. Then
\begin{align*} 
	&	\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \int_s^t \dd r \frac{ \Theta(n) K_n }{\sqrt{n}}    \sum_{(x,y) \in A_n} B_{r,v}^{H,n}(x,y) a(y-x)   \bar{\xi} _x^{\alpha}( \eta_r^n ) \bar{\xi} _y^{\beta}( \eta_r^n ) \Bigg\}^{2} \Bigg] \leq \widehat{C} (t-s)^{2} \frac{  \big[ \Theta(n) K_n \big]^{2}  }{ n^{4}  } \mathbbm{1}_{ \{ \gamma \geq 1 \} },
\end{align*}
where for every $z,w \in \mathbb{Z}^{2}$, $B_{r,v}^{H,n}(z,w):=[  H ( \tfrac{w - r v_n }{n}  ) - H ( \tfrac{z - r v_n }{n}  )  ] - [  H ( \tfrac{ \lfloor w - r v_n \rfloor }{n}  ) - H ( \tfrac{ \lfloor z - r v_n \rfloor }{n}  )  ]$. Furthermore, if $H \in C_c^2(\mathbb{R})$, the role of $\widehat{C}$ is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}.

