body:
[Theorem 8 (Branching capacity and asymptotics of visiting probability) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] Consider a \(\Tree\)-walk in \(\Z^{d}\), and assume that 
\begin{enumerate}[(i)]
  \item \(d> \frac{2\alpha}{\alpha-1}\), or \(d=\frac{2\alpha}{\alpha-1}\) and
\Cref{Assum:SufficientConditionTransience} holds;
\item the jump distribution \(\theta\) has a finite
moment of order \(d-1\);
\end{enumerate}


Then for all finite \(A \subset \Z^d\) we have

\begin{equation*}{
 \P(\Tree^{x} \cap A \neq \emptyset) \sim_{x \to \infty} \bcp(A)g_{\theta}(x).
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 20 of arXiv:2604.11921, 'Replica symmetry up to the de Almeida--Thouless line in the Sherrington--Kirkpatrick model'] \label[proposition]{prop:hard-hsmall}
Assume
\begin{equation}
h\le \sigma^2=\beta^2 q.
\end{equation}
Then for all $\lambda$ such that $0\le \lambda\le \beta^2(1-q)$, 
\begin{equation}
a_2(\lambda)\le a_2(0)=\E[S^2]=\frac{\alpha}{\beta^2}.
\end{equation}
Further, if $\alpha\le 1$, then for all $t \in [q,1]$,
\[
\E[m_t^2]\le t.
\]

[Prop P: uniqueness HJ of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Let $F_{\text{in}} \in CDF(\overline{\mathbb{R}})$ and assume $Q = 0$.  If $\mathcal{F}(v,w) = -H(v)$ for a convex $H : \mathbb{R} \to \mathbb{R}$ satisfying $H(0) = 0$ and (equation E: superlinear of the paper), and if $\underline{F}$ and $\overline{F}$ are the maximal subsolution and minimal supersolution, respectively, of (equation E: initial value problem appendix of the paper), then, for any $(x,t) \in \mathbb{R} \times (0,+\infty)$,
		\begin{align} 
			\underline{F}(x,t) = \overline{F}(x,t) = \inf \left\{ F_{\text{in}}( y ) + t L \left( \frac{x - y}{t} \right) \, \mid \, y \in \mathbb{R} \right\}.
		\end{align}
	where $L$ is the Legendre-Fenchel transform of $H$. 

	Furthermore, the following statements hold:
		\begin{itemize}
			\item[(i)] For any $t > 0$, the functions $\underline{F}(\cdot,t)$ and $F_{\text{in}}$ coincide on the set $\{-\infty,+\infty\}$.
			\item[(ii)] If $\{ F^{(n)}_{\text{in}}\}$ is a sequence in $CDF(\overline{\mathbb{R}})$ converging vaguely to $F_{\text{in}}$, and if $\{ \underline{F}^{(n)} \}$ are the corresponding maximal subsolutions of (equation E: initial value problem appendix of the paper), then, for any compact set $K \subseteq \mathbb{R} \times (0,+\infty)$,
				\begin{align*}
					\lim_{ n \to \infty } \sup \left\{ | \underline{F}^{(n)}(x,t) - \underline{F}^{(n)}(x,t) | \, \mid \, (x,t) \in K \right\} = 0.
				\end{align*}
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 (Gibbs variational principle) of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] Let $\mu \in \eP(T)$ be given. Then, for any $\beta > 0$,
	\begin{align}
		\Phi_\beta(X; \mu) = \langle \sm_{\beta,\mu}, X \rangle - \frac{1}{\beta}D(\sm_{\beta,\mu}\|\mu) = \sup_{\nu \in \eP(T)} \left[\langle \nu, X \rangle - \frac{1}{\beta}D(\nu \| \mu)\right].
	\end{align}

[Theorem 4 of arXiv:2605.03057, 'Uniform-in-time quantitative fluctuations of large scale interacting particle systems'] Let $F\in\mathbb{D}^{2,4}$ be centered with $\E[F^2]=\sigma^2>0$ and
let $Z_\sigma\sim\mathcal{N}(0,\sigma^2)$. Then,
\begin{equation*}
W_1(F,Z_\sigma)\le \sqrt{\frac{8}{\pi\sigma^2}}
\sqrt{
\iint_{A\times A}
\sqrt{\E\left(\left(D^2F\otimes_1 D^2F\right)(x,y)^2\right)}
\sqrt{\E\left(DF(x)^2DF(y)^2\right)}
 \lambda(dx)\lambda(dy)
}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 34 of arXiv:2609.01389, 'K-stability and birational rigidity of Fano 3-fold weighted complete intersections'] The following assertions hold.
\begin{enumerate}
\item We have $\alpha \beta = 0$.
\item If $\alpha = \gamma = 0$, then $\delta \ne 0$.
\item If $\beta = \gamma = 0$, then $\varepsilon \ne 0$.
\end{enumerate}

[Theorem 7 of arXiv:2606.02856, 'Geometric Routing in Geometric Inhomogeneous Random Graphs'] Let \(w_0, D_0\) be sufficiently large constants. The geometric routing protocol finds a path from a vertex of weight at least \(w_0\) to a vertex within distance \(D_0\) of \(t\), which constitutes the main part of the routing, whose length is upper-bounded by
\begin{equation}
\frac{1 + \oh{1}}{\abs{\log(\tau - 2)}} \left( \log \log_{w_0} (D_{s}^d) + \log \log_{D_0} (D_{s}) \right) + \Oh{f_0(n)},
\end{equation}
where \(D_s = \norm{x_s -x_t}\) and \(\om{1} \leq f_0(n) \leq o(\log\log n)\). As \( D_s \leq n^{1/d}\), the bound evaluates to \[\frac{2+\oh{1}}{\abs{\log(\tau-2)}}\log \log n.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma E:5.67a of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] For each~$\alpha\in(-\ffrac12,\ffrac12)$ there exists~$\tilde \epsilon>0$ and~$\widetilde C,\widetilde\eta>0$ such that for all~$\beta>\beta_\text{\rm c}$ satisfying $1/\beta>1/\beta_\text{\rm c}-\tilde\epsilon$,
\begin{equation}

|\tilde r_k-\tilde r_{k-1}|\le \widetilde C\text{\rm  e}\mkern0.7mu^{-\widetilde\eta \min\{k,n-k\}}
\end{equation}
holds for all~$n\ge k\ge2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

