Let T be a consistent theory in a countable language \mathcal{L}, and for each n, let \Sigma_n(x) be a non-principal type. Then T has a countable model \mathcal{M} that omits every \Sigma_n.
Countable language \mathcal{L}
Non-principal types \Sigma_n

[Lemma 22 (Shape-operator characterization) of arXiv:2608.29406, 'Partially Totally Real Submanifolds of Sasakian Manifolds'] The normal morphism \(F\) is parallel if and only if
\begin{equation}
 A_{fV}X=P A_VX
\end{equation}
for every tangent vector field \(X\) and normal vector field \(V\).
Moreover, whenever \(F\) is parallel,
\begin{equation}
 PA_V=-A_VP,
 \qquad
 A_{fV}=-A_VP .
\end{equation}

[Conj c:main of arXiv:2607.18194, 'Temperature chaos in directed polymers'] Let $\beta>0$. 
    Setting $\beta_1=\beta$ and letting $\beta_2=\beta_2(n) > \beta_1$ depend on $n\geqslant 1$,
    as $n\to \infty$ the following hold.

    \begin{itemize}
        \item \textbf{\emph{Energetic decorrelation:}}
        \begin{align*}
            \Corr(F_{\beta_1},F_{\beta_2})
            =
            \begin{cases}
                1-o(1), & \beta_2-\beta_1\ll n^{-1/6},\\[2mm]
                o(1),   & \beta_2-\beta_1\gg n^{-1/6}.
            \end{cases}
        \end{align*}
        See Figure (fig:simulation-free-energy of the paper).
        \item \textbf{\emph{Polymer chaos:}}
        For the normalized polymer overlap,
        \begin{align}
            \mathbb{E}\left[
                \frac{|\pi_1\cap \pi_2|}{n}
            \right]
            =
            \begin{cases}
                \Theta(1),
                & \beta_2-\beta_1\ll n^{-1/6},\\[2mm]
                o(1),
                & \beta_2-\beta_1\gg n^{-1/6},
            \end{cases}
        \end{align}
        where the expectation is over the disorder and the conditionally independent polymer measures.
        See Figure (fig:simulation-free-energy of the paper).
    \end{itemize}

    The corresponding conjecture for the CDRP is obtained by an intermediate disorder change of variables, replacing $\beta$ by $\beta n^{-1/4}$, so that in the $n\to\infty$ limit one obtains the CDRP at inverse temperature $\beta$.
    After this change of variables, to recover behavior analogous to the fixed-temperature lattice polymer, one must send the CDRP inverse temperature $\beta$ to infinity.
    Under this change of variables, the conjectural lattice temperature chaos scale $n^{-1/6}$ becomes the CDRP scale $\beta^{1/3}$.
    \footnote{
        By a space-time-temperature scaling, the CDRP of height $1$ and inverse temperature $\beta_2$ is comparable to a lattice model of height $n=\beta_1^{4}$ and inverse temperature $\frac{\beta_2}{\beta_1}$.
        Thus, under this scaling, the additive change in inverse temperature $1\to 1+ n^{-1/6}$ corresponds to the multiplicative change $\beta_1 \to \beta_1 (1+ \beta_1^{-2/3}) = \beta_1 + \beta_1^{1/3}$.
        This will be expanded on further in (s:heuristic of the paper).
        }
    Thus, as $\beta_1,\beta_2\to\infty$ with $\beta_2 > \beta_1$, the CDRP free energies satisfy
    \begin{align} 
        (\mathfrak{H}^\xi_{\beta_1},\;\mathfrak{H}^\xi_{\beta_2})
        &\xrightarrow{\,d\,}
        \begin{cases} 
            (\mathcal{L}_1, \mathcal{L}_1), &  \beta_2-\beta_1\ll \beta_1^{1/3},
                \\[2mm]
            (\mathcal{L}_1, \mathcal{L}_2),  &  \beta_2-\beta_1\gg \beta_1^{1/3},
        \end{cases}  
    \end{align}
    where $\mathcal{L}_1$ and $\mathcal{L}_2$ are independent directed landscapes, 
    and convergence is in the uniform-on-compact topology on $C(\mathbb{R}^{4}_{\uparrow})$ in each coordinate.
    The marginal convergence is known by (t:KPZ-to-landscape of the paper). (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Theorem 3 of arXiv:2606.06489, 'The Missing Central Limit Theorems for Local Functionals of Berry's Random Wave Model'] As $R\to\infty$, the \emph{defect} or \emph{signed volume} of Berry's model,
    \begin{equation*}
    D(R)=|\set{x\in B_R: u_1(x)>0}|-|\set{x\in B_R: u_1(x)<0}|,
    \quad R>0,    
    \end{equation*}
    satisfies $\var D(R)\sim C R^d$, $C>0$, and $\frac{D(R)}{\sqrt{\var D(R)}}$ converges in 1-Wasserstein distance to a standard Gaussian random variable as $\R\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:max.ent.POC of arXiv:2607.07598, 'Universal Central Limit Theorem for non-exchangeable interacting diffusions'] Suppose Assumption (assum.main of the paper) holds with $k \ge 0$. Then, for each $t\in[0,T]$:
			\begin{enumerate}[(i)]
				\item \emph{(Maximum three-particle entropy.)}
				\begin{align*} 
					\max_{\substack{i,j,k\in[n]\\ i\neq j,\ i\neq k,\ j\neq k}}
					H(P_t^{ijk}\,|\, \mu_t^{\otimes 3})
					\lesssim
					\max_{i, j \in [n]}\xi_{ij}^2.
				\end{align*}
				\item \emph{(Average two-particle entropy.)}
				\begin{align*}
					\frac{1}{n(n-1)}\sum_{\substack{i, j \in [n] \\ i \neq j}} H(P_t^{ij}\,|\, \mu_t^{\otimes 2})
					\lesssim
					\frac{1}{n}\sum_{i=1}^n\Big(\sum_{j=1}^n(\xi_{ij}^2+\xi_{ji}^2)\Big)^2.
				\end{align*}
			\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:barb of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] $(i)$ $($Coercivity$)$ For any $x\in {\mathbb R}^n, \mu\in \mathscr{P}_{\kappa}({\mathbb R}^n)$, we have
		\begin{align}
			\langle \bar{b}(x,\mu), x\rangle \lesssim \big(1+|x|^2+M_2(\mu)\big).
		\end{align}
		$(ii)$ $($Exponential ergodicity$)$ There exist  positive constants $C_{\kappa}, \beta$ such that for any $x\in {\mathbb R}^n, \mu\in \mathscr{P}_{\kappa}({\mathbb R}^n), \gamma\in \mathscr{P}_{\kappa}({\mathbb R}^m), z\in {\mathbb R}^m$,
		\begin{align}
			\big|\tilde{\mathbb{E}}\,b\big(x,\mu,Y_t^{\mu,\gamma,z},\mathscr{L}_{Y_t^{\mu,\gamma}}\big)-\bar{b}(x,\mu)\big|\lesssim\big(1+|x|^{\kappa}+|z|^{\kappa}+M_{\kappa}(\mu)+M_{\kappa}(\gamma)\big)e^{-\beta t}.
		\end{align}
		$ (iii)$ $($Local Lipschitz$)$ For any $x_1,x_2\in{\mathbb R}^n$, $\mu, \nu\in\mathscr{P}_{\kappa}({\mathbb R}^n)$, it holds that
		\begin{align}
			&|\bar{b}(x_1,\mu)-\bar{b}(x_2,\nu)| \nonumber\\
		\lesssim&\big(1+M_{\kappa}^{\frac{1}{2}}(\mu)+M_{\kappa}^{\frac{1}{2}}(\nu)\big)\big|x_1-x_2\big| \nonumber\\
		&+\big(1+|x_1|^{\frac{\kappa}{2}}+ |x_2|^{\frac{\kappa}{2}}+M_{\kappa}^{\frac{1}{2}}(\mu)+M_{\kappa}^{\frac{1}{2}}(\nu)\big)\big(1+M_{\kappa}^{\frac{1}{2}}(\mu)+M_{\kappa}^{\frac{1}{2}}(\nu)\big)  \mathbb{W}_2(\mu,\nu).
			\end{align}
		In particular, we obtain the growth of $\bar{b}$ in the sense that for any $x\in {\mathbb R}^n, \mu\in \mathscr{P}_{\kappa}({\mathbb R}^n)$, it holds that
		\begin{align}
			|\bar{b}(x,\mu)|\lesssim \big(1+M_{\kappa}^{\frac{1}{2}}(\mu)\big)|x|
			+\big(1+|x|^{\frac{\kappa}{2}}+M_{\kappa}^{\frac{1}{2}}(\mu)\big)\big(1+M_{\kappa}^{\frac{1}{2}}(\mu)\big)  M_2^{\frac{1}{2}}(\mu).
		\end{align}

