body:
[Corollary 25 of arXiv:2604.19738, 'Phase Transitions in the Fluctuations of Functionals of Random Neural Networks \\'] Let $\widehat \kappa_L$ be as in \eqref{defkappahatL} and assume \Cref{ass:cri-pot}. Then for $q\ge2$ we have the following.

\noindent
If $q<\frac{d}{2\nu}$, as $L\to\infty$ we have $\int_{-1}^1\widehat \beta ^q \di\mu >0$ always and
	\begin{equation*}
		\int_{-1}^1 \widehat \kappa_L(u)^q\,\di \mu(u)
		=\frac{L^{-q}}{\beta_0^q} \int_{-1}^1  \widehat \beta(u)^q\,\di \mu(u)\,(1+o(1))\, .
	\end{equation*}

    \noindent
If $q\ge \frac{d}{2\nu}$ we have

$$ \int_{-1}^1 \widehat \kappa_L(u)^q \di \mu (u) \asymp \frac{1}{(L\beta_0)^q} \int_{-1}^1 \beta_L(u)^q \di \mu(u)\asymp
\begin{cases}
			L^{-q} \log L &\textnormal{if } q=\frac{d}{2\nu}\,, \\
			L^{-\frac{d}{2\nu} } &\textnormal{if } q>\frac{d}{2\nu}\,.
		\end{cases}
        $$
{Moreover,}
$$ \int_{-1}^1  |\widehat\kappa_L(u)|^q \di \mu (u)\lesssim
\begin{cases}
L^{-q}  &\textnormal{if } q<\frac{d}{2\nu}\,, \\
			L^{-q} \log L &\textnormal{if } q=\frac{d}{2\nu}\,, \\
			L^{-\frac{d}{2\nu} } &\textnormal{if } q>\frac{d}{2\nu}\,.
		\end{cases}
        $$

