[Lemma Lem_Omega_Tilde of arXiv:2504.15999, 'Infinitely many collisions between a recurrent simple random walk and arbitrary many trans'] There exists a set of environments $\widetilde\Omega$,
which has probability $\textnormal{\textsf{P}}\big(\widetilde\Omega\big)=1$.
Also, there exists a (random) strictly increasing sequence $(i(n))_{n\in \mathbb{N} }$ of integers, defined on $\widetilde\Omega$ and depending
only on the environment $\omega$,

with $i(0)\geq 1$.

Moreover, there exists $C_8>0$ such that, for every $\omega\in\widetilde\Omega$,
\begin{equation}

    \liminf_{n\rightarrow +\infty}\inf_{k\in [N_{i(n)}/2,2N_{i(n)}[\cap (2\mathbb Z)}
\ \
    P_\omega^{b_{i(n)}}\big[S_k=b_{i(n)}\big]
\ge
    C_8\, .
\end{equation}
Finally
for every $x\in \mathbb{Z} $, for $\textnormal{\textsf{P}}$-almost every environment $\omega$,
\begin{equation}

    P_\omega^x[\tau(b_{i(n)})\le N_{i(n)}/10]
\to_{n\to+\infty
    }1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem_area of arXiv:2608.09105, 'Longest convex chains with i.i.d.\ points'] Let $f\colon[a,b]\to\mathbb{R}$ be continuous and convex.
Assume $\partial^+f(a)=s_a<s_b=\partial^-f(b)$, where at least one of $s_a,s_b$ is finite.
\begin{enumerate}[label=\textup{(\alph*)}]

\item 
Using the quantities $\Delta_1$ and $\Delta_2$ defined in (equation eq_unif_case_a of the paper) and (equation eq_unif_case_b of the paper), we have
\eeq{ 
\mathrm{Area}\big(\mathsf{Tri}_f(a,b)\big) = \frac{1}{2}\begin{cases}
\Delta_1(b-a) &\text{if $-\infty<s_a<s_b=\infty$} \\
\Delta_2(b-a) &\text{if $-\infty=s_a<s_b<\infty$} \\
\Delta_1\Delta_2/(s_b-s_a) &\text{if $-\infty<s_a<s_b<\infty$.}
\end{cases}
}

\item 
Assume further that $\partial^+f$ is absolutely continuous on $[a,u]$ for every $u\in(a,b)$, and $\partial^-f(b)<\infty$.
If $0 < c \leqslant f''(u) \leqslant C$ for almost every $u\in(a,b)$, then
\eeq{ 
\frac{c^2}{C} \leqslant \frac{\mathrm{Area}\big(\mathsf{Tri}_f(a,b)\big)}{\tfrac{1}{8}(b-a)^3} \leqslant \frac{C^2}{c}\wedge 2C.
}

\end{enumerate}

