[Definition of arXiv:2411.04631, 'Existence of Martingale Solutions to Stochastic Constrained Heat Equation'] (\textbf{Aldous Condition}) [dhariwal2017study]
     The sequence $(Y_k)_{k \in \mathbb{N}}$satisfies Aldous condition \textbf{[A]} if and only if $\forall \epsilon_1>0, \epsilon_{2}>0 ,\exists \delta' > 0$ in such a way that for every sequence $s_k$of stopping times with $s_{k} \leq T $ we have :
    \begin{align}
        \sup_{k \in \mathbb{N}} \sup_{0\leq a \leq \delta  } \mathbb{P}(\mathcal{\rho}(Y_{k}(s_k+a),Y_{k}(s_k))\geq \epsilon_2)\leq \epsilon_{1} \nonumber
    \end{align}

[Thm 21 (Main Theorem $n\ge 2$) of arXiv:2609.00974, 'On Algebraic Integrability\\ of Vector Fields \\ with Rational Function Coefficients\\ tha'] Let $k=\overline{\mathbb{Q}}$ be an algebraic closure of rational numbers.

Let $n\ge 2$ be an integer.
Let $x_1,x_2,\ldots, x_n$ be free variables.

Let $f_1,f_2,\ldots,f_n \in \overline{\mathbb{Q}}(X)$ be non-zero rational functions in one variable.

For each $i=1,2,\ldots,n$, let $PFD(\frac{1}{f_i})=P_i+L_i+H_i$, see Theorem \ref{thm: PFD}, with $L_i=\sum_{j=1}^{d_i}\frac{c_{i,j}}{X-\alpha_{i,j}}$. We define $V_i=\op{Span}_\mathbb{Q}(c_{i,1},c_{i,2},\ldots,c_{i,d_i})\subset \overline{\mathbb{Q}}$: the vector space spanned by residues of $\frac{1}{f_i}$.

Let $D=
f_1(x_1)\frac{\partial}{\partial x_1}+f_2(x_2)\frac{\partial}{\partial x_2}+\ldots+f_n(x_n)\frac{\partial}{\partial x_n}$ be a derivation on $\overline{\mathbb{Q}}(x_1,\ldots,x_n)$.

Then the following are equivalent:
\begin{enumerate}
    \item Let $K$ be a number field such that $f_i \in K(X)$. Let $\cO_K$ be the ring of integers of $K$.

    For almost all prime numbers $p$, and all prime ideals $q$ in $\cO_K$ over these $p$, the derivation $D$ is $p$-closed modulo $q$.
    \item One of the following is true:
    \begin{enumerate}
        \item For all $i$, we have $L_i=0$.
        \item For all $i$, we have $P_i=H_i=0$ and the dimension of $V_i$ is $1$. 

        And the dimension of $V_1+V_2+\ldots+V_n$ is $1$.
    \end{enumerate}
    \item The foliation $\F$ defined by $D$, i.e., $\F=\overline{\mathbb{Q}}(x_1,x_2,\ldots,x_n)D$, is algebraically integrable, i.e., the subfield
    $W=\op{Ann}(\F)=\{g\in \overline{\mathbb{Q}}(x_1,x_2,\ldots,x_n): D(g)=0\}$ is of transcendental degree $n-1$, and $\F=\op{Der}_W(\overline{\mathbb{Q}}(x_1,x_2,\ldots,x_n))$.
\end{enumerate}

Moreover, we can write down explicit transcendental bases:
\begin{itemize}
    \item (2a): Let $1<j\le n$. Then we can take:
        \begin{equation}
            F_{1j}\coloneqq \int \frac{dx_1}{f_1}-\int \frac{dx_j}{f_j} \in \overline{\mathbb{Q}}(x_1,x_j)\setminus \left(\overline{\mathbb{Q}}(x_1)\cup \overline{\mathbb{Q}}(x_j)\right).
        \end{equation}


    \item (2b): There exists $\eta \in \overline{\mathbb{Q}}$, $\eta \ne 0$, and an integer $N>0$ such that $N\eta c_{i,j}\in \mathbb{Z}$ for all $i,j$. Now, let $1<j\le n$. Then we can take:
    \begin{equation}
        G_{1j} \coloneqq \op{exp}\left(N\eta \left(\frac{dx_1}{f_1}-\int \frac{dx_j}{f_j}\right)\right)\in \overline{\mathbb{Q}}(x_1,x_j)\setminus \left(\overline{\mathbb{Q}}(x_1)\cup \overline{\mathbb{Q}}(x_j)\right).
    \end{equation}
\end{itemize}
    Thus we always have that $W$ is a separable closure of $\overline{\mathbb{Q}}(F_{ij})$ or $\overline{\mathbb{Q}}(G_{ij})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 52 ({\cite[Theorem 2.10) of arXiv:2607.18104, '2607.18104'] {ACH:Fixed}}]
Let $\alpha \in (-1,1)$, and fix $M\in \N$. Consider a family of initial Bernoulli paths $h_0^{(i)}$ for $i\in \lbr M \rbr$. Let $\hfix_{0}^{(i),\varepsilon}$ denote the corresponding the rescaled ASEP height functions from \eqref{def:RescaledASEPheight} in Definition~\ref{def:ASEPheightRescaled}. Suppose that for all $i \in \lbr M \rbr$, the rescaled height functions  $\hfix_{0}^{(i),\varepsilon}$ converge as $\varepsilon \rightarrow 0$ in the topology of uniform convergence on compact sets to some function $\hfix_{0}^{(i)} \colon \R \rightarrow \R \cup \{-\infty \}$ in $\UC$ such that the following holds: There exists a constant $C>0$ such that, for all $\varepsilon>0$ and $i \in \lbr M \rbr$, we have 
\begin{equation}
\hfix_{0}^{(i),\varepsilon}(x) \leq C(1 + |x|) 
\end{equation} for all $x\in \R$, as well as 
\begin{equation}
\sup_{x\in [-C,C]}  \hfix_{0}^{(i),\varepsilon}(x) \geq - C . 
\end{equation}
Then we have weak convergence as $\varepsilon\to 0$ of
\begin{equation}
\left(\hAeps(\hfix_0^{(i),\varepsilon};\cdot,t)\right)_{i \in \lbr M \rbr, t \in \mathcal{T}} \rightarrow \left(\hfix(\hfix_0^{(i)};\cdot,t)\right)_{i \in \lbr M \rbr, t \in \mathcal{T}}
\end{equation} under the topology of uniform convergence on compact sets. Here, the functions on the left-hand side are coupled according to the basic coupling for the underlying ASEPs on $\Z$, while the functions on the right-hand side are coupled as in Definition~\ref{def:KPZfixedFullSpace} with respect to a common full-space directed landscape $\mathcal{L}$, taking values in $\mathcal{T}$ for the time component. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem SMR-delayed blow-up of arXiv:2605.28194, 'Delayed Blow-up in 3D Fluids via Pseudo-Transport Noise'] Let $a\in [-1,0)\text{ and }2b+a =0$. Fix $4<p<\infty$,
		\begin{equation*}
			0<\epsilon<1 \quad \text{ and }\quad R_0>0.
		\end{equation*} 
		Then there exists $\nu_0=\nu_0(R_0)\text{ and }N_0=N_0(\nu,R_0,\epsilon)$, such that for all $\nu>\nu_0,\,N>N_0$ and initial data $u_0$ satisfying
		\begin{equation*}
			u^N(0)=u_0\in X_{tr}\quad \text{ and }\quad \|u_0\|_{X_{tr}}\leq R_0,
		\end{equation*}
		the equation (equation NS-SMR section of the paper) admits a unique strong solution which is spatially smooth and, with a probability no less than $1-\epsilon$, exists globally on $[0,\infty)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def B of arXiv:2411.15954, 'A gradient model for the Bernstein polynomial basis'] For each $ n,L\in\mathbb{N}$ fixed with $n\leq L$, define the constraint $\mathbf{b}_{n,L}:\Omega_N\to[0,1]$ as 
    \begin{align}
		\mathbf{b}_{n,L}
		:=
		\frac{1}{L+1}\sum_{j=0}^{L}
		\mathbf{b}_{n,L}^j
        \quad\text{with}\quad
            \mathbf{b}_{n,L}^j(\eta)
            :=\mathbf{1}\big\{{\langle \eta\rangle}_{W_j^L}=\tfrac{n}{L}\big\}.
    \end{align}
    We refer to the process induced by setting $\mathbf{c}=\mathbf{b}_{n,L}$ in (equation generic:gen of the paper) as B($n$,$L$), and its corresponding Markov generator as $\mathcal{L}_N^{n,L}$.

[Proposition 15 (``Shape'' of local extrema of GFF) of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] There exists a probability law~$\nu$ on~$\R^\N$ such that the following holds:
Given~$f\in\Cloc^+$, $k\ge1$ and~$u\in\R$, let $g_{k,u}\colon[0,1]\times\R\to[0,\infty)$ be defined by
\begin{equation}

\texte^{-g_{k,u}(v,s)}:=\wt E\Bigl(\texte^{-f(v,\,s, \, h(\zero)-h(\zero\cdot))}\,\Big|\, h(\zero) = \max_{y\in\BbbL_k}h(y)=m_k+u\Bigr)
\end{equation}
and $g\colon[0,1]\times\R\to[0,\infty)$ defined by
\begin{equation}

g(v,s):=-\log\biggl(
\int\nu(\textd\phi)\texte^{-f(v,s,\phi)}\biggr).
\end{equation}
Then
\begin{equation}

\sup_{v\in[0,1]}\,\,\sup_{s\in\R}\,\,\sup_{k^{ 1/13 }\le u\le k^{ 12/13 }}\,\bigl|g_{k,u}(v,s)-g(v,s)\bigr|\,\,\underset{k\to\infty}\longrightarrow\,\,0.
\end{equation}
The measure $\nu$ is concentrated on $\{\phi_0=0\}\cap\bigcap_{x\in\N\smallsetminus\{0\}}\{\phi_x>0\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 7 (subgaussian maximal inequality) of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] If $X_1,\ldots,X_n$ are $\sigma$-subgaussian random variables defined on a common probability space, then 
\begin{align*}
  \Ex [\max_{i\in [n]} X_i] \le \max_{i\in [n]} \Ex X_i + \sigma\sqrt{2 \log n}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 1 of arXiv:2604.24392, 'Numerical approximation of Markovian BSDEs in infinite horizon and elliptic PDEs'] Assume \eqref{as:generatorf}.
 \begin{enumerate}
  \item If there exists {a parameter $\nu \in (0,2\mu-K_{f,z}^2)$}

  such that, for all $x\in \bR^d$,
  \begin{align*}

\E{\int_0^{+\infty} e^{-\nu s}|\Xx_s|^{2r}\ds} <+\infty,
  \end{align*}
then, for all $x \in \bR^{d}$, BSDE \eqref{eq:BSDEinfinitehorizon} has a unique solution $(\Yx,\Zx)\in \mathscr{S}^2_{loc} \times \mathscr{M}^2_{loc}$ such that
\begin{align*}
\lim_{T \rightarrow + \infty} \E{e^{-\nu T} |\Yx_T|^2} = 0.
\end{align*}
Moreover this solution satisfies
\begin{align*}
\E{\int_0^{+\infty} e^{-\nu s}\norm{\Zx_s}^2 \ds}+\E{\sup_{0 \leqslant s < +\infty} e^{-\nu s} |\Yx_s|^2}  \leqslant C\left(1+\E{\int_0^{+\infty} e^{-\nu s}|\Xx_s|^{2r}\ds}\right),
\end{align*}
with a constant $C$ that does not depend on $x$.
 \item If $d'=1$ (i.e. $\Yx$ is scalar valued) and $r=0$ then, for all $x \in \bR^d$, the BSDE \eqref{eq:BSDEinfinitehorizon} has a solution such that $\Yx$ is a   bounded continuous process and $(\Yx,\Zx)$ satisfies
 \begin{align}
 \esssup_{\Omega, t \in \bR^+} |\Yx_t| +  \E{\int_0^{\infty} e^{-2\mu s}\norm{\Zx_s}^2 \ds}\leqslant C,
 \end{align}
 with a constant $C$ that does not depend on $x$.
 Moreover this solution is unique in the class of processes $(\Yx,\Zx)$ such that $\Yx$ is bounded continuous   and $\Zx \in \mathscr{M}^2_{loc}$.
 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 of arXiv:2604.01852, 'The on/off Brownian snake'] Fix $s>0$. For $t \geq 0$, $s_i>s$ let $\text{Res}^{i, \rm d}_t(s) \coloneqq \text{Res}^i_t(s)\mathbbm{1}_{A^i_t(s)=0}$ and $\text{Res}^{i, \rm a}_t(s) \coloneqq \text{Res}^i_t(s)\mathbbm{1}_{A^i_t(s)=1}$. Firstly, there exist local time processes $\ell^{\rm a}_{s,i}(\cdot)$ and $\ell^{\rm d}_{s,i}(\cdot)$ at level $0$ for $(\text{Res}^{i, \rm d}_t(s))_{t \geq 0}$ and $(\text{Res}^{i, \rm a}_t(s))_{t \geq 0}$.
    \par
    Secondly, we have
    \begin{equation*}
        (\varepsilon \mathcal{Z}^{(\varepsilon, \rm d)}_s, \varepsilon\mathcal{Z}^{(\varepsilon, \rm a)}_s) \xrightarrow[\varepsilon \rightarrow 0]{a.s.} (\mathcal{Z}^{(\rm d)}_s, \mathcal{Z}^{(\rm a)}_s),
    \end{equation*}
    on the space of $\mathcal{M}_F(\mathbb{R}^d)^2$. For $s=0$ set $\mathcal{Z}^{(\rm d)}_s$, $\mathcal{Z}^{(\rm a)}_s$ to be $\mu_{\rm d}$, $\mu_{\rm a}$. Then the limits $((\mathcal{Z}^{(\rm d)}_s, \mathcal{Z}^{(\rm a)}_s))_{s \geq 0}$ have the finite-dimensional distributions of $\text{ooSBM}(4, c, \Tilde{c})$ started at $(\mu_{\rm d}, \mu_{\rm a})$. 
    \par
    Finally, for fixed $s>0$, and for any continuous bounded function $\Phi:\mathbb{R}^d \rightarrow [0,\infty)$ we have that
    \begin{equation}
        \langle \mathcal{Z}^{(\rm d)}_s, \Phi \rangle \coloneqq \int_x \Phi(x) \mathcal{Z}^{(\rm d)}_s(dx) = e^{-\Tilde{c}s}\int_x \Phi(x) \mu_{\rm d}(dx) + \sum_{i \in I: s_i<s} \int_{t=0}^{\sigma(f^i)} \Phi(\hat{w}^i_t)d\ell^{\rm d}_{s, i}(t)
    \end{equation}
    and
    \begin{equation}
        \langle \mathcal{Z}^{(\rm a)}_s, \Phi \rangle \coloneqq \int_x \Phi(x) \mathcal{Z}^{(\rm a)}_s(dx) = \sum_{i \in I: s_i<s} \int_{t=0}^{\sigma(f^i)} \Phi(\hat{w}^i_t)d\ell^{\rm a}_{s, i}(t).
    \end{equation}
    \begin{proof}
        For the first part of the theorem suppose $i \in I$ and $s_i<s$. The processes $(\text{Res}^{i, \rm d}_t(s))_{t \geq 0}$, $(\text{Res}^{i, \rm a}_t(s))_{t \geq 0}$ are simply the processes $(\text{Res}^i_{\eta(s,t',i, \rm a)})_{t' \geq 0}$, $(\text{Res}^i_{\eta(s,t',i, \rm d)})_{t' \geq 0}$ from Proposition \ref{proposition snake reflecting brownian motion} with a time change and so by Proposition \ref{proposition snake reflecting brownian motion} this implies the existence of the local time processes $\ell^{\rm d}_{s,i}(\cdot)$ and $\ell^{\rm a}_{s,i}(\cdot)$.
        \par
        Now we show the second part of the theorem and first we consider $i \in I$ with $s_i>s$ i.e. the particles that started dormant and have remained in the dormant state until time $s$. As before let $\varepsilon > 0$ and let $h = \varepsilon/2$. We have by Remark \ref{remark snake dormant until after time t} that $M_i^{h,d}$ is equal to one iff $\sup\{f^i_t, 0 \leq t \leq \sigma(f^i)\}$ is greater than $h$, otherwise $M_i^{h,d}$ is equal to zero. Furthermore we have that $M_i^{h,a} = 0$, because if $s_i > s$, then $A_\cdot^i(s) = 0$. Therefore we have
        \begin{equation*}
            \Big(\varepsilon \sum_{i \in I:s_i>s} \sum_{n=1}^{M^{h, \rm d}_i} \delta_{S^{h, \rm d}_{s,n,i}},  \varepsilon \sum_{i \in I:s_i> s} \sum_{n=1}^{M^{h, \rm a}_i} \delta_{S^{h, \rm a}_{s,n,i}}\Big) = \Big(\varepsilon \sum_{i \in I:s_i>s, T_h(f^i)<\infty} \delta_{T_h(f^i)}, 0\Big),
        \end{equation*}
        which means that 
        \begin{equation*}
            \Big(\varepsilon \sum_{i \in I:s_i>s} \mathcal{Z}^{(\varepsilon, \rm d)}_{s,i}, \varepsilon \sum_{i \in I:s_i>s} \mathcal{Z}^{(\varepsilon, \rm a)}_{s,i}\Big) = \Big(\varepsilon \sum_{i \in I:s_i>s, T_h(f^i)<\infty} \delta_{b_i} , 0\Big)
        \end{equation*}
        and this is a Poisson random measure with intensity $(e^{-\Tilde{c}s}\mu_{\rm d}(db)/\varepsilon, 0)$ rescaled by $\varepsilon$ and this converges to the measure $(e^{-\Tilde{c}s}\mu_{\rm d}(db),0)$ as $\varepsilon$ tends to zero $\mathbb{P}_{(\mu_{\rm d},\mu_{\rm a})}$-a.s. by the strong law of large numbers for Poisson processes, see Dudley \cite[Theorem 11.4.1]{dudley2002real}.
        \par
        Now we return to $i \in I$ with $ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi 9 of arXiv:2506.10213, 'Coupling of forward-backward stochastic differential equations on the Wiener space, and ap'] An $\F$-progressively measurable random field 
    $w:[0,T]\times \Oz\times \R^n \to \R^m$ with $w(T,x) = g(x)$ is called a 
    ``decoupling field" of FBSDE \eqref{fbsde:equ:general} if there is a constant $\dz > 0$ 
    such that, for all $ 0 \leq t_1 < t_2 \leq T$ with $t_2 - t_1 \leq \dz$,
    and all $\xi \in \cL^2(\Oz,\cF_{t_1},\P;\R^N)$, the FBSDE
    \begin{align}
        \begin{cases}
            X_s = \xi + \int^s_{t_1} b(u,X_u,Y_u,Z_u)\,\od u + \int^s_{t_1} \mu(u,X_u,Y_u,Z_u)\,\od W_u;\\
            \ \\
            Y_s = w(t_2,X_{t_2}) + \int^{t_2}_s f(u,X_u,Y_u,Z_u)\,\od u - \int^{t_2}_s Z_u\,\od W_u,
          \end{cases} 
    \end{align}
    has a unique solution, denoted by $\Tz^{\xi,[t_1,t_2]} := (X^{\xi,[t_1,t_2]},Y^{\xi,[t_1,t_2]},Z^{\xi,[t_1,t_2]})$,
    that satisfies, for all $s\in [t_1, t_2]$,
    \begin{equation}
        Y^{\xi,[t_1,t_2]}_s = w(s,X^{\xi,[t_1,t_2]}_s)\quad \P-a.s.
    \end{equation}

[Definition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] We call an $ H $-valued, $ \mathbf{F} $-adapted, continuous stochastic process $ X(\cdot) $ a weak solution to (eqSEE of the paper)     if $F(\cdot, X(\cdot)) \in L^1(0, T ; H)$ a.s., $\widetilde{F}(\cdot, X(\cdot)) \in L_{\mathbb{F}}^{2}(0, T ; H)$, and for any $t \in[0, T]$ and $\xi \in D\left(A^*\right)$,
    \begin{align*}
        \langle X(t), \xi\rangle_H= & \left\langle X_0, \xi\right\rangle_H+\int_0^t\left(\left\langle X(s), A^* \xi\right\rangle_H+\langle F(s, X(s)), \xi\rangle_H\right) d s \\
        & +\int_0^t\langle\widetilde{F}(s, X(s)), \xi\rangle_H d W(s), \quad \text { a.s. }
    \end{align*}

[Defi \textbf{Allometric form} of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] We say that $\omega \in \mathcal{C}^{1}(\mathbb{R}^{*}_{+})$ has an \hypertarget{alloform}{allometric form} if there exists $0 \leq \kappa_{1} \leq \kappa_{2}$ with
\begin{itemize}
\item[-] $ \exists C_{1}>0, \quad \omega(x) \circeq_{0} C_{1} x^{\kappa_{1}}$,
\item[-]$ \exists C_{2}>0, \quad \omega(x) \circeq_{\infty} C_{2}x^{\kappa_{2}}$.
\end{itemize}
Remark that in that case, $\omega$ is non-decreasing.

[Lem closed-monodromy-approximants of arXiv:2608.27939, 'Entropy and domination for quasi-Hitchin representations'] Let $\gamma\in\pi_1(S)$ be an essential curve, and assume that the axis of $\gamma$ in $\widetilde S$ is not a leaf of $\widetilde\lambda$. Let $A,A_0 \in \mathrm{SL}_n(\mathbb{C})$ be the normalized (determinant-one) lifts of the monodromies $\rho(\gamma), \rho_0(\gamma)$ respectively. 
Then there is a sequence of approximating matrices
$A_{N},A_{0,N}\in\mathrm{SL}_n(\mathbb{C})$ with the following properties:
\begin{enumerate}
\item[(i)] $A_{N}\to A$ and $A_{0,N}\to A_0$ as $N\to \infty$;
\item[(ii)] for each $N$, there is a (finite) weighted planar network $(\mathcal A_N,\omega_N)$ with weight matrix $A_{N}$, and the weight matrix of $(\mathcal A_N, \lvert \omega_N \rvert)$  is $A_{0,N}$.
\item[(iii)] for every $1\leq k\leq n$, we have
\begin{equation}
 \bigl|\bigwedge^k A_N\bigr|
 \leq \bigwedge^k A_{0,N}
\end{equation}
entrywise.
\end{enumerate}

[Lemma 17 of arXiv:2607.19873, 'Local limit theorem for the operator norm of products of random matrices'] Let $\mu$ be a Borel probability measure on $G$. 
Then, for any $x \in \wh M$, 
the operator $P_{\mu, x}$ is bounded on $W_x^0$, and for any $f \in V_x^*$ and $\psi \in W_x^0$, we have 
\begin{align*}
P_{\mu} \langle f, \psi \rangle = \langle f, P_{\mu, x} \psi \rangle. 
\end{align*}

