body:
[Theorem 9 of arXiv:2605.15386, 'The non-central gamma sum and difference distributions: exact distribution and asymptotic '] Let $\alpha_1,\alpha_2,\beta_1,\beta_2>0$ and $\lambda_1,\lambda_2\geq0$. For the asymptotic expansions involving the sum $X_1+X_2$ we further suppose that $\beta_1>\beta_2$.

\vspace{3mm}

\noindent 1. Suppose that $\lambda_1\neq0$. Then, as $x\rightarrow\infty$,
	\begin{align}
	\overline{F}_{X_1\mp X_2}(x)&\sim\frac{1}{2\sqrt{\pi}}\bigg(\frac{1}{\beta_2}\pm\frac{1}{\beta_1}\bigg)^{-\alpha_2}\beta_1^{1-\alpha_1}\beta_2^{-\alpha_2}\bigg(\frac{\lambda_1}{\beta_1}\bigg)^{(1-2\alpha_1)/4}\exp\bigg(-\lambda_1-\frac{\lambda_2\beta_2}{\beta_2\pm\beta_1}\bigg)\nonumber\\
	&\quad\times x^{(2\alpha_1-3)/4}\exp\bigg(2\sqrt{\frac{\lambda_1 x}{\beta_1}}-\frac{x}{\beta_1}\bigg)\sum_{p=0}^{\infty}\frac{\gamma_p(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_1,\lambda_2)}{x^{p/2}},
	\end{align}
	where $\gamma_0(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_1,\lambda_2)=1$ and
	\begin{align}
		\gamma_p(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_1,\lambda_2)&=\sum_{\substack{i,j,k,l\geq0 \\ i+2j+k+l=p}}(-1)^{i+j}c_l(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_1,\lambda_2)\binom{\alpha_1-1/2-l}{k}\nonumber\\
		&\quad\times\binom{\alpha_1-3/2-l-k-2j}{i}\big((l+k)/2-(2\alpha_1-3)/4\big)_j\nonumber\\
        &\quad\times\beta_1^{j}\big(\lambda_1\beta_1\big)^{(k+i)/2}, \quad p\geq1,\nonumber
	\end{align}
	with $c_l(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_1,\lambda_2)$, $l\geq0$, defined as in part 1 of Theorem \ref{thm3.1}.

\vspace{3mm}

\noindent	2. Suppose that $\lambda_1=0$. Then, as $x\rightarrow\infty$,
\begin{align}
	\overline{F}_{X_1\mp X_2}(x)&\sim\frac{\beta_1^{1-\alpha_1}\beta_2^{-\alpha_2}}{\Gamma(\alpha_1)}\bigg(\frac{1}{\beta_2}\pm\frac{1}{\beta_1}\bigg)^{-\alpha_2}{x^{\alpha_1-1}}\exp\bigg(-\frac{x}{\beta_1}-\frac{\lambda_2\beta_2}{\beta_2\pm\beta_1}\bigg)\sum_{k=0}^{\infty}\frac{\delta_k(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_2)}{x^k},
	\end{align}
	where $\delta_0(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_2)=1$ and
	\begin{equation}
	\delta_k(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_2)=\sum_{s=0}^{k}(-\beta_1)^{k-s}(k+1-\alpha_1)_{k-s}\,d_s(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_2), \quad k\geq1,\nonumber
	\end{equation}
	with $d_s(\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_2)$, $s\geq0$, defined as in part 2 of Theorem \ref{thm3.1}.

        \vspace{3mm}

\noindent	3. Suppose that $\lambda_2\not=0$. Then, as $x\rightarrow-\infty$,
	\begin{align}
	F_{X_1-X_2}(x)&\sim\frac{1}{2\sqrt{\pi}}\bigg(\frac{1}{\beta_1}+\frac{1}{\beta_2}\bigg)^{-\alpha_1}\beta_1^{-\alpha_1}\beta_2^{1-\alpha_2}\bigg(\frac{\lambda_2}{\beta_2}\bigg)^{(1-2\alpha_2)/4}\exp\bigg(-\lambda_2-\frac{\lambda_1\beta_1}{\beta_1+\beta_2}\bigg)\nonumber\\
	&\quad\times |x|^{(2\alpha_2-3)/4}\exp\bigg(2\sqrt{\frac{\lambda_2 |x|}{\beta_2}}+\frac{x}{\beta_2}\bigg)\sum_{p=0}^{\infty}\frac{\gamma_p(\alpha_2,\alpha_1,\beta_2,\beta_1,\lambda_2,\lambda_1)}{|x|^{p/2}}.
	\end{align}
4. Suppose that $\lambda_2=0$. Then, as $x\rightarrow-\infty$,
	\begin{align}
		F_{X_1-X_2}(x)&\sim\frac{\beta_1^{-\alpha_1}\beta_2^{1-\alpha_2}}{\Gamma(\alpha_2)}\bigg(\frac{1}{\beta_1}+\frac{1}{\beta_2}\bigg)^{-\alpha_1}|x|^{\alpha_2-1}\exp\bigg(\frac{x}{\beta_2}-\frac{\lambda_1\beta_1}{\beta_1+\beta_2}\bigg)\sum_{k=0}^{\infty}\frac{\delta_k(\alpha_2,\alpha_1,\beta_2,\beta_1,\lambda_1)}{|x|^k}.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

