body:
[Corollary 37 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] Let $\wtilde{M}$ be the process defined in \eqref{eqn-martingale-1}. Then, for $t\in[0, T]$, the quadratic variation of $\wtilde{M}$ is given by
				\begin{align}
					\llbracket \wtilde{M}\rrbracket_t=\int_0^t\sum_{i=1}^M\|\Nn_i(u(s))\|_{L^2(\bO)}^2ds.
				\end{align}

[Lemma tensorization of arXiv:2604.11761, 'The smallest singular value of signed random combinatorial matrices'] Let $\varepsilon_0 \in (0, 1)$ and $B \ge 1$. Let $X_1, \dots, X_m$ be independent
 random variables such that each $X_i$ satisfies
\begin{align*}
\textbf{P}\left(|X_i| \le \varepsilon\right) \le B\varepsilon \quad \text{for all } \varepsilon \ge \varepsilon_0.
\end{align*}
Then there exists a universal constant $C > 0$ such that
\begin{align*}
\textbf{P}\left( \|(X_1, \dots, X_m)\|_2 \le \varepsilon \sqrt{m} \right) \le (CB\varepsilon)^m \quad \text{for every } \varepsilon \ge \varepsilon_0.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn def:length-dl of arXiv:2607.18194, 'Temperature chaos in directed polymers'] For any $s<t$ and any continuous path $\pi:[s,t]\to \mathbb{R}$, we define the \emph{length} of $\pi$ by
    \begin{align*}
        \int_s^t d\mathcal{L}\circ \pi \coloneqq  
        \inf_{k\in \mathbb{N}}
        \inf_{s=s_0 < s_1 < \cdots < s_k = t}
        \sum_{i=0}^{k-1} \mathcal{L}(s_i, \pi(s_i); s_{i+1}, \pi(s_{i+1})). 
    \end{align*}

[Lemma Lem_AlgebraInTransversality of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] For every $\phi \in \mathbb{H}{\backslash}\set{0}$ and $\psi \in \mathbb{H}$ there are $\xi,\eta,\zeta \in \operatorname{Im} \mathbb{H}$ such that
  \begin{equation*}
    i\phi\xi + j\phi\eta + k\phi\zeta = \psi.
  \end{equation*}

[Corollary 26 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\mu_{\rm d}$, $\mu_{\rm a} \in \mathcal{M}_F(\mathbb{R}^d)$ and let $(\mathcal{Y}_t^{(\rm d)}, \mathcal{Y}_t^{(\rm a)})_{t \geq 0}$ be an $\text{ooSBM}(4, c, \Tilde{c})$ started from $(\mu_{\rm d}, \mu_{\rm a})$. Then $\mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}$-a.s. there exist $(N_k, k \in \mathbb{N})$ finite constants such that for $k \in \mathbb{N}$ and for $s$, $t \in \mathbb{R}$ with $k \leq s < t < k+1$ we have
    \begin{equation*}
        \overline{\bigcup_{s \leq u \leq t} \text{supp}(\mathcal{Y}_u^{(\rm d)}) \cup \text{supp}(\mathcal{Y}_u^{(\rm a)})} \subseteq \text{supp}(\mathcal{Y}_s^{(\rm d)}) \cup \text{supp}(\mathcal{Y}_s^{(\rm a)})^{N_kH(t-s)}.
    \end{equation*}
    \begin{proof}
        Lemma \ref{lemma oosbm finite propagation}, along with the Markov property for ooSBM, establishes the claim for $k=0$. The general result can then be derived from the $k=0$ case and then again by the Markov property of ooSBM.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 79 ({\cite[Theorem 1.2) of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] {GH20}}]

  Let $B_{r}^m$ denote a Brownian motion of diffusivity $2$ on $[-r (1+m)^{2/3}, r (1+m)^{2/3}]$. Then there exist positive constants $g_1,g_2,g_3,g_4,g_5$ and $m_0>0$ such that for all $m_0\leq m\leq n/2$, $r$ satisfying $r\leq m^{1/3}/2$, and all measurable sets $A$ satisfying
  \begin{equation}

   e^{-g_1m^{1/12}}\leq  \PP(B_{r}^m\in A) \leq g_2\wedge e^{-g_3r^{12}},
 \end{equation}
 we have
    \begin{equation}

    \PP(\frakf^m_{r}\in A)\leq  g_4r^6\PP(B_{r}^m\in A)\exp( g_5r^7 (\log \PP(B_{r}^m\in A)^{-1})^{5/6}).
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2609.01436, '2609.01436'] Uniformly in $k\geq0$,
\begin{equation}
 m_k\asymp1+k,
 \qquad
 \gamma_k\asymp
 b_0\frac{\varepsilon_k^{\eta-1}}{1+k},
 \qquad
 Q_k\asymp
 \frac{\varepsilon_k^{3/2}}{\sqrt{1+k}}.
\end{equation}
Moreover, there exists an integer $k_0=k_0(N)\geq0$ such that
\begin{equation}
 (e^2-1)^2Ne^{-2m_k}\leq\frac{Q_k}{2}
\end{equation}
for every $k\geq k_0$.

[Lemma 4 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] \cite{franck}
		Let $\Phi \in \Delta_{2}$ be a  $N$-function and $\widetilde{\Phi}$ its conjugate.	Let $v \in L^{\Phi}(\Omega)^{d}$ satisfy 
		\begin{equation*}
			\int_{\Omega} v\cdot g d\mu = 0, \quad \textup{for \; all} \;\, g \in  \mathcal{V}^{\widetilde{\Phi}}_{\textup{div} }= \{ f \in \mathcal{C}^{\infty}(\Omega)^{d} : \textup{div}_{\omega,\widetilde{\Phi}}f=0 \}.
		\end{equation*}
		Then, there exists $u \in W^{1}_{\#}L^{\Phi}(\Omega)$ such that 
		\begin{equation*}
			v = \overline{D}_{\omega,\Phi}u.
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 of arXiv:2607.11773, '2607.11773'] Suppose that {\bf(H1)}-{\bf(H4)} hold
   and $\varepsilon \in (0,1]$.
   Then for every $\varphi \in L^2( \Omega, \mathcal{F}_\tau;  D_{\rho} )$, the stochastic 
   equation
   \eqref{lmvlds-2} has a unique solution $u$ in the sense of Definition \ref{def-sol},
   which satisfies,
  for any $T > 0$,
   \begin{align}
          & \mathbb{E} \left[ \sup_{t \in [\tau,\tau+T]} \|u(t)\|^2 \right]
            + \mathbb{E} \left[ \int_{\tau}^{\tau+T} \|u(s)\|^p_p ds \right]  \nonumber\\
     \le & C \mathbb{E} \left[ \sup_{s \in [-\rho,0]} \|\varphi(s)\|^2 \right] e^{C T}  
         + C \left( T
                       + \int_{\tau}^{\tau + T}
                               \left( \|g(s)\|^2 + \|h(s)\|^2 +  \| \widetilde{h}(s) \|^2_{L^2(\mathbb{Y}, \nu; \ell^2)}
                               \right)ds
                \right) e^{C T},
   \end{align}
   where   $C>0$
   is constant    independent of $\tau$, $T$, $\varphi$
   and $\varepsilon$.

   Moreover, 
   if  
   $\theta \in \left(2, \tfrac{2(p-2)}{q-2} \right)$,
   \begin{equation}
   	     \int_{\tau}^{\tau+T}
   	         \bigl( \|g(s)\|^\theta 
   	                   + \|h(s)\|^\theta
   	                   + \|\widetilde{h}(s)\|_{L^\theta(\mathbb{Y}, \nu; \ell^2)}^\theta
   	                   + \|\widetilde{h}(s)\|_{L^2(\mathbb{Y}, \nu; \ell^2)}^\theta
          	 \bigr) ds
   	      < \infty,
   \end{equation}
   and
   \begin{equation}
         \int_{y \in \mathbb{Y} }
   	         \biggl[ 
   	                    \Bigl( \sum_{i \in \mathbb{Z}} L_{\tilde{\sigma}, i}(y) 
   	                    \Bigr)^{\theta}
   	                   + 
   	                   \Bigl( \sum_{i \in \mathbb{Z}} |\widetilde{\sigma}_{i}(0, \delta_{0}, y) |
   	                      \Bigr)^{\theta}
   	         \biggr] \nu(dy)
   	      < \infty 
   \end{equation}
   hold, 
   then for every 
   $\varphi \in L^{\theta}(\Omega,\mathcal{F}_\tau;\mathcal{D}_{\rho})$, 
   we have 
   \[ 
      \mathbb{E}
             \left[ \sup_{t \in [\tau, \tau+T] } 
                        \|u(t)\|^{\theta}
             \right]
       + \mathbb{E}
                 \left[ \int_{\tau}^{\tau+T} 
                              \|u(s)\|^{\theta-2} \|u(s)\|_{p}^{p} 
                           ds
                 \right]  
   \le
   M_{\theta,T,\varphi} 
   \] 
   where $M_{\theta,T,\varphi}>0$ is a constant   depending 
   only on $\theta$, $T$ and $\varphi$, but not
   on $\varepsilon$.

[Definition 8 of arXiv:2608.05514, 'It\^{o}'s formula for L\'evy-It\^{o} processes taking values in the dual of nuclear space'] Let $L$, $U$, $M$ and $R$ as described in the above paragraphs. Let $\xi$ and $B$ as in Assumption \ref{assumItoProcess}. 
A \emph{L\'{e}vy-It\^{o} process} defined with respect to $L$ is a $\Psi'$-valued process of the form
\begin{equation}
X_t = \xi+\int_0^t B(s) \, ds + \int_{0}^{t} \int_{\Phi'} R(s,f) L(ds,df),   
\end{equation} 
with the stochastic integral as in \eqref{eqDefiLevyIntegral}.

[Theorem thm: convergence of the pinning measure of arXiv:2602.04429, 'Disordered systems and (subcritical) polynomial chaos\\ with heavy-tail disorder'] {}
	Under the same assumptions as Theorem (thm: convergence of the partition function of the pinning model of the paper), for every $\hat{\beta} \in [0,\infty)$ and \(\hat{h} \in {\ensuremath{\mathbb R}} \), there exists a random probability measure ${\ensuremath{\mathbf Q}} _{\hat{h}}^{\boldsymbol\zeta,\hat{\beta}}$ on ${\ensuremath{\mathcal C}} _{\infty}$ such that the following convergence in distribution holds in ${\ensuremath{\mathcal M}} _1({\ensuremath{\mathcal C}} _{\infty})$,
	\begin{equation*}
		\mathrm{P}_{N,h_N}^{\beta_N,\omega} \xrightarrow[N \to +\infty]{(d)} {\ensuremath{\mathbf Q}} _{\hat{h}}^{\boldsymbol\zeta,\hat{\beta}}\,.
	\end{equation*}
	This convergence holds jointly with the convergence of the discrete noise to $\boldsymbol\zeta$. 
	We refer to the measure~${\ensuremath{\mathbf Q}} _{\hat{h}}^{\boldsymbol\zeta,\hat{\beta}}$ as the \emph{continuum disordered pinning model with \(\gamma\)-stable Lévy noise}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:upper_bounds of arXiv:2607.22908, 'Epidemic Phase Transitions in the Zero-Range Process'] For any relative deviation $\delta > 0$ and corresponding absolute deviation $\varepsilon = \rho\delta > 0$:
  \begin{equation}
  \begin{gathered}
    \mathbb{P}(\bar{X} \ge \rho(1+\delta)) \le \exp\braces*{ -n \frac{\rho}{\Gamma} \frac{\delta^2}{2 + 2\delta/3} }, \\
    \mathbb{P}(\bar{X} \ge \rho + \varepsilon) \le \exp\braces*{ -\frac{n}{\Gamma} \frac{\varepsilon^2}{2 \rho + 2\varepsilon/3} }.
  \end{gathered}
  \end{equation}
  If restricted to $\delta \in (0, 1]$ (or $\varepsilon \le \rho$), the bounds simplify to the sub-Gaussian forms $\exp\braces{ -n \frac{\rho \delta^2}{3\Gamma} }$ and $\exp\braces{ -n \frac{\varepsilon^2}{3 \Gamma \rho} }$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem ImplicationOfLongCluster of arXiv:2410.23859, 'Subcritical regimes in the Poisson Boolean percolation on Ahlfors regular spaces'] For all $x \in S$ and $r>0$, the following inclusion holds:
        \begin{equation*}
            \{M(x) > 9\sigma^2 r\} \subset G(x,r) \cup  H(x,r).
        \end{equation*}

[Defn 6 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] Let $\eta = [\eta_1,\ldots,\eta_{n+1}]$ for $n\geq 2$ be a sequence, where $\min(\eta) > 0$. Define 
\begin{align}
\Theta_{i}(\eta) = \max\left( \log(\eta_{i-1}) + \log(\eta_{i+1}) - 2\log(\eta_i) \,,\, 0 \right), 
\end{align}
for every $i\in\{2,\ldots,n\}$. Then,
\begin{align}
\Theta(\eta) = \sum_{i=2}^{n} \Theta_{i}(\eta), 
\end{align}
is called the \emph{log-concavity deviation} of $\eta$ under logarithmic scaling.

[Lemma lem:proper-reference of arXiv:2609.00399, 'Shannon's problem on the monotonicity of entropy and a Conjecture of Tao'] Fix $1\leq K<\infty$.  There are constants
$d_*(K),C_*(K),L_*(K)<\infty$ with the following property.  Let $Q$ be a
finitely supported variable in a torsion-free abelian group and suppose
\begin{equation}
 H(Q+Q')-H(Q)\leq\log K,
\end{equation}
where $Q'$ is an independent copy.  Then there are
\begin{enumerate}
\item a proper affine GAP datum $A$ of rank at most $d_*(K)$;
\item a jointly distributed pair $(U,Z)$ such that
$U\in\operatorname{Im}(A)$ almost surely and $U+Z=Q$ almost surely;
\end{enumerate}
such that
\begin{align}
 D\!\left(\mathcal L(U,Z)\middle\Vert u_A\otimes\mathcal L(Z)\right)
 &\leq L_*(K),\\
 |A|&\geq\exp\{H(Q)-C_*(K)\}.

\end{align}

[Definition smoothed-copula-clean of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let $C$ be an \textit{absolutely continuous
copula} on $[0,1]^{2}$ with density $c$. For $\varepsilon >0$, define 
\begin{equation}
c_{\varepsilon }(u,v)=\int_{0}^{1}\int_{0}^{1}c(s,t)\,k_{\varepsilon
}(u,s)\,k_{\varepsilon }(v,t)\,ds\,dt,\qquad (u,v)\in \lbrack 0,1]^{2},

\end{equation}
and then define the smoothed copula 
\begin{equation}
C_{\varepsilon }(u,v)=\int_{0}^{u}\int_{0}^{v}c_{\varepsilon }(x,y)\,dx\,dy.

\end{equation}

[Lemma 24 (Integration by parts) of arXiv:2605.14630, '2605.14630'] Assume $X \sim \cN(0,C)$. 
For any $i\in\intset{1,N}$, the equality 
\begin{equation}

 \bigexpec{X_i f(X)} = \sum_{j=1}^N C_{ij} \bigexpec{\partial_j f(X)}
\end{equation} 
holds for all differentiable $f:\R^N\to\R$ such that both sides of the equality are 
well-defined.

