[Dfn 3 ({\cite[Definition 2.4) of arXiv:2605.27974, 'Discrete approximation of semi-Dirichlet forms with non-symmetric perturbations of resista'] {kuwae2003convergence}}]
We say that $\{ u_{n} \}_{n \in \N} \,(u_{n} \in \mathscr{X}_{n})$ strongly converges to 
$u \in \mathscr{X}_{\infty}$ if there exists 
$\{\varphi_{m} \}_{m \in \N} \subset \mathscr{C}_{\infty}$ which satisfies 
\begin{equation}
    \limtoinfty{m} \norm{\varphi_{m}-u}_{\mathscr{X}_{\infty}}=0 
    \text{ and }
    \limtoinfty{m} \limsuptoinfty{n}
    \norm{\Phi_{n} \varphi_{m}-u_{n}}_{\mathscr{X}_{n}}=0.
\end{equation}

[Lemma lem:base_difference of arXiv:2609.01697, 'Unique ergodicity of projective cocycles over the 2D stochastic Navier--Stokes equations'] Let $w^1, w^2 \in C([0,T]; \mathcal{H}) \cap L^2([0,T]; H^1)$ be such that $\tilde w \overset{\mathrm{\scriptscriptstyle def}}{=}
  w^1 - w^2$ solves weakly
  \begin{equation}
    \partial_t \tilde w = \Delta \tilde w - B(\tilde w, w^1) - B(w^2, \tilde w) + g ,
    \qquad g \in L^2\big([0,T]; H^{-1}\big) .
  \end{equation}
  Then
  \begin{equation}
    \frac{\mathrm{\,d}}{\mathrm{\,d} t} \|\tilde w_t\|^2 + \|\nabla \tilde w_t\|^2
    \ \leqslant\ C_0 \|w^1_t\| \|w^1_t\|_{H^1} \|\tilde w_t\|^2 + 8 \|g_t\|_{H^{-1}}^2
  \end{equation}
  and, with $\Lambda_T \overset{\mathrm{\scriptscriptstyle def}}{=} C_0 \int_0^T \|w^1_r\| \|w^1_r\|_{H^1} \mathrm{\,d} r$,
  \begin{equation}
    \sup_{t \leqslant T} \|\tilde w_t\|^2 + \int_0^T \|\nabla \tilde w_r\|^2 \mathrm{\,d} r
    \ \leqslant\ 2 e^{\Lambda_T} \Big( \|\tilde w_0\|^2 + 8 \int_0^T \|g_r\|_{H^{-1}}^2 \mathrm{\,d} r \Big) .
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 31 of arXiv:2605.27222, '2605.27222'] For every $k\ge1$,
\begin{equation}
\|\chi G_{e_k}\|_{L^2(\R)}\le Ck^{-1}
\end{equation}
and
\begin{equation}
\|\chi G_{e_k}\|_{H^1(\R)}\le C.
\end{equation}
Consequently, for every $0<\varepsilon<1/2$,
\begin{equation}
\|\chi G_{e_k}\|_{H^{1/2+\varepsilon}(\R)}^2\le C_\varepsilon k^{-1+2\varepsilon}.
\end{equation}

