body:
[Lemma 64 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] For any $\delta>0$, $k\ge1$, and sequences $(a_i^n)$, $(a_i)$, $(b_i^n)$, $(b_i)$ satisfying the above assumptions, we have uniformly for all $s\in (\delta,h(\ell)-\delta)\cap\frac{1}{n}\mathbb{Z}$,
\begin{align*}
        \mathbb{P}_n\left(Y^n(s-\tfrac{1}{n})=y^n(s-\tfrac{1}{n})\,|\,B_s\right)
        =\,\begin{cases}
            1+o_n(1),&\quad\text{if }s-\tfrac{1}{n}\in \{a^n_1,\ldots,a^n_k\},\\
            \dfrac{\binom{y^n(s)}{2}\sigma_n(s)^2}{q_n(s)}\big(1+o_n(1)\big),&\quad\text{if }s-\tfrac{1}{n}\in \{b^n_1,\ldots,b^n_m\},\\
            1-\dfrac{\binom{y^n(s)}{2}\sigma_n(s)^2}{q_n(s)} \big(1 + o_n(1)\big),&\quad\text{otherwise}.
        \end{cases}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:linear-critical-window of arXiv:2606.06612, 'The limit shape and emergence of the \\ Discrete Gaussian level lines'] Fix a constant $\alpha \in (0, 1)$. Set $\lambda_* = $ $\tfrac{1}{\beta}(2\tau(0) + \tfrac{\mathsf w_1}{2})$. For any loop $\gamma$ in the unit square with an interior area of $|A(\gamma)| \geq \alpha$, we have that
    \[\ensuremath{\mathcal F}_\lambda(\gamma)\leq \begin{cases}
			\beta(\lambda - \lambda_*), & \text{if $\lambda \geq \lambda_*$}\\
            -\beta(\lambda_* - \lambda)\alpha, & \text{if $\lambda < \lambda_*$ and $1 - (4\tau(0)^2- \tfrac{\mathsf w_1^2}{4})\tfrac{1}{\beta^2\lambda^2} \geq \alpha$.}
		 \end{cases}\]
    Moreover, if $\lambda \geq \lambda_*$, then $\sup_\gamma\ensuremath{\mathcal F}_\lambda(\gamma) = \ensuremath{\mathcal F}_\lambda({\ensuremath{\mathscr L}}(\lambda))$ and $\ensuremath{\mathcal F}_\lambda({\ensuremath{\mathscr L}}(\lambda)) \geq (\beta - (4\tau(0)^2- \tfrac{\mathsf w_1^2}{4})\tfrac{1}{\beta\lambda^2})(\lambda - \lambda_*)$.

[Corollary 18 (Subcritical and critical component density) of arXiv:2607.16833, 'Dynamical Equations for Poisson Galton--Watson Trees and Component Densities of Sparse Inh'] Suppose $u\kappa\in L^1(\pi\otimes\pi)$ and $\cT_u$ becomes extinct almost
surely.  Then $q_u=1$ $\pi$-almost everywhere, $c_u=\pi$, and
\begin{equation}
 m_\pi(u):=\iint_{S^2}u\kappa(x,y)\pi(\dd x)\pi(\dd y)<\infty.
\end{equation}
In this case
\begin{equation}
 \gamma(u)=\bE_\pi\frac1{T_u}=1-\frac{m_\pi(u)}2,
\end{equation}
and the BJR graph in Theorem~\ref{thm:IRG-general} satisfies
\begin{equation}
 \frac{K(G_n)}n\longrightarrow1-\frac{m_\pi(u)}2
 \qquad\text{in probability and in $L^1$.}
\end{equation}

[Theorem 5 (Dynamics at $\hat{J}=+\infty$) of arXiv:2605.29608, '2605.29608'] For $\hat{J}=+\infty$ (critical point), the Wolff dynamics reaches the set $\{-\textbf{1},+\textbf{1}\}$ in finitely many steps almost surely. Moreover, once the chain enters $\{-\textbf{1},+\textbf{1}\}$, it remains in this set thereafter. More precisely, if the initial configuration $Y_{1}\in\{-\textbf{1},+\textbf{1}\}$, then for any $k\geq 1$
	\begin{equation*}
		Y_{k}=
		\begin{cases}
			Y_{1}, & k \ \text{is odd},\\
			-Y_{1}, & k \ \text{is even}.
		\end{cases}
	\end{equation*}
	Furthermore, for any initial configuration $\tilde{\sigma}\in\Omega$ with $\tilde{\sigma}\notin\{-\textbf{1},+\textbf{1}\}$, we have
	\begin{align*}
		\mathbb{P}(Y_{\tilde{\mathcal{C}}^{\tilde{\sigma}}}\in\{-\textbf{1},+\textbf{1}\}\mid Y_{1}=\tilde{\sigma})=1,
	\end{align*}
	and consequently, for any $k\geq 0$,
	\begin{align*}
		\mathbb{P}(Y_{\tilde{\mathcal{C}}^{\tilde{\sigma}}+k}\in\{-\textbf{1},+\textbf{1}\}\mid Y_{1}=\tilde{\sigma})=1.
	\end{align*}

