By the exponential Chebyshev inequality, we have that
\bas{
{\mathbb P}(V_n^*\le c/2)
\le e^{\lambda_* c/2}\,{\mathbb E}[e^{-\lambda_*V_n^*}].
}
By~((eq:7634589-4 of the paper)),
\bas{
{\mathbb E}[e^{-\lambda_*V_n^*}]
\le \exp\Bigl(-\sum_{k=1}^n \Bigl(c \frac{1-\beta}{1-\beta^n} \beta^{n-k} \lambda_* \Bigr)\wedge q\Bigr).
}
Now, for every $k\in\{1,\dots,n\}$, one has
\bas{
c \frac{1-\beta}{1-\beta^n} \beta^{n-k} \lambda_*
=q\beta^{n-k}\le q.
}
Hence all terms inside the minimum are unsaturated and therefore
\bas{
\sum_{k=1}^n \Bigl(c \frac{1-\beta}{1-\beta^n} \beta^{n-k} \lambda_* \Bigr)\wedge q
= q\sum_{k=1}^n \beta^{n-k}
= ...","release_manifest_digest":"sha256:5ff183d3d3ca192609bffed8dd25d7e96daca8bdbb0012add5e8a8241b37d1d4","revision_digest":"sha256:d1d24ea8090794cdd258e045253d396bf69386ee2cbc5a8afa72522e7dda7921","source_id":"arxiv:2608.30382","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

