body:
[Corollary cor_estimation_SID of arXiv:2411.08846, 'On the Number of Crossings and Bouncings\\ of a Diffusion at a Sticky Threshold'] Let $\mathcal P_x =(\Omega, \bF, (\bF_t)_{t\ge 0}, \Prob_x)$ be a filtered probability space and let $X$ be an $(\bF_t)_{t\ge 0}$-adapted process solution to (equation eq_stickySDE of the paper) on $\mathcal P_x$. 
The statistic defined by 
\begin{equation}
	\begin{aligned}
		\varrho_n(X) &= \left(\frac{ 4}{\sigma(0)} \sqrt{\frac 2 \pi} \right) \frac{1}{\sqrt n}\frac{\cC{2}{n,t}(X)}{ \cC{1}{n,t}(X)},
		& n&\in \IN,
	\end{aligned}
\end{equation}
is a consistent estimators of $\rho $, conditionally on the event $\mathcal H_t =\{\tau^{X}_0 < t\}= \{\exists\; s \in [0,t) \colon  X_s = 0\}$.
This means that (see~Definition~(def_conditional_convergence_in_probability of the paper)),  $\varrho_n(X)  \longrightarrow  \rho $, in $\Prob^{\mathcal H_t}_x $-probability, as $n \longrightarrow  \infty $.

[Mainthm real BKK of arXiv:2411.11345, 'Real Gaussian exponential sums via a real moment map'] Let $\mathcal{E}$ be given by (eq: def expsum in intro of the paper). Then we have:
\begin{equation}
  \mathbb{E}\mathbb{S}\left\{\mathcal{E};\mathbb{R}^m\right\}=\frac{1}{2^{\tfrac{m-2}{2}}s_m} \vol_g (P)
\end{equation}
where $s_m$ denotes the Euclidean volume of the unit sphere $S^m\subset \mathbb{R}^{m+1}$ and $\vol_g$ is the Riemannian volume for the metric $g:=D^2_p\Phi^*$, i.e., $g$ is given by the Hessian of the Legendre transform $\Phi^*$ of the potential $\Phi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:two-cut-kernel of arXiv:2609.03532, 'Airy limit for the Jack process and topological expansion'] Uniformly in $L\ge 0$ and $\delta\in\mathbb Z$,
\begin{equation}
  \mathcal T_L(\delta)\leq C(L+1)^{1/2}.

\end{equation}
In the pathwise expansion of $\mathcal T_L(\delta)$, restrict the sum
to configurations satisfying at least one of the following conditions:
$A\geq R$, $B\geq R$, or the unrestricted middle
walk $W^{\mathrm c}$ satisfies
$\operatorname{osc}(W^{\mathrm c})\geq R$.  The restricted sum is
bounded by
\begin{equation}
  C(L+1)^{1/2}
  \exp\!\left\{-\frac{cR^2}{L+R+1}\right\}.

\end{equation}

[Lemma lem:abstract-fixed-submersion-nullity of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Let $g\in\mathcal Q^M$.  If $E\in\mathcal B(\mathbb R^M)$ and
$\mathcal L^M(E)=0$, then
\begin{equation*}
 \Omega_{\nu,g}^{\rm sub}
 \cap\Lambda_{\nu}^{-1}(E)
 \in\mathcal B(X),
 \qquad
 \mathbb P\left(
 \Omega_{\nu,g}^{\rm sub}
 \cap\Lambda_{\nu}^{-1}(E)
 \right)=0.
\end{equation*}

[Defn pure partition function of arXiv:2506.01306, 'Asymptotic of Coulomb gas integral, Temperley-Lieb type algebras and pure partition functi'] The functions $\mathcal{Z}_\alpha: \mathfrak{X}_n \rightarrow \mathbb{R}^+$, indexed by link patterns $\alpha \in \mathrm{LP}(n,m)$, are called \emph{pure partition functions}. They are a collection of positive solutions to the null vector equations, subject to boundary conditions specified by their asymptotic behavior, which is determined by the link pattern $\alpha$
\begin{itemize}
    \item[\textnormal{(ASY)}] \textbf{Asymptotics:} For all $\alpha \in \mathrm{LP}_(n,m)$, $j \in \{1, \ldots, n\}$, and $\xi \in (x_{j-1}, x_{j+2})$, the following limit exists:
    \[
    \lim_{x_j, x_{j+1} \rightarrow \xi} \frac{\mathcal{Z}_\alpha\left(x_1, \ldots, x_n\right)}{(x_{j+1} - x_j)^{\frac{6 - \kappa}{\kappa}}}
    =
    \begin{cases}
        0, & \text{if } \{j, j+1\} \notin \alpha, \\
        \mathcal{Z}_{\hat{\alpha}}\left(x_1, \ldots, x_{j-1}, x_{j+2}, \ldots, x_n\right), & \text{if } \{j, j+1\} \in \alpha,
    \end{cases}
    \]
\end{itemize}
where $\hat{\alpha} = \alpha / \{j, j+1\} \in \mathrm{LP}(n-2,m-1)$ denotes the link pattern obtained from $\alpha$ by removing the link $\{j, j+1\}$ and relabeling the remaining indices as $1, 2, \ldots, n-2$.

[Lemma lemma-sum-prod-L-x-j-delta of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] Let $0 < \alpha < 1$. There exists a constant $C>0$ depending on $D$ only such that for any $k \in \mathbb{N}$,
    \begin{equation*}
        \delta^{2k} \sum_{(x_1,\dots,x_k) \in D_{\delta}^k \setminus B_k(\delta)} \big[\prod_{j=1}^{k} L(x_j)\big]^{-\alpha} \leq C^kk^{\alpha k}
    \end{equation*}
    where we have set $B_k(\delta):= \{(x_1,\dots,x_k) \in D_{\delta}^k: \exists i \neq j, \vert x_i - x_j \vert \leq 4\delta \}$.

[Lemma 4 of arXiv:2605.25719, 'A note on convergence rate for reflected BSDEs with quadratic generators by penalization m'] Let assumptions $(A1^{'}),~(A2)$ and $(A3)$ be satisfied. Then for $n \geq 1$ and $i=1,\dots,n$, BSDE \eqref{num-PBSDE} has a unique solution $(Y_{t}^{n,i,\lambda},Z_{t}^{n,i,\lambda}) \in \mathcal{S}^{\infty,i}(\mathbb{R}) \times \mathcal{H}^{2,i}(\mathbb{R}^{d})$ and \eqref{e3} has a unique solution $(Y_{t}^{n,\lambda},Z_{t}^{n,\lambda}) \in \mathcal{S}^{\infty}(\mathbb{R}) \times BMO$ and
\begin{equation}
\Vert Y^{n,\lambda}-Y^{\lambda} \Vert_{\mathcal{S}^{\infty}(R)}+\Vert Z^{n,\lambda}-Z^{\lambda} \Vert_{BMO} \leq \frac{C_{\lambda}}{n^{\frac{\varepsilon}{4}}}.
\end{equation} 
where $C_{\lambda}$ depends on $M_{\lambda}:=\sup \limits_{n\in \mathbb{N}} \left\{ \Vert Y^{n,\lambda} \Vert_{\mathcal{S}^{\infty}(R)} \right\}$ and $N_{\lambda}:=\sup \limits_{n\in \mathbb{N}} \left\{ \Vert Z^{n,\lambda}\cdot W \Vert_{BMO} \right\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 3recurrence of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Under the same condition as Proposition~(pr:key_estimate of the paper), there exist constants $C, C^*, \widetilde{C} < +\infty$ depending on $i,j,\alpha,h,N,k,d,\mathsf{r}$ satisfying
		\begin{align*}
			I^{* \;(N,k)}_{\; m,\alpha, h}(i,j) &\leqslant C^*(i,j,\alpha, h,N,k,d,\mathsf{r}), \\
			\widetilde{I}^{ \;(N,k)}_{\; m,\alpha, h}(i,j) &\leqslant \widetilde{C}(i,j,\alpha,h,N,k,d,\mathsf{r}), \\
			I^{\; (N,k)}_{\; m,\alpha, h}(i,j) &\leqslant C(i,j,\alpha,h,N,k,d,\mathsf{r}). \\
		\end{align*}

