[Definition 19 of arXiv:2606.14443, 'SEMICLASSICAL LIMIT OF POLYAKOV-LIOUVILLE MEASURE and Q-Curvature Uniformization ON EVEN-D'] A massive co-polyharmonic Gaussian field on $(M,g)$ with mass $m>0$ is a centered Gaussian random variable $\tilde h_0$ on $\mathring{\mathfrak D}'$ with covariance
	\begin{equation}

		\mathbb{E} \Big[\langle \tilde h_0|\phi\rangle \langle \tilde h_0|\eta\rangle\Big]=\mathring{\mathcal K}_{m}(\phi,\eta)

		\quad\qquad \forall \phi,\eta\in \mathring{\mathfrak D} ,
	\end{equation}
	where
	\begin{align*}
		\mathring{\mathcal K}_{m}(\phi,\eta)
		=&\sum_{j=1}^\infty \frac{\scalar{\phi}{\psi_j}\scalar{\eta}{\psi_j}}{\nu_j+m}.
	\end{align*}

[Lem 20 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] If $b$ is locally bounded then   \begin{equation*}
        C_c^2([0,\infty)\times \mathbb{R}^d)\subset \mathcal{D}(\mathcal{L})\quad \mbox{and}\quad {\sf \overline{L}}f=\mathcal{L}f, \quad f\in C_c^2([0,\infty)\times \mathbb{R}^d).
