[Lemma lem.velocity-decomp of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] Let $\alpha\in(0,\delta/2)$, let $\zeta\in(0,\zeta_H]$, let $\theta\in(0,1/4)$, and let $\varepsilon>0$ satisfy $\varepsilon(1-\alpha)<\alpha$.
				There exist deterministic constants $C,C'<\infty$ and $c>0$, a deterministic exponent $\sigma\in(0,1)$, and a random scale $\lambda_*^H\colon\Omega\to(0,1]$ such that
				\begin{equation}
						\mathbb{Q}\bigl(\lambda_*^H\le\lambda\bigr)\le C'\exp\bigl(-c (\log(1/\lambda))^\sigma\bigr)\qquad\text{for every }\lambda\in(0,1]\, .
					\end{equation}
					The constants $C,C',c,\sigma$ depend only on the displayed parameters and on $(d,\Lambda,r_0,\beta_h)$. For $\mathbb{Q}$-a.e.\ $\omega$ and every $0<\lambda\le\lambda_*^H(\omega)$,
			\begin{equation}
			\begin{aligned}
				\Bigl|\frac{\ell(\lambda)}{\lambda}-\bar{\mathbf{a}} e_1\Bigr|
				&\le C\rho(\lambda)^{-2}\lambda^{-2\varepsilon}
				+C\rho(\lambda)^{-1/2+\theta}
				+Ce^{-c3^{h(\lambda)}}\\
				&\qquad
				+C \rho(\lambda)^{1/2}3^{(d/2+1-\beta_h)h(\lambda)-\delta m(\lambda)}\, .
			\end{aligned}
			\end{equation}

[Prop 16 of arXiv:2609.02576, 'Sharp estimates for the Jacobi and trigonometric Dunkl heat kernels'] The Opdam--Cherednik heat kernel satisfies the upper bound
	\begin{equation*}
		\hOC_t (x,y) \lesssim H_t^0(x,y), 
	\end{equation*}
	uniformly in $t\geq 1$ and $x,y>0$.

