[Corollary cor:LPI of arXiv:2607.10801, 'Relaxation times of non-reversible\\ Markov processes'] \begin{enumerate}[(i)]
        \item If (equation eq:A1 of the paper), (equation eq:B1 of the paper) and (equation eq:C1 of the paper) are satisfied, then
        \begin{equation*}
            \norm{f}^2\ \leq \ \left(\frac{2}{m_1}+\frac{1+2C_1^2}{\gamma}\right)\mathcal{E}_1^\mathcal{L}(f,f)
        \end{equation*}
