[Theorem thmIgfpmf of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] The state probabilities $\hat{q}^\alpha(n,t)=\mathrm{Pr}\{\hat{M}^\alpha(t)=n\}$, $n\ge0$ of time-changed IGCP are given by
{\footnotesize
	\begin{equation*}
		\hat{q}^\alpha(n,t)=\sum_{\Omega(k,n)}\Big(\prod_{j=1}^{k}\frac{\lambda_{j}^{n_{j}}}{n_{j}!}\Big)\sum_{\sum_{j_0=1}^{k_0}r_{j_0}=z_{k}}z_{k}!\Big(\prod_{j_0=1}^{k_0}\frac{j_0^{r_{j_0}}}{r_{j_0}!}\Big)\sum_{\substack{x_{j_0}\ge0\\1\le j_0\le k_0}}\Big(\prod_{j_0=1}^{k_0}\frac{x_{j_0}^{r_{j_0}}(\mu_{j_0}t^\alpha e^{-j_0\lambda})^{x_{j_0}}}{x_{j_0}!}\Big)z_{k_0}! E_{\alpha,\alpha z_{k_0}+1}^{z_{k_0}+1}(-\mu t^\alpha),
\end{equation*}}
where  $\Omega(k,n)=\{(n_1,n_2,\dots,n_k):\sum_{j=1}^{k}jn_j=n,\, n_j\in\mathbb{N}_0\}$, $z_k=n_1+n_2+\dots+n_k$ and $z_{k_0}=x_1+x_2+\dots+x_{k_0}$.

[Lemma 48 (Wick polarization) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $m\ge1$ and let $K$ be a symmetric algebraic order-$m$ kernel over
$\cH_{\R}$, and let $W_1,\ldots,W_m$ be independent copies of the
isonormal process.  For $\varepsilon\in\{-1,1\}^m$, set
\[
 W_\varepsilon
 :=m^{-1/2}\sum_{j=1}^m\varepsilon_jW_j.
\]
Then every $W_\varepsilon$ is isonormal and
\begin{equation}

 \cT_{\Dec_mK}^{(m)}(W_1,\ldots,W_m)
 =\frac{m^{m/2}}{2^m m!}
 \sum_{\varepsilon\in\{-1,1\}^m}
 \left(\prod_{j=1}^m\varepsilon_j\right)
 I_m(K;W_\varepsilon).
\end{equation}
Consequently, for $1\le p<\infty$ and every $1\le r\le\infty$ for which
the algebraic evaluations are measured in $\Sch_r$,
\begin{equation}

 \norm{\cT_{\Dec_mK}^{(m)}}_{L^p(\Omega;\Sch_r)}
 \le\frac{m^{m/2}}{m!}
 \norm{I_m(K)}_{L^p(\Omega;\Sch_r)}.
\end{equation}
For $2\le r<\infty$, both statements extend by density to
$K\in\mathfrak W_{m,r}$.  On the quotient-sum completion, the algebraic
identity is used below; after Theorem~\ref{thm:low-Schatten-Fock}
establishes continuity of both evaluations, it extends there by density.

[Lemma lem-exponentiallytight of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Suppose that Assumption (V) holds. Then the following holds.
\begin{enumerate}
\item For any $R,L\in \mathbb{N}$, the set $K_{R}^{{{\scriptscriptstyle{({\mathcal S }})}}}(L)$ is closed in the weak topology. 
Furthermore, the set
\begin{equation}
\big\{\xi\in {\mathcal M }_1({\mathcal L }_{W_R}\times{\mathcal S }_{W_R})\colon  \Pi_{W_R}^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi)\in K_R^{{{\scriptscriptstyle{({\mathcal S }})}}}(L),\langle \partial\Pi_{W_R}^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi), \mathfrak N_{\partial {W_R}}^{{{\scriptscriptstyle{({\mathcal S }})}}}\rangle =\rho_2, J_{W_R}(\xi)\leq C\big\}
\end{equation}
is compact for any $\rho_2,C\in(0,\infty)$.

\item
\begin{equation}
\lim_{L\to\infty}\sup_{R\in \mathbb{N}}\limsup_{N\to\infty}\frac 1{|\Lambda_N|} \log \widehat{{\tt Q}}^{\ssup{\Lambda_N,{\rm par}}}\Big(\Xi_{N,R}^{{{\scriptscriptstyle{({{\mathcal S }}})}}}\in \big(K_{R}^{{{\scriptscriptstyle{({\mathcal S }})}}}(L)\big)^{\rm  c}\Big)=-\infty.
\end{equation}

\item 
For any  $R,L\in \mathbb{N}$, the map $\psi\mapsto \int\psi({\rm d} \mu)\,\sum_{i\in I} l_i$ is continuous on $K_{R}^{{{\scriptscriptstyle{({\mathcal S }})}}}(L)$.

\end{enumerate}

[Lemma 1 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $ (f_{N}, N\geq 1)$ be a sequence  in $ H ^{\odot p}$ with $p\geq 2$. Assume	\begin{equation}
			f_{N} \otimes _{1} f_{N}\to _{N \to \infty} 0  
			\mbox{ in } H ^{\otimes 2p-2}.
		\end{equation} and that there exists $M>0$ such that 
		\begin{equation}
			\sup_{N\geq1 } \Vert f_{N} \Vert ^{2} _{ H^{\otimes p}}\leq M.
		\end{equation}
		Then 

		\begin{enumerate}
			\item 	For every $ g\in H ^{\odot p}$ we have 

			\begin{equation*}
				\langle f_{N}, g\rangle _{ H ^{\otimes p}} \to _{N \to \infty} 0.
			\end{equation*}
			\item Let $ (g_{N}, N\geq 1)$  be a sequence in $ H ^{\odot p}$ which converges in $ H ^{\otimes p}$. Then 
			\begin{equation*}
				\langle f_{N}, g_{N}\rangle _{ H ^{\otimes p}}\to _{N \to \infty }0.
			\end{equation*}

		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma h of arXiv:2509.04155, 'An Approach to Sub-Gaussian Heat Kernel Estimates via Analysis on Metric Spaces'] Let $\kappa,\sigma$ and $h_{x_0,R_0}$ be as in Lemma (lemma:K of the paper).
    There are constants $C \geq 1$ and $\delta > 0$ depending only on the constants in (eq:HKMain of the paper), the constants associated with $\Psi$ in (equation eq:PsiRad of the paper) and the doubling constant of $\mu$ in (equation eq:muDoubling of the paper) such that the following holds. For all $x \in B(x_0,2\sigma R_0)\setminus B(x_0,R_0\kappa/2)$ and $y,z \in B(x,R_0\kappa /16)$,
    \begin{equation}
        \abs{h_{x_0,R_0}(y)-h_{x_0,R_0}(z)} \leq C \left(\frac{d(y,z)}{R_0}\right)^{\delta}\Psi(R_0).
    \end{equation}

