[Proposition 24 (One-sided endpoint domination) of arXiv:2608.10992, '2608.10992'] Fix $s\geq0$ with $\mathbb E[L_s]<\infty$ and $K\geq1$. Let
$q^{s,K}$ be the tail flow of Lemma~\ref{lem:tail-flow-general-data}
with initial data
\[
q_k^{s,K}(0)
:=
\mathbb P(L_s\wedge K\geq k).
\]
Then, for every $k\geq1$ and $t\geq0$,
\begin{equation}

q_k^{s,K}(t)
\leq
\mathbb P(L_{s+t}\geq k).
\end{equation}
Consequently, with $m_{s,K}:=\mathbb E[L_s\wedge K]$,
\begin{equation}

t_{\infty}^{\mathrm{iso}}
\leq
s+2\log\left(1+\frac1{m_{s,K}}\right).
\end{equation}
In particular,
\begin{equation}

X_t\preceq L_t,
\qquad
t_{\infty}^{\mathrm{iso}}
\leq t_{\infty}^{\mathrm{os}}.
\end{equation}

[Proposition 5 of arXiv:2608.29143, 'Least Variability in a Polynomial-Square Class\\ of Rational Kernels'] For the optimizer $a_*$ and center $\mu_*$ defined above,
\begin{equation}
  \int_0^\infty R_*(t)b(t)^2\e^{-t}\dd t\ge0,
  \qquad b\in\Pcal_m.
\end{equation}
Moreover, equality holds at $b=a_*$.

[Lemma 33 of arXiv:2608.17509, '2608.17509'] Let \(a>1\), and for \(m\geq1\) set
\(
        M_m(a):=\int_0^\infty r_a(\xi)^m\,\mathrm d\xi.
\)
Then
\begin{equation}

        M_m(a)
        =
        \frac{1}{2(a-1)}
        B\left(\frac{m}{a-1},m+1\right),
\end{equation}
where \(B\) is the Beta function. Equivalently,
\begin{equation}

        M_m(a)
        =
        \frac{1}{2}
        \sum_{j=0}^{m}
        (-1)^j
        \binom{m}{j}
        \frac{1}{m+(a-1)j}.
\end{equation}
Moreover, as \(m\to\infty\),
\begin{equation}

        M_m(a)
        \sim
        \sqrt{\frac{\pi}{2a}}\,m^{-1/2}\rho_a^m.
\end{equation}

