body:
[Lemma lem:mont of arXiv:2505.09604, 'Exceptional force, uncountably many solutions in the KPZ fixed point'] The following holds on the event $\Omega_1$, for all $\xi \in \mathbb{R}$. Whenever $\xi \notin \Xi$ and $b \in \mathcal{F}^\xi$, we have that 
\begin{equation} 
b(y,t) - b(x,s) = W^{\xi}(x,s;y,t),  \quad \forall (x,s;y,t) \in \mathbb{R}^4.
\end{equation}
In general, for $\xi \in \mathbb{R}$ and $b \in \mathcal{F}^\xi$, $t \in \mathbb{R}$, and $x < y$, 
\begin{equation} 
W^{\xi -}(x,t;y,t) \le b(y,t) - b(x,t) \le W^{\xi +}(x,t;y,t).
\end{equation}

[Lem pure-phase-decay-of-correlations of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] Let $\pi_\infty^-$ be the infinite volume minus measure, and fix some finite sets $U,V$. For $\beta>\beta_0$, we have 
    \begin{align*}
        \|\pi_\infty^- (\sigma(V) \in \cdot) - \pi_\infty^-(\sigma(V) \in \cdot \mid \sigma(U)\equiv -1)\|_{{\textsc{tv}}}\le |U| e^{ - \beta d(U,V)}\,.
    \end{align*}

[Lemma 8 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let $f,g \in L^2([0,T];H^1(\T^d)^d)$ with $f$ that is divergence-free. Let $p>d$ and $\gamma\in (\frac{d}{p},1)$. Then there exists $C>0$ such that for any $t\in [0,T]$,
\begin{equation*}
\int_{0}^{t} \Big\Vert e^{\left(  t-s\right) \Delta} P \big[ (f_{s} \cdot \nabla)g_s\big] \Big\Vert _{\gamma,p} \dd s \leq C \int_{0}^{t}  \frac{1}{(t-s)^{\frac{1+\gamma}{2}}} \left\Vert f_{s} \otimes g_{s} \right\Vert _{L^p_{x}}  \dd s .
\end{equation*}

[Lemma lem:sizeBoundTime of arXiv:2507.03552, 'On one-dimensional Cluster cluster model'] For $\alpha < 0$:
\begin{equation}
    \Prob{T_{k,n}^x \le \tau, \abs{\mathfs{C}_x\left( T_n^x- \right)} \le v} \le \Prob{v^\alpha \Tilde{T}_{k,n}^x \le \tau}
\end{equation}
and
\begin{equation}
    \Prob{T_{k,n}^x \ge \tau, \abs{\mathfs{C}_x\left( T_k^x \right)} \ge v} \le \Prob{v^\alpha \Tilde{T}_{k,n}^x \ge \tau}
.\end{equation}

For $\alpha > 0$:
\begin{equation}
    \Prob{T_{k,n}^x \le \tau, \abs{\mathfs{C}_x\left( T_k^x \right)} \ge v} \le \Prob{v^\alpha \Tilde{T}_{k,n}^x \le \tau}
\end{equation}
and
\begin{equation}
    \Prob{T_{k,n}^x \ge \tau, \abs{\mathfs{C}_x\left( T_n^x- \right)} \le v} \le \Prob{v^\alpha \Tilde{T}_{k,n}^x \ge \tau}
