[Corollary cor:LLN of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Fix $m\in\mathbb{N}$,  a choice sequence $\mathbf x$ such that Assumption~$\hyperref[ass:A]{\mathbf{x}}$ is satisfied for some $\varepsilon\in(0,1/((m+1)\log \theta))$ in  Part~(item:hI of the paper) and some $\eta\in(0,1/((m+1)\log\theta))$ in Part~(item:Jn of the paper). Define for $i\in\mathbb{N}_0$,        \begin{align}
N^{(n)}_i &\coloneq  |\{v \in \mathbb A_n \colon \deg_n(v) =  i\}|, &&\,N^{(n)}_{\geq i} \coloneq  |\{v \in \mathbb A_n \colon \deg_n(v) \geq   i\}|,
\intertext{and}
M^{(n)}_i &\coloneq  |\{v \in \mathbb F_n \colon \deg_n(v) =    i\}|, 
&&M^{(n)}_{\geq i} \coloneq  |\{v \in \mathbb F_n \colon \deg_n(v) \geq    i\}|.
\end{align} 
Then, for any $i=i(n),j=j(n)\in\mathbb{N}_0$ such that $\log_\theta(A_n)-i(n)\to\infty$ and $\log_\theta(F_n)-j(n)\to\infty$ with $n$, 
we have 
\begin{equation} 
\frac{ N^{(n)}_i}{(1-\theta^{-1})\theta^{-i}A_n}\buildrel {\mathbb{P}}\over{\longrightarrow} 1,\quad \frac{N^{(n)}_{\geq i}}{\theta^{-i}A_n}\buildrel {\mathbb{P}}\over{\longrightarrow}1,\quad \frac{M^{(n)}_j}{(1-\theta^{-1})\theta^{-j}F_n}\buildrel {\mathbb{P}}\over{\longrightarrow} 1,\quad \frac{M^{(n)}_{\geq j}}{\theta^{-j}F_n}\buildrel {\mathbb{P}}\over{\longrightarrow} 1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn Ypsilon of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] We define the following spaces:
\begin{align} 
\Upsilon&=\left\{\boldsymbol{\upsilon}=(\mathbf{x}^+,\mathbf{x}^-,\gamma,\delta)\in \mathbf{W}_{\infty;+}\times \mathbf{W}_{\infty;+}\times \mathbb{R}\times \mathbb{R}_+:\sum_{i=1}^\infty (x_i^+)^2+(x_i^-)^2\le \delta\right\},\\
\Upsilon_+&=\left\{\boldsymbol{v}=(\mathbf{x},\gamma)\in \mathbf{W}_{\infty;+}\times \mathbb{R}_+: \sum_{i=1}^\infty x_i\le \gamma \right\},
\end{align}
endowed with product topology as subsets of $\mathbb{R}^{\mathbb{N}}\times \mathbb{R}^{\mathbb{N}}\times \mathbb{R}\times \mathbb{R}_+$ and $\mathbb{R}^{\mathbb{N}}\times \mathbb{R}_+$ respectively.

