[Lemma l:divergence-pullback of arXiv:2607.24640, 'The Yang-Mills measure on surfaces via Morse theory'] Let $\mathrm{v}$ be a volume form on a compact manifold $M$ of dimension $n$. Let $V$ be a smooth vector field with $(\varphi^t)_{t\in \mathbb{R}}:M\mapsto M$ the corresponding flow. Then we have the exact identity
\begin{equation}
\varphi^{t*}({\rm v})=    e^{\int_0^t(\operatorname{div}_{{\rm v}} (V))\circ \varphi^s ds}   {\rm v}.
\end{equation}

[Lem nu-1-lem of arXiv:2608.30518, 'Grow-up rates of inhomogeneous semilinear heat equations in the critical dimension'] It follows that $\nu_1\in C^1(T_{0},\infty)$,
\begin{equation*}
\text{$\nu_1=\nu_0+O(\delta(t)^2)$ \hspace{2mm} and \hspace{2mm} $\nu_1'(t)=O(\delta(t)|\delta'(t)|)$ \hspace{2mm} as $t\to\infty$.}
\end{equation*}
In addition, $\xi_1 \in C^{1}((T_{0},\infty); H^{1}_{0}(B_1))$ and $\xi_1(r,t), \xi_{1,t}(r,t)\in C^1_{0}(\overline{B_1^2})$ for any $t>T_{0}$. Moreover, we have 
\begin{equation*}
    \text{$\lVert \zeta_1\rVert_{C^1(B_{1}^2)}\le C$, \quad $|\xi_1|\le \frac{M_2}{2}\psi_{1}$\quad in $B_1$\quad and \quad$|\xi_{1,t}|<C|\delta'|\delta^{-1/3} \psi_{1}$ 
\quad in $B_1$}
\end{equation*}
for any $t$ sufficiently large with some $C>0$ independent of $t$.

