[Lemma 37 of arXiv:2608.27372, 'Universality and sharp thresholds for ellipsoid fitting'] Assume the hypotheses of
	Corollary~\ref{cor:matrix-scale-universality}~\textup{(ii)}, and let
	$\varepsilon_1,\ldots,\varepsilon_n$ be independent Rademacher signs.
	Then
	\begin{equation}

		\E\left\|\frac1n\sum_{i=1}^n\varepsilon_i W_i\right\|_{\op}
		\le C\frac{\sqrt{\log d}}d.
	\end{equation}

[Lemma anbn of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] \nr{Let $(a_0, b_0) \in \mathcal{P}$. }Let $s\in {\mathbb R}$ and $(a_0, b_0) = (x(s),y(s))$. For any integer $n \in {\mathbb Z}$, we define
\nr{$$(a_{2n}, b_{2n}) = (\eta\zeta)^n(a_0,b_0), \quad (a_{2n+1}, b_{2n+1})  =  \zeta(\eta\zeta)^n(a_0,b_0)$$}
\nb{$$(a_{2n}, b_{2n}) = \left(x((\eta\zeta)^ns),y((\eta\zeta)^ns)\right), \quad (a_{2n+1}, b_{2n+1})  = \left(x(\zeta(\eta\zeta)^ns), y(\zeta(\eta\zeta)^ns)\right)$$}
(see Figure (autoo1 of the paper)). Then, for any $n \in {\mathbb Z}$ the following expressions hold.
\begin{equation}
a_{2n} = -2n^2 +  2(a_0 - b_0 - \mu_2)n + a_0, \ \ a_{2n+1} = a_{2n}
\end{equation}
\begin{equation}b_{2n} = -2n^2 + 2(a_0 - b_0 + \mu_1) n + b_0, \ \ b_{2n+1} = b_{2n+2}.
\end{equation}

[Lem 16 of arXiv:2609.03777, '2609.03777'] Let $\mu_1,\mu_2$ be lattice points that satisfy $\mu_1\ordN\mu_2$ and $\mu_1\succ\mu_2$. For $N,j\in\ZZ_{>0}$, we have
\begin{align}
G^{(N;\mu_1,\mu_2)}_{2j}(\tau)-G^{(\infty;\mu_1,\mu_2)}_{2j}(\tau)=\summ{\lambda\in\latzero}\chi_N(\lambda)(f_j(\mu_1,\lambda)-f_j(\mu_2,\lambda))\,,
\end{align}
and the series in the right-hand side absolutely converges for any $j\geq1$.

