[Lemma l.1point-minimizer of arXiv:2505.15283, 'Quantization of Probability Distributions via Divide-and-Conquer: Convergence and Error Pr'] Let $\mu \in {\mathcal{M}}_1$ then for any $x\in {\mathbb{R}}$ we have
\begin{equation}
    W_1(\mu,\delta_x) = \int_{\mathbb{R}} |t-x| \mathrm{d} \mu(t).
\end{equation}
Moreover, if $f$ is a split function and letting 
\begin{equation}
    \bar{\mu}_{+} = {\mathbb{E}}_\mu[X | X > f(\mu)], \quad
    \bar{\mu}_{-} = {\mathbb{E}}_\mu[X | X \leq f(\mu)],
\end{equation} 
then
\begin{equation}
    \begin{split}        
    W_1( \mu,\delta_{\mathrm{med}(\mu)})  
    & = \frac{1}{2} 
    \left(
        \bar{\mu}_+-\bar{\mu}_-
    \right)\\
    W_1( \mu,\delta_{\bar{\mu}})
    &= 2 \mu(\Omega_-) \left(\bar{\mu} - \bar{\mu}_-\right)  
    = 2 \mu(\Omega_+) \left(\bar{\mu}_+ - \bar{\mu}\right).
    \end{split}    
\end{equation}

