body:
[Prop 11 of arXiv:2608.25829, 'Topology of low-dimensional generalized Ricci solitons and string backgrounds'] Let $(M^8, \Phi)$ be a nontrivial compact strong torsion $\Spin(7)$-manifold.  Then
\begin{enumerate}
    \item $b_3 \geq 1$,
    \item $Y_{[g_{\Phi}]} > 0$,
    \item $\Aroof = 0$,
    \item $\chi = \tau = p_1^2 = p_2 = 0$.
\end{enumerate}
\begin{proof} Compact strong torsion $\Spin(7)$-manifolds are generalized Ricci solitons \cite{ivanov2023riemannianspin7}, hence items (1) and (2) follow from Propositions \ref{p:b3bound} and \ref{p:AroofGRS}.  As manifolds with $\Spin(7)$ structures are automatically spin, item (3) follows.  Compact nontrivial strong torsion $\Spin(7)$-manifolds admit a canonical Bismut parallel vector field by \cite[Theorem 6.4]{ivanov2023riemannianspin7}.  This vector field is in particular nowhere vanishing, hence $\chi = 0$. 

Using the Hirzebruch signature theorem (cf. \cite{joyce2000compact}) we obtain 
\begin{align*}
    45 (b_4^+ - b_4^-) = 45 \tau = 7 p_2 - p_1^2, \qquad 45 \cdot 2^7 \Aroof = 7 p_1^2 - 4 p_2.
\end{align*}
On the other hand the existence of a $\Spin(7)$ structure always implies
\begin{align*}
    p_1^2 - 4 p_2 + 8 \chi = 0.
\end{align*}
As we have shown that $\chi = \Aroof  = 0$, it follows that $p_1^2 = p_2 = 0$, hence also $\tau = 0$, finishing item (4).
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:negligible W+ of arXiv:2512.17747, 'On exponentially height-penalized random trees'] {Recall $t_{\mu/n}=\argmin_{t \in (0,2)}\lambda_{\mu/n}(t)$, and} $X_{n,m}$ be as defined as in~(equation eq:def smt of the paper), and $\epsilon_n\ll1$ be such that $\epsilon_nt_n\gg1$ and $\epsilon_n^2(\mu^2n)^{1/3}\gg\log(\mu^2n)$.
    Then, the sum over $m\geq(1+\epsilon_n)t_{\mu/n}$ of $X_{n,m}$ is negligible, as given by
    \begin{align*}
        \lim_{n\rightarrow\infty}\sum_{(1+\epsilon_n)t_{\mu/n}\leq m\leq n}X_{n,m}=0\,.
    \end{align*}

