[Corollary 4 of arXiv:2608.26618, 'A Unified Descriptive-Complexity Framework for Model Selection under Correlated Designs'] For every $\lambda \geq \lambda_{\rm sel}$, if the following conditions hold:
\begin{itemize}
    \item[(\romannumeral 1)]
    There exists a sufficiently large constant $c_1>1$ such that, for every
    $S\in\mathcal M_{\mathrm{sub}}$,
    \begin{equation*}
    \mathrm{APP}(S)\ge
    c_1\Bigg(
    (s^*-s)\log n
    +\lambda\Bigl((g^*\log m)^{\frac{2}{\alpha}}-(g\log m)^{\frac{2}{\alpha}}\Bigr)
    +\log^{\frac{2}{\alpha}}\binom{g^*}{\Delta^-(S)}
    \Bigg).
    \end{equation*}

\item[(\romannumeral 2)]
There exists a constant \(\kappa>0\) such that
\(2B_S<u_S\) for all \(S\in\mathcal M_w\) with
\(g>(1+\kappa)g^*\).
Moreover, for every \(S\in\mathcal M_w\) with
\(g\le(1+\kappa)g^*\),
\begin{equation*}
\begin{aligned}
\mathrm{APP}(S)\ge{}&
\lambda\left\{
\log
\binom{g^*}{\Delta^-(S)}
\binom{m-g^*}{\Delta^+(S)}
\right\}^{\frac{2}{\alpha}}
+2(s^*-s)\log n
\\
&+2\lambda\left\{
(g^*\log m)^{\frac{2}{\alpha}}
-(g\log m)^{\frac{2}{\alpha}}
\right\}
+\log\log n
+8(r_S-\widetilde r_S).
\end{aligned}
\end{equation*}
\end{itemize}
Then
\[
\Pr\!\left(
\min_{S\in\mathcal M_n,\;S\neq S^*}\mathrm{DCIC}(S)>\mathrm{DCIC}(S^*)
\right)\to 1
\qquad \text{as } n\to\infty.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2605.28377, 'Geometric functionals of Brownian motion on Hermitian symmetric spaces of non-compact type'] For every $t > 0$, $\alpha > 0$ and $\tau \in \bar{\mathcal{C}}$,
\[
  \mathbb{E}\bigl[e^{i\alpha S(t)} \mid \tau(t) = \tau\bigr]
  = e^{n\alpha\sqrt{\gamma}\, t}
    \frac{p^{a,\, 1+2\alpha\sqrt{\gamma},\, 2b - 2\alpha\sqrt{\gamma}}_t(\tau(0), \tau)}
         {p^{a,\, 1,\, 2b}_t(\tau(0), \tau)}
    \prod_{i=1}^r \bigl(4\cosh\tau_i(0)\cosh\tau_i\bigr)^{\alpha\sqrt{\gamma}},
\]
where $p^{k_1,k_2,k_3}_t$ denotes the heat kernel of the Heckman--Opdam Laplacian
$\frac{1}{2}\mathcal{L}_{k_1,k_2,k_3}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:J momentum map of arXiv:2608.28278, 'Reduction of symmetric time-dependent Hamiltonian systems I: presymplectic principal $\R$-'] $(T^*Q, \omega_h, T^*\phi, J)$ is a symmetric presymplectic Hamiltonian system with $Ad^*$-equivariant momentum map $J:T^*Q \to \mathfrak{g}^*$ given by
    \begin{equation}
        J(\alpha_q)(\xi) = \alpha_q(\xi_Q(q)) - F_h(\alpha_q)c_\phi(\xi),
    \end{equation}
    for all $\alpha_q \in T_q^*Q$ and $\xi \in \mathfrak{g}$.

