body:
[Corollary thm.mtg2 of arXiv:2605.17725, 'Limit theorems for random walks with spatio-temporal drift'] Let $(M_n)$ be an $\mathbb{R}^d$-valued martingale such that
        $$\Lambda_n := \sum_{k=1}^n \mathbb{E}[\Delta_k \Delta_k^\top] = \mathbb{E}[M_n M_n^\top] \to \infty$$ and $\Lambda_n$ is eventually positive definite.
Assume that 
for every $\varepsilon > 0$,
\begin{align}
    &\Lambda_n^{-1/2}\sum_{k=1}^n \mathbb{E}\Big[ \Delta_k \Delta_k^\top \,
        \mathbf{1}_{\Big\{\norm{\Lambda_n^{-1/2}\Delta_k} > \varepsilon\Big\}} \,\Big|\, \mathcal{F}_{k-1} \Big]\Lambda_n^{-1/2}
        \xrightarrow{p} 0\quad \text{and}\\
    & \Lambda_n^{-1/2} \sum_{k=1}^n \mathbb{E}\left[\Delta_k \Delta_k^\top \mid \mathcal{F}_{k-1}\right] \Lambda_n^{-1/2} \xrightarrow{p} I_d.
\end{align}
Then,
$\Lambda_n^{-1/2} M_n \xrightarrow{d} \mathcal{N}_d(0, I_d)$.

[Definition 5 of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] For $Z\in H^2_G(0,T)$, a symmetric $G$-martingale $\int_0^\cdot Z_sdB_s$ on $[0,T]$ is called a $G$-BMO martingale if
    \begin{align*}
       \|Z\|_{BMO_G}^2:=\sup_{\P\in\mathcal{P}}\|Z\|^2_{BMO(\P)}=\sup_{\P\in\mathcal{P}}\sup_{\tau\in\mathcal{T}_0^T}\Bigg\|\E^\P_\tau\left[\int_\tau^T|Z_t|^2d\langle B\rangle_t\right] \Bigg\|_{L^\infty(\P)}<\infty,
    \end{align*}
    where $\mathcal{T}_0^T$ denotes the collection of all $\mathbb{F}$-stopping times taking values in $[0,T]$ and $\|Z\|_{BMO(\P)}$ is the BMO norm of $\int_0^\cdot Z_s dB_s$ under probability $\P$. $Z$ is called a $G$-BMO martingale generator.

[Lemma lem:second_moment_Uk of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] For any $\hat{\beta} \in [0,z_a)$, there exists $C_{\hat \beta}>0$ such that
    \begin{equation}
    \limsup_{N\to\infty} \sup_{1 \le k\leq M}{\mathbb E}\left[ U_{k,M,N}^2\right] \leq  \frac{C_{\hat \beta}}{M}\,,
\end{equation}
and
\begin{equation}

    \lim_{M \to \infty} \, \lim_{N \to \infty} \sum_{k=1}^M \mathbb{E} \big[ U_{k,M,N}^2\big] = \lambda^2 \coloneqq \log \tilde J_\alpha (\hat \beta )^{-1}\,.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:Gini_comparison_special_case of arXiv:2602.00988, 'Wealth exchange under ceiling and flooring constraints: a modified Bennati–Dragulescu–Yako'] Let $a \in \mathbb N$ and $b \to \infty$. Then the equilibrium solution $({\bf p}^{a,\infty})^*$ of the mean-field system (equation eq:law_limit of the paper) with ${\bf p}(0) \in V_\mu$ satisfies the following Gini index comparison principle
\begin{equation}
G[({\bf p}^{a',\infty})^*] \leq G[({\bf p}^{a,\infty})^*]
\end{equation}
whenever $a \leq a' < \mu$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition SigmaCTM of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] \medskip \noindent  A random vector $X$ is $\Sigma $\textit{
-countermonotone} if, for every nonempty proper subset $A$, the bivariate
pair 
\begin{equation*}
(S_{A},S_{A^{c}})
\end{equation*}
is countermonotone. \medskip

\textit{Joint mixability} implies $\Sigma $\textit{-countermonotonicity},
since if 
\begin{equation*}
\sum_{i}X_{i}=k\quad \text{a.s.},
\end{equation*}
then 
\begin{equation*}
S_{A^{c}}=k-S_{A}.
\end{equation*}

[Lemma GLTNNRS-A of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] Let ${\mathbb{B}_{\frac{1}{2}}}\left( {\mathrm{Id}} \right)$ be the metric ball consisting of symmetric $2 \times 2$ matrices, where $\mathrm{Id}$ is the identity matrix. Then, there exist finite set $\Lambda  \subset {\mathbb{Z}^2}$ and smooth function ${\gamma _\xi }:\ {\mathbb{B}_{\frac{1}{2}}}\left( {\mathrm{Id}} \right) \longrightarrow \mathbb{R}$ for each $\xi \in \Lambda$ such that
\begin{equation*}
R = \sum\limits_{\xi  \in \Lambda } {\gamma _\xi ^2\left( R \right)\xi  \otimes \xi },\ \ \forall \, R \in {\mathbb{B}_{\frac{1}{2}}}\left( {\mathrm{Id}} \right) .
\end{equation*}
Furthermore, there exist smooth $1$-periodic functions ${g_{\xi ,e,n}} {\left( t \right)}:\ \mathbb{R} \longrightarrow \mathbb{R}$ such that
\begin{equation*}
\int_0^1 {g_{\xi ,\iota ,n}^2\left( t \right)} \ \mathrm{d}t = 1,\ \ \forall \,  \left( {\xi ,\iota,n} \right) \in \Lambda  \times \left\{ {e,o} \right\} \times \left\{ {1,2, \cdots ,\Gamma } \right\},
\end{equation*}
and
\begin{equation*}
\mathrm{supp}_t \ {g_{{\xi _1},{\iota_1},{n_1}}} \cap \mathrm{supp}_t \ {g_{{\xi _2},{\iota_2},{n_2}}} = \emptyset , \ \ \mbox{as}\ \left( {{\xi _1},{\iota_1},{n_1}} \right) \ne \left( {{\xi _2},{\iota_2},{n_2}} \right) \in \Lambda  \times \left\{ {e,o} \right\} \times \left\{ {1,2, \cdots ,\Gamma } \right\} ,
\end{equation*}
where the step size $\Gamma$ is specified in Appendix C. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 232 (The main estimates for difficult top-order spacetime error integrals requiring integration by parts in $\newL$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $N = \Ntop$, 
and let $\tanderY^N \in \mathfrak{Y}^{(N)}$ be of the form $\tanderY^N = \Yvf{A} \tanderY^{N-1}$ for some $A = 2,3$, where $\tanderY^{N-1} \in \mathfrak{Y}^{(N-1)}$. 
Then the following estimate holds for 
$(\ubar,u) \in [\leftubar,\ubarboot) \times [\moreinterestingu_1,\moreinterestingu_2]$:
	\begin{align}
		\begin{split} 
			& \left| \sum_{i=1}^3 \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}} 
			 (\Lunit \tanderY^N v^i)
			(\muX v^i) \tanderY^N \mytr_{\gtorus}\upchi
			\weight^{\blowupratetoporderwave} \ReciprocalLunitAppliedtoTimeFunction
			\, \voldiamond\right| \\
			&  \le  \boxed{\frac{2}{3}} \totalfluxcontrolvelocity_N(\ubar,u) + \boxed{\frac{3}{4}(1.01)}\totalfluxcontrolpartialmodifiedchi(\ubar,u)  +  \boxed{2.07} \weakspacetimeangularvelocitycontrol_N(\ubar,u) \\
			& \ \ + \Errortoparg{N}(\ubar,u).
		\end{split}
	\end{align}
where $\Errortoparg{N}(\timefunction,u)$ satisfies \eqref{E:ERRORTOPORDERWAVEESTIMATES}.

