[Definition 8 of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] Let $U\subset \BC$ be a domain. Let $z \in U$. Let $(U_n)_{n\ge 0}$ be a sequence of domains in $\BC$. The sequence $(U_n)_{n\ge 0}$ converges in the sense of Carath\'eodory toward $U$ relative to $z$ if 
	\begin{itemize}
		\item For each compact set $K\subset U$, we have $K\subset U_n$ for all $n$ large enough;
		\item For each connected open set $V\ni z$, if $V \subset U_n$ for infinitely many $n\ge 0$, then $V \subset U$.
	\end{itemize}

[Proposition 51 (Mixed Schatten profile and incidence reduction) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Let $\mathbf c=(c_1,\ldots,c_m)$ with $c_j\in\ell^2(\Gamma)$.  For every
$N\ge1$ and every cut $S\subset[m]$,
\begin{align}

 \norm{\Flat_S(\widetilde K_{\mathbf c,N}^{L,Q})}_{\Sch_2}^2
 &=\sum_{x_1,\ldots,x_m}
 \left|\prod_{j=1}^mc_{j,x_j}^{(N)}\right|^2
 \#\{y\in A_Q:x_1\cdots x_my\in A_L\}.
\end{align}
Consequently,
\begin{equation}

 \Prof_{m,r}(K_{\mathbf c,N}^{L,Q})
 \le\Prof_{m,r}(\widetilde K_{\mathbf c,N}^{L,Q})
 \le C_\Gamma^{1/r}\min\{L,Q\}^{D/r}
      \prod_{j=1}^m\norm{c_j^{(N)}}_{\ell^2},
 \qquad 2\le r\le\infty.
\end{equation}
At $r=\infty$, the factor involving $C_\Gamma,L,Q$ is interpreted as one.

[Proposition 15 of arXiv:2609.03556, 'An Effective SPDE Model for a Schr\"odinger Equation with a Fluctuating Magnetic Potential'] \label[proposition]{prop:compactness_time_fluct}
    For each $\tau\in(0,1)$ and $0\leq s\leq t\leq T$,
    \begin{align*}
        \|\xi^{\tau}_t-\xi^{\tau}_s\|_{H^{-5}}
        &\leq\norm{\int_s^t
        Z^{\tau}_r\cdot\nabla\bar{\psi}_r\,dr}_{H^{-3}}+\norm{\int_s^t
        \frac{\wick{|A^\tau_r|^2}\bar{\psi}_r}{\sqrt{\tau}}\,dr}_{H^{-3}}\\
        &\quad+
        K|t-s|^{1/2}e^{K\mathcal A_T^\tau}
        \left(1+\int_0^T\|A^{\tau}_r\|^6_{W^{3,\infty}}dr\right)
        \mathcal N_T^\tau
         \quad \mathbb{P}-a.s.
\end{align*}
for some positive non-random constant $K>0$ independent of $\tau,s,t.$

