body:
[Lemma 21 of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] Let $I$ denote a uniformly random independent set in $\Qp$.
\begin{enumerate}
	\item  For $p > 0$, 
	\begin{equation}
		\P\left[I \cap \cE \in \Sep^\cE \text{ or } I \cap \cO \in \Sep^\cO \text{, but not both}\right] \pto 1.
	\end{equation}

	\item For $p > 0$ and any $S \in \Sep^\cE$ (uniformly),
	\begin{equation}
		\P\left[I \cap \cE = S \middle| I \cap \cE \in \Sep^\cE\right] \psim \fr{\prod_{\fp \in S} \phi_\fp}{\polymerpf^\cE},
	\end{equation}
	and similarly for $\cE$ replaced by $\cO$.

	\item For $p > \fr{1}{2} - \gamma$ (where $\gamma > 0$ is as in Proposition \ref{prop:dimers}),
	\begin{equation}
		\P\left[I \cap \cE \in \Sep^\cE \right] \psim q^\cE,
	\end{equation}
	and similarly for $\cE$ replaced by $\cO$.
\end{enumerate}

