Set
\begin{align*}
&\hat{F}_t=F^1_t-F^2_t, \textrm{ where } F=Y,Z,K,y,z,k, \\ &\hat{f}_t=f(t,y^1_t,\P_{y^1_t},z^1_t,\P_{z^1_t},G_t(k^1))-f(t,y^2_t,\P_{y^2_t},z^2_t,\P_{z^2_t},G_t(k^2)).
