body:
[Thm permuton_conv of arXiv:2509.07729, 'Permuton and local limits for the Luce model'] Set $f_n(y):=\theta_{\lfloor yn \rfloor}$ for all $y\in[0,1]$ and assume that $f_n\to f$ almost everywhere for some positive, finite, measurable function $f$ on $[0,1]$.
	Let also $\mu$ be the law of the pair
	\begin{equation}
            (X,Y):=\Big(U,F\big(E/f(U)\big)\Big),
        \end{equation}
	where $U$ is a uniform random variable on $[0,1]$, $E$ is an independent exponential random variable of parameter 1, and
	\begin{equation}
		F(x):=1-\int_0^1\mathrm{e}^{-x f(y)}\,\text{d} y,\quad \text{for all $x\geq 0$.}
	\end{equation}
	If $\sigma_n\sim \Luce(\theta_1,\dots,\theta_n)$, then the sequence $(\sigma_n)_n$ converges in probability in the permuton sense to the deterministic permuton $\mu$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:orthogonal_density of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let $(e_i)_{i=1}^\infty, (q_k)_{k=1}^\infty$ be  orthonormal basis of $\mathcal{H}, V$, respectively.  The collection  
    \begin{equs}
        \mathcal{S}_{ON}(V \otimes \mathcal{H})= \left\{ \sum_{i,k= 1}^n f_{ik}(B(e_1), \dots, B(e_n)) q_k \otimes e_i: n \in \mathbb{N}, f_{ik} \in \mathcal{C}_{\mathrm{pol}}^\infty({\mathbb{R}}^n) \right\} 
    \end{equs}
    is dense in $\mathbb{D}^{k, p}(V \otimes \mathcal{H})$ for any $k \geq 0$, $p \geq 2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:imp of arXiv:2605.07591, 'Nonnegativity of the second largest eigenvalue of \(4 \times 4\) tridiagonal stochastic ma'] The following statements hold:
\begin{enumerate}
\item If \(\Delta_2 \le 0\), then \(\Delta_3 \le 0\).
\item If \(\Delta_3 \le 0\) and \(\Delta_2 \ge 0\), then \(\Delta_4 \le 0\).
\end{enumerate}

[Theorem thm:R0 of arXiv:2609.01562, 'Points of maximal traffic on a grid with obstruction'] Let $B=(c,c)\in\mathcal{R}_0(n)$ with $n\ge 5$. For every $A\in\mathcal{G}(n)\backslash\{(0,0),(n,n)\}$, we have
\begin{equation*}
 f_B(A) \le 
 \begin{cases}
 f_B(1,1) & \text{if $c<n\le 2c$}, \\
 f_B(n-1,n-1) & \text{if $2c \le n$.}
 \end{cases}
\end{equation*}

[Theorem thm occu mdp of arXiv:2604.10509, 'Nonequilibrium fluctuations and moderate deviations for the occupation time of the SSEP wi'] As $n \rightarrow \infty$, the sequence  $\{ \Gamma^n (t)/a_n, 0 \leq t \leq T\}$ satisfies the moderate deviation principles with decay rate $a_n^2$ and with rate function ${\mathcal I}_T$ in the space $C([0,T], \mathbb R)$. Precisely speaking,
	for any closed set $C$ and any open set $O$ in $C ([0,T], \mathbb R)$,
	\begin{align*}
		\limsup_{n \rightarrow \infty} \frac{1}{a_n^2} \log \mathbb P^n_{\rho_*} \Big( \{  \Gamma^n (t)/a_n , 0 \leq t \leq T\} \in C\Big) \leq - \inf_{\gamma \in C} \mathcal{I}_T (\gamma),\\
		\liminf_{n \rightarrow \infty} \frac{1}{a_n^2} \log \mathbb P^n_{\rho_*} \Big( \{ \Gamma^n (t)/a_n, 0 \leq t \leq T\} \in O\Big) \geq - \inf_{\gamma \in O} \mathcal{I}_T (\gamma).
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 69 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] For every permutation $w$,
\begin{equation}
 \Nrm(\Sch_w)\in\RV.
\end{equation}
Taking $\kk=\CC$, every normalized ordinary Schubert polynomial is
Lorentzian.

[Conj desirables of arXiv:2601.20502, 'Optimal matching under size priority'] Under the setting and notation of Theorem~(maintheorem2 of the paper), let us write $\mathcal{M}_{\max}(G_n)$ the set of maximum size matchings in $G_n$, then:
        \begin{equation}
            \begin{aligned}
                \lim_{n \rightarrow +\infty} \mathbb{E}\left[ \frac{1}{|E(G_n)|} \sum_{e \in E(G_n)} \mathbbm{1}_{\forall M \in \mathcal{M}_{\max}(G_n), e \in M}\right] = \mathbb{P}_{((i,Z),(i',Z'))\sim \zeta'\otimes\zeta'}\left( i+i'<k \right), \\
                \lim_{n \rightarrow +\infty} \mathbb{E}\left[ \frac{1}{|E(G_n)|} \sum_{e \in E(G_n)} \mathbbm{1}_{\forall M \in \mathcal{M}_{\max}(G_n), e \notin M}\right] = \mathbb{P}_{((i,Z),(i',Z'))\sim \zeta'\otimes\zeta'}\left( i+i'>k \right).
            \end{aligned}
        \end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Proposition 65 (Expansion of moments into Feynman diagrams) of arXiv:2605.14630, '2605.14630'] For any $n\geqs2$, 
\begin{equation}

 \biggexpecin{\mu_{1,0}}{\biggpar{\int_{\Lambda}\Wick{\phi(x)^4}\6x}^n}
 = \sum_k \Pi(\Gamma_{n,k})\;,
\end{equation} 
where the sum runs over all vacuum diagrams $\Gamma_{n,k}$ with $n$ 
vertices and $2n$ edges, obtained as perfect pairwise matchings of
$n$ vertices of arity $4$ (each vertex belongs to four edges), 
when matchings of different legs are counted as different terms.

