body:
[Theorem thm1 of arXiv:2411.15881, 'Stable Approximation for Call Function Via Stein's method'] Let $X_1,X_2,\ldots$ be independent and identically distributed random variables defined on a common probability space, and suppose that $X_1$ has
a distribution of the form ((px of the paper)) with $B(x)$ satisfying ((bound of the paper)).
Set $\sigma=\left(A\alpha\int_{-\infty}^{\infty} \frac{1-\cos y}{|y|^{1+\alpha}}dy\right)^\frac1\alpha$ and
\begin{equation}
S_n=\frac{1}{\sigma n^{\frac{1}{\alpha}}}\sum_{i=1}^{n}(X_i-\mathbb{E}[X_i]).
\end{equation}
Then we have
\begin{align*}
\left|\mathbb{E}\left(S_n-M\right)_{+}-\mathbb{E}\left(S_\alpha (1,\delta)-M\right)_{+}\right|\leq c_{1}{R_{n}},
\end{align*}
where
\begin{align}
R_{n}=\begin{cases}
n^{1-\frac{2}{\alpha}},\quad &\gamma\in(2-\alpha,\infty),\\
n^{1-\frac{2}{\alpha}}\left|\log \left(\sigma n^{\frac{1}{\alpha}}\right)\right|,\quad &\gamma=2-\alpha,\\
n^{-\frac{(\alpha-1)\gamma}{\alpha(1-\gamma)}},\quad &\gamma\in(0,2-\alpha),\\
n^{1-\frac{2}{\alpha}}+n^{1-\frac{2}{\alpha}}\int_{-\sigma n^{\frac{1}{\alpha}}}^{\sigma n^{\frac{1}{\alpha}}}\frac{|B(x)|}{|x|^{\alpha-1}}dx+(\sup_{|x|\geq \sigma n^{\frac{1}{\alpha}}}|B(x)|)^{\alpha-1}, &\gamma=0,
\end{cases}
\end{align}
and
\begin{align*}
c_{1}=&
\left[\frac{16d_{\alpha}\mathbb{E}\left[\left|\xi_{1}-\mathbb{E}[\xi_{1}]\right|^{2-\alpha}\right]}{(2-\alpha)(\alpha-1)\sigma^{2-\alpha}}
+\frac{12\mathbb{E}\left[|\xi_{1}|\right]\left|\mathbb{E}[\xi_{1}]\right|}{\sigma^{2}}\right]\eta_{2,\alpha,\delta}\\
&+
\begin{cases}
\frac{8(2A)^{\frac{2}{\alpha}}}{\sigma^{2}}\left[\frac{2}{2-\alpha}+\frac{2L}{\alpha+\gamma-2}(2A)^{-\frac{\alpha+\gamma}{\alpha}}\right]\eta_{2,\alpha,\delta},
&\gamma\in(2-\alpha,\infty),\\
\frac{1}{\sigma^{2}}\left[4\left(\frac{4(2A)^{\frac{2}{\alpha}}}{2-\alpha}+\frac{8L}{\alpha-1}\right)\eta_{2,\alpha,\delta}
+\frac{8\alpha^{2}(A+L)-4L}{\alpha-1}\right],&\gamma=2-\alpha,\\
\sigma^{\frac{\alpha-\gamma}{\gamma-1}}\left[4\left(\frac{4(2A)^{\frac{2}{\alpha}}}{2-\alpha}+\frac{8L}{2-\alpha-\gamma}\right)\eta_{2,\alpha,\delta}
+\frac{8\alpha^{2}(A+L)-4L}{\alpha-1}\right], &\gamma\in(0,2-\alpha),\\
4\max\left\{\frac{2\alpha(2A)^{\frac{2}{\alpha}}}{(2-\alpha)\sigma^{2}},\frac{4}{\sigma^{2}},
\frac{8}{(2-\alpha)\sigma^{\alpha}}+\frac{2(2A)^{\frac{2}{\alpha}}}{\sigma^{\alpha}}+\frac{8\alpha^{2}(A+L)-4L}{4(\alpha-1)\eta_{2,\alpha,\delta}\sigma^{\alpha}}\right\}
\eta_{2,\alpha,\delta}, &\gamma=0.
\end{cases}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:Ytemporal of arXiv:2607.25694, 'Parameter Estimation of the Stochastic Allen--Cahn Equation via variations.'] For every \(t\in[0,T]\), \(x\in \mathbb{T}\), \(h>0\), and \(p\ge2\), it holds that
\begin{equation}
\mathbf{E}\bigl|Y(t+h,x)-Y(t,x)\bigr|^{p}\le C\,h^{\frac{p}{\beta}},
\end{equation}
for all \(\beta\in(\frac{4}{3},2)\).

