			\abs{J}\sum_{w\in\Sigma^J} \big((\mu^t\widehat{\Phi}_J)([w])-\mu^t([w])\big)\log\frac{\mu^t([w])}{\lambda([w])}
			&& \text{(Observation~(obs:IPS:generator-in-terms-of-asynchronous of the paper))} ...","release_manifest_digest":"sha256:72abc9d149b903c68d46dd1f355e0c4073b6d20bfa95aab5141c8258a9521cb7","revision_digest":"sha256:d5a7368aa6923ddf013b13b0edbeb99a1af6d609992ae3955e725145b6a66346","source_id":"arxiv:2605.16904","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

