[Lemma lem.less_peaked_coupling of arXiv:2603.11043, 'An asymptotically optimal bound for the concentration function of a sum of independent int'] Let $\mu$ and $\mu'$ be probability measures with rational probabilities
    and finite supports on $\mathbb{Z}$.

    Assume that $\mu'$ is symmetric and unimodal




    and $\mu \preccurlyeq_\epsilon \mu'$ for some $\epsilon \ge 0$.

    Then there is a coupling of $Z \sim \mu^+$ and $X'\sim\mu'$ and
    an event $A$ with $\mathbb P(A) \ge \frac 1 {1+\epsilon}$ such that
    $\mathcal{L}(Z|A) = \mu^+$ and
    \begin{align*}


            0 \le X' \le Z  \mbox{ or }  Z-1 \le X' \le 0 \quad \mbox{conditioned on $A$} 




    \end{align*}
    Furthermore, if $\mathbb P(\bar{A}) > 0$ then 
    $\mathcal{L}(Z|\bar{A}) = \mu^+$ and
    \begin{align*}
        \mbox{$Z$ and $X'$ are independent} \quad \mbox{conditioned on $\bar{A}$.}
    \end{align*}

[Theorem 1 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] Let $Y(t)$, $t\in\RR$, be a CTRW as in \eqref{defctrw} and suppose that $(S_n, T_n)$, $n\in \NN \cup \{0\}$, is a Markov chain such that \eqref{nonexplosion} holds. Assume further that, for all $(z,r) \in \mathbb{R}^d \times \mathbb{R}$, $(z^\prime,r^\prime) \in \mathbb{R}^d \times \mathbb{R}$ and $(x,s) \in \mathbb{R}^d \times \mathbb{R}$, it holds that
		\begin{align}
			\mathds{P}^{(z,r)} \left( S_{n+1} \in dy, W_{n+1} \in dw \mid S_n = x, T_n = s \right) \, = \, &\mathds{P}^{(z^\prime,r^\prime)} \left( S_{n+1} \in dy, W_{n+1} \in dw \mid S_n = x \right) \notag \\
			= \, & \mathds{P}^{(x,0)} \left( S_1 \in dy, W_1 \in dw \right) \notag  \\
			\eqqcolon \, & \mu_x(dy,dw).
		\end{align}
		Define, for $t \geq 0$,
		\begin{align}
			\xi(t) \, = \, t-T_n, \qquad T_n\leq t < T_{n+1},
		\end{align}
		i.e. $\xi(t) = t- T(t)$.
		Then the process $(Y(t), \xi (t))$, $t \geq 0$, is a time-homogeneous Markov process, under the measures $\PP^{(x,s)}$, $(x,s)\in \RR^d\times (-\infty,0]$, and the filtration $\mathcal{F}_t$, $t \geq 0$, generated by $N(s), S_0, \dots, S_{N(s)}, T_0, \dots, T_{N(s)}$, $s \le t$. Moreover, its semigroup $P_t$, $t \geq 0$, satisfies for $(x,s)\in \RR^d\times [0,+\infty)$
		\begin{align}
			P_tf(x,s) \, = \, f(x,s+t) \, \frac{\mu_x(\mathbb{R}^d, (t+s, +\infty))}{\mu_x(\mathbb{R}^d, (s, +\infty))} + \int_{(s,s+t]} \int_{\mathbb{R}^d} P_{t+s-u}f(y,0)   \frac{\mu_x(dy, du)}{\mu_x(\mathbb{R}^d, (s, +\infty))},

		\end{align}
		and 
		\begin{align}
			P_tf(x,0) = \mathds{E}^{(x,0)} f(Y(t), \xi(t)), \quad x\in \RR^d,

		\end{align}
		for any function $f$ which is bounded and Borel measurable ($f \in \mathcal{B}_b (\mathbb{R}^d \times [0, +\infty))$).

