body:
[Theorem 5 of arXiv:2604.23610, 'Scaling limits of Lévy walks with random velocities'] Let $\{U_V\left(t\right)\}_{t\ge0}$ and $\{O_V\left(t\right)\}_{t\ge0}$ be the wait-first LW with
 random velocities and jump-first LW with random velocities, respectively, that are generated by the sequence $\left\{V_i, \, T_i, \, \mathbf{J}_i\right\}_{i\in \mathbb{N}}$. Then,
 \begin{enumerate}
     \item 
     if $\alpha<\beta$, we have
     \begin{equation}
         \begin{aligned}
             n^{-1/\alpha}U_V\left(n^{1/\alpha}t\right) \overunderset{\mathbb{J}_1}{n \to \infty}{\to } \left(\mathbf{L}_{\alpha}^-\left(S_{\alpha}^{-1}\left(t\right)\right)\right)^+,\\
             n^{-1/\alpha}O_V\left(n^{1/\alpha}t\right) \overunderset{\mathbb{J}_1}{n \to \infty}{\to } \mathbf{L}_{\alpha}\left(S_{\alpha}^{-1}\left(t\right)\right),
         \end{aligned}
     \end{equation}
     where the processes $\{\mathbf{L}_{\alpha}\left(t\right)\}_{t\ge0}$ and $\{S_{\alpha}\left(t\right)\}_{t\ge0}$ are dependent according to their joint L\'evy measure given by Eq. \eqref{levymeasure1},
     \item 
     if $\alpha>\beta$, we have
     \begin{equation}
         \begin{aligned}
             n^{-1/\beta}U_V\left(n^{1/\alpha}t\right) \overunderset{\mathbb{J}_1}{n \to \infty}{\to } \left(\mathbf{L}_{\beta}^-\left(S_{\alpha}^{-1}\left(t\right)\right)\right)^+,\\
             n^{-1/\beta}O_V\left(n^{1/\alpha}t\right) \overunderset{\mathbb{J}_1}{n \to \infty}{\to } \mathbf{L}_{\beta}\left(S_{\alpha}^{-1}\left(t\right)\right),
         \end{aligned}
     \end{equation}
     where the processes $\{\mathbf{L}_{\beta}\left(t\right)\}_{t\ge0}$ and $\{S_{\alpha}\left(t\right)\}_{t\ge0}$ are independent according their joint L\'evy measure given by Eq. \eqref{levymeasure2},
     \item 
     if $\alpha=\beta$, we have
     \begin{equation}
         \begin{aligned}
             n^{-1/\alpha}U_V\left(n^{1/\alpha}t\right) \overunderset{\mathbb{J}_1}{n \to \infty}{\to } \left(\mathbf{L}_{\alpha}^{\text{log}-}\left(S_{\alpha}^{-1}\left(t\right)\right)\right)^+,\\
             n^{-1/\alpha}O_V\left(n^{1/\alpha}t\right) \overunderset{\mathbb{J}_1}{n \to \infty}{\to } \mathbf{L}_{\alpha}^{\text{log}}\left(S_{\alpha}^{-1}\left(t\right)\right),
         \end{aligned}
     \end{equation}
     where the processes $\{\mathbf{L}_{\alpha}^{\text{log}}\left(t\right)\}_{t\ge0}$ and $\{S_{\alpha}\left(t\right)\}_{t\ge0}$ are independent according their joint L\'evy measure given by Eq. \eqref{levymeasure3}.
 \end{enumerate}
 \begin{proof}
     To prove part 1 and 3, we consider the array of random vectors $\left\{n^{-1/\alpha}\mathbf{J}_i, \, n^{-1/\alpha}T_i\right\}_{i\in\mathbb{N}}$ and define two auxiliary sequences of wait-first LW and jump-first LW
     \begin{equation}
         U_{V,\,n}\left(t\right) = n^{-1/\alpha}\sum_{i=1}^{N_n\left(t\right)}\mathbf{J}_i, \quad O_{V,\,n}\left(t\right) = n^{-1/\alpha}\sum_{i=1}^{N_n\left(t\right)+1}\mathbf{J}_i,
     \end{equation}
     where 
     \begin{equation}
         N_n\left(t\right) = \max\left\{k\geq0:\, \sum_{i=1}^k n^{-1/\alpha}T_i\leq t\right\}.
     \end{equation}
    Since Lemma \ref{vectorconv} holds, by Theorem 3.6 from \cite{Straka2011}, the process $\{S_{\alpha}\left(t\right)\}_{t\ge0}$ has strictly increasing realizations for parts 1 and 3 holds
    \begin{equation}
        \begin{aligned}
             U_{V, n}\left(n^{1/\alpha}t\right) \overunderset{\mathbb{J}_1}{n \to \infty}{\to } \left(\mathbf{L}_{\alpha}^-\left(S_{\alpha}^{-1}\left(t\right)\right)\right)^+,\quad 
             O_{V, n}\left(n^{1/\alpha}t\right) \overunderset{\mathbb{J}_1}{n \to \infty}{\to } \mathbf{L}_{\alpha}\left(S_{\alpha}^{-1}\left(t\right)\right).
         \end{aligned}
    \end{equation}
    Finally, we observe, that 
    \begin{equation}
        N_n\left(t\right) = \max\left\{k\geq0:\, \sum_{i=1}^k n^{-1/\alpha}T_i\leq t\right\} = \max\left\{k\geq0:\, \sum_{i=1}^k T_i\leq n^{1/\alpha}t\right\} = N\left(n^{1/\alpha}t\right).
    \end{equation}
    Hence, $U_{V,\,n}\left(t\right) = n^{-1/\alpha}U_V\left(n^{-1/\alpha}t\right)$ and $O_ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 65 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Suppose that \cref{ncptas} is satisfied. 
  We regard $F$ and $F_n$ as subsets of a common $\bcm$ space $(M,d)$.
  Let $x\in F$ and $x_n\in F_n$. Take $r_{\infty}\ge r_0$ satisfying 
  $x\in B(\rho,r_{\infty})$ and $x_n\in B(\rho_n,r_{\infty})$.
  Then, for any $f\in\BL^{\kappa}(M),\kappa\in [1/2,1]$ and $t>0$
  \begin{align*}
    |P_{t}f(x)-P^n_tf(x_n)|
    \lesssim\|f\|_{\BL^{\kappa}}
    \inf\Bigl\{  \Psi_1(n,r)+C_n(r)\Psi_2(n,r)^E : r\in [r_{\infty},\infty), \Psi_2(n,r)\le \frac{1}{2}\Bigr\},
  \end{align*}
  where
  \begin{equation*}
    \Psi_1(n,r)=P_{x}^n(\sigma_{B(\rho,r)^c}\le t)\vee P_{x_n}^n(\sigma^n_{B(\rho_n,r)^c}\le t),
  \end{equation*}
  \begin{equation*}
    \Psi_2(n,r)=d_{\rm{H}}(F^{(r)},F_n^{(r)})^{\kappa}+d_{\BL^{\kappa}}(\mu^{(r)},\mu^{(r)}_n)+d(x,x_n),
  \end{equation*}
  \begin{equation*}
    \begin{aligned}
      C_n(r)=&(D_n^{(r)})^{4+2(1+\frac{s}{2(1+s)\theta})(2\kappa-1)}\\
    &\quad\times \left[(\diam K_n^{(r)}+\mu_n(F_n^{(r)}))\diam K_n^{(r)}\mu_n(F_n^{(r)})\mu(F^{(r)})^{3/2}\diam F^{(r)}(\mu(F^{(r)})^{1/2}+\mu_n(F_n^{(r)}))\right]\\
    \lesssim& r^{6+\frac{3}{2}s+2(1+\frac{s}{2(1+s)\theta})(2\kappa-1)}(r+\mu_n(F^{(r)}))(r^{s/2}+\mu_n(F^{(r)}))(r^s+\mu_n(F^{(r)}))^{4+2(1+\frac{s}{2(1+s)\theta})(2\kappa-1)},
    \end{aligned}
  \end{equation*}
  \begin{equation*}
    K_n^{(r)}=F^{(r)}\cup F_n^{(r)},\qquad D_n^{(r)}=\mu(F^{(r)})\diam F^{(r)}\vee \mu_n(F^{(r)}_n)\diam F^{(r)}_n,
  \end{equation*}
  and
  \begin{equation*}
    E=\frac{\kappa}{\kappa+(1+s)(2+\kappa)(\kappa+\theta)}.
  \end{equation*}
  Moreover, the time-dependence of the constant in $\lesssim$ is $t^{[\kappa-\frac{s}{2(1+s)\theta}(2\kappa-1)]},\;t\in (0,1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Df 3 of arXiv:2512.10199, 'Explicit correlation functions for the six-vertex model in the free-fermion regime'] A \emph{generalised snake configuration on $\midedge_n$} is a permutation $\orho:\midedge_n \to \midedge_n$ with the additional property that, for all $x \in \midedge_n$,
\begin{equation*}
    \orho(x) \in \begin{cases}
        \{x,x+ \tfrac{1}{2}(e^1 + e^2), x + e^1\} &\text{ if } x \text{ black,}\\
        \{x,x+ \tfrac{1}{2}(e^1 + e^2), x + e^2\} &\text{ if } x \text{ white.}
    \end{cases}
\end{equation*}
Let $\gen_n$ be the set of generalised snake configurations on $\midedge_n$.

A \emph{crossing} in a generalised snake configuration $\orho$ is a vertex $v \in \mathbb{T}_n$ for which
\begin{align*}
\orho(v - \tfrac{1}{2}e^1) = v+\tfrac{1}{2}e^1 \quad \text{and} \quad \orho(v - \tfrac{1}{2}e^2) = v+\tfrac{1}{2}e^2.
\end{align*}
A \emph{pure snake configuration} (which we will often denote by $\rho$) is a generalised snake configuration with no crossings. Denote $\pure_n$ to be the set of pure snake configurations on $\midedge_n$.

[Theorem of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] The  functional type law of large numbers holds for the multi-scale ensemble Kalman sampler model $((ex2:systema of the paper))$-$((ex2:systemb of the paper))$, i.e.,
	\begin{align*}
		\mathbb{E}\Big[\sup_{t\in [0, T]}|X_{t}^{\varepsilon}-\bar{X}_{t}|^{2}\Big]\lesssim_T (\varepsilon+\delta^{1/3}),
	\end{align*}
	where $\bar{X}_t$ is the solution of the corresponding averaged equation. Moreover,
	if $\delta = o(\varepsilon)$, then $\{X^{\varepsilon}\}_{\varepsilon\in (0,1)}$ satisfies the LDP.

