		\biggl(\sum_{q=m}^{p} c_q W_{q,\gamma}(t)\biggr)_{t\in[0,1]}   &\longrightarrow_{\mathcal{D}}   \left( t   \sum_{q=1}^{p} c_q  \,   \frac{H_q \left( Z \right)}{\sqrt{q!}} \right)_{t \in [0,1]} \hspace{1mm} \text{in } \; C[0,1]  \text{ as } \gamma \rightarrow 0.
	\end{align*}

