[Thm 42 of arXiv:2509.06869, 'Infinite Interacting Brownian Motions and EVI Gradient Flows'] Suppose \ref{ass:CE}, ~\ref{ass:ConditionalClos} and  Assumption~\ref{a:AP}.  Then

\begin{enumerate}[{\rm (a)}]
\item  $(${\bf  log-Harnack inequality}$)$ for every non-negative $u \in L^1(\U, \QP)$ and $t>0$, there exists $\Omega \subset \U$ with $\QP(\Omega)=1$ such that

\begin{align} 
T^{\U, \QP}_t\log u(\gamma) \le \log (T^{\U, \QP}_tu(\eta)) + \frac{{\mssd}_\U(\gamma, \eta)^2}{4I_{2K}(t)}\comma \quad \text{$\gamma, \eta \in \Omega$} \comma
\end{align}
where $I_K(t) :=\int_0^t e^{Kr}\diff r=\frac{e^{Kt}-1}{K}$. 

Furthermore, for every non-negative $u \in \mathcal B_b(\U)$ and $t>0$, 
\begin{align} 
T^{\U, \QP}_t\log u(\gamma) \le \log (T^{\U, \QP}_tu(\eta)) + \frac{{\mssd}_\U(\gamma, \eta)^2}{4I_{2K}(t)}\comma \quad \text{$\gamma, \eta \in \Theta$} \comma
\end{align}
where $\Theta$ was given in Assumption~\ref{a:AP};

\item    $(${\bf  dimension-free Harnack inequality}$)$ for every non-negative $u \in L^\infty(\U, \QP)$, $t>0$ and $\alpha>1$, there exists $\Omega \subset \U$ with $\QP(\Omega)=1$ such that 
$$(T^{\U, \QP}_tu)^\alpha(\gamma)\le T^{\U, \QP}_tu^\alpha(\eta) \exp\Bigl\{ \frac{\alpha}{4(\alpha-1)I_{2K}}{\mssd}_\U(\gamma, \eta)^2\Bigr\} \comma \quad \gamma, \eta \in \Omega \fstop$$
\end{enumerate}

