body:
[Proposition 20 (Power-law summability) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Assume that, for some $C_G>0$ and $\Gamma\in\R$,
\begin{equation}
 \mathcal G(N)\le C_G N^{-\Gamma}\qquad (N\in\Dyd).
\end{equation}
If
\begin{equation}
 \Gamma>\frac d2,\qquad
 \sigma>\max\{0,d-\Gamma\},\qquad
 \beta<\Gamma-d,
 \qquad
 \zeta<\Gamma-d,
\end{equation}
then one can choose $\eps>0$ so small that
\begin{equation}
 \mathfrak S_H^{(\eps)}(\beta,\sigma)
 +\mathfrak S_B^{(\eps)}(\zeta,\sigma)<\infty.
\end{equation}

[Cor 13 of arXiv:2608.20552, 'One-point fluctuations for exponential last passage percolation under upper-tail condition'] Let $n_1,n_2\in\N$ and $0\le i,j\le n_2$. Define\footnote{The superscript and subscript indicate whether the $1$- and $2$-blocks in the left and right lists, respectively, are ordered as $12$ or $21$.} 
\beqq
\begin{aligned}
	\J^{12}_{12}(a,b,n_1,n_2)&:=\J^{1^{n_1-a}(12)^a2^{n_2-a}}_{1^{n_1-b}(12)^b2^{n_2-b}},
	&\qquad
	\J^{12}_{21}(a,b,n_1,n_2)&:=\J^{1^{n_1-a}(12)^a2^{n_2-a}}_{2^{n_2-b}(12)^b1^{n_1-b}},\\
	\J^{21}_{12}(a,b,n_1,n_2)&:=\J^{2^{n_2-a}(12)^a1^{n_1-a}}_{1^{n_1-b}(12)^b2^{n_2-b}},
	&\qquad 
	\J^{21}_{21}(a,b,n_1,n_2)&:=\J^{2^{n_2-a}(12)^a1^{n_1-a}}_{2^{n_2-b}(12)^b1^{n_1-b}}.
\end{aligned}
\eeqq
Then
\beqq
	\left| \J^{2^{n_2-i}1^{n_1}2^i}_{2^{n_2-j}1^{n_1}2^j} \right| \le 2^{2(n_1+n_2)} S^{\alpha}_{\beta}
	\qquad
	\text{for each } \alpha,\beta \in\{12,21\},
\eeqq
where
\beqq
\begin{alignedat}{2}
	S^{12}_{12}
	&:=
	\sum_{a=0}^{n_1\wedge(n_2-i)}
	\sum_{b=0}^{n_1\wedge(n_2-j)}
	a!b!\,|\J^{12}_{12}(a,b,n_1,n_2)|,
	\qquad&
	S^{12}_{21}
	&:=
	\sum_{a=0}^{n_1\wedge(n_2-i)}
	\sum_{b=0}^{n_1\wedge j}
	a!b!\,|\J^{12}_{21}(a,b,n_1,n_2)|,\\
	S^{21}_{12}
	&:=
	\sum_{a=0}^{n_1\wedge i}
	\sum_{b=0}^{n_1\wedge(n_2-j)}
	a!b!\,|\J^{21}_{12}(a,b,n_1,n_2)|,
	\qquad&
	S^{21}_{21}
	&:=
	\sum_{a=0}^{n_1\wedge i}
	\sum_{b=0}^{n_1\wedge j}
	a!b!\,|\J^{21}_{21}(a,b,n_1,n_2)|.
\end{alignedat}
\eeqq

[Theorem thm:LIL of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] Let $\beta \in \mathcal{C}^2\big([0, \infty); \mathbb{R}\big)$ satisfy $t \dot{\beta}_t \to 0$ as $t \to \infty$.
  If 
  \begin{equation}

    \int_1^\infty \frac{\mathrm{d} r}{r \exp \beta_r} = \infty,
  \end{equation}
  then almost surely, for every nonempty open $U \subset S^{d-1}$, there exist sequences $t_n \nearrow \infty$ and $p_n \in \mathcal{P}_{t_n}$ such that for all $n \in \mathbb{N}$,
  \begin{equation}

    R_{t_n}(p_n) = 2t_n + \frac{d-2}{2} \log t_n + \beta_{t_n} \quad \text{and} \quad \Theta_{t_n}(p_n) \in U.
  \end{equation}
  If (equation eq:integral-condition of the paper) does not hold, then almost surely there exists $\tau > 0$ such that for all $t > \tau,$
  \begin{equation*}
    \max_{p \in \mathcal{P}_t} R_t(p) < 2t + \frac{d-2}{2} \log t + \beta_t.
  \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:maximal-scalar-mass-growth of arXiv:2608.30779, 'Some uniform estimates for K\"ahler--Ricci Shrinkers'] Suppose that \(k=n\).  Then the finite limit
\begin{equation}
 \Lambda_X:=\lim_{r\to\infty}r^{2-2n}
 \int_{B_g(p,r)}R_\omega\,\frac{\omega^n}{n!}
\end{equation}
exists. Moreover
if the shrinker is nonflat, then \(\Lambda_X>0\).

[Lemma lem-deterministic-representation of arXiv:2411.12623, 'Random signed measures'] Any $\mu\in\mathsf{M}_S$ has the following decomposition
	\begin{equation}
		\mu=\alpha_+-\alpha_-+\sum_{k\leq\kappa_+}\beta_{+,k}\delta_{\sigma_{+,k}}-\sum_{k\leq\kappa_-}\beta_{-,k}\delta_{\sigma_{-,k}}
	\end{equation}
	where $\alpha_+,\alpha_-\in\mathcal{M}_S$ and they are atomless, $\kappa_+,\kappa_-\in\mathbb{N}\cup\{0\}\cup\{\infty\}$, $\beta_{+,1},\beta_{-,1},\beta_{+,2},\beta_{-,2},...>0$, and distinct $\sigma_{+,1},\sigma_{-,1},\sigma_{+,2},\sigma_{-,2},...\in S$. Moreover, the Jordan decomposition of $\mu$ is given by the measures
	\begin{equation*}
		\mu_+=\alpha_+\sum_{k\leq\kappa_+}\beta_{+,k}\delta_{\sigma_{+,k}}\quad\text{and}\quad \mu_-=\alpha_-+\sum_{k\leq\kappa_-}\beta_{-,k}\delta_{\sigma_{-,k}}.
	\end{equation*}
	The representations for $\mu$, $\mu_+$, and $\mu_-$ are unique up to the order of terms, and we may choose $\alpha_+$, $\alpha_-$, $\kappa_+$, $\kappa_-$, and all $(\beta_{+,k},\sigma_{+,k})$ and  $(\beta_{-,k},\sigma_{-,k})$ to be measurable functions of $\mu$, $\mu_+$ and $\mu_-$. Conversely, any locally finite sum as in $((eq-measure of the paper))$, involving measurable functions $\alpha_+$, $\alpha_-$, $\kappa_+$, $\kappa_-$, $(\beta_{+,k},\sigma_{+,k})$, $(\beta_{-,k},\sigma_{-,k})$ as above, defined on some measurable space $(A,\mathcal{B})$, uniquely determine $\mu$, $\mu_+$, and $\mu_-$ as measurable functions on $A$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def_admissible of arXiv:2412.05709, 'Incipient infinite clusters and volume growth for Gaussian free fields and loop soups on m'] We say a family of events $\{\mathsf{A}_h\}_{h\ge 0}$ is admissible if there exist $k\in \mathbb{N}^+$, $\{a_1,...,a_k\}\subset (0,\infty)$, $\{v_1,...,v_k\}\subset   \widetilde{\mathbb{Z}}^d$ and disjoint subsets $\gamma_1,...,\gamma_l\subset \{v_1,...,v_k\}$ such that $\mathsf{A}_h=\mathsf{A}_h^{(\mathrm{i})}(v_1,...,v_k;a_1,...,a_k)\cap \mathsf{A}_h^{(\mathrm{ii})}(\gamma_1,...,\gamma_l)$ for all $h\ge 0$, where $\mathsf{A}_h^{(\mathrm{i})}(\cdot )$ and $\mathsf{A}_h^{(\mathrm{ii})}(\cdot)$ are defined as
\begin{equation}
	\mathsf{A}^{(\mathrm{i})}(v_1,...,v_k;a_1,...,a_k):=\cap_{1\le i\le k} \big\{ \widehat{\mathcal{L}}_{1/2}^{v_i}+ \widehat{\mathcal{I}}^{\frac{1}{2}h^2}_{v_i} \ge a_i\big\},
\end{equation}
\begin{equation}
	\begin{split}
		\mathsf{A}^{(\mathrm{ii})}(\gamma_1,...,\gamma_l ):= & \cap_{1\le j\le l}\cap_{v,v'\in \gamma_j}\big\{ v \xleftrightarrow{[h]} v'\big\}.
	\end{split}
\end{equation}

[Theorem 5 of arXiv:2606.28793, 'Randomized second order Riesz projections on the Hamming cube'] Let $a_1,\ldots,a_n>0$ and let $\Delta_a=\sum_{j=1}^n a_jD_j$.  Then $\Lambda_p(a)<\infty$ for every $1\leq p<\infty$, and for every Banach space $X$ and every $g:\Omega_n\to X$,
\begin{equation}

 \left(
 \E_{\eps,\delta}
 \left\|
 \sum_{j=1}^n\delta_j a_j\Delta_a^{-1}D_jg(\eps)
 \right\|_X^p
 \right)^{1/p}
 \leq
 \Lambda_p(a)\,\|g\|_{L^p(\Omega_n;X)}.
\end{equation}
Moreover, if $1\leq p\leq2$, then
\begin{equation}

 \Lambda_p(a)\leq\Lambda_2(a)
 =\int_0^\infty
 \left(\sum_{j=1}^n\frac{a_j^2}{e^{2a_jt}-1}\right)^{1/2}dt.
\end{equation}
In particular, if $a_1=\cdots=a_n$, then $\Lambda_2(a)=(\pi/2)\sqrt n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:SpectralComparison of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] There exists a constant $\tilde{C} > 0$ such that for all $r \in \mathbb{N}$ and $A \subseteq \mathrm{Centre}(C)$ with $r = R(2\ell)$ and $\ell = \left\lvertA\right\rvert \leqslant \delta \left\lvert\mathrm{Centre}(C)\right\rvert$ and $\delta \in (0, 1/2]$, we have
    \begin{equation}

        \sup_{f \colon \mathrm{Centre}(C) \rightarrow \mathbb{R},\, f\vert_{A^{\mathsf{c}}} = 0,\, f \neq 0} \frac{\langle (I-P^{\textup{aux}})f, f\rangle_{\pi_{\textup{aux}}}}{\langle (I-P^{\textup{res}})f, f\rangle_{\pi_{\textup{res}}}} \leqslant \tilde{C} r^2
    \end{equation}
    for all $n$ sufficiently large. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 15 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $0<\mu\le 1$ and $\beta>\frac{1}{2}$. For $u_0\in e^X(H^1(\IR^2)\cap L_\mu^2(\IR^2))$, consider the unique solution $u_\eps$ to the regularized equation associated to \eqref{Hartree}. Then there exists a unique function $u\in\CC(\IR,e^X(H^1(\IR^2)\cap L_\mu^2(\IR^2)))$ such that
\begin{equation}
\lim_{\eps\to0}\ \sup_{t\in[-T,T]}\|e^{-X_\eps}u_\eps(t)-e^{-X}u(t)\|_{H^1(\IR^2)\cap L_\mu^2(\IR^2)}=0
\end{equation}
for any $T>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Th:simulation_stable of arXiv:2412.06374, 'Stable and tempered stable distributions and processes: an overview toward trajectory simu'] Let $\alpha \in (0,2)$ and  $U,V$ be two independent random variables such that $U\sim \mathcal{U}\left([-\frac\pi2, \frac\pi2] \right)$ and $V\sim \mathcal{E}(1).$
Let $\theta = \alpha^{-1}\arctan\left(\beta \tan\left(\frac{\pi\alpha}{2} \right) \right)$ for  $\beta \in [-1,1]$  and $\alpha \neq 1$ then
 \begin{align}
     X \sim \begin{cases}
\frac{\sin(\alpha(\theta + U))}{\left(\cos(\alpha \theta)\cos(U)\right)^{1/\alpha}} \left(\frac{\cos(\alpha \theta + (\alpha-1)U)}{V}\right)^{(1-\alpha)/\alpha} & \text{ if } \alpha \neq 1, \\
  \frac{2}{\pi} \left[\left( \frac{\pi}{2} + \beta U\right)\tan(U) - \beta \log\left( \frac{\frac{\pi}{2}V\cos(U)}{\frac{\pi}{2}+ \beta U} \right) \right]       & \text { if } \alpha=1,
     \end{cases}
 \end{align}
 is distributed as $S_\alpha (1,\beta, 0).$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[The 25 (Alexandrov's theorem) of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let $\phi\in\text{\rm SCL}\,(\T^n)$. Then we have
\begin{align*}
	\mathscr{L}(\text{\rm Alex}\,(\phi))=\mathscr{L}(\T^n).
\end{align*}

[Theorem 10 of arXiv:2607.28004, 'Folding representations of reflected diffusions'] Consider measurable functions $b:D \to \R^d$ and $\sigma:D \to \R^{d \times d}$, such that $\sigma$ satisfies the assumptions of Lemma~\ref{lem:ODE_cube}. Furthermore, let constants $\nu^{ii}$ be given by \eqref{eq:nus_cube}, construct the diagonal matrix $\nu$ of these elements, and suppose that the function $\xi$ defined in \eqref{eq:xi} is bounded. Then,
\begin{enumerate}[label = (\roman*),noitemsep]
    \item  the function $f:D \to D$ given by equation \eqref{eq:f_quadrant} with flow maps satisfying \eqref{eq:flows_cube} is well-defined, belongs to $W^{2,\infty}(D)$, has $D$ as its range, and is the unique solution to the PDE \eqref{eq:nonlinear_PDE_cube} satisfying the boundary condition \eqref{eq:f_boundary_cube};
    \item with 
    \begin{equation} 
    \alpha(x) = \nu\sign(\overline x)\, \xi\big(f(|\overline x|)\big), \qquad \text{for a.e. } x \in \R^d,
    \end{equation}
    and $\overline x = x - \Even(x)$, 
     the SDE \eqref{eq:X_SDE_nu} has a pathwise unique, strong solution $X$ for every initial value $X_0 \in \R^d$;
    \item the process $Y = f(|X-\Even(X)|)$ satisfies the RSDE \eqref{eq:RSDE} on $D$ with initial condition $Y_0 = f(|X_0-\Even(X_0)|)$, normally reflecting processes
    \begin{equation}

\begin{aligned} 
\Phi_t^i  = &  \frac{1}{\nu^{ii}}\sum_{n \in \Z} \int_0^t \sigma^{ii}\Big(f\big(|X_s - \Even(X_s)|\odot ({\bf 1}_d - e_i)\big)\Big)dL_s^{2n}(X^i) \\
&  - \frac{1}{\nu^{ii}}\sum_{n \in \Z} \int_0^t \sigma^{ii}\Big(f\big(|X_s - \Even(X_s)|\odot ({\bf 1}_d - e_i)+e_i\big)\Big)dL_s^{2n+1}(X^i), 
    \end{aligned}
\end{equation}
for $i=1,\dots,d$,  $ t \geq 0$, 
    and Brownian Motion $W = \int_0^\cdot\sign(X_t-\Even(X_t))dB_t$. 
    \end{enumerate}

[Proposition 13 of arXiv:2608.12947, 'Branch-stationary max-stable fields on rooted trees'] Let \(Z\) be an \(\alpha\)-spectral representer satisfying
(equation 2 of the paper), and let \(\eta\) be given by
(equation 3 of the paper). The following statements are
equivalent:
\begin{enumerate}[(i)]
\item \(\eta\) is branch-stationary;
\item \(B^aZ\sim_\alpha Z\) for every \(a\in\mathcal T\);
\item the punctured tail measure is branch-invariant, i.e.,
\begin{equation}
  \nu_Z^\circ\bigl((B^a)^{-1}A\bigr)
  =
  \nu_Z^\circ(A),
  \qquad
  A\in\mathcal B(\mathcal F^\circ),\quad a\in\mathcal T,

\end{equation}
where
\[
  (B^a)^{-1}A
  =
  \{f\in\mathcal F^\circ:B^af\in A\};
\]
\item the local spectral tail fields satisfy
\begin{equation}
  B^a\Theta^{[au]}\stackrel{\mathrm d}{=}\Theta^{[u]},
  \qquad a,u\in\mathcal T;

\end{equation}
\item for every \(a,u\in\mathcal T\) and every \(F\in\mathfrak H_0\),
\begin{equation}
  \E*{
    Z_{au}^{\alpha}F(B^aZ)
  }
  =
  \E*{
    Z_u^{\alpha}F(Z)
  }.

\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 27 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $\widetilde{m}$ be  an order function satisfying \eqref{Hypothèse fonction d'ordre Mildred} with $\alpha$ replaced by $t$. Let $\psi\in \mathscr{C}^\infty_c(\R)$ and consider $0<h^{1-2\eta}\ll\alpha\leq t\leq \beta$ with notations \eqref{Scaling en fonction de t}, \eqref{Scaling de q atchek en fonction de t}, \eqref{Scaling de q_0 atchek en fonction de t} and \eqref{Fonction d'ordre théorème central - version en t}. Then, under the assumptions of Theorem \ref{Théorème central}, for $a\in \{0,1\}$ the following decomposition holds:
        \begin{equation}
        \mathrm{tr}\pr{\frac{1}{t^a}\psi\pr{\frac{\atc{q}_{N,t_1,t_2}}{t}}}=N^d\Bigl(I^a_t+II^a_t+III^a_t+IV^a_t\Bigl)

    \end{equation}
    where for $k\geq 1$,
    \begin{equation}
        \begin{split}
            I^a_t &:=\frac{(h^\eta t)^d}{t^a}\int_{\mc{T}_{t_1,t_2}}\psi\pr{\frac{\atc{q}_0(\widetilde{\rho})}{t}}d\widetilde{\rho}\\
            II^a_t &:=\mc{O}_M(1)\frac{(h^\eta t)^d}{t^a}\Tilde{h}\int_{\mc{T}_{t_1,t_2}}\widetilde{\chi}\pr{\frac{\atc{q}_0(\widetilde{\rho})}{t}}d\widetilde{\rho}\\
            III^a_t &:= \mc{O}_M(1)\frac{(h^\eta t)^d}{t^a}\Tilde{h}^M\int_{\mc{T}_{t_1,t_2}}\widetilde{m}(\widetilde{\rho})d\widetilde{\rho}\\
            IV^a_t &:= \mc{O}_k(1)\frac{(h^\eta t)^d}{t^a}\pr{Nh^\eta t^{1/2}}^{-k}\int_{\mc{T}_{t_1,t_2}}\widetilde{m}(\widetilde{\rho})d\widetilde{\rho}.
        \end{split}

    \end{equation}
    and where $\widetilde{\chi}\in \mathscr{C}^{\infty}_c(\R;[0,1])$ is such that $\widetilde{\chi}\equiv 1$ on a neighborhood of $[0,\sup\mathrm{supp}(\psi)]$.

