[Lemma 12 of arXiv:2608.15616, '\textbf{Compact Support Property of Super-Brownian Motion with Irregular Drift}'] Let $r >0$, $m >0$, and 
		\begin{equation}
			\psi^{m,r}(x) =
			\begin{cases}
				0, & |x| \leq r, \\
				m(|x|/r - 1), & r \leq |x| \leq 2r, \\
				m, & 2r \leq |x|.
			\end{cases}
		\end{equation}
		Then there exists a unique mild nonnegative solution $u^m$ to 
		\begin{equation}
			 \frac{1}{2}\Delta u^m(x) -\frac{1}{2}(u^m(x))^2 + \psi^{m,r}(x ) = 0, \quad x \in \R. 
		\end{equation}
		Furthermore, $u^m(x)$ is monotonically increasing in $m$ for all $x\in R$ and there exists a constant $\constFromEq{c}{eq:est_u_infty}>0$ such that for $|x| < r$ we have
		\begin{equation}
			\lim_{m \rightarrow \infty} u^m(x) \leq \constFromEq{c}{eq:est_u_infty}(r-|x|)^{-2}.
		\end{equation}
    Furthermore, the monotone pointwise limit $u$ of $u^m$ is the unique, nonnegative solution to
    \begin{equation}
        \begin{cases}
            \Delta u(x) = \big( u(x) \big)^2, \quad x\in (-r,r), \\
            u(x) \rightarrow \infty, \text{ as } x\rightarrow r \text{ or } x\rightarrow -r.

        \end{cases}
    \end{equation}

[Theorem 17 (Lamperti reduction) of arXiv:2608.17927, 'Near-unit-root persistence of symmetric stable \\ autoregressive sequences'] For every $h > 0$, the sequence $(R_{jh})_{j \geq 0}$ is the stationary symmetric stable AR($1$) chain
\begin{equation}

R_{(j+1)h} = e^{-h/\alpha}R_{jh}+\zeta_{j},
\end{equation}
where the innovations are independent symmetric $\alpha$-stable variables with scale $(1-e^{-h})^{1/\alpha}$. Setting $h = \alpha\log{(1/a)}$ yields
\begin{equation}

\Lambda(a,\alpha) = \lambda_{\alpha}(h)
\end{equation}
and
\begin{equation}

0 < \frac{G_{\alpha}^{*}}{\alpha} = \lim_{h \downarrow 0}\frac{\lambda_{\alpha}(h)}{h} = \sup_{h > 0}\frac{\lambda_{\alpha}(h)}{h} \leq \frac{1}{2}.
\end{equation}

