\begin{equation}
\matrc_\mathsf{K}(a\cup a',b\cup b')\,\matrc_\mathsf{K}(a\cap a',b \cap b')\geq \matrc_\mathsf{K}(a,b)\,\matrc_\mathsf{K}(a',b').
\end{equation}

