[Thm 15 of arXiv:2609.03061, '2609.03061'] For $f: [a,b] \rightarrow Sp(2n,\mathbb{R})$ smooth and decomposition as above,
$f(t) = K(\Pi(f(t))) \cdot e^{A(t)}$
$$ \begin{array}{l}
  Trace( J \ f(t)' \cdot f(t)^{-1}) =  Trace(  J \ K(U(f(t)))' \cdot K(U(f(t)))^{-1})\\ \hspace{1in}
  +  Trace( J \ A(t)' A(t)^{-1} \ (1/2) \ (Id[2n] - e^{-2A(t)}))
\end{array} $$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem le:limit_theorem_L2 of arXiv:2506.17168, '{\bf Scaling limits for sample autocovariance operators of Hilbert space-valued linear pro'] Let $\{X_{n}\}_{n \in \mathbb Z}$ be an $L^2(\mathbb{Y})$-valued linear process (equation eq:XninL2 of the paper) and consider its autocovariance operators $(\widehat \gamma_{N,h}, h = 0,\dots,H)$ given in (equation eq:gammars of the paper). Suppose $ d(s) \in \left(\frac{1}{4},\frac{1}{2}\right)$, 
\begin{equation} 
  \operatorname{E} \| \varepsilon_{0} \|^4_{L^4(\mathbb{Y})} < \infty. 
\end{equation}
and
\begin{equation} 
\int_{\mathbb{Y}} \frac{\sigma^2(r)}{(1-2d(r))(2d(r)-1/2)}	\mu(dr)  < \infty.
\end{equation}
Then, 
\begin{equation*}
\Xi_N \begin{pmatrix}
    \widehat{\gamma}_{N,0}-\gamma_{0} \\
    \vdots 
    \\
    \widehat{\gamma}_{N,H}-\gamma_{H}
\end{pmatrix} 
\overset{\operatorname{d}}{\to}
\begin{pmatrix}
    \mathfrak{R} \\
    \vdots \\
     \mathfrak{R}
\end{pmatrix}
 \in L^2(\mathbb{Y}^2:\mathbb R^{(H+1)}),
\end{equation*}
where $\mathfrak{R}$ is given in (equation equality_f^(u,l)_t,(m,s) of the paper) below and $\Xi_N$ in (equation eq:Xi-def of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $3\le d\le 5$ and $\epsilon>0$, there exist $\Cl(d,\epsilon),\cl(d,\epsilon)>0$ such that for any $n\ge \Cref{const_lemma_separation1}$, $N\ge \Cref{const_lemma_separation1}n$, $\psi\in \Psi(n,N)$, $\diamond\in \{\mathrm{in},\mathrm{out}\}$, $i\in \{ 1,2\}$, and any line segment $\widetilde{\eta}\subset \mathfrak{B}_{m_{\diamond},100}^{\diamond}$ satisfying $\mathrm{vol}(\widetilde{\eta})\le 100m_\diamond$ and $\mathrm{dist}(z_i^{\diamond},\widetilde{\eta})\ge \frac{m_\diamond}{100}$, 
	 \begin{equation}
	 	\mathbb{P}\big( \mathsf{R}_i^{\diamond}[\psi, \cref{const_lemma_separation2}, \widetilde{\eta}] \mid    \mathsf{C}[\psi] \big) \le \tfrac{1}{4} \epsilon. 
	 \end{equation}
	Particularly, by taking $\widetilde{\eta}=\{z_{3-i}^\diamond\}$, this implies 
\begin{equation}
		\mathbb{P}\big( \mathsf{S}[\psi,\cref{const_lemma_separation2}] \mid    \mathsf{C}[\psi] \big)\le   \epsilon.
	\end{equation}
	Consequently, there exists $\cl>0$ such that 
	\begin{equation}
		\mathbb{P}\big(     \widehat{\mathsf{C}}[\psi, \cref{const_lemma_separation3}] \big)\asymp  \mathbb{P}\big(  \mathsf{C}[\psi] \big), \ \forall \psi\in \Psi(n,N). 
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:string-plaquette-operation of arXiv:2505.16585, 'Expanded regimes of area law for lattice Yang--Mills theories'] Let $s \in \mc{S}_{\Lambda}$ be non-null and $K: \mc{P}_{\Lambda}^{+} \backslash P \to \N$ be a plaquette count supported on good plaquettes. We make the following definitions.
\begin{enumerate}
    \item If $s$ contains a good edge $\mbf{e}$, then $(s',K')$ is a positive merger of $(s,K)$ at $\mbf{e}$ if $s' \in \mbb{M}_+(s,\mbf{e})$ and $K'=K$. The set of all positive mergers of $(s,K)$ at $\mbf{e}$ is denoted by $\mbb{M}_+((s,K),\mbf{e})$.
    \item The sets $\mbb{M}_-((s,K),\mbf{e})$, $\mbb{S}_+((s,K),\mbf{e})$, and $\mbb{S}_-((s,K),\mbf{e})$ may be similarly defined.
    \item If $s$ contains a good edge $\mbf{e}$, we say that $(s',K')$ is a positive (resp. negative) deformation of $(s,K)$ at $\mbf{e}$, if we can express $s'=s \oplus_{\mbf{e}} p$  (resp. $s'=s \ominus_{\mbf{e}} p$) for some plaquette $p$, and moreover $K'$ 
    is given by (here $|p|$ denotes the positively oriented version of $p$, which may be $p$ itself if it is already positively oriented)
    \begin{equs}
    K'(q) = \begin{cases}
        K(q) & q \in \mc{P}_\Lambda^+ \backslash \{|p|\}, \\
        K(p) - 1 & q  = |p|.
        \end{cases}
    \end{equs}
    The set of all such $(s',K')$ is denoted $\mbb{D}_+((s,K),\mbf{e})$ (resp. $\mbb{D}_-((s,K),\mbf{e})$). 
    \item We say that $(s',K')$ is a revival of $(s,K)$ with revival set $R$ if $s' \in \mc{R}(s,R)$, $K'(p)=K(p)$ for $p \in \mc{P}_{\Lambda}^+ \backslash R$, $K'(p)=0$ for all $p \in R$, and the plaquette count $J : o(R) \ra \N$ such that $s' = s \Delta_R J$ satisfies $J(p) + J(p^{-1}) \leq K(p)$ for all $p \in \mc{P}_\Lambda^+$. In this case, we write $(s', K') = (s, K) \Delta_R J$. The set of all revivals of $(s,K)$ with revival set $R$ is denoted $\mc{R}((s,K),R)$.
\end{enumerate}

[Lem abel of arXiv:2510.26123, 'Directed distances in bipolar-oriented triangulations:\\ exact exponents and scaling limit'] For every $t>0$,
\begin{equation}
\sum_{k\ge0} f(k)\sin(tk)
= \sum_{k\ge0} S(k+1)\big(\sin((k+1)t)-\sin(kt)\big).
\end{equation}
Equivalently,
\begin{equation}
\sum_{k\ge0} f(k)\sin(tk)
= \int_{0}^{\infty} S\big(\lfloor u/t\rfloor+1\big)\cos u\,du .
\end{equation}

[Thm hyc of arXiv:2507.02518, '{\bf Exponential Ergodicity in Relative Entropy and $L^2$-Wasserstein Distance for non-equ'] Assume  {\bf(B)} and $\sigma\sigma^\ast$ is invertible. Then (equation Degth1 of the paper) has a unique invariant probability measure $\bar{\mu}\in\mathscr P_2(\mathbb R^{2d})$ and there exists a constant $t_1>0$ such that $P_{t_1}^\ast $, the adjoint operator of $P_{t_1}$ in $L^2(\bar{\mu})$, is hypercontractive, in the sense that
\begin{align}
\|P_{t_1}^\ast\|_{L^{\frac{4}{3}}(\bar{\mu})\rightarrow L^{2}(\bar{\mu})}= 1.
\end{align}
Consequently, there exist constants $c,\tilde c,\lambda>0$ such that
\begin{align} \mathrm{Ent}(\mathscr L_{(X_t^{\mu_0},Y_t^{\mu_0})}|\bar{\mu})\leq c\text{\rm{e}}^{-2\lambda t}\mathrm{Ent}(\mu_0|\bar{\mu}),~ t\geq 0, \mu_0\in\mathscr P(\mathbb R^{2d}),
\end{align}
and
\begin{align}\mathbb W_2(\mathscr L_{(X_t^{\mu_0},Y_t^{\mu_0})},\bar{\mu})\leq \tilde c\text{\rm{e}}^{-\lambda t}\mathbb W_2(\mu_0,\bar{\mu}),\ \ t\geq 0, \mu_0\in\mathscr P_2(\mathbb R^{2d}).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 (Harris--FKG--Inequality) of arXiv:2504.02435, 'Poisson-Voronoi percolation in higher rank'] In the above setting, $\omega_p^{(\lambda)}$ satisfies the Harris-FKG-Inequality, i.e.~
    \begin{equation*}
        \mathbb P_p^{(\lambda)} (A_1 \cap A_2) \geq \mathbb P_p^{(\lambda)} (A_1) \mathbb P_p^{(\lambda)} (A_2)
    \end{equation*}
    for every increasing events $A_1$ and $A_2$.

[Definition 9 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $(p,\alpha)\in(1,\infty)\times(0,1)$ with $p\alpha<1$. We define $C^{\alpha,p}_o([0,T],G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^k))$ as the set of continuous paths $\mathbf{x}:[0,T]\rightarrow G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^k)$ such that $\mathbf{x}_0=(1,0,\dots,0)$ and
    \begin{equation*}
        \begin{aligned}
            &\lVert \mathbf{x} \rVert_{\textup{hom $p$-var};[0,T]} + \lVert \mathbf{x} \rVert_{\textup{hom $\alpha$-H\"{o}l};[0,T]} < \infty\\(\textit{equiv.}\; &\lVert \mathbf{x} \rVert_{\textup{inhom $p$-var}} + \lVert \mathbf{x} \rVert_{\textup{inhom $\alpha$-H\"{o}l};[0,T]} < \infty).
        \end{aligned}
    \end{equation*}
    Moreover, we define
    \begin{equation*}
        \begin{aligned}
            &\widehat{C}^{\alpha,p}_o=\widehat{C}^{\alpha,p}_o([0,T],G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^{k+1})) :=\\
            &:= \Big\{\widehat{\mathbf{x}}\in C_o^{\alpha,p}([0,T],G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^{k+1})) \,:\, \widehat{\mathbf{x}}^{(1)}=\left(t,\mathbf{x}^{(1)}\right)\;\forall\,t\in[0,T],\,\mathbf{x}\in C^{\alpha,p}_o([0,T],G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^k))\Big\}.
        \end{aligned}
    \end{equation*}

[Lemma lem:moment-bound:H^0_epsilon of arXiv:2411.02459, 'Existence and higher regularity of statistically steady states for the stochastic Coleman-'] Assume the hypotheses of~Theorem (thm:well-posed of the paper) and let $U_0=(u_0,\eta_0)\in \mathcal{H}^0_\mu$. Then

\begin{enumerate}[noitemsep,topsep=0pt,wide=0pt,label=\arabic*.,ref=\theassumption.\arabic*]
\item For all $\beta$ sufficiently small independent of $\mu\in\mathcal{M}_\delta$,
\begin{equation}
\mathbb{E} \exp\left({\beta\Psi_0(U(t))}\right)\le e^{-c_0t}\exp\left({\beta\Psi_0(U_0)}\right)+C_0,\quad t\ge 0,
\end{equation}
where $\Psi_0$ is as in (equation form:Psi_0 of the paper) and $c_0=c_0(\beta)>0$, $C_0=C_0(\beta)>0$ do not depend on $U_0\in\mathcal{H}^0_\mu$, $t\ge 0$ and $\mu\in\mathcal{M}_\delta$.

\item For all $n\ge 1$, there exist positive constants $c_{0,n},\tilde{c}_{0,n}$ and $C_{0,n}$ independent of $U_0\in\mathcal{H}^0_\mu$, $t\ge 0$ and $\mu\in\mathcal{M}_\delta$ such that
\begin{equation}  
\emph{d} \Psi_0(U(t))^n\le -c_{0,n} \Psi_0(U(t))^n\emph{d} t+\tilde{c}_{0,n}\emph{d} t+\emph{d} M_{0,n}(t),
\end{equation}
where $M_{0,n}(t)$ is the semi-martingale given by
\begin{equation} 
M_{0,n}(t)=\int_0^t n\Psi_0(U(r))^{n-1}\langle u(t),Q\emph{d} w(r)\rangle_H.
\end{equation}
Furthermore,
\begin{equation} 
\mathbb{E}\Psi_0(U(t))^n \le e^{-c_{0,n}t}\Psi_0(U_0)^n+C_{0,n},\quad t\ge 0.
\end{equation}
\end{enumerate}

