[Theorem scaling limit of arXiv:2605.28194, 'Delayed Blow-up in 3D Fluids via Pseudo-Transport Noise'] Let $\omega^N$ be the solution to (equation scalar eqn of the paper) with $\sigma_k=\sigma_k^N$, we have the following:
		\begin{itemize}
			\item[(1).] Deterministic initial condition: If $\omega_0\in H^{2b+a}$, then $\omega^N$ converges in law, in $C([0,T];\mathcal{S}')$, to the solution of the (fractional) heat equation:
			\begin{equation*}
				\left\{
				\begin{aligned}
					& \partial_t \omega =-\nu(-\Delta)^{1+a}\omega,\\
					& \omega(0)=\omega_0.
				\end{aligned}
				\right.
			\end{equation*}
			\item[(2).] Random initial condition: If Law ($\omega_0$)= $(-\Delta)^{-\frac{a}{2}-b}\mu$, then $\omega^N$ converges in law, in $C([0,T];\mathcal{S}')$, to the stationary infinite dimensional Ornstein-Uhlenbeck process:
			\begin{equation}
				\left\{
				\begin{aligned}
					& {\,\rm d} \omega =-\nu(-\Delta)^{1+a}\omega + \sqrt{2\nu}(-\Delta)^{1/2-b}{\,\rm d} W,\\
					& \omega(0)=\omega_0,
				\end{aligned}
				\right.
			\end{equation}
			where ${\,\rm d} W$ is the space-time white noise.
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma adhoclem of arXiv:2608.09856, '\bf Mass erasure on measured $\bbR$-trees,\\ applications to L\'evy forests'] Let $E$ be Polish and let ${\boldsymbol{\Lambda}}\! : \! \Omega \! \to \! \mathcal{M}_f(E)$ be a random finite measure. Let $f_i \! : \! E\! \to \! \mathbb{R}_+$, $i\! \in \!  \{ 1, 2\}$, be Borel-measurable. We denote by ${\boldsymbol{\Lambda}} \circ f_i^{-1}$ the random finite measure on $\mathbb{R}_+$ that is the push-forward measure of ${\boldsymbol{\Lambda}}$ via $f_i$. We assume the following. 
\begin{compactenum}

\smallskip

\item[$(a)$] ${\bf P}$-a.s.~${\boldsymbol{\Lambda}} \big( \{ x\! \in \!  E: f_2(x) \! < \!  f_1(x) \}\big)\! = \!  0$.

\smallskip

\item[$(b)$] Under ${\bf P}$ the two $\mathcal{M}_f(\mathbb{R}_+) $-valued r.v.s ${\boldsymbol{\Lambda}} \circ f_1^{-1}$ and ${\boldsymbol{\Lambda}} \circ f_2^{-1}$ have the same law. 

\smallskip

\end{compactenum}
{\noindent}
Then ${\bf P}$-a.s.~${\boldsymbol{\Lambda}} \big( \{ x\! \in \!  E: f_2(x) \! \neq \!  f_1(x) \}\big)\! = \!  0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Le23 of arXiv:2411.09949, '$W_{\bf d}$-convergence rate of EM schemes for invariant measures of supercritical stable '] Under $(\mathbf{H}^1)$ and (equation mon of the paper), there is a constant $C=C(\Theta)>0$ such that
for any Lipschitz function $g$ and $f=\int^\infty_0 P_t\bar g{\mathord{{\rm d}}} t$ with $\bar g:=g-\mu(g)$,
\begin{align}
\|\nabla f\|_\infty+\|\nabla^2 f\|_\infty+\|{\mathscr L}^{(\alpha)}_\sigma f\|_{{\mathbf C}^{2-\alpha}}
\lesssim_C\|\nabla g\|_\infty.
\end{align}
Moreover,  for all $x_1,x_2\in{\mathbb R}^d$,
\begin{align}
\|{\mathscr L}^{(\alpha)}_{\sigma(x_1)} f-{\mathscr L}^{(\alpha)}_{\sigma(x_2)} f\|_\infty
\lesssim_C\|\nabla g\|_\infty|x_1-x_2|.
\end{align}

