[Proposition 6 of arXiv:2605.20041, '\makeatletter \HRule \\[0.4cm] { \huge \bfseries Fourier Representations of Spectral Densi'] The two following assertions are equivalent:
\vspace{-\parskip}
\begin{enumerate}[label=(\roman*)]
\item Condition \ref{condition:longMemoryAutocovariances} is satisfied with $L_{1}$ quasi-monotone,
\item Condition \ref{condition:longMemorySpectralDensity} is satisfied with $L_{2}$ quasi-monotone.
\end{enumerate}
\vspace{-\parskip}
In addition, if one of these assertions is satisfied, the spectral measure of $(X_{t})_{t \in \mathbb{Z}}$ is absolutely continuous, and the Fourier series of its spectral density converges everywhere on $(0,\pi]$ and diverges to $+\infty$ at 0. Moreover, Condition \ref{condition:longMemorySpectralDensity} holds with $f$ the sum of the Fourier series of the spectral density, and we have $$L_{2}(x) \underset{x \to 0}{\sim} L_{1}\hspace{-1.6pt}\left(\frac{1}{x}\right)\frac{1}{\pi}\Gamma(2d)\cos(d\pi),\,\text{and}~L_{1}(x) \underset{x \to +\infty}{\sim} L_{2}\hspace{-1.6pt}\left(\frac{1}{x}\right)2\Gamma(1-2d)\sin(d\pi).$$

[Lemma random-walk of arXiv:2505.04942, '\textbf{Randomized Routing to Remote Queues}'] Assume condition~(equation eq:rmk-inequality of the paper) holds. Then with probability 1,
	\begin{equation}
		\limsup_{n \to \infty} \frac{\sup_{1\leq j \leq n^{\alpha}T}G^{m}_{k}(j)}{\sqrt{n^{\alpha}\log\log n}} = - \liminf_{n \to \infty} \frac{\inf_{1\leq j \leq n^{\alpha}T}G^{m}_{k}(j)}{\sqrt{n^{\alpha}\log\log n}} = \sqrt{2 T p_{m}r_{m,k}(1 - p_{m}r_{m,k})}
	\end{equation}
	for $ \alpha > 0 $, $ T > 0 $, $ m = 1, \ldots, b $, and $ k = 1, \ldots, s $. Moreover, there exists a positive number $ C^{m}_{k,T} $ and a standard Brownian motion $ \check{B}^{m}_{k} $ such that with probability 1,
	\begin{equation}
		\limsup_{n \to \infty} \frac{1}{\log n} \sup_{1 \leq j \leq nT} | G^{m}_{k}(j) - \sqrt{p_{m}r_{m,k}(1 - p_{m}r_{m,k})}\check{B}^{m}_{k}(j)| \leq C^{m}_{k,T}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm: convergence of the partition function of the pinning model of arXiv:2602.04429, 'Disordered systems and (subcritical) polynomial chaos\\ with heavy-tail disorder'] {}
	Let the renewal process $\tau$ satisfy (equation def: inter-arrival law of the paper) and assume that $1-\alpha <\frac1\gamma$. Note in particular that this guarantees that \(u(N)V_N \to \infty\) as \(N\to\infty\).
	Assume also the following scaling for the parameters \(\beta_N,h_N\): 
	\begin{equation}

		\lim_{N\to\infty} \beta_N \, u(N) V_N = \hat{\beta}  \in (0,+\infty)\,, \qquad  \lim_{N\to\infty} h_N \, u(N) N = \hat{h} \in {\ensuremath{\mathbb R}}  \,.
	\end{equation}
	Then we have the following convergence in distribution:
	\begin{equation}{}
	Z_{N,h_N}^{\omega,\beta_N} \xrightarrow[\ N\to\infty \ ]{(d)}{\ensuremath{\mathcal Z}}_{\hat{h}}^{\boldsymbol\zeta,\hat{\beta}} = 1 + \sum\limits_{k \, \geqslant\, 1} \frac{\hat{\beta}^k}{k!} \int_{(0,1)^k} \boldsymbol\psi_{\hat{h}}^{(k)}(t_1,\dots,t_k) \prod\limits_{j=1}^k \boldsymbol\zeta(\mathrm{d} t_j),
	\end{equation}
	where $\boldsymbol\zeta$ is a $\gamma$-stable noise on $(0,1)$ and for every $k \, \geqslant\, 1$, and $\boldsymbol\psi_{\hat{h}}^{(k)}$ is defined in (equation eq: continuum correlation functions of the pinning model of the paper). 
	This convergence holds jointly with the convergence of the discrete noise to $\boldsymbol\zeta$.  
	Furthermore, for every $p \in [1,\gamma)$, ${\ensuremath{\mathcal Z}}_{\hat{h}}^{\boldsymbol\zeta,\hat{\beta}}$ has a finite moment of order~$p$, and 
	$\lim_{N \to +\infty} \mathds{E}[(Z_{N,h_N}^{\omega,\beta_N})^p] = \mathds{E}[({\ensuremath{\mathcal Z}}_{\hat{h}}^{\boldsymbol\zeta,\hat{\beta}})^p]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 41 of arXiv:2609.01826, 'An extension theory for fully fractional Schr\"odinger equations with memory'] Let $A\in \R\setminus\{0\}$ and $0<s<1$. Then
 \begin{equation}
 -\frac{s}{\G(1-s)} \int_0^\infty \frac{1}{\sigma^{1+s}} [e^{-i \sigma A} - 1] d\sigma = (i A)^s = |A|^s e^{i\frac{\pi s}{2} \operatorname{sgn}A}.
 \end{equation}

