[Lemma 6 of arXiv:2609.02779, '2609.02779'] Recall that $\A_i=\pi_M(\Gamma_i)$, and let $I_*:=\{i\in\{1,\dots,N\}:m_i=0\}$.
Then $I_*\neq\emptyset$.  Moreover, for every $x\in M$ there exists
$i\in I_*$ such that, for every $a\in \A_i$,
\begin{equation}
 u_0(x)=u_0(a)+h(a,x).
\end{equation}

[Theorem 1 of arXiv:2605.30091, 'Computing lower expectations with respect to total variation distance and chi-squared dive'] Let $r$ be defined as above. Then
\begin{equation*}
    \underline{E}^\mathrm{TV}_{p,\delta}(f)
    =
    E_{q_\mathrm{TV}}(f)
\end{equation*}
where, if $r>1$, $q_\mathrm{TV}\in\Sigma_\mathcal{X}$ is given by
\begin{equation*}
    q_\mathrm{TV}(x_i):=
    \begin{cases}
        p(x_1)+\delta & \text{if } i=1,\\
        p(x_i) & \text{if } i\in\{2,\ldots,r-1\},\\
        \sum_{i=r}^{n} p(x_i)-\delta & \text{if } i=r,\\
        0 & \text{if } i\in\{r+1,\ldots,n\}.
    \end{cases}
\end{equation*}
and, if $r=1$, $q_\mathrm{TV}\in\Sigma_\mathcal{X}$ is given by
\begin{equation*}
    q_\mathrm{TV}(x_i):=
    \begin{cases}
        1 & \text{if } i=1,\\
        0 & \text{if } i\in\{2,\ldots,n\}.
    \end{cases}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 7 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] For all sufficiently small $\eps>0$, $\omega_\eps$ extends to a smooth K\"ahler metric on $\widetilde X$, and
\begin{equation}
  [\omega_\eps]=\pi^*[\omega]-\eps^2[E].
\end{equation}

[Lemma 69 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same notation as in Definition \ref{Def.ScalingBulk}, where $\mathcal{T} \subset (0,\infty)$. For each $j \in \llbracket 1, m \rrbracket$, we have
\begin{equation}\begin{split}
    & \lim_{a \rightarrow \infty} \limsup_{N \rightarrow \infty} \mathbb{P}(X^{j,N}_1 \geq a) = 0\quad\mbox{ if }c\in[0,1),\\
    & \lim_{a \rightarrow \infty} \limsup_{N \rightarrow \infty} \mathbb{P}(X^{j,N}_2 \geq a) = 0\quad\mbox{ if }c\in(1,q^{-1}).
\end{split} \end{equation}

[Lemma lem: DHX input for specific rare event of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] Recall that $u_i$ is the center of $\mathsf{B}_i$ and let $\bar{\partial}\mathsf{B}_i=\partial\mathsf{B}_i\cup\partial\Lambda_{M/2}(u_i)\cup \partial\Lambda_{M/4}(u_i)$. There exists a constant $c_5>0$ such that for any $1\le i\le n$, any external field $h\in\mathbb R^{\Lambda_N}$ and any set $I\subset \mathsf{B}_i$, we have  \begin{align}
       |\langle ~\sigma^I\mid\mathcal{E}_\tau~\rangle_{\Lambda_N,{\epsilon} \hat{h}^i}^{+}|&\le c_5^{|I|} F(\bar{\partial}\mathsf{B}_i,I),
    \end{align}
    where $\hat h^i_x=h_x\cdot \mathbf 1_{x\not\in\mathsf{B}_i}$ is the external field obtained by removing the field inside $\mathsf{B}_i.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition BBM fixed splitting time, tail estimate of arXiv:2606.19207, 'Extrema of cooling branching Brownian motion and related Gaussian fields'] Fix $\alpha\in(0,1/2]$ and consider the same BBM as in Proposition~(proposition: aBBM exceeding probability of the paper). Recall that $\mathcal{N}_T$ is the index set of all particles at the terminal time $T$. There exist constants $C,c,c_1,c_2>0$ and thresholds $K_*,T_*>0$ such that, for all integers $N\geq1$ with $T=N\Delta t\geq T_*$, all $K_0\geq K_*$, all
	$n\in\mathbb{Z}_+$, and every deterministic subset $\Gamma\subset\mathcal{N}_T$,
	\begin{equation}
		\begin{aligned}
			&\mathbb{P}\Bigl(\exists\,v\in\Gamma\colon
			Y_T^{\alpha,v}\geq A(T)+K_0-n\Bigr)\\
			&\quad\leq Ce^{-c(K_0+n)}
			+C \lvert\Gamma\rvert 
			\exp\bigl\{-\tfrac12c_A^2T-c_1K_0+c_2T^\alpha(n+1)\bigr\},
		\end{aligned}
	\end{equation}
	where $c_A:=\sqrt{2\log m/\Delta t}$.

[Lemma 16 of arXiv:2609.01166, 'Nonparametric inference for density-dependent McKean--Vlasov diffusions'] Suppose Assumptions~\ref{ass:potential} and~\ref{ass:coefficient} hold, and assume \(\kappa\leq\xi\leq K\) and \(\Vert \xi\Vert_{\mathcal{H}^{\widetilde{\beta}}([0,U])}+\Vert\Xi_0\Vert_{\mathcal{H}^{\widetilde{\beta}}([0,U])}\leq \widetilde{H}\) for some \(\widetilde{\beta}>0\). 
Let \(I=[r_-,r_+]\Subset(0,a_0)\) and assume that the mode satisfies \(a_\xi \ge r_+ + \eta_I\) for some fixed \(\eta_I>0\). Finally, suppose that Assumption~\ref{ass:regular-interior} holds for \(\xi_\circ=\Xi_0\).
Then 
\begin{equation}
 \norm{\xi-\Xi_0}_{L^2(I)} \leq C \KL(\pi_0\Vert\pi_\xi)^{\widetilde{\beta}/(2(\widetilde{\beta}+1))}
\end{equation}
for some constant 
\(
C:=C(I,V,\kappa,K,\widetilde{\beta},\widetilde{H})>0
\).

