[Prop 7 of arXiv:2608.30380, 'Morita Induction and Geometric Ideals in $\ell^p$ Roe-Type Algebras'] Let $I\triangleleft B$ and set $J=\Ind_B^A(I)$.  Then
\begin{align}
 J
 &=\clspan{{}_A\langle E^{>}I,E^{<}\rangle}
 =\clspan{{}_A\langle E^{>},I E^{<}\rangle}
 =\clspan{{}_A\langle E^{>},{}_I E^{<}\rangle}.
 \tag{2.3}
\end{align}
In particular, $J$ is a closed two-sided ideal of $A$.

[Theorem 10 (Minimax lower bound) of arXiv:2608.22179, '\bf Token-Level Likelihood-Array Regression for Membership Inference and AI-Generated Text'] For fixed $\nu>1$ and $M>0$, there exists a constant $c>0$ such that, for all
sufficiently large $n$,
\begin{equation}
\inf_{\widetilde{\eta}}
\sup_{P\in\mathcal P_\nu(M)}
\mathbb E_P
\|\widetilde{\eta}-\eta_0\|_{P_\Phi}^2
\geq
c
\left\{
\frac{\log(en)}{n}
\right\}^{\nu/(\nu+1)}.

\end{equation}
The infimum is over all estimators based on
$\{(Y_i,\Phi_i):i=1,\ldots,n\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 22 of arXiv:2605.16560, 'Seasonal Statistics of Shannon Rate in a Dynamical Poisson-Voronoi Cellular Network'] The coverage probability with respect to Palm probability distribution of the typical mS-MI, MS and typical time epoch is given by 
\begin{align}
p^c(\tau,\mu,\la,\a)&=  \E^0_H\left[e^{-\mu\tau H^{\a}\s^2} \Lcal_{I_{H}}(\mu\tau H^{\a})\right],

\end{align}

where $H \in \{H_{\sst \Vcal}, H_{\sst S},R\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2608.19753, 'Uniform large deviation principles for the stochastic heat equation over unbounded sets of'] Let the conditions of Theorem \ref{th:C} hold and let $\tilde{p}\in (6,\frac{3q}{\lambda})$.     
Let  $N\in[0,\infty)$, let $u\in L^2(0,T;L^2(D))$ with $\|u\|_{L^2(0,T;L^2(D))}\leq N$, and let $x\in L^q(D)$. 
Define the space $F_T$ as in \eqref{eq:defE_TF_T}, 
and define $\Psi_x^b, \Psi_x^{\sigma,u}\col F_T \to F_T$  and $\Psi_x^\sigma\col L^{\tilde p}(\Om;F_T)\to L^{\tilde p}(\Om;F_T)$ by  the formulas in \eqref{eq:defs Psi maps}. 

Then, these mappings are well-defined and the following Lipschitz bounds hold for all   $\phi,\psi \in F_T$,   $\tilde\phi,\tilde\psi\in L^{\tilde p}(\Om;F_T)$, and $t\in(0,T]$:
\begin{align}
\begin{split}
\|\Psi_x^{b}(\phi)-\Psi_x^{b}(\psi)\|_{F_t}^{\tilde{p}} 
    &\lesssim_{T,\tilde p} \int_0^t \|\phi-\psi\|_{F_s}^{\tilde{p}}\dd s,\\ 
    \|\Psi_x^{\sigma,u}(\phi)-\Psi_x^{\sigma,u}(\psi)\|_{F_t}^{\tilde p} 
    &\lesssim_{N,T,\tilde p} \int_0^t \|\phi-\psi\|_{F_s}^{\tilde p} \dd s,\\ 
    \|\Psi_x^{\sigma}(\tilde\phi)-\Psi_x^{\sigma}(\tilde\psi)\|_{L^{\tilde{p}}(\Om;F_t)}^{\tilde{p}}
    &\lesssim_{T,\tilde p} \int_0^t \|\tilde\phi-\tilde\psi\|_{L^{\tilde{p}}(\Om;F_s)}^{\tilde{p}}\dd s.  
 \end{split}
 \end{align}  
 Furthermore,  $\Psi_x^b$ and $\Psi_x^{\sigma,u}$ with $u\in \A_N$ (see \eqref{eq:AN}) are also well-defined as mappings $L^{\tilde p}(\Om;F_T)\to L^{\tilde p}(\Om;F_T)$, and the first two bounds in \eqref{eq:PsiLip C} hold a.s.\ for $\phi,\psi\in L^{\tilde p}(\Om;F_T)$.

[Theorem 11 (Multi-horizon spectral sandwich) of arXiv:2608.21466, 'Spectral partitioning for $k$-block averaging kernels of finite Markov chains'] Let $k\in\llbracket 2,n-1\rrbracket$, and recall that $L_\star, g_\star, W_\star$ are introduced in \eqref{eq:multi-L-g-W}. For every $k$-block partition $\mathcal O$,
\begin{equation}
    L_\star+g_\star\delta(\mathcal O)
    \leq F_\star(\mathcal O)
    \leq L_\star+W_\star\delta(\mathcal O).

\end{equation}

[OPEN PROBLEM - not a proved fact. Stated in arXiv:2512.02538, 'On the spectral geometry of Liouville quantum gravity' (problem environment labelled C:Sar).] For each $x \ge 0$, show that 
\begin{equation}
\frac1{N} \sum_{j=1}^{N} 1_{\{ c_\gamma \mu_\ph(\Sigma)(\boldsymbol{\lambda}_{j+1} - \boldsymbol{\lambda}_j) \le x\} } \xrightarrow[N\to\infty]{p} F_{\emph{GOE}}(x),
\end{equation}
where $F_{\emph{GOE}} (x)$ is the GOE \emph{level-spacing distribution}. (Verbatim from the paper's TeX; symbols are the source paper's. Stated as open/conjectural; no resolution of it was found in the paper's own text by the rules of problem_index.py - a paper may still prove special cases of a conjecture it states.)

[Prop 43 of arXiv:2607.28578, 'On two differing geometric descriptions of the passage from microscopy to macroscopy in Ma'] For each admissible $r$, the map
	\[
		\rho\longmapsto(\Kop^{\Wass}_{\rho})^{-1}
	\]
	is smooth from $\mathcal U^s_+(M)$ into $\mathcal L(H^{r-1}_0(M),H^{r+1}(M)/\R)$. Its differential is
	\begin{equation}
		D(\Kop^{\Wass}_{\rho})^{-1}[\eta]=-(\Kop^{\Wass}_{\rho})^{-1}\bigl(D\Kop^{\Wass}_{\rho}[\eta]\bigr)(\Kop^{\Wass}_{\rho})^{-1},
	\end{equation}
	where
	\begin{equation}
		D\Kop^{\Wass}_{\rho}[\eta]\phi=-\Div(\eta\grad\phi).
	\end{equation}

