[Definition 20 ($Obj(Loop)$ and $\rightarrow_L$) of arXiv:2608.29086, '2608.29086'] The objects $Obj(Loop)$ and the binary relation $\rightarrow_L$ on them are defined as follows:
\begin{enumerate}
\item $Obj(Loop)$ denotes the power set of $LOOP(M_0)$, i.e.,
\begin{equation*}
Obj(Loop):=Power(LOOP(M_0)).
\end{equation*}
Elements of $Obj(Loop)$ are called \textit{loop complices} (on $M_0$). 

Given $l =\{\psi_i\} \in Obj(Loop)$. Then, $l$ is expressed as a monomial, i.e.,
\begin{equation*}
l=\prod_{i}{\psi}_i  \in Obj(Loop),
\end{equation*}
using the multiplicative notation. The \textit{region $|l|$ of $l$} is defined by
\begin{equation*}
|l|:= \bigcup_{{\psi}_i \in l} |{\psi}_i|  \in REG(M_0).
\end{equation*}
``$Z$'' denotes the empty set of $Obj(Loop)$, i.e., 
\begin{equation*}
Z:= \emptyset  \in Obj(Loop).
\end{equation*}

\item Given $l_1=\prod_ i {\psi}_i,\  l_2=\prod_i {\phi}_i \in Obj(Loop)$. The binary relation $\rightarrow_L$  between $l_1$ and $l_2$ is defined by 
\begin{multline*} 
\phantom{aaaaaaaa}l_1 \rightarrow_L l_2 \text{ if and only if} \\
\text{ for } \forall {\phi}_i \in l_2,\  \exists B_{\phi_i}  \subset l_1 \text{ such that } 
|{\phi}_i| =\bigcup_{\psi_j \in B_{\phi_i}} |{\psi}_j|.
\end{multline*}
\end{enumerate}

[Lemma eq.DFmu_formula of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] For every $F \subseteq E_d({\scaleobj{1}{\square}}_m)$ with $\vert F \vert = k \geqslant 1$, we have the following identity
		\begin{multline}
			\sum_{\substack{|F|=k\\ F\subseteq E_d({\scaleobj{1}{\square}}_m)}} D_F \mathscr{E}_{m,\xi}(\mathbf{a}) =  	\frac{1}{|{\scaleobj{1}{\square}}_m|}
			\left \langle \nabla \ell_\xi, \mathbf{a} \sum_{\substack{|F|=k \\ F \subseteq E_d({\scaleobj{1}{\square}}_m)}} (D_{F}\nabla v_{m,\xi})(\mathbf{a})\right \rangle_{{\scaleobj{1}{\square}}_m}\\
			+	\frac{1}{|{\scaleobj{1}{\square}}_m|}\sum_{e\in E_d({\scaleobj{1}{\square}}_m)}
			\left \langle \nabla\ell_\xi, (\mathbf{a}^e-\mathbf{a})\sum_{\substack{|G|=k-1 \\  G \subseteq E_d({\scaleobj{1}{\square}}_m)}} (D_{G}\nabla v_{m,\xi})(\mathbf{a}^e)\right \rangle_{{\scaleobj{1}{\square}}_m}.
		\end{multline}

