[Definition eq generic automorphism def of arXiv:2609.04072, 'Oort's conjecture for split unitary Shimura varieties'] Let $N=gm(n-m)-n+1$. If $n \nmid g$ we define
\begin{equation}
    \Gamma_{\operatorname{gen}} := \mathbb{Z}_p^\times + \pi^N \operatorname{Mat}_g(\mathcal{O}_D)=\mathbb{Z}_p^\times.V_N,
\end{equation}
and if $n \mid g$ we define
\begin{equation}
    \Gamma_{\operatorname{gen}}:=\mathbb{Z}_p^\times + \pi^{N-1}\mathcal{O}_D+\pi^N\operatorname{Mat}_g(\mathcal{O}_D)=(\mathbb{Z}_p^\times + \pi^{N-1}\mathcal{O}_D).V_N.
\end{equation}

[Lemma Hopf Lax of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $\mu$ be a probability measure on $\mathbb{R}$ with support bounded from below and let $t>0$.
		\begin{enumerate}
			\item Let $x\in\mathbb{R}$ and set $\omega := \omega_{\mu,t}(x)\in\mathbb{C}^+\cup\mathbb{R}$. Define the characteristic path $(z_s)_{s\in [0,t]}$ by
			\begin{equation}
				z_s = \omega + s\, G_\mu(\omega).
			\end{equation}
			If $x\leq \ell(\mu\boxplus\sigma_t)$, then for every $s\in [0,t]$,
			\begin{equation}
				x \leq z_s \leq \ell(\mu\boxplus\sigma_s).
			\end{equation}
			If instead $x$ lies in the interior of $\mathrm{supp}(\mu\boxplus\sigma_t)$, then for every $s\in [0,t)$,
			\begin{equation*}
				\Im\bigl(\omega + s\,G_\mu(\omega)\bigr) > 0.
			\end{equation*}

			\item For every $x\leq \ell(\mu\boxplus\sigma_t)$,
			\begin{multline}
				\int \log|\lambda-x|\,\mathrm{d} (\mu\boxplus \sigma_t)(\lambda) = \int \log |\lambda-\omega_{\mu,t}(x)|\,\mathrm{d} \mu(\lambda) + \frac{\Re\bigl(\omega_{\mu,t}(x)-x\bigr)^2 - \Im\bigl(\omega_{\mu,t}(x)\bigr)^2}{2t}\\
				= \inf_{u\leq \ell(\mu)}\;\sup_{\substack{v\geq 0 \\ u+iv\in \overline{\Omega_{\mu,t}}}} \Bigl(\int \log |\lambda-(u+iv)|\,\mathrm{d} \mu(\lambda) + \frac{(x-u)^2-v^2}{2t}\Bigr).
			\end{multline}
			Moreover, the infimum in (equation eq:ch of the paper) is uniquely attained at $(u,v)=\bigl(\Re(\omega_{\mu,t}(x)),\,\Im(\omega_{\mu,t}(x))\bigr)$.
		\end{enumerate}

[Theorem 3 of arXiv:2604.25336, 'Central limit theorem for slow-fast system under mixed fractional Brownian motion'] Under assumptions \textbf{H1}-\textbf{H3}. Then for any function \(h\in C^{2,2+\gamma}\) with \(\gamma\in(0,1]\) which is ``centering" that is \(\bar h = \int_{\mathbb{R}^{m}} h(x,y)\mu^x(dy)=0\), there exists a unique solution $u$ satisfying the following Poisson equation in \(\mathbb{R}^m\) which depends on the parameter \(x\), 
\begin{equation}
-\mathcal{L}^x(y)u(x,y) = h(x,y).
\end{equation}
Here, \(\mathcal{L}^x\) is the infinitesimal generator of the fast process \(Y\) where \(x\) is considered as a parameter. 
Moreover, \(u(x,y)\in C^2\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2608.05679, 'Small ball probabilities and Chung's law of the iterated logarithm for Gaussian Volterra p'] Under Condition \eqref{eq constant cond}, there exists a constant
$\kappa_5\in(0,\infty)$ such that, for every $t>0$,
\begin{align}
\liminf_{r\to0^+}
\sup_{|s|\le r}
\frac{ (\log\log r^{-1})^{\gamma+\frac32} }
{r^{\gamma+\frac32} }|X(t+s)-X(t)|
=
\kappa_5 t^{\alpha+\beta},
\qquad \text{a.s.}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

