[Proposition 15 of arXiv:2604.11921, 'Replica symmetry up to the de Almeida--Thouless line in the Sherrington--Kirkpatrick model'] \label[proposition]{prop:Doob}
Let $t=q+\lambda/\beta^2$ with $0\le \lambda\le \beta^2(1-q)$, and fix $x\in\R$.  For every bounded measurable
$\psi:\R\to\R$,
\begin{equation}
\E\bigl[\psi(X_t)\mid X_q=x\bigr]
=
\frac{\E\bigl[\psi(x+\sqrt\lambda\,G)\cosh(x+\sqrt\lambda\,G)\bigr]}
{\E\bigl[\cosh(x+\sqrt\lambda\,G)\bigr]},
\qquad G\sim N(0,1).
\end{equation}

