[Lemma lem-26apr2002 of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] Suppose there exists $C>0$ so that 
    \begin{equation}

      \kappa(t)\le \frac{C}{|t|} \quad \text{for all } t \leq -1.
    \end{equation}
    Then there exists $t_{\textnormal{max}} \leq -1$ such that for all $\mathfrak{t} \leq t_{\textnormal{max}}$, there exists $T=T(\mathfrak{t}) > |\mathfrak{t}|$ such that the solution $z(t,x)$ of (equation eq:finite-time of the paper) satisfies
    \begin{equation}

      z(\mathfrak{t}, x) \geq x \quad \text{for all } x \leq \frac{\abs{\mathfrak{t}}}{2}
    \end{equation}
    and
    \begin{equation}

      \left |\partial_x z(t,x) \right| \leq 16 \quad \text{for all } t<\mathfrak{t}, x > 0.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem polynomial_recursion of arXiv:2506.02611, '\textbf{The tight length spectrum of large-genus random hyperbolic surfaces with many cusp'] For all $g,n \ge 0$ such that $n \ge 3$ for $g =0$ and $n\ge 1$ for $g=1$, and any $\mu \le \mu_c$, we have
    \begin{align*}
        T_{g,n}(\mathbf{L},\mu) = \frac{1}{M_0(\mu)^{2g-2+n}}\mathcal{P}_{g,n}\bigg(\mathbf{L},\frac{M_1(\mu)}{M_0(\mu)},\cdots,\frac{M_{3g-3+n}(\mu)}{M_0(\mu)}\bigg),
    \end{align*}
    where $\mathcal{P}_{g,n}(\mathbf{L},\mathbf{m})$ is a rational polynomial in $L_1^2,\cdots,L_n^{2},m_1,\cdots,m_{3g-3+n}$. This polynomial is symmetric and of degree $3g-3+n$ in $L_1^2,\cdots,L_n^{2}$ while $\mathcal{P}_{g,n}(\sqrt{\sigma}\mathbf{L},\sigma m_1,\cdots,\sigma^{3g-3+n}m_{3g-3+n})$ is homogeneous of degree $3g-3+n$ in $\sigma$. For $g \ge 0$, $n \ge 1$ such that $2g-3+n > 0$, the polynomial $\mathcal{P}_{g,n}(\mathbf{L},\mathbf{m})$ can be obtained from $\mathcal{P}_{g,n-1}(\mathbf{L},\mathbf{m})$ via the recursion relation
    \begin{align}
        &\mathcal{P}_{g,n}(\mathbf{L},\mathbf{m}) = \somme{p=1}{3g-4+n}{\bigg( m_{p+1} - \frac{L_1^{2p+2}}{2^{p+1}(p+1)!} - m_1m_p + \frac{1}{2}L_1^{2}m_p\bigg)\frac{\partial \mathcal{P}_{g,n-1}}{\partial m_p}(\mathbf{L}_{\widehat{\{1\}}},\mathbf{m})}\\
        &\qquad +(2g-3+n)\bigg(-m_1+\frac{1}{2}L_1^2\bigg)\mathcal{P}_{g,n-1}(\mathbf{L}_{\widehat{\{1\}}},\mathbf{m}) + \somme{i=2}{n}{\inte{0}{L_i}{x\mathcal{P}_{g,n-1}(x,\mathbf{L}_{\widehat{\{1,i\}}},\mathbf{m})}{x}}.\nonumber
    \end{align}
Furthermore, we have:
\begin{align}
    &\mathcal{P}_{0,3}(\mathbf{L},\mathbf{m}) = 1,\\
    &\mathcal{P}_{1,1}(\mathbf{L},\mathbf{m}) = \frac{1}{24}(-m_1+\frac{1}{2}L_1^{2}),
\end{align}
and $\mathcal{P}_{g,0}(\mathbf{m})$ is given by:
\begin{align}
    \mathcal{P}_{g,0}(\mathbf{m}) = \somme{\substack{d_2,d_3\cdots \ge 0\\ \somme{k=2}{3g-2}{(k-1)d_k} = 3g-3}}{}{\langle \tau_{2}^{d_2}\cdots\tau_{3g-2}^{d_{3g-2}}\rangle_g \prod_{k=2}^{3g-2}\frac{(-m_{k-1})^{d_k}}{d_k!} },
\end{align}
where $\langle \tau_{2}^{d_2}\cdots\tau_{3g-2}^{d_{3g-2}}\rangle_g$ are the $\psi$-class intersection numbers on the moduli space $\mathcal{M}_{g,n}$ with $n = \somme{k}{}{d_k} \le 3g-3$ marked points. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:homogeneous-section-weighted-integrability of arXiv:2608.30779, 'Some uniform estimates for K\"ahler--Ricci Shrinkers'] Let
\(X\in\overline{\mathcal{KRS}(n)}\),
\(k\in\mathbb Z_{\geq0}\), and
\[
 s\in H^0\!\left(X,\mathcal O_X(-kK_X)\right)
\]
be homogeneous for the canonical lift of the soliton torus.  Then
\begin{equation}
 \int_{\mathcal R}|s|_{h^k}^2e^{-\tau f}\omega^n<\infty
 \qquad\text{for every }\tau>0.
\end{equation}
If \(s\ne0\) and \(As=\lambda s\), where
\(A=-\sqrt{-1}\mathcal L_\xi\), then
\begin{equation}
 \frac{\int_{\mathcal R}f|s|_{h^k}^2e^{-f}\omega^n}
      {\int_{\mathcal R}|s|_{h^k}^2e^{-f}\omega^n}
 =\frac{\lambda}{k+1}.
\end{equation}

[Proposition thm:assoc-game of arXiv:2412.09087, 'General Markovian randomized equilibrium existence and construction in zero-sum Dynkin gam'] \enskip

\begin{enumerate}[(i)]
\item A global Markovian pure Nash equilibrium $(\tilde\tau_1^*,\tilde\tau_2^*)$, whose value corresponds to a continuous function $V: {\cal I}\rightarrow \mathbb{R}$, exists. 
More precisely,  
\begin{align*}
 \tilde \tau_i^*= \inf\{t \geq 0: X_t \in D_i^{*}\}, \enskip i=1,2,
\end{align*}
where
\begin{align}
\begin{split}
D_1^{*}:&=\{x \in {\cal I}: \tilde f(x)=V(x)\},\\
D_2^{*}:&=\{x \in {\cal I}: \tilde g(x)=V(x)\}.
\end{split}
\end{align}
Moreover, $\tilde f(x)\leq V(x) \leq\tilde g(x)$, for each $x \in {\mathcal I}$.

\item  For $x \in B^{g \leq f} \supseteq  {B^{g\leq h \leq f}} \cup {B^{h<g<f}} \cup {B^{g<f<h}} $, it holds that $V(x) = \tilde f(x)=\tilde g(x)$. 
Moreover, in equilibrium both players stop on $B^{g \leq f}$; in particular, 
\begin{align}
{B^{g\leq h \leq f}} \cup {B^{h<g<f}} \cup {B^{g<f<h}} \subseteq B^{g \leq f} \subseteq  D_i^{*} , \enskip i =1,2.
\end{align} 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

