[Theorem 4 (Stollmann--Voigt inequality) of arXiv:2607.00853, '\sf Energy integrals and asymmetric co-potentials for closed forms'] For any $\alpha>\beta_0$, $\mu\in {\sf S}_{0}$ and $f\in D(\form)$, we have 
 \begin{align*} 
 \int_Ef^2d\mu\leq K_{\alpha}^2\|U_{\alpha}\mu\|_{\infty}^{1/2} \|\widehat{U}_{\alpha}\mu\|_{\infty}^{1/2} \form_{\alpha}(f,f). 
 \end{align*}

[Lemma estimate of arXiv:2607.02742, 'Gaussian fluctuations for the parabolic Anderson model with L\'evy white noise'] Let $p\geq 2$ be such that $m_p<\infty$, and $\Phi=\{\Phi(t,x); t\geq 0, x\in\mathbb{R}\}$ be
predictable process such that for any $t>0$ and $x\in \mathbb{R}$,
\[
\int_0^t \int_{\mathbb{R} }G_{t-s}^2(x-y)|\Phi(s,y)|^2 dyds<\infty. 
\]
Then, for any $t>0$ and $x \in \mathbb{R}$,
\begin{equation}

\mathbb{E}\left| \int_0^t\int_{\mathbb{R}}G_{t-s}(x-y)\Phi(s,y)L(ds,dy) \right|^p \le A_{t,p} \int_0^t\int_{\mathbb{R}}
H_{t-s}^{(p)}(x-y)\mathbb{E}|\Phi(s,y)|^p dyds,
\end{equation}
where $A_{t,p}=\mathcal{C}_p^p\max\{\nu_{t,2}^{\frac{p}{2}-1}, 1\}$, $\mathcal{C}_p$ is the constant from Proposition (ros1 of the paper), and 
\begin{equation}

H_t^{(p)}(x)=G_t^2(x)+G_t^p(x). 
\end{equation}

[Proposition 98 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\beta \in (\frac{1}{3},\frac{1}{2}]$ be an index, and let $f_0 \in \Lip([0,T] \times W,D(A))$ and $f \in C_b^{2\beta,3}([0,T] \times W, L(V,D(A^2)))$ be mappings such that \eqref{f0-restriction} and \eqref{f-restriction} are fulfilled. Then the It\^{o}-Lyons map
\begin{align*}
D(A^2) \times \big( \scrc^{\beta}([0,T],V), d_{\beta} \big) \to \calc^{\beta}([0,T],W) \times \calc^{\beta}([0,T],L(V,W))
\end{align*}
induced by Theorem \ref{thm-RPDE-main} is locally Lipschitz continuous. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2606.11142, 'Strong invariance principles for diffusions, Markov chains and their perturbations.'] For transition densities $p^h, p^h_\epsilon$ of Markov chains there exists a constant $C_1(q) > 0$ such that for any $t_i < t_j$ and $x \in \mathbb{R}^d$:
\begin{equation} 
\int_{\mathbb{R}^d} |p^h(t_i, t_j, x, y) - p^h_\epsilon(t_i, t_j, x, y)| dy \le C_1 \Delta_{\epsilon,\gamma,q}.
\end{equation}
For transition densities $p, p_\epsilon$ of diffusions there also exists a constant $C_2(q) > 0$ such that:
\begin{equation} 
\int_{\mathbb{R}^d} |p(t_i, t_j, x, y) - p_\epsilon(t_i, t_j, x, y)| dy \le C_2 \Delta_{\epsilon,\gamma,q}.
\end{equation}

