[Thm 12 of arXiv:2609.02974, 'Quilt decompositions of surfaces and Torelli group action on the extended Hatcher complex'] \mbox{} 

    (1) A torsion-free subgroup of $\mathcal{M}_{g,r}$ acts freely on the colored extended Hatcher complex $\overline{H}(\Sigma_{g,r})$.

    (2) A torsion-free subgroup of $\mathcal{M}_{g,r}$ also acts freely on the extended Hatcher complex $\widetilde{H}(\Sigma_{g,r})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2607.10725, 'From the Airy line ensemble to the Gaussian free field'] Fix $t \in \mathbb{R}$, $x < 0$, $\eta > 0$, and $T > 0$. Let $S(z;t,x)$ be as in (\ref{Eq.DefS}) and assume the notation in Definition \ref{def: contour}. With $|dz|$ and $|dw|$ denoting integration with respect to arc-length, the following inequalities all hold. 
\begin{equation}
\begin{aligned}
& \int_{\refbeth^{\pm,1}} |\diff z |\left|e^{T^{3/2} \left(S(z; t, x)- S(\crit^\pm;t, x)\right)}\right|
\le \left(\sqrt{-x} + \frac{1}{T^{3/2}\sqrt{-x} \eta} \right)e^{-T^{3/2}\sqrt{-x}\eta^2},\\
& \int_{\contour^{\pm,1}} |\diff w| \left|e^{-T^{3/2} \left(S(w; t, x)- S(\crit^\pm;t, x)\right)}\right|
\le \left(\sqrt{-x} + \frac{1}{T^{3/2}\sqrt{-x} \eta} \right)e^{-T^{3/2}\sqrt{-x}\eta^2},
\end{aligned}
\end{equation}

\begin{equation}
\begin{aligned}
& \int_{\refbeth^{\pm,0}} |\diff z|  \left|e^{T^{3/2} \left(S(z; t, x)- S(\crit^\pm;t, x)\right)}\right|\le \frac{4}{T^{3/4}(-x)^{1/4}},\\
& \int_{\contour^{\pm,0}} |\diff w|  \left|e^{-T^{3/2} \left(S(w; t, x)- S(\crit^\pm;t, x)\right)}\right|\le \frac{4}{T^{3/4}(-x)^{1/4}}.
\end{aligned}
\end{equation}

\begin{equation}
\begin{aligned}
&\int_{\refbeth^{\pm,0}} \abs{\diff z} \int_{\contour^{\pm,0}} \abs{\diff w}\, \frac{\left|e^{T^{3/2}\left(S(z;t,x)-S(w;t,x)\right)}\right|}{\abs{z-w}} \leq \frac{32}{T^{3/4} (-x)^{1/4}}, \\
&\int_{\refbeth^{\pm,0}} \abs{\diff z} \int_{\contour^{\mp,0}} \abs{\diff w}\, \frac{\left|e^{T^{3/2}\left(S(z;t,x)-S(w;t,x)\right)}\right|}{\abs{z-w}} \leq \frac{32}{T^{3/4} (-x)^{1/4}}.
\end{aligned}
\end{equation}

