[Definition 1 (Bulk contour statistic) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] Let \(A\) be a real symmetric matrix and let \(\varphi\) be analytic on a
neighborhood of \(\overline{D_\Gamma}\).  Define
\begin{equation}
 \mathcal L_A^\Gamma(\varphi)
 :=\sum_{j=1}^N
 \varphi(\lambda_j(A))\one_{\{\lambda_j(A)\in D_\Gamma\}}.
\end{equation}
If \(\spec(A)\cap\Gamma=\varnothing\), then
\begin{equation}
 \mathcal L_A^\Gamma(\varphi)
 =-\frac{1}{2\pi\ii}
 \oint_\Gamma
 \varphi(z)\Tr(A-zI)^{-1}\,\dd z.
\end{equation}

[Theorem 3 of arXiv:2605.23461, 'An almost sure invariance principle for the Takagi--van der Waerden class functions'] Suppose that \eqref{Assump2:A_n_to_infinite} and \eqref{Assump2:last_term} hold. Then, for any $p\in (0, 1)$,
  \begin{equation}
    s_n^2 \to \infty \quad \text{as $n\to\infty$},
  \end{equation}
  and without changing the distribution of the process $\{S_n \colon n\ge 0\}$, we can redefine the process $\{S_n\colon n\ge 0\}$ on a richer probability space on which a standard Brownian motion $\{B(t)\colon t\ge 0\}$ is defined such that
\begin{equation}
  S_n -  B(s_n^2) = o(s_n^{1-\lambda}) \quad \text{as $n\to \infty$, a.s.}
\end{equation}
 for each $\lambda < \delta/16$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2608.26001, 'The kernel of the Birman--Craggs--Johnson homomorphism'] Fix $g \geq 2$.  Set $H_{\Z} = \HH_1(\Sigma_g^1) = \HH_1(\Sigma_g)$ and
$H = \HH_1(\Sigma_g^1;\bbF_2) = \HH_1(\Sigma_g;\bbF_2)$.  We then
have commutative diagrams with exact rows
\[\begin{tikzcd}[column sep=tiny]
1 \arrow{r}
  & \cK_g^1 \arrow[two heads]{d} \arrow{r}
  & \Torelli_g^1 \arrow[two heads]{d} \arrow{r}{\tau}
  & \wedge^3 H_{\Z} \arrow[two heads]{d}{\substack{\text{reduce}\\ \text{mod }2}}
      \arrow{r}
  & 1 \\
  & \QK_g^1 \arrow{r}
  & \QTorelli_g^1 \arrow{r}
  & \wedge^3 H \arrow{r}
  & 1
\end{tikzcd}
\enspace \text{and} \enspace
\begin{tikzcd}[column sep=tiny]
1 \arrow{r}
  & \cK_g \arrow[two heads]{d} \arrow{r}
  & \Torelli_g \arrow[two heads]{d} \arrow{r}{\tau}
  & (\wedge^3 H_{\Z})/H_{\Z} \arrow[two heads]{d}{\substack{\text{reduce}\\ \text{mod }2}}
      \arrow{r}
  & 1 \\
  & \QK_g \arrow{r}
  & \QTorelli_g \arrow{r}
  & (\wedge^3 H)/H \arrow{r}
  & 1
\end{tikzcd}\]

