body:
[Lemma 18 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] \begin{itemize}
\item The functions $\Theta_1$ and $\Theta_3$ satisfy the following heat equations:
\begin{equation}
	\partial_r \Theta_1(r; z) = \partial_z^2 \Theta_1(r; z), \quad 
	\partial_r \Theta_3(r; z) = \partial_z^2 \Theta_3(r; z).
\end{equation}
\item The function $\Theta_1(r; \cdot)$ has period $2\pi$ while the function $\Theta_3(r; \cdot)$ has anti-period $2\pi$:
\begin{equation} 
	\Theta_1(r; z)=-\Theta_1(r; z+2\pi), \quad \Theta_3(r; z)=\Theta_3(r; z+2\pi).
\end{equation}
\item The functions $\Theta_1$ and $\Theta_3$ satisfy the following imaginary shift identities:
\begin{equation}
	\Theta_1(r; z + \ii r) = \ii \ee^{\frac{r}{4} - \frac{\ii z}{2}} \Theta_3(r; z), \quad 
	\Theta_3(r; z + \ii r) = \ii \ee^{\frac{r}{4} - \frac{\ii z}{2}} \Theta_1(r; z).
\end{equation}
\item The functions $\Theta_1$ and $\Theta_3$ have the following asymptotics as $r\to \infty$: for $x\in \R$, we have

\begin{align} 
	\Theta_1(r; x)= 2 \ee^{-r/4} \sin\left(\frac{x}{2}\right) (1+O(1)\ee^{-2r}),\quad
	\Theta_3(r; x)= 1 + O(1)\ee^{-r},
\end{align}
where the $O(1)$ terms have upper bounds independent of $x$.
\end{itemize}

