[Theorem 1 of arXiv:2511.06196, 'Central limit theorem for high temperature spin models via martingale embedding'] Let $X$ follow the Ising model \cref{eq:Isingmodel} with $0\preceq A\prec I_n$. Let $\theta=(\theta_1,\dots, \theta_n)^\top\in \IR^n$ be a unit vector, that is, $|\theta|=1$. Let
\ben{
W_n:=\theta^\top X,\quad \mu_n:=\E(W_n),\quad \sigma_n^2:=\Var(W_n).
}
Then, we have
\besn{

&\mathcal{W}_2 (\mathcal{L}(W_n), N(\mu_n, \sigma_n^2))\leq 14\left\{\frac{1}{1-\|A\|_{\text{op}}} \sup_{h\in \IR^n} \sum_{k=1}^n \bigg[\sum_{i=1}^n \Big(\sum_{j=1}^n \theta_j B_{ij}^{(h)}\Big)\Big(\sum_{l=1}^n \theta_l B_{ilk}^{(h)}\Big) \bigg]^2 \right\}^{\frac{1}{14}}
}
provided that the right-hand side is sufficiently small, where
\besn{
&B_{ij}^{(h)}:=\Cov(X_i, X_j),\\
&B_{ilk}^{(h)}:= \E (X_i-\E X_i)(X_l-\E X_l)(X_k-\E X_k),
}
$N(\mu_n, \sigma_n^2)$ denotes the normal distribution with mean $\mu_n$ and variance $\sigma_n^2$,
the supremum in \cref{eq:thm1} is over all possible external fields $h\in \IR^n$,
and the expectations and covariances in \cref{eq:Bilk} are computed under the model \cref{eq:Isingmodel} with the external field $h$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi sol1 of arXiv:2605.10309, 'Exponential Decay of $L^2$-Solutions to Stochastic Nonlinear Schr\"odinger Equations Drive'] Let $\alpha\in(1,1+\frac{4}{d})$ and $T>0$. 
A $L^2$-solution of (equation SNLS of the paper) is a pair $(X,\tau)$, where $\tau(\le T)$ is an $(\mathcal{F}_t)$-stopping time, and $X=(X(t))_{t\in[0,\tau]}$ is a $L^2(dt)\cap L^2(d\langle M\rangle(t))$-valued continuous $(\mathcal{F}_t)$-adapted process, such that $|X|^{\alpha}\in L^1([0,T],H^{-2}(\mathbb{R}^d)), {
{\mathbf{P}}\text{-a.s.}}$, and it satisfies ${
{\mathbf{P}}\text{-a.s.}}$,
\begin{align}

X(t)&=x-\int_0^t(i\Delta X(s)+\lambda i|X(s)|^{\alpha-1}X(s))ds \nonumber \\
& \quad -\frac{1}{2}\sum_{j=1}^N\int_0^t|\mu_j|^2|e_j|^2 X(s)d\langle M_j\rangle(s)+\int_0^tX(s)dM(s), \quad t\in[0,\tau],
\end{align}
as equation in $H^{-2}$.

