[Thm 3 of arXiv:2607.22414, 'Asymptotic fluctuations in supercritical multi-type Crump--Mode--Jagers processes'] Assume~\ref{assumpt:Malthusian alpha} through~\ref{assumpt:hreprMoments} hold,
and let $\varphi$ be characteristic with c\`adl\`ag paths satisfying~\ref{assumpt:dRimean} through~\ref{assumpt:local ui}
for which~\eqref{eq:meanAs1} holds. Let $\mathcal{N}$ be a standard normal variable independent of Nerman's martingale limit $W$.
	\begin{enumerate}[\normalfont(i), wide]
		\item If $n=-1$, then
		\begin{equation*}
			e^{-\frac\alpha2t} \big(\cZ_t^\varphi - H_\Lambda(t) - H_\dLambda(t) \big) \tod \sigma \Big(\frac{W}\beta\Big)^{\!1/2} \mathcal{N}
			\quad	\text{as } t \to \infty
		\end{equation*}
		where
		\begin{equation*}
			\sigma^2 = \int_\G e^{-\alpha t} \bu^\trans \Var[\bxi*f^\varphi + \varphi](t) \, \ell(\dd t)
		\end{equation*}
		for the function
		\begin{equation}
			\begin{split}
				f^\varphi(t) 
				&= r(t)\1_{[0,\infty)}(t) - \!\!\!\sum_{\lambda\in\intLambda} e^{\lambda t} \sum_{k=0}^{k_\lambda-1} A_{\lambda,k+1} \int_\G \E[\varphi](s)\frac{(t-s)^k}{k!} e^{-\lambda s} \, \ell(\dd s) \1_{(-\infty,0)}(t).
			\end{split}
		\end{equation}
		Moreover, $\sigma=0$
		if and only if $\cZ_t^{\varphi} = H_\Lambda(t) + H_\dLambda(t) + \be_{\tau(\varnothing)}^\trans r(t)$ a.\,s.\ for any $t \geq 0$.
		\item If $n\geq0$, then
		\begin{equation*}
			\frac{e^{-\frac\alpha2 t}}{\sqrt{t^{2n+1}}} \big(\cZ_t^\varphi - H_\Lambda(t) - H_\dLambda(t) \big) \tod \frac{\rho_n}{\sqrt{2n+1}} \Big(\frac{W}\beta\Big)^{\!1/2} \mathcal{N}\quad	\text{as } t \to \infty.
		\end{equation*}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

