body:
[Pro disc of arXiv:2507.00737, 'Dispersion models on a circle: universal properties and asymptotic results'] In the discrete parking,
	\begin{equation} 
	{{\bf N}_{t_n}^{(n)}}/{\sqrt{n}} \xrightarrow[n]{(proba.)} \lambda (1-e^{-1})\end{equation}
	while, in the continuous parking
	\begin{equation}  {{\bf N}_{t_n} }/{\sqrt{n}} \xrightarrow[n]{(proba.)} \lambda.\end{equation}
	For any $k$, the following convergence in distribution holds in $\mathbb{R}^k$,
	\begin{eqnarray} 
	n^{-1}\,L^{(n), \downarrow}[t_n(\lambda),k] &\xrightarrow[n]{(d)}&(\ell_i^{\downarrow}(\lambda,{\sf e}),1\leq i \leq k)\\
	 n^{-1}\,L^{\downarrow}[t_n(\lambda),k] &\xrightarrow[n]{(d)}&(\ell_i^{\downarrow}(\lambda,{\sf e}),1\leq i \leq k)
	\end{eqnarray}
	where $(\ell_i^{\downarrow}(\lambda,{\sf e}),1\leq i \leq k)$ is the (random) vector formed by the $k$ largest excursion sizes of the process $t\mapsto ({\sf e}_t -\lambda_t)-\min_{s\leq t} ({\sf e}_s -\lambda s)$, sorted in descending order (where ${\sf e}$ is a normalized Brownian excursion). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 6 of arXiv:2511.11189, 'Sharp asymptotics for the maximal distance from the boundary to the nucleus of a typical P'] As \(t\rightarrow\infty\), 
		\begin{equation*}
			\E\left[\Card \left( \left(\VOMR\right)^2_{\neq} \right) \right] 
			= \mathcal{O}\left( t^{d(d-2)} e^{-\kappa_dt^d} \right)
			= o\left( \E\left[\Card (\VOMR) \right] \right).
		\end{equation*}

[Proposition 24 of arXiv:2605.02002, 'Glauber dynamics for random field Ising models on bounded degree graphs and MLSI'] Let $(u,v)\in E$ be any edge of the graph $G=(V,E)$ of maximal degree $\Delta$. Assume that Assumption \ref{thiasssumptionnew} holds for the given $p_0\in(0,1)$, then we have, for any $m\geq 1$,
    \begin{equation}\begin{aligned}
\mathbb{P}&\left(\sup_{\theta\in[0,\theta_*],\Lambda,\tau_0\in\Omega(\Lambda)}
\sum_{(wz)\in E}|\operatorname{Cor}_{(1-\theta)\otimes\mu^{\tau_0}}^{(2)}(uv,wz)|\geq \Delta m\right)\\&\leq \frac{2}{(1-e^{-\alpha_*})(1-e^{-2\alpha_*})}e^{2\gamma_*}e^{-\alpha_*m},\end{aligned}
    \end{equation}
    where $\gamma_*:=\ln\frac{1-p_0}{p_0(\Delta-2)}$ and $\alpha_*=\frac{1}{2}\log\frac{(\Delta-2)^{\Delta-2}}{p_0(\Delta-1)^{\Delta-1}(1-p_0)^{\Delta-2}}.$

[Theorem 16 (Time-uniform risk curves under contraction) of arXiv:2608.30261, 'Estimating Population-Risk Curves Along Nonconvex Gradient Flows from the Training Sample'] \label[theorem]{thm:contractive-risk-curve}
Suppose the conditions in
\cref{app:contractive-risk-curve-conditions} hold.  Let
$D_\Lambda=\operatorname{diam}(\Lambda,\|\cdot\|)$ and define the finite
deterministic constants
\begin{equation}
\begin{aligned}
 C_{{\rm ALO},\mu}
 &=\frac{2G_{\rm ev}J_3G_{\rm tr}^2}{\mu^3},\\
 C_{PP,\mu}
 &=\frac{H_{\rm ev}G_{\rm tr}^2}{\mu^2}
   +G_{\rm ev}\left\{
      \frac{2H_{\rm tr}G_{\rm tr}}{\mu^2}
      +\frac{J_3G_{\rm tr}^2}{\mu^3}\right\},\\
 C_{{\rm hyp},\mu}
 &=\max\left\{G_{\rm ev}G_{\rm tr},
       L_{\rm ev}^{\lambda}
       +\frac{G_{\rm ev}L_{\rm tr}^{\lambda}}{\mu}\right\},
 &D_\mu&=\mu^{-1}+D_\Lambda.
\end{aligned}
\end{equation}
For $\delta\in(0,1)$, define
\begin{equation}
\begin{aligned}
 \mathfrak r_{n,\mu}^{\rm ctr}(\delta)
 &=\frac{C_{{\rm ALO},\mu}+2C_{PP,\mu}}{(n-1)^2}
   +\frac{2C_{{\rm hyp},\mu}}{\sqrt n}\\
 &\quad+\frac{B_{\rm rng}+4G_{\rm ev}G_{\rm tr}/\mu}{\sqrt{2n}}
 \left[(d_\lambda+1)\log\{1+4D_\mu\sqrt n\}
       +\log\frac2\delta\right]^{1/2}.
\end{aligned}
\end{equation}
Then there is a measurable event with probability at least $1-\delta$ on
which
\begin{equation}
 \sup_{(t,\lambda)\in\cH_n}
 |\widetilde\Score_n(t,\lambda)-\Risk_S(t,\lambda)|
 \leq\mathfrak r_{n,\mu}^{\rm ctr}(\delta).
\end{equation}
The radius in \eqref{eq:contractive-risk-radius} is independent of $T_n$.

[Proposition 8 of arXiv:2608.02319, 'Averaging Principle for Ordinary Differential Equations in a Multiscale Random Environment'] For all $i\in I$, $x_i\in E_i$, $z\in\mathbb R^d$ and $T>0$, if assumptions \eqref{hyp:Lip} and \eqref{hyp:ErgoF} hold true and $F_i(z,\,\cdot\,)\in\mathcal A_i$, we have
\begin{align*}
\mathbf E_{x_i}\big[\lvert\mathbf Z_{\tau_1^n}^{n,z}-\bar{\mathbf Z}_{\tau_1}^z\rvert\,\mathbf 1_{\{\tau_1^n\vee\tau_1\leq T\}}\big]\underset{n\to\infty}{\longrightarrow}0.
\end{align*}

