[Theo 1 (Records for the $k$-coverage threshold when $B \subset A^o$) of arXiv:2608.19104, 'Record times for coverage thresholds and maximal spacings'] Suppose that $B = \overline{B^o} \neq \emptyset $,
	and that  $B \subset  A^o$ with $\dim(\partial B) < d $.
Let $k \in \N$.

  Then as $n \to \infty$,
	\begin{align}
		\E[N_{n,k}] & \sim (1/2) (\log n )^2;

\\
		N_{n,k} & \sim  (1/2) (\log n )^2
~~~~{\rm a.s.}

	\end{align} 
and 
	\begin{align}
	\nu_{n,k}^{1/\sqrt{n}} \to \exp \big( \sqrt{2} \: \big)   
~~~~{\rm a.s.}

		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2609.03084, 'Convergence rates to traveling waves for an FKPP model with nonlinear advection'] Let $\eta$ be defined as in \eqref{profile_function}. Then
        \begin{equation}
            \eta + \chi A \in C^3(0, 1). 
        \end{equation}

[Lemma 26 of arXiv:2609.02878, '2609.02878'] Let $d\nu_{x,b;a}$ be the conjugate heat-kernel probability at time $a$
with pole $(x,b)$, where $a<b<T$.  Then every smooth real or complex
function $\phi$ satisfies
\begin{equation}
 \int\left|\phi-\int\phi\,d\nu_{x,b;a}\right|^2d\nu_{x,b;a}
 \le2(b-a)\int|\nabla\phi|_{g(a)}^2\,d\nu_{x,b;a}.
\end{equation}

[Theorem 6 (Approximation accuracy of MYULA) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] Fix $t\ge1$ and $\tilde\alpha\in(0,1)$. Under the same assumptions of \cref{thm:linear-statistical}, for every fixed initial point $\theta_0\in \Theta$, there exist
$\varsigma_t>0$, $\gamma_{t}>0$, and $N_{t}\in\bN$ such that
    \begin{equation}
    \norm[1]{\delta_{\theta_0}\cK_{t,\varsigma_t,\gamma_{t}}^{N_{t}}-\Pi_t}_{\mathrm{TV}}
    \le \tilde\alpha
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 1 of arXiv:2605.12142, 'Nonlinear filtering with stochastic discontinuities'] The $\bbF^Y$-compensator\footnote{Also known in the literature as the dual predictable projection, \citep{jacod2013limit}} of $\mu$ is given by the predictable random measure
    \begin{align}
        \nu(dt, dy) = \sum_{i=1}^K \delta_{T_i}(dt) F^i(dy).
    \end{align}

