\begin{equation}
\mathcal C(\kappa)\geq-C H^2.
\end{equation}

[Corollary cor:LG-scalar of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The one-point Fredholm determinant
$F_{t, a, n} = \det(I - K_{t, a, n})$ satisfies
\begin{equation}
F_{t+1, a, n+1} F_{t, a+1, n}
- q F_{t, a, n} F_{t+1, a+1, n+1}
- p F_{t+1, a+1, n} F_{t, a, n+1}
= 0,
\end{equation}
at every $(t, a, n)$ with $a < y_{n+1} - 1$.

