[Lemma 17 (Exterior PRellich-Pohozaev-type identity) of arXiv:2609.03339, 'Exterior Serrin Rigidity for the Homogeneous \texorpdfstring{$k$}{k}-Hessian Equation\\'] One has
		\begin{equation}
			c^{k+1}\int_{\partial\Omega}hH_{k-1}\,dS
			+(n-k+1)J
			-2c^k\int_{\partial\Omega}hH_k\,dS=0.
		\end{equation}
		Equivalently,
		\begin{equation}
			(n-k+1)\left(J+\frac{c^{k+1}}{k-1}I_{k-2}\right)
			-\frac{2(n-k)c^k}{k}I_{k-1}=0.
		\end{equation}

[Lemma lem:moments-first of arXiv:2605.03703, 'Scaling Limits of Bivariate Nearly-Unstable Hawkes Processes and Applications to Rough Vol'] The following estimates hold uniformly in $t\ge0$:
\begin{align}
\mathbb{E}[\lambda_t^{T,1}]&\le \frac{\mu_T^1}{1-a_T^1},
\\
\mathbb{E}[\lambda_t^{T,2}]&\le
\frac{\mu_T^2}{1-a_T^2}
+\frac{b_T^{12}\|\psi^{12}\|_1}{1-a_T^2}
\frac{\mu_T^1}{1-a_T^1}.

\end{align}
Consequently $\sup_{T,t\in[0,1]}\mathbb{E}[V_t^{T,i}]<\infty$ for $i=1,2$.

[Lemma Benamou Brenier for W-p of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{Benamou-Brenier for Wasserstein-$p$ distance [ambrosio2005gradient][ledoux2015stein]} 
    Suppose $X, Z$ are two random variables in $\mathbb{R}^d$ with probability measures $\mathcal{L}(X), \mathcal{L}(Z) \in \mathcal{P}_p(\mathbb{R}^d)$ respectively. 
    For a weakly continuous curve of probability measures $\mu_t : I \to \mathcal{P}_p(\mathbb{R}^d)$ with open interval $I \subset \mathbb{R}$. If it  satisfies the continuity equation for some Borel vector field $v_t$ with $\int_I \int_{\mathbb{R}^d} \|v_t(x)\|_2^p d\mu_t(x) dt < \infty$ and
        $\partial_t \mu_t + \text{div}(\mu_t v_t) = 0, \; \forall (x,t) \in \mathbb{R}^d\times I$. Then curve $\mu_t: I\to \mathcal{P}_p(\mathbb{R}^d)$ is absolutely continuous and for Lebesgue-almost everywhere $t \in I$, we have
        \begin{align*}
            \lim_{ s\to t} \frac{W_p(\mu_s, \mu_t)}{|s-t|} \leq \left\{\int_{\mathbb{R}^d} \|v_t(x)\|_2^p d\mu_t(x) \right\}^{1/p} 
        \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2609.03512, ''] Let $G$ be a connected graph with $g(G)\neq 3$, $\gamma(G)=2.$ 
Let $D=\{u,v\}$ be a dominating set of $G$. Then $D$ is a total dominating set if and only if the following hold:
\begin{itemize}
\item $N(u)\cap N(v)=\emptyset,$ and
\item $\deg(u)+\deg(v)=|V(G)|.$
\end{itemize}

[Lemma l:exactcovfourier of arXiv:2411.08848, 'Stationary random measures: Covariance asymptotics, variance bounds and central limit theo'] Let ${\mathcal X}$ be a stationary random measure and let $f,g:\mathbb{R}^d\to \mathbb{R}$. Assume that
\begin{enumerate}
\item $\widehat {\bf K}$ is real analytic on $\mathbb{R}^d$.
\item $g$ is smooth. Further, $f,g$ and   partial derivatives of $g$ of all orders  are in $L^1\cap L^2$.
\item $\sum\limits_{\gamma \in \mathbb{Z}^d_+}  \frac{1}{\gamma!} |\partial^{\gamma}\widehat{{\bf K}}(0)| \, \,  \|\partial^{\gamma}g\|_2< \infty.$
\end{enumerate}

Then (equation eq:covarianceformulageneral of the paper) holds where the summands can be rewritten as follows:

 \begin{align}  
 Q_m^{{\bf K}}(f,g)=\begin{cases}
 (2\pi)^{-d}(\lambda_D + \widehat{{\bf K}}(0))\ \int \hat{f}(t)\overline{\hat{g}(t)}\mathrm{d} t  &\mbox{ if }m=0, \\
 (2\pi)^{-d}\sum\limits_{\gamma \in \mathbb{Z}^d_+:\ |\gamma|=m}\frac{\partial^{\gamma}\widehat{{\bf K}}(0)}{\gamma!}\int t^{\gamma}\hat{f}(t)\overline{\hat{g}(t)} \mathrm{d} t &\mbox{ if } m \ge 1. 
 \end{cases}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Extratheorem 2 of arXiv:2608.19179, 'A random walk on $p$-groups with a symmetric perfect pairing'] \cite{FriedmanWashington}

  If $\mathcal{M}_{k,k}$ is a random matrix whose entries are independent Haar distributed elements of $\Z_p$, $ker(\mathcal{M}_{k,k})$ is finite almost surely and:
  \begin{equation}

  \lim_{k \rightarrow \infty}\probP\Big( ker(\mathcal{M}_{k,k}) \cong G \Big) \propto \frac{1}{|Aut(G)|}
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem bt1 of arXiv:2603.05467, 'Thresholds for colouring the random Borsuk graph'] For $d\geq 2$, there is a constant $c_2=c_2(d)>0 $ such that for all fixed $\varepsilon>0 $ and all sequences $\alpha=\alpha(n)$ 
it holds that
\begin{equation*}
\lim_{n\to\infty}\mathbb{P}(\chi(G({n},\alpha)) > 2)=\begin{cases}
1 & \text{if }\alpha\geq (c_2+\varepsilon)\cdot n^{-1/d},\\
0 & \text{if }\alpha\leq (c_2-\varepsilon)\cdot n^{-1/d}.
\end{cases}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

