[Lemma 3 (Evolution of the area and its push-forward) of arXiv:2609.00501, 'Uniqueness of Finite-Time Varifold Limits for the M\"obius-Invariant Willmore Flow'] Let $X_t:=\partial_tF_t$.  Then the induced area measure on the fixed
domain satisfies
\begin{equation}

 \partial_t\dd\mu_t
 =-\langle H_t,X_t\rangle\dd\mu_t
 =a_t^{-2}\langle H_t,G_t\rangle\dd\mu_t.
\end{equation}
Moreover, for every $\varphi\in C^1(\Sph^3)$,
\begin{equation}

 \begin{aligned}
 \frac{\dd}{\dd t}\int_{\Sph^3}\varphi\dd\lambda_t
 &=\int_\Sigma
 \left[
  \big\langle\nabla^{\Sph^3}\varphi(F_t),X_t\big\rangle
  -\varphi(F_t)\langle H_t,X_t\rangle
 \right]\dd\mu_t\\
 &=\int_\Sigma a_t^{-2}
 \left[
  -\big\langle\nabla^{\Sph^3}\varphi(F_t),G_t\big\rangle
  +\varphi(F_t)\langle H_t,G_t\rangle
 \right]\dd\mu_t.
 \end{aligned}
\end{equation}

[Theorem thm:upper_bounds of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] Fix any $f_{\rm in} \in L^\infty_m$ for some $m > 2$ satisfying $0 \le f_{\rm in} \le 1$. Any classical solution $f\colon[0,T]\times \Omega \times \mathbb R^3 \to [0,1]$ to (equation e.LFD of the paper) with initial data $f_{\rm in}$ satisfies the pointwise bound
    \begin{equation*}
        \left\vertf(t,x,v)\right\vert \le e^{Kt} \frac{\norm{f_{\rm in}}_{L^\infty_m}}{\left\vertv\right\vert^m} \qquad \text{for each }(t,x,v) \in [0,T]\times \Omega\times \mathbb R^3.
    \end{equation*}
    Here $K = K(m)$ depends only only on $m$. The spatial domain $\Omega$ may be either $\mathbb T^3$ or $\mathbb R^3$.
    Consequently, the mass and energy densities satisfy
    \begin{equation}
        \rho(t,x) = \int_{\mathbb R^3} f(t,x,v) \, {\rm d} v \lesssim  e^{Kt} \|f_{\rm in}\|_{L^\infty_m}
        \qquad \text{and} \qquad E(t,x) = \int_{\mathbb R^3} \left\vertv\right\vert^2 f(t,x,v) \, {\rm d} v \lesssim e^{Kt}\|f_{\rm in}\|_{L^\infty_m},
    \end{equation}
    provided $m > 5$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem recur:lowerBound of arXiv:2607.09841, 'Mixing and cutoff for the systematic scan dynamics of the mean-field ferromagnetic Potts m'] Let $\{x_t\}_{t \geq 0}$ be a sequence of real numbers define for $t \geq n$ by
\begin{align*}
    x_t &= \frac{\beta}{nq}\sum_{i = t-n}^{t-1} x_i - \frac{C}{n} \sum_{i = t-n}^{t-1} \gamma_n^{2i} - \frac{\tilde C}{n},
\end{align*}
where $C, \tilde C > 0$ are constants. If for all $i \in \{0,\dots,n-1\}$, there exists a constant $\rho > 0$ such that
$x_i \geq \rho$, then there exists a constant $\hat C > 0$ such that
\begin{align*}
     x_t  \geq  (\rho - \hat C C) \gamma_n^t - \frac{\tilde C \hat C}{n}.
\end{align*}

