[Proposition 58 of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] Fix $k\in \NN,t\geq 1$ and let $\mathbf{a}\in \RR$ be such that $(\mathbf{a},\mathbf{a}+t)\subseteq [-n^{1/10},n^{1/10}]$. Define $U(\mathbf{a})=[\![1,k]\!]\times (\mathbf{a},\mathbf{a}+t)$. Then there exists a random sequence of continuous functions $\fL^{\mathbf{a}}=\fL^{t,k,\mathbf{a}}$ such that the following hold:
  \begin{enumerate}
  \item Almost surely, $\fL^{\mathbf{a}}$ satisfies $\fL_i^{\mathbf{a}}(r)>\fL_{i+1}^{\mathbf{a}}(r)$ for all $(i,r)\notin U(\mathbf{a})$.
  \item The line ensemble $\fL^{\mathbf{a}}$ satisfies the following Gibbs property. For $1\leq m\leq n+1$ and $-n^{1/3}/2<a<b<\infty$, set $S=[\![1,m]\!]\times [a,b]$. Then conditional on the data given by $\fL_i^{\mathbf{a}}(r)$ for $(i,r)\notin S$, the law of $\fL_i^{\mathbf{a}}(r)$ for $(i,r)\in S$ is given by independent Brownian bridges $B_1,\dots,B_\ell$ from $(a,\fL_i^{\mathbf{a}}(a))$ to $(b,\fL_i^{\mathbf{a}}(b))$ for $i\in [\![1,k]\!]$, additionally conditioned on having $B_i(r)>B_{i+1}(r)$ for all $(i,r)\notin U(\mathbf{a})$.
  \item There exists a constant $c_k$ for which we have
    \begin{equation}

      \PP(\fL_1^{\mathbf{a}}>\fL_2^{\mathbf{a}}>\dots>\fL_{n+1}^{\mathbf{a}})\geq e^{-c_kt^3}.
    \end{equation}
  \item There is an event $\cE$ which is measurable with respect to the data given by $\cP_i(r)$ for $(i,r)\notin U(\mathbf{a})$, satisfying for a positive constant $c_k$, the inequality
    \begin{equation}

      \PP(\cE^c)\leq e^{-c_kn},
    \end{equation}
    such that if we condition $\fL^{\mathbf{a}}$ on the event $\{\fL_1^{\mathbf{a}}>\fL_2^{\mathbf{a}}>\dots>\fL_{n+1}^{\mathbf{a}}\}$, then the resulting ensemble has the same law as $\cP$ conditioned on the event $\cE$. 
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2604.22130, 'Reflected Stochastic Differential Equations Driven by $G$-Brownian Motion with Nonlinear C'] Given two reflected $G$-BSDEs with parameters $(x^i,f^i,h^i,g,l,r)$, $i=1,2$ satisfying the assumptions in Theorem (thm5.9 of the paper), we additionally suppose the following condition.
\begin{itemize}
\item  For each $t\in[0,T]$, $g$ does not depends on $x$ and either $f^1(t,\cdot),g^1(t,\cdot)$ or $f^2(t,\cdot),g^2(t,\cdot)$ are nondecreasing.

\end{itemize}
Let $(X^i,A^i)$ be the solution to reflected $G$-SDE with parameters $(x^i,f^i,h^i,g,l,r)$ and $(A^{i,l},A^{i.r})$ be the associated constraining processes, $i=1,2$. Then, we have
\begin{itemize}
\item[(1)] $A^{1,l}_t\leq A^{2,l}_t\leq A^{1,l}_t+\hat{X}_t+(x^2-x^1)$;
\item[(2)] $A^{2,r}_t\leq A^{1,r}_t\leq A^{2,r}_t+\hat{X}_t+(x^2-x^1)$,
\end{itemize}
where $\hat{X}_t=\int_0^t f^2(s,X^2_s)-f^1(s,X^1_s)ds+\int_0^t h^2(s,X^2_s)-h^1(s,X^1_s)d\langle B\rangle_s$.

