[Corollary 53 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] For all $y \in \T^d$ and $h>0$,
    \[\P_U\big(\text{there exists more than one solution to~\eqref{eq:main refreshing ODE 0} on } [0,h]\big) = 1.\]
    Further, for all $y \in \T^d$ and almost surely in $U$, for all $\ep>0$ sufficiently small
    \begin{equation}
    \limsup_{t \to 0} t^{- \frac{1}{2-2\alpha - \beta - \ep}}\mathrm{diam}\{X_t : X \text{ is a solution to~\eqref{eq:main refreshing ODE 0}}\} =\infty.

    \end{equation}

[Thm 3.2 of arXiv:2608.00420, '{Weighted $L^p$ solutions of scalar BSDEs with general unbounded stochastic coefficients}\'] Let the generator $g$ satisfy assumption (A:H1 of the paper). Assume further that either $\mu_\cdot\in {\mathbb R}_+$ or (A:H1 of the paper)(iii) is replaced with the following stronger condition: $g$ has a general growth in $y$ and a stochastic linear growth in $z$, i.e., there exists a function $\phi_t(\omega,x)\in\mathbf{S}$ such that for each $(t,y,z)\in[0,\tau]\times{\mathbb R}\times{\mathbb R}^d$,
\begin{align}
|g(\omega,t,y,z)|\leq \phi_t(\omega,|y|)+\nu_t(\omega)|z|.
\end{align}
Then, for each $\xi\in L_\tau^p(\rho_\cdot;{\mathbb R})$, BSDE (equation BSDE1.1 of the paper) admits a solution $(y_t,z_t)_{t\in[0,\tau]}$ such that $y_\cdot\in S_\tau^p(\rho_\cdot;{\mathbb R})$. Furthermore, if the process $\rho_\cdot$ also satisfies
\begin{align}
\rho_t\geq \mu_t+\frac{\theta}{2[1\wedge(p-1)]}\nu_t^2, \ \ t\in[0,\tau],
\end{align}
then $z_\cdot\in M_\tau^p(\rho_\cdot;{\mathbb R}^{d})$.\vspace{0.1cm} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 26 (Isotropic sharpness) of arXiv:2608.10992, '2608.10992'] In the isotropic model,
\begin{equation}

        t_{\mathrm{sus}}^{\mathrm{iso}}
        =t_{\infty}^{\mathrm{iso}}
        =:t_c^{\mathrm{iso}}.
\end{equation}
Moreover,
\begin{equation}

        \frac13
        \leq t_c^{\mathrm{iso}}
        \leq t_c^{\mathrm{os}}
        \leq2\log2,
\end{equation}
and
\[
        \mathbb{P}(S_{t_c^{\mathrm{iso}}+s}=\infty)>0,
        \qquad s>0.
\]

[Proposition rep:ss of arXiv:2411.09949, '$W_{\bf d}$-convergence rate of EM schemes for invariant measures of supercritical stable '] Let $g\in {\mathcal C}_0$ and $\bar g=g-\mu(g)$. Then it holds that
\begin{align}
f(x):=\int^\infty_0P_t \bar g(x){\mathord{{\rm d}}} t\in{\mathcal D}({\mathcal A})\mbox{ and }{\mathcal A} f=-\bar g.
\end{align}

[Theorem 8 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$, $f\in \Sob^k(\Rbb^n,\gamma_n)$ with $\left\|f\right\|_{\Leb^\infty}\leq 1$, and $p\in [1,2)$,
\begin{equation}
    \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-iso-Gaussian}}}(p)^k\Wop^{\geq k}(f) \left[1+ \frac{1}{2k}\ln\left(\frac{1}{\Wop^{\geq k}(f)}\right)\right]^\frac{kp}{2},
\end{equation}
and further,
\begin{equation}
    \max_{\kappa\in \Nbb^n:|\kappa|=k}\left\|\Dop^\kappa f\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-iso-Gaussian}}}(p)^k\, \frac{\Wop^{\geq k}(f)}{\binom{n+k-1}{k}} \left[1+ \frac{1}{2k} \ln\left(\frac{\binom{n+k-1}{k}}{\Wop^{\geq k}(f)}\right)\right]^{\frac{kp}{2}},
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-iso-Gaussian}}}(p) = C^{\text{\rm\ref{thm:high-order-Tal-isoper-Boolean}}}(p) \gtrsim 2-p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 (Elementary inequalities on the finite probability space) of arXiv:2609.03993, 'The Endpoint Fractional Riesz Estimate on the Hamming Cube'] Let $1<p<\infty$ and $q=p/(p-1)$.
		\begin{enumerate}[label=\textup{(\roman*)}]
			\item For $u,v$ in a Hilbert space,
			$|\langle u,v\rangle|\le\|u\|\|v\|$.
			\item For nonnegative scalar functions $a,b$ on $\Om$,
			\begin{equation}
				\E(ab)\le(\E a^p)^{1/p}(\E b^q)^{1/q}.

			\end{equation}
			\item For every $H$-valued $F$ and $1\le r<\infty$,
			\begin{equation}
				\|\E F\|_H\le\E\|F\|_H\le\|F\|_{L^r(\Om;H)}.

			\end{equation}
		\end{enumerate}

[Lemma lem:technical1 of arXiv:2411.13707, 'High-degree cubature on Wiener space \\ through unshuffle expansions'] \[
\begin{aligned}
\sum_{1\leq i,j\leq d}(\epsilon_0,\epsilon_i^2,\epsilon_j^2)=\sum_{1\leq i,j\leq d}&\Big (\frac{2}{3}\xi_{0iijj}+\frac{1}{3}\xi_{ii0jj}+2(\xi_0,\xi_i,\xi_{ijj})+2(\xi_i,\xi_i,\xi_{0jj})\\
&+2(\xi_{0},\xi_{ij},\xi_{ij})+ \frac{8}{3}(\xi_i,\xi_{0j},\xi_{ij})+(\xi_{0},\xi_i,\xi_i,\xi_j,\xi_j)\Big ).
\end{aligned}
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 20 (Discrete-time crossing of a curved boundary) of arXiv:2608.20337, 'Information on trajectories:\\ martingales and random times'] Let $X=N+A$ be a discrete class-$(\Sigma)$ process and let $\varphi\colon\R_+\to(0,\infty]$ be Borel with $I:=\int_0^\infty\varphi(x)^{-1}\dd x<\infty$.
Write $w(x):=\exp\bigl(-\int_x^\infty\varphi(z)^{-1}\dd z\bigr)$, $\zeta:=1-w$ and $h:=w/\varphi$, so that $w'=h$ and $\zeta'=-h$, and assume $h$ is bounded.
Then $M_t:=\zeta(A_t)+h(A_t)X_t$ is nonnegative with $M_0=1-e^{-I}$, the crossing event is exactly
\begin{equation}
  \bigl\{\exists\,t:\ X_t>\varphi(A_t)\bigr\}
  =\bigl\{\sup\nolimits_t M_t>1\bigr\},
\end{equation}
and $M$ decomposes pathwise as
\begin{equation}
  M_t=M_0+\sum_{s\le t}h(A_{s-1})\,\Delta N_s+\sum_{s\le t}R_s,
  \qquad
  R_s:=h(A_{s-1})\,\Delta A_s-\bigl(w(A_s)-w(A_{s-1})\bigr),
\end{equation}
the first sum a martingale and $R_s=\int_{A_{s-1}}^{A_s}\bigl(h(A_{s-1})-h(z)\bigr)\dd z$ the quadrature residual of $h$ across the jump of $A$.
If in addition $h$ has finite total variation $\mathrm{var}(h)$ on $\R_+$, the jumps of $A$ are uniformly bounded, $A_t\to\infty$, and $M_t\to0$ off the crossing event, then with $T:=\inf\{t:X_t>\varphi(A_t)\}$ and overshoot $J:=M_T-1\ge0$,
\begin{equation}
  \PP\bigl(\exists\,t:\ X_t>\varphi(A_t)\bigr)
  =1-e^{-I}
   +\E\Bigl[\sum_{s\le T}R_s\Bigr]
   -\E\bigl[J\,\ind\{T<\infty\}\bigr].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem finite-n-characteristic-moments of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Let $\phi:[0,\infty)\to\mathds{R}$ satisfy $|\phi(a)|\leqslant Ce^{\eta a}$ for some $\eta<1$. Define $h_{n,\phi}(t) := e^{-\alpha_nt}\E Z_n^\phi(t)$ and $\mathcal{Z}_{n,\phi}(t) := e^{-\alpha_nt}\bigl(Z_n^\phi(t)-\E Z_n^\phi(t)\bigr)$ for $t\geqslant0$ (and zero otherwise). Then
\begin{align}
 \sup_{n\geqslant n_0}\sup_{t\geqslant0} \left( \abs{h_{n,\phi}(t)} + \E\abs{\mathcal{Z}_{n,\phi}(t)}^2 \right) <\infty.
\end{align}
If, moreover, $\sup_{n\geqslant n_0} \bigl( \sup_{a\geqslant0}e^{-\alpha_na}\left\vert\phi(a)\right\vert + \operatorname{TV}_{[0,\infty)} \bigl(e^{-\alpha_n\cdot}\phi\bigr) \bigr) <\infty$, there exists $C_\phi<\infty$ such that, for any interval $I$ of length at most one,
\begin{align}
 \E\sup_{t\in I} \abs{ \sum_{j=1}^m a_j\mathcal{Z}_{n,\phi}^{(j)}(t-b_j) }^2 \leqslant C_\phi\sum_{j=1}^m a_j^2
\end{align}
for all $a_j\in\mathds{R}$, $b_j\geqslant0$, and independent copies $\mathcal{Z}_{n,\phi}^{(j)}$, uniformly in $n\geqslant n_0$.

