        \sum_{n}\frac{\Psi(g^{\alpha}_{n})}{\|g^{\alpha}_{n}\|_{\infty}}=+\infty.
    \end{equation}

    Then, Condition \eqref{eq:conditioncontractralphaaa} holds true.

