[Theorem OptimalPWConcentration of arXiv:2609.02541, 'A note on the norm of the embedding of $\text{PW}^2$ into $\text{PW}^q$'] Let $S \subset \mathbb{R}$ be a measurable set with $0 < |S| < \infty$ and $g$ be any function of $PW^2$ with $\|g\|_{2}=1$. Then
\begin{align*}
     \int_{0}^{|S|}u^{*}(x) dx \leq \sup_{\substack{f\in PW^2\\ \|f\|_2=1}} \int_{-|S|/2}^{|S|/2}|f(x)|^2 dx = \lambda(|S|).
\end{align*}
Here $u^{*}$ denotes the decreasing rearrangement of $|g|^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Finite-entropy criterion for the entropic CCLT) of arXiv:2608.30579, '2608.30579'] Let $(\xi,\eta )$ be a pair of random variables. 
    Let $\{(\xi_i,\eta_i)\}_{i\geq 1}$ be independent copies of $(\xi,\eta)$.
	  Define
	  \begin{equation}
					W_n = \frac{\xi_1 + \xi_2 + \cdots + \xi_n}{\sqrt{n}}, 
			\quad \boldsymbol{\eta}_{n}= (\eta_1, \ldots, \eta_n).	
	  \end{equation}
			Assume that
\begin{equation}
			\sigma^{2} \triangleq\mathbb{E}\,\operatorname{Var}(\xi  \vert \eta) < \infty, 
		\quad (\xi \vert \eta) \ll \mathcal{L}, \ P_{\eta} \text{-a.s.},
\end{equation}
			where $\mathcal{L} $ denotes Lebesgue measure and the notation $\nu \ll \mathcal{L}$ indicates that $\nu$ is 
			absolutely continuous with respect to  $\mathcal{L}$. Define
	\begin{equation}
	h_{n}= \mathbb{E}\, h\!\left(W_{n} \vert \boldsymbol{\eta}_{n}\right).		
	\end{equation}		
			Then the convergence
\begin{equation}
			\lim_{n \to \infty} h_n = \frac{1}{2} \log (2\pi e \sigma^2)
\end{equation}
holds if and only if there exists $n_0 \geq 1$ such that
\begin{equation}
	h_{n_{0}}= \mathbb{E}\, h\!\left(W_{n_0} \vert \boldsymbol{\eta}_{n_{0}}\right) > -\infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 19 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let us keep the context fixed in the beginning of this section. 
Then there exists a right process $X^K$ on $E$,
\begin{equation*}
X^K=\left(\Omega^K,\mathcal{F}^K,\mathcal{F}^K(t),X^K(t)=(X^K_1(t),X^K_2(t)),\mathbb{P}^K_{s,x}, (s,x)\in E, t\geq 0\right)
\end{equation*}
which has a.s. c\`adl\`ag trajectories with respect to the (trace of the) norm topology on $E$, and such that the following properties hold:
\begin{enumerate}
    \item[(i)] For $(s,x)\in E$ we have
            \begin{equation*}
            \mathbb{P}^K_{s,x}\left( X_1^K(t)= t+s; 0\leq t<\infty  \right)=1.
            \end{equation*}
    \item[(ii)] For every $\psi\in pb\left(\mathcal{B}(\mathbb{R}^d)\otimes\mathcal{B}(\mathbb{R}^d)\right)$, $ \psi(y,y)=0, y\in \mathbb{R}^d$, we have
    \begin{equation*}
    \mathbb{E}^K_{s,x}
    \left\{\sum_{r\leq t}
    \psi(X_2^K(r-), X_2^K(r))\right\}
    =
    \mathbb{E}^K_{s,x}
    \left\{\int_0^t \int_{\mathbb{R}^d} 
    \psi(X_2^K(r), y) K(s+r,X_2^K(r), dy) dr\right\}, \quad t\geq 0.
    \end{equation*}
    \item[(iii)] If there exists $\delta_V \in (0,\infty)$ and $0\leq V\in C^2(\mathbb{R}^d)$ such that
    \begin{equation*}
        \overline{\sf L}V\leq \delta_V V \quad\mbox{and} \quad K(t,x,V(\cdot))\leq \delta_V V(x), \;t\geq 0, x\in \mathbb{R}^d,
    \end{equation*}
    then the transition semigroup $(P^K_t)_{t\geq 0}$ of $X^K$ satisfies
    \begin{equation*}
        P^K_t V\leq e^{2\delta_V t} V, \quad t\geq 0.
    \end{equation*}
    Moreover, the bound \eqref{eq:doob} holds for $X_2^K$ instead of $X_2$ and $2\delta_V$ instead of $\delta_V$.
    \item[(iv)]  We have that $\mathcal{L}^K$ coincides with the generator on $b\mathcal{B}(E^K)$ associated to $X^K$ in the sense given by \eqref{eq:D(L)_weak}, $\mathcal{D}_b(\mathcal{L})=\mathcal{D}_b(\mathcal{L}^K)$, and for every $f\in \mathcal{D}_b(\mathcal{L})=\mathcal{D}_b(\mathcal{L}^K)$ and every $(s,x)\in E$, the process
    \begin{equation}
        f(X^K(t))-  f(X^K(0)) -\int_0^t \mathcal{L}^Kf\left(X^K(s)\right) ds,\quad t\geq 0,
    \end{equation}
    is a c\`adl\`ag $(\mathcal{F}^K(t))$-martingale under $\mathbb{P}^K_{s,x}$.
\end{enumerate}

