[Thm 75 ({\cite[Theorems 1.5(ii) and 1.7) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {BTM24}}]
Let $\alpha>2$ and $E\in \left(0,\frac{\alpha-2}{10(2\alpha-1)}\right)$.
Then it holds for any $K\in (0,\infty)$ and $0<T_1<T_2<\infty$ that
\begin{equation*}
  \sup_{x\in \R}|P_0(X_1\le x)-P^n_0(X^n_1\le x)|=O(n^{-\theta}),
\end{equation*}
and
\begin{equation*}
  \lim_{n\to\infty}n^{\frac{2}{3}E}\sup_{\substack{|x|\le K\\t\in [T_1,T_2]}}\left| p(t,0,x)-p_n\left( t,0,\frac{\floor{nx}}{n} \right) \right|=0,
\end{equation*}
$P$-almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2609.01885, 'The Order of the Non-universal Tree of a Hilbert Space with Respect to the Haar Basis'] Let $T$ be a tree on a set $A$. An \textbf{infinite hand} in $T$ is a sequence $(s_n)_{n=0}^\infty\subseteq T$ with the following properties:
\begin{enumerate}
\item $(|s_n|)_{n=0}^\infty\subseteq\mathbb N$ is strictly monotone increasing.
\item There exists an element $s\in T$ with $s\sqsubset s_n$ for every $n$; the element of largest length which satisfies this property is called the \textbf{palm} of the infinite hand.
\end{enumerate}

[Lemma lem:two-point-decompose of arXiv:2605.19419, 'Tail exponents of the three-dimensional uniform spanning tree and Abelian sandpile'] Suppose $4r<R$ and $x\in\partial B_R$, $y\in\partial B_r$. Suppose that $\gamma$ is an ILERW started from $0$. $S_{1}$ and $S_{2}$ are two independent SRWs started from $x$ and $y$. Write $P_{x,y}$ for their joint law. Let $E$ denote the intersection of the following events:
\begin{itemize}
\item[1.]\ $S_{1}$ hits $0$ and, writing $\tau_{1}$ for the first hitting time of $0$, $S_{1}[0,\tau_{1}]\cap\gamma=\{0\}$.
\item[2.]\ $S_{2}$ hits $\operatorname{LE}(S_1[0,\tau_1])$ before it intersects $\gamma$.
\end{itemize}
Then,
\begin{equation}
P_{x,y}(E)\gtrsim (\log r)^{-1}R^{-1-\alpha}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] Let	$N_n:=\{(i,j):1\leq i,j\leq n,\ i\neq j\}$, 
	and suppose $(Z_{ij})_{(i,j) \in N_{n}}$ is given by expression \ref{eqn:Z.Fform}. Then, for any directed matching block  \(B\subseteq N_n\),\footnote{Meaning that for any two distinct dyads
		\((i,j),(k,\ell)\in B\), $\{i,j\}\cap\{k,\ell\}=\varnothing$.}
	\begin{align}
		\Gamma^{\mathrm{sum}}_p(B) = 	\Gamma^\sharp_p(B) =1,~\forall p \in (1,\infty),
	\end{align}
	and
	\begin{align}
		\Gamma^{\mathrm{sum}}_1(B)
		=
		\Gamma^\sharp_1(B)
		=
		\sqrt{|B|},~for~p=1
	\end{align}

