[Proposition 3 (Calabi symmetry = the ansatz over $\mathbb{CP}^{n-1}$) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] Calabi symmetry is precisely the circle-bundle ansatz \eqref{eq:ansatz-metric} satisfying the Kähler condition \eqref{eq:kahler-condition} with the following data:

	\begin{itemize}
		\item \textbf{Number of factors and base:} $r = 1$, $N = N_1 = \mathbb{CP}^{n-1}$ (so $n_1 = n - 1$), with $g_1 = 2\, g_{FS}$, $p_1 = n$;
		\item \textbf{Circle bundle:} $P = S^{2n-1} \subset \mathbb{C}^n$ the unit sphere, with the $\mathrm{U}(1)$-action $z \mapsto e^{\sqrt{-1}\varphi} z$ and $\pi : S^{2n-1} \to \mathbb{CP}^{n-1}$ the Hopf fibration, i.e. $e(P) = a_1$ and $q_1 = 1$;
		\item \textbf{Vertical field:} $\xi = \sqrt{-1} \sum_{j=1}^n \big( z_j \partial_{z_j} - \bar{z}_j \partial_{\bar{z}_j} \big)$, the generator of the scalar rotation;
		\item \textbf{Connection form:} $\theta = \frac{\sqrt{-1}}{2} \big( \bar{\partial}\rho - \partial\rho \big)$ (the form denoted $\eta$ in parts of the literature);
		\item \textbf{Identification of the manifold:} $I \times S^{2n-1} \xrightarrow{\;\cong\;} \mathbb{C}^n \setminus \{0\}$ (or an annulus), $(s, p) \mapsto e^{\rho(s)/2}\, p$, where $s$ and $\rho$ are related by $ds = \sqrt{u_{\rho\rho}/2}\; d\rho$;
		\item \textbf{Warping functions:}
	\end{itemize}

	\begin{equation}
		H \;=\; \sqrt{2\, u_{\rho\rho}}, \qquad F_1 \;=\; \sqrt{u_{\rho}} \qquad (\text{composed with } \rho = \rho(s)).
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem t:Girsanov of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Fix~$\pi\in\msP(\mbfT_\circ)$ and suppose that Assumption~(ass:Girsanov of the paper) is satisfied.
Then, the quadratic form~$\big({\widehat\mcE_\pi^\phi,\msD(\widehat\mcE_\pi^\phi)}\big)$ defined by
\begin{equation}
\begin{gathered}
\msD(\widehat\mcE_\pi^\phi)\eqdef \set{u\in \msD(\widehat\mcE_\pi)^\bullet_{\loc} \cap L^2(\mcQ_\pi^\phi) : \int_\msP \widehat\mcG_\pi(u)\, \mathop{}\!\mathrm{d}\mcQ_\pi^\phi<\infty }\,\mathrm{,}\;\,
\\
\widehat\mcE_\pi^\phi(u,v)\eqdef \int_\msP \widehat\mcG_\pi(u,v)\, \mathop{}\!\mathrm{d}\mcQ_\pi^\phi \,\mathrm{,}\;\, \qquad u,v\in \msD(\widehat\mcE_\pi^\phi) \,\mathrm{,}\;\, 
\end{gathered}
\end{equation}
is a $\tau_\mrma$- and $\tau_\mrmn$-quasi-regular local Dirichlet form on~$L^2(\mcQ_\pi^\phi)$.

If, additionally,
\begin{equation}
\phi\in L^2(\mcQ_\pi) \qquad \text{and} \qquad\int \widehat\mcG_\pi(\phi) \mathop{}\!\mathrm{d} \mcQ_\pi <\infty \,\mathrm{.}
\end{equation}
Then, 
\begin{enumerate}[$(i)$]
\item the form~$\big({\widehat\mcE_\pi^\phi,\msD(\widehat\mcE_\pi^\phi)}\big)$ is additionally strongly local and recurrent;
\item for the generator~$\big({\widehat\mcL_\pi^\phi,\msD(\widehat\mcL_\pi^\phi)}\big)$ of~$\big({\widehat\mcE_\pi^\phi,\msD(\widehat\mcE_\pi^\phi)}\big)$ we have~$\hCylP{}{0}\subset \msD(\widehat\mcL_\pi^\phi)$ and
\[
\widehat\mcL_\pi^\phi u= \widehat\mcL^\phi u\eqdef \widehat\mcL u+\phi^{-1}\,\widehat\mcG_\pi(\phi, u) \quad \text{on}\quad \hCylP{}{0} \,\mathrm{.}
\]

\item $\big({\widehat\mcE_\pi^\phi,\msD(\widehat\mcE_\pi^\phi)}\big)$ is properly associated with the $\mcQ_\pi^\phi$-symmetric process~$\widehat\mcW_\pi^\phi$, which is thus recurrent (in particular: conservative) and a right Borel process for both~$\tau_\mrma$ and~$\tau_\mrmn$;

\item a $\mcQ_\pi^\phi$-measurable set~$\mbfA\subset \msP$ is $\widehat\mcE_\pi^\phi$-invariant if and only if it is $\widehat\mcE_\pi$-invariant;

\item 
$\widehat\mcW^\phi_\pi$ is a solution to the martingale problem for~$\ttparen{\widehat\mcL^\phi,\hCylP{}{0}}$. 
In particular, for every~$u\in\hCylP{}{0}$ ($\subset \mcC_b(\tau_\mrma)$), the process
\begin{equation}
M^{\class{u}}_t\eqdef u(\widehat\mcX^{\pi,\phi}_t)- u(\widehat\mcX^{\pi,\phi}_0)-\int_0^t (\widehat\mcL^\phi u)(\widehat\mcX^{\pi,\phi}_s)\mathop{}\!\mathrm{d} s
\end{equation}
is an adapted square-integrable martingale with quadratic variation
\begin{equation}
\tquadvar{M^{\class{u}}}_t = \int_0^t \widehat\mcG(u)(\widehat\mcX^{\pi,\phi}_s)\mathop{}\!\mathrm{d} s \,\mathrm{.}
\end{equation}
\end{enumerate}

Finally, suppose, in addition to~(equation eq:t:Girsanov:00 of the paper), that
\begin{equation}
\phi^2\in L^2(\mcQ_\pi) \qquad \text{and}\qquad \int \phi^2\, \widehat\mcG_\pi(\phi)\mathop{}\!\mathrm{d}\mcQ_\pi <\infty\,\mathrm{.}
\end{equation}
Then, additionally,
\begin{enumerate}[$(i)$, resume]
\item
$\hCylP{}{0}$ is a form core for~$\big({\widehat\mcE_\pi^\phi,\msD(\widehat\mcE_\pi^\phi)}\big)$.

\item 
$\widehat \mcL^\phi \hCylP{}{0}\subset L^1(\mcQ_\pi^\phi)$ and there exists a unique strongly continuous semigroup on~$L^1(\mcQ_\pi^\phi)$ the generator of which extends~$\tparen{\widehat\mcL^\phi,\hCylP{}{0}}$.
In particular, the self-adjoint operator $\big({\widehat\mcL_\pi^\phi,\msD(\widehat\mcL_\pi^\phi)}\big)$ is the unique Markovian extension of $\tparen{\widehat\mcL_\pi^\phi,\hCylP{}{0}}$, and~$\big({\widehat\mcE_\pi^\phi,\msD(\widehat\mcE_\pi^\phi)}\big)$ is the unique Dirichlet form extending~$\tparen{\widehat\mcE_\pi^\phi,\hCylP{}{0}}$;

\item 
$\widehat\mcW_\pi^\phi$ is the unique ---up to~$\mcQ_\pi^\phi$-equivalence--- $\mcQ_\pi^\phi$-sub-stationary $\mcQ_\pi^\phi$-special standard process solving the martingale problem~(equation eq:t:Girsanov:1 of the paper).
\end{enumerate}

