[Proposition 15 (Boundary quotient rigidity) of arXiv:2609.03339, 'Exterior Serrin Rigidity for the Homogeneous \texorpdfstring{$k$}{k}-Hessian Equation\\'] Let $2\le k<n$.  Suppose $\partial\Omega$ is smooth, connected,
		strictly star-shaped, and strictly $k$-convex.  If, for some $b>0$,
		\begin{equation}
			H_k\ge qbH_{k-1},
		\end{equation}
	\begin{equation}
			I_{k-1}=b\frac{n-k+1}{k-1}I_{k-2},
	\end{equation}
		where $q=(n-k)/k$, then $\partial\Omega$ is a round sphere of radius
		$b^{-1}$.

[Proposition 8 (Convergence of the energy and of the corrector) of arXiv:2604.21143, 'Quantitative homogenization for the critical long-range random conductance model'] Under Assumption~\textup{(U)}, there exists a constant $C = C(d, U, \lambda) < \infty$ such that, for every $\eps \in (0,1)$ and every $p \in \Rd$,
		\begin{equation}

			\nu(U^\eps, p) + \|\phi_p^\eps\|_{H^1_{\mathrm{crit}}(U^\eps)}^2
			\le \frac{C|p|^2}{|\ln\eps|}
			+ \mathcal{O}_1\left(\frac{C|p|^2\eps^d}{|\ln\eps|}\right)
			+ \mathcal{O}_2\left(C|p|^2 \eps^{d/2}\right).
		\end{equation}

