[Lem 49 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] Suppose that there are $y_1$ strings equal to $s_i$ among $\widehat {\mathbf a}_i$.
        Then for all $\widetilde{\mathbf a}\in \cS^p_{\geq_{\lex}s_i}(m,y_{p,i}-y_1)$, we have
        \begin{equation}

            \mu_{\mathbf a_i} \lt( \widehat{\mathbf a}^{\rem,m}_i=\widetilde{\mathbf a}| \widehat{\mathbf{a}}^m_i \rt)  
            = 
            \frac{ \nu_{\mathbf a_i, \widehat{\mathbf a}^m_i}(\widetilde{\mathbf a})}
            {\sum_{\widetilde{\mathbf a} \in \cS^p_{\geq_{\lex}s_i}(m,y_{p,i}-y_1)} \nu_{\mathbf a_i, \overline{\mathbf a}^m_i}(\widetilde{\mathbf a})},
        \end{equation}
        where
        \begin{equation} 
            \nu_{\mathbf a_i, \widehat{\mathbf a}^m_i}(\widetilde{\mathbf a})=\prod_{t=1}^{K-1}\prod_{j=1}^{m}\frac{ \overline n_{\widetilde{s}_j[t]}^{(t),m,\rem}-\sum_{i<j} 1_{\widetilde{s}_i[t]=\widetilde{s}_j[t]}}{N-n_l^{(1)}+j}.
        \end{equation}
        For all $\widetilde{\mathbf a}\in (\cS^p_{\geq_{\lex}s_i})^m \setminus \cS^p_{\geq_{\lex}s_i}(m,y_{p,i}-y_1)$, we have $\mu_{\mathbf a_i} \lt( \widehat{\mathbf a}^{\rem,m}_i=\widetilde{\mathbf a}| \widehat{\mathbf{a}}^m_i \rt)=0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 7 (Elliptic a priori estimates) of arXiv:2605.12175, 'Hypocoercive Langevin dynamics on the Lie group $\textbf{SE}(2)$'] Assume that $\Phi: \mathbb{R}^2 \rightarrow \mathbb{R}$ satisfies \emph{(C1)}, \emph{(C2)} and \emph{(C3)}, $\sigma \in (0, \infty)$, and $f\in D$. Then for all
$f\in D$, the following estimates hold:

\begin{equation*}
    \begin{aligned}
        \|BSf\| \leq c_1 \|(I-\Pi_{\#})f\|, \qquad \|BA(I-\P)f\| \leq c_2 \|(I-\Pi_{\#})f\|, 
    \end{aligned}
\end{equation*}

\noindent where $\Pi_{\#}$ is either $\P_{\S}$ or $\P$, and the constanst are given by $c_1 = \frac{\sigma^2}{4}$, and $c_{2} \in (0, \infty)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:new of arXiv:2604.25851, '{Non-uniqueness of nonlinear Markov processes in the sense of McKean associated with parab'] Let $(u(t,\cdot))_{t>0} \subseteq  \mathcal P_* $ be a distributional solution to the FPE (equation eq:Main_FPE_our_paper of the paper) in the sense of (def:FPE-sol of the paper) with initial condition $\zeta \in \mathcal P$ and coefficients $(a, b): \mathbb{R}^d \times \mathcal P_* \to \mathbb{R} \times \mathbb{R}^d$ for some $\mathcal P_* \subseteq \mathcal P_{\textup{ac}} $, and assume further (equation eq:integrability_our_paper of the paper). Let $f: \mathbb{R}^d \times \mathcal D(f) \to \mathbb{R} $ with $\mathcal D(f) \subseteq \mathcal P_{\textup{ac}}$ be as in (lem:many-PDEs_new of the paper),
        and assume further
        \begin{equation}
            \big[(t,x)\mapsto f(x,u(t,\cdot))\big] \in L^1_{\textup{loc}}(\mathbb{R}_+;W^{1,1}(\mathbb{R}^d)).
        \end{equation}
        Then there exists a weak solution $(X_t)_{t\geq 0}$ to 
        \begin{equation}
        \begin{dcases}
            dX_t = \left( b(X_t,u(t,\cdot)) + \frac{\nabla f(X_t,u(t,\cdot))}{u(t,X_t)} \right) dt + \sqrt{2}\left( a(X_t,u(t,\cdot)) + \frac{f(X_t,u(t,\cdot))}{u(t,X_t)} \right)^{\frac{1}{2}} dW_t, \\
            \mathcal{L}(X_t) = u(t,x)dx,\quad t>0,
        \end{dcases}
    \end{equation}
    with $\mathcal{L}(X_0) = \zeta$, with the same convention for the coefficients on $\{u=0\}$ as in (lem:many-PDEs_new of the paper).

[Theorem Upper bound of cumulants GUE of arXiv:2411.11341, 'Ultra high order cumulants and quantitative CLT for polynomials in Random Matrices'] Let $\mathcal{X}\sim $ GUE or GOE. Consider the polynomial $P(\mathcal{X},\mathcal{D})$ in ((def of P of the paper)) and the random variable $\mathbf{X}$ defined in ((object of the paper)). Suppose that $\mathbf{C}_1$ is satisfied. 
Then there exists a constant $\theta_1\equiv \theta_1 (K, M, t)\in (0, 1)$ such that 
\begin{align}|K_r(\mathbf{X})|\leq \frac{r!^{\frac{M}{2}}}{(\theta_1 N)^{r-2}}, 
\end{align}
for any $N$ and $r\geq 3$. (Proof in the paper; no proof environment follows the statement in the TeX.)

