body:
[Lemma 29 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $x \geq 0$. Assume that, for any $\eta > 0$ and $\pi_0 \in \Sym_n$, there exist $\gamma > 0$, a random subset $\Neg \subseteq \Sym_n$, and a function $F: B(\pi_0, x - \eta) \setminus \Neg \to \mc{P}(\Sym_n)$ verifying the following conditions.

    \begin{enumerate}
        \item if $\pi \in \Dom F$, $|F(\pi)| \geq e^{\gamma n \log n}$;
        \item if $\pi \in \Dom F$ and $\pi' \in F(\pi)$, $\Proba(\pi'| G, H, (p_e)) \geq e^{-o_{\Proba}(n \log n)} \Proba(\pi| G, H, (p_e))$;
        \item if $\pi' \in \Sym_n$, $|F^{-1}(\pi')| \leq e^{o_\Proba(n \log n)}$ (uniformly over $\pi'$);
        \item $\Proba(\pi^* \in \Neg) = o(1)$.
    \end{enumerate}
    Then, if $\hat{\pi}$ is an estimator of $\pi^*$, there exist at least $x(n - o_\Proba(n))$ vertices $v \in [n]$ such that $\hat{\pi}(v) \neq \pi^*(v)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition Finite propagation of arXiv:2604.08154, '\small Hydrodynamic limit of the directed exclusion process'] There exist constants $v, C>0$ such that the following holds. For any $x<y$ in $\mathbb{Z}$,
	any $(\zeta_0,\xi_0)\in \mathbf{X}^2$, and any
	\begin{equation}
	0<t<\frac{y-x}{2v}\; \text{,}\;\;
	\end{equation}
	if $\eta_0$ and $\xi_0$ coincide on the interval $[x,y]\cap\mathbb{Z}$, then
	\begin{equation}
	\mathds{P}\Bigl(
	\eta(\zeta_0,\omega,s)(z)=\eta(\xi_0,\omega,s)(z)
	\ \text{for all } z\in [x+vt,y-vt]\cap\mathbb Z
	\text{ and } s\in[0,t]
	\Bigr)
	\ge 1-e^{-Ct}\; \text{.}
	\end{equation}

[Proposition pro: Lp norm of q_infty of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{($L^p$ norm of queue length)} For SSQ, under assumption (ass:heavy_overload of the paper), the $L^p$ norm of the centered queue length is bounded in the below interval
    \begin{align}
        \| \hat{q} \|_{L^p} &\leq \min\{(C_{1,\lambda,\mu}\sqrt{\frac{1}{\gamma}} \sqrt{p} + C_{2,\lambda,\mu} p),  (C_{3,\lambda,\mu} \frac{p}{\log(1+\gamma p/\lambda)})\} \\
        \| \hat{q} \|_{L^p}&\geq C_{4,\lambda,\mu} \exp\left( -C_{5,\lambda,\mu} \frac{1}{ \gamma p} \right) \frac{p}{\log(1+\gamma p/\lambda)} 
    \end{align}
    All the above constants are only dependent on $\lambda, \mu, C$ and $\alpha$. Their closed forms are given in (equation eq: constants for L-p norm of the paper) (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition dhe of arXiv:2609.03926, 'Overcolored Partition $k$-tuples Restricted by Parity of the Parts'] {wom}}}] 
	A modular form $f(z)\in M_k(\Gamma_0(N), \chi)$ is called a Hecke eigenform if for every $m\ge 2$ there is a complex number $\lambda(m)$ for which
	\begin{align}
		f(z)\mid T_m=\lambda(m)f(z).
	\end{align}

[Proposition prop.finite of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] Let $\pi_k$ be the initial distribution of $Q_1$ in the case of (equation initial of the paper) after taking the limit $\lambda \uparrow x, \mu \downarrow x$. We have
    \begin{equation}
        \pi_k = \frac{\left(q;q\right)_{\infty}}{\left(q;q\right)_{k}} q^k.
    \end{equation}
    In addition, $Q_1$ has finite mean for any fixed $q \in [0,1)$ 
    \begin{equation}
        \mathbb{E}\left[Q_1\right] < \infty.
    \end{equation}

[Theorem 7 of arXiv:2506.22213, 'No arbitrage assumption implies the differentiability of derivative pricing function'] Let $\hat{X}$ be an $m$-dimensional continuous Markov semimartingale starting at $x\in\bbR^m$ and satisfy SDE
    \begin{align}

        d\hat{X}_t=b(V_t,\hat{X}_t)dV_t+\sigma(V_t,\hat{X}_t)dN_t;\quad \hat{X}_0=x,
    \end{align}
    where $N$ is an adapted local martingale with $\langle N,N \rangle_t=V_t$, and $V$ is an adapted strictly increasing continuous finite variation process. Suppose $b,\sigma$ satisfy Assumption \ref{sde assumption}. We further assume SDE \eqref{ito sde} with coefficients $(b,\sigma)$ has a unique strong solution, for instance, $\sigma$ is Lipschitz. Then $(f(V_t,\hat{X}_t))_{t\geq 0}$ is a semimartingale if and only if $f\in \hat{V}^L_\mu(loc)$, and it has decomposition
\begin{align}

    f(V_t,\hat{X}_t)=f(0,\hat{X}_0)+\int_0^t f_x(V_s,\hat{X}_s)d\hat{X}_s+ A_t^f
\end{align}
where $A^f$ is uniquely determined by the relation
\begin{align}
    E\int_0^\infty\psi(V_s,\hat{X}_s)dA_s^f=\iint\psi(s,x)\nu^L_f(ds,dx)
\end{align}
for each bounded continuous function $\psi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:PCM of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] \medskip \noindent  A random vector $X=(X_{1},\ldots ,X_{d})$
is \textit{paired countermonotone}, or PCM, with respect to the pairing (\ref
{2050}), if:

\begin{enumerate}
\item for each $r=1,\ldots ,m$, the pair $(X_{2r-1},X_{2r})$ is
countermonotone in the bivariate sense;

\item the blocks 
\begin{equation*}
(X_{1},X_{2}),\ (X_{3},X_{4}),\ldots ,(X_{2m-1},X_{2m})
\end{equation*}
are independent.
\end{enumerate}

[Lemma lem: threshold for null initial condition of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] Recall from (equation eq: equilibrium threshold of the paper) that
	\begin{equation*}
		y_* \vcentcolon= \inf\asetc{y \geq 0}{\lambda_0\int_0^y S_g(u, u)du \geq 1},
	\end{equation*}
	where $y_* \vcentcolon= \infty$ if the integral is strictly less than one for all $y \geq 0$. Suppose that $\boldsymbol{\mu} \in \mathcal{S}^+$ has initial condition the null measure. Then
	\begin{equation*}
		\bar y_*(\boldsymbol{\mu}_t) = \begin{cases}
			\infty 	& \text{if} \quad 0 \leq t < y_*, \\
			y_* 	& \text{if} \quad y_* < \infty \quad \text{and} \quad t \geq y_*.	
		\end{cases}
	\end{equation*}

