body:
[Satz thm:sufficiency-log of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d,k\in\mathds{N}$, $s,\alpha,\beta,\gamma,\theta\in\mathds{R}$, and $p,q\in (0,\infty]$.
Assume that $a$ follows a Besov sequence prior and $f$ follows a Besov prior, both with parameters $(\alpha,\beta,\gamma,\theta,k)$ and template random variable $X$, satisfying
\begin{equation}
\begin{cases} \:\exists\: \eps>0:\,\mathds{E}\bigl[\left\lvertX\right\rvert^p \cdot \log_2^+(\left\lvertX\right\rvert)\bigr]< \infty&\text{if }p\in (0,\infty),\\
\:\exists\:  R>0:\, \left\lvertX\right\rvert\stackrel{a.s.}{\leq}R&\text{if }p=\infty.\end{cases}
\end{equation}
If Property A holds, then $a$ almost surely belongs to $b^s_{p,q}(\mathds{R}^d)$.
Moreover, if Properties A and B are satisfied, then $f$ belongs almost surely to $B^s_{p,q}(\mathds{R}^d)$.

[Proposition prop:estimate_hyperfluctuating_case of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] \begin{equation*}
			s_{\xi_B}(t)-\bar{s}_{\xi_B}(t) \underset{t\to 0}{=}O(1).
		\end{equation*}

[Lemma L1 of arXiv:2608.22945, 'A Momentum-Based Variance-Reduced Algorithm for Federated Multiobjective Optimization'] Under Assumption (A1 of the paper), if $\gamma L \leq \frac{1}{2}$, then, for all $t\ge 0 $,
\begin{align*}
	\mathbb{E}[f_s(x^{t+1})]\leq \mathbb{E}[f_s(x^t)]-\frac{\gamma}{4}\mathbb{E}[\|g^t\|^2]+\frac{\gamma}{2}\mathcal{E}_s^t, \quad s \in [S].
\end{align*}
and
\begin{align*}
     \frac{2\left(\mathbb{E}[f_s(x^T)]-f_s(x^0)\right)}{\gamma}+\frac{1}{2}\sum_{t=0}^{T-1}\mathbb{E}[\|g^t\|^2]\leq\sum_{t=0}^{T-1}\mathcal{E}_s^t, \quad s \in [S].
\end{align*}

[Thm Bup of arXiv:2504.14036, 'Darwinian evolution in Malthusian population growth model and Markov chains'] The population is bounded at all times, i.e., there exists an upper bound 
\begin{gather}
B_{up} := \max\left(\frac{(\|1-f_{mut}\|_2 + b\|F_{mut}\|_{\infty})^2}{4b\|F_{mut}\|_{\infty}}\cdot K, K, \|P_0\|_1\right)

\end{gather}

\noindent
such that $\|P_n\|_1 \leqslant B_{up}$ for all $n\in\mathbb{N}_0.$

