[Proposition prop:exact_values of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] Let~$\tau $ and~$\sigma^2$ be as above and set~$a_k=\alpha_k\beta_{k-1}^{-1}$ and~$b_k=\alpha_k^{-1}\beta_k$. Then
\begin{equation}
\tau =
\sum_{k=1}^\ell \frac{1+a_k+a_kb_k+a_kb_ka_{k+1}}
{(1+a_k)(1+b_k)(1+a_{k+1})}
\end{equation}
and
\begin{equation}
\sigma^2=
\sum_{k=1}^\ell \frac{(1+a_k+a_kb_k+a_kb_ka_{k+1})(b_k+a_{k+1}+b_ka_{k+1}+a_ka_{k+1})}
{(1+a_k)^2(1+b_k)^2(1+a_{k+1})^2}
\end{equation}
where~$a_{\ell+1}=a_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Given any fixed integers  $s\ge 1$ and  $t_i\ge 1$ for $1\le i\le s$, $1\le j\le t_i$, if  $\|A\|\le \sqrt{\alpha}+O(N^{-\frac{1}{3}})$ with $ \epsilon\le \alpha\le 1$ for some fixed $\epsilon>0$, and
    \begin{equation}
        \theta t_N\ll n_{i,j}\le  \tau N^{\frac{1}{3}}
    \end{equation}
    for any fixed constant $\tau$  such that   $t_1n_1+\cdots+t_kn_k$ is even, then   
    \begin{equation}
        \mathbb{E}\Big[\prod_{i=1}^{s}\mathrm{Tr} \prod_{j=1}^{t_i} (\frac{1}{n_{i,j}}Q_{n_{i,j}}(\frac{X}{2}))\Big]=\mathbb{E}\Big[\prod_{i=1}^{s}\mathrm{Tr} \prod_{j=1}^{t_i}(\frac{1}{n_{i,j}}Q_{n_{i,j}}(\frac{\widetilde{X}}{2}))\Big]+o(1).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:evaluation:bias of arXiv:2609.02304, 'Bayes-Optimal BER and AUC: \\Estimation and Evaluation of Estimators'] Let
  $\mathrm{bias}_{\nu} =
    \E{\widehat{\mathrm{BER}^*_{\nu}}} - \mathrm{BER}^*_{\nu}$
  denote the bias of the estimator
  $\widehat{\mathrm{BER}^*_{\nu}}$ at noise level $\nu$.
  Then
  \begin{equation}
    \E{
      \paren{\widehat{\mathrm{BER}^*_{\nu}} - U_{\mathrm{BER}}(\nu)}_+
      +
      \paren{L_{\mathrm{BER}}(\nu) - \widehat{\mathrm{BER}^*_{\nu}}}_+
    }
    \geq
    \left[
      \abs{\mathrm{bias}_{\nu}}
      -
      \frac{u_{\mathrm{BER}}}{K} (1 - \nu)
    \right]_+
    \text{,}
  \end{equation}
  where
  $
    K
    \coloneqq
    \min \set{
    1,
    \frac{\beta (1 - \beta)}{\theta (1 - \theta)}
    }
    \in (0, 1]
  $.

[Definition def: hazard rate of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] The survival function associated with $g$ is defined as
	\begin{equation*}
		S_g(x, y) \vcentcolon= \int_{[x, \infty) \times [y, \infty)} g(u, v)dudv \quad \text{for all} \quad x, y \in \mathbbm{R}_+.
	\end{equation*}
	Consider the open set $U_g \vcentcolon= \setc{(x, y) \in \mathbbm{R}_+^2}{S_g(x, y) > 0}$. If the survival function $S_g$ is differentiable, then we define the hazard rate vector field $\map{h_g}{\mathbbm{R}_+^2}{\mathbbm{R}_+^2}$ as:
	\begin{equation*}
		h_g(x, y) \vcentcolon= -\nabla \left[\log S_g\right](x, y) \quad \text{if} \quad (x, y) \in U_g \quad \text{and} \quad h_g(x, y) \vcentcolon= 0 \quad \text{otherwise}.
	\end{equation*}
	The first and second components of $h_g$ are denoted by $h_g^x$ and $h_g^y$, respectively.

[Theorem 14 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] Let $0\le p<(4a-1)/4a$. Then,
{\small\begin{equation*}
\lim_{n\to \infty}\frac{1}{\log n}\sum_{k=1}^{n}\frac{S_k^2}{k^2}=\frac{1}{(2a(1-p)-1)^2}\Big(\frac{(a(2p-1))^2}{4a(1-p)-1}+\frac{(1-2p)(a-1)}{1-p}+(a-1)^2\Big)\ \ \text{a.s.}
\end{equation*}}

