	\begin{align} 
	\lim_{a\to 0}	\vert 2^{-\frac{1}{4}} a^{-\frac{1}{2}} F^a(b_2^a) \vert= \vert F(y_2;y_1,y_3,y_4) \vert,
	\end{align}
where $F(\cdot;y_1,y_3,y_4)$ is defined by~(equation eqn::def_obser_free_con_1 of the paper) and~(equation eqn::def_obser_free_con_2 of the paper).

[Lemma 5 (Airy convolution identity) of arXiv:2607.18619, 'Chernoff's Density Is Strongly Log-Concave'] Define the nonnegative integrable kernel
\begin{equation}
    r(u):=2u\sum_{j=1}^\infty e^{-\lambda_j u},
    \qquad u>0.
\end{equation}
Then, for every $x\in\R$,
\begin{equation}
    \int_0^\infty r(u)g(x+u)\dd u
      =x^2g(x)+\frac12g'(x).
\end{equation}
Consequently, if $g$ is log-concave and
$\curvg=-(\log g)''$, then
\begin{equation}
    \curvg(x)\ge4x, \qquad x\in\R.
\end{equation}

