[Theo elliptic regularity limsup of mass of arXiv:2505.12127, 'Generalised principal eigenvalues and global survival of branching Markov processes'] We assume Assumption (assum:uniformly elliptic standing assumptions of the paper). Then
\begin{equation}
\lambda'_1(L)\leq \liminf_{t{\rightarrow}\infty}\frac{1}{t}\ln{\mathbb E}_x[N_t]\leq  \limsup_{t{\rightarrow}\infty}\frac{1}{t}\ln{\mathbb E}_x[N_t]= \lambda''_1(L).
\end{equation}
for all $x\in E$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 (Visible Markov property under edge homogeneity) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] Assume the model is edge-homogeneous near $\theta_0$ and satisfies \cref{ass:regularity}. Fix a visible depth $m\ge1$. Then, for every $\theta$ near $\theta_0$, the visible process $Z^{(m)}$ is a time-homogeneous first-order Markov chain. More precisely, if $y\in\cS_m$ has last edge $e$ and $a$ is admissible from $e$, then
\begin{equation}
P_\theta\bigl(Z_{t+1}^{(m)}=U_m(y,a)\mid Z_t^{(m)}=y\bigr)=\mu_\theta(a\mid e).
\end{equation}

[Proposition 32 of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] \la{prop:Oshima-ineq}
  Let $h$ be the strictly positive continuous bounded ground state in \eqref{eq:22}. 
  There exists a positive function $g \in L^{1}(h^{2} dx)$ and a non-negative function
  $\psi \in C_{0}^{\infty}(\bR^{d})$ with $\int_{\bR^{d}}^{ } \psi h^{2} dx = 1$ such that
  for any $u \in \cF_{e}^{\alpha}$, 
  \begin{align}

    &\hspace{-1cm}
      \int_{\bR^{d}}^{ } \left| u(x) - h(x) L \left( \frac{u}{h} \right) \right| g(x) h(x) dx \\
    &\le C \mathcal{E}^{-\theta_{c} \mu}(u,u)^{1/2} 
    = C \left( \cE^{\alpha}(u,u) -
      \theta_{c} \int_{\bR^{d}}^{ } u(x)^{2} d\mu \right)^{1/2}
  \end{align}
  where $L(u)$ is a linear functional defined by 
  \begin{align}

    L(u) = \int_{\bR^{d}}^{ } u(x) \psi(x) h(x)^{2} dx.
  \end{align}

