body:
[Theorem 11 of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] With the assumptions of \Cref{prop:AlternativeGreenFunction}, for all finite \(A \subset \Z^d\),
as \(\lVert x \rVert\to +\infty\) we have

\begin{equation*}{
 \P(\Tree_{+}^{x} \cap A \neq \emptyset) \sim \P(\Tree_{-}^{x} \cap A \neq \emptyset) \sim \left(\frac{\bcp(A)}{\bcp(\{ 0 \})}\right)^{\alpha-1} G(x).
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 (Asymptotics, case $\alpha = 0, \pi$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Let $z_0 \in \R^2$. The following asymptotics hold:
\begin{equation}
g^{z_0}(r, 0) \underset{r\to+\infty}{\sim} C_0 f_0(z_0)\frac{e^{-r\M}}{r^{3/2}}, \quad\quad g^{z_0}(-r, 0) \underset{r\to+\infty}{\sim} C_\pi f_\pi(z_0)\frac{e^{-r\m}}{r^{3/2}},
\end{equation}
where $C_0, C_\pi > 0$ and $f_0(z_0), f_\pi(z_0) > 0$ are defined as follows.
The constant $C_0$ is given by:
\begin{equation} 
C_0 =
\begin{cases}
    -\dfrac{\sqrt{\det(\Sigma^+)(\M - x_{min}^+)}}{\sqrt{\pi} \Sigma_{22}^+ (\Sigma_{22}^+ + \Sigma_{22}^-) \gamma(\M, Y^-(\M), Z^+(\M))} > 0 \quad &\text{if } \M = x_{max}^+ < x_{max}^- \\[2ex]
    -\dfrac{\sqrt{\det(\Sigma^-)(\M - x_{min}^-)}}{\sqrt{\pi} \Sigma_{22}^- (\Sigma_{22}^+ + \Sigma_{22}^-) \gamma(\M, Y^-(\M), Z^+(\M))} > 0 \quad &\text{if } \M = x_{max}^- < x_{max}^+.
\end{cases}
\end{equation}

Moreover, $f_0(z_0)$ is defined as follows:
\begin{itemize}
    \item If $\M = x_{max}^+ < x_{max}^-$ (cases B and C of Figure~\ref{anglesalphab}), then
    \begin{equation} 
    f_0(a_0, b_0) =
    \begin{cases}
    \left(b_0 - \dfrac{\Sigma_{22}^+}{(\Sigma_{22}^+ + \Sigma_{22}^-) \gamma(\M, Y^-(\M), Z^+(\M))}\right)
    e^{\M a_0 + b_0 Y^\pm(\M)} &\text{if } b_0 \geq 0 \\[2ex]
    \dfrac{-\Sigma_{22}^+}{(\Sigma_{22}^+ + \Sigma_{22}^-) \gamma(\M, Y^-(\M), Z^+(\M))} 
    e^{\M a_0 + b_0 Z^+(\M)} &\text{if } b_0 < 0
    \end{cases}
    \end{equation}

    \item If $\M = x_{max}^- < x_{max}^+$ (cases A and D of Figure~\ref{anglesalphab}), then
    \begin{equation} 
    f_0(a_0, b_0) =
    \begin{cases}
    \dfrac{-\Sigma_{22}^-}{(\Sigma_{22}^+ + \Sigma_{22}^-) \gamma(\M, Y^-(\M), Z^+(\M))}
    e^{\M a_0 + b_0 Y^-(\M)} &\text{if } b_0 \geq 0 \\[2ex]
    \left(-b_0 - \dfrac{\Sigma_{22}^-}{(\Sigma_{22}^+ + \Sigma_{22}^-) \gamma(\M, Y^-(\M), Z^+(\M))}\right)
    e^{\M a_0 + b_0 Z^\pm(\M)} &\text{if } b_0 < 0
    \end{cases}
    \end{equation}
\end{itemize}

The expressions for $C_\pi$ and $f_\pi(z_0)$ are symmetric. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 20 (Negative correlation of real functionals) of arXiv:2607.18201, 'Finding Adam in noisy trees'] Fix $r\geq 2$, and consider the random variables
    \begin{align*}
        Y_i:=f(X_i,(\cT_n(i;E_r),i)),\quad Z:=\sum_{i=1}^r Y_i~.
    \end{align*}
    Then for all $i \neq j$,
    \begin{align*}
        \CExp{(Y_i-\CExp{Y_i}{Z})(Y_j-\CExp{Y_j}{Z})}{Z}\leq 0~.
    \end{align*}

