[Prop i!-left-Quillen-equiv-sp of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $i\colon G\to G'$ be an \emph{injective} homomorphism of compact Lie groups. Then
    \[
        i_!\colon\cat{$\bm{G}$-OrthSp}\rightleftarrows\cat{$\bm{G'}$-OrthSp}
	\nobreak
	\mspace{6mu plus 1mu}
	{:}
	\nonscript\mkern-\thinmuskip
	\mathpunct{}
	\mspace{2mu}
 i^*
    \]
    is a Quillen adjunction in which both adjoints are homotopical. In particular, they descend to an adjunction $i_!\colon{\mathfrak S\kern-.5pt\mathfrak p}_G\rightleftarrows{\mathfrak S\kern-.5pt\mathfrak p}_{G'}
	\nobreak
	\mspace{6mu plus 1mu}
	{:}
	\nonscript\mkern-\thinmuskip
	\mathpunct{}
	\mspace{2mu}
 i^*$.
    \begin{proof}
        [DHLPS2019Proper]*{Theorem~1.66(i)} shows that $i^*$ is homotopical right Quillen, while $i_!$ is homotopical by [schwede2018global]*{Corollary~3.2.21}.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop: ModuleRephrasingWalkDet of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] It holds that $p^2 \nmid \det(\bW)$ if and only if one of the following two events occurs: 
    \begin{enumerate}[leftmargin = 1.6em]
        \item It holds that $\coker\bigl(\bM - x\bI,\, \zeta\bigr)_{p,\beta} \cong 0$ for all monic $\beta(x) \in \bbZ[x]$ with irreducible reduction in $\bbF_p[x]$.
        \item Or, there exists $a\in \bbZ$ such that one has an isomorphism of $\bbZ[x]$-modules 
        \begin{align}
            \coker\bigl(\bM - x\bI,\, \zeta\bigr)_{p, x-a} \cong \bbF_{p}[x]/(x-a)\bbF_{p}[x],
        \end{align}
        and it holds that $\coker\bigl(\bM - x\bI,\, \zeta\bigr)_{p,\beta} \cong 0$ for every $\beta \not\equiv x-a \bmod p$.     
    \end{enumerate}

[Definition 84 of arXiv:2608.29086, '2608.29086'] [Cone complex $\prod^{\ast} CONE(\bigcap^{\ast}S_i)$]
Given $M \subset H_0$ and its open covering $V=\{S_i \subset M \ |\ i \in I \}$. The \textit{cone complex} on $M$ is a collection of three objects $CONE(M)$, $\prod_{i \in I}CONE(S_i)$, and $\prod\prod_{i<j} CONE(S_i \cap S_j)$ with two linear mappings $\iota$ and $\delta_0$ defined by
\begin{equation*}
\iota:CONE(M) \rightarrow \prod_{i \in I}CONE(S_i),\quad
\iota\left((Cone\ A, M)\right):= \prod_{i \in I} \left(Cone\ A, S_i\right),
\end{equation*}
\begin{multline*}
\delta^0: \prod_{i \in I}CONE(S_i) \rightarrow \prod\prod_{i<j} CONE(S_i \cap S_j),\quad  \delta^0\left(\prod_{i \in I} (Cone\ A_i, S_i)\right):= \\
 \prod_{i \in \{i \in I|i<j\}}\prod_{i \in I} \left(v_{{\partial}Cone\ A_i}(x) - v_{{\partial}Cone\ A_j}(x), S_i \cap S_j\right)
\end{multline*}
(Figure \ref{figure8} (a)).

[Theorem thm: Existence A-localized states of arXiv:2411.10271, '$A$-localized states for clock models on trees and their extremal decomposition into glass'] Let $d\geq 2$ be an integer and $A\subset \mathbb{Z}_q$ with $n:=|A|\geq 1$. There is a positive quantity $\eta=\eta(d,n)$ such that the following statement holds. Assume that the transfer operator is normalized by $Q(0)=1$ and satisfies the condition 
    \begin{equation}
        \epsilon:=\| Q- \mathds{1}_{\{0\}}\|_{\frac{d+1}{2}}\leq \eta(d,n).
    \end{equation}
    Then, the Gibbsian specification which is induced by $Q$ on the $d$-regular tree with local state space $\mathbb{Z}_q$ admits a spatially homogeneous tree-indexed Markov chain Gibbs measure $\mu_A$. Denote by 
    \begin{align}
         \nonumber&\pi_A: \mathbb{Z}_q \rightarrow [0,1],~~~~~\pi_A(i):=\mu_A(\sigma_\rho=i),\\
         &\Delta: \mathbb{Z}_q \rightarrow [0,1],~~~~~~\Delta(i):=P_A(i,i),
    \end{align}
    the functions giving the single-site marginals of $\mu_A$ and the diagonal elements of the transition matrix $P_A$. Moreover, the single-site marginals $\pi_A$ are strictly positive and the following estimates hold:
    \begin{align}
        \nonumber(i) ~\|\Delta|_{A^c}&\|_{\frac{d+1}{d-1}}\leq c_1 \epsilon^{d-1}, ~~~~(ii) ~\min_{i\in A} \Delta(i)>1-c_2\epsilon,\\
        (iii) ~\sum_{i\in A^c} \pi_A(i) \leq c_3& \epsilon^{d+1},~~~~(iv)~(1-c_5\epsilon)\frac{1}{|A|}\leq \pi_A|_A \leq (1-c_4\epsilon)^{-1} \frac{1}{|A|}
    \end{align}
    where $c_1,...,c_5$ are positive constants depending on $d$ and $n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 41 (Short-time full covariance negative moments) of arXiv:2607.19752, 'Weak Equilibrium Measures and Capacity--Hitting Identities\\ for the Hypoelliptic Third-Or'] For every $q\ge1$, after decreasing $t_0$ if necessary,
\[
    \sup_{\substack{
        0\le\delta\le1,\ z\in K_0\\
        0<t\le t_0}}
    \mathbb E_z\left[
        \lambda_{\min}\left(
            T_t^{-1}\mathcal M_{t,r}^{\delta,\mathsf O}T_t^{-1}
        \right)^{-q}
    \right]<\infty .
\]

