body:
[Defn 23 (Boman chain condition) of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] A probability measure $\rho\in\ms P(\mb T^d)$ satisfies the \emph{Boman chain condition} with parameters $A, B, C > 1$, if there exists a covering $\m F$ of $\mb T^d$ by open balls such that:
\begin{itemize}
    \item for any $x\in\mb T^d$, $\sum_{Q\in\m F}1_{2Q}(x) \leq A$;

    \item given any fixed ball $Q_0\in\m F$, which is called the central ball, for every $Q\in\m F$, there exists a chain $Q_0, Q_1, \cdots, Q_N = Q$ of distinct balls from $\m F$ such that $Q\subset BQ_j$ holds for all $j\in\{0, 1, \cdots, N-1\}$;

    \item consecutive balls of the above chain satisfy
    \begin{align*}
        \rho(Q_j\cap Q_{j+1}) \geq C^{-1}\max\{\rho(Q_j), \rho(Q_{j+1})\},\quad\forall\, j\in\{0, 1, \cdots, N-1\}.
    \end{align*}
\end{itemize}
\myqed

[Deff eq:doapt of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Let $S$ be a semigroup  with generator $A$ satisfying $\|S(t)\|_{\mathcal{L}(L^p, L^p)} \lesssim e^{-t}$ (for example if $A$
is a sectorial operator, see (semigrp-deff of the paper)).
  Then for any $\vartheta > 0$ we define the fractional power of $(-A)$ as
  \begin{equation}
      (-A)^{-\vartheta} = \frac{1}{\Gamma(\vartheta)} \int_0^\infty t^{\vartheta - 1} S(t)  dt \,, 
  \end{equation}
  where $\Gamma$ is the usual $\Gamma$-function and the integral exist by the assumed bound on $S$. 

  Furthermore, we define 
  \begin{equation}
      (-A)^\vartheta = ((-A)^{-\vartheta})^{-1} \qquad \textrm{and}\quad A^0 = I \,.
  \end{equation}

[Proposition 3 of arXiv:2605.03902, 'Bundles of Probability Schemes'] The outer rectangle obtained by pasting two fiber products of bundles
  as shown
  \begin{equation}
    \begin{split}
  \xymatrix{
    \Omega_3 \otimes_{\Omega_2} (\Omega_2 \otimes_{\Omega_0}\Omega_1)
      \ar[r] \ar[d] & \Omega_2 \otimes_{\Omega_0} \Omega_1 \ar[r] \ar[d]
      & \Omega_1 \ar[d]^{\alpha} \\ \Omega_3 \ar[r]_{\gamma} & \Omega_2
      \ar[r]_{\beta} & \Omega_0
  }
\end{split}
 \end{equation}
 is isomorphic to the fiber product of the bundles $\alpha$ and $\delta =
 \beta\gamma$.

[Lemma 10 of arXiv:2609.01965, 'A logarithmic Bogomolov--Sommese vanishing theorem on compact K\"ahler manifolds'] Let $(X,\omega)$ be a compact K\"ahler manifold of dimension $n$ and $L$ a pseudo-effective line bundle over $X$ with $\nd(L)=k>p$.
    Let $D$ be a reduced simple normal crossing divisor on $X$.
    There exist constants $c_0,C_0>0$ such that for every $\varepsilon$ sufficiently small, we have the following properties.
    \begin{enumerate}
        \item There exists a log resolution 
        $$\pi_\varepsilon:\widetilde{X}_\varepsilon\longrightarrow X$$
        and a reduced simple normal crossing divisor $B_\varepsilon$ such that $B_\varepsilon$ contains the total transform of $D$ and the exceptional divisor.
        Moreover, $\pi_\varepsilon$ induces a natural morphism from $\Omega^p_X(\log D)$ to $\Omega^p_{\widetilde{X}_\varepsilon}(\log B_\varepsilon)$.
        \item There exists a singular Hermitian metric $\widetilde{h}_\varepsilon$ on line bundle $\pi^*_\varepsilon L$ 
        with divisorial singularities supported on $B_\varepsilon$ and smooth on $$Y_\varepsilon:=\widetilde{X}_\varepsilon\setminus B_\varepsilon.$$
        \item There exist K\"ahler forms $\gamma_\varepsilon$ and $\Omega_\varepsilon$ on $\widetilde{X}_\varepsilon$ such that, on $Y_\varepsilon$,
        \begin{equation}
            \image\Theta_{\pi^*_\varepsilon L,\widetilde{h}_\varepsilon}=\gamma_\varepsilon-3\varepsilon\pi^*_\varepsilon\omega 
            \quad \text{and} \quad \Omega_\varepsilon\geq \pi^*_\varepsilon\omega.
        \end{equation}
        \item The following uniform estimates hold:
        \begin{equation}
            V_\varepsilon:=\int_{\widetilde{X}_\varepsilon}\gamma_\varepsilon^n\geq c_0\varepsilon^{n-k} 
            \quad \text{and} \quad
            \int_{\widetilde{X}_\varepsilon}\gamma_\varepsilon^{p}\wedge\Omega_\varepsilon^{n-p}\leq C_0.
        \end{equation}
    \end{enumerate}

