body:
[Lemma lem: 792 of arXiv:2607.05848, 'Mesoscopic eigenvalue statistics for correlated random matrices'] {EHR26+}}]
Suppose the same setting as in Theorem (thm: 369 of the paper).
Consider $z=E_{1}+\mathrm{i}\eta_{1}$ and $w=E_{2}+\mathrm{i}\eta_{2}$ with $E_{1},E_{2}\in\mathcal{I}(\epsilon_{0}/2)$ and $|\eta_{1}|,|\eta_{2}|\in(0,100)$.
Let $\mathcal{B}_{z,w}$ be as in (equation eq: 535 of the paper).
Then,
\begin{equation}
	\lVert \mathcal{B}_{z,w}^{-1} \rVert_{\lVert\cdot\rVert\to\lVert\cdot\rVert} + \lVert \mathcal{B}_{z,w}^{-1} \rVert_{\lVert\cdot\rVert_{\textnormal{hs}}\to\lVert\cdot\rVert_{\textnormal{hs}}}
	\lesssim
	\begin{cases}
		1, & \eta_{1}\eta_{2} > 0, \\
		\max\{1,|z-w|^{-1}\}, & \eta_{1}\eta_{2} < 0.
	\end{cases}
\end{equation}
Specifically, for the case $z=w$,
\begin{equation}
	\lVert \mathcal{B}_{z}^{-1} \rVert_{\lVert\cdot\rVert\to\lVert\cdot\rVert} + \lVert \mathcal{B}_{z}^{-1} \rVert_{\lVert\cdot\rVert_{\textnormal{hs}}\to\lVert\cdot\rVert_{\textnormal{hs}}}
	\lesssim 1.
\end{equation}
Moreover, there exist (small) positive thresholds $\beta_{*},\epsilon_{*}\sim 1$, $\epsilon_{*}<1/3$, such that, if $|z-w|\le\beta_{*}$ and $\eta_{1}\eta_{2}<0$, then
\begin{equation}
	\lVert (\zeta-\mathcal{B}_{z,w})^{-1} \rVert_{\lVert\cdot\rVert\to\lVert\cdot\rVert} + \lVert (\zeta-\mathcal{B}_{z,w})^{-1} \rVert_{\lVert\cdot\rVert_{\textnormal{hs}}\to\lVert\cdot\rVert_{\textnormal{hs}}}
	\lesssim 1,
\end{equation}
for all $\zeta\in\mathbb{C}$ satisfying $|\zeta|\ge\epsilon_{*}$ and $|1-\zeta|\ge 1-2\epsilon_{*}$,
and the disk of radius $\epsilon_{*}$ around the origin contains a single eigenvalue $\beta_{z,w}$ of $\mathcal{B}_{z,w}$ with algebraic multiplicity one, that is,
\begin{equation}
	\textnormal{rank}\,\Pi_{z,w} = 1, \quad\;\; \Pi_{z,w}\coloneqq \frac{1}{2\pi\mathrm{i}}\oint_{|\zeta|=\epsilon_{*}} (\zeta-\mathcal{B}_{z,w})^{-1} \mathrm{d}\zeta,
\end{equation}
where $\Pi_{z,w}$ is the spectral projection corresponding to $\beta_{z,w}$.
Furthermore, the eigenvalue $\beta_{z,w}$ of $\mathcal{B}_{z,w}$ satisfies
\begin{equation}
	|\beta_{z,w}| \sim 
	\begin{cases}
		1, & \eta_{1}\eta_{2} > 0, \\
		\min\{1,|z-w|\}, & \eta_{1}\eta_{2} < 0.
	\end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop ine:KeyScalingInequality of arXiv:2410.23859, 'Subcritical regimes in the Poisson Boolean percolation on Ahlfors regular spaces'] Let $\lambda > 0$. Let $C_1>0$ be a constant appeared in Proposition (prp:UniformRecursiveEstimate of the paper). For $r > 0$,
        We have 
            \begin{equation} 
                \sup_{x\in S} \mathbb{P}_\lambda(G(x, 10\sigma^3r)) \leq C_1 (\sup_{x \in S} \mathbb{P}_\lambda(G(x, r)))^2 + (100\sigma^6)^s\lambdaC_\textup{V}\int_r^\infty R^s \rho(dR)
            \end{equation}
        and 
        \begin{equation}
            \sup_{x\in S}\mathbb{P}_\lambda(M(x) > 9\sigma^2 r) \leq \sup_{x\in S}\mathbb{P}_\lambda(G(x,r)) + (10\tau)^s \lambda C_\textup{V}\int_{\sigma^3 r /\tau}^\infty R^s \rho(dR).
        \end{equation}

[Lemma 18 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] Let $f:\ZZ^d\to\RR$. Then for all $R\ge 1$,
    \begin{equation}
        \left(\fint_{B_R}\Big|f-\fint_{B_R }f\Big|^{q}\right)^\frac1q\,\lesssim_{p}\, R\left(\fint_{ B_{R}}|\nabla f|^{p}\right)^\frac1p
    \end{equation}
    provided that $\frac1p\le\frac1q+\frac1d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 13 of arXiv:2608.01674, '\textbf{Limit Theorems for Tempered Linear Processes with Innovations in the Domain of Att'] For every $p>1$,
\begin{equation}
 \frac1N\sum_{j\in\Z}|w_N(j)-w(j/N)|^p
 \longrightarrow0, \qquad N\to\infty.

\end{equation}

