[Theorem 3 of arXiv:2506.08775, 'Markovian multivariate Hawkes population processes: Efficient evaluation of moments'] Fix $t\in\rr_+$, and assume $\bm{Q}(t_0) = \bm{Q}_0 \in\nn_0^{d}$ and $\bm{\lambda}(t_0) = \bm{\lambda}_0 \in\rr_+^d$ for some $0 \leqslant t_0 <t$. Then, for any $\bm{z}\in[-1,1]^d$, $\bm{s}\in\rr_+^d$,
\begin{align} 
    \zeta_{t_0}(t,\bm{s},\bm{z})
    &= \prod_{j=1}^d \hat{z}_j(t_0)^{Q_{j,0}} \exp \Big( -\tilde{s}_j(t)\lambda_{j,0} -\overline{\lambda}_j \alpha_j \int_{t_0}^t \tilde{s}_j(u)\ddiff u \Big),
\end{align}
where, for $t_0 \leqslant u \leqslant t$ and $j\in[d]$, the functions $\hat{z}_j(\cdot)$ and $\tilde{s}_j(\cdot)$ satisfy
\begin{align} 
\begin{split}
    &\hat{z}_j(u) = 1 + (z_j-1)e^{-\mu_j(t-u)}, \\
    &\frac{\mathrm{d} \tilde{s}_j(u)}{\mathrm{d} u} + \alpha_j \tilde{s}_j(u) + \big(1 + (z_j - 1)e^{-\mu_j(u-t_0)}\big) \beta_j(\tilde{\bm{s}}(u)) - 1 = 0,
\end{split}
\end{align}
with  boundary condition $\tilde{s}_j(t_0) = s_j$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:dynamics-coupling of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] [Grand coupling of dynamics] For each vertex $v$ in $\mathbb Z^d$, assign an independent intensity-$1$ Poisson process process on $(0,\infty)$, denoted $\mathcal T_v = (t_{v,1}<t_{v,2}<...)$ and to each point $t\in \bigcup_i \{t_{v,i}\}$ assign a $\text{Unif}[0,1]$ random variable $\mathcal U_{v,t}$. For every finite $\Lambda \subset \mathbb Z^d$, boundary conditions $\eta \in \{\pm 1\}^{\Lambda^c}$ and inital configuration $x_0\in \{\pm 1\}^\Lambda$, generate the Glauber dynamics $(X_t)_{t\ge 0} = (X_{\Lambda^\eta,t}^{x_0})_{t\ge 0}$ on $\Lambda$ with boundary conditions $\eta$ initialized from $x_0$ as follows: let $t_1<t_2<...<t_{k(t)}<t$ be the ordered points of $\bigcup_{v \in \Lambda} \mathcal T_v$ at times before $t$, 
    \begin{itemize}
        \item for $s\in [0,t_1)$, let $X_s = x_0$; 
        \item iteratively, for $i = 1,...,k(t)$, for $s\in [t_i,t_{i+1})$, if $t_i\in \mathcal T_v$, let 
        \begin{align*}
            X_s(w) & = X_{t_i^-}(w) \qquad w\ne v\\ 
            X_s(v) & = \begin{cases}+1  & \text{ if }\quad  \mathcal U_{v,t_i}\le \pi_{\Lambda}^{\eta}(\sigma_v = +1 \mid (\sigma_w)_{w\ne v} = (X_{t_i^-}(w))_{w\ne v}) \\ -1 & \text{ else}
            \end{cases}
        \end{align*}
    \end{itemize}

[Lemma 22 of arXiv:2609.04155, 'The subconvexity problem for symmetric square\\ $L$-functions in Level aspect'] Let $F$ be a smooth function supported on $[0, 2A]$ for some large $A$ and $F\equiv 1$ on $[0, A]$, then we have
		\begin{equation}
			\mathcal I(m, n, q)= \sqrt{|\mathfrak X|}\frac{q^2}{C^2}\frac{C}{Q}\frac{p^{1/4}}{m^{1/4}} U\left(\frac{m}{M}\right)V\left(\frac{|n|}{N}\right)F\left(\frac{|4m-n^2|}{p^{1+\eps}C/Q}\right) \tilde I_q (m, n) + O(p^{-2026})
		\end{equation}
		where, 
		\begin{equation*}
			\tilde I_q(m, n):= \int_\R \frac{W(x)}{\sqrt{x}}g\left(q, \frac{xC\mathfrak X}{q}\right)e\left(\pm \frac{4m-n^2}{4xpC|\mathfrak X|/Q}\right)\, dx.
		\end{equation*}

