[Definition 10 (Iterative edge-colored bipartite graph process) of arXiv:2608.07239, 'Unified framework for asymptotically uniform iterative construction of generalised random '] Consider the bipartite vertex set $V=A\cup B$ with $A=\{v_1,\ldots,v_n\}$ and $B=\{v_1',\ldots,v_{n'}'\}$, and for $g=1,\ldots,\chi$, consider degree sequences $\d^{(g)}=(d_1^{(g)},\ldots,d_n^{(g)})$ and $\d'^{(g)}=(d_1'^{(g)},\ldots,d_{n'}'^{(g)})$ of non-negative integers with $m^{(g)}:=d_1^{(g)}+\ldots+d_n^{(g)}=d_1'^{(g)}+\ldots+d_{n'}'^{(g)}>0$, and consider a set $X^{(g)}$ of forbidden edges. For $g=1,\ldots,\chi$, define $$\b^{(g)}_{i,j}:=\frac{d_i^{(g)}d_j'^{(g)}}{2m^{(g)}}+\sum_{\substack{h=g+1,\ldots,\chi\\(v_i,v_j')\not\in X^{(h)}}}\frac{d_i^{(h)}d_j'^{(h)}}{m^{(h)}}.$$ For $g=1,\ldots,\chi$, sample $E^{(g)}$ with the following steps:
		\begin{itemize}
			\item Start with no edges $E_0^{(g)}=\emptyset$.
			\item For $r=0,\ldots,m^{(g)}-1$, let $d_{i,r}^{(g)}$ and $d_{j,r}'^{(g)}$ denote the degrees of vertices $v_i$ and $v_j'$ in $(V,E_r^{(g)})$, and consider those pairs of vertices $(v_i,v_j')\in A\times B$ with $d_{i,r}^{(g)}<d_i^{(g)}$, $d_{j,r}'^{(g)}<d_j'^{(g)}$, and $(v_i,v_j')\not\in E_r^{(g)}\cup X^{(g)}\cup E^{(1)}\cup\ldots\cup E^{(g-1)}$.
			\begin{itemize}
				\item If no such pairs exist, let $E_{r+1}^{(g)}=E_r^{(g)}$.
				\item Otherwise, choose such a pair $(v_i,v_j')$ at random with probability proportional to $(d_i^{(g)}-d_{i,r}^{(g)})(d_j'^{(g)}-d_{j,r}'^{(g)})(1-\b^{(g)}_{i,j})$, and let $E_{r+1}^{(g)}=E_r^{(g)}\cup\{(v_i,v_j')\}$.
			\end{itemize}
			\item Finally, apply rejection sampling to sample $E^{(g)}=E_{m^{(g)}}^{(g)}$ with $m^{(g)}$ edges.
		\end{itemize}
		This guarantees that $(V,E^{(g)})$ for $g=1,\ldots,\chi$ are edge-disjoint simple bipartite graphs with degree sequences $\d^{(g)}$ and $\d'^{(g)}$ on their parts and with no edges from $X^{(g)}$.

[Corollary 40 of arXiv:2604.01852, 'The on/off Brownian snake'] In the setting of Proposition \ref{proposition identification oobmm h erased tree}, the process $(\Tilde{\mathcal{Z}}_y^{(\varepsilon)})_{y \geq 0}$, defined to be, for $y \geq 0$,
    \begin{equation*}
        \Tilde{\mathcal{Z}}_y^{(\varepsilon)} \coloneqq \sum_{i \in I} \sum_{\substack{p: A^i_{\gamma^{(h)}_{p, i}}(s)=1 \hspace{0.1cm} \forall 0 \leq s \leq y, \\ y \in [Y_{p, i}^{(h)}, Z_{p, i}^{(h)})}} \delta_{w^i_{\gamma^{(h)}_{p, i}}(y)}, 
    \end{equation*}
    is a $\text{BBM}(2/\varepsilon, 2/\varepsilon + c)$ starting from a Poisson random measure with intensity $\mu_{\rm a}/\varepsilon$.
    \begin{proof}
        This follows in the same way as for the $\text{BBM}(4/\varepsilon)$ (which is the same as $\text{BBM}(2/\varepsilon, 2/\varepsilon)$) given in Proposition \ref{proposition identification oobmm h erased tree}. The difference here is that once an active particle moves to the dormant state it is no longer included in the sum, and this is what increases the death rate by $c$.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:Durrett_Nguyen of arXiv:2508.18809, '{\bf Critical long-range percolation III: The upper critical dimension}'] Let $G=(V,E,J)$ be a weighted graph, let $o$ be a vertex of $G$ and let $K$ be the cluster of $o$ in Bernoulli-$\beta$ percolation. Then
\[
  \frac{d}{d\beta}\mathbb E_\beta \min\{|K|,m\} \leq 
  \sqrt{
  \beta^{-1}
  |J^*| \mathbb E_\beta[\min\{|K|,m\}] \mathbb E_\beta[\min\{|K|,m\}^2]
  }
\]
for every $\beta<\beta_c$ and $m>0$, where we define $|J^*|$ to be the supremal total weight of edges emanating from a vertex of $G$. If $G$ is transitive and $\beta<\beta_c$ then the inequality also holds with $m=\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:admiss-ST of arXiv:2412.09087, 'General Markovian randomized equilibrium existence and construction in zero-sum Dynkin gam'] A stopping time for Player $i=1,2$ is said to be admissible if it is on the form
\begin{align}
\tau_i = \tau_{\Psi^{(i)}} = \inf \{t \geq 0: \Psi_t^{(i)} \geq E_i \}
\end{align}
where (i)
$\Psi^{(i)} = (\Psi_t^{(i)})_{t \geq 0}$,  with $\Psi_{0-}^{(i)}= 0$, is a 
non-decreasing, right-continuous and ${\cal F}^X$-adapted process that takes values in $[0,\infty]$, and 
(ii) $E_i$ is an $Exp(1)$-distributed random variable (assumed to live on our probability space) that is independent of all other random sources.  

The spaces of admissible stopping times are denoted by $\mathbb{T}_i,i=1,2$.

[Theorem t.nonvacuum of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] Fix any $m > 2$ and $f_{\rm in} \in L^\infty_m$ satisfying $0 \le f_{\rm in} \le 1$ and further assume that $f_{\rm in}$ is non-vacuum at some $(x_0,v_0)$ with radius $r > 0$ and size $\delta > 0$. 
    Let $f:[0,T]\times \Omega \times \mathbb R^3 \to \mathbb R^+$ be any classical solution of~(equation e.LFD of the paper) with initial data $f_{\rm in}$. Then, for every $t_0 \in (0,T]$ and $R>0$, there is $c_0 \in (0,\nicefrac12)$ such that
    \begin{equation}

        0 < c_0 \le  f
            \le 1-c_0
            <  1
            \qquad\text{ on }
            [t_0,T]\times B_R(x_0)\times B_R(v_0).
    \end{equation}
    The constant $c_0$ depends on the parameters $v_0$, $t_0$, $T$, $R$, $r$, $\delta$, $m$, and $\|f_{\rm in}\|_{L^\infty_m}$. Consequently,
    \begin{equation}
       A[f(1-f)](t,x,v) \ge \lambda_0\left(\frac{\Pi(v)}{\left\langle v \right\rangle} + \frac{\mathrm{Id} - \Pi(v)}{\left\langle v \right\rangle^3}\right) \qquad \text{where} \quad (t,x,v) \in [t_0,T]\times B_R(x_0)\times \mathbb R^3.
    \end{equation}
    Here $\lambda_0 > 0$ depends on the same parameters as $c_0$. 
    Further, if $R<r$, (equation e.nonvacuum_on_compacts of the paper)-(equation e.coercivity of the paper) hold even up to $t_0 = 0$, with constants that also depend on $r-R$ and deteriorate as $R \uparrow r$. (Proof in the paper; no proof environment follows the statement in the TeX.)

