[Lemma B4LagPoly of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] For any $n,~a\in\mathbb{N}$ and $x\ge0$, the Laguerre polynomials are bounded as
\begin{equation}
        \left|L_n^a(x)\right|\le\left(\begin{matrix}
            n+a\\n
        \end{matrix}\right)e^{\frac{x}{2}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2605.17328, 'Transportation cost inequalities for mean reflection SPDEs with white noise'] {\rm(\cite[Lemma 4.3]{DuanJTP2025})}
{\rm Let  $\bar{z}_i$ be the first component of the solution to  the obstacle problem  \eqref{deterEqGeneral1} corresponding to process $v_i\in \mathcal{S}^1$, $i=1,2$, respectively. Then under the Assumption (H), we have for any $T>0$,}
\begin{align}
|\bar{z}_1-\bar{z}_2|^T_{\infty}\leq l\mathbb{E}\left[|v_1-v_2|^T_{\infty}\right],
\end{align}
{\rm where $l\geq 0$ is a constant.} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:clt of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] For $\lambda^2$ as in (equation eq:lambda of the paper) and for all  $\hat \beta \in [0,z_a)$, 
\begin{equation}
     \quad \log W_N^{\beta_N}\stackrel{{ (d)}}{\longrightarrow} \mathcal N\left(-\frac{\lambda^2}{2},\lambda^2\right),\quad N\to\infty\,,
\end{equation} 
in distribution.
On the other hand, $W_N^{\beta_N}\to 0$ in probability for all $\hat \beta\geq z_a$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:detailed-matrix-overlaps of arXiv:2605.19894, 'Sharp Spectral Thresholds for Multi-View Spiked Wigner Models'] In the setup of Proposition~(prop:sketch-statement-overlap of the paper), let
    \begin{equation}
        s(\nu_n) = \sgn\rbr{w^\top U^\top \nu_n}\in\{\pm 1\}
    \end{equation}
    fix the global sign of $\nu_n$. Then:
    \begin{enumerate}[label=(\alph*),ref=(\alph*)]
        \item
        \begin{align}
            \nbr{ U^\top \nu_n - s(\nu_n) \frac{w}{\sqrt{w^\top \cQ^\prime(\sigma) w}} } &= \cO_{\prec}(n^{-1/10});
        \end{align}

        \item
        \begin{equation}
            \nbr{ \frac{1}{\sqrt{n}} \matop(\nu_n)^\top X - \frac{s(\nu_n)}{\sqrt{w^\top \cQ^\prime(\sigma) w}} \cbr{ V^{-1}M(\sigma)\Diag\rbr{w\odot\sqrt{\lambda}}B }  } = \cO_{\prec}(n^{-1/10});
        \end{equation}

        \item
        Let $\cP_{\sigma}$ be the linear operator on $\mathsf{Sym}_L(\RR)$ defined by
        \begin{equation}
            \cP_{\sigma}[A] := M(\sigma) \cbr{ A + \Diag\rbr{\lambda\odot \sbr{\sbr{I_L - M(\sigma)^{\odot 2}\Lambda}^{-1}\diag\rbr{ M(\sigma) A M(\sigma)}} } }M(\sigma).
        \end{equation}
        Then for any $l_1,l_2\in[L]$,
        \begin{align}
            \Big| & \langle\nu_n^{(l_1)},\nu_n^{(l_2)}\rangle-  \\
            &\quad \frac{1}{2w^\top\cQ^\prime(\sigma)w} w^\top\cbr{ \rbr{\sqrt{\Lambda}B\sqrt{\Lambda}} \odot \rbr{ \cP_{\sigma}\sbr{ V^{-1} \rbr{e_{l_1}e_{l_2}^\top+e_{l_2}e_{l_1}^\top} V^{-1} } } }w \Big| = \cO_{\prec}\rbr{ n^{-1/20} }.
        \end{align}
    \end{enumerate}

