[Definition FlowboxSpace of arXiv:2607.19037, 'Semiclassical analysis for Yang--Mills \\ random connections on compact surfaces'] On $\square \equiv[0,1]_x\times [0,1]_y$, we define local semi-norms on smooth connections as follows. For all $ \tilde{A}\in\Omega^1(\square,\mathfrak{g})$,
 \begin{align*}
    &\Vert \tilde{A}\Vert_{\mathcal{W}^{\alpha,\alpha-1;p}_{x,y}(\square) } \coloneq    \Vert W\Vert_{\mathcal{W}^{\alpha,\alpha;p}_{x,y}([0,1]\times [0,1]) }\\
     &\hspace{2cm}= 
\left\{
\int_{ [0,1]\times [0,1]} \frac{\vert W(x_1,y_2)-W(x_2,y_1)-W(x_1,y_2)+W(x_2,y_2) \vert^p_{\mathfrak{g}}}{\vert x_1-x_2\vert^{1+\alpha p}\vert y_1-y_2\vert^{1+\alpha p}} \,\mathrm{d} x_1\mathrm{d} x_2 \mathrm{d} y_1\mathrm{d} y_2\right\}^{\frac{1}{p}}
\nonumber\\
&\nonumber\hspace{4cm}+ \Vert W \Vert_{L^p([0,1]\times [0,1])},
 \end{align*}
where $W$ is such that
\[\tilde{A}(x,y)= \left(\partial_y W \right) (x,y)\mathrm{d} y  \text{ and } W(.,0)=0~\footnote{This acts like some half--Dirichlet condition on $W$.}.\]
With the usual changes for $p=\infty$.

[Proposition prop:translated-univ of arXiv:2608.10184, 'The sharp SAT/UNSAT phase transition in random ellipsoid fitting'] Fix $C_0<\infty$, $\kappa>0$, and $\varepsilon \in (0,1/4)$. Let $m\to\infty$ and let $n=n(m)$ satisfy $n/m^2 \in [\varepsilon , 1/2 - \varepsilon]$.  For each $m$, let $\mathcal{C}_m$ be an arbitrary nonempty closed subset of
\begin{equation}
\mathcal{B}_m (C_0,\kappa) : =\left\{B\in\mathsf{S}^{m}:\|B\|_{\mathrm{F}}\le C_0,\ 
\operatorname{Tr}|B|^3\le m^{-\kappa}\right\},
\end{equation}
and let $a_1,\ldots,a_n\in\mathbb{R}$ be arbitrary deterministic offsets. For $\{X_i\}_{i\le n} \subset \mathsf{S}^m$, define
\begin{equation}
  \mathscr{E}_{\mathcal{C}_m} (\{X_i\}) =\inf_{B\in\mathcal{C}_m}\frac1n\sum_{i=1}^n
\varphi\bigl(a_i+\sqrt m\,\operatorname{Tr}(X_iB)\bigr).
\end{equation}
Let $z_1,\ldots,z_n\sim_{\mathrm{iid}}\mathcal{N}(0,I_m)$ and set $W_i = (z_i z_i^\top - I_m)/\sqrt m$, and let $G_1,\ldots,G_n$ be independent $\operatorname{GOE}(m)$ matrices.  Then, as $m \to \infty$,
\begin{equation}
\sup_{(a_i),\,\mathcal{C}_m}
\left|\mathbb{E} \mathscr{E}_{\mathcal{C}_m} (\{W_i\})-\mathbb{E} \mathscr{E}_{\mathcal{C}_m} (\{G_i\})\right| \longrightarrow0,
\end{equation}
where the supremum is over all offsets and closed subsets $\mathcal{C}_m$ of (equation eq:diffuse-class of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop equ-condi-ep of arXiv:2412.05698, 'Controlled rough SDEs, pathwise stochastic control and dynamic programming principles'] Suppose that $(b,\sigma,f)$ satisfies  (assum-path-stoch of the paper) $(1), (2)$. For any $\eta  \in   \mathcal{A}^2,$ let $Y^{\eta,\mathbf{X}}$ be the solution to (equation r-dsde' of the paper) with $\mathbf{X} \in {\mathscr{C}}^{0,\alpha}_T$, and $\bar{Y}^{\bar{\eta}}$  be

the randomized solution given by (equation randomized-rsde of the paper). Let $g$ be bounded and measurable. Then we have 

 \begin{equation} 
  \mathbb{E} [g (\bar{Y}^{\bar{\eta}}_T) |
     {\text{${\mathfrak F}$}}_T^{\mathbf{W}} ] = \mathbb{E} [g (Y^{\eta, \mathbf{X}}_T)] \Big|_{\mathbf{X} = \mathbf{W}}. 
 \end{equation}

