body:
[Proposition prop: technical estimate on slow varying functions of arXiv:2602.04429, 'Disordered systems and (subcritical) polynomial chaos\\ with heavy-tail disorder'] {}
	Let $L$ be a strictly positive slowly-varying function and let $\xi > 0$.
	For every $\varepsilon > 0$, there exist a constant $C = C_{\varepsilon}$ such that for every $k,N \in {\ensuremath{\mathbb N}} ^*$,
	\begin{multline*}
		\sum\limits_{1 \, \leqslant\, n_1 < \dots < n_k \, \leqslant\, N} \prod\limits_{j=1}^k L(n_j-n_{j-1})(n_j-n_{j-1})^{\xi-1} 
		\\ \, \leqslant\, C^k L(N)^k N^{k \xi} \int_{0 < t_1 < \dots < t_k < 1} \prod\limits_{j=1}^k (t_j-t_{j-1})^{\xi-\varepsilon -1} \mathrm{d} t_j \,,
	\end{multline*}
	and 
	\begin{multline*}
		\sum\limits_{1 \, \leqslant\, n_1 < \dots < n_k < n_{k+1} := N} \prod\limits_{j=1}^{k+1} L(n_j-n_{j-1})(n_j-n_{j-1})^{\xi-1} \\
		\, \leqslant\, C^{k+1} L(N)^{k+1} N^{k \xi + \xi -1} \int_{0 < t_1 < \dots < t_k < t_{k+1} =1} \prod\limits_{j=1}^{k+1} L(t_j-t_{j-1}) (t_j-t_{j-1})^{\xi -\varepsilon - 1} \prod\limits_{j=1}^k \mathrm{d} t_j \,.
	\end{multline*}

