[Lemma 13 of arXiv:2609.02225, '\textbf{The direct moving plane method for weak solutions of the fractional $p$-Laplacian}'] There exists \(c_H=c_H(n,s,p)>0\) such that, for every \(\lambda\in\mathbb R\) and \(x\in\Sigma_\lambda^-\),
\begin{equation}
 \int_{\Sigma_\lambda}
 \frac{
 \bigl(
  |u(x)-u(y)|+|u_\lambda(x)-u(y)|
 \bigr)^{p-2}}
 {|x-y^\lambda|^{n+sp}}\,dy
 \ge c_H(\lambda-x_1)^{-sp}u(x)^{p-2}.
\end{equation}
If \(\lambda\le0\), then
\begin{equation}
 \int_{\Sigma_\lambda}
 \frac{
 \bigl(
  |u(x)-u(y)|+|u_\lambda(x)-u(y)|
 \bigr)^{p-2}}
 {|x-y^\lambda|^{n+sp}}\,dy
 \ge c_H|x|^{-sp}u(x)^{p-2},
 \qquad\text{for }x\in\Sigma_\lambda^-.
\end{equation}
Let \(I\subset\mathbb R\) be a bounded interval and set $L_I:=\max\left\{1,\sup_{\mu\in I}|\mu|\right\}$. Then, for every \(\lambda\in I\) and every \(x\in\Sigma_\lambda^-\) with \(|x|\ge L_I\), there exists \(c_H'=c_H'(n,s,p)>0\) such that
\begin{equation}
   \int_{\Sigma_\lambda}
 \frac{
 \bigl(
 |u(x)-u(y)|+|u_\lambda(x)-u(y)|
 \bigr)^{p-2}}
 {|x-y^\lambda|^{n+sp}}\,dy
 \ge c_H'|x|^{-sp}u(x)^{p-2}.
\end{equation}

