[Proposition 18 (Stability in $b$) of arXiv:2606.06757, 'Path-Dependent Ergodic Optimal Control \\ and Backward Stochastic Differential Equations'] There exists a constant $C>0$ depending only on $\eta_1,\eta_2,\theta_0,\theta$ such that, for any $\xi\in\mathcal C_{\theta}^0$ and $K\in\K,$
\begin{equation*}
\begin{array}{cc}
     \displaystyle \int_0^{\infty} K(s)|\mathcal{X}^{\xi}_s- \tilde{\mathcal{X}}^{\xi}_s|_{\theta} \, ds\leq \Big(\int_0^{\infty} K(s)|\mathcal{X}^{\xi}_s- \tilde{\mathcal{X}}^{\xi}_s|_{\theta} \, ds\Big)^{\frac{1}{2}}\leq  C  \,  \Big(\int_0^{\infty} K(s)(\delta b(s))^2 \,ds\Big)^{\frac{1}{2}} \, , & \mathbb{P}-\text{a.s.}
\end{array}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:equivalenceofensembles of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] Let $f:\Omega\longrightarrow\mathbb{R}$ be a local function whose support is included in $\{0,\hdots ,\ell_0-1\}$ for some $\ell_0\ge 1$. Then, there exists a constant $C_1=C_1(f)>0$ such that for any $\ell\ge\ell_0$, 
    \begin{equation}
        \sup_{\eta\in\Omega}\left| \mathbb{E}_\ell [f] - \left(\psi_f(\xi_0^\ell ,\eta_0^\ell ) - \frac{1}{2\ell }\mathrm{Tr}\big( \chi \mathrm{Hess}(\psi_f)\big) (\xi_0^\ell ,\eta_0^\ell)\right)\right| \le \frac{C_1}{\ell^2}.
    \end{equation}
    where $\chi$ is the compressibility matrix defined in (defin:compressibilitymatrix of the paper), and $\mathrm{Hess}(\psi_f)$ denotes the Hessian matrix of $\psi_f$.

