body:
[Corollary cor:N* of arXiv:2512.12902, 'Non-equilibrium fluctuations for the \\stirring process with births and deaths'] Let  $K\geq 2$ be a fixed  integer number,  $\zeta>0$ and $0<c^*<\frac{1}{4(K+2)}$. For $\beta^*<2$ and $\epsilon<1$, there exists $N^*$ positive integer (large enough) satisfying 
\begin{equation}
(2-\beta^*)c^*(N^*+1)>1+\zeta
\end{equation}
and thus
 \begin{equation}
 \sup_{0<t\leq T}\sup_{\underline{x}\in\Lambda_N^{n,\neq}}|v^{\epsilon}_{n}(\underline{x},t)|\leq c\epsilon^{1+\zeta},\quad n\geq N^*+1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2606.10313, '\textbf{Invariance principles for additive functionals of voter models}'] Let $\eta_0$ be distributed with $\mu_p$.
For any $t\geq 0$,
\begin{align*}
&\lim_{N\rightarrow+\infty}\Big(\frac{1}{\sqrt{N}}\tilde{G}^N(tN, \eta_{tN})-\frac{1}{\sqrt{N}}\tilde{G}^N(0, \eta_0)\\
&\text{\quad\quad\quad}-\frac{1}{\sqrt{N}}
\int_0^{tN}\left(S(N)F(\eta_s)-\mathbb{E}_{\mu_p}S(N)F(\eta_s)\right)ds\Big)=0
\end{align*}
in $L^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2604.14752, 'Strong and weak rates of convergence in the Smoluchowski--Kramers approximation for stocha'] For all $\alpha\in[0,1]$ and all $\delta\in[0,\frac{\alpha}{2}]$, there exists $C_{\alpha,\delta}\in(0,\infty)$ such that, for all $\epsilon\in(0,1)$, all $t>0$ and all $u\in H^{\alpha-2\delta}$ one has
\begin{equation}
\|\Pi_u e^{tA_\epsilon}(u,0)-e^{-t\IL}u\|_{H}\le C_{\alpha,\delta}\epsilon^{\alpha}t^{-\delta}\|u\|_{H^{\alpha-2\delta}}.
\end{equation}
Moreover, for all $\alpha\in[0,1]$ and all $\delta\in[\frac{\alpha}{2},\frac12]$, there exists $C_{\alpha,\delta}\in(0,\infty)$ such that, for all $\epsilon\in(0,1)$, all $t>0$ and all $v\in H^{\alpha-2\delta}$ one has
\begin{equation}
\|\Pi_u e^{tA_\epsilon}(0,\frac{v}{\epsilon})-e^{-t\IL}v\|_{H}\le C_{\alpha,\delta}\epsilon^{\alpha}t^{-\delta}\|v\|_{H^{\alpha-2\delta}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] Let us fix $T>0$, $p\in [2, \infty)$ and $u_0\in \Vp\cap \bM$. If $u_m$ denotes the unique solution of the SDE \eqref{eqn-Faedo-Galerkin}, then, for each fixed $m\in \N$, the following estimate holds true:
			\begin{align}
				& \sup_{m\in\N}\E \bigg[ \sup_{t\in[0,T]}\big(\|u_m(t)\|_{H_0^1(\bO)}^{4} + \|u_m(t)\|_{L^p(\bO)}^{2p}\big) \bigg] + \sup_{m\in\N}\E\left[\int_0^T\|{P_m(|u_m(t)|^{p-2}u_m(t))}\|_{L^{2}(\bO)}^{2}dt\right]\\
				& \quad + \sup_{m\in\N}\E\left[\int_0^T\|\Delta u_m(t)\|_{L^2(\bO)}^2dt\right] + 2(p-1)\sup_{m\in\N}\E\left[\int_0^T\||u_m(t)|^{\frac{p-2}{2}} \nabla u_m(t)\|_{L^2(\bO)}^2dt\right]\\
				& \leq C\left(\|u_0\|_{\Vp},T,  \sum_{i=1}^M \|f_i\|_{\Vp}\right).
			\end{align}

