body:
[Proposition 1 of arXiv:2506.12834, 'Space-time fractional stochastic partial differential equations driven by L\'evy white noi'] Let $p\in[1,2]$. For any $\cF_t$-adapted function $\phi:[0,\infty)\times\R^d\times E\times \Omega\to\R$ satisfying
  \begin{equation*}
    \int_{0}^{t}\int_{\R^d}\int_E \E\left[\left|\phi(s,x,\xi)\right|^p\right]\ud s\ud x \mu(\ud\xi)<\infty,
  \end{equation*}
  the stochastic integral
  \begin{equation*}
    \int_{0}^{t}\int_{\R^d}\int_E \phi(s,x,\xi)   M(\ud s,\ud x,\ud\xi)
  \end{equation*}
   is well defined in $L^p(\Omega,\cF,\P)$ and is $\{\cF_t\}$-adapted. Moreover, the following inequality holds
   \begin{equation*}
     \E\left[\left|\int_{0}^{t}\int_{\R^d}\int_E \phi(s,x,\xi) M(\ud s,\ud x,\ud\xi)\right|^p\right]\le C\int_{0}^{t}\int_{\R^d}\int_E \E\left[\left|\phi(s,x,\xi)\right|^p\right]\ud s\ud x \mu(\ud\xi).
   \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem -gmX^p1 of arXiv:2411.01849, 'A tamed-adaptive Milstein scheme for stochastic differential equations with low regularity'] For any $p>0$, there exists a positive constant $C_p$, which does not depend on $\Delta$, such that for any $s>0$, it holds that 
	 	\begin{align}
	\mathbb{E}\left[|\widehat{X}_s^p -\widehat{X}_{\underline{s}}^p|\big| \mathcal{F}_{\underline{s}}\right] \leq C_p\sum\limits_{i=0}^{p-2}  |\widehat{X}_{\underline{s}}|^i.
	\end{align}

[Proposition 30 of arXiv:2607.16479, 'The Site Frequency Spectrum in an Exponentially-Growing Population with Selection'] Let $J_\varepsilon(t)\lsimas{t}{\infty}\exp\left(\left(\frac{\lambda_0\lambda_1}{\lambda_0+\lambda_1}+\varepsilon\right)t\right)$ be monotone, then:
    \begin{align*}
        \limsup_{t\to\infty} S_{J_\varepsilon(t)}(t)\gsimas{\varepsilon}{0^+}\varepsilon^{-1}
    \end{align*}
    on $\Omega_0^\infty$.

