body:
[Lemma a22 of arXiv:2411.19926, 'Sparse Pseudospectral Shattering'] Suppose $\frac{1}{n} < \rho \le 1$, $0 < s < \frac{2}{e}$, $\varepsilon > 0$, and integer $K \ge 1$. Let
\[
    T = \left(2 \varepsilon n \sqrt{\frac{2}{s}}\right)^{1/K}, \quad H = \left(\frac{\log(2/s)}{\rho}\right)^{1/K}.
\]
Furthermore let $R \ge 1$ and suppose
\begin{equation} 
    T \le \frac{1}{Rn}, \quad \frac{\varepsilon}{T^{(K-1)}} \le \frac{1}{n^2}, \quad T \ge (4n)^{1/K}\exp\left(-\frac{\rho n }{4KH}\right), \quad H^K \le n, \quad H^{K-1} \le \frac{1}{\rho}.
\end{equation}
Then for $n \ge 30$ we have
\begin{equation} 
    \Pr\pare{\exists v\in\textnormal{\texttt{Comp}}(2\varepsilon\sqrt n,s)\,\,\textnormal{s.t.}\,\,\left\|(M+N_g)v\right\|\le\varepsilon}
    \le 55K^2 e^{-\frac34 n\rho} +\Pr\mleft(\left\|M+N_g\right\|_\infty\ge R\mright).
\end{equation}

