[Lemma 12 of arXiv:2609.04095, '2609.04095'] For \(x>0\) and \(L=N-1\),
\begin{align*}
 \sum_{\substack{0\le u\le N\\u\ {\rm odd}}}
 u\binom Nu x^u
 &=Nx\mathcal E_{N-1}(x),\\
 \sum_{\substack{0\le u\le N\\u\ {\rm odd}}}
 u(u-1)\binom Nu x^u
 &=N(N-1)x^2\mathcal O_{N-2}(x),\\
 \sum_{\substack{0\le v\le L\\v\ {\rm odd}}}
 v\binom Lv x^v
 &=Lx\mathcal E_{L-1}(x),\\
 \sum_{\substack{0\le v\le L\\v\ {\rm odd}}}
 \frac1{v+1}\binom Lv x^v
 &=\frac{\mathcal E_{L+1}(x)-1}{(L+1)x}.
\end{align*}

[Proposition prop:central-tower of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] The truncations $\pi_N:G^{(N+1)}\to G^{(N)}$ are surjective group homomorphisms with central kernel
\begin{equation}
\ker\pi_N=\exp(\mathfrak{L}_{N+1})\cong\mathbb{R}^{\ell_d(N+1)}.
\end{equation}
Hence the representation ladder
\begin{equation}
\cdots\twoheadrightarrow\mathrm{Sig}^{(N+1)}\twoheadrightarrow\mathrm{Sig}^{(N)}\twoheadrightarrow\cdots
\end{equation}
is a tower of central extensions, each step forgetting exactly the top-degree free-Lie directions, of dimension the Witt number $\ell_d(N+1)$.

[Lemma lem-LDPforXi of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Fix a window $W=[-R,R]^d$ and any $\psi\in{\mathcal M }_1({\mathcal T }_W)$.  Then, under ${{\tt Q}}^{\ssup{\Lambda_N,{\rm bc}}}$ conditioned on $\{\partial\Pi_W^{{{\scriptscriptstyle{({\mathcal S }})}}}(\Xi_{N,R})=\psi_N\}$ for some $\psi_N\to\psi$, the sequence $(\Xi_{N,R})_{N\in\mathbb{N}}$ satisfies an LDP on ${\mathcal M }_1({\mathcal L }_W\times{\mathcal S }_W)$ with speed $|\Lambda_N|$ with rate function
\begin{equation}
J_{W}^{{{\scriptscriptstyle{({\psi}})}}}(\xi) =\begin{cases}\frac 1{|W|} H_{{\mathcal L }_W\times{\mathcal S }_W}\big(\xi\,\big|\,\Pi_W^{{{\scriptscriptstyle{({\mathcal L }})}}}({\tt Q})\otimes [\psi\otimes {\tt K}_{W}]\big)&\mbox{if }\partial\Pi_W^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi)=\psi\mbox{ and }\xi\in\bigcap_{k\in\mathbb{N}}{\mathcal M }_1^{{{\scriptscriptstyle{({k}})}}}({\mathcal L }_W\times{\mathcal S }_W),\\
+\infty&\mbox{otherwise.}
\end{cases}
\end{equation}

