[Lemma lem:mart of arXiv:2607.26169, 'Scaling and partial universality of the height zero probability in the 2D Abelian sandpile'] For any function $g : \mathcal{V} \to \mathbb{R}$, and for any $v \in \mathcal{V}$, we have that
\eqnst{
  g(S_n) - g(S_0) - \sum_{t=0}^{n-1} \frac{1}{\deg(S_t)} \Delta g (S_t), \quad n \ge 0, }
is a martingale under $\mathbf{P}^v$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 17 of arXiv:2608.16256, 'Error Distribution of the Local Linearization Method for Stochastic Differential Equations'] \label[proposition]{prop:ll_R45_ucp_zero}
For \(\ell=4,5\),
\begin{equation}
    R^{(\ell),n}
    \xrightarrow{\mathrm{ucp}}0 .
\end{equation}

[Lemma 7 of arXiv:2608.30991, 'A block-Toeplitz approach to the spectrum of the Neumann-Poincaré operator on self-similar'] For $m \neq 0$, the blocks in Lemma~\ref{lem: Toeplitz structure of NP operator} satisfy the exponential decay bounds:
	\begin{equation*}
		\| r^{m\alpha} \tilde{K}^*_m \|_{\mathcal{L}(W_0^{s,p}(\Gamma_0))} \le \begin{cases} 
			C r^{m\alpha}, & m > 0, \\ 
			C r^{|m|(d-\alpha)}, & m < 0, 
		\end{cases}
	\end{equation*}
	for some constant $C > 0$ independent of $m$. Moreover, $\tilde{K}^*_m \in \mathcal{K}(W_0^{s,p}(\Gamma_0))$ for all $m \in \mathbb{Z}$.

[Prp 4 of arXiv:2606.14917, 'The Ornstein--Uhlenbeck process on $\scr P_2$ \\with a volatility operator'] If $u$ is given as in \eqref{eq:u}, \eqref{eq:ubounds}, then $u\circ\Psi_\lam, \partial_g (u\circ\Psi_\lam) \in W^{1,2}(T_\lam,G)$ for $g\in T_\lam\setminus\{0\}$ and
	\begin{multline*}
		\partial_g\partial_g(u\circ\Psi_\lam)(f)=\Big(\sum_{i,j=1}^m\partial_i\partial_jF\big(\lam(\varphi_1\circ f),\dots,\lam(\varphi_m\circ f)\big)
	{\big\la \na^\euc\varphi_i \circ f,g\big\ra}_{T_\lam}{\big\la \na^\euc\varphi_j \circ f,g\big\ra}_{T_\lam}\Big)
	\\+\Big(\sum_{i=1}^m\partial_iF\big(\lam(\varphi_1\circ f),\dots,\lam(\varphi_m\circ f)\big){\big\la g,(\hes\varphi_i \circ f)g\big\ra}_{T_\lam}\Big).
	\end{multline*}
	for $f\in T_\lam$. In particular,
	\begin{multline*}
		\div \big(B\na(u\circ\Psi_\lam)\big)(f)=
		\Big(\sum_{i,j=1}^m\partial_i\partial_jF\big(\lam(\varphi_1\circ f),\dots,\lam(\varphi_m\circ f)\big)
		{\big\la B(\na^\euc\varphi_i \circ f),\na^\euc\varphi_j \circ f\big\ra}_{T_\lam}\Big)\\
		+\Big(\sum_{n=1}^\infty\sum_{i=1}^m\partial_iF\big(\lam(\varphi_1\circ f),\dots,\lam(\varphi_m\circ f)\big){\big\la Bg_n,(\hes\varphi_i \circ f)g_n\big\ra}_{T_\lam}\Big)
	\end{multline*}
	for any positive, symmetric trace class operator $B$ on $T_\lam$, orthonormal basis ${(g_n)}_{n\in\NN}$ and $f\in T_\lam$.

[Theorem 1 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Assume \eqref{H1}--\eqref{H2}. Define $\alpha(t) :=\frac{1}{4}\int_0^t\sigma(W^{\ell^\sigma}_s)^2\d s$. Let $\alpha^{-1}(t)$ be the inverse of $\alpha(t)$.\footnote{We will verify in Lemma~\ref{lem:alpha} that $\alpha$ is a.s. strictly increasing, so $\alpha^{-1}(t)$ is well-defined.} Then
\begin{align}
    \Big(n^{-1}C_{\lfloor 2n^2 t_1\rfloor}(\mathscr{T}^{n}), n^{-1}H_{\lfloor n^2 t_2\rfloor}(\mathscr{T}^{n})\Big)_{0\le t_1,t_2<\infty} \overset{d}{\longrightarrow} \Big(W_{\alpha^{-1}(t_1)}^{\ell^\sigma}, W^{\ell^\sigma}_{\alpha^{-1}(t_2)}\Big)_{0\le t_1,t_2<\infty}
\end{align}
in the product space \(\big(D[0, \infty)\big)^2\) equipped with the product Skorokhod topology
(where the functions on both sides are extended by \(0\) outside their original domains). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm:not independent of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Suppose Assumption (Assumption G-SDE of the paper)  and the following statments hold:
        \begin{itemize}
            \item $b,h_{ij}$ are Lipschitz continuous;
            \item there is a positive definite $q\in Q$ where $Q$ is given in (equation Set for G-BM of the paper);
            \item $\sigma$ is uniformly nondegenerate, i.e., there exists  a positive definite matrix $\Sigma\in \mathbb S_d$ such that
        \[
        \sigma^{\top}(x)\sigma(x)\geq \Sigma, \text{ for all } x\in \mathbb R^n.
        \]
        \end{itemize}
        Then for any $t>s$, $\tilde \xi_t$ is NOT independent from $\tilde \xi_s$.

