[Lemma 63 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $U,V$ be quasi-Banach spaces and let $T\colon U\to V$ be a compact linear map and let $t\in(0,\infty)$.
    Assume that 
    \begin{equation*}
       \liminf_{k\to \infty} \bigl( k^{t} \cdot \en_k(T)\bigr) >0.
    \end{equation*}
    Then $\bigl(T(\ball_U), \norm{\cdot \mid V}\bigr)$ is totally bounded and we have $\lmd\bigl(T(\ball_U)\bigr) \ge \frac{1}{t}$.

[Lemma lem:kpz-red-derivative-identities of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Under the hypotheses of
Proposition~(thm:kpz-red-Darboux of the paper), the dressed
observable $\mathcal A=z\Phi R\Psi$ satisfies
\begin{align}
\mathcal A_a
&=\mathcal F_{1,0}-\mathcal A^2+\mathcal F_{0,1},
 \\
\mathcal A_{aa}
&=\mathcal F_{2,0}+\mathcal F_{0,2}
+2\mathcal F_{1,1}
-\mathcal F_{1,0}\mathcal A
-\mathcal A\mathcal F_{0,1}
-\mathcal A_a\mathcal A
-\mathcal A\mathcal A_a,
 \\
\mathcal A_x
&=\mathcal F_{0,2}-\mathcal F_{2,0}
+\mathcal A\mathcal F_{1,0}
-\mathcal F_{0,1}\mathcal A
+2C\mathcal A-2\mathcal A C,
 \\
\mathcal A_t
&=-\tfrac13\mathcal F_{3,0}
  -\tfrac13\mathcal F_{0,3}
  +\tfrac13(\mathcal F_{0,2}\mathcal A
  -\mathcal F_{0,1}\mathcal F_{1,0}
  +\mathcal A\mathcal F_{2,0})
\notag \\
&\quad
  +C\mathcal F_{1,0}+\mathcal F_{0,1}C
  -\mathcal A C\mathcal A
  +(\Lambda+C_a)\mathcal A
  -\mathcal A\Lambda.

\end{align}

[Lemma 15 of arXiv:2606.11389, 'Instability of a nonlinear oscillator with small friction and small additive noise'] {\rm \cite[Lemma 11]{BG02}}
 Let $f$ be a smooth
function on ${\bf R}^2 \setminus \{(0,0)\}$. Write $\tilde{f}(x,y) = f(x,y) - \int f \,dm_h$ for $(x,y)
\in H^{-1}(h)$.  Then there is a unique function $F$ on ${\bf R}^2
\setminus \{(0,0)\}$ such that $U_1.F(x,y) = \tilde{f}(x,y)$ and
$F(0,y) = 0$ for all $y > 0$.  Moreover we have the equality
  \begin{equation} \nonumber
  U_1.(U_2.F)(x,y)  = U_2.\tilde{f}(x,y) - J(x,y)\tilde{f}(x,y)
    \end{equation}
and the inequalities
   \begin{align*}
   |F(x,y)| & \le   T(h)\sup\{|\tilde{f}(u,v)|: (u,v) \in H^{-1}(h)\}, \\
   |(U_2.F)(x,y)| & \le   T(h)\sup\{|(U_2-J).\tilde{f}(u,v)|: (u,v) \in H^{-1}(h)\},
       \\
   |(U_2^2.F)(x,y)| & \le  T(h)\sup\{|(U_2-J)^2.\tilde{f}(u,v)|: (u,v) \in
   H^{-1}(h)\} 
   \end{align*}
valid for $(x,y) \in H^{-1}(h)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:small-ball of arXiv:2411.12192, 'Sample path properties and small ball probabilities for stochastic fractional diffusion eq'] Let $\{u(t,x), t \ge 0, x \in \mathbb{R}^d\} $ be the solution of (equation e:fde of the paper) and recall that $\theta_1$ and $\theta_2$  are given in (equation e:theta12 of the paper).
  \begin{enumerate}[(1)]
    \item (Small ball probability in time). Assume the conditions (equation e:DL of the paper) and (equation e:tilde-U-exist of the paper) hold. Assume additionally
    either $\beta+\gamma-2\le0$ or
    \begin{equation*}
      \begin{cases}
        \beta+\gamma-2>0, \\
        -H_0+\frac{\beta}{\alpha}(d-H)<1.
      \end{cases}
    \end{equation*}
        Then,
    \begin{equation*}
      \lim_{\varepsilon\to0} \varepsilon^{1/\theta_1}\log\mathbb P\bigg\{\max_{t\in[0,1]}|u(t,x)|\le\varepsilon\bigg\} = -C_1^{1/2\theta_1}\kappa ,
    \end{equation*}
    where $C_1$ is defined in (equation e:de-C1 of the paper) and $\kappa$ is the small ball constant of a fractional Brownian motion
    with index $\theta_1$ (e.g. [Li2001Gaussian]).
    \item (Small ball probability in space). Assume the conditions (equation e:DL of the paper) and (equation e:hat-U-exist of the paper) hold. There exist
    positive constants $c$ and $C$ independent of $t>0$ such that for sufficiently small $\varepsilon>0$,
    \begin{equation*}
      \exp\left(-\frac{c}{\varepsilon^{d/\theta_2}}\right)\le \mathbb P\bigg\{\max_{x\in[-1,1]^d}|u(t,x)-u(t,0)|\le\varepsilon\bigg\}\le \exp\left(-\frac{C}{\varepsilon^{d/\theta_2}}\right).
    \end{equation*}
    \item (Space-time joint small ball probability). Assume the conditions (equation e:DL of the paper) and (equation e:U-exist of the paper) hold. Assume additionally
    either $\beta+\gamma-2\le0$ or
    \begin{equation*}
      \begin{cases}
        \beta+\gamma-2>0, \\
        -H_0+\frac{\beta}{\alpha}(d-H)<1.
      \end{cases}
    \end{equation*}
    Then, there exist positive constants $c$ and $C$ such that for sufficiently small $\varepsilon>0$,
    \begin{equation*}
      \exp\left(-\frac{c}{\varepsilon^{Q}}\right)\le \mathbb P\left\{\max_{(t,x)\in [0,1]\times[-1,1]^d}|u(t,x)|\le\varepsilon\right\}\le \exp\left(-\frac{C}{\varepsilon^{Q}}\right),
    \end{equation*}
  where $Q=\frac{1}{\theta_1}+\frac{d}{\theta_2}$.
  \end{enumerate}

