[Proposition prop_key of arXiv:2507.06522, 'Balanced multi-species spin glasses'] Assume that both $(\vc \Delta,\vc\lambda_N)$ and $(\widetilde{\vc\Delta},\vc\lambda_N)$ satisfy (equation delta_decay_finite of the paper).
For either ${\scaleobj{1.1}{\diamond}}\in\{\mathsf{Ising},\mathsf{spherical}\}$, we have
\begin{subequations} 
\begin{align}

F_{N,{\scaleobj{1.1}{\diamond}}}(\widetilde{\vc\Delta},\vc\lambda_N)- F_{N,{\scaleobj{1.1}{\diamond}}}(\vc\Delta,\vc\lambda_N) 
&\leqslant \frac{1}{2}\Big[\xi_{N,\widetilde{\vc\Delta}}({\boldsymbol 1})-\xi_{N,\vc\Delta}({\boldsymbol 1}) \nonumber \\
&\phantom{\leqslant\frac12\Big[}+ \sup_{{\boldsymbol x}\in[-1,1]^\mathscr{S}}\big(\xi_{N,\vc\Delta}({\boldsymbol x})-\xi_{N,\widetilde{\vc\Delta}}({\boldsymbol x})\big)\Big], \\

\text{and}\quad |F_{N,{\scaleobj{1.1}{\diamond}}}(\vc\Delta,\vc\lambda_N) - F_{N,{\scaleobj{1.1}{\diamond}}}(\widetilde{\vc\Delta},\vc\lambda_N)| &\leqslant \sup_{{\boldsymbol x}\in[-1,1]^\mathscr{S}} |\xi_{N,\vc\Delta}({\boldsymbol x})-\xi_{N,\widetilde{\vc\Delta}}({\boldsymbol x})|.
\end{align}
\end{subequations}
In the large-$N$ limit: if (equation converging_ratios of the paper)  holds, and both $(\vc\Delta,\vc\lambda)$ and $(\widetilde{\vc\Delta},\vc\lambda)$ satisfy (equation delta_decay of the paper), then
\begin{subequations} 
\begin{align}

\limsup_{N\to\infty}\big(F_{N,{\scaleobj{1.1}{\diamond}}}(\widetilde{\vc\Delta},\vc\lambda_N)-F_{N,{\scaleobj{1.1}{\diamond}}}(\vc\Delta,\vc\lambda_N)\big)
&\leqslant\frac{1}{2}\Big[\xi_{\infty,\widetilde{\vc\Delta}}({\boldsymbol 1})-\xi_{\infty,\vc\Delta}({\boldsymbol 1}) \nonumber \\
&\phantom{\leqslant\frac12\Big[}+\sup_{{\boldsymbol x}\in[0,1]^\mathscr{S}}\big(\xi_{\infty,\vc\Delta}({\boldsymbol x})-\xi_{\infty,\widetilde{\vc\Delta}}({\boldsymbol x})\big)\Big], \\

\text{and}\quad\limsup_{N\to\infty}|F_{N,{\scaleobj{1.1}{\diamond}}}(\widetilde{\vc\Delta},\vc\lambda_N)-F_{N,{\scaleobj{1.1}{\diamond}}}(\vc\Delta,\vc\lambda_N)|
&\leqslant\sup_{{\boldsymbol x}\in[0,1]^\mathscr{S}}|\xi_{\infty,\vc\Delta}({\boldsymbol x})-\xi_{\infty,\widetilde{\vc\Delta}}({\boldsymbol x})|.
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 2 of arXiv:2606.04950, 'The Tricomi equation in the hyperbolic half plane under additive space-time Gaussian White'] For any $t>0$ the stochastic process $\{U(t,x)\}_{x\in\mathbb{R}}$ is second order stationary with expectation
\begin{align*}
\mathbb{E}[U(t,x)]=0\quad\mbox{ for all }x\in\mathbb{R}
\end{align*}
and covariance
\begin{align}
\mathtt{cov}(U(t,x),U(t,y))=\frac{1}{2\pi^2}\int_0^{+\infty}\cos(\rho |x-y|)\int_0^t|C(t,s,\rho)|^2dsd\rho\quad\mbox{ for all }x,y\in\mathbb{R}.
\end{align}
Moreover, the correlation function
\begin{align*}
r_t(h):=\frac{\mathtt{cov}(U(t,x+h),U(t,x))}{\mathbb{V}[U(t,x)]},\quad t>0,x,h\in\mathbb{R},
\end{align*}
verifies
\begin{align*}
r_t(h)=1-\alpha_t|h|+o(|h|)\mbox{ as $|h|$ tends to zero},
\end{align*}
with
\begin{align*}
\alpha_t:=\frac{\pi}{2\int_0^{+\infty}\int_0^{t}\left|C(t,s,\rho)\right|^2ds d\rho}.
\end{align*}
In particular, the stochastic process $\{U(t,x)\}_{x\in\mathbb{R}}$ admits a continuous modification. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 14 (Zero cone) of arXiv:2609.02595, 'Minimal Radial Sub-Gamma Envelopes for Infinitely Divisible Random Vectors'] For every centered infinitely divisible vector with finite second moment,
\begin{equation}
 \{t:C_X(t)=0\}
 =\{t:b_X(t)=0\}
 =\bigl(\overline{\cone}(\supp\nu)\bigr)^\circ.
\end{equation}

[Corollary 2DHD-cor6.7 of arXiv:2604.21591, '\bf Long-time dynamics of stochastic 2D hydrodynamic-type evolution equations driven by mu'] Under the hypotheses of Lemma (2DHD-lemma6.3 of the paper). For every $\tau \in \mathbb{R}$, $D=\{D(t):t\in \mathbb{R}\}\in \mathscr{D}$, there exists $\varepsilon_0=\min\left\{\sqrt{\frac{\mu\lambda_1}{2\widehat{L}_{gv}}},\sqrt{\frac{\mu\lambda_1}{12L_g+2\mathbf{c}_4L_g+8\mathbf{c}_4\widetilde{L}_g}}\right\}$ and $T:=T(\tau,D)> 1$ such that for all $t\geq T$ and $\varepsilon_1, \varepsilon_2 \in (0,\varepsilon_0]$, the solution $ u$ of system ((2DHD-1.1 of the paper)) satisfies
	\begin{align}
		&~\mathbb{ E}\left[\|u(\tau,\tau-t,u_{\tau-t})\|_{H}^4\right]\leq \rho_5 +\rho_5\int_{-\infty}^{\tau}e^{-\widetilde{\kappa} (\tau-s)} \|f(s)\|_{H}^{4} ds,
	\end{align}
	where $u_{\tau-t}\in L^{4}(\Omega,\mathscr{F}_{\tau-t};H)$ with $\mathscr{L}(u_{\tau-t}) \in D(\tau-t)$, and $\rho_5>0$ is a constant independent of $u_{\tau-t}$, $\varepsilon_1$, $\varepsilon_{2}$, $\tau$ and $D$.

