[Theorem 1 (Harnack inequality) of arXiv:2604.10142, 'H\MakeLowercase{arnack inequality for} $p$\MakeLowercase{-harmonic functions: \\ improved '] Let $u$ be a positive $p$-harmonic function on $B_R(0)$ where $R>1$. Then $u$ satisfies the Harnack inequality:
        \begin{equation}
            \sup_{B_1(0)}u\leq H_R(p,d)  u(0),
        \end{equation}
        where $\displaystyle H_R(p,d) \le \exp\left( C_R \, \frac{d}{p-1}\log\frac{d}{p-1}\right)$ and $C_R$ depends only on $R$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 8 of arXiv:2512.08745, 'Variance strikes back: sub-game--perfect Nash equilibria in time‑inconsistent $N$‑player g'] Let {\rm\Cref{assumption:regularityForNecessityZero}} hold, and let $\hat\balpha \in \mathcal{NA}_{s,0}$ be a zero-sum sub-game--perfect Nash equilibrium. Then, one can construct a quadruple $(Y,Z,M^{\star},Z^{m,\star})$ that satisfies the following system $\P \text{\rm--a.s.}$
\begin{align}
\notag Y_t &= g\big(X^1_{\cdot \land T}\big) + G\big(\varphi(X^1_{\cdot \land T})\big)\big) + \int_t^T \bigg( f_s\big(X^1_{\cdot \land s},\hat\alpha^1_s,\hat\alpha^2_s\big) + Z_s \cdot b_s\big(X^1_{\cdot \land s},\hat\alpha^1_s,\hat\alpha^2_s\big) - \frac{G^{\prime\prime}\big(M^{\star}_s\big)}{2} \|Z^{m,\star}_s\|^2 \bigg) \d s\\
&\quad - \int_t^T Z_s \cdot \d W_s^1, \; t \in [0,T], \\
M^{\star}_t &= \varphi\big(X^1_{\cdot \land T}\big) + \int_t^T Z^{m,\star}_s \cdot b_s\big(X^1_{\cdot \land s},\hat\alpha^1_s,\hat\alpha^2_s\big) \d s - \int_t^T Z^{m,\star}_s \cdot \d W_s^1, \; t \in [0,T].
\end{align}
It holds that $J(t,\cdot,\hat\balpha) = Y_t$, $\P\text{\rm--a.s.}$, for every $t \in [0,T]$. Moreover, for some $p \geq 1$, the following integrability condition holds true
\begin{align*}
&\sup_{\balpha \in \cA^\smalltext{2}_\smalltext{1}} \E^{\P^{\smalltext{\balpha}}} \Bigg[ \sup_{t \in [0,T]} |Y_t|^p + \bigg(\int_0^T \|{Z}_t\|^2 \d t\bigg)^\frac{p}{2} \Bigg] +\esssup_{\balpha \in \cA^\smalltext{2}_\smalltext{1}} \Bigg\{\sup_{t \in [0,T]} | M^{\star}_t| + \sup_{\tau \in \cT_{0,T}} \E^{\P^{\smalltext{\balpha}\smalltext{,}\smalltext{\tau}}_{\smalltext{\cdot}}} \bigg[ \int_\tau^T \|Z^{m,\star}_t\|^2 \d t \bigg] \Bigg\} < +\infty.
\end{align*}
Finally, we have, $\d t \otimes \d \P\text{\rm--a.e.} \; (t,\omega) \in [0,T] \times \Omega$,
\begin{align}
\notag \sup_{\tilde{a} \in A} \inf_{a \in A} \big\{f_t(X^1_{\cdot \land t}, a, \tilde{a}) +  Z_t \cdot b_t(X^1_{\cdot \land t},a,\tilde{a}) \big\} &= \inf_{a \in A} \sup_{\tilde{a} \in A}\big\{f_t(X^1_{\cdot \land t}, a, \tilde{a}) + Z_t \cdot b_t(X^1_{\cdot \land t},a,\tilde{a}) \big\} \\
&=f_t\big(X^1_{\cdot \land t}, \hat\alpha^1_t, \hat\alpha^2_t \big) +  Z_t \cdot b_t\big(X^1_{\cdot \land t},\hat\alpha^1_t, \hat\alpha^2_t \big).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 17 of arXiv:2609.02415, 'Nef Cones of Hilbert Schemes of Orthogonal Grassmannians'] The nef cone of the Hilbert scheme $\mathrm{Hilb}_{P_{d,r}(t)}(OG(q;V))$ is a cone generated b $6$ classes
\begin{align*}
(\pi_1^1\circ \varphi_1)^*\sigma_1^{(1,1)},\;\;(\pi_2^1\circ \varphi_1)^*\sigma_1^{(2,1)},\;\;\bigl[D_{Y_{\widetilde{\lambda^1}}}\bigr],\;\; (\pi_1^2\circ \varphi_2)^*\sigma_1^{(1,2)},\;\; (\pi_2^2\circ \varphi_2)^*\sigma_1^{(2,2)}\;\;\text{and}\;\;\bigl[D_{Y_{\widetilde{\lambda^2}}}\bigr].
\end{align*}

[Prop R_1< R_0 of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] Let $O_n$ be the event defined in (equation definition of O_n of the paper) and $S_n$ is the random walk defined in (equation def of S_n and S_n hat of the paper). Then, for some absolute constant $C$, 
   \begin{align}
         R_n^1 = \mathbb{E}\biggl[\frac{1}{|X_0-X_2|^2|X_0-X_3|^2|S_n|^4} \mathbbm{1}_{O_n}\biggr] \leq C\mathbb{E}\biggl[\frac{1}{|(X_0-X_2)S_n|^2} \mathbbm{1}_{O_n}\biggr] = C R_{n}^0.
   \end{align}

[Lem 16 (Existence of the solution to \eqref{eq:Gstareq}) of arXiv:2604.06122, 'REM universality for linear random energy'] There exists $ N_{\e}>0$ such that for any $n>N_{\e}$ and $h\in \mathfrak{L}^{\e}_{n}$ and $x\in \mathfrak{R}_{n,\lambda^*}(h)$ the system of equations \eqref{eq:Gstareq} admits a solution \been{
(\tilde A_n(h), \tilde \Lambda_n(h),\tilde \Lambda^{x}_n(h))
}
satisfying
\been{

\tilde A_n(h)\in [A^{-}_n(h),A^{+}_n(h)],\quad \tilde \Lambda_n(h)\in [\Lambda^{-}_n(h),\Lambda^{+}_n(h)],\qquad \tilde\Lambda^{x}_n(h)\in [\Lambda^{-,x}_n(h),\Lambda^{+,x}_n(h)].
}
with
\begin{align}
A^{-}_n(h) &:= A_n(h, C^{-}_n), & 
A^{+}_n(h) &:= A_n(h, C^{+}_n),\\
\Lambda^{-}_n(h) &:= \Lambda_n(h, A^{-}_n(h)), &
\Lambda^{+}_n(h) &:= \Lambda_n(h, A^{+}_n(h)),\\
\Lambda^{-,x}_n(h) &:= \Lambda_n(h, A^{-}_n(h)+x), &
\Lambda^{+,x}_n(h) &:= \Lambda_n(h, A^{+}_n(h)+x).
\end{align}

