K_{t,x-1,m}-K_{t,x,m}
  &=\psi_{t,x-1,m}\phi_{t,x-1,m},
 \\
\partial_tK_{t,x,m}
  &=-\gamma\psi_{t,x-1,m}\phi_{t,x,m},
 \\
K_{t,x-1,m+1}-K_{t,x,m}
  &=-\tau\psi_{t,x-1,m}\phi_{t,x-1,m+1}.

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

