[Lem1 26 of arXiv:2608.29797, 'Mean-field branching SDEs: propagation of chaos, scaling limits and phase transitions'] If $a>a_\star^{\rm log}$, then
\begin{equation}
 \liminf_{t\to\infty}m_t>0.

\end{equation}

[Theorem 1 of arXiv:2605.27713, 'Lower path regularity in all dimensions'] Suppose that $X=(X_t)_{t\in[0,T]}$ satisfies Assumption \ref{a1} and that
		\begin{equation}
			0\leq \alpha<d\quad\text{if $Hd<1$}\qquad\text{respectively}\qquad \max\big(0,d-\frac{1}{H}\big)<\alpha<d\quad\text{if $Hd\geq 1$}.
		\end{equation}

		\begin{enumerate}
			\item[(i)] For any $t \in (0,T)$  there is a constant $c_2(t)>0$ such that
			\begin{equation}

				\limsup _{r \to 0}\: \sup_{x\in\rr^d}\:\frac{L^{\alpha,X}(x,[t-r,t+r])}{r^{1-H(d-\alpha)} (\log \log r^{-1})^{H(\theta+d-\alpha)}} \leq c_2(t)\qquad \text{$\mathbb{P}$-a.s.}
			\end{equation}
			\item[(ii)] There is a constant $c_3>0$ such that
			\begin{equation}

				\limsup _{r \to 0} \sup_{t\in(0,T)} \sup_{x\in\rr^d} \frac{L^{\alpha,X}(x,[t-r,t+r])}{r^{1-H(d-\alpha)} (\log r^{-1})^{H(\theta+d-\alpha)}} \leq c_3 \qquad \text{$\mathbb{P}$-a.s.}
			\end{equation}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lm 19 of arXiv:2604.20435, 'Stochastic Extinction with Relaxed Boundedness Conditions'] Let $p^*\in (0,\frac{\gamma_0}4)$ be fixed.
	There is a universal constant $\wdt C$, independent of $\by,\by_1$ such that
	\begin{equation}
		\E\big( \sup_{t\leq\xi_\delta} e^{p^* t}|\BY_1(t)-\wdt\BY_1(t)|^2\big)\leq \wdt C(|\by_1-\wdt \by_1|^2+\delta^2).
	\end{equation}

