body:
[Proposition prop:BE-kernel of arXiv:2605.16244, 'Analysis of a twisted Bose--Einstein Markov chain with applications to sampling Catalan st'] Let $K$ and $\pi$ be the transition kernel and the stationary distribution of the twisted Bose--Einstein Markov chain on $[k]^n$. Then for all $x,y \in [k]^n$,
\begin{equation}
 K(x,y)
 =
 \prod_{a=1}^k
 \frac{\displaystyle\prod_{b=1}^k
 \left(\frac{\theta}{k}\right)_{(m_{a,b}(x,y))}}
 {(\theta)_{(i_a(x))}}
 \end{equation}
and
\begin{equation} 
 \pi(x)
 =
 \frac{\displaystyle\prod_{a=1}^k(\theta)_{(i_a(x))}}
 {(k\theta)_{(n)}}.
\end{equation}

