[Lemma 5 (anisotropic Sobolev embedding) of arXiv:2609.01093, 'Ideal MHD below the classical well-posedness threshold'] Let
\begin{equation}
 \sreg>\frac{n-1}{2},\qquad \preg\ge0,\qquad \sreg+\preg>\frac n2 .
\end{equation}
Then every $f\in Y^{\sreg,\preg}(\Rn)$ satisfies
\begin{equation}
 \|f\|_{L^\infty(\Rn)}
 \le
 \frac{C(n,\sreg,\preg,v_{\rm A})}
 {(\sreg+\preg-\frac n2)^{1/2}}
 \|f\|_{Y^{\sreg,\preg}} .
\end{equation}
Both strict inequalities in \eqref{eq:Y-embed-range} are necessary.

[Theorem 4 of arXiv:2604.16795, '2604.16795'] Under Assumption {\rm\ref{A0}}, for any measurable function $\phi$ on $\R^d$ satisfying
	\begin{align}
		\int_{\R^d} H_{c,c_0}(y) |\phi(y)| \,\mu(\d y) <\infty
	\end{align} with $c>0$ large enough and $c_0>0$ small enough,
	there are constants $T_0>0$ and $C_0>0$ such that all $t > T_0$,
	\begin{align}
		\|e^{\lambda_0t}P_t(\phi)-\Pi(\phi)\|_{L^{\infty}(\mu)}
		\le C_0 e^{-(\lambda_1-\lambda_0)t}.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 4 of arXiv:2604.15874, 'On Continuous Data Assimilation for a class of 2D and 3D stochastic non-Newtonian fluids o'] We say that the stochastic system \eqref{STGF} admits a \emph{strong solution} (in the probabilistic sense) if, for every stochastic basis $(\Omega,\mathscr{F},\{\mathscr{F}_t\}_{t\geq 0},\Pbb)$	and every $\Qrm$-Wiener process $\{\Wrm(t)\}_{t\geq 0}$ defined on this basis, there exists a progressively measurable process $\u : [0,+\infty)\times\Omega \to \Hbb$ such that, $\Pbb$-a.s.,
\begin{align*}
		\u(\cdot,\omega)\in \C([0,+\infty);\Hbb)\cap \Lrm_{\mathrm{loc}}^2(0,+\infty;\Vbb)\cap \Lrm_{\mathrm{loc}}^{4}(0,+\infty;\mathbb{W}_0^{1,4}(\Ocal)),
\end{align*}
	and for all $t\in[0,T]$ and all $\v\in\X$, the following identity holds $\Pbb$-a.s.:
	\begin{align*}
	& (\u(t),\v) 
	  \\ &  =(\u_0,\v)-\int_0^t\langle\v , \; \nu \Acal\u(s)+\B(\u(s),\u(s)) + \alpha\J(\u(s))  +\beta\K(\u(s)) - \f\rangle\d s 
	  + \int_0^t\left(\v , \; \Grm(s,\u(s))\d\W(s)\right).
\end{align*}

[Lemma 21 of arXiv:2606.11389, 'Instability of a nonlinear oscillator with small friction and small additive noise'] Suppose ${\cal U}''(x)$ is unbounded above.  Given any initial condition $(x_0,y_0, \theta_0) \in \R^2 \times \R/(2 \pi Z)$, any target point $(x_1,y_1,\theta_1) \in \R^2 \times \R/(2 \pi Z)$ and any $\e > 0$ and any $T \ge 0$ there exists a piecewise continuous $h: [0,T] \to \R$ such that the unique solution of 
     \begin{equation} 
     (\dot{x}(t),\dot{y}(t),\dot{\theta}(t)) = X_0(x(t),y(t),\theta(t)) + h(t)X_1(x(t),y(t),\theta(t))
     \end{equation}
with initial condition $(x_0,y_0,\theta_0)$ satisfies $\|(x(T),y(T),\theta(T)) - (x_1,y_1,\theta_1)\| < \e$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem le:sup_Lp_concentration of arXiv:2411.03482, 'Ergodicity of 2D singular stochastic Navier--Stokes equations'] Let $p\in \mathbf{N}^*$. There exists some constant $C = C(p)$ such that for any $j, N \geq 1$, we have
	\begin{equ}

		\mathbb{E} \sup_{0\leq t \leq 1} \|\Delta_j X[t]\|_{L^{2p}}^{2N} \leq  2^{4j}(C\alpha_0)^{2N} \Big(1 + N^{N} 2^{-jN/p}\Big)\;.
	\end{equ}
	As a result, there exists $j_*$ such that for $j \geq j_*$, we have 
	\begin{equ}

		\mathbb{P}\left(\sup_{0\leq t \leq 1} \|\Delta_j X[t]\|_{L^{2p}} \geq j^{1/2}\alpha_0  \right) \leq C 2^{-6j}\;.
	\end{equ}

