			J_n:=\mathbb{E}\left[\int_0^Ts^{2H-1}\left|\int_0^s(s-r)^{-\frac12-H}r^{\frac12-H}b(r,B_r^H)\mathrm{d} r\right|^2\mathrm{d} s\right]^n\leq C^{2n}\Vert b\Vert_{L^p_xL^q_t}^{2n}n^{2(1-\kappa+\varepsilon)n}
		\end{align}
		where $\kappa=1-H-Hd/p-1/q>0$ and $0<\varepsilon<\kappa$.

