[Proposition prop:semi of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] For $\epsilon>0, \beta\in(0,\alpha-1),$ some constant $\gamma$ as below, $\epsilon<\mu\leqslant 1+\epsilon$ and $\mu\geqslant \frac{\beta-\gamma}{\alpha}$, there exists a constant $N=N(d,\alpha,\beta,\mu,\gamma,\epsilon)$ so that the following holds: for any $f\in {\mathbb C}_{\boldsymbol{a}}^{(1+\alpha)\beta}$ and $(s,t)\in(0,1]_\leqslant^2$,
\begin{align}

    \|\nabla^\gamma P_tf\|_{\infty}\leqslant& N \|f\|_{{\mathbb C}_{\boldsymbol{a}}^{\beta}}t^{\frac{(\beta-\gamma)\wedge0}{\alpha}}, \quad t\in(0,1], \gamma\geqslant0;\\

    \|\nabla^\gamma (P_tf-P_s\Gamma_{t-s}f)\|_{\infty}\leqslant& N (\|f\|_{{\mathbb C}_{\boldsymbol{a}}^{\beta}}+t^{\beta}\|f\|_{{\mathbb C}_{\boldsymbol{a}}^{(1+\alpha)\beta}} )s^{\frac{(\beta-\gamma)}{\alpha}-\mu}(t-s)^{\mu-\epsilon}, \gamma=0,1.
\end{align}

