[Corollary corollary3.70 of arXiv:2606.01664, 'Brown measure convergence for the spectrum of polynomials in Ginibre matrices'] Let $R_1,\cdots,R_n$ act irreducibly and non-trivially on the module $Z$.
Then with probability $1-\exp(-\Omega(N))$ over the columns in $\mathcal{T}_{-a}$,
the affine Gaussian map 
$$
D_a(\xi):Z\to W_a
$$ satisfies that, for any unit vector $A\in\operatorname{Hom}(Z,W_a)$,
\begin{equation}
\mathbb{E}\left|\langle A,D_a(\xi)-\mathbb{E}[D_a(\xi)]\rangle\right|^2\geq N^{-B_Z}
\end{equation} whenever $N\geq N_0(R)$. Here $N_0(R)\in\mathbb{N}_+$ depends on the module $Z$ and $R_1,\cdots,R_n$, while the constant $B_Z$ depends only on $\dim Z$. The coefficient in $\Omega(N)$ depends only on $n$. Moreover, on the same high probability event over $\mathcal{T}_{-a}$ and when $N\geq N_0$, we can find a constant $C_Z>0$ depending only on $\dim Z$ such that we have the following estimate
\begin{equation}
\mathbb{E}[|\det D_a(\xi)|^2]\geq C_Z N^{-B_Z\dim Z}.
\end{equation}

[Define of arXiv:2601.09990, 'Remarks on the convex integration technique applied to singular stochastic partial differe'] \rm{(\hspace{1sp}[H14])} Let $\alpha < 0$ and $r = - \lceil \alpha \rceil > 0$. We say $\xi \in \mathcal{S}'$ belongs to $\mathscr{C}_{\mathfrak{s}}^{\alpha}$ if it belongs to the dual of $C_{c}^{r}(\mathbb{R} \times \mathbb{T}^{d})$ and for every compact set $K \subset \mathbb{R} \times \mathbb{T}^{d}$ there exists a constant $C$ such that 
\begin{align*}
\langle \xi, \mathscr{S}_{\mathfrak{s},\bar{z}}^{\delta} \eta \rangle  \leq C \delta^{\alpha} \hspace{3mm} \forall \, \eta \in \{ \psi \in C^{r}: \lVert \psi \rVert_{C^{r}} \leq 1, \supp \psi \subset B_{\mathfrak{s}}(0,1)\},  
\end{align*}
for all $\delta \in (0, 1]$ and all $\bar{z} \in K$.

[Theorem thm:riesz of arXiv:2510.18392, 'Hyperuniformity of random measures, transport and rigidity'] Let $ s\in (0,1),\beta >0.$   
  \begin{itemize}
\item Let $ \gamma \in (0,1],\varphi \in   \mathscr  F_{ \gamma }^{ *}$. Then there is $ C_{ \varphi }$ not depending on $ n,R$ such that
\begin{align*}
  \textrm{Var}\left(\mathsf{P}_{ n}^{ s,\beta }(\varphi _{ R})\right) \leqslant C_{ \varphi }R^{ 2-\min(1-s,\gamma )}\ln(R)^{ 1-s = \gamma }.
\end{align*}
\item  Any  limit point $ \mathsf{P}^{ s,\beta }$ of $ \mathsf{P}_{ n}^{ s,\beta }$ is stationary and  $ (1-s)$-hyperuniform, hence for $ \gamma >0,\varphi \in   \mathscr  F_{ \gamma }$, 
\begin{align*}
  \textrm{Var}\left(\mathsf{P}^{ s,\beta }(\varphi _{ R})\right) = O(R^{ 2-\min(1-s,\gamma )}\ln(R)^{ 1-s = \gamma }
).
\end{align*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2608.10183, '2608.10183'] Assume that
\eqref{eq:phi-g-order}--\eqref{eq:general-contraction-rate}
hold. Then the coupling generator associated with the two prescribed
environments \(\eta\) and \(\widehat\eta\) satisfies
\begin{align}
\mathcal L_{2,t}^{\eta,\widehat\eta}H(x,y)
\leq
-dH(x,y)
+
\sum_{i=1}^{\infty}
\min\left\{
\phi_i(x^i),
\phi_i(y^i)
\right\}
D_i(\eta_t,\widehat\eta_t).

\end{align}

