[Lemma lem:FB_HS_norm_in_L2 of arXiv:2411.09482, 'Anomalous Regularization in Kazantsev-Kraichnan Model'] Let $M \in H^{-d/2-\alpha}_{\div}$, $\widehat G \in \mathcal{S}$, $\widehat G \ge 0$ and $\gamma(\mathrm{d}n) \coloneqq \widehat G (n) \mathrm{d}n$. Then,
	\begin{equation}
		\| \mathcal{F} B [M] \|_{\HS(H^{d/2+\alpha}_{\div}; L^2_\gamma)}^2 
		= (2\pi)^{-d/2}\int_{\mathbb{R}^d}  \mathbb F_{\gamma} (n) \widehat{M} (n) \cdot \overline{\widehat{M}} (n) \,\mathrm{d} n

	\end{equation}
	where
	\begin{equation}
		\mathbb F_\gamma (n) \coloneqq \int_{\mathbb{R}^d} \langle n-k \rangle^{-d-2\alpha} \widehat{G}(k) \left(|P^\perp_{n-k}k|^2 I +(d-1)\, k k^\top -2P^\perp_{n-k}\, k k^\top \right) \,\mathrm{d} k.
	\end{equation}

[Lemma bundi of arXiv:2412.04013, 'Rate estimates for total variation distance with applications\thanks{The author gratefully'] If (equation smoothie of the paper) holds then
for each integer $l\geq 1$, there are $N(l),H_{l}>0$ such that
\begin{equation}
|\phi_{S_{n}}(u)|\leq H_{l}(1+|u|)^{-l},\ u\in\mathbb{R}^{d},\ n\geq N(l).
\end{equation}

[Proposition 20 (Random-walk absorption probabilities) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $U_2,U_3,\dots$ be independent random variables with
$
U_m\sim\operatorname{Bern}(\frac 1 {2m})$,
$m\geq 2$.
Then, for $n\geq 1$ and $d\geq 0$,
\begin{equation}
    \pwalk{n}{d}
    =\pr\left(\sum_{m=2}^{n}U_m\geq d\right).

\end{equation}
Consequently, for $n\geq 2$ and $d\geq 1$,
\begin{equation}
    \pwalk{n}{d}
    =\frac {2n-1}{2n} \pwalk{n-1}{d}
    +\frac {1}{2n} \pwalk{n-1}{d-1}.

\end{equation}
Together with the boundary conditions $\pwalk{n}{0}=1$ for all  $n\geq 1$ and $\pwalk{1}{d}=0$  for all $d\geq 1$, this
recurrence uniquely determines the array.

[Lemma 3 of arXiv:2605.09372, 'Sharp weighted norm estimates for martingale square functions'] Let $1\leq p<\infty$ and let $W$ be a matrix weight. There exists a sequence of matrix-valued functions $(\widetilde W_n)_{n\geq 1}$ such that for every $n$,  the entries of $\widetilde W_n$ are adapted to $ \mathcal F_n$ and
\begin{equation}
\|\widetilde W_ne\|^p_{\mathbb C^d}\thickapprox_d \mathbb E_n\big(\|W^{\frac1p}e\|_{\mathbb C^d}^{p}\big),\quad \forall e\in \mathbb C^d.
\end{equation}
Moreover,  for all $n\in\mathbb N$ we have
	\begin{equation}
 \mathbb E_n\big(\|W^{
				\frac1p}\widetilde W_n^{-1}\|^{p}\big)=\mathbb E_n\big(\|\widetilde W_n^{-1}W^{
				\frac1p}\|^{p}\big) \lesssim_{p,d} 1.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 13 ({\cite[Theorem 4.3) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] {CMT}}]

Let $D \subset \mathbb{T}_N$ be a finite, simply-connected tileable domain. For the Glauber dynamic in $D$ constrained between $H_-$ and $H_+$, one has
          \begin{eqnarray}

            \tmix\le C (N {\rm diam}(D))^2\times (N H_{\max})^2 (\log N)^2, \quad H_{\max}:=\max_{z\in D}(H_{+}(z)-H_{-}(z))
          \end{eqnarray}
          for some universal constant $C$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2511.02725, 'Mixing of general biased adjacent transposition chains'] In the same setting as Lemma~\ref{lem:spatial-mixing}, with possibly a different choice of $C'(\eps) = e^{O(1/\eps)}$, one has for $r\ge C'(\eps)\ell_{\max}$ that 
    \begin{align*}
        \max_{\zeta} \left|\frac{\mu(\sigma(A_r)= \zeta \mid \sigma(A^c)=\eta, \sigma \in \vec{\ell}\loc)}{\mu(\bar \sigma(A_r)= \zeta \mid \bar \sigma(A^c)=\bar \eta, \bar \sigma \in \vec{\ell}\loc)} - 1\right|  \le \exp\left( - \fc{r}{C'(\eps) \ell_{\max}}\right)
    \end{align*}
    where the maximum is over all $\zeta$ for which the probabilities involved are non-zero (that set of $\zeta$ being the same so long as $r\ge 2\ell_{\max}$).

[Prop fixedepsconv of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] Take $C_1>0$, and assume that $|k_\ell-N^{2/3}\mathbf k_\ell|<C_1$, $|N_\ell-N+\boldsymbol{\tau}_\ell N^{2/3}|<C_1$ for each $\ell\in\llbracket 1, m\rrbracket$.
Then
\begin{multline}  
\lim_{N\to\infty} 2^{-m}N^m \sum_{\vec\mathfrak b\in \{0,1\}^m} \prod_{\ell=1}^m (2\sqrt{N_\ell N})^{-k_\ell-\mathfrak b_\ell}  \sum_{\vec r \in \mathscr B_\epsilon^*}  w(\vec r)
\\
=\lim_{C_2\to\infty}\int_{\substack{(\vec\mathbf p,  \vec\boldsymbol{\upsilon},\mathbf H)\in\mathscr K_\epsilon[\vec\mathbf k]:  \\ \mathbf p^0, \mathbf H, \boldsymbol{\delta} < C_2 }} \exp\left(\sum_{\ell=1}^{m-1}
(\boldsymbol{\tau}_\ell-\boldsymbol{\tau}_{\ell+1}) \mathbf H(\mathbf Q_\ell)/2 \right)\mathbf I_{\beta,\vec\mathbf k}[\vec \mathbf p, \vec\boldsymbol{\upsilon},\mathbf H] \mathrm d(\vec\mathbf p,  \vec\boldsymbol{\upsilon},\mathbf H),
\end{multline}
and
\begin{multline}  
\lim_{N\to\infty} 2^{-m}N^m \sum_{\vec\mathfrak b\in \{0,1\}^m} \prod_{\ell=1}^m (2\sqrt{N_\ell N})^{-k_\ell-\mathfrak b_\ell}  \sum_{\vec r \in \mathscr B_\epsilon^*}  |w(\vec r)|
\\
=\lim_{C_2\to\infty}\int_{\substack{(\vec\mathbf p,  \vec\boldsymbol{\upsilon},\mathbf H)\in\mathscr K_\epsilon[\vec\mathbf k]:  \\ \mathbf p^0, \mathbf H, \boldsymbol{\delta} < C_2 }} \exp\left(\sum_{\ell=1}^{m-1}
(\boldsymbol{\tau}_\ell-\boldsymbol{\tau}_{\ell+1}) \mathbf H(\mathbf Q_\ell)/2 \right)|\mathbf I_{\beta,\vec\mathbf k}[\vec \mathbf p, \vec\boldsymbol{\upsilon},\mathbf H]|\mathrm d(\vec\mathbf p,  \vec\boldsymbol{\upsilon},\mathbf H),
\end{multline}
and all the limits above exist and are finite. (Proof in the paper; no proof environment follows the statement in the TeX.)

