[Lem 125 (\cite{LTDMLS}) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Set $c=3-a-b$ and define the sets 
		\begin{flalign*}
			& \mathcal{A} = \{ (s, t, u, v) \in \mathbb{R}^4 : (s, t) \in \mathcal{T} \}; \\
			& \mathcal{W} = \{ (a, b, x, y) \in \mathbb{R}^4 : 0 < \min \{ a, b \} < a+b < 3, (x, y) \in \mathfrak{L}_{a,b,c} \},
		\end{flalign*}

		\noindent and define the map $\Phi :  \mathcal{W} \mapsto\mathcal{A}$ by setting 
		\begin{flalign*} 
			\Phi (a,b, x, y) = ( \partial_x \mathcal{H}_{a,b,c} (x,y), \partial_y \mathcal{H}_{a,b,c}(x,y), \partial_{xx} \mathcal{H}_{a,b,c} (x, y), \partial_{xy} \mathcal{H}_{a,b,c} (x,y)).
		\end{flalign*}

		\begin{enumerate} 
			\item The map $\Phi : \mathcal{W} \rightarrow \mathcal{A}$ is a diffeomorphism. 
			\item For any compact subset $\mathcal{W}_0 \subset \mathcal{W}$, there exists a constant $C = C(\mathcal{W}_0)$ such that the  Jacobian of $\Phi$ is bounded above by $C$ and below by $C^{-1}$ everywhere on $\mathcal{W}_0$. 
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 1 of arXiv:2607.00587, '(Non-)Hyperuniformity of Second Order Statistics\\ of Point Processes\thanks{The research '] For the determinantal point process $\KK$ defined by \req{rhodpp} the structure factor is given by
\begin{align}
    S(\xi) \,=\, 1 - \bigl|(E+\xi) \cap E\bigr|.
\end{align}
In particular, $S(0)=0$, while $S(\xi) >0$ for all $\xi \neq 0$.

[Proposition 23 of arXiv:2609.03556, 'An Effective SPDE Model for a Schr\"odinger Equation with a Fluctuating Magnetic Potential'] \label[proposition]{well_simplified_ldp}
    Assume \cref{hp:noise}, $\psi_0\in B^{L^2}_R$, and
    $(f,g)\in \mathcal{P}_1^N\times \mathcal{P}_2^N$. Then there exists a
    unique probabilistically strong, analytically weak solution of
    \eqref{eq:simplified_model_ldp} with trajectories in $\mathcal{E}$
    $\mathbb{P}-a.s.$ Moreover, it satisfies
    \begin{align*}
        \|\Psi^{\tau,\psi_0,f,g}_t\|^2=\|\psi_0\|^2 \quad \text{for all }t\geq 0\quad  \mathbb{P}-a.s.
    \end{align*}
   In particular, $\Psi^{\tau,\psi_0,f,g}$ belongs to $C([0,T];L^2)\ \mathbb{P}-a.s.$

