[Theorem 1 of arXiv:2605.17296, 'Zero correlations and averaged fields of orthonormal Gaussian Functions'] For fixed $k \ge 1$, as $n\rightarrow \infty $, 
\begin{equation*}
g_{n,n+k}(z,z) = 
\begin{cases}
\disp 1-\frac{5}{4n^{2}}+O\left( \frac{1}{n^{3}}\right) <1 &
 \text{if $k=1$}, \\
\disp \frac{4}{3}
+\frac{1}{12n^2}+O\left( \frac{1}{n^3}\right) 
>1 &
 \text{if $k=2$},  \\
\disp 1 & \text{if $k\geq 3$}.  
\end{cases}
\end{equation*}
Thus, the short-range correlations between $\cZ_{f_{n}}$ and $
\cZ_{f_{n+k}}$ display repulsion if $k=1$, attraction if $k=2$ and
no correlations if $k\geq 3$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2605.22146, 'Poisson approximation of the largest gaps between zeros of a stationary Gaussian process'] Let $f$ be a $C^2$-smooth SGP with a spectral density. Suppose either:
\begin{enumerate}
\item ($\infty$-PD) holds, and moreover $\int K(x) \,dx \neq 0$, or
\item ($\alpha$-PD) holds for some $\alpha \neq 1$, and moreover $K > 0$ and $\sup_x |K'(x)| / K(x) < \infty$.
\end{enumerate}
Then the largest gaps obey a Poisson approximation in the sense of Definition \ref{d:pa}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 49 of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] As $n\to\infty$ we have 
    \begin{align*}
        (m_n^{-1}\bar u_{\lfloor xm_n\rfloor}, \bar u_{\lfloor xm_n\rfloor +1}-\bar u_{\lfloor xm_n\rfloor}) \Rightarrow (\psi_d(x),\psi_d'(x)),
    \end{align*}
    in law with respect to the Skorokhod topology on $\R_+$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 4 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] A sequence $[\eta_1,\ldots,\eta_{n+1}]$ for $n\geq 2$ is a \emph{near}-log-concave sequence of degree $r\in \Z_+$ for finite $0 \leq r \leq n-2$, if the following holds:
\begin{align}
\eta_{i-1}\eta_{i+1} \leq \eta^2_{i} \hspace{0.15in} \text{$\forall i\in\mathcal{I}_{n}^{(r)}$}, \notag
\end{align}
where $\mathcal{I}_{n}^{(r)} \subseteq \mathcal{I}_{n} = \{2,\ldots,n\}$ such that 
\begin{align}
|\mathcal{I}_{n}^{(r)}| = n - r - 1.
\end{align}

[Lem 20 (Dynkin's criterion in discrete time) of arXiv:2604.12853, 'Coupling Markov Chains \\with a Common Image Chain'] The stochastic matrix $P\in\SM(A)$ lumps strongly under $f: A \twoheadrightarrow C$ if and only if for each $z,z'\in C$,
    \begin{equation} 
        \sum_{x'\in f^{-1}(z')}{P(x,x')}
        \quad
        \text{ takes the same value for all $x\in f^{-1}(z)$.}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 (Error recursion bounds) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] For $\alpha>1$ and integers $n_0,m_0>0$ such that
$m_0+n_0\ge16\alpha$, define
$$\alpha_k=\frac{\alpha}{k+n_0},\quad     \tau(j,m)=\sum_{k=j}^{m-1}\alpha_{k+1},\quad\text{and}\quad m_{r+1}:=\max\cW(m_r,T),\; r\ge 0$$ 
where $\cW(\cdot,T)$ is the window defined in
Lemma~\ref{lemma:step size_window}. We will consider $T=1/4$ or $T = 1/5$. 

Let $g > 1/\alpha$ be a fixed constant and set $\lambda:=\alpha g$. In addition, when $T=1/4$, assume $g\le1$; when $T=1/5$, assume $g\le4/5$. 

Suppose that for every $r\ge0$ and every $m\in\cW(m_r,T)$ the nonnegative sequence
$\set{\Delta_n:n\ge m_0}$ satisfies, 
\begin{equation}
\begin{aligned}
        \Delta_m
        &\le
        e^{-g\tau(m_r,m)}\Delta_{m_r}
        +
        K_1\sqrt{\frac{H_{m_r}}{m_r+n_0}}
        +
        \frac{K_2}{m_r+n_0}
\end{aligned}

\end{equation}
for some non-negative and non-decreasing sequence $\set{H_n:n\ge m_0}$ and $K_1,K_2\ge0$. 
Then, for every $n\ge m_0$,
\begin{equation}
\begin{aligned}
        \Delta_n
        \le e^{1/16}\Delta_{m_0}
        \crbk{\frac{m_0+n_0}{n+n_0}}^\lambda +
        \frac{14\alpha  K_1}{\lambda-1/2}
        \sqrt{\frac{H_n}{n+n_0}}+
       \frac{17\alpha  K_2}{\lambda-1}
        \frac{1}{n+n_0}.
\end{aligned}

\end{equation}

