[Lemma 11 of arXiv:2608.09700, 'A general paracontrolled ansatz for singular SPDEs'] For any $\tau\in T$ and for any $\tau/\sigma\in T^+$
		\begin{equation}
			\widetilde{ \PPi}(\tau)_i = \sum_{m\geq 0} \frac{1}{m!} \, \Delta_i^m\big(\widetilde{ \PPi}(\downarrow^m\hspace{-2pt}\tau)\big),\quad 
			\widetilde{ g}(\tau/\sigma)_i = \sum_{m\geq 0} \frac{1}{m!} \, \Delta_i^m\big(\widetilde{ g}(\downarrow^m\hspace{-2pt}\tau/\sigma )\big).
		\end{equation}

[Corollary 10 (Boundary non-stationary Choquet-integral asymptotics) of arXiv:2607.16502, 'Asymptotic Behavior of Path Functionals for Vector-Valued Gaussian Processes at High Level'] Let \(\bm X\) satisfy Assumptions~\ref{D1}--\ref{D3} on \([0,T]\), and fix
\(L>0\).  Let \((\nu,\psi)\) be \(L\)-admissible Choquet data in the sense of
Definition~\ref{def:admissible-choquet-data}, and put
\(\Gamma=\Gamma^{\nu,\psi}\).  In each of the following regimes assume that the
corresponding limiting model in Theorem~\ref{thm:main_theorem} is non-trivial
for this Choquet functional.  With \(\bm d(t)=t^\beta A\bm w\), define
\begin{align*}
  \mathcal H_{\nu,\psi}^{\mathrm{bd}}(L)
  & =
  \mathcal H_{\Gamma,L,\alpha,V_{I,I},\Sigma,\bm b},\\
  \mathcal P_{\nu,\psi}^{\mathrm{bd}}(L)
  & =
  \mathcal P_{\Gamma,L,\alpha,V_{I,I},\bm d_I,\Sigma,\bm b},\\
  \mathcal C_{\nu,\psi}^{\mathrm{bd}}(L)
  & =
  \mathcal C_{\Gamma,L,\bm d,\Sigma,\bm b}.
\end{align*}
Then the following asymptotics hold as \(u\to\infty\).
\begin{enumerate}[(a)]
  \item If \(\alpha<\beta\), then
  \begin{equation}

    \pk{
      \Gamma_{[0,T]}^{\nu,\psi}\bigl(\uu(\bm X-u\bm b)\bigr)
      > L u^{-2\lambda_\nu/\alpha}
    }
    \sim
    \mathcal H_{\nu,\psi}^{\mathrm{bd}}(L)\,
    \Gamma(1/\beta+1)\,
    \tau_{\bm w}^{-1/\beta}\,
    u^{2/\alpha-2/\beta-|I|}\,
    \varphi_\Sigma(u\bb).
  \end{equation}
  \item If \(\alpha=\beta\), then
  \begin{equation}

    \pk{
      \Gamma_{[0,T]}^{\nu,\psi}\bigl(\uu(\bm X-u\bm b)\bigr)
      > L u^{-2\lambda_\nu/\beta}
    }
    \sim
    \mathcal P_{\nu,\psi}^{\mathrm{bd}}(L)\,
    u^{-|I|}\,
    \varphi_\Sigma(u\bb).
  \end{equation}
  \item If \(\alpha>\beta\), then
  \begin{equation}

    \pk{
      \Gamma_{[0,T]}^{\nu,\psi}\bigl(\uu(\bm X-u\bm b)\bigr)
      > L u^{-2\lambda_\nu/\beta}
    }
    \sim
    \mathcal C_{\nu,\psi}^{\mathrm{bd}}(L)\,
    u^{-|I|}\,
    \varphi_\Sigma(u\bb).
  \end{equation}
\end{enumerate}
The constants displayed above are finite and positive in the regimes in which
they are used.

[Lemma LEM:GAP2 of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $Q \in \mathbb{Z}$ with $Q\ge 2$, and let $d>0$ be a large constant. Then there exist $c>0$ and $C>0$  such that if $\phi \in \mathcal{C}_Q$ with $\phi(-\infty)=0$ and $\phi(\infty)=2\pi Q$ satisfies 
\begin{align}
\textup{dist}(\phi, \mathcal{M}_Q^{<d})=\inf_{\substack{\xi_1,\dots,\xi_Q \in \mathbb{R} \\ \min_{i \neq j}|\xi_i-\xi_j|<d } }\| \phi-m_{\xi_1,\dots,\xi_Q}   \|_{L^2(\mathbb{R})}<\delta

\end{align}
where $\delta\le c \,e^{-d/2}$, then
\begin{align*}
E(\phi) \ge |Q| E_{\textup{kink}}+ C\cdot e^{-d}.
\end{align*}

[Lemma lem:C_reg of arXiv:2605.21265, 'The non-Hermitian minor process'] Let $\Omega$ be defined as in Theorem~(theo:main of the paper). Fix (small) $c_0,\varepsilon>0$. For any $f_1,f_2\in H_0^{2}(\Omega)$ and $x_j,x_j'\in [c_0,1]$, $j=1,2$, it holds that
\begin{equation}
\left\vert C^{(G)}\big((x_1,f_1),(x_2,f_2)\big) - C^{(G)}\big((x_1',f_1),(x_2',f_2)\big)\right\vert \lesssim \left(|x_1-x_1'|+|x_2-x_2'|\right)^{1/2-\varepsilon} \prod_{j=1}^2\|\Delta f_j\|_{L^2(\Omega)},

\end{equation}
where the implicit constant depends only on $c_0$ and $\varepsilon$.

