\begin{equation*}
    \mathbb{P}[D_h^{\xi}(\text{around} \,\, \mathbb{A}_{1,2}(0)) = x] = \mathbb{P}[D_h^{\xi}(0,1) = x] = 0.
\end{equation*}   
Moreover, we have that
\begin{equation*}
    \mathbb{P}[D_h^{\xi}(0,1) \in (a,b)] > 0 \quad \text{for all} \quad 0<a<b.
\end{equation*}

