[Definition def:associated_profile of arXiv:2601.04997, 'Fluctuations of the Boundary-Driven Symmetric Zero-Range Process from the NESS'] A sequence $\{\mu^N\}_N$ of probability measures on $\Omega_N$ is said to be \textit{associated} to a measurable profile $\gamma:[0,1]\to\mathbb[0, \infty)$ if,  for any $\varepsilon>0$ and any continuous function $H:[0,1]\to\mathbb{R}$, the following limit holds:
\begin{equation*}
    \mylim_{N\to\infty}
    \mu^N \left\{\eta\in\Omega_N: \left|\frac{1}{N} \sum_{x=1}^{N-1} H\left(\frac{x}{N}\right)\eta(x)
    - \int_0^1 H(u)\gamma(u)\de u \right| > \varepsilon\right\} = 0.
\end{equation*}

[Proposition 50 (Maximal canonical Gaussian factor) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] \begin{equation}
 F=A^{\can}+G^{\can},
 \qquad
 G^{\can}\indep A^{\can}.

\end{equation}
If a Hilbert--Stein split has an independent Gaussian factor and zero proper residual contraction
register, then closed graded spaces $T_s\subset\cN_s(F)^\perp$ exist such that
\begin{equation}
 G_a^{\mathrm{HS}}
 =
 \sum_sI_1(P_{T_s}\ell_{a,s}),
 \qquad
 \Cov(G^{\mathrm{HS}})
 \preccurlyeq
 \Cov(G^{\can}).

\end{equation}

[Lemma lemma-V4 of arXiv:2609.02552, 'Resolvent Estimates for the Stokes Operator \\ in a Three-Dimensional Lipschitz Domain'] Let $(u, \phi )$ be the same as in Theorem (thm-L of the paper).
Suppose  $q>3$ satisfies the condition (equation q of the paper) with $d=3$.
 Let  $r=R |\lambda|^{-1/2}$ for some $R\ge 1$.
Then
\begin{equation}
\aligned
|\lambda| \| u \|_{L^\infty(E_r)}
& \le C \left\{
\| F \|_{L^\infty(E_{Nr})}   R N^{\frac{3}{q}}
+ |\lambda| \| u \|_{L^\infty(E_{Nr})} N^{\frac{3}{q}-1}\right\}\\
& 
+ C |\lambda|^{\frac12} 
  N^{\frac{3}{q}-1} \left(\fint_{E_{Nr}}  |\nabla u|^q \right)^{1/q} 
+ C |\lambda|^{\frac12} N^{\frac{3}{q}-1}  \left(\fint_{\Delta_{Nr}} |\nabla u|^p \right)^{1/p} \\
& 
+ C |\lambda|^{\frac12} N^{\frac{3}{q}-1}   \inf_{\beta\in \mathbb{C}}
\left\{ 
 \left(\fint_{E_{Nr}} |\phi -\beta |^q \right)^{1/q}  
 +   \left(\fint_{\Delta_{Nr}} |\phi -\beta |^p \right)^{1/p}  \right\},
\endaligned
\end{equation}
where $p=\frac{2q}{3}$ and  $C$ depends only on $\theta$,   $q$ and $M$.

