				\mathbb{E}[\widetilde \Delta_m^{\delta, (1)}] = \sum_{l=0}^{\vert E_d({\scaleobj{1}{\square}}_m)\vert} \widetilde c_{l,m}\left(\frac{\delta}{1-\mathfrak{p}}\right)^l,
			\end{equation}
			with the coefficients
