				\widetilde c_{l,m} = \frac{1}{|{\scaleobj{1}{\square}}_m|} \mathbb{E} \left[\sum_{e\in E_d({\scaleobj{1}{\square}}_m)}\left \langle \nabla v_m(\widetilde{\mathbf{a}}^\delta_{m}),({\mathbf{a}}^{e}-\widetilde{\mathbf{a}}^\delta_{m})\sum_{\substack{|G|=l-1\\mathcal{G}\subseteq E_d({\scaleobj{1}{\square}}_m)}}D_{G}\big(\nabla v_m({\mathbf{a}}^{e})\big)\right \rangle_{{\scaleobj{1}{\square}}_m}\right].
