[Lem 50 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Fix $\delta>0$.
		Let $k \ge 1$ be a positive integer and $q', q \in [0, \varepsilon_0]$, and $u \ge 0$ be real numbers such that $|q-q'| \le 2^k N^{-1-4\delta} u$. We have
		\begin{flalign}

		\mathcal C^q_k(u):=	\left[\mathcal{B}_{k+1}^q (u) \cup \bigcup_{j=1}^k \mathcal{A}_j^q (u)\right] \subseteq \bigcup_{j=1}^{k+1} \mathcal{A}_j^{q'} \big( (1 - N^{-\delta}) u \big),
		\end{flalign} 
and
		\begin{flalign}

			1 - 2N^{-2\delta} \le \mathtt{e}_{z;q'} \mathtt{e}_{z;q}^{-1} \le 1 + 2 N^{-2\delta}, \qquad \text{for every $z\in \mathcal C^q_k(u)$}.
		\end{flalign}

