body:
[Theorem 11 (Scaling limit of Sinkhorn-rescaled random matrices) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Let $(\r_k, \c_k)$ and $\bLambda_k$ satisfy Assumption \ref{assumption: limit_theory}, and for each $k$ let $\X_k$ be a random matrix satisfying Assumption \ref{assump:random_matrix} with mean $\bLambda_k$ and target margin $(\r_k, \c_k)$. Let $\varphi_{\X_k^{\r_k,\c_k}}$ denote the piecewise constant extension of $\X_k^{\r_k,\c_k}$ to $[0,1]^2$ as in Theorem \ref{thm:bound_X^rs-Z}, and let $W^{\r,\c;\bLambda} := d\pi^{\r,\c;\bLambda}/(dx\,dy)$ be the Lebesgue density of the limiting SSB from Theorem \ref{thm:SSB_deterministic_limit}. Assume
		\begin{enumerate}[label=\textup{(\roman*)}]
			\item $\sup_k \sigma_k \le \sigma < \infty$ and $\sup_k R_k \le R < \infty$;
			\item $\liminf_k (m_k/n_k) \wedge (n_k/m_k) \ge \gamma > 0$;
			\item $(m_k \vee n_k)^{3/2} \sqrt{\log(m_k \vee n_k)} = o_{K,\delta,\gamma,\sigma,R}(\|\bLambda_k\|_1)$.
		\end{enumerate}
		Fix $D > 0$. Then for any $g \in L^{\infty}([0,1]^2)$,
		\begin{align}
			&\left|\int_{[0,1]^2} g\!\left(\varphi_{\X_k^{\r_k,\c_k}} - W^{\r,\c;\bLambda}\right) dx\, dy\right| \nonumber \\
			&\qquad = O_{K, \delta, \|g\|_{\infty}, \sigma, R}\!\left( \frac{(m_k \vee n_k)^{3/2} \sqrt{D\log(m_k \vee n_k)}}{\|\bLambda_k\|_1} + \sqrt{\norm{\rho_{\r} - \rho_{\r_k}}_{L^1} + \norm{\rho_{\c} - \rho_{\c_k}}_{L^1}} + d_H(\varphi_{\bLambda_k}, \varphi_{\bLambda}) \right)
		\end{align}
		with probability at least 
		\begin{align}
			1 - 2(m_k \vee n_k)^{-D} - m_k^2 \exp(-c\,\Phi_{\bLambda_k}) - 2\exp\left(-\frac{\|\bLambda_k\|_1^2}{2(m_k n_k \sigma^2 + R\|\bLambda_k\|_1)}\right)
		\end{align}
		for an absolute constant $c > 0$, where $\Phi_{\bLambda_k}$ is the row-alignment rate in \eqref{eq:Phi_def}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:flags of arXiv:2609.01776, 'On the Cuspidal Cohomology of Iwahori Congruence Subgroups of $\mathrm{SL}(3, \mathbb{Z})$'] Let $\mathbb{F}_p = \mathbb{Z}/p\mathbb{Z}$.  Further, let $\overline{B}$ denote the Borel subgroup of upper triangular matrices in $\overline{G} = \mathrm{SL}(n, \mathbb{F}_p)$.  Let $V = \{v_1, \ldots, v_m\}$ and $W = \{w_1, \ldots, w_m\}$ be two saturated lists in $\mathbb{Z}^n$.  Let $V_i$ and $W_i$ denote the subspaces of $\mathbb{Q}^n$ generated by $\{v_1, \ldots, v_i\}$ and  $\{w_1, \ldots, w_i \}$ respectively. 

    Fix $i_1 < i_2 < \cdots < i_k$ from $\{1, \ldots, m\}$.  Consider the flags $F^V$ and $F^W$, which correspond to a nested sequence of subspaces
    \begin{gather*}
        0 \subsetneq V_{i_1} \subsetneq V_{i_2} \subsetneq \cdots \subsetneq V_{i_k} \subseteq \mathbb{Q}^n, \\
        0 \subsetneq W_{i_1} \subsetneq W_{i_2} \subsetneq \cdots \subsetneq W_{i_k} \subseteq \mathbb{Q}^n.
    \end{gather*}

    Let $\overline{F}^V$ and $\overline{F}^W$ denote the flags 
    \begin{gather*}
        0 \subsetneq \overline{V}_{i_1} \subsetneq \overline{V}_{i_2} \subsetneq \cdots \subsetneq \overline{V}_{i_k} \subseteq \mathbb{F}_p^n, \\
        0 \subsetneq \overline{W}_{i_1} \subsetneq \overline{W}_{i_2} \subsetneq \cdots \subsetneq  \overline{W}_{i_k} \subseteq \mathbb{F}_p^n,
    \end{gather*}
    where $\overline{V}_i = \langle \bar{v}_1, \ldots, \bar{v}_i \rangle$ and $\overline{W}_i = \langle \bar{w}_1, \ldots, \bar{w}_i \rangle$ with 
    $v_j \equiv \bar{v}_j \pmod p$ and $w_j \equiv \bar{w}_j \pmod p$.  Suppose there exists $B_0 \in \overline{B}$ that sends $\overline{F}^V$ to $\overline{F}^W$.  Then, there exists some $\mathcal{I}_0 \in \mathcal{I}(n, p)$ such that $\mathcal{I}_0 \equiv B_0 \pmod p$ and $\mathcal{I}_0$ sends $F^V$ to $F^W$.

