body:
[Cor of arXiv:2412.03415, 'Critical first passage percolation on random graphs'] \begin{enumeratea}
\item If the associated branching process {\bf does not} explode i.e., $\theta_\ell \uparrow \infty$ as $\ell \uparrow \infty$ then $T_n(u,v) \stackrel{P}{\longrightarrow} \infty$ as $n\to \infty$. 
\item If the associated branching processes explode in finite time, then for any $a> 0$, 
\[\liminf_{n\to \infty}\pr(T_n(u,v) \geqslant a) \geqslant \pr(\theta_\infty^{(u)}+ \theta_\infty^{(v)} \geqslant a),\]
where $\theta_\infty^{(u)}, \theta_\infty^{(v)}$ are independent copies of the explosion time. 
\end{enumeratea}

[Lemma 18 of arXiv:2606.31455, 'Discrete time-multidimensional renewal theory and applications'] Assume the hypotheses of Proposition~\ref{prop:SLLN-N}, so that under \eqref{eq:lambda-scaling} one has
$N(k_{1:d})/|k|_1\to\mu_\lambda$ almost surely.
Let $(Y_n)_{n\ge 1}$ be i.i.d.\ real-valued random variables with
$\mathbbm{E}[Y_1]=0$ and $\mathbbm{E}[Y_1^2]=1$, and set $T_n=\sum_{m=1}^n Y_m$.
Then, under \eqref{eq:lambda-scaling},

\begin{equation}
\frac{T_{N(k_{1:d})}}{\sqrt{|k|_1}}
\xrightarrow[k_{1:d}\stackrel{\lambda}{\to}\infty]{d}
\mathcal{N}(0,\mu_\lambda).
\end{equation}

