[Corollary use1.25 of arXiv:2412.05709, 'Incipient infinite clusters and volume growth for Gaussian free fields and loop soups on m'] For any $d\ge 3$ with $d\neq 6$, the following properties hold. 
 	\begin{enumerate}
 		\item Recall $\ensuremath{c_{\ref*{const_typical_volume_3}}}(d,\epsilon),\ensuremath{C_{\ref*{const_typical_volume_2}}}(d,\epsilon)$ in Theorem (thm_1.2 of the paper). For any $\epsilon>0$ and $M\ge 1$, 
 		\begin{equation}
	\mathbb{P}_{d,\mathrm{IIC}}\big(\ensuremath{c_{\ref*{const_typical_volume_3}}}M^{(\frac{d}{2}+1)\boxdot  4}  \le  \mathscr{V}_{M}^{\ge 0} \le \ensuremath{C_{\ref*{const_typical_volume_2}}}M^{(\frac{d}{2}+1)\boxdot   4} \big)\ge 1-\epsilon.
\end{equation}


 		\item Recall $\ensuremath{c_{\ref*{const_volume_sharp2}}}(d,\lambda)$ in Theorem (thm_1.3 of the paper). For any $\lambda\ge 1$ and $M\ge 1$,  
 		\begin{equation}
			\mathbb{P}_{d,\mathrm{IIC}}\big(\mathscr{V}_{M}^{\ge 0}\ge \lambda M^{(\frac{d}{2}+1)\boxdot  4}  \big) \ge \ensuremath{c_{\ref*{const_volume_sharp2}}}.
	\end{equation}


 		\item  Recall $\ensuremath{c_{\ref*{const_iic_two_point3}}}(d), \ensuremath{C_{\ref*{const_iic_two_point2}}}(d)$ in Theorem (thm_1.4 of the paper). For any $M\ge 1$ and $y\in \partial B(M)$, 
 		\begin{equation}
\ensuremath{c_{\ref*{const_iic_two_point3}}} M^{-[(\frac{d}{2}-1)\boxdot  (d-4)]} \le 	\mathbb{P}_{d,\mathrm{IIC}}\big( \bm{0}\xleftrightarrow{\ge 0} y \big) \le \ensuremath{C_{\ref*{const_iic_two_point2}}} M^{-[(\frac{d}{2}-1)\boxdot  (d-4)]}. 
\end{equation}

 	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 74 of arXiv:2609.03875, 'Measure theory without infinities'] {$ $}
  \begin{enumerate}
  \item [(i)] Let $\mu$ be a positive measure and $\eta = \as[\mf R]\mu$. Then $\eta$ is a $\sigma$-finite $\mf R$-valued measure, $\eta$ is an extension of $\mu$, $D_\eta = \q\eta = \q\mu$, and $\mu = \mf F\eta$.
  \item [(ii)] Let $\eta$ be a $\sigma$-finite $\mf R$-valued measure and $\mu = \mf F\eta$. Then $\mu$ is a positive measure and $\eta = \as[\mf R]\mu$.
