[Lem lemma:smallData of arXiv:2607.27472, 'The stochastic Keller--Segel system in critical spaces'] Assume that the parameters $s,s_v,q,q_v,p,\kappa$ satisfy (equation Eq_standard of the paper) and  (equation Eq_pc1_new of the paper)--(equation Eq_pc5_new of the paper), and let $g^{i}$, $i\in \{1,2\}$, satisfy Assumptions (Ass_noise of the paper) and (equation assumption_for_global of the paper). 
			Then there exist constants $T_0>0$ and $C_*>0$,  such that, for every $\varepsilon\in(0,1)$, if
			\begin{equation}
				U_0\in L^p_{\mathfrak{F}_0}\bigl(\Omega; X_{1-\frac{1+\kappa}{p},p}\bigr)
				\quad\text{and}\quad
				\mathbb{E}\|U_0\|_{X_{1-\frac{1+\kappa}{p},p}}^p \le C_*\varepsilon,
			\end{equation}
			then the corresponding $L^p_{\kappa}$-maximal solution $(U,\sigma)$ to the stochastic Keller--Segel system (equation 25.06.19.16.01 of the paper) provided by Theorem (thm:local_wp of the paper) satisfies
			\begin{equation}

				\mathbb{P}(\sigma \geq T_0)\ge 1-\varepsilon.
			\end{equation}
			Moreover, there exists a stopping time $\tau\in(0,\sigma]$ and  constants $K_\theta<\infty$ for $\theta \in [0,1/2)$,  such that (equation eqn47 of the paper) implies also
			\begin{equation}
				\mathbb{P}(\tau\ge T_0)\ge 1-\varepsilon,
			\end{equation}
			and we have the estimate
			\begin{equation}
				\mathbb{E}\left[
				\mathbf{1}_{\{\tau\ge \overline T_0\}}
				\|U\|^p_{H^{\theta,p}((0,\overline T_0),w_\kappa;X_{1-\theta})}
				\right]
				\leq
				K_\theta\,\mathbb{E}\|U_0\|_{X_{1-\frac{1+\kappa}{p},p}}^p,
			\end{equation}
			for all  $\overline T_0\in(0,T_0]$. In the case $p=2$, the left-hand side of (equation eqn10 of the paper) needs to  be replaced by $\mathbb{E}[
			\mathbf{1}_{\{\tau\ge \overline T_0\}}
			\|U\|^p_{C([0,\overline T_0];X_{1/2})}
			]$ for $\theta>0$.

[Lemma lem:6 of arXiv:2609.00193, 'Provably Efficient Federated Reinforcement Learning with Linear Function Approximation and'] For any $\lambda\ge 1$ and $\gamma\ge 1$,
\[
\begin{aligned}
&\sum_{h=1}^H\sum_{k=1}^K\sum_{t=\tau_k}^{\tau_{k+1}-1}\sum_{m=1}^M
\|\phi(x_h^{m,t},a_h^{m,t})\|_{(\Lambda_h^k)^{-1}}
\le \\
&H\Bigg(
\sqrt{6dMT\log\Bigl(1+\frac{MT}{d\lambda}\Bigr)}
+\frac{Md}{\log 3}\sqrt{\gamma\log\gamma}\,\log\Bigl(1+\frac{MT}{d\lambda}\Bigr)+\frac{Md}{\sqrt\lambda\,\log 3}\,\log\Bigl(1+\frac{MT}{d\lambda}\Bigr)
\Bigg).
\end{aligned}
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2609.01237, ''] There exists a constant $C > 0$, depending only on $\beta$ and $\Omega_2$, such that
    \begin{align}
\left| \langle \boldsymbol{n}_1 \cdot \nabla v ,\psi \rangle_{\Sigma}  \right| \leq C \|v\|_{H^1(\Omega_2)} \|\psi\|_{H^{\half}(\Sigma)},
    \end{align}
for any $v\in \cW$ and $\psi \in H^{\half}(\Sigma)$.

