[Definition d:StandardFC of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Set
\begin{gather}
\FC{\msA}{}\eqdef \set{u\colon \msP\to{\mathbb R} : \begin{gathered} u=F\circ \mbff^\star\,\mathrm{,}\;\, F\in \mcC_b^\infty({\mathbb R}^k) \,\mathrm{,}\;\,
\\
k\in {\mathbb N}_0\,\mathrm{,}\;\, f_i \in \msA\,\mathrm{,}\;\, i\leq k \end{gathered}}\,\mathrm{.}
\end{gather}

Further let~$\hFC{\msA}{}$ and~$\hFC{\msA}{\epsilon}$ with~$\epsilon\in\mbbI$ be defined as in Definition~(d:CylinderF of the paper) by replacing the space of polynomials~${\mathbb R}[t_1,\dotsc, t_k]$ there with the space~$\mcC_b^\infty({\mathbb R}^k)$ of smooth functions with continuous and bounded derivatives of all orders.

[Lemma lem-inductive-ecal-h-t of arXiv:2607.22324, 'The conclave process'] {}
    We have the following estimates for $1 \leq t \leq m_0$:
    \begin{align}
        &\mathbb P_n^{\alpha}\left( \mathcal E_{1,t+1}^c; \cap_{1 \leq h \leq 6, 1 \leq s \leq t} \mathcal E_{h,s} \right) = o(1) \,;  \\
        &\mathbb P_n^{\alpha}\left( \mathcal E_{2,t+1}^c; \cap_{1 \leq h \leq 6, 1 \leq s \leq t} \mathcal E_{h,s} \right) = o(1) \,;  \\
        &\mathbb P_n^{\alpha}\left( \mathcal E_{3,t+1}^c; \cap_{1 \leq h \leq 6, 1 \leq s \leq t} \mathcal E_{h,s} \right) = o(1) \,;  \\
        &\mathbb P_n^{\alpha}\left( \mathcal E_{4,t+1}^c; \cap_{1 \leq h \leq 6, 1 \leq s \leq t} \mathcal E_{h,s}  \right) = o(1) \,;  \\
        &\mathbb P_n^{\alpha}\left( \mathcal E_{5,t+1}^c; \cap_{1 \leq h \leq 6, 1 \leq s \leq t} \mathcal E_{h,s}  \right) = o(1) \,.  \\
        &\mathbb P_n^{\alpha}\left( \mathcal E_{6,t+1}^c; \cap_{1 \leq h \leq 6, 1 \leq s \leq t} \mathcal E_{h,s} \right) = o(1) \,. 
    \end{align}

