body:
[Lemma lenkenopoeje of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] We have
\begin{eqnarray}
S_{K-1}=(1+o_{b\to 0}(1))S_\infty
\end{eqnarray}
where $S_\infty$ is given by 
\begin{equation}
S_\infty(d,\ell) :=  \frac{1}{a}\sum_{j=0}^{+\infty}\frac{(-1)^ja^jg_j^\infty}{\Gamma(\nu+j+3)}
\end{equation}
and where $g_j^\infty$ corresponds to the limiting problem (equation eq: Formal Limit Equation of the paper) and is given by  (equation eq: Expansion of Theta and G of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 2 of arXiv:2609.00598, 'Supercritical mean--field limit for magnetized Hamiltonian dynamics'] Suppose that
\begin{itemize}
  \item[{\rm(i)}] $\omega^{\mathrm{in}}\in W^{1,\infty}( \mathbb{T}^{2})$, $\int_{\mathbb T^2}\omega^{\mathrm{in}}\,\dd x=0,$ $B\in W^{1,\infty}(\mathbb{R}_{+};W^{2,\infty}(\mathbb{T}^{2}))$, 
  and $(\omega,v)$ is the solution to \eqref{vorticity formulation intro} with initial data $\omega^{\mathrm{in}};$
    \item[{\rm(ii)}] $(x_{1}^{0},\cdots\!,x_{N}^{0})\in \Delta_{N}^{c}$, 
    $(x_{1}(t),\cdots\!,x_{N}(t),\xi_{1}(t),\cdots\! ,\xi_{N}(t))\in C^{1}(\mathbb{R}_{+};\mathbb{T}^{2N}\times \mathbb{R}^{2N})$ is the solution to \eqref{trajectories intro},
    and $\rho_{\varepsilon,N}$ and 
    $J_{\varepsilon,N}$ are given by \eqref{discrete density and current}{\rm;}
   \item[{\rm(iii)}] $\mathcal{E}_{\varepsilon,N}(t)$ is given by \eqref{magnetized renormalized modulated energy}{\rm;}
    \item[{\rm(iv)}]$\varepsilon=\varepsilon(N)\to0$ is such that  $\mathcal{E}_{\varepsilon,N}(0)\underset{N\rightarrow \infty}{\longrightarrow }0$ and $\frac{\log N}{N \varepsilon}\underset{N\rightarrow \infty}{\longrightarrow}0$. 
\end{itemize}
Then
\begin{align*}
\underset{t\in [0,T]}{\sup}\mathcal{E}_{\varepsilon,N}(t)\underset{\varepsilon+\frac{1}{N}\rightarrow 0}{\longrightarrow} 0,
\end{align*}
provided 
$\mathcal{E}_{\varepsilon,N}(0)\underset{\varepsilon+\frac{1}{N}\rightarrow 0}{\longrightarrow}0$.    
This implies that
\begin{align*}
\rho_{\varepsilon,N}(t,\cdot)\xrightharpoonup[{\varepsilon+\frac{1}{N}\rightarrow 0}]{}1 
\quad\,\, \mbox{and} \quad\,\, 
J_{\varepsilon,N}\xrightharpoonup[\varepsilon+\frac{1}{N}\rightarrow 0]{}v
\end{align*}
weakly in the sense of measures. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 (Simultaneous pathwise block bound) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Assume, in addition to Assumption~\ref{ass:time}, the Galerkin-state finite-state condition stated there.  Fix a final loss $\eps>0$.  Choose $0<\eps_0<\eps$ and $\rho>0$ so that
\begin{equation}
 \eps_0+3\rho<\eps.
\end{equation}
Then there is a full-probability event $\Omega_*$ and a finite random variable $C_*(\omega)$ such that, for every $\omega\in\Omega_*$, every dyadic triple in $\Triads$, and every cutoff,
\begin{equation}
 \norm{B^\circ_{\Lambda,N,Q,M}(\omega)}_{C(\Delta_T;\cL(L^2_q,L^2_n))}
 \le C_*(\omega)a^{(\eps)}_{N,Q,M}.
\end{equation}
No independence between distinct dyadic blocks is required.

[Lemma 15 of arXiv:2512.02322, 'Ursell functions in lattice gauge theory'] Consider Ising lattice gauge theory with parameter $\beta \ge \beta_0$. Let $(\gamma_i)_{i \in [n]}$ be loops in Definition \ref{Def:Wilsonloops}. Then, for $i \in \{1,...,n-1\}$, it holds that
    \begin{align*}
        &\Psi_\beta[\{i,i+1\}] =  |\gamma_i| \Big( \myexp(-4(4(m-1)-2)\beta) +  \mathcal{O}\big(\myexp{(-4(4(m-1))\beta)}\big)\Big),
    \end{align*}
    where the term $\mathcal{O}\big(\myexp{(-4(4(m-1))\beta)}\big)$ is independent of $|\gamma_i|$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:expectation_and_median of arXiv:2411.04988, '{\bf A relation between isoperimetry and total variation decay with applications to graphs'] Let $G=(V,E)$ be a locally finite graph with degrees bounded by $M\geq 2$ and let $d$ be a metric on $V$. We have that
    \begin{equation*}
    \sup_x \sup_{0\leq m \leq n} \mathbf{P}_x \left(d(X_0,X_m)\geq \frac{1}{16} \sup_y \mathbf{E}_y \left[\max_{0\leq \ell \leq n} d(X_0,X_\ell)\right] \right) \geq \frac{c}{M\log M} 
    \end{equation*}
    and hence that
    \begin{equation*}
    \sup_x \sup_{0\leq m \leq n} \mathbf{E}_x \left[d(X_0,X_m)\right] \geq \frac{c}{16M\log M} \sup_y \mathbf{E}_y \left[\max_{0\leq m \leq n} d(X_0,X_m)\right]
    \end{equation*}
    for every $n\geq 1$, where $c$ is a positive universal constant.

[Lemma 23 (Lemma 7.2.7 from \cite{vershynin2018high}) of arXiv:2604.01978, 'Homogenized Transformers'] Consider two independent Gaussian random vectors $X\sim\cN(0,\Sigma^{X})$ and $Y\sim \cN(0,\Sigma^{Y})$. Define the interpolated Gaussian vector 
\begin{equation*}
    X_t=\sqrt{t}X+\sqrt{1-t}Y.
\end{equation*}
Then for all $\varphi\in C^2(\R^m)$, we have
\begin{equation*}
    \frac{\de}{\de t}\E \varphi(X_t)=\frac{1}{2}\E\left[\Tr\left((\Sigma^{X}-\Sigma^{Y})^{\sT}\; \nabla^{2}\varphi(X_t)\right)\right].
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] We have
    \begin{align*}
        \Cov\left(\sum_{i<j} (j-i+2)I_iI_j,\sum_{k=1}^m I_k\left(I_k-1\right)\right)=-\frac{2n(n-1)(m-1)(m+7)}{6m^2}.
    \end{align*}

