\begin{equation}
    \sum_{x_1,\ldots, x_k}
    \left|
        (A^{s_1})_{x_1x_2} (A^{s_2})_{x_2x_3} \cdots (A^{s_k})_{x_kx_1}
    \right|\le a^{s_1 + \cdots + s_k} \, r^k.
