[Thm 7 of arXiv:2604.03548, 'Degree-preserving conservative processes and a unified approach for their hydrodynamics'] Assume that the process $\{\eta(t)\}_{t\ge 0}$ satisfies all items in both Assumptions \ref{assmp:generator_element_basic} and \ref{assumption:second_order_polymonial}. 
Let $\rho_0\in L^2(\mathbb T)$ and  
let $\{\mu_N\}_{N\in\mathbb N}$ be a sequence of probability measures on $\mathscr X_N$ associated to  $\rho_0$.
Moreover, assume that  
\begin{equation}

\sup_{N\in\mathbb N}
E_{\mu_N}\bigg[\frac{1}{N} \sum_{x\in\mathbb T_N} \eta_x^2 \bigg] < C 
\end{equation}
for some constant $C>0$. 
Then, for every $t\in [0,T]$, the sequence of empirical measures $\{\pi^{N}_t\}_{N\in\mathbb N}$ converges in probability to the absolute continuous measure $\rho(t,u)du$, that is, for any $\delta>0$ and for any $G\in C^2(\mathbb{T})$ we have 
\begin{equation*}
\lim_{N\to\infty}
Q^{N}_m 
\bigg(\Big|\langle \pi^{N}_{t},G\rangle-\int_{\mathbb T} \rho(t,u)G(u)du \Big|>\delta\bigg) =0 
\end{equation*}
where $\rho(t,u)$ is the unique weak solution to the heat equation \eqref{eq:HDL_heat_equation} provided $m>5/2$, where recall that the measure $Q^{N}_m$ was defined  for the process taking values in Sobolev space $H^{-m}(\mathbb T)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro 12 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let the assumptions of \cref{cor:decay-mass}, excluding \eqref{eq:cor:decay-mass}, be satisfied. Let $\{M_n : n \ge 1\} \subseteq \bN\cup\{0\}$ be a non-decreasing sequence and assume that, for each $n \ge 1$, the  family $\{X^n_k :  k \in S_n\}$ is $M_n$-pairwise diagonally negatively dependent. If
\begin{align}
\lim_{n \to \infty} N(K_n, \ep)^{1 - (\frac{1}{p} \wedge \frac{1}{2})} \lt\|K_n\rt\| \BB((1+M_n) \sum_{k\in S_n} a_{n, k}^2\BB)^{\frac{1}{p} \wedge \frac{1}{2}} = 0\quad \trm{for all }  \ep >0,
\end{align}
then
	\begin{align*}
		\lim_{n \to \infty} \mathbb{E}  \,\BB\| \sum_{k \in S_n} a_{n, k} (X^n_k - \bE X^n_k) \BB\|^p  = 0.
	\end{align*}

