body:
[Defn def:root-biased of arXiv:2601.00119, 'The largest common subtree of two random trees'] Let $\mu$ be a critical measure on $\mathbb{N}$. A random plane tree $\tau_*$ is called a \emph{root-biased Bienaym\'{e} tree with offspring distribution $\mu$} if it satisfies the following properties:
\begin{enumerate}
    \item[(a)] For all $k \geq 0$, $\mathbf{P}(\mathrm{k}_\varnothing(\tau_*) = k) = (k+1)\mu(k+1)$.
    \item[(b)] For all $k \geq 1$ such that $\mathbf{P}(\mathrm{k}_\varnothing(\tau_*) = k) > 0$, conditionally given that $\mathrm{k}_{\varnothing}(\tau_*) = k$, $\theta_1\tau,...,\theta_k\tau$ are independent Bienaym\'{e} trees with offspring distribution $\mu$.
\end{enumerate}

[Lemma 5 of arXiv:2608.09419, 'Left-tail expansions for Schr\"oder branching processes with explicit convergence rates'] \lb{L2}
	Let $\mP_{p,E}$ be the set of polynomial probability generating functions with the expectation $P'(1)=E$ and, also, satisfying $P(0)=0$, $P'(0)=p$. Denote $N=\lfloor \frac{E-p}{1-p}\rfloor$. Then, the unique minimizer of the second derivative at $z=1$ is
	\[\lb{110}
	{\rm argmin}_{P\in\mP_{p,E}}P''(1)=pz+(N(1-p)+1-E)z^N+(E-p-N(1-p))z^{N+1}.
	\]
It is assumed that $E\ge 2-p$, because, otherwise, $\mP_{p,E}=\varnothing$, and \er{110} does not make sense. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 13 of arXiv:2605.03528, '\bf Kolmogorov-Smirnov distance and discrepancies {\em versus} Wasserstein distances'] $(a)$ Let $\mu$ and $\nu$ two probability measures on $([0,1]^d, {\cal B}or([0,1]^d),\lambda_d)$ be such that $\mu\big((0,1]^d\big)= \nu\big((0,1]^d\big) =1$. Then, for any integer $\ent\ge2$
\begin{equation}
{\cal W}^p_p(\mu, \nu)\le\diamd^p\frac{\ent^p+1}{2}\sum_{\ell\ge 1} \ent^{-p\ell} \sum_{F\in {\cal P}_\ell}|\mu(F)-\nu(F)|
\end{equation}
where  $\displaystyle \diamd=\sup_{x,y\in (0,1]^d}|y-x|$ depends on $p$, $d$ and the norm $|\cdot|$ on $(0,1]^d$ and
\begin{equation}
{\cal P}_\ell= \Big\{a+(-\ent^{-\ell}, \ent^{-\ell}]^d,\; a = \frac{2k+\mbox{\bf 1}}{\ent^{\ell}},\,k\in\llbracket 0,\ent^{\ell-1}-1\rrbracket^d  \Big\}
\end{equation}
with $\mbox{\bf 1} = (1,�\ldots,1)$. Note that ${\rm card}({\cal P}_\ell)= \ent^{d(\ell-1)}$.

\smallskip
\noindent $(b)$ \fab{When $\mu$ and $\nu$ are probability measures on $([0,1]^d, {\cal B}or([0,1]^d),\lambda_d)$, then~\eqref{eq:FG2} still holds with the family of $(\tilde{{\cal P}_\ell})_{\ell\ge0}$, where $\tilde{{\cal P}_\ell}$ is a partition of $[0,1]^d$ which only differs from ${{\cal P}_\ell}$ for the multi-indices $k=(k_1,\ldots,k_d)\in\llbracket 0,\ent^{\ell-1}-1\rrbracket^d$ for which there exists $i\in\llbracket1,d\rrbracket$ such that $k_i=0$. In this case, the semi-open box $\frac{2k+\mbox{\bf 1}}{\ent^{\ell}}+(-\ent^{-\ell}, \ent^{-\ell}]^d$ is replaced\footnote{More simply, when a semi-open box of ${\cal P}_\ell$ has one or severals faces which are included in the faces of $[0,1]^d$, we add them to define the elements of $\tilde{{\cal P}_\ell}$.} by
$$ \left\{x\in[0,1]^d, \frac{k_i}{\ent^{\ell-1}}<x^i\le \frac{k_i+1}{\ent^{\ell-1}} \textnormal{ if  $k_i\ge 1$}, 0\le x^i\le \frac{1}{\ent^{\ell-1}} \textnormal{ if  $k_i=0$}\right\}.$$
} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:geometric of arXiv:2411.10419, 'Lower bounds on the top Lyapunov exponent for linear PDEs driven by the 2D stochastic Navi'] For any $ \ell \in \mathbf{R}^{2} $ define $ Q_{\ell} (k) = || \ell |^{2} - 2 \langle k, \ell
\rangle |^{2} | \langle k^{\perp}, \ell \rangle |^{2}$.
Then there exists a $ c > 0 $ such that for all $ k \in \mathbf{Z}^{2} $
\begin{equ}
\sum_{| \ell | \leqslant \sqrt{2}} Q_{\ell}(k) \geqslant c | k |^{4} \;.
\end{equ}

[Prop of arXiv:2505.12127, 'Generalised principal eigenvalues and global survival of branching Markov processes'] For any $\sigma>0$ we have
\begin{equation}
    \limsup_{\sigma{\rightarrow} 0}\lambda_1'(L_0^\sigma)\leq -\frac{1}{2}.
\end{equation}
Moreover we have
\begin{equation}
\lambda_1''(L_0^\sigma)\geq \frac{7}{10}.   
\end{equation}
Therefore $\lambda_1'(L^\sigma_0)<\lambda_1''(L^\sigma_0)$ for all $\sigma>0$ sufficiently small. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 25 of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] Let $T<\infty$. The function $(t,l)\mapsto \tilde W_T(t,l)$ is $\llip{\tilde{\mathcal{S}}_T}$. Specifically, at points of differentiability it holds that
    \begin{equation}
        \partial_l \tilde{W}_T(t,l)=\mathbb{E}\left[\int_{0}^{\tilde\tau^*}\partial_l L^l_{u}\partial_l(\tilde{\mathcal{L}}\tilde{g})(L^l_{u})\,du\right]
    \end{equation}
    where $\tilde\tau^*:=\tilde\tau^*_T(t,l)$ is the optimal stopping time, and 
    \begin{equation}
        \mathbb{E}[c(t+\tilde\tau^*)]-c(t)\leq \partial_t\tilde{W}_T(t,l)\leq  \mathbb{E}[c(t+\tilde\tau^*)]-c(t) + K''\mathbb{P}(\tilde\tau^*=T-t),
    \end{equation}
     where $K''$ is defined in Proposition \ref{prop:time_lip}.

[Definition defi:pioxWP of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] When $j < N$,  the ${\sf ox}$-projection of $W_{j,V}$ is defined as
\begin{align}
	\pi_{{\sf ox}} W_{j, V} =  \pi_{{\sf ox}}  \mathbb{W}_{w_j ,  V_j }

\end{align}
The $\pi_{\sf ox}$-projection of $P_{j,V}$ is defined as
\begin{align}
	\pi_{{\sf ox}} P_{j,V} = \begin{cases} 
			\frac{1}{2} \operatorname{Loc}^{{\sf ox}} \Big( \operatorname{Cov}_{\pi, j+1} [\theta V ; \theta V] + \E_{j+1} \theta W_{j,V}  \Big) & (j +1 < N) \\
			0 & (j+1=N) .
		\end{cases}

\end{align}

[Pro transformation of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] We denote by $T \subset \mathbb{R}$ an interval, we fix $d \geq 1$ and we consider $P, P' \in \mathcal{P}((\mathbb{R}^d)^T)$.
		\begin{enumerate}
			\item Let $(f_t)_{t \in T}$ be a family of continuous injective functions from $\mathbb{R}^d$ to $\mathbb{R}^d$ and set $  f := \left( \otimes_{t \in T} f_t \right): (x_t)_{t \in T} \in {(\mathbb{R}^d)}^T \mapsto (f_t(x_t))_{t \in T} \in {(\mathbb{R}^d)}^T$.  If $P'$ is a weak (resp. the strong) local Markov transform of $P$, then ${f }_\# P'$ is a weak (resp. the strong) local Markov transform of ${ f}_\# P$.
			\item Let $S,T \subset \mathbb{R}$ be two intervals and $\phi :S \to T$ be a strictly increasing continuous function. If $P'$ is a weak (resp. the strong) local Markov transform of $P$, then $P'^{\phi} \in \mathcal{P}((\mathbb{R}^d)^S)$ is a weak (resp. the strong) local Markov transform of $P^\phi \in \mathcal{P}((\mathbb{R}^d)^S)$.
		\end{enumerate}

