body:
[Lemma lem:l2-chain of arXiv:2606.19763, 'Optimal Sparsification of Gaussian Processes'] Let $T$ be finite.
	Suppose $v_t:[0,1]\to\R^n$ and $a_t:[0,1]\to\R$ are absolutely continuous and that, for constants $L,M<\infty$,
	\[
		\|v_t'(\theta)\|_2\leq  L\,,
		\qquad
		|a_t'(\theta)|\leq  M
	\]
	for every $t\in T$ and for a.e.~$\theta\in[0,1]$.
	Fix $\beta>0$, and set
	\[
		H_\theta(g)
		=
		\frac{1}{\beta}
		\log\pbra{
		\sum_{t\in T}
		\exp\pbra{\beta\pbra{g\cdot v_t(\theta)+a_t(\theta)}}
		}\,.
	\]
	Then $\theta\mapsto H_\theta$ is absolutely continuous as a map from $[0,1]$ into $L^2$.
	Moreover, for a.e.~$\theta$, the $L^2$-derivative is represented by
	\[
		\frac{d}{d\theta}H_\theta(g)
		=
		\sum_{t\in T}
		\omega_t^\theta(g)
		\pbra{
		g\cdot v_t'(\theta)
		+
		a_t'(\theta)
		}\,,
	\]
	where
	\[
		\omega_t^\theta(g)
		:=
		\frac{
		\exp\left(\beta(g\cdot v_t(\theta)+a_t(\theta))\right)
		}{
		\sum_{t'\in T}
		\exp\left(\beta(g\cdot v_{t'}(\theta)+a_{t'}(\theta))\right)
		}\,.
	\]

[Lemma 11 (Terminal regularization and the third-derivative sign) of arXiv:2607.18032, 'FRSB in the SK spin glass: convergence to full-interval support at zero temperature'] For every $\lambda>0$, define
\begin{equation*}
 u_\lambda:=u^{\lambda,\gamma\wedge\lambda}=u^{h_\lambda,\gamma\wedge\lambda}.
\end{equation*}
For every $T<1$ and $j\geq0$,
\begin{equation}
 \lim_{\lambda\to\infty}\partial_x^ju_\lambda
 =\partial_x^ju^{|\cdot|,\gamma}
 \quad\text{locally uniformly on }[0,T]\times\R.

\end{equation}
In particular, for the unadorned solution $u:=u^{|\cdot|,\gamma}$,
\begin{equation}
 \mathsf D(t,x)=u_{xxx}(t,x)\leq0,
 \qquad \forall (t,x)\in[0,1)\times(0,\infty).

\end{equation}

[Lemma eq:GNpos of arXiv:2609.00481, 'The frameset of the second-order B-spline along $ab=1/q$'] For $N\in \mathbb{N}$, and $\gamma\in \mathbb{R}$, we have
\begin{align}
    G_N(\gamma) \vcentcolon= (N+1) F_{N+1}(\gamma) - D_N(\gamma) = \left(\frac{\sin(N\pi \gamma)}
    {\sin(\pi \gamma)}\right)^2 \geq 0, 
\end{align}
and
\begin{align}
    \sum_{k=1}^N k \cos(2\pi k \gamma) = \frac{N+1}{2}\left(D_N(\gamma) -
    F_{N+1}(\gamma)\right).
\end{align}

[Lemma 56 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] Let $E\subset F$ be a super order dense sublattice and let $B\subset F$ be solid. The following sets are equal:
\item[(i)] The set of all $f\in F$ such that there is $Q\subset B_{+}$ with $Q\uparrow\left|f\right|$;
\item[(i')] The set of all $f\in F$ such that there is $Q\subset B_{+}\cap E$ with $Q\uparrow\left|f\right|$;
\item[(ii)] The order adherence of $B$ in $F$;
\item[(ii')] The order adherence of $B\cap E$ in $F$;
\item[(iii)] The uo adherence of $B$ in $F$;
\item[(iii')] The uo adherence of $B\cap E$ in $F$.\medskip

This set is solid and its intersection with $E$ is the common $\sigma$-order and $\mathrm{u\sigma o}$ adherence of $B\cap E$ in $E$. The $\sigma$-order and $\mathrm{u\sigma o}$ closures of $B$ and $B\cap E$ also coincide, and are a solid set. Both the adherence and the closure are convex, whenever $B$ is. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 15 of arXiv:2510.27451, 'Bi-martingale optimal transport and its applications'] We have the equality,
	\begin{align*}
		Z_2(\mu,\nu) &=  \min\left\{ \int_X \! \int_Y \!\frac{1}{2} \bigg( \Big| \frac{dq}{d\gamma}(x,y) - x \Big|^2\! \!\!+ \Big| \frac{dq}{d\gamma}(x,y) - y \Big|^2  \bigg)   \gamma(dxdy) \, : \, 	(\gamma,q) \in \Gamma Q(\mu,\nu)  \right\}
	\end{align*}
	and the set of minimizers is identical to the set of minimizers in \eqref{eq:C_gammaq}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:Jrr-sharper of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{lem:averaged_ball_connection}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel with $J(x,y) = O(d_G(x,y)^{-d \alpha})$ with $\alpha>1$.

     Let $\varepsilon \in(0,1)$.

    Then there exists $c = c(G,J)$ such that for all $k\in \mathbf{N}$, at least $(1-\varepsilon)$ proportion of the radii $r \in [2^{k-1},2^k]$ satisfy

    \begin{equation}

        J
        \left(
            B(r), 
            B(r)^c
        \right)
        \leq 
         \frac{c}{\varepsilon}
        r^{
        \max
        \left(
            d(2-\alpha),
            d - 1
        \right)  
        }
        \log(r)^{
            \mathbf{1}
            \left(
                \alpha=1+1/d
            \right)
        }.
    \end{equation}

