[Theorem T:diam_extreme of arXiv:2512.21977, 'Repeat times and a two-weight UST model'] Let $\gamma \geq 5$. For any $\varepsilon > 0$ there exists $A = A(\varepsilon)$ and $n_0 = n_0(\varepsilon)$ such that for $n \geq n_0$
    \begin{equation}
         \widehat{\mathbb{P}} \big( A^{-1} n^{1/3} \log n \leq \operatorname{diam}({\ensuremath{\mathcal T}} ) \leq A n^{1/3} \log n \log \log n \big) \geq 1 - \varepsilon,
    \end{equation}
    where $\widehat{\mathbb{P}}(\cdot)$ is the averaged law $\mathbb{E}[\ensuremath{\boldsymbol{\mathrm{P}}}_{\ensuremath{\mathcal T}} (\cdot)]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 25 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, let $E_*$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}. For $\eps_*>0$ sufficiently small, every $z$ with $|z-E_*|<\eps_*$ and $\Im z\geq0$ satisfies
        \begin{align}
                |\Theta|+\|\bbs_*\| & \lesssim|z-E_*|^{1/3}\leq\eps_*^{1/3},  \\
                \|\bbs_*\|          & \lesssim|z-E_*|+|\Theta|^2. 
        \end{align}
        Moreover, $\Theta$ satisfies
        \begin{align}
                0=\mu_1(z-E_*)+\mu_2\Theta^2+\mu_3\Theta^3+O(|z-E_*||\Theta|+|z-E_*|^2+|\Theta|^4), 
        \end{align}
        and the coefficients defined above are real and satisfy
        \begin{align}
                c\leq\mu_1\leq C, \qquad |\mu_2|+|\mu_3|\leq C. 
        \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm of arXiv:2609.00884, 'The weakness of typicality'] \label[theorem]{thm:rp12-criterion-genericity}
Let $\mathsf{P}$ be a r$\Pi^1_2$-problem.
\begin{itemize}
    \item[(1)] $\mathsf{P}$ has property \textup{P}${}_1$ for genericity if and only if there is a computable $\mathsf{P}$-instance with no computable $\mathsf{P}$-solution.
    \item[(2)] $\mathsf{P}$ has property \textup{P}${}_2$ for genericity if and only if the class of sets~$A$ computing a $\mathsf{P}$-instance with no $A$-computable $\mathsf{P}$-solution, is co-meager.
    \item[(3)] $\mathsf{P}$ has property \textup{P}${}_3$ for genericity if and only if there is a $\mathsf{P}$-instance~$X$ with no $X$-computable $\mathsf{P}$-solution.
\end{itemize}

