[Defi 9 (Measure-preserving Map) of arXiv:2506.13587, 'Non-exchangeable mean-field theory for adaptive weights: propagation of dissociatedness an'] For two probability spaces $(\Omega, \mathcal{A}, \pi)$ and $(\Omega', \mathcal{A}', \pi')$, a measurable map $\varphi: \Omega \to \Omega'$ is called \textit{measure-preserving} if
    \begin{equation*}
        \pi(\varphi^{-1}(A')) = \pi'(A') \quad \text{for all } A' \in \mathcal{A}'.
    \end{equation*}
    That is, the push-forward of $\pi$ by $\varphi$ coincides with $\pi'$, denoted as $\varphi_{\#} \pi = \pi'$.

[Lemma 11 of arXiv:2605.18136, 'L\'evy processes with partially stochastic resetting'] Let $q,\lambda >0$, $p \in (0,1)$ and $[u_1,u_2] \subset \B$ s.t.~$[pu_1,pu_2] \subset \B$. Then, for $x \in \B$ and $f \in C_\mathrm{b}(\B)$, 
	\begin{equation}
		\lim\limits_{p\rightarrow 0} \int^{u_2}_{u_1} \overline{\V}^{(p)}_\lambda[\f^{(q+\lambda)}](x,y) f(py) \dd y  = f(0)  \frac{\lambda \int^{u_2}_{u_1} \f^{(q+\lambda)}(x,y) \dd y}{1- \lambda \int^{u_2}_{u_1} \f^{(q+\lambda)}(0,y) \dd y}, 
	\end{equation} 
	where $\overline{\V}^{(p)}_\lambda[\f^{(q+\lambda)}]$ is given in Definition \ref{Def:ResolventDefn}.

