body:
[Proposition 21 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X,\|\cdot\|_X)$ and $(Y,\|\cdot\|_Y)$ be finite dimensional normed spaces. Let $c: X \times Y \to \R$ be a continuous cost function that is positively 1-homogeneous in the second variable, meaning $c(x, ty) = tc(x,y)$ for all $t > 0$.

    Suppose a bounded set $K\subset X$ satisfies the non-degeneracy condition:
    \begin{equation}

        \inf_{u \in \mathbb{S}_Y} \sup_{x \in K} -c(x,u) = \epsilon > 0,
    \end{equation}
    where $\mathbb{S}_Y = \{y \in Y \mid \|y\|_Y = 1\}$. Let $L \subset Y$ be a non-empty set and suppose that $-c$ is non-negative on $K\times L$. Set $M(K,L) = \sup_{x\in K, y\in L} -c(x, y)$. Then,
    \begin{enumerate}
        \item If $L$ is unbounded, then $M(K,L)=\infty$.
        \item If $L$ is bounded, then $0\leq M(K,L)<\infty$ and $L\subseteq M(K,L)K^{\circ, c}$. Moreover, if $-c(x,y)=0$ for all $x \in K$ implies $y=o$, then $M(K,L)=0$ implies $L=\{o_Y\}$.
    \end{enumerate}

[Lemma 15 of arXiv:2608.02319, 'Averaging Principle for Ordinary Differential Equations in a Multiscale Random Environment'] For all $0<s<t$, $n,k\geq 1$, $x\in E$ and $z\in\mathbb R^d$ we set 
\begin{align*}
\phi_{s,t}^{n,k}(z,x):=\mathbf E_x\big[f_1(\mathbf Z_s^{n,z})\,f_2(\mathbf Z_t^{n,z})\,\mathbf 1_{\{\tau_{k-1}^n<s<t\leq\tau_k^n\}}\big].
\end{align*}
Then, for all $T>0$, $0<s_1<s_2<T$, $t_1<t_2<T$ and $L,M>0$ we have
\begin{align*}
&\lvert\phi_{s_1,t_1}^{n,k}(y,x)-\phi_{s_2,t_2}^{n,k}(y,x)\rvert\\
&\leq\big(\|f_1'\|_\infty\,\|f_2\|_\infty\,(s_2-s_1)+\|f_1\|_\infty\,\|f_2'\|_\infty\,(t_2-t_1)\big)\,\Big(L\,(\lvert z\rvert+TM)\,e^{TL}+M\Big)\\
&+2\,\|f_1\|_\infty\,\|f_2\|_\infty\,\big(\mathbf P_x(s_2\leq\tau_k^n,L_{s_2}^n>L)+\mathbf P_x(s_2\leq\tau_k^n,M_{s_2}^n>M)\big)\\
&+\|f_1\|_\infty\,\|f_2\|_\infty\,\mathbf P_x(s_1\leq\tau_{k-1}^n<s_2)+\mathbf P_x(t_1\leq\tau_k^n<t_2)+\mathbf P_x(t_2\leq\tau_k^n,L_{t_2}^n>L)\\
&+\mathbf P_x(t_2\leq\tau_k^n,M_{t_2}^n>M)\big)+\mathbf P_x(s_1\leq\tau_{k-1}^n<s_2)+\mathbf P_x(t_1\leq\tau_k^n<t_2)\big).
\end{align*}

[Proposition 6 of arXiv:2609.00946, 'Embedded Conditional Independence Tests for Large Language Model Generated Text with an Ap'] Suppose $\Sigma(X,Z)$ is almost surely positive definite with $0 < \E[h^{\top}\Sigma^{-1}h] < \infty$, and let $\mathcal{F}$ be the set of measurable $f : \mathcal{X} \times \mathcal{Z} \to \mathbb{R}^K$ with $0 < \E[f^{\top}\Sigma f] < \infty$, all functions being evaluated at $(X,Z)$. Then
  \begin{equation}

    \sup_{f \in \mathcal{F}} \frac{\bigl(\E\langle h, f\rangle\bigr)^2}{\E\bigl[f^{\top}\Sigma f\bigr]} = \E\bigl[h^{\top}\Sigma^{-1}h\bigr],
  \end{equation}
  and the supremum is attained at $f \in \mathcal{F}$ if and only if $f = \kappa\,\Sigma^{-1}h$ almost surely for some $\kappa > 0$.

