[Lemma 5 of arXiv:2604.06823, 'On spectrum of sample correlation matrices from large fold tensor vectors'] (\cite{Bai1999}*{Lemma 2.7}) 
Let $A,B$ be two $p \times n$ complex matrices. Then
\begin{align*}
    L^4 \left( F^{AA^*}, F^{BB^*} \right) \le \dfrac{2}{p^2} \Tr \left( (A-B)(A-B)^* \right)  \Tr \left( AA^*+BB^* \right).
\end{align*}
Here, $L(\cdot,\cdot)$ denotes the L\'evy distance of two distribution functions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary gumbel of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] \phantom{a}
\begin{itemize}
\item[(a)]
For $x>0$ and real $s$,
\begin{align}
\lim_{\varepsilon\to0^+}F(x,({s-\log\varepsilon})/{\varepsilon};e^{-\varepsilon})=\exp \left({-xe^{-s}}\right).
\end{align}
\item[(b)]
The counting function $N_q$ of the absolute squares of zeroes of the Gaussian power series ${\varphi (z)}=\sum_{k\ge 0} c_k z^k $ conditioned on the event that $|g(0)|^2=t$ converges in distribution, in the scaling limit
\begin{align}
q\to 1^{-}\,\, \text{ and }\,\, t=\frac{s-\log \log \frac1 q }{\log \frac 1 q},
\end{align}
 to Poisson$(e^{-s})$.
\end{itemize}

