[Cor non of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Suppose exactly the same conditions as that of Corollary (cor;non of the paper), then 
	\begin{equation}
		\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P(B\cap T^{-i}C)=P(B)Q(C)\text{ for any }B,C\in\mathcal{F}.
	\end{equation}
	In particular, 
	\begin{equation}
		\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P\circ T^{-i}=Q.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem syy2 of arXiv:2411.09949, '$W_{\bf d}$-convergence rate of EM schemes for invariant measures of supercritical stable '] Let $\alpha\in(1,2)$ and ${\bf d}(x,y)=|x-y|$. It holds that
\begin{align*}
\frac{\alpha-1}{\alpha}\int_{0}^{1}r^{\alpha}\mathrm{e}^{-\frac{r^\alpha}{\alpha}}{\mathord{{\rm d}}} r\leqslant \varliminf_{\eta\to0}\frac{{\mathcal W}_{\bf d}(\mu_\eta,\mu)}\eta\leqslant \varlimsup_{\eta\to0}\frac{{\mathcal W}_{\bf d}(\mu_\eta,\mu)}\eta\leqslant \frac{\alpha-1}{2\alpha^{(1+\alpha)/\alpha}}{\mathbb E} \big|L^{(\alpha)}_1\big|.
\end{align*}

