[Proposition prop: set of probability one of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] There exists a set of probability one $\Gamma \in \mathcal{F}$ such that if $\omega \in \Gamma$, then
	\begin{equation*}
		\lim_{N \to \infty} \bar\boldsymbol{X}^N(\omega) = \bar\boldsymbol{X}(\omega), \quad \bar\boldsymbol{A}_t(\omega, \varphi) = \lambda_0 \int_0^t \varphi_s(0, 0)ds \quad \text{and} \quad \bar\boldsymbol{D}(\omega) = \bar\boldsymbol{D}^c(\omega).
	\end{equation*}
	We may and will define $\Gamma$ such that property (c) of Assumption (ass: standing assumptions 1 of the paper) holds in $\Gamma$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 26 of arXiv:2606.24167, '\bf On the stability of rarefaction for stochastic viscous conservation law'] If coefficients in Lemma \ref{stochastic area} satisfy the following
    \begin{enumerate}
      \item[\rm{(A1) }]{ $
\xi_j < \theta^\prime_j(\bar\rho\psi_j -1), \text{ if } \theta^\prime_j>0 \text{ and }\psi_j\geq 0;\, j=1,\cdots, \mathfrak n.$}
      \item[\rm{(A2) }]{  $
\kappa<(\alpha-1)\bar\rho-1.$}
      \end{enumerate}
      Then  one can take appropriate $y$, $w\geq0$ and $z>0$, such that 
      \bae 
a_j>1,\ \forall j\in \Theta,\quad \mathfrak b>1,\quad \mathfrak c<0,
\eae
 and
 \begin{eqnarray}
-z(y+\rho+\xi)+w&>&0,\\
     yz-w-1&>&0, \\
 w/\theta^\prime_j+\gamma_j+(a_j-1)z&>&1,\ \forall j\in \{j,\theta_j^\prime> 0\},\\
  (\mathfrak b-1)z&>&1. 
\end{eqnarray}

[Proposition 13 ({Single-time adapted $L^2(\mathcal{F}_t)$-bound}) of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] Let $n, D, J_n \in \mathbb{N}$ and $\boldsymbol{\alpha} \in \mathbb{N}^{J_n \times D}$ as above. Then, for every $\varepsilon>0$, there exists a $\operatorname{MLP}$ with $\operatorname{ReLU}$ activation function $\Phi_{\boldsymbol{\alpha},\varepsilon}:\mathbb{R}^{J_n \times D} \rightarrow \mathbb{R}$ such that 
\begin{equation}

        \mathbb{E}\left[ \left\vert h_{\boldsymbol\alpha}(\mathbf{Z}) - \Phi_{\boldsymbol\alpha,\varepsilon}(\mathbf{Z}) \right\vert^2 \right]^\frac{1}{2} \leq \varepsilon;
\end{equation}
$\Phi_{\boldsymbol\alpha,\varepsilon}(\mathbf{Z}) \in L^2(\mathcal{F}_t)$ when $\mathbf{Z}$ is $\mathcal{F}_t$-measurable. Moreover, the complexity of $\Phi_{\boldsymbol{\alpha},\varepsilon}(\cdot)$ can be chosen in the following way. We set $Q_n \eqdef J_n D$, write $h_m(x)=\sum_{\ell=0}^{m} c_{m,\ell} x^{\ell}$, and define $A_{m,B}\eqdef \sum_{\ell=0}^{m}|c_{m,\ell}|B^{\ell}$ and $A_{\boldsymbol{\alpha},B}\eqdef 1 + \max_{j \in [J_n]_{+} \\ r \in [D]_{+}} A_{\alpha_{j,r},B}$, for $B > 0$. In addition, we define $\mathcal{C}_{\boldsymbol{\alpha},B}\eqdef 1 + \sup_{z \in [-B,B]^{J_n \times D}}|h_{\boldsymbol{\alpha}}(z)|$ and choose $B_{\boldsymbol{\alpha},\varepsilon}$ such that
\begin{equation*}
\left(
\mathbb E\left[
\mathbf 1_{\{\|\mathbf{Z}\|_\infty>B_{\boldsymbol{\alpha},\varepsilon}\}}
|h_{\boldsymbol{\alpha}}(\mathbf{Z})|^2\right]\right)^{1/2}\le\frac{\varepsilon}{3},\quad\text{and}\quad\mathcal C_{\boldsymbol{\alpha},B_{\boldsymbol{\alpha},\varepsilon}}\,
\mathbb P\left(\|\mathbf{Z}\|_\infty>B_{\boldsymbol{\alpha},\varepsilon}\right)^{1/2}\le
\frac{\varepsilon}{3}.    
\end{equation*}
Finally, we set $\varepsilon_{\mathrm{loc}}\eqdef
\min\left\{\frac12,\frac{\varepsilon}{3}\right\}$ and $\ell_{Q_n}\eqdef
\left\lceil\log_2(Q_n\vee2)\right\rceil$.

Then, $\Phi_{\boldsymbol\alpha,\varepsilon}(\cdot)$ may be chosen with $\operatorname{width}(\Phi_{\boldsymbol\alpha,\varepsilon}(\cdot)) \leq C(Q_n+n+1)$,
\begin{equation*}
\begin{aligned}
    \operatorname{depth}(\Phi_{\boldsymbol\alpha,\varepsilon}(\cdot)) \leq C\Bigg[
& 1+
\max_{\substack{j \in [J_n]_{+}\\ r \in [D]_{+}}}
\log_2\left(
1+
\frac{
2 Q_n\,\alpha_{j,r}\,
A_{\alpha_{j,r},B_{\boldsymbol{\alpha},\varepsilon}} A_{\boldsymbol{\alpha},B_{\boldsymbol{\alpha},\varepsilon}}^{Q_n-1}}{\varepsilon_{\mathrm{loc}}}
\right) \\
&\qquad\quad
+
\ell_{Q_n}
\left(
1+
\log_2\left(
1+
\frac{
2^{Q_n+1}Q_n
A_{\boldsymbol{\alpha},B_{\boldsymbol{\alpha},\varepsilon}}^{\,Q_n}
}{
\varepsilon_{\mathrm{loc}}
}
\right)
\right)
\Bigg]
\end{aligned}
\end{equation*}
and number of non-zero parameters
\begin{equation*}
\begin{aligned}
\operatorname{size}(\Phi_{\boldsymbol\alpha,\varepsilon}(\cdot)) \leq C\Bigg[
&(Q_n+n)
\left(
1+
\max_{\substack{j \in [J_n]_{+}\\ r \in [D]_{+}}}
\log_2\left(
1+
\frac{
2Q_n\,\alpha_{j,r}\,
A_{\alpha_{j,r},B_{\boldsymbol{\alpha},\varepsilon}}\,
A_{\boldsymbol{\alpha},B_{\boldsymbol{\alpha},\varepsilon}}^{\,Q_n-1}
}{
\varepsilon_{\mathrm{loc}}
}
\right)
\right)
\\
&\qquad\qquad
+
Q_n
\left(
1+
\log_2\left(
1+
\frac{
2^{Q_n+1}Q_n
A_{\boldsymbol{\alpha},B_{\boldsymbol{\alpha},\varepsilon}}^{\,Q_n}
}{
\varepsilon_{\mathrm{loc}}
}
\right)
\right)
+1
\Bigg],
\end{aligned}
\end{equation*}
where $C>0$ is a universal constant independent of $n,J_n,D,\boldsymbol{\alpha},\varepsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem-purely discontinuous-New of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Assume that $\phi \inU$ and a function   $g\colon \mathbb{R} \to \mathbb{R}_+$
satisfies Condition (condition-g function of the paper).
Then, for every $n\in \mathbb{N}$ and every  $t \in [0,T]$, the following identities hold $\mathbb{P}$-almost surely,
\begin{align}
\sum_{s\in [0,t]} g(\Delta \langle {u}_n(s), \phi \rangle)
&=\int_0^t \int_{Y} g\bigl(  \ip{P_n F(s,{u}_n(s-),y)}{\phi}{H}\, \bigr) {\eta}(\mathrm{d} s,\mathrm{d} y),

	\end{align}
and
\begin{align}

\int_0^t \int_{Y} g\bigl(  \ip{P_n F(s,{u}_n(s-),y)}{\phi}{H}\, \bigr) \tilde{\eta}(\mathrm{d} s,\mathrm{d} y) &=	\sum_{s\in [0,t]} g(\Delta \langle {u}_n(s), \phi \rangle)
\\ \nonumber
&\hspace{-3truecm}-\int_0^t \int_{Y} g\bigl(  \ip{P_n F(s,{u}_n(s),y)}{\phi}{H}\, \bigr) \mathrm{d} s\, \nu(\mathrm{d} y).
\end{align}

[Proposition Bcurv of arXiv:2608.30747, 'Compact homogeneous complex manifolds'] For any $\alpha,\beta\in\Delta_\qg^+$ and $A\in\ag^c$,
\begin{equation}
R^b(A,E_\alpha)E_\beta = g_\ag\left(A,\tfrac{1}{x_{\alpha+\beta}}A_{\alpha+\beta}-\tfrac{1}{x_{\beta}}A_{\beta}\right) \tfrac{N_{\alpha,\beta} \left(x_{\alpha+\beta}-x_\alpha\right)}{x_{\alpha+\beta}}E_{\alpha+\beta}, \qquad  \alpha+\beta\in\Delta_\qg, 
\end{equation}
\begin{equation}
R^b(E_\alpha,E_{-\alpha})E_\beta  = -\left(\la\alpha,\beta\ra+\tfrac{g_\ag(A_\alpha,A_\beta)}{x_\beta}\right)E_\beta, \qquad  \alpha\pm\beta\notin\Delta_\qg, 
\end{equation}
and 
\begin{equation}
R^b(E_\alpha,E_{-\alpha})E_\beta  =
\left(\tfrac{N_{-\alpha,\beta}^2 \left(x_{\beta}-x_\alpha\right)^2}{x_{-\alpha+\beta}x_\beta} 
-\tfrac{N_{\alpha,\beta}^2 \left(x_{\alpha+\beta}-x_\alpha\right)^2}{x_{\alpha+\beta}x_\beta} -\la\alpha,\beta\ra-\tfrac{g_\ag(A_\alpha,A_\beta)}{x_\beta}\right)E_\beta, 
\end{equation}
where in the last line, the term containing $N_{-\alpha,\beta}^2$ appears only if $-\alpha+\beta\in\Delta_\qg^+$ and the term containing $N_{\alpha,\beta}^2$ appears only if $\alpha+\beta\in\Delta_\qg^+$.  

Furthermore, if $\alpha+\beta\in\Delta_\qg$ and $\alpha-\beta\notin\Delta_\qg$, then 
\begin{equation}
R^b(E_{-\alpha},E_\beta)E_\alpha 
= -\tfrac{N_{\alpha,\beta}^2 \left(x_{\alpha+\beta}-x_\beta\right)\left(x_{\alpha+\beta}-x_\alpha\right)}{x_{\alpha+\beta} x_{\beta}} E_\beta. 
\end{equation}

