[Definition attractor of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] A random compact set $\mathcal{A} = \{ \mathcal{A}(\omega^-) \}_{\omega^- \in \mathcal{B}}$ is called a \(\mathrm{P}\)-pullback attractor for the SDS \(\varphi\) if the following conditions are satisfied.
	\begin{enumerate}
		\item For every $\omega^-, \omega^+ \in \mathcal{B}$, we have
		\[
		\Phi^{t}_{(\omega^-,\omega^+)}(\mathcal{A}(\omega^-)) = \mathcal{A}(P_t(\omega^-,\omega^+)).
		\]

		\item For every compact set 
		\( K \subset \mathbb{R}^d \)
		\[
		\lim_{t \to \infty} \sup_{x \in K} d(\varphi^{t}_{\omega^-}(x), {\mathcal{A}}(\omega^-)) = 0 \quad \mathbf{P}\text{-a.s.}
		\]
	\end{enumerate}
