[Lemma 116 (Properties of $^{(\textnormal{reg})}\newuL$, its flow, and an approximate eikonal function) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] \hfill

\noindent \underline{\textbf{Properties of $^{(\textnormal{reg})}\newuL$:}}

Let $^{(\textnormal{reg})}\newuL$ be as in \eqref{E:REGULARINGOINGNULLVECTORFIELD}. Then $^{(\textnormal{reg})}\newuL$ is a $\gfour$-null vectorfield. Moreover, in the differential structure of the geometric coordinates, $^{(\textnormal{reg})}\newuL$ is a $\nullhyparg{u}$-transverse vectorfield of class $C^{1,1}_{\textnormal{geo}}\left(\twoargMrough{[\timefunction_0,0],[- \rightu,\leftu]}{0}\right)$. In addition, $^{(\textnormal{reg})}\newuL$ is also transverse to $\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}$.

\medskip

\noindent \underline{\textbf{The flow of $^{(\textnormal{reg})}\newuL$:}}

Denote the flow map of $^{(\textnormal{reg})}\newuL$ by $^{(\textnormal{reg})}\Lambda_{\Delta s}$. That is, the $(t,u,x^2,x^3)$-coordinate components of $^{(\textnormal{reg})}\newuL$ solve: 
\begin{align}
	\frac{\p}{\p \Delta s} \, ^{(\textnormal{reg})}\Lambda_{\Delta s} (t,u,x^2,x^3) = \,^{(\textnormal{reg})}\newuL \circ \, ^{(\textnormal{reg})}\Lambda_{\Delta s}(t,u,x^2,x^3), & & ^{(\textnormal{reg})}\Lambda_{0}  (t,u,x^2,x^3) = (t,u,x^2,x^3). 
\end{align}
Let $\domainforembeddingdatahypfortimefunctiontwoarg{0}{[0,\mupositive]}, \, \embeddingdatahypfortimefunctionarg{0}, \, \scalarembeddingdatahypfortimefunctionarg{0}$ be the set and maps defined in Prop.\,\ref{P:PROPERTIESOFMUXMUZEROLEVELSET}. Then there exists a unique maximal flowout domain $^{(\textnormal{reg})} \mathscr{F} \subset \R \times \domainforembeddingdatahypfortimefunctiontwoarg{0}{[0,\mupositive]}$ and flow $^{(\textnormal{reg})}F$ given by: 
\begin{subequations}
	\begin{align}
		\begin{split}
			^{(\textnormal{reg})}\mathscr{F} & \eqdef \left\{ (\Delta s, t,x^2,x^3) \ | \ (t,x^2,x^3) \in \domainforembeddingdatahypfortimefunctiontwoarg{0}{[0,\mupositive]}  \right. \\
			& \ \ \left. \text{ and } \Delta s \in [\, ^{(\textnormal{reg})}\Delta a(t,x^2,x^3) - \scalarembeddingdatahypfortimefunctionarg{0}(t,x^2,x^3), \, ^{(\textnormal{reg})}\Delta b(t,x^2,x^3) - \scalarembeddingdatahypfortimefunctionarg{0}(t,x^2,x^3)] \right\},
		\end{split} \\
		^{(\textnormal{reg})} F(\Delta s,t,x^2,x^3) & \eqdef \, ^{(\textnormal{reg})}\Lambda_{\Delta s} \circ  \embeddingdatahypfortimefunctionarg{0}(t, x^2,x^3),  
	\end{align} 
\end{subequations}
for some $C^{1,1}$ functions  $^{(\textnormal{reg})}\Delta b, \, ^{(\textnormal{reg})} \Delta a \colon \domainforembeddingdatahypfortimefunctiontwoarg{0}{[0,\mupositive]} \to \R$. Set: 
\begin{align}
	^{(\textnormal{reg})} \mathscr{D} \eqdef \, ^{(\textnormal{reg})} F \left(\, ^{(\textnormal{reg})}\mathscr{F} \right) 
\end{align}
as the flowout of $\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}$ by $^{(\textnormal{reg})}\newuL$. Then $^{(\textnormal{reg})} F$ is a $C^{1,1}(^{(\textnormal{reg})}\mathscr{F})$-diffeomorphism with inverse  $^{(\textnormal{reg})} F^{-1} \in C^{1,1}_{\textnormal{geo}}(^{(\textnormal{reg})}\mathscr{D})$ satisfying:
\begin{subequations}
	\begin{align}
		\left\|\, ^{(\textnormal{reg})} F \right\|_{C^{1,1}(\, ^{(\textnormal{reg})}\mathscr{F})} \lesssim 1,  \\ 
		\left\|\, ^{(\textnormal{reg})} F^{-1} \right\|_{C^{1,1}_{\textnormal{geo}}(\, ^{(\textnormal{reg})}\mathscr{D})} \lesssim 1. 
	\end{align}
\end{subequations}Moreover, if $|\timefunction_0|$ is sufficiently small, for any  $(t,x^2,x^3) \in \domainforembeddingdatahypfortimefunctiontwoarg{0}{[0,\mupositive]}$, we have: 
\begin{subequations}
	\begin{align}
		\timefunction \circ \, ^{(\textnormal{reg})}F(\, ^{(\textnormal{reg})}\Delta b(t,x^2,x^3),t,x^2,x^3)  & = 0,   \\
		\timefunction \circ \, ^{(\textnormal{reg})}F( \, ^{(\textnormal{reg})}\Delta a(t,x^2,x^3),t,x^2,x^3)  & = \timefunction_0, .
	\end{align}
\end{subequations}
That is, the flowouts to the left and right of $\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}$ always terminate on $ \hypthreearg{0}{[- \rightu,\leftu]}{0}$ and $ \hypthreearg{\timefunction_0}{[- \rightu,\leftu]}{0}$, respectively.

Finall

