&\leq \sup _{n \geq n_{0}} 2 \frac{1}{\varepsilon_{2}^{2}} \mathbb{E}[\langle M^{f, j}\rangle_{\tau_{n}}-\langle M^{f, j}\rangle_{\sigma_{n}}+|A_{\tau_{n}}^{f, j}-A_{\sigma_{n}}^{f, j}|^{2}] \quad \text { (by Markov inequality) } \\
&\leq \frac{2}{\varepsilon_{2}^{2}}C \delta \leq \varepsilon_{1} \quad \text { (by Lemmas } (L:AldousA_M of the paper) \text { and } (L:AldousA_A of the paper) \text{ with } \delta \text { sufficiently small)","release_manifest_digest":"sha256:733a0fee76e669047bd73c5f2b4cabd68af7b24f1bc719d99fbd524b46721144","revision_digest":"sha256:e742b5aac8c0805f6ab768113a527752b449e2f011c71c57bb19fde894dd1e86","source_id":"arxiv:2606.03079","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

