[Lemm BTZbound of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] Let Assumption (assum52 of the paper) be in force. Then 
				\begin{align*}
					|Y_i| \leq (\|\xi\|_{\infty} + \Lambda_0 T)\exp\left(1+\Lambda_yT \right).
				\end{align*}

[Defi 2 of arXiv:2609.02427, 'Ampleness in the Farey graph'] \cite{PillayGeomFork, AmpleDividing}
Let $T$ be a stable theory and $n\geq1$. Then $T$ is $n$-ample if (after possibly adding some parameters) there are 
$a_0,a_1,\ldots,a_n$ such that:
\begin{enumerate}
\item $a_0$ forks with $a_n$ over $\emptyset$;
\item $a_{i+1}$ does not fork with $a_0,\ldots,a_{i-1}$ over $a_i$, for $1\leq i<n$;
\item $\acl^{eq}(a_0)\cap \acl^{eq}(a_1)=\acl^{eq}(\emptyset)$;
\item $\acl^{eq}(a_0,\ldots,a_{i-1},a_i)\cap acl^{eq}(a_0,\ldots,a_{i-1},a_{i+1})=\acl^{eq}(a_0,\ldots,a_{i-1})$, for $1\leq i<n$.
\end{enumerate}

[Lemma eq:dI-budget of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:aggregate-jet-budget}
Uniformly in \(O\in\mathcal O_{N,L}\),
\begin{equation}
 \sum_{I\in[N]^p}\mathfrak d_I\le C N,
 \qquad
 \max_{I\in[N]^p}\mathfrak d_I\le Cq_N^2.
\end{equation}
Writing \(\alpha_I(J)=\partial_I\Psi_O(J)\), one also has
\begin{equation}
 \max_I\left\lvert\alpha_I(J)\right\rvert\le Cq_N,
 \qquad
 \sum_I\left\lvert\alpha_I(J)\right\rvert^2\le CN,
\end{equation}
and, for \(2\le k\le m+1\),
\begin{equation}
 \left\lvert\partial_I^k\Psi_O(J)\right\rvert
 \le C_k\mathfrak d_Iq_N^{k-2}.
\end{equation}
Consequently, for \(2\le k\le m+1\),
\begin{align}
 \left\lvert\partial_I^kF_O(J)\right\rvert
 &\le C_kF_O(J)
 \left(\left\lvert\alpha_I(J)\right\rvert^k+
       \mathfrak d_Iq_N^{k-2}\right),
 \\
 \sum_I\left\lvert\partial_I^kF_O(J)\right\rvert
 &\le C_kNq_N^{k-2}F_O(J).

\end{align}
All constants are uniform in \(J,N,O\).

[Lemma lemma10.444 of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Under the assumption of Theorem (Theorem1.2 of the paper), for any $\delta_1,\delta_2\geq e^{-cn^{\sigma}}$, any $u\in\mathbb{S}^{n-1}$, and any $p>1$, we have the following estimate:
\begin{equation}
\begin{aligned}
&\mathbb{E}_{A_n}\sup_{r_1,r_2\in\mathbb{R}}\mathbb{P}_X\left(
    \frac{|\langle (A_n-\lambda_i I_n)^{-1}X,X\rangle-r_i|}{\|(A_n-\lambda_i I_n)^{-1}\|_*}\leq\delta_i
    ,\langle X,u\rangle\geq s,\frac{\prod_{i=1}^2\mu_1(\lambda_i)}{n}\leq(\delta_1\delta_2)^{-p}
    \right)\\&\lesssim e^{-s}\delta_1\delta_2+e^{-\Omega(n^{\sigma/2})}
    \\&+e^{-s}\delta_1\delta_2\mathbb{E}_{A_n}\left[\left(\frac{\prod_{i=1}^2\mu_1(\lambda_i)}{n}\right)^{\frac{9}{10}}
    \wedge\left\{ \frac{\prod_{i=1}^2\mu_1(\lambda_i)}{n}\leq (\delta_1\delta_2)^{-p}\right\}\right]^{\frac{80}{81}},\end{aligned}
\end{equation}
    where the constant $c>0$ in the assumption $\delta_i\geq e^{-cn^\sigma}$ and the implied constant in the inequality $\lesssim$ depend on all the constants $B,\kappa,\Delta,\sigma$.

[Lemma 29 of arXiv:2608.26816, '\textbf{On the existence of maximal foliations in general relativity}'] Under  the assumptions of Theorem \ref{maxfol},  the mean curvature flow (\ref{mcf}) satisfies 
\begin{equation} 
 \int_{M_{T}}|\nabla^{3}H|^{2}+\int_{0}^{T}(\int_{M_{t}} |\nabla^{4} H|^{2}) dt\leq  ||\nabla^3 H||^2_{L^2(M_0)}+C(E_2^{\frac{4}{3}}+E_1^4)E_2^2,
\end{equation}
and 
\begin{equation} 
    \begin{split}
& \int_{M_{T}}|\nabla^{3}H|^{2}+\int_{\frac{15}{32}T}^{T}(\int_{M_{t}} |\nabla^{4} H|^{2}) dt\\ 
     \leq &C(E_2^{\frac{4}{3}}+E_1^4+T^{-1})||H||_{L^{p_0}(M_0)}^2\{(||H||_{L^{p_0}(M_0)} E^{\frac{1}{2}}_1E^{\frac{1}{2}}_2{T^{-\frac{3}{2p_0}}}+T^{-1} + E_1^4) \\
&\times( E_1^2T^{1-\frac{3}{p_0}}+ T^{\frac{1}{2}-\frac{3}{p_0}})+ E_1^3E_2 T^{1-\frac{3}{p_0}}\}+C E_1E_2^3||H||_{L^{p_0}(M_0)}^2T^{1-\frac{3}{p_0}}\\
&+C(E_1^2E_2^2+E_2^{\frac{8}{3}})||H||_{L^{p_0}(M_0)}^2( E_1^2T^{1-\frac{3}{p_0}}+T^{\frac{1}{2}-\frac{3}{p_0}}).
    \end{split}
\end{equation}

