body:
[Lemma 14 (Survival along a sequence of stars) of arXiv:2604.00630, 'The contact process on a bipartite spatial network'] Let~$G$ be a bipartite graph. Let~$(x_k)_{k\ge 0}$ and~$(y_k)_{k \ge 1}$ be sequences of vertices of~$G$ such that:
	\begin{itemize}
		\item $(x_k)_{k \ge 0}$ have type 1 and~$(y_k)_{k \ge 1}$ have type~2, with
	\[
x_0 \sim y_1 \sim x_1 \sim y_2 \sim x_2 \sim \cdots;
	\]
\item the sequence~$(x_k)_{k\ge 0}$ has infinitely many distinct elements.
	\end{itemize}
	Then, the contact process on~$G$ with rates~$\lambda_1,\lambda_2$ and~$x_0$ initially infected survives forever with probability at least
	\begin{equation*}
		1-\sum_{k=0}^\infty ((\varepsilon \lambda_1 \lambda_2 \deg(x_k))^{-1/2} + \exp\{-c\lambda_1 \lambda_2^2 \lfloor \exp(\varepsilon \lambda_1 \lambda_2 \cdot \deg(x_k)) \rfloor \}),
	\end{equation*}
	where~$\varepsilon > 0$ is the constant of Lemma~\ref{lem_main_star} and~$c > 0$ is a constant not depending on~$\lambda_1,\lambda_2$.

[Definition fixptfun of arXiv:2605.06887, 'Law of large numbers for activated random walk on villages'] Define the function $\phi:\mathbb{R}_+^{V} \rightarrow{\mathbb{R}^{V}}$ as follows: for $m \in \mathbb{R}_+^{V}$ and $x \in V$, set
\begin{equation} 
     \phi(m)_x = (\sigma_x - \frac{\lambda_x}{1+\lambda_x})\left( 1-e^{-\beta(m)_x}\right) + \beta(m)_x
\end{equation}
We call $\phi$ the fixed point function of the VARW model.

[Lem branching_rate_upper_bound of arXiv:2506.10623, 'Polynomial slowdown in an angle-dependent 2d branching Brownian motion'] There exists $\sigma,L > 0$ such that, for any $0 \leq s_0 \leq t$,  on the event $\{ \forall s \in [s_0,t], X_s \leq \sqrt{2} s \text{ and } \mathopen{}\mathclose\bgroup\originalleft\lvert\theta_s\aftergroup\egroup\originalright\rvert < \sigma \}$ as well as on the event $\{ \forall s \in [s_0,t], X_s \leq \sqrt{2} s \text{ and } \mathopen{}\mathclose\bgroup\originalleft\lvertY_s\aftergroup\egroup\originalright\rvert < \sigma s \}$, we have

	\begin{equation*}
	\forall s \in [s_0,t], \quad b(\theta_s) \leq 1 - \beta \abs{\frac{Y_s}{\sqrt{2} s}}^\alpha (1+f(Y_s,s)),
	\end{equation*}
    where $f = f^-_{L,2-\alpha,1} = - \bigl( \bigl[ L \bigl( \abs{\frac{y}{s}}^{2-\alpha} + s^{-1} \bigr) \bigr] \wedge \zeta \bigr)$ where $\zeta \in (0,1/2]$ is chosen in (equation eq:def_f_-_+ of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop: general approximation bound for numerics of arXiv:2605.28770, 'Cutoff profiles for conjugacy invariant random walks on symmetric groups'] Let $n\geq 3$ and $t\geq 0$. Then
    \begin{equation}
         \left| \textup{d}^{(n)}(t) - \frac{(n-1)}{e}\left( \frac{n-3}{n-1} \right)^t\right| \leq \varepsilon^{(n)}(t),
    \end{equation}
where 
\begin{equation}
     \varepsilon^{(n)}(t) = \left( \sum_{r=2}^{\left\lfloor (n-1)/2\right\rfloor} n^r \left( 1 - \frac{2r(n-r+1)}{n(n-1)}\right)^{t}\right)+ \frac{\sqrt{p(n)n!}}{2^{t+1}} + \frac{1}{(n-2)!}.
\end{equation}

[Lemma lem:pathwise_boundedness of arXiv:2608.27313, 'A Finite Sample Analysis for Quantile Temporal Difference Learning in Distributional Reinf'] Let
\begin{equation*}
    B\coloneq\frac1{1-\gamma},
    \qquad
    \Delta\coloneq\frac{c}{1-\gamma}.
\end{equation*}
If $\bm\theta^{(0)}\in[0,B]^{{\mathcal{S}}\times[m]}$, then, almost surely,
\begin{equation}
    \bm\theta^{(t)}\in[-\Delta,B+\Delta]^{{\mathcal{S}}\times[m]}
    \qquad\text{for every }t\ge0.
\end{equation}
Consequently,
\begin{equation}
    \norm{\bm\theta^{(t)}-\bm\theta_m}_\infty
    \le\frac{1+c}{1-\gamma}
    \qquad\text{for every }t\ge0.
\end{equation}

[Lemma le:chineq of arXiv:2506.17168, '{\bf Scaling limits for sample autocovariance operators of Hilbert space-valued linear pro'] The function $c(r,s)$ in (equation equality_beta of the paper) can be bounded from above as
\begin{equation} 
c(r,s)\leq\frac{1}{d(r)}+\frac{1}{1-d(r,s)}
\end{equation}
for $d(r,s)=d(r)+d(s)$ and $d(s) \in (0,\frac{1}{2})$.

