[Theorem thm:allminors of arXiv:2609.01672, '\textbf{All-Minors Matrix-Tree Theory for Superport Networks:\\ Completed Quotient-Inciden'] Let \(I,J\subseteq N\) with \(|I|=|J|=k\), and put \(r=q-k\). Then
\begin{equation}
\boxed{
\det L[I,J]
=\frac{1}{\Phi_{\mathrm{valid}}}
\sum_{F\in\mathcal{F}_{r+1}}
\widehat\chi_F(I)\widehat\chi_F(J)w(F).}

\end{equation}
For every forest,
\begin{equation}
\boxed{\alpha_F(I,J):=\widehat\chi_F(I)\widehat\chi_F(J)\in\{0,+1,-1\}.}

\end{equation}
The coefficient is nonzero exactly when both complementary port-edge sets \(N\setminus I\) and \(N\setminus J\) are spanning trees of \(H_F\).

[Lemma thm012104-26 of arXiv:2606.07353, 'The Gaussian structure of a perturbed KPZ'] Assume (equation V00 of the paper) and $t>0$. Then, for any $q\in(1,+\infty)$
we have
  \begin{equation}

\int_{\mathrm{H} }\exp\Big\{q\widetilde{\mathcal X}_t(V, u
      )
   \Big\} \nu(du)=\exp\left\{\frac
{tq(q-1)}2
\|V\|_{L^2(\mathbb{T})}^2\right\}<+\infty.
\end{equation}
In addition, $F\in L^p(\nu)$, where
  $p\in(1,+\infty)$, we have 
\begin{equation}
\begin{aligned}
&{\mathcal P}_t^VF(u)  =
   \mathbf{E} \Big[
  F\big(\tilde u(t ;u)\big) \exp\Big\{\widetilde{\mathcal X}_t(V, u
      )
   \Big\}\Big],\quad \nu \mbox{ a.s. in $u$.}
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition rk:sym of arXiv:2508.21055, 'Modern aspects of Markov chains:\\entropy, curvature and the cutoff phenomenon'] The \red[Dirichlet form] is the quadratic form on $L^2$ defined by
\begin{eqnarray*}
\mathscr {E}(f,g) & := & \langle f,-Lg\rangle \ = \ \sum_{x\in\mathbb{X}}\pi(x)T(x,y)f(x)\left(g(x)-g(y)\right).
\end{eqnarray*}
When $T^\star=T$ or  $f=g$, we also have the useful symmetrized expression
\begin{eqnarray}

\mathscr {E}(f,g) & = & 
\frac{1}{2}\sum_{(x,y)\in\mathbb{X}^2}\pi(x)T(x,y)\left(f(x)-f(y)\right)\left(g(x)-g(y)\right).
\end{eqnarray}

[Theorem eq:HRPalm of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For all measurable and non-negative $f$
\begin{equation}
\mathbb E_{{\mathcal V }}^0 [f({\mathcal H })] = \pi \lambda^{\frac 3 2}
\int_{(\mathbb{R}^+)^3}
\mathbb{E}_{\mathcal H }\left[ {\mathds{1}}_{{\mathcal H }\left(U^{\hat{s}(0,h,-t',h')}_{\hat{h}(0,h,-t',h')}\right)=0}
f \left(\theta_{\hat{s}(0,h,-t',h')}           \left({\mathcal H }+\delta_{(0,h)}+\delta_{(-t',h')}\right)\right)\right] {\rm d} t'{\rm d} h'{\rm d} h.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 7 of arXiv:2606.05430, 'On a random matrix proof of\\ a bipartite Harer-Zagier formula'] Let $n$ be a non-negative integer. We call $F_n^+$ and $F_n^-$ the rising and falling factorial, defined as
        \begin{align*}
        F_n^+(X) & = X(X+1)\cdots(X+n-1) \\
        F_n^-(X) & = X(X-1)\cdots(X-n+1) = (-1)^n F_n^+(-X).
        \end{align*}
        By convention we denote $F_0^+ = F_0^- = 1$. Note that by definition $F_n^+$ and $F_n^-$ are polynomials of degree $n$.

[Lemma 18 (Polynomial convolution) of arXiv:2607.13210, 'Punctured Wilson--Evolving Sets and Root Identities for Massive Kirchhoff Forests'] Assume \eqref{eq:intro-volume-growth} with $\nu>4$, and put for $x,y$ in $V$:
\begin{equation*}
  k(x,y):=(1+d_G(x,y))^{2-\nu}.
\end{equation*}
For every fixed $c>0$, there exists $C<\infty$, depending only on
$c$, $C_V$ and $\nu$, such that, for every $x,y\in V$ and
$0<q\leq1$,
\begin{equation}
  \sum_{z\in V}
  k(x,z)e^{-c\sqrt q\,d_G(x,z)}
  \leq
  \frac{C}{q},
\end{equation}
and
\begin{equation}
  \sum_{z\in V}k(x,z)k(y,z)
  \leq
  C(1+d_G(x,y))^{4-\nu}.
\end{equation}

