body:
[Lm 13 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] The functions defined by \eqref{eq:Q-kernel},\eqref{eq:p-kernel} and \eqref{eq:R-kernel} satisfy the following recurrence relations
	\begin{align}
        \begin{split}
    		Q_{i+1,j}(x_{i},x_{j}) & = \sum_{y_i\geq x_i} Q_{i,j}(y_i,x_j), \\
    		Q_{i,j+1}(x_{i},x_{j}) & = \sum_{y_j\geq x_j} Q_{i,j}(x_i,y_j), \\
    		U_{k+1}(z) & = \sum_{y\geq z} U_{k}(y), \\
    		p_{k+1}(z) & = \sum_{y\geq z} p_k(y).
        \end{split}
	\end{align}

