[Prp prpAppExpEst_LDP of arXiv:2607.29423, 'Schwarzian Field Theory at High Temperatures'] There exists $C>0$ such that for any $\sigma>0$, any $s, t\in \mathbb{T}$ such that $t\neq s\in \mathbb{T}$,
and any $\lambda\in [-C^{-1}, C^{-1}]$, we have
\begin{multline}
\int \exp\left\{\frac{2\lambda}{\sigma^2} \left(\obs{\phi}{0}{t} -\frac{1}{t}\right)\right\}\mathop{}\!\mathrm{d} \mathscr{M}_{\sigma^2}(\phi) \\
\leq
\frac{\sqrt{2}}{\sqrt{\pi t}\sigma}
\int_{\mathbb{R}_+^2}
\exp\left\{ -\frac{\alpha^2}{2t\sigma^2}
+ \frac{C_1|\lambda|(\alpha^2+ |\lambda|)}{2t\sigma^2}
\right\}
\exp\left(-\frac{(1-t)\sigma^2}{2}\cdot k_2^2\right)
\sinh(2\pi k_2)\, 2k_2 \mathop{}\!\mathrm{d} k_2
\mathop{}\!\mathrm{d} \alpha.
\end{multline}

[Theorem thm:transport of arXiv:2607.24705, 'Derangetropy Operators'] Let $f_{0} \in \mathcal{D}_{+}^{2}$ and let $f_{t}$ solve the
		canonical flow~(equation eq:flow of the paper), with inverse transport
		$B_{t} = A_{t}^{-1}$ given in the coordinate
		$V(z) = \tan(\pi(z - \tfrac12))$ by
		\begin{equation}
			V\circ B_{t} = e^{-t}\,V,
			\qquad
			B_{t}'(z) = \frac{e^{-t}\big(1 + V(z)^{2}\big)}
			{1 + e^{-2t}V(z)^{2}}.

		\end{equation}
		Then the Schwarzian of the transport satisfies
		\begin{equation}
			\{B_{t}, z\} = 2\pi^{2}\big(1 - (B_{t}')^{2}\big),

		\end{equation}
		and the potential evolves by
		\begin{equation}
			\mathfrak{U}_{t}
			= \big(\mathfrak{U}_{0}\circ B_{t}\big)\,(B_{t}')^{2},
			\qquad
			\mathfrak{U} := U - 2\pi^{2}:

		\end{equation}
		relative to the canonical background, the flow transports the
		centered potential as a plain quadratic differential, with no
		Schwarzian anomaly. The same holds for every element of the isotropy
		group of Theorem~(thm:exceptional of the paper).

