[Theorem thm:TLC_Holder of arXiv:2605.30999, 'Functional central limit theorems for $U$-statistics of $\beta$-mixing data'] Let $\alpha\in\left(0,1/2\right)$ and define $p\left(\alpha\right):=\left(1/2-\alpha\right)^{-1}$. 
Suppose that (equation eq:condition_sur_beta of the paper) is satisfied as well as the the following conditions:
\begin{equation}
    \lim_{s\to +\infty} s^{p\left(\alpha\right)-1}
    \int_0^1 Q_{h_1\left(X_0\right)}\left(u\right)\mathbf{1}\ens{\alpha^{-1}\left(u\right)Q_{h_1\left(X_0\right)}\left(u\right) >s}du=0
\end{equation}
\begin{equation}
    \lim_{t\to +\infty }t^{p\left(\alpha\right)}\max_{k\in \llbracket 1,m\rrbracket }\sup_{\bm{i}\in \operatorname{Inc}^k}
    \mathbb P\pr{\abs{ H_{\bm{i},k}}>t }=0.
\end{equation}
Then the following convergence in distribution takes place: 
 \begin{equation*}
 \pr{ \frac{\sqrt{n}}{\binom nm}\pr{W_{m,n}\left(h,t\right)-\E{W_{m,n}\left(h,t\right)}} }_{0\leqslant t\leqslant 1}
     \to \pr{m\sigma t^{m-1}B_t}_{0\leqslant t\leqslant 1}\mbox{ in }\mathcal{H}_\alpha \left([0,1]\right),
 \end{equation*}
 where $\left(B_t\right)_{0\leqslant t\leqslant 1}$ is a standard Brownian motion and $\sigma^2$ 
 is given by (equation eq:definition_de_sigma of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition proposition_bootstrap_gamma_derivatives of arXiv:2609.00973, 'The Vlasov-Maxwell point charge system : study of the spherically symmetric case'] Let $\delta \leq \frac{1}{44}$. Assume that for all $\omega\in \mathcal{I}$
    \begin{equation*}
        \|(a^{-24}+a^{24}+|\theta|^{8}+\ell^{16})\gamma(T_0)\|_{L^1}+\|\omega^{(1)}\gamma_\theta(T_0)\|_{L^1}+\|\omega^{(2)}\gamma_a(T_0)\|_{L^1}\leq \varepsilon_0,
    \end{equation*}
    and for all $t\in[T_0,T]$,
    \begin{equation}

        \|(a^{-24}+a^{24}+|\theta|^{8}+\ell^{16})\gamma(t)\|_{L^1}\leq \varepsilon_1t^\delta,\qquad \|\omega_{d,n,q}^{(1)}\gamma_\theta(t)\|_{L^1}+\|\omega_{d,n,q}^{(2)}\gamma_a(t)\|_{L^1}\leq \varepsilon_1 t^{(d+1)\delta}
\end{equation}
    If $C\varepsilon_0\leq \delta$, where $C$ is a constant that depends only on $m$ and $T_0$, then the stronger bounds hold 
    \begin{equation*}
        \|(a^{-24}+a^{24}+\ell^{16})\gamma(t)\|_{L^1}\lesssim \varepsilon_0,\qquad \| |\theta|^{8}\gamma(t)\|_{L^1}\lesssim (\varepsilon_0+\varepsilon_1)t^{C\varepsilon_0}, 
    \end{equation*}
    \begin{equation}

        \|\omega^{(1)}_{d,n,q}\gamma_\theta(t)\|\lesssim \varepsilon_0+\frac{\varepsilon_1(\varepsilon_0+\varepsilon_1)}{\delta} t^{d\delta},\quad \|\omega^{(2)}_{d,n,q}\gamma_a(t)\|\lesssim \varepsilon_0+\frac{\varepsilon_1(\varepsilon_0+\varepsilon_1)}{\delta^2}t^{(d+1)\delta}.
    \end{equation}

