body:
[Definition 28 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] \begin{trivlist}
\item[(o)] $C([0,T];\StokesH_{,w}) \coloneqq$ the space of continuous functions $\bv: [0,T] \to \StokesH_{,w}$ endowed with the weakest topology $\mathscr{Z}_0$ such that for all $\bv \in \StokesH$, the mappings
     \begin{equation*}
        C([0,T];\StokesH_{,w}) \ni \bu \mapsto (\bu(\cdot),\bv) \in C([0,T];\mathbb{R}) \; \; \text{are continuous}.
     \end{equation*}
In particular, $\bv_n \to \bv$ in $C([0,T];\StokesH_{,w})$ if and only if 
   \begin{equation*}
      \lim_{n \to \infty} \sup_{t \in[0,T]} \lvert (\bv_n(t) - \bv(t),\bw) \rvert=0, \;\; \mbox{for all $\bw \in \StokesH$.}
    \end{equation*}
    Since the space $\StokesH_{,w}$ is not metrizable and the space $C([0,T];\StokesH_{,w})$ contains $\StokesH_{,w}$ as a closed subspace via the constant maps, 
we infer that the  topology   $\mathscr{Z}_0$ is not metrizable. 
\item[(i)] $C([0,T];\rU_0^\prime)\coloneqq$ the space of continuous functions
$\bv: [0,T] \to \rU_0^\prime$ 
endowed with  the topology $\mathscr{Z}_1$ induced by the $\sup$ norm, i.e. the topology of  the uniform convergence on $[0,T]$, 

\item[(ii)] $L_w^2(0,T;\StokesV)\coloneqq$ the Hilbert space $L^2(0,T;\StokesV)$ endowed with the weak topology $\mathscr{Z}_2$. In particular,  $\bv_n \to \bv$ in $L_w^2(0,T;\StokesV)$ if and only if  for all $\bw \in L^2(0,T;\StokesVp)$,
     \begin{equation*}
       \lim_{n \to \infty} \int_0^T \duality{\bw(s)}{\bv_n(s) - \bv(s)}{\StokesV}{\StokesVp} \, \d s=0.
    \end{equation*}    
We can verify as above that the topology $\mathscr{Z}_2$ is not metrizable either.

\item[(iii)] $C([0,T];\newone{H}_{,w})\coloneqq$ the space of  continuous functions $\bv: [0,T] \to \newone{H}_{,w}$ endowed with the topology $\mathscr{Z}_3$ defined as in item (o).

\item[(iv)] $C([0,T];\newonep{V})\coloneqq$  the space of $\newonep{V}$-valued trajectories with the topology $\mathscr{Z}_4$ of the uniform convergence on $[0,T]$. $C([0,T];\newonep{V})$  is a separable Banach space.

\item[(v)] $L_w^{\beta}(0,T;\newone{V})\coloneqq$ the space $L^\beta(0,T;\newone{V})$ with the weak topology $\mathscr{Z}_5$.

\item[(vi)] The separable Hilbert space $L^2(0,T;\StokesH)$ with the topology $\mathscr{Z}_6$  induced by the norm. 

\item[(vii)] The separable Hilbert space $L^\beta(0,T;\newone{H})$ with the topology $\mathscr{Z}_7$  induced by the norm.
\end{trivlist}

[Definition 72 (The first fundamental forms of $\doublenulltoritwoarg{\ubar}{u}$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] \hfill
\begin{itemize}
	\item We define the \emph{first fundamental forms of} $\doublenulltoritwoarg{\ubar}{u}$ relative to $\gfour$ to be the symmetric type $\binom{0}{2}$ tensorfield $\gnulltori$ such that $\gnulltori(Y,Z) = \gfour(Y,Z)$ for all pairs of vectorfields tangent to $\doublenulltoritwoarg{\ubar}{u}$ and such that $\gnulltori(V,\cdot) = \gnulltori(\cdot,V) = 0$ if $V$ is $\gfour$-orthogonal to $\doublenulltoritwoarg{\ubar}{u}$. 
	\item We define the \emph{inverse first fundamental form} $\gnulltori^{-1}$ to be the dual of $\gnulltori$ relative to $\gfour$, i.e., relative to arbitrary coordinates, it is the symmetric type $\binom{2}{0}$ tensorfield wit the following components:
	\begin{equation}  
		(\gnulltori^{-1})^{\alpha\beta} = (\gfour^{-1})^{\alpha\gamma} (\gfour^{-1})^{\beta\delta} \gnulltori_{\gamma\delta}.
	\end{equation}
\end{itemize}

[Proposition prop:duality of arXiv:2607.22991, 'Mixing times and spectra of non-equilibrium symmetric exclusion processes on general graph'] For any subset of sites $\{v_1,\ldots,v_k\}\subset V$, the SEP process~$\sigma_t$ 
and its dual~$\hat\sigma_t$ are related as follows:
\begin{equation*}
   \Pr[\sigma_t(v_1,\ldots,v_k)=(z_1,\ldots,z_k)] = 
   \Pr[\hat\sigma_t(v_1,\ldots,v_k)=(z_1,\ldots,z_k)]\quad\forall (z_1,\ldots,z_k)\in(\{0,1\}\cup V)^k.  
\end{equation*}

