[Thm t:2.1o of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] \begin{equation}
\lim_{\delta \downarrow 0} \limsup_{n \to \infty}
\mathbb{P} \Big(\frac{1}{\sqrt{n}} \big|{\mathbf W}_n(0)\big| \notin \big(\delta, \delta^{-1} \big) \Big) = 0 \,.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition proposition_RL_functions of arXiv:2605.26804, '\Large Large Deviation Principle for the Empirical Measures of Simple Random Walks on $\ov'] Let $m \in \mathbb{Z}$ and suppose that for all $\mu \in \mathcal{P}(\overline{\mathbb{Z}})$,
\begin{align}
-I(\mu)\leq &\lim \limits_{\varepsilon \to 0^+} \liminf \limits_{n \to \infty} \frac{1}{n} \log \mathbb{P}_m \big( \ell_n \in B(\mu,\varepsilon) \big), \qquad \qquad \qquad \qquad \qquad \qquad \\
\text{and} \qquad \qquad \qquad \qquad \quad  &\lim \limits_{\varepsilon \to 0^+} \limsup \limits_{n \to \infty} \frac{1}{n} \log \mathbb{P}_m \big( \ell_n \in B(\mu,\varepsilon) \big) \leq -I(\mu).
\end{align}
Then, the sequence $(\ell_n)_{n \in \mathbb{N}}$ satisfies under $\mathbb{P}_m$ a full LDP with rate function $I$.

