[Definition defn:nvali of arXiv:2411.10586, 'A convergence framework for Airy$_\beta$ line ensemble\\ via pole evolution'] For ${\mathfrak d},C_*>0$, a Nevanlinna function $Y$ is \emph{$({\mathfrak d}, C_*)$-Airy-like}, or simply \emph{Airy-like}, if 
\begin{enumerate}
\item  it is particle-generated, and all the poles are $\le C_*$;
\item  for all $w$ with ${\rm Im}[w]\geq C_*\sqrt{{\rm Re}[w]\vee 0+1}$,
\begin{align}
|Y(w)-\sqrt{w}|\leq \frac{C_*{\rm Im}[\sqrt{w}]^{1-{\mathfrak d}}}{{\rm Im}[w]}.
\end{align}
\end{enumerate}

[Lem 95 of arXiv:2609.01389, 'K-stability and birational rigidity of Fano 3-fold weighted complete intersections'] We have $H|_S = \Gamma + \Delta$, where $\Gamma$ and $\Delta$ are irreducible and reduced curves satisfying the following properties.
\begin{enumerate}
\item The curve $\Gamma$ is quasismooth, $\msp \in \Gamma$ and $\msp \notin \Delta$.
\item $(\Gamma^2) = - 7/12$, $(\Delta^2) = -1/4$ and $(\Gamma \cdot \Delta) = 3/4$.
\end{enumerate}

[Corollary 22 (Wendel--Stirling mixtures) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] For $n\geq 1$ and $d\geq 0$,
\begin{equation}
    \pwalk{n}{d}
    =\mathbb E\left[\pwend{K_n}{d}\right]
    =\frac{1}{n!}\sum_{k=d+1}^{n}
        \stirling{n}{k}\pwend{k}{d}.

\end{equation}
For $n\geq 2$ and $d\geq 0$,
\begin{equation}
    \pbridge{n}{d}
    =\mathbb E\left[\pwend{K_{n}^{\mathrm{br}}}{d}\right]
    =\frac{1}{n!}\sum_{k=d+1}^{n-1}
        2^k\stirling{n-1}{k}\pwend{k}{d}.

\end{equation}

[Lem cA7 of arXiv:2504.07255, 'A Tail-Respecting Splitting Numerical Scheme\\ for L\'evy-Driven SDEs With Superlinear Dri'] For any $q\in(0,p)$,
there exists $C\in(0,\infty)$ such that
\begin{equation}\begin{aligned}
\sup_{t\in[0, T]}\mathbf{E}^{(N)}_{t_1,\dots,t_N}\Big[\|\Delta_t^n\|^q\Big]
\leq C^{N+1}h_n^{\frac{p-q}{\chi}\wedge q}(1+2\|x\|^{p})+ (2N+1)C^{N+1}
\end{aligned}\end{equation}
for $n$ large enough uniformly over
$N\in\mathbb{N}_0$ and $N$-tuples $\{t_1,\dots, t_N\}\subset (0,T)$.

