[Theorem int:polynomial-volume-scalar-mass of arXiv:2608.30779, 'Some uniform estimates for K\"ahler--Ricci Shrinkers'] Let \(X\in \mathcal{KRS}(n,k)\), where \(k\in\{1,\ldots,n\}\). Then the
following hold.
\begin{enumerate}
    \item For all sufficiently large \(s\), the function
    \[
        s\longmapsto \operatorname{Vol}\{\rho^2<s\}
    \]
    agrees with a polynomial of degree \(k\) with positive leading
    coefficient.

    \item One has
    \[
        0<
        \lim_{r\to\infty}
        \frac{\operatorname{Vol}_g B_g(p,r)}{r^{2k}}
        <\infty,
        \qquad
        \lim_{r\to\infty}
        \frac{\int_{B_g(p,r)} R_\omega\,\omega^n/n!}
             {\operatorname{Vol}_g B_g(p,r)}
        =n-k.
    \]

    \item If \(k=n\), then the limit
    \[
        \lim_{r\to\infty}
        r^{2-2n}
        \int_{B_g(p,r)} R_\omega\,\frac{\omega^n}{n!}
    \]
    exists and is positive unless \(X\) is Gaussian.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:subgamma of arXiv:2609.01581, 'Concentration of additive functionals of Stratonovich-type'] Let $\tilde\sigma^2 > 0$ and $c > 0$. 
Consider the convex function on $[0, 1/c)$
\begin{align}
\phi(k) = \frac{k^2\tilde\sigma^2}{2(1 - ck)}.
\end{align}
Its Legendre transform $\phi^\ast(a)$ is, for $a > 0$,
\begin{align}
  \phi^\ast(a)
  \equiv \sup_{0 \leq k < 1/c}\left[ka - \frac{\tilde\sigma^2 k^2}{2(1 - ck)}\right]
  = \frac{\tilde\sigma^2}{c^2}h\left(\frac{c a}{\tilde\sigma^2}\right),

\end{align}
with supremum attained at $k^\ast = c^{-1}\bigl(1 - \sqrt{\tilde\sigma^2/(\tilde\sigma^2 + 2ca)}\bigr) > 0$
and we define the auxiliary function $h(u) \equiv 1 + u - \sqrt{1 + 2u}$.
Moreover, we have $h(u) \geq u^2/[2(1+u)]$ for $u \geq 0$, i.e.,
\begin{align}
  \phi^\ast(a) \geq \frac{a^2}{2(\tilde\sigma^2 + ca)}.

\end{align}

[Lemma lem:entropy of arXiv:2608.07410, 'Extreme least singular values of random row submatrices\\ with bounded-density subgaussian'] Suppose $n_m/m\to\beta>1$ and let
\[
L_m:=\binom{n_m}{m-1}.
\]
Then
\begin{equation}
\frac1m\log L_m\longrightarrow h(\beta).
\end{equation}
Moreover, for every $\alpha\in(0,h(\beta))$ there are constants $\delta_0,\kappa>0$ such that, for all
sufficiently large $m$,
\begin{equation}
\frac1{L_m}
\sum_{1\le k\le\lfloor\delta_0m\rfloor}
\binom{m-1}{k}\binom{n_m-m+1}{k}
\le e^{-(\alpha+4\kappa)m}.
\end{equation}

[Definition of arXiv:2505.10256, 'Stochastic Oscillators out of equilibrium:\\ scaling limits and correlation estimates'] Let $\{\mu_N\}_{N\in\mathbb N}$ be a sequence of probability measures in $\Omega_N$ and let $v_0$ and $e_0$ be measurable real-valued functions defined on $\mathbb T$.
We say the sequence $\{\mu_N\}_{N\in\mathbb N}$ is associated to $(v_0,e_0)$ if for every real-valued continuous function $G$ on $\mathbb T$ and for every $\delta>0$ we have that 
\begin{equation*}
\lim_{N\to\infty}\mu_N\bigg( \eta\in\Omega_N \,;\,  
\Big| \frac{1}{N} \sum_{x\in\mathbb T_N} \eta(x) G\Big(\frac xN\Big) - \int_{\mathbb{T}}G(u)v_0(u)du \Big| > \delta\bigg) =0
\end{equation*}
and 
\begin{equation*}
\lim_{N\to\infty}\mu_N\bigg( \eta\in\Omega_N \,;\,  
\Big| \frac{1}{N} \sum_{x\in\mathbb T_N} \eta(x)^2 G\Big(\frac xN \Big) - \int_{\mathbb{T}}G(u)e_0(u)du \Big| > \delta\bigg) =0.
\end{equation*}

