[Lemma 14 (Stopped estimates) of arXiv:2608.16256, 'Error Distribution of the Local Linearization Method for Stochastic Differential Equations'] \label[lemma]{le:ll_stopped_int_l2}
For every \(\rho>0\), there exists \(C_\rho<\infty\) such that, for
\(p=2,4\),
\begin{equation}
    \Exp*{}{
        \sup_{s\in I_m^n}
        \left|
            \hat X^n_{s\wedge\tau_{n,\rho}}
            -
            \hat X^n_{t_{m-1}^n\wedge\tau_{n,\rho}}
        \right|^p
    }
    \le
    C_\rho n^{-p/2}.
\end{equation}
Moreover,
\begin{equation}
    \Exp*{}{
        \int_0^{\tau_{n,\rho}}
        |\hat X_s^n-\hat X_{\varphi_n(s)}^n|^2\,ds
    }
    \le
    C_\rho n^{-1},
\end{equation}
\begin{equation}
    \Exp*{}{
        \left(
            \int_0^{\tau_{n,\rho}}
            |\hat X_s^n-\hat X_{\varphi_n(s)}^n|^2\,ds
        \right)^2
    }
    \le
    C_\rho n^{-2},
\end{equation}
and
\begin{equation}
    \Exp*{}{
        \sup_{t\le1}
        |X_{t\wedge\tau_{n,\rho}}-
        \hat X^n_{t\wedge\tau_{n,\rho}}|^2
    }
    \le
    C_\rho n^{-3} .
\end{equation}
Consequently,
\begin{equation}
    \Exp*{}{
        \int_0^{\tau_{n,\rho}}|X_s-\hat X_s^n|^2\,ds
    }
    \le
    C_\rho n^{-3},
\end{equation}
and, for \(m=0,\dots,n\),
\begin{equation}
    \Exp*{}{
        |X_{t_m^n\wedge\tau_{n,\rho}}
        -\hat X^n_{t_m^n\wedge\tau_{n,\rho}}|^2
    }
    \le
    C_\rho n^{-3} .
\end{equation}

[Lemma 38 of arXiv:2604.04823, '2604.04823'] There exists a dimensional constant~$\hat c_d>0$ such that for any~$\epsilon > 0$ and~$h \in (0,1]$,  
   \begin{equation}
        \gap(T_{h, \epsilon})\geq \hat c_d\exp\paren*{-\frac{2\norm{U}_{L^\infty}}{\epsilon} }h^2 \,.
    \end{equation}
    Here, $T_{h, \epsilon}$ is the lazy Metropolis random walk with step size~$h$ and stationary density~$\pi_\epsilon$, defined as in~\eqref{e:Thpi-def}.

