    \begin{equation*}
        \nabla_x u(\cdot,\cdot)\in L^\infty([0,T]\times \mathbb{R}^d)+L^2([0,T];L^2(\mathbb{R}^d))\subset L^2([0,T];H^1_{\sf loc}(\mathbb{R}^d)), \quad T>0.
    \end{equation*}

