[Corollary 9 of arXiv:2609.02581, '\bfseries Interior Curvature Estimates for the Graphical Scalar Curvature Equation in All '] Under the assumptions of Proposition~\ref{prop:jacobi}, with
\(I\) defined by
\eqref{def:good-bad-directions}, we have
\begin{equation}
 \sum_i\Theta_iT_u^{ii}b_i^2
 \geq
 \frac12\sum_{i\in I}T_u^{ii}b_i^2
 -\frac{n-4}{n}
  \sum_{i\notin I}T_u^{ii}b_i^2.
\end{equation}
Moreover,
\begin{equation}
 T_u^{ij}h_i^kh_{kj}\geq\frac{H^2}{64}
 \sum_{i\notin I}T_u^{ii}.
\end{equation}
Consequently, \eqref{eq:jacobi} implies
\begin{equation}
 \Delta_{T_u}b
 \geq
 H-T_u^{ij}h_i^kh_{kj}
 +\frac12\sum_{i\in I}T_u^{ii}b_i^2
 -\frac{n-4}{n}
  \sum_{i\notin I}T_u^{ii}b_i^2.
\end{equation}

[Theorem 3 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] For every fixed $k\in {\mathbb Z}$, as $n\to\infty$,
\begin{align}
{\mathbb P}[M_n-b_n\leq k]&=\int_{-\infty}^\infty p_\ell(e^{-s}) e^{-s} \exp\left(- e^{(e-1)s+c_n-k}\right)
{\rm d}s+o(1)
\\\nonumber
&= \frac{1}{\ell!}
\int_{-\infty}^\infty\exp\left(- e^{-s} -(\ell+1)s- e^{(e-1)s+c_n-k}\right)
{\rm d}s+o(1).
\end{align}
\nopf (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop spec-frag-transient of arXiv:2511.10223, 'Stochastic Reaction Networks Within Interacting Compartments with Content-Dependent Fragme'] Let $N$ be the coarse-grained model associated with (equation eq:specific-content-dependent-fragmentation of the paper)
\begin{equation*}
\begin{tikzcd}
    0\arrow[yshift=.5ex]{r}{\kappa_b}& S\arrow[yshift=-.5ex]{l}{\kappa_d} & &
    0\arrow[yshift=.5ex]{r}{\kappa_I}& C\arrow[yshift=-.5ex]{l}{\kappa_E} \arrow[yshift=.5ex]{r}{\kappa_FS_C}& 2C\arrow[yshift=-.5ex]{l}{\kappa_C} & &
    \mu,
\end{tikzcd}
\end{equation*}
where we again assume that condition~(con:lambda finite of the paper) holds, i.e., $\lambda<\infty$. If $(\kappa_F-\kappa_E)\kappa_b>(\kappa_E+\kappa_d)\kappa_E$ and $\kappa_I>0$ and $\kappa_C=0$, then all states are transient for $N$.

[Theorem thm:eigenvalue_comparison of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\phi$ be a Bernstein function such that 
\begin{align}
    \int_0^\infty u^{\frac{Q}{2}-1} e^{-t\phi(u)}du<\infty
\end{align}
for some $t>0$. Then,
\begin{enumerate}[leftmargin=*]
\item $\Delta^{\phi,\Omega}_{\mathcal{H}}$ has purely point spectrum in $L^2(\Omega, dx)$ and the first eigenvalue is strictly larger than $\phi(0)$. Moreover, denoting the eigenvalues of $\Delta^{\phi,\Omega}_{\mathcal H}$ by 
\begin{align*}
\lambda_{1,\phi}\leqslant \lambda_{2,\phi}\leqslant \cdots,
\end{align*}
we have
\begin{align} 
    \lambda_{n,\phi}\leqslant 4\phi(\lambda_n) \quad \mbox{for all $n$},
\end{align}
where $0<\lambda_1\leqslant \lambda_2\leqslant \cdots$ denote the eigenvalues of the Dirichlet sub-Laplacian $\Delta^{\Omega}_{\mathcal H}$. 
\item If $\phi$ is a complete Bernstein function, then 
\begin{align} 
    \lambda_{n,\phi}\leqslant \phi(\lambda_n) \quad \mbox{for all $n$}.
\end{align}
If in addition $\Omega$ satisfies the intrinsic exterior cone condition (see Definition~(def:cone_cond of the paper)), then 
\begin{align} 
    \lambda_{n,\phi}\geqslant c(\Omega)\phi(\lambda_n) \quad \mbox{for all $n$},
\end{align}
where $c(\Omega)>0$ is a constant independent of $n$ and $\phi$, and depends only on $\Omega$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

