\begin{align*}
     \abs{ g_{k,x}(y)}&\leq  \mathcal{U}_5(k,y):=\mathds{1}_{\{y>u\}} C\frac{\sum_{j=0}^{k+1} \left\vert y \right\rvert^j }{\left\vert b(y) \right\rvert^{k+1}\left\vert y-m \right\rvert }
