[Proposition 2 of arXiv:2607.23427, '\textbf{A note on Latała's argument in SK model}'] Suppose that $\rho=\rho(\beta,h)<1$, and set
\begin{equation}
\lambda_*:=\frac{\kappa(q)^{-1}-\beta^2}{4}
=\frac{1-\rho}{4\kappa(q)}.
\end{equation}
For every $N\geq1$ and $t\in[0,1]$,
\begin{equation}
\mathbb E\left[\log \left
\langle
\exp\left(\lambda_* N(R_{12}-q)^2\right)\right\rangle_t \right]
\leq \frac12
\exp\left(\frac{2\rho}{1-\rho}\right)
\log\left(\frac{2}{1-\rho}\right).
\end{equation}

[Theorem thm:WishartDiscrepancy of arXiv:2410.23915, 'Asymptotic Bounds and Online Algorithms for Average-Case Matrix Discrepancy'] Let $W_1,\ldots,W_n$ be a sequence of independent $m \times m$ Wishart matrices with rank $r \leq m$. There exist constants $C_1,C_2 > 0$ such that, for $n \ll m^2$,
        \begin{equation*}
            \lim_{n \to \infty} \P{C_1\sqrt{rnm} \leq \disc(A_1,\ldots,A_n) \leq C_2\sqrt{rm^3}} = 1.
        \end{equation*}
        In particular, when $n = \Theta(m^2)$, we have that $\disc(A_1,\ldots,A_n) = \Theta(\sqrt{rm^3})$ with high probability as $n \to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 11 (Expected Cost and Value Function) of arXiv:2607.03318, 'Continuous Differentiability of the Value Function for Infinite-Dimensional Finite-Horizon'] For a given initial time $t \in [0, T]$, let $\mathcal{T}_{t, T}$ denote the class of all $\F$-stopping times $\tau \colon \Omega \to [t, T]$. The finite-horizon optimal stopping problem is characterized by the following quantities:
\begin{enumerate}[label={(\textit{\roman*})}, leftmargin=*]
    \item \emph{Expected Cost Functional.} For an initial state $x \in H$ and an admissible stopping strategy $\tau \in \mathcal{T}_{t, T}$, the expected cost functional $J \colon [0, T] \times H \times \mathcal{T}_{t, T} \to \R$ is defined by:
    \begin{equation} 

        J(t, x; \tau) := \E \left[ \int_t^\tau f(s, X(s)) \, \mathrm{d}s + \Phi(\tau, X(\tau))\ind_{\{\tau < T\}} + \Psi(X(T))\ind_{\{\tau = T\}} \right],
    \end{equation}
    where $X(\cdot) \equiv X(\cdot; t, x)$ denotes the continuous mild solution of the governing semilinear state equation \eqref{eq:mild_solution_eq}.

    \item \emph{Value Function.} The value function $v \colon [0, T] \times H \to \R$ is defined as the infimum of the expected cost evaluated over the entire class of admissible stopping strategies:
    \begin{equation} 

        v(t, x) := \inf_{\tau \in \mathcal{T}_{t, T}} J(t, x; \tau).
    \end{equation}
\end{enumerate}

[Lemma 14 of arXiv:2605.02713, '2605.02713'] For any $i=1,\dots, n$,
	\begin{align*}
		H_q \left( Z_{i,n} \right) =  \alpha_n^{qi}  H_q \left( Z_{0,n} \right) + R_q  \left( Z_{i,n} \right)
	\end{align*}
	with 
	\begin{align}
		R_q  \left( Z_{i,n} \right) = \sum_{r=0}^{q-1} \binom{q}{r} \alpha_n^{ri} \left( \sqrt{ 1 - \left( \alpha_n^{i} \right)^2 } \right)^{(q-r)}  \hspace{-2mm} H_r \left( Z_{0,n} \right) H_{q-r} \left(   Y_{i,n}  \right) 
	\end{align}
	and $Y_{i,n}=  \sqrt{ \frac{ 1 - \alpha_n^2}{ 1 - \left( \alpha_n^{i} \right)^2}} \displaystyle\sum_{k=1}^{i} \varepsilon_k \, \alpha_n^{i-k}  $.

[Prop variational-representation-chi-square of arXiv:2504.02207, 'Finite-Time behaviors of M/M/$n$ Queue: Mixing Time, Mean Queue Length and Tail Bounds'] Given two distributions $P, Q$ with countable supports and let $\cG_Q$ be a collection of functions $g: \R \rightarrow \R$ such that $\E_Q\sqbr{g(X)^2} < \infty\}$, we have
    \begin{align}

        \chi^2(P,Q) = \sup_{g \in \cG_Q} \frac{\br{\E_P[g(X)]-\E_Q[g(X)]}^2}{\Var_Q[g(X)]}
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 (Uniform sub-Gaussian moments of the nonlinear law) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under Assumptions~\ref{ass:core-target} and \ref{ass:concentration}, together with either kernel assumption, there are $a>0$ and $C<\infty$ such that
\begin{equation}
    \sup_{t\ge0}\int e^{a\|x\|^2}\mu_t(dx)\le C.
\end{equation}

[Lemma 48 of arXiv:2608.27372, 'Universality and sharp thresholds for ellipsoid fitting'] Fix $\kappa>1$. As
	$\alpha\downarrow\alpha_\star(\kappa)$ from above,
	\begin{equation}

		e_\star(\alpha,\kappa)
		=
		\frac{(\alpha-\alpha_\star(\kappa))^2}
		{2\alpha_\star(\kappa)m(\omega_\kappa)^2}
		+o\!\left((\alpha-\alpha_\star(\kappa))^2\right).
	\end{equation}

[Definition 102 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\xi \in W$ be arbitrary. An $W$-valued continuous, adapted process $Y = (Y_t)_{t \in [0,T_0]}$ for some $T_0 \in (0,T]$ is called a \emph{local mild solution} to the SPDE \eqref{SPDE-Wiener} with $Y_0 = \xi$ if
\begin{align*}
Y_t = S_t \xi + \int_0^t S_{t-s} f_0(s,Y_s) ds + \int_0^t S_{t-s} f(s,Y_s) dX_s, \quad t \in [0,T_0].
\end{align*}
If we can choose $T_0 = T$, then we also call $Y$ a \emph{(global) solution} to the SPDE \eqref{SPDE-Wiener} with $Y_0 = \xi$.

[Defn 21 of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] A pair $(u^h,\nu^h)$ is called a kinetic solution of \eqref{eq:skeleton-obstacle-problem} with initial data $u^0$ and obstacle $\psi$ if the following conditions hold.
\begin{enumerate}[label=\textbf{\arabic*}.]
  \item For every $p\geq1$, $u^h\in L^\infty(0,T;L^p(\mathbb T^N))$ and
\begin{align*}
\underset{0\leq t\leq T}{{\rm{ess\,sup}}}\ \Vert u^h(t)\Vert ^p_{L^p(\mathbb{T}^N)} \leq C(p,\Vert h\Vert_{L^2(0,T;U)},T,D_0),
\end{align*}
\item  We have 
\begin{equation*}
u^h(x,t)\geq\psi(x,t),\qquad\text{for } \dd x\otimes\dd t\text{-a.e. } (x,t),
\end{equation*}
and $\nu^h$ is a nonnegative finite Radon measure on $\mathbb{T}^N\times[0,T)$.
\item  The function $u^h$ satisfies the weak initial trace condition
\begin{equation*}
\lim_{\tau\downarrow0}\frac{1}{\tau}\int_0^\tau\Vert u^h(t)-u^0\Vert _{L^1(\mathbb{T}^N)}\dd t=0.
\end{equation*}
\item There exists a (deterministic) kinetic measure $q^h$ such that, with $f:= \one_{\{u^h>\xi\}}$ and $\mu^h:=\delta_{u^h}$, for all $\varphi\in C^1_c(\mathbb{T}^N\times [0,T)\times \mathbb{R})$,
\begin{align}\notag
&\int^T_0\langle f(t), \partial_t \varphi(t)\rangle \dd t+\langle f^0, \varphi(0)\rangle +\int^T_0\langle f(t), a(\xi)\cdot \nabla \varphi (t)\rangle \dd t\\
&= -\sum_{k\geq 1}\int^T_0\int_{\mathbb{T}^N} \int_{\mathbb{R}}g_k(x,\xi)\varphi (x,t,\xi)h_k(t)\dd \mu^h_{x,t}(\xi)\dd x\dd t \\
&\quad + q^h(\partial_{\xi} \varphi)-\int_0^T\int_{\mathbb{T}^N}\varphi(x,t,\psi(x,t))\dd\nu^h(x,t),\nonumber
\end{align}
 where  $\mu^h_{x,t}(\dd\xi)=\delta_{u^h(x,t)}(\dd\xi)$.
\end{enumerate}

[Thm smasympexUN of arXiv:2412.00593, 'A new approach to strong convergence II.\\The classical ensembles'] There is a universal constant $C>0$, and a compactly supported 
distribution $\mu_k$ for every $k\in\mathbb{Z}_+$, such that the following 
hold. Fix any $h\in C^\infty(\mathbb{R})$, and let
$f(\theta):= h(K\cos\theta)$. Then
$$
	\left| \mathbf{E}[\mathop{\textnormal{tr}} h(X^N)]- \sum_{k=0}^{m-1} \frac{\mu_k(h)}{N^k} 
	\right| \leq 
	\frac{(C\tilde q_0)^m}{u^mN^m}
	\|f^{(m'+1)}\|_{[0,2\pi]} 
	+\frac{(C\tilde q_0)^{2m}}{m!\, u^{2m} N^m} 
	\|f^{(2m'+1)}\|_{[0,2\pi]} 
$$
for every $m, N\in \mathbb{N}$ and $u\in (0,1)$, where
$m':=\lceil (1+u)m\rceil$ and $\tilde q_0 := q_0(1+\log q_0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:mass_ex_lvl_set of arXiv:2411.07113, '\begin{LARGE}On differentiability and mass distributions of topologically typical multivar'] Let $C$ be a $d$-dimensional Archimedean copula and $\gamma \in \mathcal{P}_{\mathcal{W}_d}$ its corresponding Williamson measure. Moreover, let $s_1,s_2 \in \mathbb{I}$, with $s_1 \leq s_2$. Then the following assertion holds:
    \begin{equation}
    \mu_C(L_{[s_1,s_2]}) = \gamma\left(\left[\frac{1}{\varphi(s_1)},\frac{1}{\varphi(s_2)}\right]\right).
    \end{equation}

[Corollary cor.uniform-renewal of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] Let $\theta\in(0,1/4)$ and $\varepsilon>0$. There exist a $\mathbb{Q}$-full-probability event $\Omega_{\theta,\varepsilon}$ and a deterministic constant $C=C(\theta,\varepsilon,d,\Lambda,r_0)<\infty$ such that, for every $\omega\in\Omega_{\theta,\varepsilon}$, there exists a finite random scale $\lambda_0(\omega)>0$ with the property that for every $0<\lambda\le\lambda_0(\omega)$ and every $t\ge\lambda^{-2-\varepsilon}$,
		\begin{equation}
			E_0^{\lambda,\omega}|X^\lambda(t)-\ell(\lambda)t|\le C\sqrt t (\lambda^2 t)^\theta\, ,
		\end{equation}
		and
		\begin{equation}
			\widehat E_0^{\lambda,\omega}|A^\lambda(t)-\eta(\lambda)t|\le C\lambda^{-1}\sqrt t (\lambda^2 t)^\theta\, .
		\end{equation}
		Moreover, $\lambda_0$ has polynomial tails of every order: for each $p>0$ there is $C_p=C_p(p,\theta,\varepsilon,d,\Lambda,r_0)<\infty$ such that
		\begin{equation}
			\mathbb{Q}\bigl(\lambda_0\le 2^{-k}\bigr)\le C_p 2^{-pk}\qquad\text{for every integer }k\ge 0\, .
		\end{equation}

