[Lemma lem:gamma-square-ibp-B of arXiv:2605.03718, 'Potential Hessian Ascent III:\\ Sampling the Sherrington--Kirkpatrick Model at $\beta < 1/'] For $t\in(0,1)$,
\begin{equation}

\frac{\beta}{2}t^{-1/2}\,\mathop{{}\mathbb{E}}\,\operatorname{tr}_{N}\!\bigl[\chi_k^2\,B_k\,R\,K_k\,R\bigr]
=
\beta^2\,\mathop{{}\mathbb{E}}\Bigl[
\operatorname{tr}_{N}[\chi_k R]\;\operatorname{tr}_{N}[\chi_k\,R\,K_k\,R]
+\frac{1}{N}\operatorname{tr}_{N}\!\bigl[\chi_k^2\,R^3\,K_k\bigr]
\Bigr]
+\mathrm{Err}_{B,\chi}(t),
\end{equation}
where
\begin{equation}

\mathrm{Err}_{B,\chi}(t)
:=
\frac{\beta}{2}t^{-1/2}\cdot \frac{1}{N^2}\sum_{i,j=1}^{N}
\mathop{{}\mathbb{E}}\left[
\frac{\partial (\chi_k^2)}{\partial (B_k)_{ij}}\;
\bigl[R\,K_k\,R\bigr]_{ji}
\right].
\end{equation}

[Lemma lem: double-connection-trunc of arXiv:2604.08462, 'Convergence of $k$-point functions in\\ high dimensional percolation'] Let $\epsilon > 0$ be fixed. There exists a $C = C(\epsilon) > 0$ such that, for all $1 \leq M \leq K \leq \epsilon n / 2$ and edges $f \in B(M)$, vertices $x_1, x_2 \in F(\epsilon, n)$, we have
\begin{align*}
\wto{\mathbb{E}}[\mathbf{1}_{ 0\Longleftrightarrow \underline{f}, \, 0 \leftrightarrow x_1}\dwt{\mathbb{P}}\big( \, \overline{f}\leftrightarrow x_2 \text{ off } \widetilde{\mathfrak{C}}_{B(2K)}(\underline{f})\big) ]
- \wto{\mathbb{E}}[\mathbf{1}_{ 0\stackrel{B(2K)}{\Longleftrightarrow} \underline{f}, \, 0 \leftrightarrow x_1}\dwt{\mathbb{P}}\big( \, \overline{f}\leftrightarrow x_2 \text{ off } \widetilde{\mathfrak{C}}_{B(2K)}(\underline{f})\big) ] \leq C K^{-2} n^{4-2d}\ .
\end{align*}

