[Ingredient 21 of arXiv:2608.26803, 'On bubbling of Fueter maps'] Let $V$ be a Hausdorff topological vector space, $W$ a Banach space and $j: V \to W$ a continuous linear map with dense image. Let $K$ be a compact smooth manifold of dimension $k$ and let $\cR \subset W$ be Fredholm $C^1$-rectifiable of codimension $n$. If $k<n$, then 
    \begin{equation*}
        \{ f \in C^\infty(K, V) \, | \, (j\circ f)(K) \cap \cR = \emptyset \}
    \end{equation*} 
    is comeager in $C^\infty(K, V)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2608.26565, 'A Horizon-Free Extrinsic Penrose Inequality'] The first variation is
\begin{equation}
 \frac{d}{ds}\bigg|_{s=0}\mathscr F_t(\Phi_s(G))
 =\int_\Sigma H_\Sigma\langle Y,\nu_E\rangle\,dA
 +\int_{\partial\Sigma}
 \langle Y,\eta_\Sigma-\tanh t\,\bar\eta_E\rangle\,ds.

\end{equation}
Consequently, if $G$ is $\mathscr F_t$-critical, then
\begin{equation}
 H_\Sigma=0,\qquad
 \langle\nu_E,\nu_S\rangle=-\tanh t.

\end{equation}

[Corollary 37 of arXiv:2609.02878, '2609.02878'] Assume the semiample limiting-class setting of
\cref{sec:fano-fibration-setup}, let \(q\in Y^{\rm prod}\), and let
\(\xi=(\mu_t)_{t<T}\) be a fixed limiting point based at \(q\).  The
time-\((-1)\) model of every tangent space at \(\xi\) splits globally,
biholomorphically, and isometrically as
\begin{equation}
                         Z\cong\C^m\times Z',
                         \qquad \dim_\C Z'=n-m.
\end{equation}
The factor \(Z'\) is complete, normal, and klt; its K\"ahler current has
bounded local potentials and a local ambient lower bound.  Write \(f_Z\)
for the normalized tangent shrinker potential.  At time \(-1\),
\begin{equation}
 f_Z(z,y)=\frac{|z|^2}{4}+\ell(z)+f'(y),
\end{equation}
where \(\ell\) is real affine-linear and \(f'\) is locally Lipschitz.
Moreover,
\begin{equation}
                 \int_{\Reg Z'}e^{-f'}\,dV_{g'}<\infty,
\end{equation}
and, writing \((\mathcal X_s,g_\infty(s))\) for the tangent flow, there
is a residual ancient flow \(g'(s)\) such that in the canonical gauge
\begin{equation}
 (\mathcal X_s,g_\infty(s))
 \cong(\C^m,g_{\rm E})\times(Z',g'(s)),\qquad s<0.
\end{equation}

[Definition def:cdc of arXiv:2602.19192, 'Bakry--\'Emery Curvature of the Fractional Laplacian\\ via Fractional Brownian Covariance'] The sesquilinear carr\'e du champ of $L_\gamma$ is
\begin{equation}
  \widetilde{\Gamma}_\gamma(f,g)(x)
  := \frac{1}{2} \int_{\mathbb{R} \setminus \{0\}}
  \bigl[f(x+z) - f(x)\bigr]\,
  \overline{\bigl[g(x+z) - g(x)\bigr]}\;
  \nu_\gamma(dz).
\end{equation}
On Fourier modes:
\begin{equation}
  \widetilde{\Gamma}_\gamma(e^{i\xi\cdot}, e^{i\eta\cdot})(x)
  = e^{i(\xi-\eta)x}\,\Psi_\gamma(\xi,\eta),
\end{equation}
where $\Psi_\gamma(\xi,\eta)
= \tfrac{1}{2}(|\xi|^\gamma + |\eta|^\gamma - |\xi-\eta|^\gamma)$.
Exponentials $e^{i\xi\,\cdot}$ lie in the extended Dirichlet space
of~$L_\gamma$ on $\mathbb{T}$ for all $\gamma \in (0,2)$; see
[BoettcherSchillingWang2013], \S4.7, for the general framework
of carr\'e du champ for L\'evy-type operators.

[Proposition 47 of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] Consider the same setup as in Proposition \ref{prop:path_coupling}, we have 
\begin{align*}
    \pr\left(|\tl B^{(\cdr_n)}(t) - \tl B^{(\cdr_n)}_n(t)| \le \frac{\log^{3-1/8}n}{\sqrt{n(1-t)}},\quad 0\le t\le \sft_n\right)\ge 1-2e^{-\log^{10/9}n}.
    \end{align*}

