[Proposition 6 (Aldous--Pitman representation) of arXiv:2607.16833, 'Dynamical Equations for Poisson Galton--Watson Trees and Component Densities of Sparse Inh'] Let $U$ be uniform on $(0,1)$ and independent of
$(\widehat G_s^*,0\leq s\leq1)$.  Then
\begin{equation}
 (\widehat G_\lambda,0\leq\lambda<A)
 \stackrel d=
 \left(\widehat G_{\lambda U}^{*},
       0\leq\lambda<\frac{-\log U}{1-U}\right).
\end{equation}
Consequently, for every fixed $0<u\leq1$,
\begin{equation}
 \widehat G_u\stackrel d=\widehat G_{uU}^{*}.
\end{equation}

[Definition 5 (Parallel tempering chain) of arXiv:2604.04823, '2604.04823'] Let~$\mathcal X$ be a Polish space and let $(R_k, \mu_k)_{k=0}^N$ be a collection of reversible Markov chains~$R_k$ on~$\mathcal X$, each with stationary density~$\mu_k$. Define transition kernels~$R$ and~$S$ on the product space~$\mathcal X_\pt = \mathcal X^{N+1}$ by
\begin{align}
    R(x,dy) &= \frac{1}{2(N+1)}\sum_{k=0}^N R_k(x_k, dy_k)\,\delta_{x_{[-k]}}\paren*{dy_{[-k]}}\,,\\
    S(x,dy) &= \frac{1}{2N}\sum_{k=0}^{N-1} \delta_{(k,k+1)x}(dy)\,\tau(x,(k,k+1)x) \\
    &\quad + \delta_x(dy)\paren*{1 - \frac{1}{2N}\sum_{k=0}^{N-1}\tau(x,(k,k+1)x)}\,.
\end{align}
Here,
\begin{gather}
    x = (x_0, x_1, \ldots, x_N), \quad 
    x_{[-k]} = (x_0, \ldots, x_{k-1}, x_{k+1}, \ldots, x_N),\\
    (k,k+1)x = (x_0, \ldots, x_{k-1}, x_{k+1}, x_k, x_{k+2}, \ldots, x_N),
\end{gather}
and~$\tau\colon \mathcal X_\pt \times \mathcal X_\pt \to [0,1]$ is the Metropolis acceptance probability
\begin{equation}
    \tau(x,y) = \min\set*{1, \frac{\mu(y)}{\mu(x)}}, 
    \quad \text{where} \quad 
    \mu = \prod_{k=0}^N \mu_k\,.
\end{equation}
The parallel tempering kernel~$P_\pt$ is defined by
\begin{equation}
    P_\pt = SRS\,.
\end{equation}

[Lemma re4D of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Under the same assumption as in Lemma (keyI of the paper), let $\tilde{x}_N(s)=\tilde{\mu}_{n,N}-\tilde{\sigma}_{n,N}s$ with
\begin{equation}
    \tilde{\mu}_{n,N}=\left(\frac{1}{\sigma_{n-1,N}^{1/2}}+\frac{1}{\sigma_{n,N-1}^{1/2}}\right)\left(\frac{1}{\mu_{n-1,N}\sigma_{n-1,N}^{1/2}}+\frac{1}{\mu_{n,N-1}\sigma_{n,N-1}^{1/2}}\right)^{-1}
\end{equation}
and
\begin{equation}
    \tilde{\sigma}_{n,N}=\left(\frac{\sigma_{n-1,N}^{1/2}}{\mu_{n-1,N}}+\frac{\sigma_{n,N-1}^{1/2}}{\mu_{n,N-1}}\right)\left(\frac{1}{\mu_{n-1,N}\sigma_{n-1,N}^{1/2}}+\frac{1}{\mu_{n,N-1}\sigma_{n,N-1}^{1/2}}\right)^{-1}.
\end{equation} 
Then
\begin{equation*}
    N^{\frac{2}{3}}D(\tilde{x}_N(s))\le C(s_0,\gamma)e^{-\frac{s}{2}}
\end{equation*}
holds for any $s\in\left[s_0,\frac{e_0\tilde{\mu}_{n,N}}{\tilde{\sigma}_{n,N}}\right]$ when $N$ large enough.

[Theorem thm:eqM of arXiv:2412.04973, 'On the Laplace equation with non-local dynamical boundary conditions'] Let us write $M_\Phi(t, \theta) = \mathbf{E}_0[\exp(-\theta L_t)]$, $t>0$, $\theta>0$. Then, $\varphi(t) = M^0_\Phi(t, \theta)$ is the unique solution to
\begin{equation*}
\left\lbrace
\begin{array}{ll}
\displaystyle D^\Phi_t \, \varphi(t) = - \theta\, \varphi(t), & t>0,\\
\displaystyle \varphi(0)=1.
\end{array}
\right. 
\end{equation*}

