[Proposition 143 of arXiv:2601.16377, '2601.16377'] Assume $\sqrt{2\theta \kappa} < \pi$.  Let $f$ be an analytic test function and denote
\begin{equation}

\sigma(z) = \sqrt{z^2 - \beta^2}\qquad \textnormal{with}\quad \beta = \sqrt{\frac{2\theta}{\kappa}}.
\end{equation}
The random variable
\[
\sum_{i = 1}^{N} f\bigg(\frac{\ell_i}{N}\bigg) - N\int_{-\beta}^{\beta} f(x)\dd\mu(x)
\]
is approximated in the sense of moments as $N \rightarrow \infty$ by a Gaussian random variable, with mean
\begin{equation}

\textnormal{\textsf{Mean}}[f] = \frac{\theta -1}{2\theta}\left(\frac{f(-\beta) + f(\beta)}{2} - \frac{1}{\pi} \int_{-\beta}^{\beta} \frac{f(x) \dd x}{|\sigma(x)|}  - \frac{\kappa}{\pi^2}\cdot \textnormal{p.v.}\int_{-\beta}^{\beta} \int_{-\beta}^{\beta} \frac{f(x) \cdot y \cdot \textnormal{T}\big[\kappa|\sigma(y)|\big]}{(x - y)|\sigma(x)|} \dd x \dd y \right)\!,
\end{equation}
where $\textnormal{T}(u) = u\big(u\frac{\cos(u)}{\sin(u)} - 1\big)$ and p.v. is the Cauchy principal value, and with covariance
\begin{equation}
\begin{split}
\textnormal{\textsf{Cov}}[f,f] & = \oint_{\gamma} \oint_{\gamma} \frac{\dd z_1\dd z_2}{(2\ii\pi)^2} \cdot \frac{f(z_1)f(z_2)}{2\theta (z_1 - z_2)^2}\left(-1 + \frac{z_1z_2 - \beta^2}{\sigma(z_1)\sigma(z_2)}\right) \\
& = \frac{1}{4\pi^2} \int_{-\beta}^{\beta}\int_{-\beta}^{\beta} f'(x_1)f'(x_2) \log\left(\frac{\beta^2 - x_1x_2 - \sqrt{(\beta^2 - x_1^2)(\beta^2 - x_2^2)}}{\beta^2 - x_1x_2  + \sqrt{(\beta^2 - x_1^2)(\beta^2 - x_2^2)}}\right) \dd x_1 \dd x_2.
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm:precise_I_bounds of arXiv:2605.09377, 'A factorization formula for the partition function in the semi-discrete parabolic Anderson'] Let $\nu \in (\tfrac{1}{2}, 1)$, $\delta \in (0,1)$, $\nu_0 \in (0, \tfrac{\delta}{2})$, $\kappa \in (0, \delta)$, and $\hat \kappa \in (0, \nu)$. Then  
\begin{flalign}

	\frac{t^{l+r}}{(l+r)!} \lesssim& \ t^{-1/2} \left(\frac{e}{\kappa} \right)^{\delta t} \qquad \text{for} \ 0 \leq l \leq \nu_0 t, \ 1 \leq r \leq l+1;

\\

	\frac{t^l}{l!} \lesssim& \ t^{-1/2} \left(\frac{e}{\hat \kappa} \right)^{\nu t} \qquad \text{for} \ \nu_0 t < l \leq \nu t. 
\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:betaLR1 of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For all non-negative measurable and symmetric functions $f$, we have

\begin{equation}
\!\!\!\!\!\!\mathbb{E}^0_{{\mathcal L }^{(1)}_{1,2}} \left[f (\theta_{\tilde \beta^{(1)}_{1,2}(0)}({\mathcal H }))\right]
\!=\!\mathbb{E}^0_{{\mathcal R }^{(2)}_{2,1}} \left[f (\theta_{\beta^{(2)}_{2,1}(0)}({\mathcal H }))\right],

\end{equation}

\begin{equation}
\mathbb{E}^0_{{\mathcal L }^{(2)}_{1,2}} \left[f (\theta_{\tilde \beta^{(2)}_{1,2}(0)}({\mathcal H }))\right] \!=\!\mathbb{E}^0_{{\mathcal R }^{(1)}_{2,1}} \left[f (\theta_{\beta^{(1)}_{2,1}(0)}({\mathcal H }))\right].

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

