[Corollary 13 of arXiv:2604.15874, 'On Continuous Data Assimilation for a class of 2D and 3D stochastic non-Newtonian fluids o'] Under the Hypothesis of Lemma \ref{lem-Difference}, for any $\u_0$, $\Urm_0\in\Hbb$ and any $R$, $\uppi$, $\delta>0$, we get
	\begin{align*}
		\Ebb\left[ \mathbf{1}_{(\uptau_{R,\uppi,\delta,\kappa}=+\infty)}  \|\u(t)-\Urm(t)\|^2_{2} \right] \leq e^{R+\uppi - \frac{\delta\kappa}{(1+\delta)^2}t} \|\u_0-\Urm_0\|^2_2.
	\end{align*}

[Proposition randomwalk of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] Let $\left(X_n\right)_{n \geq 0}$ be a birth--death chain with transition probabilities $\left(p_i, q_i, r_i\right)$, and define $\theta_n = \frac{\prod_{i=0}^{n-1}p_i}{\prod_{i=1}^{n}q_i}$. Consider the sequence of polynomials $\{R_n\}_{n \geq 0}$ determined by the three-term recurrence
    \begin{equation}
        \left\{
        \begin{aligned}
            &xR_n\left(x\right)  = p_n R_{n+1}\left(x\right) + r_n R_{n}\left(x\right) + q_n R_{n-1}\left(x\right), \\
            &R_0\left(x\right) =1, R_{-1}\left(x\right) = 0.
        \end{aligned}
        \right.
    \end{equation}
    Then there is an unique positive density function $\psi\left(x\right)$ such that  $\text{supp}\left(\psi\right) \subset [-1,1]$ and the $n$-step transition probabilities of $X_n$ satisfy
    \begin{equation}
        \mathbb{P}^{n}_{ij} = \theta_j \int_{-1}^{1} x^n R_i\left(x\right) R_{j}\left(x\right)\psi\left(x\right) dx.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

