[Definition 2 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] $(a)$    $\mathcal{HP}_{T,t}$
    denotes the set of $\mathbb C^{m\times m}$-valued functions analytic in $\mathbb C_r$ and such that
    \begin{equation}

      \begin{pmatrix}F(z)&I_m&\end{pmatrix}\begin{pmatrix}-T&I_m\\I_m&tT\end{pmatrix}\begin{pmatrix}F(z)^*\\ I_m\end{pmatrix}\ge 0,\quad z\in\mathbb C_r,
      \end{equation}
i.e.
\begin{equation}

  F(z)+F(z)^*+tT-F(z)TF(z)^*\ge 0,\quad z\in\mathbb C_r.
\end{equation}
$(b)$ The function $F$ is called canonical if in addition
\begin{equation}

  F(z)+F(z)^*+tT-F(z)TF(z)^*= 0,\quad for\,\,\,a.e.\,\, z\in i\mathbb R.
\end{equation}
$\T$

[Proposition prop:stable of arXiv:2411.09716, 'Stable Tables'] For preferences $\pi\in \Pi_n$:
    \begin{enumerate}
        \item[(i)] If $\pi$ is regular, there is a unique stable matching.
        \item[(ii)] If $\pi$ is irregular and $n$ is even, a matching is stable if and only if no person is unmatched.
        \item[(iii)] If $\pi$ is irregular and $n$ is odd, there exists no stable matching.\footnote{Notice that since a cycle graph with an odd number of vertices is not bipartite, a stable matching is not guaranteed from Gale-Shapley.}
    \end{enumerate}

[Lemma lem:small-set-return of arXiv:2601.08184, 'Wasserstein-p Central Limit Theorem Rates: From Local Dependence to Markov Chains'] Under Assumption~(assumption:markovchain of the paper), there exist an accessible small set \(\bar C\subseteq \mathcal X\) and a constant \(\kappa>1\) such that
\begin{equation}
    M(a):=\sup_{x\in \bar C}\mathbb{E}_x\big[a^{\sigma_{\bar C}}\big]<\infty,
    \qquad \forall a\in(1,\kappa],
\end{equation}
where $\sigma_{\bar C}:=\inf\{n\ge 1:x_n\in \bar C\}.$ Moreover, there exist \(m\in\mathbb N\), \(\beta\in(0,1)\), and a probability measure \(\nu\) on \(\mathcal X\), supported on \(\bar C\), such that \(\nu(\bar C)=1\), \(\nu(\bar C^c)=0\) and 
\begin{equation}
   P^m(x,\cdot)\ge \beta \mathbf{1}_{\bar C}(x)\nu(\cdot),
   \qquad x\in\mathcal X.
\end{equation}
The existence of \(\bar C\) and the exponential return bound~(equation eq:return of the paper) is a standard consequence of geometric ergodicity; see, for example, Theorem~15.0.1 of [Meyn12_book] and Theorem~15.1.5 of [douc2018markov]. The minorization condition~(equation eq:M of the paper) is the standard small-set minorization; see Proposition~5.2.4 of [Meyn12_book]. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2604.00598, 'Allowing for Imprecision in the Game-theoretic Characterisation of the Poisson Process'] Suppose \(\gencapprocs\) is coherent.
Then for all \(\stopt\in\stopts\), \(f\in\stoptdom\), \(\pth\in\set{\stopt<+\infty}\) and \(\gencapital_\bullet\in\gencapprocs\) such that \(\liminf\gencapital_\bullet\geq_{\tostop{\stopt}{\pth}} f\),
\begin{equation*}
\gencapital_t\vert_{\tostop{\stopt}{\pth}}
\geq \inf f\vert_{\tostop{\stopt}{\pth}}
\quad\text{for all } t\in\coi{\stopt\gr{\pth}}{+\infty}.
\end{equation*}

[Lemma Lemma-Q1 n m of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $\delta_1=\delta_{\mathcal Q_1}$  be as defined in (equation delta-Qi of the paper) and let $m,n\ge1$.  The following estimates hold true:
		\begin{align}
			&\left|\IP{\mathcal{Q}_{1,n} f-\mathcal{Q}_{1,m} g,f-g}_{H^{\theta}} \right|\notag\\
			\lesssim \ & (n \land m)^{-2(s-\theta-\delta_1)}(\left\lVertf\right\rVert_{H^{s}}+\left\lVertg\right\rVert_{H^{s}})^2+\|f-g\|^2_{H^{\theta}},\quad f,g\in H_d^s,\ \, s>\theta+\delta_1, 

		\end{align}
		and
		\begin{align}
			&\Big|\BIP{\mathcal{Q}_{1,n}^2 f-\mathcal{Q}_{1,m}^2 g,f-g}_{H^{\theta}}+
			\BIP{\mathcal{Q}_{1,n} f-\mathcal{Q}_{1,m} g,\mathcal{Q}_{1,n} f-\mathcal{Q}_{1,m} g}_{H^{\theta}}\Big|\notag\\
			\lesssim\ &  (n \land m)^{-(s-\theta-\delta_1)}(\left\lVertf\right\rVert_{H^{s}}+\left\lVertg\right\rVert_{H^{s}})^2+\|f-g\|^2_{H^{\theta}},\quad f,g\in H_d^s,\ \,  s>\theta+2\delta_1.

		\end{align}

