body:
[Prop 9 of arXiv:2511.00679, 'Stochastic solutions to abstract telegraph-type equations involving fractional dynamics'] The Fourier transform of the solution of the problem \eqref{fepd} is given by 
\begin{align*}
\widehat{u}(t,\xi) &= \left(\frac{2}{t ||\xi||^{\beta/2}}\right)^{\lambda-\frac{1}{2}}\Gamma\left(\lambda+\frac{1}{2}\right)J_{\lambda-\frac{1}{2}}\left(t||\xi||^{{\beta}/2}\right)\widehat f(\xi)\\
&= \frac{1}{B(\lambda,\frac12)t}\int_{-t}^{t}\left(1-\frac{w^2}{t^2}\right)^{\lambda-1}\left(\frac{e^{i ||\xi||^{{\beta}/2}w}+e^{-i||\xi||^{{\beta}/2}w}}{2}\right)\widehat f(\xi)\de w. 
\end{align*} 
Furthermore, we have the following stochastic solution
\begin{align*}
    u(t,x)&=  \mathbb E[\widebar{u}(t\sqrt{\mathfrak X},x)] 
 \end{align*}
where $\widebar{u}(t,x)=(\mathcal F^{-1}\cos(t||\xi||^{\beta/2})\widehat{f}(\xi))(x)$ is the solution to the abstract wave equation \eqref{naw}.

[Lemma 6 of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $1<q_0,q_1<\infty$, $1< p_0,p_1< \infty$ and $-4\leq s_0,s_1 \leq 4$.
\begin{enumerate}[label=(\roman*)]
    \item  If $q_0\leq q_1$ and $s_0-\frac{d}{q_0}\geq s_1-\frac{d}{q_1}$ hold true, then 
\begin{align*}
    \bpsn{s_0,q_0} \hookrightarrow \bpsn{s_1,q_1}.
\end{align*}
\item  Let $s_0,s_1 \neq \pm 4$. If $q_0\leq q_1$ , $s_0-\frac{d}{q_0}\geq s_1-\frac{d}{q_1}$, and $p_0\leq p_1$ hold true, then 
\begin{align*}
    {_\nu B^{ s_0 }_{q_0,p_0}(\sO)}\hookrightarrow {_\nu B^{ s_1 }_{q_1,p_1}(\sO)}.
\end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary corollary5 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A8 of the paper) hold and that $\mu_{\alpha}$ is spread-out such that there exists a Stone's decomposition of its associated renewal measure $e^{-\alpha x} \nu^{(\infty)}({\rm d}x)$ that satisfies (S1 of the paper). Let $\varphi$ be any non-negative $h$-dependent descendant characteristic that vanishes on the negative half-line (i.e., $\varphi(t)= 0$, for $t<0$) and satisfies (C2 of the paper)-(C3 of the paper) and (C5 of the paper). Suppose further that 
\begin{align} 
\mathbb{E}[\varphi(t)] \leq C e^{(\alpha-\delta) t} \mathbf{1}_{[0,\infty)}(t), \quad \text{for every} \, \, t \in \mathbb{R},
\end{align}
\noindent for some $\delta \in (\varepsilon, \alpha)$ and finite constant $C > 0$, where $\varepsilon \in (\alpha/2, \alpha)$ is as in (S1 of the paper). Then, there exists $\sigma \geq 0$ so that, for $a_{\alpha} \coloneqq \beta^{-1} \int_{0}^{\infty} \mathbb{E}[\varphi(x)] e^{- \alpha x} {\rm d} x$,
\begin{align}
e^{-\frac{\alpha}{2}t} \left(\mathcal{Z}_{t}^{\varphi} - a_{\alpha} e^{\alpha t} W \right) \xrightarrow[]{\rm st} \sigma \left( \frac{W}{\beta} \right)^{1/2} \mathcal{N}, \quad \text{as} \quad t \rightarrow \infty, \, t \in \mathbb{G},
\end{align}
\noindent where $\mathcal{N}$ is a standard normal random variable independent of $W$. The constant $\sigma$ can be explicitly computed; see (equation eq121 of the paper) (and in particular, $\mathbb{E}[H_{\Lambda}(t)] = a_{\alpha} e^{\alpha t}$, for $t \in \mathbb{R}$). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:local_quasi of arXiv:2511.12692, 'A stochastic flow approach to De Giorgi--Nash--Moser estimates for SPDE\lowercase{s} with '] Let Assumptions (ass:quasilinear of the paper) and (ass:quasilinear_data of the paper) be satisfied.  Then 
there exists a maximal $(p,\kappa,q)$-solution $(U,\sigma)$ to (equation eq:SPDE_quasi of the paper) satisfying a.s.\ $\sigma>0$ and
\begin{align}
U&\in L^{p}_{{\rm loc}}([0,\sigma);W^{1,q} (\mathbb{T}^d)) \cap C([0,\sigma);B^{1-2\frac{1+\kappa}{p}}_{q,p}(\mathbb{T}^d)), \\

U&\in C_{{\rm loc}}^{\vartheta,2\vartheta}((0,\sigma)\times \mathbb{T}^d) \ \text{ for all }\vartheta <\tfrac{1}{2},
\end{align}
as well as
\begin{equation}

{\mathbb P}\Big(t<\sigma<T,\, \sup_{s\in [t,\sigma)}\|U(s)\|_{C^{\varepsilon}(\mathbb{T}^d)}<\infty\Big)=0,
\end{equation}
for all $0<t<T<\infty$ and $\varepsilon \in (0,1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

