\end{align}
where $
Z_{G,J} = \prod_{e \in E} e^{J_e}  \sum_{\sigma \in \{-1,1\}^V}\prod_{e \in U(\sigma)} e^{- 2 J_e}.
$
Let $\sigma_1 \otimes \sigma_2$ denote the pointwise product of $\sigma_1$ and $\sigma_2$. Using that $U(\sigma \otimes \sigma_2) = U(\sigma) \triangle U(\sigma_2)$, 
    \begin{align*}
\mu^{\XOR}[\sigma] &= \sum_{\sigma_1, \sigma_2} \mu[\sigma_1] \mu[\sigma_2] 1\! \!1[\sigma_1 \otimes \sigma_2 = \sigma]
=  \sum_{\sigma_1, \sigma_2} \mu[\sigma_1 \otimes \sigma_2] \mu[\sigma_2] 1\! \!1[\sigma_1= \sigma] 
= \sum_{\sigma_2} \mu[\sigma ...","release_manifest_digest":"sha256:b917e8f15eafa018c0d082065eefb1241dfde03fb904f1792be571032f3c223d","revision_digest":"sha256:eb043ac27c75b3a56025840008730bbd441b69783f4fe9e526f253471057df77","source_id":"arxiv:2506.10765","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

