[Definition 36 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let $\kappa,q,p$ be properly tight,
$\hat b\leq 1,\rho>0$ be some constants,
\index{$S$@Miscelenea!properly tight}
 $b $ be a function
on $\bR^{d+1}$, and $\rho\in(0,\infty)$.  
\index{$S$@Miscelenea!$\bar b_{R}$@$\hat b_{(q,p),\rho}$}
Introduce
\begin{equation}

 \hat b_{(q,p),\rho}=\sup_{r\leq \rho}r\sup_{C\in \bC_{r}}
\dashnorm b\|_{L_{(q ,p) }(C)} .
\end{equation}

[Lem lA10 of arXiv:2504.07255, 'A Tail-Respecting Splitting Numerical Scheme\\ for L\'evy-Driven SDEs With Superlinear Dri'] We have
\begin{align}

\|X_t^n-X^{\langle n\rangle}_t\|&\leq_C U^n_t,\\

\|\Phi_x(\delta_t^n, Y_t^n)-\Phi_x(\delta_t^n, X^{(n)}_t)\| &\leq_C U^n_t,
\end{align}
and for any $\gamma\in [0,1]$ we have
\begin{align}

\|X^{\langle n\rangle}_t-X^{(n)}_t\|&\leq_C h_n^{\gamma}(1+\|X^{(n)}_t\|^{\gamma\chi+1}),\\

\|X^n_t-X^{(n)}_t\|&\leq_C h_n^{\gamma}(1+\|X^{(n)}_t\|^{\gamma\chi+1})  + U^n_t.
\end{align}

[Proposition 1 of arXiv:2506.10522, 'On the Law of the Iterated Logarithm for $m$-dependent stationary random variables under s'] Let $\{X_n;n=1,2,\cdots\}$ be a sequence of independent random variables in a sub-linear space $\sles$ satisfying $|X_n|\leq\alpha_n\frac{s_n}{t_n}$ for some $\alpha_n\to0$ and $s_n^2\to\infty$. Denote $\underline{s}_n^2=\sum_{i=1}^n\mbe[X_i^2]$ and $V_n^2=\sum_{i=1}^nX_i^2$, and assume that there exists a real number $r$ such that
\begin{equation}
    \frac{\underline{s}_n^2}{s_n^2}\to r.
\end{equation}
Then 
\begin{equation}
    \mvstar\left(r\leq\liminf_{n\to\infty}{\frac{V_n^2}{s_n^2}}\leq\limsup_{n\to\infty}{\frac{V_n^2}{s_n^2}}\leq1\right)=1.
\end{equation}

[Lemma 6 of arXiv:2606.22656, 'Fluctuations of Point Vortex Ensembles\\ at Small Negative Inverse Temperature'] For every finite simple graph $\Gamma$ with $n$ vertices and every $\beta_*<8\pi$,
there exists $C_{\Gamma,\beta_*}<\infty$ such that, for all sufficiently
large $N$ and $\beta\leq \beta_*$,
\begin{equation*}
    |A_N(\Gamma)| \leq C_{\Gamma,\beta_*}
    \left(\frac{\beta}{N}\right)^{e(\Gamma)}.
\end{equation*}

