      &\geq \left(\frac{(p-1)^2}{p^2} -2\lambda\frac{p-1}{p^2}+ C^2\right)-\frac{(p-1)^2}{p^2} u^2 + 2\lambda\frac{p-1}{p^2} u - C^{2}C^{\frac{2-2p}{3p-2}}  \\
      &\geq C^2 - \frac{(p-1)^2}{p^2}\left(2\max\left(0,\frac{2\lambda}{p-1}-1\right)C^{\frac{p}{3p-2}} + C^{\frac{2p}{3p-2}} \right) + 2\lambda\frac{p-1}{p^2} C^{\frac{p}{3p-2}} - C^{\frac{4p-2}{3p-2}}  \\
  \end{split}
  \end{equation*}
