[Lemma lemma_prepare_loop_decompose of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$, there exists $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}>0$ such that the following holds. Let $\mathbf{B}_1:=[\widetilde{B}(10\ensuremath{C_{\ref*{const_prepare_loop_decompose}}}M)]^c$, $\mathscr{B}_1:= \partial B(\ensuremath{C_{\ref*{const_prepare_loop_decompose}}}M)$, $\mathbf{B}_2:=\widetilde{B}(\frac{N}{10\ensuremath{C_{\ref*{const_prepare_loop_decompose}}}})$ and $\mathscr{B}_2:= \partial B(\frac{M}{\ensuremath{C_{\ref*{const_prepare_loop_decompose}}}})$. Then for any $M> N\ge 1$, $j\in \{1,2\}$, $k\in \mathbb{N}^+$, $A_1,...,A_k,D\subset \mathbf{B}_j$ and $\omega_l\in \Omega_l[N,M]$, 
	\begin{equation}
	\begin{split}
			&\mathbb{P}\Big( A_1\xleftrightarrow{\overline{\mathfrak{L}}^{D}[N,M]} ... \xleftrightarrow{\overline{\mathfrak{L}}^{D}[N,M]}   A_k \xleftrightarrow{\overline{\mathfrak{L}}^{D}[N,M]} \mathfrak{L}^{D}[N,M] \cup \mathscr{B}_j \mid \widehat{\mathsf{G}}^{D}[\omega_l; N,M] \Big)\\
		\le &	 (l+1)\mathbb{P}\big( A_1\xleftrightarrow{(D)} ... \xleftrightarrow{(D)} A_k \xleftrightarrow{(D)} \mathscr{B}_j \big).
	\end{split}
	\end{equation}

[Lemma 20 (Large-penalty expansion) of arXiv:2608.26693, '2608.26693'] Under Assumption~\ref{ass:spectral-bounds}, for equal penalties $\tau$, the covariance action satisfies, uniformly over $p$ and all admissible covariance pairs as $\tau\to\infty$,
\begin{equation}
\Acal_{\rm cov,\tau}(\Sigma_{0,p},\Sigma_{1,p})
=d_B^2(\Sigma_{0,p},\Sigma_{1,p})+O(p/\tau).
\end{equation}
If the Gaussian means are not necessarily zero but additionally $\|m_{0,p}-m_{1,p}\|^2=O(p)$ uniformly in $p$, then the full action satisfies
\begin{equation}
\Acal_{*,p}(\tau)
=W_2^2(\N(m_{0,p},\Sigma_{0,p}),\N(m_{1,p},\Sigma_{1,p}))+O(p/\tau).
\end{equation}
The constants in the remainders depend only on $\underline\lambda,\overline\lambda$ and, in the second statement, on the implicit constant in $\|m_{0,p}-m_{1,p}\|^2=O(p)$.

[Thm mainGeneral of arXiv:2509.26254, '$K$-Branching Random Walk with Noisy Selection: \\ \Large Large Population Limits and Phas'] Assume that $(M_N^0)_{N \in \mathbb{N}}$ has limiting log-profile $g^0\in{\mathcal D}$ and let  $(g^t)_{t\geq0}$ be the dynamics as defined in Theorem (thm:main of the paper). 
Suppose further that 
\begin{enumerate}
\item[(i)] $g^t\in{\cal D}$,
\item[(ii)] for all $t \geq 0$,
\begin{align}
\forall a,b \in \mathbb{R}\setminus D_{g^{t+1}}, \ \ \sup_{x \in (a,b]} \bar{s}(r^t)(x) &\neq 0, 
\end{align}
\item[(iii)]  $\sigma^t$ is the unique $\sigma$ for which $\sup s_\sigma(r^t) = \gamma$. 
\end{enumerate}
Then for all $t \in \mathbb{N}$, the sequences of point measures $(M_N^t)_{N \in \mathbb{N}}$ have limiting log-profile $g^t$.

