body:
[Theorem th:modulus-space of arXiv:2411.12192, 'Sample path properties and small ball probabilities for stochastic fractional diffusion eq'] Assume the conditions of Lemma (le:sLND-hat-U of the paper)  hold and recall that $\theta_2$ is given in (equation e:theta12 of the paper). For any
    fixed $t>0$, we have the following spatial regularity results:
  \begin{enumerate}
    \item (Uniform modulus of continuity). For any $M>0$, there exists a constant $k_4\in(0,\infty)$ such that
    \begin{equation*}
      \lim_{\varepsilon\to0^+}\sup_{\substack{x,y\in [-M,M]^d;\\ |x-y|\le\varepsilon}}\dfrac{|u(t,x)-u(t,y)|}{|x-y|^{\theta_2}\sqrt{\log\left(1+|x-y|^{-1}\right)}}=k_4,
      \text{ a.s. }
    \end{equation*}
    \item (Local modulus of continuity). There exists a constant $k_5\in(0,\infty)$ such that for any $x\in\mathbb{R}^d$,
    \begin{equation*}
      \lim_{\varepsilon\to0^+}\sup_{|y|\le \varepsilon} \dfrac{|u(t,x+y)-u(t,x)|}{|y|^{\theta_2} \sqrt{\log\log\left(1+|y|^{-1}\right)}}=k_5,
      \text{ a.s. }
    \end{equation*}
    \item (Chung's LIL). There exists a constant $k_6\in(0,\infty)$ such that for any $x\in\mathbb{R}^d$,
    \begin{equation*}
    \liminf_{\varepsilon\to0^+}\sup_{|y|\le \varepsilon} \dfrac{|u(t,x+y)-u(t,x)|}{\varepsilon^{\theta_2}\left(\log\log \varepsilon^{-1}\right)^{-\theta_2/d}}=k_6, \text{ a.s. }
  \end{equation*}
  \end{enumerate}

