[Proposition 6 of arXiv:2606.03122, 'Propagation of support for super-Brownian motion with general branching mechanism'] Suppose that $\Psi$ satisfies Condition \ref{con_localize}. Then for any $0<R_1<R$, we have
\begin{align}
u_\theta^\Psi(x,t)\leq u_{R,\Phi_R}(R_1)P_x(\sigma_{R_1}<t),\quad \forall x\in B(0,R_1),\ t>0,
\end{align}
where $P_x$ denotes the law of a $d$-dimensional Brownian motion $W$ starting from $x$ and $\sigma_{R_1}:=\inf\{s>0:|W_s|=R_1\}$.

[Corollary 7 (\cite{Gross1975document}, Theorem 3 and \cite{Diaconis1996}, Example 3.2) of arXiv:2605.29608, '2605.29608'] Let $(Y_{k})_{k\in\mathbb{Z}^{+}}$ and $\mu_{N}$ be defined as in Theorem \ref{thm: transitionmatrix}. At infinite temperature (i.e., $\hat{J}=0$), the Wolff dynamics reduces to the simple random walk on the hypercube $\Omega=\{-1,+1\}^{N}$, where at each step a single spin is chosen uniformly at random and flipped. Applying Theorem~\ref{thm:logsobolev} to the Markov chain with transition probability~\eqref{eq:transition0}, the log-Sobolev inequality
	\begin{align} 
		E_{\mu_{N}}[f^{2}\log f^{2}]-E_{\mu_{N}}[f^{2}]\log E_{\mu_{N}}[f^{2}]\leq&N	\mathcal{E}^{\text{W},0}_{\mu_{N}}(f),
	\end{align}
	holds for all functions $f:\Omega\to\mathbb{R}$, where
	\begin{align*}	
		\mathcal{E}^{\text{W},0}_{\mu_{N}}(f):=\frac{1}{2N}\sum_{i=1}^{N}E_{\mu_{N}}\big[(f(\sigma)-f(\sigma^{i}))^{2}\big]=\frac{1}{2N}\sum_{i=1}^{N}(f(\sigma)-f(\sigma^{i}))^{2}\frac{1}{2^{N}}.
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2607.16954, 'Repeated differentiation of deterministic polynomials with asymptotically radial root dist'] The coefficients of $\pp$ and $\qq$ as defined in Notation \ref{not:setting.derivatives} are related as follows.
\begin{equation}

\coef{k}{\qq}=\falling{mn-mk}{ml}\, \coef{k}{\pp},\qquad \text{for } 0\leq k\leq n.    
\end{equation}
Furthermore, the ratio of consecutive coefficients satisfies
\begin{equation}

\frac{\coef{k}{\qq}}{\coef{k-1}{\qq}}=\frac{\coef{k}{\pp}}{\coef{k-1}{\pp}} \prod_{i=1}^{m} \frac{ n-k-l+\frac{i}{m}}{n-k+\frac{i}{m}},\qquad \text{for } 1\leq k\leq n-c_\qq,
\end{equation}
where $c_\qq$ is the multiplicity of the root 0 of $\qq$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 1 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] Define an infinite sub-triangular array $\tau$ by
\begin{align}
\tau_{n,j} \triangleq \T_{n + 3, j + 3} \notag
\end{align}
for every $n \geq 0$ and $1 \leq j \leq n +1$. Then, $\tau_{n,*}$ is a strictly-positive log-concave sequence for every $n\geq 2$.

