[Defn 7 of arXiv:2608.13976, 'Boundary Harnack principle for diffusion with jumps on metric measure spaces'] \begin{enumerate}
\item [\rm (i)]
 We say condition  ${\rm \bf (Jt)}_{\leq, \bar r, \gamma}$ holds
 with some $\bar r>0$ and $\gamma>0$ if  there is a constant $C=C(\bar r, \gamma)>0$ such that for $r\in (0, \bar r],$
\begin{equation}
J(x,  \sX \setminus B(x,r))\leq Cr^{-\gamma}   \quad\hbox{ for every }x\in\sX.
\end{equation}

\item [\rm (ii)]
 We say  condition  ${\rm \bf ({\wh{Jt}})}_{\leq,  \bar r,  \gamma}$ holds
   with $ \bar r>0$ and $\gamma >0$ if there is a constant $C= C(\bar r, \gamma)>0$ such that for every ball $B$ with radius
 $\bar r$ and  $\overline B\subsetneq \sX$ and   every  $r\in (0, \bar r/4],$
\begin{equation}
\wh J^B(x, (2^{-1}B)\setminus B(x,r))\leq Cr^{-\gamma}   \quad\hbox{ for every }x\in 2^{-1}B.
\end{equation}
\end{enumerate}

[Theorem formal of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] $F(x,t;q)$ admits a formal expansion
\begin{align*}
F(x,(s-\log\varepsilon)/\varepsilon;\exp(-\varepsilon))\sim e^{-xe^{-s}}\Big(1+\sum_{l=1}^\infty G_l(x,\log\varepsilon,s)\Big),
\end{align*}
where
\begin{align*}
G_l(x,\log\varepsilon,s)=\sum\limits_{m=1}^{2l}x^me^{-ms}g_{l,m}(\log\varepsilon,s)
\end{align*}
with $g_{l,m}(\cdot,\cdot)$ a bivariate polynomial of degree $m$ in each of the arguments.

[Definition wegner of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] Define a block random Hermitian matrix by
\begin{equation}
X = \sqrt{1-\lambda}\,H + \sqrt{\lambda}\,\Lambda,
\end{equation}
where $\lambda\in[0,1)$ may depend on $M$,
for any $i, j \in \mathbb{T}_D^d$, the $(i, j)$-th block of size $M\times M$ is given by
\begin{equation}
    (H)_{i,j} = \delta_{i,j} H_i,
\end{equation}
and
\begin{equation}
    (\Lambda)_{i,j} = \begin{cases}
        \frac{1}{\sqrt{2d}}A_{i,j}, & \text{if } |i-j|_1 = 1, \\
        0, & \text{otherwise}.
    \end{cases}
\end{equation}
Here $|i-j|_1$ denotes the $\ell^1$ distance on the discrete torus (nearest neighbors), and  all non-zero block matrices are independent up to  symmetry  such that diagonal blocks $\{H_i\}$ are   rescaled $M\times M$ GUE (or GOE) matrices and
 off-diagonal blocks $A_{i,j}$ are  rescaled $M\times M$  Ginibre matrices.

[Defn 22 (Constructible differential forms) of arXiv:2608.28200, '\textbf On the Formality of Configuration Spaces of $\aka$'] For $s\le k$, define  
\ali{
\qquad A^s_{con,(k)}(U) = 
\set {\sum_{u+v=s}\sum_{|I|=u,|J|=v} f_{IJ} dx^{I} d\bar z^{J} }{f_{IJ} \text{ are constructible $C^{k-s}$   functions on $U$} }
}
\iffalse
\ali{
&\qquad A^s_{con,(k)}(U) = \\
&\set {\sum_{u+v=s}\sum_{\substack{i_1<\cdots< i_u, \\ j_1<\cdots<j_v}} f_{i_1,\cdots, i_u,j_1,\cdots, j_v} dx^{i_1}\cdots dx^{i_u} d\bar z^{j_1}\cdots d\bar z^{j_v}}     {f_{i_1,\cdots, i_u,j_1,\cdots, j_v} \text{ are constructible $C^{k-s}$   functions on $U$} }
}
\fi
and the space of constructible $C^{k-\bullet}$ forms
$$
\Aconk(U):=\bigoplus_{s=0}^{p+q} A^s_{con,(k)}(U).
$$

[Proposition 7 of arXiv:2604.19220, 'Split merge dynamics for expanding intervals and point processes on the real line.'] If  $ 0 \le c \le + \infty,$ 
    $\tau_n/n$ and $\nu_{\tau_n}$ are asymptotically independent~:
    \begin{equation}

    \left (\frac{\tau_n}{n} , \nu_{\tau_n} \right ) \xrightarrow[n\to\infty]{d} \left ( X, \epsilon_q \right ) 
    \end{equation}
    where $ X \overset{d}{=} \beta_{c,1}, $ if $  0 < c < + \infty,$ $ X = 0, $ if $ c = 0,$ $ X= 1 $ if $ c = 1, $  and is independent of $ \epsilon_q $ a Bernoulli random variable with parameter $q.$

