[Definition def: E^k, E_S and A_S of arXiv:2603.10738, 'Pairwise Negative Correlation for Uniform Spanning\\ Subgraphs of the Complete Graph'] \begin{enumerate}
		\item[(a)]	For an integer $k\in[1,n]$, let $E^{(k)}$ denote the event that the smallest connected component of the random graph $\big(V(K_n),\eta(\omega)\big)$ contains exactly $k$ vertices. 

		\item[(b)] For a subset $S\subset V(K_n)$, let $E_S$  denote the event that  $S$ is the vertex set of some connected component of the random graph $\big(V(K_n),\eta(\omega)\big)$. 

		\item[(c)]
		 For a subset $S\subset V(K_n)$, let  $A_S$ denote the event that there are no isolated vertices in $V(K_n)\setminus S$ for the random graph $\big(V(K_n),\eta(\omega)\big)$.  
	\end{enumerate}

[Proposition 7 (Chart invariance of first-order criteria) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] Let $\psi:(\widetilde\Theta,\widetilde\theta_0)\to(\Theta,\theta_0)$ be a $C^1$ local reparameterization with invertible derivative at $\widetilde\theta_0$, and let $\widetilde q_{\cQ}^{(m)}:=q_{\cQ}^{(m)}\circ\psi$. Identify a tangent block $\widetilde T\subset T_{\widetilde\theta_0}\widetilde\Theta$ with $T:=D\psi(\widetilde\theta_0)\widetilde T\subset T_{\theta_0}\Theta$. Then for every visible depth $m$,
\begin{equation}
D\widetilde q_{\cQ}^{(m)}(\widetilde\theta_0)|_{\widetilde T} = Dq_{\cQ}^{(m)}(\theta_0)|_T\circ
D\psi(\widetilde\theta_0)|_{\widetilde T}.
\end{equation}
Consequently, the rank of the restricted derivative, kernel inclusions between visible depths on corresponding tangent blocks, first-order local sufficiency, and the minimal informative window $m_*(T,\theta_0)$ are invariant under $C^1$ reparameterization.

[Proposition prop-radial-weld-ns of arXiv:2605.03385, 'Quantum Loewner evolution in quantum natural time: phases and Markov properties'] Let $\kappa \in (4,8)$ and $\gamma = 4/\sqrt\kappa \in (\sqrt2,2)$. We have 
\begin{equation}
\left(\int_0^\infty \mathrm{Weld}(\mathrm{GQD}_{3}(a, \ell, a)) \, da \right)^\# = (\mathrm{LF}_{\mathbb D, f, \ell}^{(Q-\frac\gamma4, 0), (\frac4\gamma - \frac\gamma2, 1)})^\# \times \mathrm{raSLE}_\kappa.
\end{equation}

