[Theorem 9 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to \Rbb$ and $q\in [1,2)$,
\begin{equation}
    \left\|\left|\grad^k f\right|\right\|_{\Leb^2}^{2} \geq \Wop^{\geq k}(f) \left[1+ \frac{q}{2k(2-q)}\ln^+\left(\frac{\Wop^{\geq k}(f)}{\sum_{J:|J|=k} \left\|\Dop_J f\right\|_{\Leb^q}^2} \right)\right]^k,
\end{equation}
and further for $\left\|f\right\|_{\Leb^\infty}\leq 1$ and $q\leq p<2$,
\begin{equation}
    \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-Eldan-Gross-Boolean}}}(p,q)^k\Wop^{\geq k}(f) \left[1 + \frac{q}{2k(2-q)}\ln^+\left(\frac{1}{\sum_{J:|J|=k} \left\|\Dop_J f\right\|_{\Leb^q}^2} \right)\right]^\frac{kp}{2},
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-Eldan-Gross-Boolean}}}(p,q) = \left(\frac{2}{2-q}\,M(p)^{-\frac{2}{p}}+\frac{pq}{2\upe(2-p)(2-q)}\right)^{-\frac{p}{2}} \gtrsim \left(2-p\right)\left(2-q\right)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2603.28170, 'Stabilization time of finite configurations with a second class particle in discrete TASEP'] Let $p=\frac{1}{2}-\frac{\lambda}{2\sqrt{n}}$ for some $\lambda\in\R$ be fixed
and let $\omega\in\Omega_n$ be sampled according to the Bernoulli initial condition of parameter $p$ with a second class particle in uniform position.
Then we have that
\begin{equation}
E_n\stackrel\d\Longrightarrow X^{(\lambda)}
\end{equation}
as $n\to\infty$ where the distribution of $X^{(\lambda)}$ is given by
\begin{equation}
\P(X^{(\lambda)}=0)=1-\P(X^{(\lambda)}=1)=\E(\argmax_{s\in[0,1]}B_s^{(\lambda)})
\end{equation}
with a Brownian motion $B_s^{(\lambda)}$ with drift $\lambda$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 15 of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] The probability measure $\mu^\eps\in \mathcal P(\R^{2d})$ defined in~\eqref{eq:SpatPreLimSte} converges weakly to $\mu\in \mathcal P(\xi^{-1}(0)\times\R^d)$ given by 
\begin{align*}
    d\mu(q^2,p)\coloneqq \frac{1}{Z} \exp\biggl(-V(0,q^2) -\frac{|p|^2}{2}\biggr) dq^2 dp
\end{align*}
where $Z$ is the normalisation constant. 
In particular, for $f\in C_b(\R^d)$ with $f=f(q)$ we have
\begin{align*}
    \lim_{\eps\to 0} \int_{\R^{2d}}f(q)d\mu^\eps(q,p) = \int_{\R^{d-k}} f(0,q^2) \frac{1}{\hat Z} e^{-V(0,q^2)}dq^2,
\end{align*}
with $\hat Z\coloneqq \int_{\R^{d-k}}e^{-V(0,q^2)}dq^2$. 

Furthermore, the limit~\eqref{eq:limit-gen} of $(Q^2,P^2)$ with $\hat q=0$  admits the $(q^2,p^2)$-marginal of $\mu$, i.e.\ $\displaystyle\int_{\R^k}\mu\,dp^1$, as a steady state (cf.Proposition~\ref{prop:Behav-Q2P2}).

