[Proposition 10 (Milstein scheme) of arXiv:2512.04646, '\textbf{Canonical Rough Path over Tempered Fractional Brownian Motion: Existence, Construc'] Under the assumptions of Theorem~\ref{thm:rde}, let
$\{t_k = kT/n\}_{k=0}^n$ be a uniform partition of $[0,T]$ and
define
\begin{equation}

Y_{t_{k+1}} = Y_{t_k} + f(Y_{t_k})\,\Delta B^k_{H,\lambda}
  + Df(Y_{t_k})f(Y_{t_k})\,\Delta\mathbb{B}^k_{H,\lambda},
\end{equation}
where $\Delta B^k_{H,\lambda}=B_{H,\lambda}(t_{k+1})-B_{H,\lambda}(t_k)$
and $\Delta\mathbb{B}^k_{H,\lambda}=\mathbb{B}_{H,\lambda}(t_k,t_{k+1})$.
Then
\begin{equation}

\mathbb{E}\bigl[|Y_T - Y^{(n)}_T|^2\bigr]^{1/2}
\le C(H,\lambda,T,f)\cdot n^{-H}.
\end{equation}

