[Lemma lem:exact-recursion of arXiv:2608.26765, 'Beyond Client Averaging: A Client-Independent Second-Order Stationary-Bias Component in St'] For one communication round,
\begin{align}
  \theta_{c,h+1}
  &=\theta_{c,h}-\gamma\{f'(\theta_{c,h})+\xi_c+\varepsilon_{c,h+1}\},
  \qquad \theta_{c,0}=x,                                           \\
  x^+&=\frac1N\sum_{c=1}^N\theta_{c,H},                            \\
  \xi_c^+&=\xi_c+\frac1{\gamma H}(\theta_{c,H}-x^+).              
\end{align}
Moreover,
\begin{equation}

  \sum_{c=1}^N\xi_c^+=\sum_{c=1}^N\xi_c.
\end{equation}
Hence (ass:zerosum of the paper) is invariant under the dynamics.

[Lemma 11 of arXiv:2512.00720, 'Asymptotic behavior of the critical density of activated random walk'] \thlabel{lem:expected-chances}
For any active configuration $\config$ and finite $\FiniteVertices \subset \Vertices$ containing the origin, 
\begin{equation*}
	\E[\Ch(\config, \FiniteVertices)] \le \Green[(\Graph, P)].
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:short-exp-weighted of arXiv:2603.14906, 'Four Levels of Thermodynamic Convergence of Singularly Perturbed Markov Semigroups'] Let $\kappa\ge0$. For each $\varepsilon>0$ let $h^\varepsilon\in C^{1}((0,\infty))$ and assume that
\begin{enumerate}
\item[\textup{(i)}] $h^\varepsilon(t)\to h(t)$ for every $t>0$;
\item[\textup{(ii)}] $G^\varepsilon(t):=-e^{-2\kappa t}\,h^{\varepsilon\,\prime}(t)$ is nonincreasing on $(0,\infty)$.
\end{enumerate}
If $h$ is differentiable at some $t_0>0$, then $G^\varepsilon(t_0)\to -e^{-2\kappa t_0}h'(t_0)$, and hence
$h^{\varepsilon\,\prime}(t_0)\to h'(t_0)$.

[Proposition 18 (Distance to the weighted holomorphic space) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] For $f\in C_c^\infty(\Omega_N;\C)$,
\begin{equation}
 \|f-Q_{N,\beta}f\|_2^2
 \le\frac2\beta\sum_{j=1}^N\|\bar\partial_jf\|_2^2.
\end{equation}
For real $f$,
\begin{equation}
 \|f-Q_{N,\beta}f\|_2^2\le\frac1{2\beta}\cE_{N,\beta}(f).
\end{equation}

[Thm 49 of arXiv:2507.08909, 'Annealed almost periodic entropy'] For separable unital representations $\pi$ and $\rho$, the following are equivalent:
\begin{itemize}
\item[i.] $\pi \lesssim_{\rm{a}}\rho$;
\item[ii.] we have $\rm{rank}\,\pi(a) \le \rm{rank}\,\rho(a)$ for every $a\in \A$;
\item[iii.] there is a representation $\pi_1$ such that $\pi \oplus \pi_1 \simeq_{\rm{a}} \rho$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem_Gt_asymp of arXiv:2605.27949, 'Yaglom limits of continuous-state branching processes in Brownian random environment \than'] In the weakly subcritical regime $({\bf m}\in(-\sigma^2,0))$, let the time-dependent function $G_t(y, v)$ be defined as:
\begin{eqnarray}
G_t(y, v) := 2^{\frac{\eta}{2}-1} y^{\frac{\eta}{2}-1} v^{\frac{\eta}{2}-1} \mathrm{e}^{- \frac{{\bf m}^2}{2\sigma^2}t} \mathrm{e}^{-\frac{1}{2y} - v} \theta\left( \sqrt{\frac{2v}{y}}, \frac{\sigma^2\beta^2}{4}t \right),
\end{eqnarray}
where $\theta(r, t)$ is defined in Proposition (jtpdf of the paper). Then, for any $y>0$ and $v>0$,
\begin{eqnarray*}
\lim _{t \rightarrow \infty} t^{3/2} \mathrm{e}^{\frac{{\bf m}^2}{2 \sigma^2} t} G_t(y, v) = \frac{4\sqrt 2}{\sigma^3\beta^3\sqrt{ \pi }} G(y, v),
\end{eqnarray*}
where $G(y,v)$ is the time-independent kernel defined in (equation G_def of the paper). Furthermore, there exists a constant $C' > 0$ such that for all $t \ge 1$, the scaled function satisfies the uniform bound:
\begin{eqnarray*}
\left| t^{3/2} \mathrm{e}^{\frac{{\bf m}^2}{2 \sigma^2} t} G_t(y, v) \right| \le C' G(y,v).
\end{eqnarray*}

