[Proposition prop_3 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $A$ be positive-semidefinite. The inequality in ((en_LM of the paper)) implies HWI at best with
\begin{equation}

\kappa=\frac{9-\sqrt{17}}{32}\approx 0.1524,
\end{equation}
which is achieved for
\begin{eqnarray}
a=\frac{7-\sqrt{17}}{4}.
\end{eqnarray}
 Moreover, LMI in ((LM of the paper)) implies HWI at best with $\kappa=1-\frac{\sqrt{3}}{2}\approx 0.134$.

[Lemma 2 of arXiv:2606.30938, 'Poissonian potential measures for refracted-reflected L\'evy processes'] Let $0 \leq b \leq a$, $q \geq 0$ and $0 < \lambda < \infty$. Then the following identities hold:
			\begin{enumerate}
				\item[\upshape{(i)}] For $ x \in [b,a]$ and $ y \in [b,\infty)$,
				\begin{equation}
					\E_x\Bigl( \int^\infty_0 e^{-q t} \1_{\{Y_t \in \dd y, \; t < T_{a,Y}^{+,\lambda} \wedge \tau_{b,Y}^- \}} \dd t \Bigr) = \Bigl( \frac{\W^{(q)}(x-b)}{\Z^{(q)}(a-b, \varphi_{q+\lambda})} \Z^{(q)}(a-y, \varphi_{q+\lambda}) - \W^{(q)}(x-y)\Bigr) \dd y, 
				\end{equation}
				and, consequently, for $ y \in (a,\infty)$,	
				\begin{equation}
					\E_x\bigl( \ee^{-q T_{a,Y}^{+,\lambda}} \1_{\{Y_{T_{a,Y}^{+,\lambda}} \in \dd y, \; T_{a,Y}^{+,\lambda} < \tau_{b,Y}^-\}} \bigr) = \lambda \frac{\W^{(q)}(x-b)}{\Z^{(q)}(a-b,\varphi_{q+\lambda})} \ee^{\varphi_{q+\lambda}(a-y)} \dd y.  
				\end{equation}

				\item [\upshape{(ii)}] For $ x,y \in [b,\infty)$,	
				\begin{equation}
					\E_x \Bigl( \int^\infty_0 \ee^{-q t} \1_{\{Y_t \in \dd y, \; t < T_{a,Y}^{-,\lambda} \wedge \tau_{b,Y}^- \}} \dd t \Bigr) = \Bigl(\frac{\Z^{(q+\lambda)}(a-y, \varphi_{q})}{\Z^{(q+\lambda)}(a-b, \varphi_{q})} \W^{(q+\lambda)}(x-b) - \W^{(q+\lambda)}(x-y) \Bigr) \dd y, 
				\end{equation}
				and consequently, for $y \in (b,a)$,
				\begin{equation}
					\E_x \Bigl( \ee^{-q T_{a,Y}^{-,\lambda}} \1_{\{Y_{T_{a,Y}^{-,\lambda}} \in \dd y,\; T_{a,Y}^{-,\lambda} < \tau_{b,Y}^- \}} \Bigr) = \lambda \Bigl(\frac{\Z^{(q+\lambda)}(a-y, \varphi_{q})}{\Z^{(q+\lambda)}(a-b, \varphi_{q})} \W^{(q+\lambda)}(x-b) - \W^{(q+\lambda)}(x-y) \Bigr) \dd y. 
				\end{equation}
			\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem-tauberian of arXiv:2510.26123, 'Directed distances in bipolar-oriented triangulations:\\ exact exponents and scaling limit'] Let $\phi$ be as in~(equation eqn-gen-func-def of the paper). Assume that for some $c \in \mathbbm C\setminus i \mathbbm R$ and $\nu \in (0,1)$,  
\begin{equation} 
\phi(e^{i t}) = 1 + (c \mathbbm 1_{(t > 0)} + \overline c \mathbbm 1_{(t < 0)} ) |t|^\nu  + o(t^\nu)  ,\quad \text{as $t \to 0$}. 
\end{equation} 
Then $\operatorname{Re}(c)<0$ and setting $a=-\frac{\operatorname{Re}(c)}{\Gamma(1-\nu)}\sec\Big(\tfrac{\pi\nu}{2}\Big)>0$,
\begin{equation} 
\mathbbm P[X > R] = a R^{-\nu}  +  o(R^{-\nu}) ,\quad \text{as $R\to\infty$}. 
\end{equation}

