[Definition 24 of arXiv:2512.07202, 'Hitting Probabilities for Hypoelliptic Differential Equations Driven by Fractional Brownia'] Let $\alpha \in (0,1)$. A multiplicative functional $\mathbf{z} : \{(s,t)\in [0,T]^2 : s\leqslant t\} \to T^{([1/\alpha])}$ is called a \textit{weakly geometric $\alpha$-Hölder rough path}
if it takes values in $G^{([1/\alpha])}$ and satisfies 
\begin{equation*}
\|\mathbf{z}\|_{\alpha;\mathrm{HS}} := 
\sum_{i=1}^{[1/\alpha]} 
\sup_{0 \leqslant s < t \leqslant 1} 
\frac{\|z^i_{s,t}\|_{\mathrm{HS}}}{|t-s|^{i\alpha}} < \infty.
\end{equation*}

[Lemma tool: H reg decay of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] Let $\alpha \in \mathbb R$ and $\beta\geq0$, then
  \begin{equation} 
  \| \overline H\varphi(\tau,\cdot)\|_{B^{\alpha +\beta}_{p,q,z}}
  \leq
  C(\beta) \tau^{-\beta}\|\varphi\|_{B^\alpha_{p,q,z}}.	
\end{equation}
And similarly 
\begin{equation}
  \|H(\varphi_-,\varphi_+)(\tau,\cdot)\|_{B^{\alpha +\beta}_{p,q,z}}\leq C(\beta,L) d(\tau,\cdot)^{-\beta} \left(\|\varphi_-\|_{B^{\alpha}_{p,q,z}}+\|\varphi_+\|_{B^{\alpha}_{p,q,z}}\right).
\end{equation}

