[Theorem thm:R6 of arXiv:2509.17319, 'Non-directed polymers in random environments with range penalties: the high-dimensional ca'] Let $\alpha \in (0,d)$ and $(\zeta,\gamma)\in R_6$. Then
\begin{equation}
\lim_{N\to +\infty} N^{\zeta}\log {\ensuremath{\mathbf Z}} _N=
\lim_{N\to +\infty} N^{\zeta}\log {\ensuremath{\mathbf Z}} _N(|{\ensuremath{\mathcal R}} _N|=2)=-2\hat h\quad\text{in}~{\ensuremath{\mathbbm P}} \text{-probability}
\end{equation}
and ${\ensuremath{\mathbf P}} _N(|{\ensuremath{\mathcal R}} _N|=2)\overset{N\to\infty}{\longrightarrow}1$ in ${\ensuremath{\mathbbm P}} $-probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 (Growth of the eigenfunctions, $\varepsilon=1$ and $\gamma>0$) of arXiv:2603.29473, '$\chi^2$--cut-off phenomenon for Galerkin projections of Fokker--Planck equations with mon'] \hfill

	\noindent
	Let $V$ be the potential defined in \cref{def:V} for some $\gamma>0$ and let $\varrho_{1,\infty}$ be the density function given in \cref{ec:invm} for $\varepsilon=1$. Let $u$ be a solution to the eigenvalue problem
	\begin{equation*}
		-u'' + V' u' = \lambda u \quad \text{ on }\quad  \R
	\end{equation*}
	for some eigenvalue $\lambda > 0$ and $u \in L^2_{\varrho_{1,\infty}}(\R)$. Let $x^*$ be the turning point defined in \cref{lem:WKBprime}. Then if $n > \frac{1+\gamma}{2\gamma}$ and $u(x^*) \geq 0$ we then have  on $[x^*,\infty)$
	\begin{equation*}
		u(x) \approx e^{\sum_{i=1}^n S_i(x)},
	\end{equation*}
	where $S_i(x)$ are the solutions to the closed hierarchy given in \cref{lem:WKBprime}.
	Moreover, there exist constants $C_2,C_3,\ldots,C_n \in \R$ such that
	\begin{equation*}
		u(x)\approx
		\begin{cases}
			e^{\lambda \frac{|x|^{1-\gamma}}{1-\gamma} + \sum_{i=2}^{n} C_i |x|^{1-(2i-1)\gamma}},                     & \textrm{ if } \gamma^{-1} \notin 2\mathbb{N}-1,
			\\
			e^{\lambda \frac{|x|^{1-\gamma}}{1-\gamma} + \sum_{i=2}^{m-1} C_i |x|^{1-(2i-1)\gamma} + C_{m} \log(|x|)}, & \textrm{if } \gamma = \frac{1}{2m-1} \textrm{ for some } m\in\mathbb{N},\ 2 \leq m < n.
		\end{cases}
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 33 of arXiv:2605.14630, '2605.14630'] For any $n\geqs1$ and $h\in\H$ with $\norm{h}_\H=1$, one has 
\begin{equation}

 I_n(h^{\otimes n}) 
 = \frac{1}{\sqrt{n!}}H_n\bigpar{W(h)}\;,
\end{equation} 
independently of the basis $\set{e_i}_{1\leqs i\leqs N}$ of $\H$.

