[Corollary 27 of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] Let $n=2$ and $F:\mathbb{R}^2 \to \mathbb{R}$ A twice differential equation on $\mathbb{R}^2$ given by $F(x,y)=e^{\beta x} \left| y\right|^2$. Let $Y^1=A:=\left(A_t\right)_{t \leq T}$ be a continuous adapted process with finite variation on $[0,T]$, and  $Y^2:=\left(Y_t\right)_{t \leq T}$ a one-dimensional adapted process with regulated paths of the form \eqref{form of the process for Ito}. Then, By applying Theorem \ref{Ito's formula Theorem}, we get for all $t \leq T$,
	\begin{equation*}
		\begin{split}
			e^{\beta A_t} \left| Y_t \right|^2&=  \left| Y_0 \right|^2+\beta \int_{0}^{t} e^{\beta A_s} \left| Y_s \right|^2 dA_s+2\int_{0}^{t} e^{\beta A_s} Y_{s-} dY^{\ast}_s+\int_{0}^{t} e^{\beta A_s} d \left[Y^{\ast}\right]^c_s\\
			&\quad +\sum_{0 < s \leq t} e^{\beta A_s} \left| \Delta_{-} Y_{s} \right|^2+\sum_{0 \leq s < t} e^{\beta A_s} \left(\left| \Delta_{+} Y_{s}\right|^2+2Y_{s}\Delta_{+} Y_s \right).
		\end{split}
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 6 (Generalized predictable Euler-Maruyama ``SDEs'' are not representative of $\mathcal{H}_T^2(\mathbb{R}^{d_X})$) of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] The following is true of the class $\mathfrak{B}\subseteq \mathcal{H}_T^2(\mathbb R^{d_X})$
\begin{enumerate}
    \item[(i)] \textbf{\emph{Probabilistic {\color{black}rarity}:}}
        Let $\mu_G$ be a centred Gaussian measure on $\mathcal{H}_T^2(\mathbb R^{d_X})$ whose covariance operator $Q$ is diagonal in some orthonormal basis $(\eta_n)_{n=1}^{\infty}$, with strictly positive eigenvalues $(\lambda_n)_{n=1}^{\infty}$. Then, $\mu_G(\mathfrak{B}) = 0$,
    \item[(ii)] \textbf{\emph{Topological {\color{black}rarity}:}}
        $\mathfrak{B}$ is meagre in $\mathcal{H}_T^2(\mathbb R^{d_X})$.
\end{enumerate}

[Lemma 13 of arXiv:2609.01540, '2609.01540'] There is a bounded open set \(\mathcal O_\varrho\) with smooth boundary such that
\[
 \Gamma\subset \mathcal O_\varrho
 \subset\{x:\operatorname{dist}(x,\Gamma)<\varrho\}
\]
and
\begin{equation}
 \mathcal H^{n-1}(\partial \mathcal O_\varrho)
 \leq C_n\int_\Sigma J_{n-1}F\,d\mathcal H^{n-1}.

\end{equation}

[Proposition limit-NS of arXiv:2605.28194, 'Delayed Blow-up in 3D Fluids via Pseudo-Transport Noise'] Fix $R_0>0,\;s>\frac{1}{2}$. There exists $\nu_0=\nu_0(R_0)$ such that for every $\nu>\nu_0$ and initial data $u_0$ satisfying 
		\begin{equation*}
			u_0\in H^s,\quad\text{and} \quad \|u_0\|_{H^s}\leq R_0,
		\end{equation*}
		the equation (equation Euler-damping of the paper) admits a unique solution $u\in L^2([0,\infty); H^{s+1})\cap C([0,\infty);H^s)$. Moreover, if $u_0\in B_{2,p}^{n+1-\frac{2}{p}}$ for some $n>-\frac{1}{2},\, 1\leq p< \infty$ with $n+1-\frac{2}{p} >s$, then  the solution $u$ also belongs to $L_{loc}^p([0,\infty); H^{n+1})\cap C([0,\infty);B_{2,p}^{n+1-\frac{2}{p}})$.

