[Definition 4 of arXiv:2608.30077, 'Lie groupoid integration of singular isometries of the Poincaré disk'] A (conformal) metric $g$ on a surface $\Sigma$ admits a \emph{singularity of order $\beta-1, \beta \in \R $}, at $p \in \Sigma$ if it can be locally written as
\begin{equation*}
g = e^{2u} |z|^{2(\beta-1)} |dz|^2,
\end{equation*}
with 
\begin{equation*}
    u \in L^1, \text{ and }\text{ }  \Delta u \in L^1,
\end{equation*}
where $z$ is a local (conformal) coordinate such that
$z(p)=0$.

[Lemma 3.6 of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] \textnormal{(i) (Upper bound)} There exist positive constants $c_2(u_1)$ and $n_2(u_1)$ such that for all $n>n_2(u_1)$, $1\le m\le n$, $1\le i, i'\le n$, $1\le j'\le m$, and nonempty set $J\subseteq\{1,\ldots,m\}$, 
    \begin{equation}
        \mathbb{P}_{z}\Big(\tau_{\widetildeT_{i',j'}} = \tau_ {T_{i,J}},\tau_{\widetildeT_{i',j'}}<\tau_{\partial \widetilde{B}(z)}\Big)<c_2\Big(\log(m/|J|)+1\Big)|J|/n, \quad \text{for all } z\in\partialV_{i,J},
    \end{equation}
    and 
    \begin{equation}
        \mathbb{P}_{z}\Big(\tau_{\widetildeT_{i, j}}=\tau_{T_{i,J}} ,\tau_{\widetildeT_{i, j}}<\tau_{\partial \widetilde{B}(z)}\Big)<c_2\Big(\log(m/|J|)+1\Big)|J|/n,
        \quad \text{for all } z\inT_{i,j}.
    \end{equation}
    \textnormal{(ii) (Lower bound)} There exist positive constants $c_3(u_1)\le \min\{1,1/(2c_2)\}$, $c_4(u_1)$ and $n_3(u_1)$ such that for all $n>n_3$, $m=[c_3n]$, $1\le i, i'\le n$, $1\le j'\le m$, and $z\in\partial S_i$,
    \begin{equation}
    \mathbb{P}_{z}\Big(\tau_{\widetildeT_{i', j'}}=\tau_{T_i} ,\tau_{\widetildeT_{i', j'}}<\tau_{\partial \widetilde{B}(z)}\Big)>c_4.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2606.06193, 'Peng's Maximum Principle for McKean-Vlasov Stochastic Differential Equations with Common N'] If Assumption \ref{Assumption:C^{2,1}} holds, then for any $1 \leq k$,
    \begin{equation*}
        \mathbb{E}\left[\sup _{t \in[0, T]}\left\|X^{\epsilon}_t-X_t-Y^{\epsilon}_t-Z^{\epsilon}_t\right\|^{2 k}\right] \in o(\epsilon^{2k}).
    \end{equation*}

