body:
[Lemma 64 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] For each $p \in [2,\infty)$ there is a constant $C_p > 0$ such that for all $s,t \in [0,T]$ with $s < t$ the following statements are true:
\begin{enumerate}
\item For each $\bbr^{m \times d}$-valued predictable process $\Phi$ such that
\begin{align*}
\int_s^t | \Phi_r |^2 dr < \infty \quad \text{$\bbp$-almost surely}
\end{align*}
we have
\begin{align*}
\bbe \Bigg[ \sup_{u \in [s,t]} \bigg| \int_s^u \Phi_r dB_r \bigg|^p \Bigg] \leq C_p \cdot \bbe \Bigg[ \bigg( \int_s^t | \Phi_r |^2 dr \bigg)^{p/2} \Bigg].
\end{align*}
\item For each $\bbr^m$-valued predictable process $\Psi$ such that
\begin{align*}
\int_s^t | \Psi_r |^2 dr < \infty \quad \text{$\bbp$-almost surely}
\end{align*}
we have
\begin{align*}
\bbe \Bigg[ \sup_{u \in [s,t]} \bigg| \int_s^u \Psi_r \otimes dB_r \bigg|^p \Bigg] \leq C_p \cdot \bbe \Bigg[ \bigg( \int_s^t | \Psi_r |^2 dr \bigg)^{p/2} \Bigg].
\end{align*}
\end{enumerate}

[Theorem 26 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] For every $t > 0$ and $q \in \mcl Q_1^\D$, there exist $p^+, p^- \in \mcl Q_{\infty,\leq 1}^\D$ such that 
\begin{equation}
p^+=\partial_q\psi(q+t\nabla\xi(p^+)), \qquad p^-=\partial_q\psi(q+t\nabla\xi(p^-)),
\end{equation}
and
\begin{equation}
\sP_{t,q}(p^-) \le \liminf_{N \to \infty} \bar F_N(t,q) \le \limsup_{N\to\infty} \bar F_N(t,q)\leq \sP_{t,q}(p^+).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:decompos-b-n of arXiv:2411.11429, 'Functional Central Limit Theorem for topological functionals of Gaussian critical points'] For $ x\in \mathsf E(u)$, let $ C_x  $ be the bounded connected component  of $ \mathsf E(u)$ containing $ x$, or the empty set if $ x$ is not in a bounded component. Then, with Definition   (def:topo-func of the paper)

\begin{align*}\beta _n(u;F) = \sum_{(x,v)\in Y^{\partial }(W_n\times [u,\infty ))}\delta (x,v,C_x),
\end{align*}
where $ \delta (x,v,C_x)$ satisfies  {for some $ \kappa <\infty $}
\begin{align*} | \delta (x,v,C_x) | \le  {\kappa } \#Y^{\partial }(C_x\times [u,\infty ))
\end{align*}
and $ \delta (x,v,C_x)$ only depends on the isotropy class of $ C_x$ (hence is not modified upon a $ \Delta $-perturbation without stratified quasi critical point by Lemma (lm:Morse of the paper)).

