    \end{equation}
    and
    \begin{equation}
    \norm{\tilde{\theta}_\alpha-2(\zeta_\alpha-1)}_{W^{s-1,\infty}}\lesssim\frac{\epsilon^2}{t^{\frac{2}{3}}}\ln (2+t).
    \end{equation}

