	\begin{align}
		 \widehat{C} (t-s)^{2} \frac{\big[ \Theta(n) K_n \big]^{2} }{n^{4} } \Bigg\{1 + \int_1^{L_n} u^{2 - 2 \gamma} \; \dd u \Bigg\}. 
